const C: Record<string, string[]> = {"Mishneh Torah, Admission into the Sanctuary 2":["אֵין כֹּהֵן גָּדוֹל נִכְנָס לְקֹדֶשׁ הַקָּדָשִׁים אֶלָּא מִיּוֹם הַכִּפּוּרִים לְיוֹם הַכִּפּוּרִים. וְכֹהֵן הֶדְיוֹט נִכְנָס לַקֹּדֶשׁ לַעֲבוֹדָה בְּכָל יוֹם:","וְהֻזְהֲרוּ כָּל הַכֹּהֲנִים שֶׁלֹּא יִכָּנְסוּ לַקֹּדֶשׁ אוֹ לְקֹדֶשׁ הַקָּדָשִׁים שֶׁלֹּא בִּשְׁעַת עֲבוֹדָה שֶׁנֶּאֱמַר (ויקרא טז ב) \"וְאַל יָבֹא בְכָל עֵת אֶל הַקֹּדֶשׁ\" זֶה קֹדֶשׁ הַקָּדָשִׁים (ויקרא טז ב) \"מִבֵּית לַפָּרֹכֶת\" לְהַזְהִיר עַל כָּל הַבַּיִת:","כֹּהֵן שֶׁנִּכְנַס לְקֹדֶשׁ הַקָּדָשִׁים בִּשְׁאָר יְמוֹת הַשָּׁנָה בֵּין כֹּהֵן הֶדְיוֹט בֵּין כֹּהֵן גָּדוֹל אוֹ כֹּהֵן גָּדוֹל שֶׁנִּכְנַס לוֹ בְּיוֹם הַכִּפּוּרִים שֶׁלֹּא בִּשְׁעַת הָעֲבוֹדָה חַיָּב מִיתָה בִּידֵי שָׁמַיִם שֶׁנֶּאֱמַר (ויקרא טז ב) \"וְלֹא יָמוּת\". וְכַמָּה פְּעָמִים הוּא נִכְנָס לְשָׁם בְּיוֹם הַכִּפּוּרִים אַרְבַּע כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ. וְאִם נִכְנָס חֲמִישִׁית חַיָּב מִיתָה בִּידֵי שָׁמַיִם:","וְהַנִּכְנָס לַקֹּדֶשׁ חוּץ לְקֹדֶשׁ הַקָּדָשִׁים שֶׁלֹּא לַעֲבוֹדָה אוֹ לְהִשְׁתַּחֲווֹת בֵּין הֶדְיוֹט בֵּין גָּדוֹל לוֹקֶה. וְאֵינוֹ חַיָּב מִיתָה שֶׁנֶּאֱמַר (ויקרא טז ב) \"אֶל פְּנֵי הַכַּפֹּרֶת\" (ויקרא טז ב) \"וְלֹא יָמוּת\". עַל קֹדֶשׁ הַקָּדָשִׁים בְּמִיתָה וְעַל שְׁאָר הַבַּיִת בְּלָאו וְלוֹקֶה:","כֹּהֵן שֶׁיָּצָא מִן הַמִּקְדָּשׁ בִּשְׁעַת הָעֲבוֹדָה בִּלְבַד חַיָּב מִיתָה בֵּין כֹּהֵן גָּדוֹל בֵּין כֹּהֵן הֶדְיוֹט שֶׁנֶּאֱמַר (ויקרא י ז) \"וּמִפֶּתַח אֹהֶל מוֹעֵד לֹא תֵצְאוּ פֶּן תָּמֻתוּ\". כְּלוֹמַר לֹא תָּנִיחוּ עֲבוֹדָה וְתֵצְאוּ מְבֹהָלִים וּדְחוּפִים מִפְּנֵי גְּזֵרָה זוֹ. וְכֵן זֶה שֶׁנֶּאֱמַר בְּכֹהֵן גָּדוֹל (ויקרא כא יב) \"וּמִן הַמִּקְדָּשׁ לֹא יֵצֵא\" אֵינוֹ אֶלָּא בִּשְׁעַת הָעֲבוֹדָה בִּלְבַד שֶׁלֹּא יָנִיחַ עֲבוֹדָתוֹ וְיֵצֵא:","אִם כֵּן מִפְּנֵי מָה נִשְׁנֵית אַזְהָרָה זוֹ בְּכֹהֵן גָּדוֹל. שֶׁכֹּהֵן הֶדְיוֹט שֶׁהָיָה בַּמִּקְדָּשׁ בַּעֲבוֹדָתוֹ וְשָׁמַע שֶׁמֵּת לוֹ מֵת שֶׁהוּא חַיָּב לְהִתְאַבֵּל עָלָיו אַף עַל פִּי שֶׁאֵינוֹ יוֹצֵא מִן הַמִּקְדָּשׁ אֵינוֹ עוֹבֵד מִפְּנֵי שֶׁהוּא אוֹנֵן וְאִם עָבַד וְהוּא אוֹנֵן שֶׁל תּוֹרָה חִלֵּל עֲבוֹדָתוֹ בֵּין בְּקָרְבַּן יָחִיד בֵּין בְּקָרְבַּן צִבּוּר. אֲבָל כֹּהֵן גָּדוֹל עוֹבֵד כְּשֶׁהוּא אוֹנֵן שֶׁנֶּאֱמַר (ויקרא כא יב) \"וּמִן הַמִּקְדָּשׁ לֹא יֵצֵא וְלֹא יְחַלֵּל\" כְּלוֹמַר יֵשֵׁב וְיַעֲבֹד עֲבוֹדָה שֶׁהָיָה עוֹסֵק בָּהּ וְאֵינָהּ מִתְחַלֶּלֶת:","וּמִנַּיִן שֶׁעֲבוֹדַת הָאוֹנֵן פְּסוּלָה. מִקַּל וָחֹמֶר. אִם בַּעַל מוּם שֶׁאוֹכֵל בְּקָדָשִׁים אִם עָבַד חִלֵּל. אוֹנֵן שֶׁהוּא אָסוּר בְּקָדָשִׁים שֶׁנֶּאֱמַר (דברים כו יד) \"לֹא אָכַלְתִּי בְאֹנִי מִמֶּנּוּ\" דִּין הוּא שֶׁיְּחַלֵּל:","וְאַף עַל פִּי שֶׁכֹּהֵן גָּדוֹל עוֹבֵד אוֹנֵן אָסוּר לֶאֱכל בְּקָדָשִׁים שֶׁנֶּאֱמַר (ויקרא י יט) \"וְאָכַלְתִּי חַטָּאת הַיּוֹם הַיִּיטַב בְּעֵינֵי ה'\". וְכֵן אֵינוֹ חוֹלֵק לֶאֱכל בָּעֶרֶב. אוֹנֵן שֶׁעָבַד אֵינוֹ לוֹקֶה. וּמֻתָּר לִגַּע בְּקָדָשִׁים אַף עַל פִּי שֶׁלֹּא טָבַל שֶׁלֹּא עָשׂוּ מַעֲלָה אֶלָּא בַּאֲכִילָה אֲבָל בִּנְגִיעָה הֲרֵי זֶה טָהוֹר כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ:","אֵי זֶהוּ אוֹנֵן זֶה שֶׁמֵּת לוֹ מֵת מִן הַקְּרוֹבִים שֶׁהוּא חַיָּב לְהִתְאַבֵּל עֲלֵיהֶן בְּיוֹם הַמִּיתָה בִּלְבַד הוּא הַנִּקְרָא אוֹנֵן דִּין תּוֹרָה. וְלַיְלָה הוּא אוֹנֵן מִדִּבְרֵי סוֹפְרִים:","וּמֵת שֶׁשָּׁהָה יָמִים וְאַחַר כָּךְ נִקְבַּר כָּל אוֹתָם הַיָּמִים שֶׁאַחַר יוֹם הַמִּיתָה הוּא אוֹנֵן מִדִּבְרֵיהֶם וְכֵן יוֹם הַקְּבוּרָה וְאֵינוֹ תּוֹפֵשׂ לֵילוֹ. לְפִיכָךְ מִי שֶׁמֵּת לוֹ מֵת (וּקְבָרוֹ) לְאַחַר יוֹם הַמִּיתָה כָּל יוֹם הַקְּבוּרָה אֵינוֹ מַקְרִיב וְאֵינוֹ אוֹכֵל בְּקָדָשִׁים מִדִּבְרֵיהֶם. וְטוֹבֵל וְאוֹכֵל לָעֶרֶב. וְיוֹם שְׁמוּעָה קְרוֹבָה וְיוֹם לִקּוּט עֲצָמוֹת הֲרֵי הוּא כְּיוֹם קְבוּרָה שֶׁאֵינוֹ תּוֹפֵשׂ לֵילוֹ וַאֲפִלּוּ מִדִּבְרֵיהֶם. לְפִיכָךְ טוֹבֵל וְאוֹכֵל בְּקָדָשִׁים לָעֶרֶב. אֲבָל יוֹם הַמִּיתָה כְּשֵׁם שֶׁאָסוּר לֶאֱכל בּוֹ קָדָשִׁים מִן הַתּוֹרָה כָּךְ אָסוּר לֶאֱכל בְּלֵילוֹ מִדִּבְרֵיהֶם. חוּץ מִן הַפֶּסַח בִּלְבַד שֶׁהוּא אוֹכֵל לָעֶרֶב כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ:","הָאָבֵל אֵינוֹ מְשַׁלֵּחַ קָרְבְּנוֹתָיו כָּל שִׁבְעָה. אֲפִלּוּ יַיִן אוֹ עֵצִים אוֹ לְבוֹנָה. וְכֵן מְצֹרָע אֵינוֹ מְשַׁלֵּחַ קָרְבְּנוֹתָיו כָּל זְמַן שֶׁאֵינוֹ רָאוּי לְבִיאָה אֶל הַמַּחֲנֶה אֵינוֹ רָאוּי לְהַקְרָבָה. אֲבָל הַמְנֻדֶּה יֵשׁ בּוֹ סָפֵק אִם מְשַׁלֵּחַ אִם אֵינוֹ מְשַׁלֵּחַ לְפִיכָךְ אִם הִקְרִיבוּ עָלָיו נִרְצָה:","טְמֵא שֶׁרֶץ וְכַיּוֹצֵא בּוֹ וְהֶעָרֵל מְשַׁלְּחִין אֶת קָרְבְּנוֹתֵיהֶם וּמַקְרִיבִין עֲלֵיהֶן חוּץ מִפֶּסַח שֶׁאֵין שׁוֹחֲטִין אוֹתוֹ עַל טְמֵא שֶׁרֶץ וְאֵין שׁוֹחֲטִין עַל הֶעָרֵל פֶּסַח כְּמוֹ שֶׁיִּתְבָּאֵר. אֲבָל טְמֵא מֵת אֵין מַקְרִיבִין עָלָיו קָרְבָּן כְּלָל עַד שֶׁיִּטָּהֵר:"],"Mishneh Torah, Agents and Partners 4":["כְּשֶׁיִּרְצוּ הַשֻּׁתָּפִין לְהִשְׁתַּתֵּף בְּמָה יִקְנֶה כָּל אֶחָד מֵהֶן מָמוֹן חֲבֵרוֹ לְהִשְׁתַּתֵּף בּוֹ. אִם בְּמָעוֹת נִשְׁתַּתְּפוּ יָבִיא זֶה מְעוֹתָיו וְיָבִיא זֶה מְעוֹתָיו וְיַטִּילוּ אוֹתָן לְכִיס אֶחָד וְיַגְבִּיהוּ אֶת הַכִּיס שְׁנֵיהֶם. אֲבָל אִם כָּתְבוּ שְׁטָר וְהֵעִידוּ עֵדִים אַף עַל פִּי שֶׁקָּנוּ מִיַּד שְׁנֵיהֶם שֶׁיָּבִיא זֶה מֵאָה וְזֶה מֵאָה וְיִשְׁתַּתְּפוּ בָּהֶן לֹא קָנוּ וַעֲדַיִן לֹא נַעֲשׂוּ שֻׁתָּפִין. שֶׁאֵין הַמַּטְבֵּעַ נִקְנֶה בַּחֲלִיפִין. לְפִיכָךְ אִם נִשְׁתַּתְּפוּ בִּשְׁאָר הַמִּטַּלְטְלִין כֵּיוָן שֶׁקָּנוּ מִיָּדָם שֶׁיָּבִיא זֶה חָבִיתוֹ שֶׁל יַיִן וְזֶה כַּדּוֹ שֶׁל דְּבַשׁ וַהֲרֵי נִשְׁתַּתְּפוּ בָּהֶן נַעֲשׂוּ שֻׁתָּפִין בָּהֶן. וְכֵן אִם עֵרְבוּ פֵּרוֹתֵיהֶן אוֹ שֶׁשָּׂכְרוּ מָקוֹם בְּשֻׁתָּפוּת וְהִנִּיחַ זֶה כַּדּוֹ וְזֶה חָבִיתוֹ שֶׁנִּשְׁתַּתְּפוּ בָּהֶן הֲרֵי אֵלּוּ שֻׁתָּפִין. כְּלָלוֹ שֶׁל דָּבָר בְּכָל הַדְּרָכִים שֶׁקּוֹנֶה הַלּוֹקֵחַ בְּאוֹתָן הַדְּרָכִים עַצְמָן קוֹנִין הַשֻּׁתָּפִין זֶה מִזֶּה הַמָּמוֹן הַמֻּטָּל בֵּינֵיהֶם לְהִשְׁתַּתֵּף בּוֹ:","הָאֻמָּנִין שֶׁנִּשְׁתַּתְּפוּ בְּאֻמָּנוּת אַף עַל פִּי שֶׁקָּנוּ מִיָּדָם אֵינָן שֻׁתָּפִין. כֵּיצַד שְׁנֵי חַיָּטִים אוֹ שְׁנֵי אוֹרְגִים שֶׁהִתְנוּ בֵּינֵיהֶם שֶׁכָּל שֶׁיִּקַּח זֶה וְזֶה בִּמְלַאכְתּוֹ יִהְיֶה בֵּינֵיהֶן בְּשָׁוֶה אֵין כָּאן שֻׁתָּפוּת כְּלָל שֶׁאֵין אָדָם מַקְנֶה לַחֲבֵרוֹ דָּבָר שֶׁלֹּא בָּא לָעוֹלָם. אֲבָל אִם הָיוּ לוֹקְחִין הַבְּגָדִים בְּמָמוֹן עַצְמָן וְתוֹפְרִין אוֹתָן וּמוֹכְרִין וְלוֹקְחִין הַשְּׁתִי וְהָעֵרֶב מִמְּעוֹתֵיהֶן וְאוֹרְגִים וּמוֹכְרִין וְנִשְׁתַּתְּפוּ בַּמָּעוֹת שֶׁלּוֹקְחִין בּוֹ הֲרֵי אֵלּוּ שֻׁתָּפִין וְכָל מַה שֶּׁיַּרְוִיחוּ בִּשְׂכַר מְלַאכְתָּן וּבְמַשָּׂאָן וּבְמַתָּנָן הֲרֵי אֵלּוּ לָאֶמְצַע:","הַשֻּׁתָּפִין שֶׁהִטִּילוּ לְכִיס זֶה מָנֶה וְזֶה מָאתַיִם וְזֶה שְׁלֹשׁ מֵאוֹת וְנִתְעַסְּקוּ כֻּלָּן בַּמָּמוֹן וּפָחֲתוּ אוֹ הוֹתִירוּ הַשָּׂכָר אוֹ הַפְּחָת בֵּינֵיהֶם בְּשָׁוֶה לְפִי מִנְיָנָם וְלֹא לְפִי הַמָּעוֹת. וַאֲפִלּוּ לָקְחוּ שׁוֹר לִטְבִיחָה שֶׁאִלּוּ טְבָחוּהוּ הָיָה נוֹטֵל כָּל אֶחָד מִבְּשָׂרוֹ כְּפִי מְעוֹתָיו אִם מְכָרוּהוּ חַי וּפָחֲתוּ אוֹ הוֹתִירוּ הַשָּׂכָר אוֹ הַפְּחָת לָאֶמְצַע. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁנָּשְׂאוּ וְנָתְנוּ בַּמָּעוֹת שֶׁנִּשְׁתַּתְּפוּ בָּהֶן אֲבָל אִם הַמָּעוֹת קַיָּמִין וַעֲדַיִן לֹא הוֹצִיאוּ אוֹתָן וּפָחֲתוּ אוֹ הוֹתִירוּ מֵחֲמַת הַמַּטְבֵּעַ שֶׁשִּׁנָּה הַמֶּלֶךְ אוֹ אַנְשֵׁי הַמְּדִינָה חוֹלְקִין הַשָּׂכָר אוֹ הַהֶפְסֵד לְפִי הַמָּעוֹת. בַּמֶּה דְּבָרִים אֲמוּרִים בִּסְתָם אֲבָל אִם הִתְנוּ שֶׁיִּטּל בַּעַל הַמֵּאָה שְׁלֹשָׁה רְבָעִים מִן הַשָּׂכָר וְיִטּל בַּעַל הַמָּאתַיִם רְבִיעַ וְאִם נִפְחֲתוּ לֹא יִפְחֹת זֶה שֶׁיִּטּל שְׁלֹשָׁה רְבִיעֵי הַשָּׂכָר אֶלָּא רְבִיעַ הַהֶפְסֵד וְיַפְסִיד זֶה שֶׁנּוֹטֵל רְבִיעַ הַשָּׂכָר שְׁלֹשָׁה רְבָעִים מִן הַפְּחָת הֲרֵי אֵלּוּ חוֹלְקִין כְּפִי מַה שֶּׁהִתְנוּ. שֶׁכָּל תְּנַאי שֶׁבְּמָמוֹן קַיָּם:","הַשֻּׁתָּפִין שֶׁהִתְנוּ בֵּינֵיהֶם שֶׁיַּעַמְדוּ בְּשֻׁתָּפוּת זְמַן קָצוּב כָּל אֶחָד וְאֶחָד מֵהֶן מְעַכֵּב עַל חֲבֵרוֹ וְאֵינוֹ יָכוֹל לַחְלֹק עַד שֶׁיַּגִּיעַ הַזְּמַן אוֹ עַד שֶׁיִּכְלֶה מָמוֹן הַשֻּׁתָּפוּת וְאֵין אֶחָד מֵהֶן יָכוֹל לִטּל חֶלְקוֹ מִן הַקֶּרֶן וְלֹא בַּשָּׂכָר עַד סוֹף הַזְּמַן. נִשְׁתַּתְּפוּ סְתָם וְלֹא קָבְעוּ לָהֶם זְמַן הֲרֵי אֵלּוּ חוֹלְקִין כָּל זְמַן שֶׁיִּרְצֶה אֶחָד מֵהֶן וְזֶה נוֹטֵל חֶלְקוֹ מִן הַסְּחוֹרָה וְזֶה נוֹטֵל חֶלְקוֹ. וְאִם לֹא הָיְתָה בְּאוֹתָהּ סְחוֹרָה דִּין חֲלוּקָה אוֹ שֶׁהָיְתָה בַּחֲלוּקָתָהּ הֶפְסֵד הֲרֵי אֵלּוּ מוֹכְרִין אוֹתָהּ וְחוֹלְקִין אֶת הַדָּמִים. הָיָה זְמַן יָדוּעַ לִמְכִירַת אוֹתָהּ סְחוֹרָה יֵשׁ לְכָל אֶחָד מֵהֶן לְעַכֵּב שֶׁלֹּא יַחֲלֹקוּ עַד שֶׁתִּמָּכֵר הַסְּחוֹרָה בַּזְּמַן הַיָּדוּעַ לִמְכִירָתָהּ. וְאֵין אֶחָד נוֹטֵל מִן הַקֶּרֶן וְלֹא מִן הָרֶוַח עַד זְמַן הַחֲלוּקָה אֶלָּא אִם הִתְנוּ בֵּינֵיהֶם. הָיָה לָהֶם חוֹב אֵצֶל אֲחֵרִים אֵינוֹ יָכוֹל לוֹמַר לַחֲבֵרוֹ לֹא נַחְלֹק עַד שֶׁנִּגְבֶּה כָּל חוֹב שֶׁיֵּשׁ לָנוּ אֶלָּא חוֹלְקִין וּכְשֶׁיִּפְרְעוּ הַחוֹבוֹת יִטּל כָּל אֶחָד חֶלְקוֹ. הָיָה עֲלֵיהֶן חוֹב לְאַחֵר אִם אֵינָן אַחְרָאִין זֶה לָזֶה חוֹלְקִין וְלִכְשֶׁיַּגִּיעַ זְמַן הַחוֹב לְפָרְעוֹ יִתֵּן כָּל אֶחָד חֶלְקוֹ. וְאִם הֵן אַחְרָאִים כָּל אֶחָד מֵהֶן מְעַכֵּב לַחְלֹק עַד שֶׁיַּגִּיעַ זְמַן הַשְּׁטָר וְיִפְרְעוּ הַחוֹב. וְלָמָּה מְעַכֵּב שֶׁהֲרֵי חֲבֵרוֹ אוֹמֵר לוֹ הוֹאִיל וְכָל אֶחָד מִמֶּנּוּ חַיָּב לְשַׁלֵּם כָּל הַשְּׁטָר נִשָּׂא וְנִתֵּן בְּדָמִים אֵלּוּ עַד שֶׁיַּגִּיעַ הַזְּמַן. אָמַר לוֹ חֲבֵרוֹ נַחְלֹק וְטל אַתָּה דָּמִים כְּנֶגֶד כָּל הַשְּׁטָר וַעֲשֵׂה מֵהֶן סְחוֹרָה לְעַצְמְךָ וּתְשַׁלֵּם כָּל הַשְּׁטָר בִּזְמַנּוֹ יֵשׁ לוֹ לְעַכֵּב עֲדַיִן וְלוֹמַר לוֹ שֶׁמָּא נַפְסִיד וְהַשְּׁנַיִם יוֹתֵר מַרְוִיחִין מִן הָאֶחָד:","הַנּוֹתֵן מָעוֹת לַחֲבֵרוֹ לֵילֵךְ לִמְדִינָה פְּלוֹנִית לִסְחוֹרָה אוֹ לִקְנוֹת לוֹ פֵּרוֹת לִסְחוֹרָה אוֹ לֵישֵׁב בּוֹ בַּחֲנוּת אֵינוֹ יָכוֹל לַחְזֹר בּוֹ וּלְהַחְזִיר הַמָּמוֹן מִיַּד הַשֻׁתָּף עַד שֶׁיֵּלֵךְ לַמָּקוֹם שֶׁהִתְנוּ וְיַחְזֹר אוֹ עַד שֶׁיִּקְנוּ אוֹתָן הַפֵּרוֹת וְיִמְכֹּר אוֹ עַד שֶׁיֵּשֵׁב בַּחֲנוּת שֶׁזֶּה כְּמִי שֶׁקָּבַע זְמַן הוּא:"],"Mishneh Torah, Appraisals and Devoted Property 7":["הַהֶקְדֵשׁוֹת אֵין פּוֹדִין אוֹתָן לֹא בְּקַרְקַע. וְלֹא בַּעֲבָדִים שֶׁהֲרֵי הֻקְּשׁוּ לְקַרְקָעוֹת. וְלֹא בִּשְׁטָרוֹת (מִפְּנֵי) שֶׁאֵין גּוּפָן מָמוֹן שֶׁנֶּאֱמַר וְנָתַן אֶת הַכֶּסֶף. אֶחָד הַכֶּסֶף וְאֶחָד שְׁאָר הַמִּטַּלְטְלִין שֶׁשָּׁוִין כֶּסֶף. וַאֲפִילוּ סֻבִּין:","כָּל הַפּוֹדֶה קָדָשָׁיו מוֹסִיף חֹמֶשׁ. וְאֶחָד הַמַּקְדִּישׁ עַצְמוֹ אוֹ אִשְׁתּוֹ אוֹ הַיּוֹרֵשׁ מוֹסִיפִים חֹמֶשׁ כְּמוֹ שֶׁבֵּאַרְנוּ. וְאַף הַחֹמֶשׁ לֹא יִהְיֶה אֶלָּא מִן הַמִּטַּלְטְלִין. וְהַחֹמֶשׁ שֶׁמּוֹסִיף הֲרֵי הוּא כְּהֶקְדֵּשׁ עַצְמוֹ וְדִין אֶחָד לָהֶם:","הַפּוֹדֶה קָדָשָׁיו אֵין הַחֹמֶשׁ מְעַכֵּב. אֶלָּא מֵאַחַר שֶׁנָּתַן אֶת הַקֶּרֶן יָצָא הַקֹּדֶשׁ לְחֻלִּין וּמֻתָּר לֵהָנוֹת בּוֹ. וּמִדִּבְרֵי סוֹפְרִים שֶׁאָסוּר לוֹ לֵהָנוֹת עַד שֶׁיִּתֵּן הַחֹמֶשׁ שֶׁמָּא יִפְשַׁע וְלֹא יִתֵּן. אֲבָל בְּשַׁבָּת מִפְּנֵי עֹנֶג שַׁבָּת הִתִּירוּ לוֹ לֶאֱכל וְאַף עַל פִּי שֶׁעֲדַיִן לֹא נָתַן אֶת הַחֹמֶשׁ וַהֲרֵי הַגִּזְבָּרִין תּוֹבְעִין אוֹתוֹ:","קָדְשֵׁי מִזְבֵּחַ שֶׁנָּפַל בָּהֶם מוּם וְנִפְדּוּ. אִם פָּדָה הַמַּקְדִּישׁ עַצְמוֹ מוֹסִיף חֹמֶשׁ כִּשְׁאָר הַהֶקְדֵּשׁוֹת. וְהַמַּקְדִּישׁ שֶׁפָּדָה לְעַצְמוֹ הוּא שֶׁמּוֹסִיף חֹמֶשׁ לֹא הַמִּתְכַּפֵּר בָּהּ שֶׁפְּדָאָהּ. וְהֶקְדֵּשׁ רִאשׁוֹן הוּא שֶׁחַיָּב בְּתוֹסֶפֶת חֹמֶשׁ. אֲבָל הֶקְדֵּשׁ שֵׁנִי אֵינוֹ מוֹסִיף עָלָיו חֹמֶשׁ. שֶׁנֶּאֱמַר (ויקרא כז טו) \"וְאִם הַמַּקְדִּישׁ יִגְאַל אֶת בֵּיתוֹ וְיָסַף חֲמִישִׁית\". הַמַּקְדִּישׁ וְלֹא הַמַּתְפִּיס:","לְפִיכָךְ אִם חִלֵּל בְּהֵמָה עַל בְּהֵמָה שְׁנִיָּה בֵּין בְּקָדְשֵׁי בֶּדֶק הַבַּיִת בֵּין בְּקָדְשֵׁי מִזְבֵּחַ שֶׁנָּפַל בָּהֶם מוּם. אוֹ שֶׁהֵמִיר בְּקָדְשֵׁי מִזְבֵּחַ. כְּשֶׁהוּא פּוֹדֶה אֶת הַשְּׁנִיָּה שֶׁחִלֵּל עָלֶיהָ אוֹ אֶת הַתְּמוּרָה לְעַצְמוֹ אֵינוֹ מוֹסִיף חֹמֶשׁ:","הַמַּפְרִישׁ אָשָׁם לְהִתְכַּפֵּר בּוֹ וְנָפַל בּוֹ מוּם וְהוֹסִיף עָלָיו חֹמֶשׁ וְחִלְּלוֹ עַל בְּהֵמָה אַחֶרֶת וְנִתְכַּפֵּר בְּאָשָׁם אַחֵר וְנִתְּקָה הַבְּהֵמָה שֶׁחִלֵּל עָלֶיהָ לִרְעִיָּה כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ. הֲרֵי הוּא סָפֵק אִם מוֹסִיף עָלֶיהָ חֹמֶשׁ הוֹאִיל וְהוּא קָרְבַּן עוֹלָה וַהֲרֵי הוּא גּוּף אֶחָד וּקְדֻשָּׁה אַחֶרֶת. אוֹ אֵינוֹ מוֹסִיף עָלֶיהָ חֹמֶשׁ מִפְּנֵי שֶׁהִיא בָּאָה מִכֹּחַ הֶקְדֵּשׁ רִאשׁוֹן שֶׁכְּבָר הוֹסִיף עָלָיו חֹמֶשׁ:","קָדְשֵׁי בֶּדֶק הַבַּיִת אֵין עוֹשִׂין תְּמוּרָה שֶׁלֹּא דָּנָה תּוֹרָה בִּתְמוּרָה אֶלָּא בְּקָדְשֵׁי מִזְבֵּחַ. כֵּיצַד. הָיוּ לְפָנָיו בֶּהֱמַת חֻלִּין וּבֶהֱמַת קָדְשֵׁי בֶּדֶק הַבַּיִת וְאָמַר זוֹ חֲלוּפַת זוֹ אוֹ זוֹ תְּמוּרַת זוֹ לֹא אָמַר כְּלוּם. אֲבָל אִם אָמַר הֲרֵי זוֹ תַּחַת זוֹ הֲרֵי זוֹ מְחֻלֶּלֶת עַל זוֹ דְּבָרָיו קַיָּמִין וְיָצְאתָה הַבְּהֵמָה הָרִאשׁוֹנָה לְחֻלִּין וְנִתְפְּסָה הַשְּׁנִיָּה:","אֶחָד קָדְשֵׁי בֶּדֶק הַבַּיִת וְאֶחָד קָדְשֵׁי מִזְבֵּחַ שֶׁנָּפַל בָּהֶן מוּם אֵין פּוֹדִין אוֹתָן לְכַתְּחִלָּה אֶלָּא בְּשָׁוְיֵיהֶן. וְאִם עָבַר וְחִלְּלָן עַל פָּחוֹת מִשָּׁוְיֵיהֶן אֲפִלּוּ הֶקְדֵּשׁ שָׁוֶה מֵאָה דִּינָר שֶׁחִלְּלוֹ עַל שְׁוֵה פְּרוּטָה הֲרֵי זֶה פָּדוּי וְיָצָא לְחֻלִּין וּמֻתָּר לֵהָנוֹת בּוֹ. וּמִדִּבְרֵי סוֹפְרִים שֶׁהוּא צָרִיךְ חֲקִירַת דָּמִים וְחַיָּב לְהַשְׁלִים אֶת דָּמָיו:","כֵּיצַד. הָיְתָה לוֹ בֶּהֱמַת קָדְשֵׁי מִזְבֵּחַ שֶׁנָּפַל בָּהּ מוּם וַהֲרֵי הִיא שָׁוָה עֲשָׂרָה וּבֶהֱמַת חֻלִּין שֶׁשָּׁוָה חֲמִשָּׁה וְאָמַר הֲרֵי זוֹ מְחֻלֶּלֶת עַל זוֹ הֲרֵי זוֹ נִפְדֵית וְיָצָאת לְחֻלִּין אֲבָל צָרִיךְ לְהַשְׁלִים הַחֲמִשָּׁה. וְכֵן אִם הָיְתָה הַבְּהֵמָה הָרִאשׁוֹנָה קָדְשֵׁי בֶּדֶק הַבַּיִת הֲרֵי זוֹ יָצָאת לְחֻלִּין לְהִגָּזֵז וּלְהֵעָבֵד וְתִכָּנֵס הַשְּׁנִיָּה תַּחְתֶּיהָ דִּין תּוֹרָה. אֲבָל מִדִּבְרֵיהֶם צָרִיךְ חֲקִירַת דָּמִים אִם הָיְתָה זוֹ שֶׁחִלֵּל עָלֶיהָ שָׁוָה אוֹ יַשְׁלִים דָּמֶיהָ:","שָׁמוּ אוֹתָהּ שְׁלֹשָׁה וְאָמְרוּ שֶׁזּוֹ בְּדָמֶיהָ אֲפִלּוּ בָּאוּ אַחַר כֵּן מֵאָה וְאָמְרוּ שֶׁל קֹדֶשׁ הָיְתָה יָפָה אֵינוֹ חוֹזֵר. הוֹאִיל וַחֲקִירַת הַדָּמִים מִדִּבְרֵיהֶם לֹא הֶחְמִירוּ בָּהּ. אֲבָל אִם שָׁמוּ אוֹתָהּ שְׁנַיִם וּבָאוּ שְׁלֹשָׁה וְאָמְרוּ שֶׁהוֹנָה הַהֶקְדֵּשׁ בְּכָל שֶׁהוּא חוֹזֵר:","אֵין פּוֹדִין אֶת הַהֶקְדֵּשׁ אַכְסָרָה אֶלָּא בַּחֲקִירַת דָּמִים כְּמוֹ שֶׁבֵּאַרְנוּ. וְאִם פָּדָה יַד הֶקְדֵּשׁ עַל הָעֶלְיוֹנָה. כֵּיצַד. פָּרָה זוֹ תַּחַת פָּרָה זוֹ שֶׁל הֶקְדֵּשׁ טַלִּית זוֹ תַּחַת טַלִּית זוֹ שֶׁל הֶקְדֵּשׁ. הֶקְדֵּשׁוֹ פָּדוּי וְיַד הֶקְדֵּשׁ עַל הָעֶלְיוֹנָה. אִם הָיְתָה הַשְּׁנִיָּה יָפָה מִן הָרִאשׁוֹנָה בְּיוֹתֵר לוֹקְחִין אוֹתָהּ הַגִּזְבָּרִין וְשׁוֹתְקִין. וְאִם אֵינָהּ יָפָה מְשַׁלֵּם אֶת הַדָּמִים כְּמוֹ שֶׁבֵּאַרְנוּ וּמוֹסִיף חֹמֶשׁ. אֲבָל אִם אָמַר טַלִּית זוֹ בְּעֶשֶׂר סְלָעִים תַּחַת טַלִּית שֶׁל הֶקְדֵּשׁ וּפָרָה זוֹ בְּעֶשֶׂר סְלָעִים תַּחַת פָּרָה זוֹ שֶׁל הֶקְדֵּשׁ. אֲפִלּוּ הָיְתָה שֶׁל הֶקְדֵּשׁ שָׁוָה חָמֵשׁ וְשֶׁלּוֹ עֶשֶׂר הֲרֵי זֶה מוֹסִיף חֹמֶשׁ וְנוֹתֵן שְׁתֵּי סְלָעִים וּמֶחֱצָה שֶׁהֲרֵי בְּדָמִים קְצוּבִים פָּדָה. וּשְׁנִיָּה אֵינָהּ טְעוּנָה חֹמֶשׁ כְּמוֹ שֶׁבֵּאַרְנוּ:","הַפּוֹדֶה מִיַּד הַהֶקְדֵּשׁ מָשַׁךְ בְּמָנֶה וְלֹא הִסְפִּיק לִתֵּן הַדָּמִים עַד שֶׁעָמַד בְּמָאתַיִם נוֹתֵן מָאתַיִם שֶׁנֶּאֱמַר וְנָתַן אֶת הַכֶּסֶף וְקָם לוֹ. בִּנְתִינַת הַכֶּסֶף הוּא שֶׁלּוֹ. מְשָׁכוֹ בְּמָאתַיִם וְלֹא הִסְפִּיק לִתֵּן אֶת הַדָּמִים עַד שֶׁעָמַד בְּמָנֶה נוֹתֵן מָאתַיִם. לֹא יְהֵא כֹּחַ הֶדְיוֹט חָמוּר מִכֹּחַ הֶקְדֵּשׁ. וַהֲרֵי קָנָה בִּמְשִׁיכָה וְנִתְחַיֵּב בַּדָּמִים:","פָּדָה בְּמָאתַיִם וְנָתַן הַדָּמִים וְלֹא הִסְפִּיק לְמָשְׁכוֹ עַד שֶׁעָמַד בְּמָנֶה כְּבָר קָנָה בִּנְתִינַת הַכֶּסֶף וּמוֹשֵׁךְ אֶת שֶׁלּוֹ וְזָכָה הֶקְדֵּשׁ בְּמָאתַיִם. פָּדָהוּ בְּמָנֶה וְנָתַן הַדָּמִים וְלֹא הִסְפִּיק לְמָשְׁכוֹ עַד שֶׁעָמַד בְּמָאתַיִם מַה שֶּׁפָּדָה פָּדוּי וְאֵינוֹ נוֹתֵן אֶלָּא הַמָּנֶה שֶׁכְּבָר נָתַן. וְאֵין אוֹמְרִין כָּאן לֹא יְהֵא כֹּחַ הֶדְיוֹט חָמוּר מִכֹּחַ הֶקְדֵּשׁ. שֶׁאֲפִלּוּ הֶדְיוֹט אֵינוֹ יָכוֹל לַחְזֹר בּוֹ עַד שֶׁיְּקַבֵּל מִי שֶׁפָּרַע כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ וְאֵין הֶקְדֵּשׁ רָאוּי לְקַבֵּל מִי שֶׁפָּרַע:","הַמַּקְדִּישׁ כָּל נְכָסָיו וְהָיְתָה עָלָיו כְּתֻבַּת אִשָּׁה אוֹ שִׁטְרֵי בַּעֲלֵי חוֹבוֹת. אֵין הָאִשָּׁה יְכוֹלָה לִגְבּוֹת כְּתֻבָּתָהּ מִן הַהֶקְדֵּשׁ וְלֹא בַּעַל חוֹב אֶת חוֹבוֹ. שֶׁהַהֶקְדֵּשׁ מַפְקִיעַ הַשִּׁעְבּוּד שֶׁקָּדַם. אֲבָל כְּשֶׁיִּמְכֹּר הַהֶקְדֵּשׁ הַקַּרְקַע שֶׁלּוֹ וְתֵצֵא הַשָּׂדֶה לְחֻלִּין יֵשׁ לְבַעַל חוֹב וּלְאִשָּׁה לִגְבּוֹת מִן הַפּוֹדֶה שֶׁהֲרֵי שִׁעְבּוּדָהּ עוֹמֵד עַל קַרְקַע זוֹ:","הָא לְמָה זֶה דּוֹמֶה לִשְׁנֵי לָקוֹחוֹת שֶׁכָּתְבָה לָרִאשׁוֹן דִּין וּדְבָרִים אֵין לִי עִמְּךָ וּמָכַר לַשֵּׁנִי שֶׁהִיא טוֹרֶפֶת מִן הַשֵּׁנִי:","וְכֵיצַד פּוֹדִין קַרְקַע זֶה. מַשְׁבִּיעִין אֶת הָאִשָּׁה אוֹ בַּעַל חוֹב תְּחִלָּה כְּדֶרֶךְ כָּל הַבָּא לִפָּרַע מִנְּכָסִים מְשֻׁעְבָּדִים וְאַחַר כָּךְ מַכְרִיזִין עֲלֵיהֶם שִׁשִּׁים יוֹם בַּבֹּקֶר וּבָעֶרֶב כְּמוֹ שֶׁבֵּאַרְנוּ. וְאוֹמְדִין כַּמָּה אָדָם רוֹצֶה לִתֵּן בַּשָּׂדֶה עַל מְנָת לִתֵּן לְאִשָּׁה כְּתֻבָּתָהּ וּלְבַעַל חוֹב אֶת חוֹבוֹ. וְאַחַר שֶׁפּוֹדִין אוֹתָהּ וְלוֹקֵחַ אוֹתָהּ הַלּוֹקֵחַ אֲפִלּוּ בְּדִינָר כְּדֵי שֶׁלֹּא יֹאמְרוּ הֶקְדֵּשׁ יוֹצֵא בְּלֹא פִּדְיוֹן. חוֹזֵר הַפּוֹדֶה וּמַגְבֶּה לָאִשָּׁה כְּתֻבָּתָהּ אוֹ לַבַּעַל חוֹב אֶת חוֹבוֹ. אֲפִלּוּ הָיָה הַחוֹב מֵאָה וְהַשָּׂדֶה שָׁוָה תִּשְׁעִים עַל מְנָת כָּךְ פּוֹדֶה אוֹתָהּ הָרוֹצֶה לִפְדּוֹתָהּ. אֲבָל אִם הָיָה הַחוֹב שְׁנַיִם בִּדְמֵי הַשָּׂדֶה כְּגוֹן שֶׁהָיְתָה שָׁוָה מֵאָה וְיֵשׁ עָלָיו חוֹב וּכְתֻבַּת אִשָּׁה מָאתַיִם אֵין פּוֹדִין אוֹתָהּ עַל מְנָת לִתֵּן הַחוֹב אוֹ הַכְּתֻבָּה אֶלָּא פּוֹדִין אוֹתָהּ סְתָם שֶׁאִם הִתְנוּ לִתֵּן אֵינָהּ נִפְדֵית כְּלָל:","הַמַּקְדִּישׁ כָּל נְכָסָיו וְאַחַר כָּךְ גֵּרֵשׁ אֶת אִשְׁתּוֹ וְגָבְתָה כְּתֻבָּתָהּ מִן הַפּוֹדֶה מִן הַהֶקְדֵּשׁ אֵינוֹ גּוֹבֶה עַד שֶׁיַּדִּירֶנָּה הֲנָאָה. שֶׁמָּא קְנוּנְיָא עָשׂוּ עַל הַהֶקְדֵּשׁ. וְאֵין אוֹמְרִין אִלּוּ רָצָה הָיָה אוֹמֵר בְּטָעוּת הִקְדַּשְׁתִּי וְיִשָּׁאֵל עַל הֶקְדֵּשׁוֹ לְחָכָם וְיַחְזֹר לוֹ:","וְכֵן אֵין נֶאֱמָן לוֹמַר אַחַר שֶׁהִקְדִּישׁ מָנֶה לִפְלוֹנִי חוֹב עָלַי אוֹ כְּלִי זֶה שֶׁל פְּלוֹנִי הוּא. שֶׁמָּא יַעֲשׂוּ קְנוּנְיָא עַל הַהֶקְדֵּשׁ. וַאֲפִלּוּ הָיָה שְׁטָר בְּיַד בַּעַל חוֹב אֵינוֹ גּוֹבֶה עַל פִּי זֶה אֶלָּא כְּדֶרֶךְ שֶׁגּוֹבִין כָּל בַּעֲלֵי חוֹבוֹת כְּמוֹ שֶׁבֵּאַרְנוּ:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּבָרִיא. אֲבָל חוֹלֶה שֶׁהִקְדִּישׁ כָּל נְכָסָיו וְאָמַר בְּשָׁעָה שֶׁהִקְדִּישׁ מָנֶה לִפְלוֹנִי בְּיָדִי נֶאֱמָן. שֶׁאֵין אָדָם עוֹשֶׂה עָרְמָה עַל הַהֶקְדֵּשׁ בִּשְׁעַת מִיתָתוֹ וְחוֹטֵא לַאֲחֵרִים שֶׁהֲרֵי הוּא הוֹלֵךְ לָמוּת. לְפִיכָךְ אִם אָמַר תְּנוּ אוֹתָהּ לוֹ נוֹטֵל בְּלֹא שְׁבוּעָה. וְאִם לֹא אָמַר תְּנוּ אֵין נוֹתְנִין אֶלָּא אִם כֵּן הָיָה בְּיָדוֹ שְׁטָר מְקֻיָּם. הֲרֵי זֶה נוֹטֵל מִן הַהֶקְדֵּשׁ מִפְּנֵי הַצַּוָּאָה. וְאִם אַחַר שֶׁהִקְדִּישׁ אָמַר תְּנוּ אֵין שׁוֹמְעִין לוֹ אֶלָּא הֲרֵי הוּא כִּשְׁאָר בַּעֲלֵי חוֹבוֹת. אִם נִתְקַיֵּם שְׁטָרוֹ נִשְׁבָּע וְגוֹבֶה מִן הַפּוֹדֶה וְלֹא מִן הַהֶקְדֵּשׁ:","מִי שֶׁיָּצָא עָלָיו קוֹל שֶׁהִפְקִיר אֶת נְכָסָיו אוֹ הִקְדִּישָׁן אוֹ הֶחֱרִימָן אֵין חוֹשְׁשִׁין לוֹ עַד שֶׁתִּהְיֶה שָׁם רְאָיָה בְּרוּרָה:"],"Mishneh Torah, Blessings 9":["כְּשֵׁם שֶׁאָסוּר לָאָדָם לֵהָנוֹת בְּמַאֲכָל אוֹ בְּמַשְׁקֶה קֹדֶם בְּרָכָה. כָּךְ אָסוּר לוֹ לֵהָנוֹת בְּרֵיחַ טוֹב קֹדֶם בְּרָכָה. וְכֵיצַד מְבָרֵךְ עַל רֵיחַ טוֹב. אִם הָיָה זֶה שֶׁיֵּשׁ לְהָרִיחַ עֵץ אוֹ מִן הָעֵץ מְבָרֵךְ בּוֹרֵא עֲצֵי בְּשָׂמִים. וְאִם הָיָה עֵשֶׂב אוֹ מִן הָעֵשֶׂב מְבָרֵךְ בּוֹרֵא עִשְׂבֵי בְּשָׂמִים. וְאִם לֹא הָיָה מִן הָעֵץ וְלֹא מִן הָאֲדָמָה כְּגוֹן הַמּוֹר שֶׁהוּא מִן הַחַיָּה מְבָרֵךְ בּוֹרֵא מִינֵי בְּשָׂמִים. וְאִם הָיָה פְּרִי הָרָאוּי לַאֲכִילָה כְּגוֹן אֶתְרוֹג אוֹ תַּפּוּחַ מְבָרֵךְ שֶׁנָּתַן רֵיחַ טוֹב בַּפֵּרוֹת. וְעַל הַכּל אִם אָמַר בּוֹרֵא מִינֵי בְּשָׂמִים יָצָא:","אֵין מְבָרְכִין עַל הַמֻּגְמָר עַד שֶׁתַּעֲלֶה תִּמְרָתוֹ. וְכֵיצַד מְבָרְכִין עָלָיו. אִם הָיָה זֶה הַנִּשְׂרָף שֶׁנָּתַן רֵיחַ מֵעֵץ מְבָרְכִין בּוֹרֵא עֲצֵי בְּשָׂמִים. וְאִם הָיָה עֵשֶׂב עִשְׂבֵי בְּשָׂמִים. וְאִם הָיָה מִמִּין חַיָּה וְכַיּוֹצֵא בָּהּ מְבָרֵךְ עָלָיו בּוֹרֵא מִינֵי בְּשָׂמִים:","שֶׁמֶן שֶׁל אֲפַרְסְמוֹן וְכַיּוֹצֵא בּוֹ מְבָרֵךְ עָלָיו בּוֹרֵא שֶׁמֶן עָרֵב. אֲבָל שֶׁמֶן זַיִת שֶׁכְּבָשׁוֹ אוֹ שֶׁטְּחָנוֹ עַד שֶׁחָזַר רֵיחוֹ נוֹדֵף מְבָרֵךְ עָלָיו בּוֹרֵא עֲצֵי בְּשָׂמִים. שֶׁמֶן שֶׁבִּשְׁמוֹ כְּעֵין שֶׁמֶן הַמִּשְׁחָה מְבָרֵךְ עָלָיו בּוֹרֵא מִינֵי בְּשָׂמִים. הֵבִיאוּ לְפָנָיו שֶׁמֶן וַהֲדַס מְבָרֵךְ עַל הַהֲדַס וּפוֹטֵר אֶת הַשֶּׁמֶן מִפְּנֵי שֶׁבְּרָכָה אַחַת לִשְׁתֵּיהֶן וְהוּא עֲצֵי בְּשָׂמִים:","הָיוּ לְפָנָיו בּשֶֹׁם שֶׁהוּא עֵץ וּבשֶֹׁם שֶׁהוּא עֵשֶׂב אֵין בְּרָכָה אַחַת מֵהֶן פּוֹטֶרֶת אֶת חֲבֵרוֹ. אֶלָּא מְבָרֵךְ עַל זֶה לְעַצְמוֹ וְעַל זֶה לְעַצְמוֹ. הֵבִיאוּ לְפָנָיו יַיִן וְשֶׁמֶן אוֹחֵז יַיִן בִּימִינוֹ וְשֶׁמֶן בִּשְׂמֹאלוֹ וּמְבָרֵךְ עַל הַיַּיִן וְשׁוֹתֵהוּ וְחוֹזֵר וּמְבָרֵךְ עַל הַשֶּׁמֶן וּמֵרִיחַ בּוֹ וְטָחוֹ בְּרֹאשׁ הַשַּׁמָּשׁ. וְאִם הָיָה הַשַּׁמָּשׁ תַּלְמִיד חָכָם טָחוֹ בַּכֹּתֶל:","דָּבָר שֶׁהוּא סָפֵק אִם מִן הָעֵץ אִם מִן הָאֲדָמָה מְבָרֵךְ עָלָיו בּוֹרֵא מִינֵי בְּשָׂמִים. בּשֶֹׁם שֶׁעֵרְבוֹ הָרוֹכֵל מִמִּינִין הַרְבֵּה מְבָרֵךְ עָלָיו בּוֹרֵא מִינֵי בְּשָׂמִים. נִכְנָס לַחֲנוּתוֹ שֶׁל בּוֹשֵׂם שֶׁיֵּשׁ בָּהּ מִינִין הַרְבֵּה מְבָרֵךְ עָלָיו בּוֹרֵא מִינֵי בְּשָׂמִים. אִם יָשַׁב שָׁם כָּל הַיּוֹם כֻּלּוֹ אֵינוֹ מְבָרֵךְ אֶלָּא אַחַת. נִכְנַס וְיָצָא נִכְנַס וְיָצָא מְבָרֵךְ עַל כָּל פַּעַם וּפַעַם:","הַשּׁוֹשַׁנָּה וַחֲלָפֵי הַמַּיִם מְבָרְכִין עֲלֵיהֶן בּוֹרֵא עֲצֵי בְּשָׂמִים. נַרְגִּיס שֶׁל גִּנָּה בּוֹרֵא עֲצֵי בְּשָׂמִים וְשֶׁל שָׂדֶה בּוֹרֵא עִשְׂבֵי בְּשָׂמִים. הַוֶּרֶד וּמֵי הַוֶּרֶד וְהַלְּבוֹנָה וְהַמַּסְטְכִי וְכַיּוֹצֵא בָּהֶן בּוֹרֵא עֲצֵי בְּשָׂמִים:","שְׁלֹשָׁה מִינֵי רֵיחַ טוֹב אֵין מְבָרְכִין עֲלֵיהֶן וְאֵלּוּ הֵן. רֵיחַ טוֹב שֶׁאָסוּר לְהָרִיחַ בּוֹ. וְרֵיחַ טוֹב שֶׁעָשׂוּי לְהַעֲבִיר רֵיחַ רַע. וְרֵיחַ טוֹב שֶׁלֹּא נַעֲשָׂה לְהָרִיחַ בְּעַצְמוֹ שֶׁל רֵיחַ זֶה:","כֵּיצַד. בְּשָׂמִים שֶׁל עַכּוּ״ם וּבְשָׂמִים שֶׁל עֶרְוָה מִן הָעֲרָיוֹת אֵין מְבָרְכִין עֲלֵיהֶן לְפִי שֶׁאָסוּר לְהָרִיחַ בָּהֶן. בְּשָׂמִים שֶׁל מֵתִים וּבְשָׂמִים שֶׁל בֵּית הַכִּסֵּא וְשֶׁמֶן הֶעָשׂוּי לְהַעֲבִיר אֶת הַזֻּהֲמָא אֵין מְבָרְכִין עֲלֵיהֶן לְפִי שֶׁנַּעֲשׂוּ לְהַעֲבִיר רֵיחַ רַע. מֻגְמָר שֶׁמְּגַמְּרִין בּוֹ אֶת הַכֵּלִים וְאֶת הַבְּגָדִים אֵין מְבָרְכִין עֲלֵיהֶן לְפִי שֶׁלֹּא נַעֲשָׂה לְהָרִיחַ בְּעַצְמוֹ שֶׁל מֻגְמָר. וְכֵן הַמֵּרִיחַ בִּבְגָדִים שֶׁהֵן מְגֻמָּרִים אֵינוֹ מְבָרֵךְ לְפִי שֶׁאֵין שָׁם עִקָּר בּשֶֹׁם אֶלָּא רֵיחַ בְּלֹא עִקָּר:","בְּשָׂמִים שֶׁל מְסִבָּה שֶׁל עַכּוּ״ם אֵין מְבָרְכִין עֲלֵיהֶם שֶׁסְּתָם מְסִבַּת עַכּוּ״ם לַעֲבוֹדַת כּוֹכָבִים. הָיָה מְהַלֵּךְ חוּץ לַכְּרַךְ וְהֵרִיחַ רֵיחַ טוֹב. אִם רֹב הָעִיר עַכּוּ״ם אֵינוֹ מְבָרֵךְ. וְאִם רֹב יִשְׂרָאֵל מְבָרֵךְ. נִתְעָרֵב רֵיחַ שֶׁמְּבָרְכִין עָלָיו בְּרֵיח שֶׁאֵין מְבָרְכִין עָלָיו הוֹלְכִין אַחֲרֵי הָרֹב:"],"Mishneh Torah, Creditor and Debtor 1":["מִצְוַת עֲשֵׂה לְהַלְווֹת לַעֲנִיֵּי יִשְׂרָאֵל שֶׁנֶּאֱמַר (שמות כב כד) \"אִם כֶּסֶף תַּלְוֶה אֶת עַמִּי אֶת הֶעָנִי עִמָּךְ\". יָכוֹל רְשׁוּת תַּלְמוּד לוֹמַר (דברים טו ח) \"הַעֲבֵט תַּעֲבִיטֶנּוּ\" וְגוֹ'. וּמִצְוָה זוֹ גְּדוֹלָה מִן הַצְּדָקָה אֶל הֶעָנִי הַשּׁוֹאֵל שֶׁזֶּה כְּבָר נִצְרַךְ לִשְׁאל וְזֶה עֲדַיִן לֹא הִגִּיעַ לְמִדָּה זוֹ. וְהַתּוֹרָה הִקְפִּידָה עַל מִי שֶׁיִּמָּנַע מִלְּהַלְווֹת לֶעָנִי שֶׁנֶּאֱמַר (דברים טו ט) \"וְרָעָה עֵינְךָ בְּאָחִיךָ הָאֶבְיוֹן\" וְגוֹ':","כָּל הַנּוֹגֵשׂ הֶעָנִי וְהוּא יוֹדֵעַ שֶׁאֵין לוֹ מַה יַּחֲזִיר לוֹ עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (שמות כב כד) \"לֹא תִהְיֶה לוֹ כְּנשֶׁה\". וּמִצְוַת עֲשֵׂה לִנְגּשֹׁ אֶת הָעַכּוּ\"ם וּלְהָצֵר לוֹ שֶׁנֶּאֱמַר (דברים טו ג) \"לַנָּכְרִי תִּגּשֹׁ\" מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזּוֹ מִצְוַת עֲשֵׂה:","אָסוּר לָאָדָם לְהַרְאוֹת עַצְמוֹ לְבַעַל חוֹבוֹ בִּזְמַן שֶׁיּוֹדֵעַ שֶׁאֵין לוֹ. אֲפִלּוּ לַעֲבֹר לְפָנָיו שֶׁלֹּא יַפְחִידוֹ אוֹ יַכְלִימוֹ אַף עַל פִּי שֶׁאֵינוֹ תּוֹבְעוֹ וְאֵין צָרִיךְ לוֹמַר אִם תְּבָעוֹ. וּכְשֵׁם שֶׁאָסוּר לְזֶה לִתְבֹּעַ כָּךְ אָסוּר לַלּוֶֹה לִכְבּשׁ מָמוֹן חֲבֵרוֹ שֶׁבְּיָדוֹ וְלוֹמַר לוֹ לֵךְ וְשׁוּב וְהוּא שֶׁיֵּשׁ לוֹ שֶׁנֶּאֱמַר (משלי ג כח) \"אַל תֹּאמַר לְרֵעֲךָ לֵךְ וְשׁוּב\". וְכֵן אָסוּר לַלּוֶֹה לִקַּח הַלְוָאָה וּלְהוֹצִיאָהּ שֶׁלֹּא לְצֹרֶךְ וּלְאַבְּדָהּ עַד שֶׁלֹּא יִמְצָא בַּעַל חוֹב מֵאַיִן יִגְבֶּה אַף עַל פִּי שֶׁהַמַּלְוֶה עָשִׁיר גָּדוֹל. וְעוֹשֶׂה זֶה רָשָׁע הוּא שֶׁנֶּאֱמַר (תהילים לז כא) \"לוֶֹה רָשָׁע וְלֹא יְשַׁלֵּם\". וְצִוּוּ חֲכָמִים (משנה אבות ב יב) \"יְהִי מָמוֹן חֲבֵרְךָ חָבִיב עָלֶיךָ כְּשֶׁלָּךְ\":","כְּשֶׁיִּתְבַּע הַמַּלְוֶה הַלְוָאָתוֹ אַף עַל פִּי שֶׁהוּא עָשִׁיר וְהַלּוֶֹה דָּחוּק וְטָרוּד בִּמְזוֹנוֹת אֵין מְרַחֲמִין בַּדִּין אֶלָּא גּוֹבִין לוֹ חוֹבוֹ עַד פְּרוּטָה אַחֲרוֹנָה מִכָּל מִטַּלְטְלִין שֶׁיִּמָּצְאוּ לוֹ. וְאִם לֹא הִסְפִּיקוּ הַמִּטַּלְטְלִין גּוֹבִין לוֹ מִן הַקַּרְקַע אַחַר שֶׁמַּחְרִימִין עַל מִי שֶׁיֵּשׁ לוֹ מִטַּלְטְלִין אוֹ מִי שֶׁיָּדַע לוֹ מִטַּלְטְלִין וְלֹא יְבִיאֵם לְבֵית דִּין. וְגוֹבִין מִכָּל קַרְקַע שֶׁיֵּשׁ לוֹ אַף עַל פִּי שֶׁהִיא מְשֻׁעְבֶּדֶת לִכְתֻבַּת אִשְׁתּוֹ אוֹ לְבַעַל חוֹבוֹ שֶׁקָּדַם גּוֹבִין לָזֶה וְאִם יָבוֹא הָרִאשׁוֹן וְיִטְרֹף יִטְרֹף. טָעַן הַלּוֶֹה שֶׁמִּטַּלְטְלִין אֵלּוּ שֶׁבְּיָדִי אֵינָן שֶׁלִּי אֶלָּא פִּקָּדוֹן הֵם בְּיָדִי אוֹ שְׂכוּרִין אוֹ שְׁאוּלִין אֵין שׁוֹמְעִין לוֹ אוֹ יָבִיא רְאָיָה אוֹ יִגְבֶּה מֵהֶן בַּעַל חוֹבוֹ:","אֵין בַּעַל חוֹב גּוֹבֶה לֹא מִכְּסוּת אִשְׁתּוֹ וּבָנָיו שֶׁל לוֶֹה וְלֹא מִבְּגָדִים צְבוּעִים שֶׁצְּבָעָן לִשְׁמָן אַף עַל פִּי שֶׁעֲדַיִן לֹא לָבְשׁוּ אוֹתָן וְלֹא מִסַּנְדָּלִים חֲדָשִׁים שֶׁלְּקָחָן לִשְׁמָן אֶלָּא הֲרֵי אֵלּוּ שֶׁלָּהֶן. בַּמֶּה דְּבָרִים אֲמוּרִים בִּכְלֵי הַחוֹל אֲבָל בִּגְדֵי שַׁבָּת וְהַמּוֹעֵד גּוֹבֶה אוֹתָן בַּעַל חוֹב וְאֵין צָרִיךְ לוֹמַר אִם הָיוּ בָּהֶן טַבָּעוֹת וּכְלֵי זָהָב אוֹ כֶּסֶף שֶׁהַכּל לְבַעַל חוֹבוֹ:","הָיוּ לוֹ מִטַּלְטְלִין אוֹ קַרְקַע וַהֲרֵי עָלָיו שְׁטַר חוֹבוֹת לָעַכּוּ\"ם וְאָמַר הֲרֵי כָּל נְכָסַי מְשֻׁעְבָּדִין לָעַכּוּ\"ם וְאִם יִטְּלוּ אוֹתָן הַיִּשְׂרְאֵלִים בְּחוֹבָם יַאַסְרוּ אוֹתִי הָעַכּוּ\"ם בְּחוֹבָן וְאֶהְיֶה בַּשִּׁבְיָה. הוֹרוּ רַבּוֹתַי שֶׁאֵין שׁוֹמְעִין לוֹ וְיִגְבּוּ הַיִּשְׂרְאֵלִים. וּכְשֶׁיָּבוֹאוּ הָעַכּוּ\"ם וְיַאַסְרוּהוּ הֲרֵי כָּל יִשְׂרָאֵל מְצֻוִּין לִפְדּוֹתוֹ:","מְסַדְּרִין לְבַעַל חוֹב כְּדֶרֶךְ שֶׁמְּסַדְּרִין בַּעֲרָכִין. כֵּיצַד. אוֹמֵר לַלּוֶֹה הָבֵא כָּל הַמִּטַּלְטְלִין שֶׁיֵּשׁ לְךָ וְלֹא תַּנִּיחַ אֲפִלּוּ מַחַט אַחַת. וְנוֹתְנִין לוֹ מִן הַכּל מְזוֹן [שְׁלֹשִׁים] יוֹם וּכְסוּת שְׁנֵים עָשָׂר חֹדֶשׁ מִכְּסוּת הָרְאוּיָה לוֹ. וְלֹא שֶׁיִּלְבַּשׁ בִּגְדֵי מֶשִׁי אוֹ מִצְנֶפֶת זְהוּבָה אֶלָּא מַעֲבִירִין אוֹתָהּ מִמֶּנּו. וְנוֹתְנִין לוֹ כְּסוּת הָרְאוּיָה לוֹ לִשְׁנֵים עָשָׂר חֹדֶשׁ. וּמִטָּה לֵישֵׁב עָלֶיהָ וּמִטָּה וּמַצָּע הָרְאוּיִין לוֹ לִישֹׁן עֲלֵיהֶם. וְאִם הָיָה עָנִי מִטָּה וּמַפָּץ לִישֹׁן עָלָיו. וְאֵין נוֹתְנִין כֵּלִים כָּאֵלּוּ לְאִשְׁתּוֹ וּבָנָיו אַף עַל פִּי שֶׁהוּא חַיָּב בִּמְזוֹנוֹתֵיהֶם. וְנוֹתְנִין לוֹ סַנְדָּלָיו וּתְפִלָּיו. הָיָה אֻמָּן נוֹתְנִין לוֹ שְׁנֵי כְּלֵי אֻמָּנוּת מִכָּל מִין וּמִין כְּגוֹן שֶׁהָיָה חָרָשׁ נוֹתְנִין לוֹ שְׁנֵי מַעֲצָדִין וּשְׁתֵּי מְגֵרוֹת. הָיָה לוֹ מִין אֶחָד מְרֻבֶּה וּמִין אֶחָד מוּעָט נוֹתְנִין לוֹ שְׁנַיִם מִן הַמְרֻבֶּה וְכָל שֶׁיֵּשׁ לוֹ מִן הַמּוּעָט. וְאֵין לוֹקְחִין לוֹ כֵּלִים מִדְּמֵי הַמְרֻבֶּה. הָיָה אִכָּר אוֹ חַמָּר אֵין נוֹתְנִין לוֹ לֹא צִמְדּוֹ וְלֹא חֲמוֹרוֹ. וְכֵן אִם הָיָה סַפָּן אֵין נוֹתְנִין לוֹ סְפִינָתוֹ אַף עַל פִּי שֶׁאֵין לוֹ מְזוֹנוֹת אֶלָּא מֵאֵלּוּ אֵין אֵלּוּ כֵּלִים אֶלָּא נְכָסִים וְיִמָּכְרוּ עִם שְׁאָר הַמִּטַּלְטְלִין בְּבֵית דִּין וְיִנָּתְנוּ לְבַעַל חוֹבוֹ:","מַלְוֶה שֶׁבָּא לְהִפָּרַע שֶׁלֹּא בִּפְנֵי הַלּוֶֹה כְּגוֹן שֶׁהָיָה הַלּוֶֹה בִּמְדִינָה רְחוֹקָה וְתָפְסָה הָאִשָּׁה מִטַּלְטְלִין מִנִּכְסֵי הַבַּעַל כְּדֵי שֶׁתִּזּוֹן מֵהֶן מוֹצִיאִין אוֹתָן מִיָּדָהּ וְנוֹתְנִין לְבַעַל חוֹב שֶׁאֲפִלּוּ הָיָה בַּעְלָהּ עִמָּהּ לֹא הָיָה יָכוֹל לָזוּן אֶת אִשְׁתּוֹ וּבָנָיו עַד שֶׁיִּפְרַע לוֹ כָּל חוֹבוֹ:"],"Mishneh Torah, Creditor and Debtor 20":["מִי שֶׁיֵּשׁ לוֹ חוֹבוֹת הַרְבֵּה כָּל שֶׁקָּדַם חוֹבוֹ גּוֹבֶה תְּחִלָּה בֵּין מִן הַלּוֶֹה עַצְמוֹ בֵּין מִן הַלָּקוֹחוֹת. וְאִם קָדַם הָאַחֲרוֹן וְגָבָה מוֹצִיאִים מִיָּדוֹ שֶׁכָּל שֶׁקָּדַם חוֹבוֹ זָכָה. בַּמֶּה דְּבָרִים אֲמוּרִים בְּקַרְקָעוֹת שֶׁהָיוּ לוֹ בְּעֵת שֶׁלָּוָה אֲבָל הַקַּרְקָעוֹת שֶׁקָּנָה אַחַר שֶׁלָּוָה מִבַּעֲלֵי חוֹבוֹת הַרְבֵּה אַף עַל פִּי שֶׁכָּתַב לְכָל אֶחָד מֵהֶן מַה שֶּׁאֲנִי עָתִיד לִקְנוֹת מְשֻׁעְבָּד לְךָ אֵין בָּהֶן דִּין קְדִימָה אֶלָּא כֻּלָּן שָׁוִין וְכָל שֶׁקָּדַם וְגָבָה זָכָה אַף עַל פִּי שֶׁהוּא אַחֲרוֹן:","לָוָה וְכָתַב לוֹ שֶׁאֲנִי עָתִיד לִקְנוֹת מְשֻׁעְבָּד לְךָ וְאַחַר כָּךְ קָנָה שָׂדֶה וְחָזַר וְלָוָה מֵאַחֵר הֲרֵי הַשָּׂדֶה מְשֻׁעְבָּד לָרִאשׁוֹן וְהוּא קוֹדֵם לִגְבּוֹת. וְכֵן אֲפִלּוּ הָיוּ מֵאָה אֵין דִּין קְדִימָה בְּמִטַּלְטְלִין אֶלָּא כָּל שֶׁקָּדַם וְגָבָה מֵהֶן זָכָה אַף עַל פִּי שֶׁהוּא אַחֲרוֹן. קִדֵּם אֶחָד מִשְּׁאָר אָדָם וְתָפַס מִן הַמִּטַּלְטְלִין שֶׁל זֶה כְּדֵי לִזְכּוֹת לְאֶחָד מִבַּעֲלֵי חוֹבוֹת לֹא זָכָה שֶׁכָּל הַתּוֹפֵס לְבַעַל חוֹב בְּמָקוֹם שֶׁיֵּשׁ עָלָיו חוֹב לַאֲחֵרִים לֹא קָנָה. אֲבָל אֵין עָלָיו חוֹב לַאֲחֵרִים קָנָה לוֹ. וְכֵן אִם אָמַר לוֹ הַלּוֶֹה זְכֵה בְּחֵפֶץ זֶה לִפְלוֹנִי זָכָה לוֹ וְאֵין אֶחָד מִבַּעֲלֵי חוֹבוֹת יְכוֹלִין לִגְבּוֹת מֵאֵלּוּ הַמִּטַּלְטְלִין שֶׁכְּבָר זָכָה בָּהֶן אַחֵר:","שְׁטָרוֹת שֶׁזְּמַן כֻּלָּן יוֹם אֶחָד אוֹ שָׁעָה אַחַת בְּמָקוֹם שֶׁכּוֹתְבִין שָׁעוֹת כָּל שֶׁקָּדַם מֵהֶן וְגָבָה בֵּין קַרְקַע בֵּין מִטַּלְטְלִין זָכָה:","בָּאוּ כֻּלָּן בְּיַחַד לִגְבּוֹת. וְכֵן בַּעֲלֵי חוֹבוֹת שֶׁכָּל אֶחָד מֵהֶן קוֹדֵם לִזְמַן חֲבֵרוֹ שֶׁבָּאוּ לִגְבּוֹת מִן הַמִּטַּלְטְלִין שֶׁהֲרֵי אֵין בָּהֶן דִּין קְדִימָה. אוֹ שֶׁבָּאוּ לִגְבּוֹת מִקַּרְקַע שֶׁקָּנָה הַלּוֶֹה לְאַחַר שֶׁלָּוָה מִן הָאַחֲרוֹן שֶׁבָּהֶן וְאֵין בַּנְּכָסִים כְּדֵי שֶׁיִּגְבֶּה כָּל אֶחָד מֵהֶן אֶת חוֹבוֹ. מְחַלְּקִין בֵּינֵיהֶן. כֵּיצַד חוֹלְקִין. אִם כְּשֶׁיִּתְחַלֵּק הַמָּמוֹן הַנִּמְצָא עַל מִנְיָנָם יַגִּיעַ לַפָּחוּת שֶׁבָּהֶן כְּשִׁעוּר חוֹבוֹ אוֹ פָּחוֹת חוֹלְקִים לְפִי מִנְיָנָם בְּשָׁוֶה. וְאִם יַגִּיעַ לַפָּחוּת שֶׁבָּהֶם יוֹתֵר עַל חוֹבוֹ חוֹלְקִים מִכָּל הַמָּמוֹן בֵּינֵיהֶם כְּדֵי שֶׁיַּגִּיעַ לַפָּחוּת שֶׁבָּהֶם כְּשִׁעוּר חוֹבוֹ וְחוֹזְרִין הַנִּשְׁאָרִים מִבַּעֲלֵי חוֹבוֹת וְחוֹלְקִין הַיֶּתֶר בֵּינֵיהֶן כַּדֶּרֶךְ הַזֹּאת. כֵּיצַד. הָיוּ שְׁלֹשָׁה חוֹבוֹת שֶׁל זֶה מָנֶה וְשֶׁל זֶה מָאתַיִם וְשֶׁל זֶה שְׁלֹשׁ מֵאוֹת אִם הָיָה כָּל הַנִּמְצָא שְׁלֹשׁ מֵאוֹת נוֹטְלִין מֵאָה מֵאָה. וְכֵן אִם נִמְצָא שָׁם פָּחוֹת מִשְּׁלֹשׁ מֵאוֹת חוֹלְקִין בְּשָׁוֶה. נִמְצָא שָׁם יֶתֶר עַל שְׁלֹשׁ מֵאוֹת חוֹלְקִין שְׁלֹשׁ מֵאוֹת בְּשָׁוֶה וְיִסְתַּלֵּק בַּעַל הַמֵּאָה וּשְׁאָר הַמָּמוֹן חוֹלְקִין אוֹתוֹ הַשְּׁנַיִם עַל אוֹתָהּ הַדֶּרֶךְ. כֵּיצַד. נִמְצְאוּ שָׁם חֲמֵשׁ מֵאוֹת אוֹ פָּחוֹת חוֹלְקִין שְׁלֹשׁ מֵאוֹת בְּשָׁוֶה וְיִסְתַּלֵּק הָאֶחָד וְחוֹזְרִין וְחוֹלְקִין הַמָּאתַיִם אוֹ הַפָּחוֹת בְּשָׁוֶה וְיִסְתַּלֵּק הַשֵּׁנִי. נִמְצָא שָׁם שֵׁשׁ מֵאוֹת חוֹלְקִין שְׁלֹשׁ מֵאוֹת בְּשָׁוֶה וְיִסְתַּלֵּק בַּעַל הַמָּנֶה וְחוֹזְרִין וְחוֹלְקִין הַמָּאתַיִם בֵּין הַשְּׁנַיִם בְּשָׁוֶה וְיִסְתַּלֵּק בַּעַל הַמָּאתַיִם. וְנוֹתְנִין הַמֵּאָה הַנִּשְׁאָרִים לְבַעַל הַשְּׁלֹשׁ מֵאוֹת וְנִמְצָא בְּיָדוֹ שְׁלֹשׁ מֵאוֹת בִּלְבַד. וְעַל דֶּרֶךְ זוֹ חוֹלְקִין אֲפִלּוּ הֵן מֵאָה כְּשֶׁיָּבוֹאוּ לִגְבּוֹת כְּאַחַת. וְיֵשׁ מִן הַגְּאוֹנִים שֶׁהוֹרוּ שֶׁחוֹלְקִין לְפִי מָמוֹנָם:","רְאוּבֵן וְשִׁמְעוֹן לְכָל אֶחָד מִשְּׁנֵיהֶם שְׁטַר חוֹב עַל לֵוִי רְאוּבֵן שְׁטָרוֹ בַּחֲמִישִׁי בְּנִיסָן וְשִׁמְעוֹן שְׁטָרוֹ בְּנִיסָן סְתָם וַהֲרֵי יֵשׁ לְלֵוִי שָׂדֶה שֶׁאֵינָהּ כְּדֵי חוֹב שֶׁל שְׁנֵיהֶם מוֹרִידִין לְתוֹכָהּ רְאוּבֵן שֶׁמָּא שְׁטָרוֹ שֶׁל שִׁמְעוֹן בְּסוֹף נִיסָן הָיָה. וְכֵן אֵין שִׁמְעוֹן יָכוֹל לִטְרֹף מֵאִיָּר וְאֵילָךְ שֶׁהֲרֵי הַלּוֹקֵחַ אוֹמֵר לוֹ שֶׁמָּא בְּאֶחָד בְּנִיסָן הוּא זְמַנּוֹ שֶׁל שְׁטָרְךָ וַהֲרֵי שָׂדֶה בַּת חוֹרִין בְּיַד רְאוּבֵן שֶׁתִּגְבֶּה אוֹתָהּ וְיָבוֹא רְאוּבֵן שֶׁהוּא אַחַר זְמַנְּךָ וְהוּא שֶׁיֵּשׁ לוֹ לִטְרֹף מִמֶּנּוּ. לְפִיכָךְ אִם כָּתְבוּ הַרְשָׁאָה זֶה לָזֶה טוֹרְפִין מֵאִיָּר וְאֵילָךְ מִכָּל צַד. וְהוּא הַדִּין בִּרְאוּבֵן וְשִׁמְעוֹן שֶׁמָּכַר לָהֶן לֵוִי שָׂדֶה אַחַת בִּשְׁנֵי שְׁטָרוֹת שְׁטָרוֹ שֶׁל זֶה בַּחֲמִשָּׁה בְּנִיסָן וּשְׁטָרוֹ שֶׁל זֶה בְּנִיסָן סְתָם:"],"Mishneh Torah, Creditor and Debtor 7":["הַמַּלְוֶה אֶת חֲבֵרוֹ וּמִשְׁכֵּן לוֹ אֶת הַשָּׂדֶה עַד זְמַן קָצוּב אוֹ עַד שֶׁיָּבִיא לוֹ מָעוֹת וְיִסְתַּלֵּק וְהָיָה הַמַּלְוֶה אוֹכֵל כָּל פֵּרוֹתֶיהָ אֲפִלּוּ אָכַל כְּשִׁעוּר חוֹבוֹ אֵין מְסַלְּקִין אוֹתוֹ בְּלֹא כְּלוּם שֶׁאִם תְּסַלֵּק אוֹתוֹ בְּלֹא מָעוֹת הֲרֵי זֶה כְּמִי שֶׁהוֹצִיא מִמֶּנּוּ בְּדַיָּנִין. וְאֵין צָרִיךְ לוֹמַר שֶׁאִם אָכַל יֶתֶר עַל מְעוֹתָיו אֵין מוֹצִיאִין מִמֶּנּוּ. וְכֵן אֵין מְחַשְּׁבִין מִשְּׁטָר לִשְׁטָר בְּמַשְׁכּוֹנָא. הָיְתָה הַקַּרְקַע הַמְמֻשְׁכֶּנֶת בְּיָדוֹ שֶׁל יְתוֹמִים וְאָכַל שִׁעוּר חוֹבוֹ מְסַלְּקִין אוֹתוֹ בְּלֹא כְּלוּם. אֲבָל יֶתֶר עַל חוֹבוֹ אֵין מוֹצִיאִין מִמֶּנּוּ הַיֶּתֶר. וּמְחַשְּׁבִין לוֹ מִשְּׁטָר לִשְׁטָר. כֵּיצַד מְחַשְּׁבִין מִשְּׁטָר לִשְׁטָר. הֲרֵי שֶׁהָיְתָה שָׂדֶה זוֹ מְמֻשְׁכֶּנֶת לוֹ בְּמֵאָה דִּינָר וְשָׂדֶה אַחֶרֶת מְמֻשְׁכֶּנֶת לוֹ בִּשְׁטָר אַחֵר בְּמֵאָה דִּינָר וּשְׁתֵּי הַשָּׂדוֹת לְאָדָם אֶחָד וְאָכַל מִפֵּרוֹת הַשָּׂדֶה הָאַחַת בַּחֲמִשִּׁים וּמִפֵּרוֹת הַשְּׁנִיָּה בְּמֵאָה וַחֲמִשִּׁים אוֹמְרִים לוֹ הֲרֵי אָכַלְתָּ מִן הַפֵּרוֹת בְּמָאתַיִם וְאֵין לְךָ כְּלוּם וּכְאִלּוּ הַשְּׁנֵי שְׁטָרוֹת שְׁטָר אֶחָד וּמַשְׁכּוֹנָא אַחַת:","מָקוֹם שֶׁנָּהֲגוּ לְסַלֵּק הַמַּלְוֶה כָּל זְמַן שֶׁיָּבִיא לוֹ מָעוֹת הֲרֵי זֶה כְּמוֹ שֶׁפֵּרֵשׁ וְאֵין צָרִיךְ לְפָרֵשׁ דָּבָר זֶה. וְכֵן מָקוֹם שֶׁנָּהֲגוּ שֶׁלֹּא יִסְתַּלֵּק הַמַּלְוֶה עַד סוֹף זְמַן הַמַּשְׁכּוֹנָא הֲרֵי זֶה כְּמוֹ שֶׁפֵּרֵשׁ. וְכָל הַמְמַשְׁכֵּן סְתָם אֵינוֹ יָכוֹל לְסַלְּקוֹ עַד שְׁנֵים עָשָׂר חֹדֶשׁ:","מָקוֹם שֶׁדַּרְכָּן לְסַלֵּק הַמַּלְוֶה כָּל זְמַן שֶׁיִּרְצֶה הַלּוֶֹה וְהִתְנָה עִמּוֹ הַמַּלְוֶה שֶׁלֹּא יִסְתַּלֵּק עַד סוֹף זְמַן הַמַּשְׁכּוֹנָא הֲרֵי זֶה אֵינוֹ יָכוֹל לְסַלְּקוֹ. הָיָה הַמִּנְהָג שֶׁאֵין הַמַּלְוֶה מִסְתַּלֵּק עַד סוֹף זְמַנּוֹ וְקִבֵּל הַמַּלְוֶה עָלָיו שֶׁיִּסְתַּלֵּק בְּכָל עֵת שֶׁיָּבִיא לוֹ מְעוֹתָיו הֲרֵי זֶה צָרִיךְ לִקְנוֹת מִיָּדוֹ עַל כָּךְ:","הַמַּשְׁכּוֹנָא בְּמָקוֹם שֶׁמִּנְהָגָם לְסַלֵּק הַמַּלְוֶה בְּכָל עֵת שֶׁיָּבִיא מְעוֹתָיו אֵין בַּעַל חוֹב שֶׁל מַלְוֶה גּוֹבֶה מִמֶּנָּה כְּדֶרֶךְ שֶׁגּוֹבֶה מִן הַקַּרְקַע. וְאֵין הַבְּכוֹר נוֹטֵל בָּהּ פִּי שְׁנַיִם. וּשְׁבִיעִית מְשַׁמַּטְתָּהּ. וּכְשֶׁמְּסַלֵּק אוֹתוֹ אֵינוֹ נוֹטֵל אֲפִלּוּ פֵּרוֹת שֶׁבָּשְׁלוּ וְנָפְלוּ לָאָרֶץ. וְאִם הִגְבִּיהַּ אוֹתָן קֹדֶם שֶׁיְּסַלְּקוּ קָנָה אוֹתָן. וּמָקוֹם שֶׁאֵינוֹ יָכוֹל לְסַלְּקוֹ עַד סוֹף זְמַנּוֹ בַּעַל חוֹב גּוֹבֶה הֵימֶנּוּ. וְהַבְּכוֹר נוֹטֵל פִּי שְׁנַיִם. וְאֵין הַשְּׁבִיעִית מְשַׁמַּטְתָּה:","אַף עַל פִּי שֶׁמַּשְׁכּוֹנָא זוֹ אֲסוּרָה הִיא וַאֲבַק רִבִּית כְּמוֹ שֶׁבֵּאַרְנוּ. אֶפְשָׁר שֶׁיִּהְיֶה מִנְהָג זֶה בְּטָעוּת אוֹ לָעַכּוּ\"ם אוֹ דֶּרֶךְ כָּל מִי שֶׁחוֹטֵא וּמִשְׁכֵּן בְּאוֹתָהּ מְדִינָה הוֹאִיל וַאֲבַק רִבִּית הוֹלְכִין אַחַר הַמִּנְהָג. וְיֵשׁ מִי שֶׁהוֹרָה שֶׁזֹּאת הַמַּשְׁכּוֹנָא בְּנִכּוּי:","עַכּוּ\"ם שֶׁמִּשְׁכֵּן חֲצֵרוֹ לְיִשְׂרָאֵל וְחָזַר הָעַכּוּ\"ם וּמְכָרָהּ לְיִשְׂרָאֵל אַחֵר אֵין הַמְמַשְׁכֵּן חַיָּב לְהַעֲלוֹת שָׂכָר לְיִשְׂרָאֵל מֵעֵת שֶׁקָּנָה הַיִּשְׂרָאֵל אֶלָּא דָּר בְּחָצֵר בְּלֹא שָׂכָר עַד שֶׁיַּחְזִיר לוֹ הָעַכּוּ\"ם אֶת הַמָּעוֹת שֶׁיֵּשׁ לוֹ עַל חָצֵר זוֹ שֶׁהֲרֵי הוּא בִּרְשׁוּת הַמְמַשְׁכֵּן בְּדִינֵיהֶם עַד שֶׁיִּתֵּן לוֹ מְעוֹתָיו וְיִסְתַּלֵּק:","הַמְמַשְׁכֵּן בַּיִת אוֹ שָׂדֶה בְּיַד חֲבֵרוֹ וְהָיָה בַּעַל הַקַּרְקַע אוֹכֵל פֵּרוֹתֶיהָ וְאָמַר לוֹ הַמַּלְוֶה לִכְשֶׁתִּמְכֹּר קַרְקַע זוֹ לֹא תִּמְכְּרֶנָּה אֶלָּא לִי בְּדָמִים אֵלּוּ הֲרֵי זֶה אָסוּר. וְאִם אָמַר לוֹ אַל תִּמְכְּרֶנָּה אֶלָּא לִי בְּשָׁוְיָהּ וְעַל מְנָת כֵּן אֲנִי מַלְוֶה אוֹתְךָ הֲרֵי זֶה מֻתָּר:","מֻתָּר לְהַרְבּוֹת בִּשְׂכַר הַקַּרְקַע. כֵּיצַד. הִשְׂכִּיר לוֹ אֶת הֶחָצֵר וְאָמַר לוֹ אִם מֵעַכְשָׁו אַתָּה נוֹתֵן לִי הֲרֵי הִיא לְךָ בְּעֶשֶׂר סְלָעִים בְּכָל שָׁנָה. וְאִם תִּתֵּן שְׂכַר חֹדֶשׁ בְּחֹדֶשׁ הֲרֵי הִיא בְּסֶלַע בְּכָל חֹדֶשׁ. הֲרֵי זֶה מֻתָּר:","הַמַּשְׂכִּיר שָׂדֶה לַחֲבֵרוֹ בַּעֲשָׂרָה כּוֹרִים לְשָׁנָה. וְאָמַר לוֹ תֵּן לִי מָאתַיִם זוּז שֶׁאֲפַרְנֵס בָּהֶן אֶת הַשָּׂדֶה וַאֲנִי אֶתֵּן לְךָ שְׁנֵים עָשָׂר כּוֹר בְּכָל שָׁנָה. הֲרֵי זֶה מֻתָּר מִפְּנֵי שֶׁאִם יְפַרְנֵס אֶת הַשָּׂדֶה בְּדִינָרִין אֵלּוּ יִהְיֶה שְׂכָרָהּ יוֹתֵר. וְכֵן אִם הִשְׂכִּיר לוֹ חֲנוּת אוֹ סְפִינָה בַּעֲשָׂרָה דִּינָרִין בְּשָׁנָה וְאָמַר לוֹ תֵּן לִי מָאתַיִם זוּז שֶׁאֶבְנֶה בָּהֶן חֲנוּת וַאֲצַיְּרֶנָּה וַאֲכַיְּרֶנָּה אוֹ אֲתַקֵּן בָּהֶן סְפִינָה זוֹ וּכְלֵי תַּשְׁמִישֶׁיהָ וַאֲנִי אַעֲלֶה לְךָ שְׁנֵים עָשָׂר דִּינָר בְּכָל שָׁנָה הֲרֵי זֶה מֻתָּר. אֲבָל אִם אָמַר לוֹ תֵּן לִי מָאתַיִם זוּז כְּדֵי לְהִתְעַסֵּק בָּהֶן בַּחֲנוּת אוֹ אוֹצִיאֵם בִּסְחוֹרָה שֶׁל סְפִינָה אוֹ אֶשְׂכֹּר בָּהֶן מַלָּחִין וַאֲנִי אַעֲלֶה לְךָ בְּשָׂכָר הֲרֵי זֶה אָסוּר:","אָסוּר לְהַרְבּוֹת בִּשְׂכַר הָאָדָם. כֵּיצַד. לֹא יֹאמַר לוֹ עֲשֵׂה עִמִּי הַיּוֹם מְלָאכָה זוֹ שֶׁהִיא שָׁוָה כֶּסֶף וַאֲנִי אֶעֱשֶׂה עִמְּךָ בְּשָׁבוּעַ אַחֵר מְלָאכָה שֶׁהִיא שָׁוָה שְׁתַּיִם:","מֻתָּר לָאָדָם לוֹמַר לַחֲבֵרוֹ נַכֵּשׁ עִמִּי הַיּוֹם וַאֲנַכֵּשׁ עִמְּךָ לְמָחָר עֲדֹר עִמִּי הַיּוֹם וְאֶעֱדֹר עִמְּךָ לְמָחָר. אֲבָל לֹא יֹאמַר לוֹ נַכֵּשׁ עִמִּי וְאֶעֱדֹר עִמְּךָ עֲדֹר עִמִּי וַאֲנַכֵּשׁ עִמְּךָ. כָּל יְמֵי גָּרִיד אֶחָד וְכָל יְמֵי רְבִיעָה אַחַת. וְלֹא יֹאמַר לוֹ חֲרשׁ עִמִּי בְּגָרִיד וַאֲנִי אֶחֱרשׁ עִמְּךָ בִּרְבִיעָה. שֶׁהֲרֵי טֹרַח הַחֲרִישָׁה בִּימוֹת הַגְּשָׁמִים יָתֵר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַשּׂוֹכֵר אֶת הַפּוֹעֵל בִּימֵי הַחֹרֶף לַעֲשׂוֹת עִמּוֹ בִּימֵי הַקֹּר בְּדִינָר בְּכָל יוֹם וְנָתַן לוֹ הַשָּׂכָר וַהֲרֵי שְׂכָרוֹ שָׁוֶה בִּימֵי הַחֹרֶף סֶלַע בְּכָל יוֹם הֲרֵי זֶה אָסוּר מִפְּנֵי שֶׁנִּרְאֶה כְּמַלְוֶה אוֹתוֹ הַיּוֹם כְּדֵי שֶׁיּוֹזִיל לוֹ בִּשְׂכָרוֹ. אֲבָל אִם אָמַר לוֹ עֲשֵׂה עִמִּי מֵהַיּוֹם וְעַד זְמַן פְּלוֹנִי בְּדִינָר בְּכָל יוֹם אַף עַל פִּי שֶׁשָּׁוֶה שְׂכָרוֹ סֶלַע בְּכָל יוֹם הֲרֵי זֶה מֻתָּר הוֹאִיל וְהוּא מַתְחִיל לַעֲשׂוֹת מֵעַתָּה אֵינוֹ נִרְאֶה כְּנוֹטֵל שְׂכַר מְעוֹתָיו שֶׁהִקְדִּים וּנְתָנָן לוֹ בִּשְׂכָרוֹ:"],"Mishneh Torah, Daily Offerings and Additional Offerings 9":["בְּאֶחָד בְּתִשְׁרֵי מַקְרִיבִין מוּסַף הַיּוֹם פַּר וְאַיִל וְשִׁבְעָה כְּבָשִׂים הַכּל עוֹלוֹת וּשְׂעִיר חַטָּאת הַנֶּאֱכֶלֶת. וְזֶה מוּסַף הַיּוֹם יֶתֶר עַל מוּסַף רֹאשׁ חֹדֶשׁ הַקָּרֵב בְּכָל רֹאשׁ חֹדֶשׁ. לְפִיכָךְ אִם חָל לִהְיוֹת בְּשַׁבָּת הָיוּ שָׁם שְׁלֹשָׁה מוּסָפִין מוּסַף שַׁבָּת וּמוּסַף רֹאשׁ חֹדֶשׁ וּמוּסַף הַיּוֹם:","וְכֵיצַד סִדּוּר הַקְרָבָתָן. מוּסַף שַׁבָּת תְּחִלָּה וְאַחֲרָיו מוּסַף הַחֹדֶשׁ וְאַחֲרָיו מוּסַף יוֹם טוֹב. שֶׁכָּל הַתָּדִיר מֵחֲבֵרוֹ קוֹדֵם אֶת חֲבֵרוֹ וְכֵן כָּל הַמְקֻדָּשׁ מֵחֲבֵרוֹ קוֹדֵם אֶת חֲבֵרוֹ. הָיָה לְפָנָיו תָּדִיר וּמְקֻדָּשׁ יַקְדִּים אֵיזֶה מֵהֶם שֶׁיִּרְצֶה:","עָבַר אוֹ שָׁכַח וְשָׁחַט אֶת שֶׁאֵינוֹ תָּדִיר אוֹ הַפָּחוּת בִּקְדֻשָּׁה תְּחִלָּה מַקְרִיבוֹ וְאַחַר כָּךְ שׁוֹחֵט אֶת הַתָּדִיר אוֹ אֶת הַמְקֻדָּשׁ:","וְאִם נִשְׁחֲטוּ שְׁנֵיהֶם כְּאֶחָד יִהְיֶה זֶה מְמָרֵס בַּדָּם עַד שֶׁיִּזְרֹק דַּם הַתָּדִיר אוֹ דַּם הַמְקֻדָּשׁ:","דַּם הַחַטָּאת קוֹדֵם לְדַם הָעוֹלָה מִפְּנֵי שֶׁדַּם הַחַטָּאת מְכַפֵּר. אֵיבְרֵי עוֹלָה קוֹדְמִין לְאֵימוּרֵי חַטָּאת מִפְּנֵי שֶׁהָעוֹלָה כֻּלָּהּ לָאִשִּׁים. דַּם חַטָּאת וְאֵיבְרֵי עוֹלָה אֵי זֶה שֶׁיִּרְצֶה יַקְדִּים. וְכֵן דַּם עוֹלָה וְאֵימוּרֵי חַטָּאת אוֹ דַּם עוֹלָה וְדַם אָשָׁם אֵי זֶה שֶׁיִּרְצֶה יַקְדִּים:","חַטָּאת קוֹדֶמֶת לְעוֹלָה אֲפִלּוּ חַטַּאת הָעוֹף קוֹדֶמֶת לְעוֹלַת בְּהֵמָה שֶׁנֶּאֱמַר (ויקרא ה ח) \"אֶת אֲשֶׁר לַחַטָּאת רִאשׁוֹנָה\" בִּנְיַן אָב לְכָל חַטָּאת שֶׁהִיא קוֹדֶמֶת לְעוֹלָה הַבָּא עִמָּהּ. וְכֵן בִּשְׁעַת הַפְרָשָׁה מַפְרִישׁ הַחַטָּאת תְּחִלָּה וְאַחַר כָּךְ הָעוֹלָה:","בְּקָרְבְּנוֹת הֶחָג אֵינוֹ כֵן אֶלָּא קְרֵבִין עַל סֵדֶר הַכָּתוּב שֶׁנֶּאֱמַר (במדבר כט ו) (במדבר כט לג) \"כְּמִשְׁפָּטָם\". כֵּיצַד. בַּתְּחִלָּה פָּרִים. וְאַחֲרֵיהֶם אֵילִים. וְאַחֲרֵיהֶם כְּבָשִׂים. וְאַחֲרֵיהֶם שְׂעִירִים. אַף עַל פִּי שֶׁהַשְּׂעִירִים חַטָּאת וְכָל אֵלּוּ שֶׁקָּדְמוּ אוֹתָן עוֹלוֹת. וְכֵן בְּשִׁגְגַת צִבּוּר בַּעֲבוֹדָה זָרָה שֶׁהֵן מְבִיאִין פַּר עוֹלָה וְשָׂעִיר חַטָּאת. הַפָּר קוֹדֵם שֶׁנֶּאֱמַר בּוֹ (במדבר טו כד) \"כַּמִּשְׁפָּט\". וּפַר כֹּהֵן מָשִׁיחַ קוֹדֵם לְפַר הֶעְלֵם דָּבָר שֶׁל צִבּוּר. וּפַר הֶעְלֵם קוֹדֵם לְפַר עֲבוֹדָה זָרָה. וּפַר עֲבוֹדָה זָרָה קוֹדֵם לְשָׂעִיר שֶׁלָּהּ. אַף עַל פִּי שֶׁהַפָּר עוֹלָה וְהַשָּׂעִיר חַטָּאת. שֶׁכָּךְ הוּא סֵדֶר הַכָּתוּב בַּתּוֹרָה. שְׂעִיר עֲבוֹדָה זָרָה קוֹדֵם לִשְׂעִיר נָשִׂיא שֶׁהַנָּשִׂיא יָחִיד. וּשְׂעִיר נָשִׂיא קוֹדֵם לִשְׂעִירַת יָחִיד. וּשְׂעִירַת יָחִיד קוֹדֶמֶת לְכַבְשָׂה. אַף עַל פִּי שֶׁשְּׁנֵיהֶם חַטָּאת. שֶׁהַשְּׂעִירָה רְאוּיָה לָבוֹא עַל הַכְּרֵתוֹת שֶׁמְּבִיאִין עֲלֵיהֶם חַטָּאת. וְהַכַּבְשָׂה אֵינָהּ בָּאָה עַל שִׁגְגַת עֲבוֹדָה זָרָה:","אֲפִלּוּ חַטַּאת הָעוֹף שֶׁל יוֹלֶדֶת קוֹדֶמֶת לְכַבְשָׂה. חַטָּאת קוֹדֶמֶת לְאָשָׁם מִפְּנֵי שֶׁדָּמָהּ נִתָּן עַל אַרְבַּע קְרָנוֹת וְעַל הַיְסוֹד. וְכָל חַטָּאוֹת שֶׁבַּתּוֹרָה קוֹדְמִין לְכָל הָאֲשָׁמוֹת. חוּץ מֵאֲשַׁם מְצֹרָע מִפְּנֵי שֶׁהוּא בָּא עַל יְדֵי הֶכְשֵר. הָאָשָׁם קוֹדֵם לְתוֹדָה וּלְאֵיל נָזִיר מִפְּנֵי שֶׁהוּא קָדְשֵׁי קָדָשִׁים. תּוֹדָה וְאֵיל נָזִיר קוֹדְמִין לִשְׁלָמִים מִפְּנֵי שֶׁהֵן נֶאֱכָלִין לְיוֹם אֶחָד וּטְעוּנִין לֶחֶם. וְהַתּוֹדָה קוֹדֶמֶת לְאֵיל נָזִיר מִפְּנֵי שֶׁיֵּשׁ בָּהּ אַרְבָּעָה מִינֵי מִנְחָה. שְׁלָמִים קוֹדְמִין לִבְכוֹר מִפְּנֵי שֶׁהֵן טְעוּנִין מַתַּן שְׁתַּיִם שֶׁהֵן כְּאַרְבַּע וּטְעוּנִין סְמִיכָה וּתְנוּפָה וּנְסָכִים. הַבְּכוֹר קוֹדֵם לְמַעְשַׂר בְּהֵמָה מִפְּנֵי שֶׁקְּדֻשָּׁתוֹ מֵרֶחֶם וְנֶאֱכָל לַכֹּהֲנִים בִּלְבַד. הַמַּעֲשֵׂר קוֹדְמִין לְעוֹפוֹת מִפְּנֵי שֶׁהוּא זֶבַח וְיֵשׁ בּוֹ קָדְשֵׁי קָדָשִׁים דָּמוֹ וְאֵימוּרָיו. וְהָעוֹפוֹת קוֹדְמִין לִמְנָחוֹת מִפְּנֵי שֶׁהֵן מִינֵי דָּמִים. הֲרֵי שֶׁהָיוּ לְפָנָיו חַטַּאת הָעוֹף וּמַעֲשֵׂר. הַמַּעֲשֵׂר קוֹדֵם מִפְּנֵי שֶׁהוּא זֶבַח. הָיוּ שָׁם חַטַּאת הָעוֹף וּמַעֲשֵׂר וְעוֹלַת בְּהֵמָה הוֹאִיל וְעוֹלָה קוֹדֶמֶת לְמַעֲשֵׂר וְחַטַּאת הָעוֹף קוֹדֶמֶת לְעוֹלַת בְּהֵמָה מַקְרִיב חַטַּאת הָעוֹף תְּחִלָּה וְאַחַר כָּךְ הָעוֹלָה וְאַחַר כָּךְ הַמַּעֲשֵׂר:","הֲרֵי שֶׁהָיוּ מִינֵי בְּהֵמָה הַרְבֵּה מִמִּין קָרְבָּן אֶחָד כֵּיצַד הֵן קְרֵבִין. הַפָּרִים קוֹדְמִין לְאֵילִים שֶׁכֵּן נִתְרַבּוּ בִּנְסָכִים. וְאֵילִים קוֹדְמִין לִכְבָשִׂים שֶׁכֵּן נִתְרַבּוּ בִּנְסָכִים. וּכְבָשִׂים קוֹדְמִין לִשְׂעִירִים שֶׁכֵּן נִתְרַבּוּ בְּאֵימוּרִים. שֶׁבִּכְלַל אֵימוּרֵי כְּבָשִׂים הָאַלְיָה וְאֵין בִּשְׂעִירִים אַלְיָה. הָעֹמֶר קוֹדֵם לַכֶּבֶשׂ הַבָּא עִמּוֹ. וּשְׁתֵּי הַלֶּחֶם קוֹדְמִין לִשְׁנֵי כְּבָשִׂים. זֶה הַכְּלָל דָּבָר הַבָּא בִּגְלַל הַיּוֹם קוֹדֵם לְדָבָר הַבָּא בִּגְלַל הַלֶּחֶם:","מִנְחַת הָאִישׁ קוֹדֶמֶת לְמִנְחַת הָאִשָּׁה. מִנְחַת חִטִּים קוֹדֶמֶת לְמִנְחַת שְׂעוֹרִים. מִנְחַת חוֹטֵא קוֹדֶמֶת לְמִנְחַת נְדָבָה מִפְּנֵי שֶׁהִיא בָּאָה עַל חֵטְא. מִנְחַת נְדָבָה וּמִנְחַת סוֹטָה אֵי זוֹ שֶׁיִּרְצֶה מֵהֶם יַקְדִּים:","מְנָחוֹת קוֹדְמִין לַיַּיִן. וְהַיַּיִן קוֹדֵם לַשֶּׁמֶן. וְהַשֶּׁמֶן קוֹדֵם לַלְּבוֹנָה. וּלְבוֹנָה קוֹדֶמֶת לַמֶּלַח. וּמֶלַח קוֹדֵם לָעֵצִים. אֵימָתַי בִּזְמַן שֶׁבָּאוּ כֻּלָּן כְּאֶחָד. אֲבָל הַבָּא רִאשׁוֹן קָרֵב רִאשׁוֹן וְהַבָּא אַחֲרוֹן קָרֵב אַחֲרוֹן:","כָּל הַקּוֹדֵם בְּהַקְרָבָה קוֹדֵם בַּאֲכִילָה:","הָיוּ לְפָנָיו שְׁלָמִים שֶׁל אֶמֶשׁ וּשְׁלָמִים שֶׁל יוֹם. שֶׁל אֶמֶשׁ קוֹדְמִין שֶׁהֲרֵי קָרַב זְמַנָּן. שְׁלָמִים שֶׁל אֶמֶשׁ וְחַטָּאת אוֹ אָשָׁם שֶׁל יוֹם. חַטָּאת וְאָשָׁם קוֹדְמִין מִפְּנֵי שֶׁהֵן קָדְשֵׁי קָדָשִׁים כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Damages to Property 7":["שׁוֹר שֶׁקְּשָׁרוֹ בְּעָלָיו בְּמוֹסֵרָה וְנָעַל בְּפָנָיו כָּרָאוּי וְיָצָא וְהִזִּיק. אִם תָּם הוּא מְשַׁלֵּם חֲצִי נֵזֶק. וְאִם הָיָה מוּעָד פָּטוּר שֶׁנֶּאֱמַר (שמות כא לו) \"וְלֹא יִשְׁמְרֶנּוּ\" הָא אִם שְׁמָרוֹ פָּטוּר וְשָׁמוּר הוּא זֶה. וְכֵן אִם הִזִּיק בְּדָבָר שֶׁהוּא מוּעָד לוֹ מִתְּחִלָּתוֹ כְּגוֹן שֶׁאָכַל דְּבָרִים הָרְאוּיִים לוֹ אוֹ שָׁבַר בְּרַגְלָיו בְּדֶרֶךְ הִלּוּכוֹ פָּטוּר מִלְּשַׁלֵּם:","הָיָה מוּעָד לְקֶרֶן יָמִין וְאֵינוֹ מוּעָד לְקֶרֶן שְׂמֹאל וְיָצָא אַחַר שֶׁשְּׁמָרוֹ כָּרָאוּי וְנָגַח בֵּין בְּקֶרֶן יָמִין בֵּין בִּשְׂמֹאל מְשַׁלֵּם חֲצִי נֵזֶק:","בְּהֵמָה שֶׁחָבְלָה בְּאָדָם בֵּין בְּכַוָּנָה בֵּין שֶׁלֹּא בְּכַוָּנָה. אִם תַּמָּה הִיא מְשַׁלֵּם חֲצִי נֵזֶק מִגּוּפָהּ וְאִם מוּעֶדֶת הִיא מְשַׁלֵּם נֵזֶק שָׁלֵם. וּפָטוּר מִן הַשֶּׁבֶת וּמִן הַבּשֶׁת וּמִן הַצַּעַר וּמִן הָרִפּוּי. שֶׁאַרְבָּעָה דְּבָרִים אֵלּוּ לֹא חִיְּבָה בָּהֶן תּוֹרָה אֶלָּא בְּאָדָם שֶׁחָבַל בַּחֲבֵרוֹ אֲבָל בְּהֵמָה שֶׁחָבְלָה בָּאָדָם הֲרֵי זֶה כְּמִי שֶׁהִזִּיקָה מָמוֹנוֹ שֶׁאֵינוֹ חַיָּב אֶלָּא חֲצִי נֵזֶק בִּלְבַד. לְפִיכָךְ שׁוֹרוֹ שֶׁבִּיֵּשׁ פָּטוּר וְאִם בִּיֵּשׁ הוּא בְּעַצְמוֹ חַיָּב כְּמוֹ שֶׁיִּתְבָּאֵר. וְשׁוֹרוֹ שֶׁחָבַל בְּאָבִיו אוֹ בְּאִמּוֹ אוֹ שֶׁהִדְלִיק גְּדִישׁ חֲבֵרוֹ בְּשַׁבָּת חַיָּב בִּנְזָקִין וְאִלּוּ הָיָה הוּא בְּעַצְמוֹ הָעוֹשֶׂה זֶה פָּטוּר מִלְּשַׁלֵּם כְּמוֹ שֶׁיִּתְבָּאֵר:","הַמַּכְנִיס שׁוֹרוֹ לַחֲצַר בַּעַל הַבַּיִת שֶׁלֹּא בִּרְשׁוּת וּנְגָחוֹ שׁוֹרוֹ שֶׁל בַּעַל הַבַּיִת אוֹ נְשָׁכוֹ כַּלְבּוֹ פָּטוּר. וְאִם נָגַח הוּא שׁוֹר שֶׁל בַּעַל הַבַּיִת. אִם הָיָה תָּם מְשַׁלֵּם חֲצִי נֵזֶק וְאִם הָיָה מוּעָד מְשַׁלֵּם נֵזֶק שָׁלֵם כְּדִין הַנּוֹגֵחַ בִּרְשׁוּת הָרַבִּים:","נָפַל לְבוֹר שֶׁבְּחָצֵר זוֹ וְהִבְאִישׁ אֶת מֵימָיו. אִם הִבְאִישׁ אֶת מֵימָיו מִיָּד בִּשְׁעַת נְפִילָה חַיָּב בְּנִזְקֵי הַמַּיִם. וְאִם אַחַר זְמַן פָּטוּר. שֶׁהֲרֵי נַעֲשָׂה הַשּׁוֹר תַּקָּלָה כְּבוֹר וְהַמַּיִם הֲרֵי הֵן כְּכֵלִים וְלֹא מָצִינוּ בּוֹר שֶׁחִיֵּב בּוֹ אֶת הַכֵּלִים. וְאִם הִכְנִיס בִּרְשׁוּת בַּעַל הַשּׁוֹר פָּטוּר. וְאִם קִבֵּל עָלָיו בַּעַל הַבַּיִת לִשְׁמֹר הֲרֵי הוּא חַיָּב בְּנֵזֶק הַשּׁוֹר שֶׁנָּפַל לַבּוֹר:","הִכְנִיס שׁוֹרוֹ לַחֲצַר בַּעַל הַבַּיִת שֶׁלֹּא בִּרְשׁוּת וְהִזִּיק אֶת בַּעַל הַבַּיִת. אוֹ שֶׁהֻזַּק בּוֹ בַּעַל הַבַּיִת. אוֹ שֶׁחָפַר בֶּחָצֵר בּוֹרוֹת שִׁיחִין וּמְעָרוֹת. בַּעַל הַשּׁוֹר חַיָּב בְּנִזְקֵי חָצֵר וּבַעַל חָצֵר חַיָּב בְּנִזְקֵי הַבּוֹר שֶׁהֲרֵי עָלָיו לְסָתְמוֹ:","הִזִּיק בַּעַל הַבַּיִת אֶת הַשּׁוֹר. אִם הִזִּיקוֹ שֶׁלֹּא לְדַעַת פָּטוּר. שֶׁהֲרֵי אוֹמְרִין לוֹ לָמָּה נִכְנַסְתָּ שֶׁלֹּא בִּרְשׁוּת. שֶׁלֹּא יָדַעְתִּי עַד שֶׁשָּׁגַגְתִּי בְּךָ. וְאִם הִזִּיקוֹ לְדַעַת חַיָּב נֵזֶק שָׁלֵם. מִפְּנֵי שֶׁיֵּשׁ לוֹ רְשׁוּת לְהוֹצִיאוֹ מֵרְשׁוּתוֹ אֲבָל לְהַזִּיקוֹ אֵין לוֹ רְשׁוּת:","שָׁמִין לִנְזָקִין. כֵּיצַד. הֲרֵי שֶׁשָּׁבַר כְּלִי שֶׁל חֲבֵרוֹ בֵּין הוּא בֵּין בְּהֶמְתּוֹ אֵין אוֹמְרִין לַמַּזִּיק קַח אַתָּה הַכְּלִי הַשָּׁבוּר וְשַׁלֵּם לָזֶה דְּמֵי הַכְּלִי אֶלָּא אוֹמְדִין כַּמָּה פָּחַת הַכְּלִי מִדָּמָיו וְנוֹתֵן לוֹ כָּל הַפְּחָת אִם הַמַּזִּיק מוּעָד אוֹ חֲצִי הַפְּחָת אִם הָיָה תָּם שֶׁנֶּאֱמַר (שמות כא לד) \"וְהַמֵּת יִהְיֶה לּוֹ\" לַנִּזָּק. פְּחַת הַנְּבֵלָה עַל הַנִּזָּק. וְשֶׁבַח הַנְּבֵלָה חוֹלְקִין אוֹתוֹ הַנִּזָּק וְהַמַּזִּיק:","כֵּיצַד. שׁוֹר שָׁוֵה מָאתַיִם שֶׁנְּגָחוּהוּ וּמֵת וַהֲרֵי הַנְּבֵלָה שָׁוָה בִּשְׁעַת מִיתָה מֵאָה וּבִשְׁעַת הַעֲמָדָה בַּדִּין פָּחֲתָה וַהֲרֵי שָׁוָה שְׁמוֹנִים. אֵין הַמַּזִּיק מְשַׁלֵּם אֶלָּא מֵאָה אִם הָיָה מוּעָד. וְאִם הָיָה תָּם מְשַׁלֵּם לוֹ חֲמִשִּׁים מִגּוּפוֹ:","הִשְׁבִּיחָה הַנְּבֵלָה וַהֲרֵי הִיא שָׁוָה בִּשְׁעַת הַעֲמָדָה בַּדִּין מֵאָה וְעֶשְׂרִים. הֲרֵי הַמַּזִּיק מְשַׁלֵּם לוֹ תִּשְׁעִים אִם הָיָה מוּעָד. וְאִם הָיָה תָּם מְשַׁלֵּם אַרְבָּעִים וַחֲמִשָּׁה מִגּוּפוֹ וְזֶהוּ שֶׁנֶּאֱמַר (שמות כא לה) \"וְגַם אֶת הַמֵּת יֶחֱצוּן\" [שֶׁבַח הַמֵּת יֶחֱצוּן]:","שׁוֹר שָׁוֶה מָאתַיִם שֶׁנָּגַח שׁוֹר שָׁוֶה מָאתַיִם וְהִפְחִיתוֹ חֲמִשִּׁים וּבִשְׁעַת הַעֲמָדָה בַּדִּין הִשְׁבִּיחַ הַנִּזָּק וַהֲרֵי הוּא שָׁוֶה אַרְבַּע מֵאוֹת זוּז וְאִלּוּלֵא הַנְּגִיחָה שֶׁהִפְחִיתוֹ הָיָה שָׁוֶה שְׁמוֹנֶה מֵאוֹת. בֵּין שֶׁפִּטְּמוֹ בֵּין שֶׁשִּׁבֵּחַ מֵאֵלָיו אֵין נוֹתֵן אֶלָּא כִּשְׁעַת הַנֵּזֶק. כִּחֵשׁ מֵחֲמַת הַמַּכָּה בִּשְׁעַת הַעֲמָדָה בַּדִּין וַהֲרֵי הַפְּחָת שָׁוֶה מֵאָה נוֹתֵן לוֹ כִּשְׁעַת הַעֲמָדָה בַּדִּין:","הִשְׁבִּיחַ הַמַּזִּיק בִּשְׁעַת הַעֲמָדָה בַּדִּין. אִם מֵחֲמַת שֶׁפִּטְּמוֹ שִׁבֵּחַ אֵינוֹ מִשְׁתַּלֵּם מִמֶּנּוּ אֶלָּא מַה שֶּׁהָיָה שָׁוֶה בְּשָׁעָה שֶׁהִזִּיק. וְאִם מֵחֲמַת עַצְמוֹ הִשְׁבִּיחַ מִשְׁתַּלֵּם חֲצִי נֵזֶק מִמֶּנּוּ כֻּלּוֹ כִּשְׁעַת הַעֲמָדָה בַּדִּין:","עַל הַמַּזִּיק לִטְרֹחַ בַּנְּבֵלָה עַד שֶׁמַּמְצִיא אוֹתָהּ לַנִּזָּק. כֵּיצַד. כְּגוֹן שֶׁנָּפַל הַשּׁוֹר לַבּוֹר וּמֵת מַעֲלֶה הַנְּבֵלָה מִן הַבּוֹר וְנוֹתְנָהּ לַנִּזָּק וְאַחַר כָּךְ שָׁמִין לוֹ פְּחַת נְבֵלָה שֶׁנֶּאֱמַר (שמות כא לד) \"כֶּסֶף יָשִׁיב לִבְעָלָיו וְהַמֵּת יִהְיֶה לּוֹ\". מְלַמֵּד שֶׁהוּא חַיָּב לְהָשִׁיב אֶת הַנְּבֵלָה וְאֶת הַפְּחָת שֶׁפָּחֲתָה מִן הַחַי לַנִּזָּק. וְאִם הָיָה תָּם חֲצִי הַפְּחָת. כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Defilement by Leprosy 3":["אֵין הַמִּחְיָה סִימַן טֻמְאָה עַד שֶׁתִּהְיֶה כַּעֲדָשָׁה מְרֻבַּעַת אוֹ יֶתֶר עַל זֶה. וְכַמָּה שִׁעוּרָהּ כְּדֵי צְמִיחַת אַרְבַּע שְׂעָרוֹת שְׁתַּיִם אֹרֶךְ וּשְׁתַּיִם רֹחַב. וְהוּא שֶׁתִּהְיֶה הַמִּחְיָה בְּאֶמְצַע הַבַּהֶרֶת וְהַבַּהֶרֶת מַקֶּפֶת אוֹתָהּ מִכָּל צַד וְהִיא יְתֵרָה עַל הַמִּחְיָה רֹחַב שְׁתֵּי שְׂעָרוֹת אוֹ יֶתֶר. אֲבָל אִם הָיְתָה הַמִּחְיָה בְּצַד הַבַּהֶרֶת אֵינָהּ סִימַן טֻמְאָה. הָיְתָה מְפֻזֶּרֶת כְּגוֹן שֶׁהָיָה בָּשָׂר חַי כְּחַרְדָּל בְּמָקוֹם זֶה וּבָשָׂר חַי כְּחַרְדָּל בְּמָקוֹם אַחֵר אַף עַל פִּי שֶׁהַכּל בְּאֶמְצַע הַבַּהֶרֶת אֵינָן מִצְטָרְפִין לְכַעֲדָשָׁה. עַד שֶׁיִּהְיֶה בְּמָקוֹם אֶחָד בְּאֶמְצַע הַבַּהֶרֶת כַּעֲדָשָׁה מְרֻבָּע אוֹ יֶתֶר:","הַמִּחְיָה מְטַמְּאָה בְּכָל מַרְאֶה בֵּין שֶׁהָיָה מַרְאֵה הַמִּחְיָה אָדֹם אוֹ שָׁחֹר אוֹ לָבָן וְהוּא שֶׁלֹּא יִהְיֶה הַלֹּבֶן מֵאַרְבַּע הַמַּרְאוֹת שֶׁבֵּאַרְנוּ:","אֵין הַמִּחְיָה סִימַן טֻמְאָה עַד שֶׁתִּהְיֶה בְּגוּפָהּ שֶׁל בַּהֶרֶת. כֵּיצַד. בַּהֶרֶת שֶׁהָיְתָה בְּאֶמְצַע שְׁחִין אוֹ מִכְוָה אוֹ מִחְיָה אוֹ בֹּהַק. וְהַמִּחְיָה בְּתוֹךְ הַשְּׁחִין אוֹ בְּתוֹךְ הַמִּכְוָה אוֹ בְּתוֹךְ מִחְיָתָן אוֹ בְּתוֹךְ הַבֹּהַק. אַף עַל פִּי שֶׁהַמִּחְיָה בְּאֶמְצַע הַבַּהֶרֶת אֵינָהּ סִימַן טֻמְאָה מִפְּנֵי שֶׁהִיא בְּתוֹךְ הַשְּׁחִין אוֹ הַמִּכְוָה אוֹ בְּתוֹךְ הַבֹּהַק אוֹ מִחְיָתָן. וְכֵן אִם הִקִּיף הַשְּׁחִין אֶת מִחְיָתוֹ וְהַמִּכְוָה אֶת מִחְיָתָהּ וְהַבֹּהַק אֶת הַמִּחְיָה אוֹ שֶׁנִּסְמַךְ אֶחָד מֵהֶן לַמִּחְיָה מִצִּדָּהּ אוֹ שֶׁחָלַק אֶחָד מֵהֶן אֶת הַמִּחְיָה וְנִכְנַס לְתוֹכָהּ אֵינָהּ סִימַן טֻמְאָה וַהֲרֵי זוֹ כְּבַהֶרֶת שֶׁאֵין בָּהּ סִימָן וְיַסְגִּיר. הָלְכוּ לָהֶן הַשְּׁחִין אוֹ הַמִּכְוָה אוֹ הַבֹּהַק שֶׁהָיָה תַּחַת הַמִּחְיָה שֶׁהָיוּ בְּצִדָּהּ אוֹ שֶׁהָיוּ מַקִּיפִין אוֹ שֶׁהָיוּ נִכְנָסִין לְתוֹכָהּ וְנִמְצֵאת הַמִּחְיָה לְבַדָּהּ בְּתוֹךְ הַבַּהֶרֶת בְּסוֹף שָׁבוּעַ רִאשׁוֹן אוֹ בְּסוֹף שָׁבוּעַ שֵׁנִי הֲרֵי זֶה יַחְלִיט. אִם לֹא הָלְכוּ לָהֶן יִפְטֹר:","הַמִּחְיָה סִימַן טֻמְאָה לְעוֹלָם בֵּין שֶׁקָּדְמָה מִחְיָה אֶת הַבַּהֶרֶת בֵּין שֶׁקָּדְמָה בַּהֶרֶת אֶת הַמִּחְיָה לְפִי שֶׁלֹּא נֶאֱמַר בָּהּ וְהִיא הָפְכָה. זֶה שֶׁנֶּאֱמַר בַּתּוֹרָה (ויקרא יג י) \"וְהִיא הָפְכָה שֵׂעָר לָבָן וּמִחְיַת בָּשָׂר חַי בַּשְּׂאֵת\" אֵינוֹ צָרִיךְ לִשְׁנֵיהֶן לְשֵׂעָר וּלְמִחְיָה אֶלָּא כָּל אֶחָד מֵהֶן סִימַן טֻמְאָה. וְלֹא נֶאֱמַר שֵׂעָר לָבָן עִם הַמִּחְיָה אֶלָּא לִתֵּן שִׁעוּר לְמִחְיָה שֶׁתִּהְיֶה כְּדֵי לְקַבֵּל שֵׂעָר לָבָן שֶׁהוּא שְׁתֵּי שְׂעָרוֹת:","בַּהֶרֶת כִּגְרִיס מְצֻמְצָם וּבְאֶמְצָעָהּ מִחְיָה כַּעֲדָשָׁה מְצֻמְצֶמֶת הֲרֵי זֶה מֻחְלָט. נִתְמַעֲטָה הַבַּהֶרֶת אוֹ שֶׁנִּתְמַעֲטָה הַמִּחְיָה טָהוֹר וְכֵן אִם רָבְתָה הַמִּחְיָה שֶׁבְּתוֹךְ בַּהֶרֶת זוֹ טָהוֹר שֶׁאֵין הַבַּהֶרֶת מְטַמָּא בְּמִחְיָה עַד שֶׁתִּהְיֶה יְתֵרָה עַל הַמִּחְיָה רֹחַב שְׁתֵּי שְׂעָרוֹת מִכָּל צַד. הָיְתָה הַמִּחְיָה פְּחוּתָה מִכַּעֲדָשָׁה וְרָבְתָה הַמִּחְיָה עַד שֶׁנַּעֲשֵׂית כַּעֲדָשָׁה הֲרֵי זֶה מֻחְלָט. נִתְמַעֲטָה הַמִּחְיָה מִמַּה שֶּׁהָיְתָה אוֹ שֶׁהָלְכָה לָהּ הֲרֵי זוֹ כְּמוֹת שֶׁהָיְתָה וְאֵין כָּאן סִימַן טֻמְאָה:","בַּהֶרֶת יְתֵרָה מִכִּגְרִיס וּבָהּ מִחְיָה יְתֵרָה מִכַּעֲדָשָׁה וְרַבּוּ אוֹ שֶׁנִּתְמַעֲטוּ טָמֵא. וּבִלְבַד שֶׁלֹּא יִתְמַעֵט בַּהֶרֶת מִכִּגְרִיס וְלֹא תִּתְמַעֵט הַמִּחְיָה מִכַּעֲדָשָׁה וְלֹא תִּקְרַב הַמִּחְיָה לְסוֹף הַבַּהֶרֶת בְּפָחוֹת מִכְּדֵי צְמִיחַת שְׁתֵּי שְׂעָרוֹת כְּמוֹ שֶׁבֵּאַרְנוּ:","בַּהֶרֶת כִּגְרִיס וּבָשָׂר חַי כַּעֲדָשָׁה אוֹ יֶתֶר מַקִּיפָהּ מִבַּחוּץ וּבַהֶרֶת שְׁנִיָּה מַקֶּפֶת אֶת הַבָּשָׂר הַחַי. הֲרֵי הַבַּהֶרֶת הַפְּנִימִית לְהַסְגִּיר שֶׁהֲרֵי אֵין בָּהּ סִימַן טֻמְאָה וּבַהֶרֶת הַחִיצוֹנָה לְהַחְלִיט שֶׁהֲרֵי הַמִּחְיָה בְּאֶמְצָעָהּ. נִתְמַעֵט הַבָּשָׂר הַחַי שֶׁבֵּינֵיהֶן אוֹ שֶׁהָלַךְ כֻּלּוֹ בֵּין שֶׁהָיָה מִתְמַעֵט וְכָלֶה מִבִּפְנִים בֵּין שֶׁהָיָה מִתְמַעֵט מִבַּחוּץ הֲרֵי שְׁתֵּיהֶן כְּבַהֶרֶת אַחַת שֶׁאֵין בָּהּ סִימַן טֻמְאָה:","בַּהֶרֶת שֶׁהָיְתָה בְּרֹאשׁ אֵיבָר מִן הָאֵיבָרִים וְהַמִּחְיָה בְּאֶמְצַע הַבַּהֶרֶת בְּרֹאשׁ הָאֵבָר אֵינָהּ סִימַן טֻמְאָה מִפְּנֵי שֶׁהַמִּחְיָה חוֹלֶקֶת אֶת הַנֶּגַע וְנִמְצָא מִקְצָתוֹ שׁוֹפֵעַ וְיוֹרֵד מִכָּאן וּמִקְצָתוֹ שׁוֹפֵעַ וְיוֹרֵד מִכָּאן וְנֶאֱמַר בִּנְגָעִים וְרָאָהוּ הַכֹּהֵן שֶׁיִּהְיֶה רוֹאֶה הַנֶּגַע כֻּלּוֹ כְּאַחַת. וְאֵלּוּ הֵן רָאשֵׁי אֵיבָרִים שֶׁאֵינָם מִטַּמְּאִין בְּמִחְיָה. רָאשֵׁי אֶצְבְּעוֹת יָדַיִם וְרַגְלַיִם וְרָאשֵׁי אָזְנַיִם וְרֹאשׁ הַחֹטֶם וְרֹאשׁ הָעֲטָרָה וְרָאשֵׁי דָּדִין שֶׁל אִשָּׁה. אֲבָל רָאשֵׁי דָּדִין שֶׁל אִישׁ וְהַיִּבּוֹלֶת וְהַדִּלְדּוּלִין מִטַּמְּאִין בְּמִחְיָה:","וְכָל רָאשֵׁי אֵיבָרִים אֵלּוּ שֶׁהָיָה מְקוֹמָן יוֹשֵׁב כִּגְרִיס מִטַּמְּאִין בִּנְגָעִים. אֲבָל אִם הָיוּ עֲגֻלִּין כְּרֹב בְּרִיַּת בְּנֵי אָדָם טְהוֹרִין. כֵּיצַד. בַּהֶרֶת כִּגְרִיס בְּרֹאשׁ חָטְמוֹ אוֹ בְּרֹאשׁ אֶצְבָּעוֹ שׁוֹפַעַת אֵילָךְ וְאֵילָךְ טָהוֹר שֶׁנֶּאֱמַר וְרָאָהוּ הַכֹּהֵן עַד שֶׁיִּרְאֵהוּ כֻּלּוֹ כְּאַחַת:"],"Mishneh Torah, Defilement by a Corpse 14":["אֵין טֻמְאָה נִכְנֶסֶת לְאֹהֶל וְלֹא יוֹצְאָה מִמֶּנּוּ בְּפָחוֹת מטֶּפַח עַל טֶפַח. כֵּיצַד. חַלּוֹן שֶׁבֵּין בַּיִת לְבַיִת אוֹ שֶׁבֵּין בַּיִת לַעֲלִיָּה. אִם יֵשׁ בּוֹ טֶפַח עַל טֶפַח מְרֻבָּע וְהָיְתָה טֻמְאָה בְּאֶחָד מֵהֶן הַבַּיִת הַשֵּׁנִי טָמֵא. אֵין בַּחַלּוֹן פּוֹתֵחַ טֶפַח אֵין הַטֻּמְאָה יוֹצְאָה מִמֶּנּוּ וְלֹא נִכְנֶסֶת לָאֹהֶל הַשֵּׁנִי. בַּמֶּה דְּבָרִים אֲמוּרִים בְּחַלּוֹן שֶׁעָשָׂה אוֹתוֹ הָאָדָם לְתַשְׁמִישׁ. אֲבָל חַלּוֹן שֶׁעָשָׂה אוֹתוֹ הָאָדָם לְאוֹרָה כְּדֵי שֶׁיִּכָּנֵס מִמֶּנּוּ הָאוֹר שִׁעוּרוֹ כְּפוּנְדְיוֹן וְהַטֻּמְאָה יוֹצְאָה מִמֶּנּוּ. כֵּיצַד. הָיְתָה טֻמְאָה בַּבַּיִת וּבָא אָדָם וְנִסְמַךְ לְחַלּוֹן זֶה שֶׁל מָאוֹר אוֹ שֶׁהִנִּיחַ בּוֹ כְּלִי אוֹ שֶׁהֶאֱהִיל עָלָיו אֹהֶל בְּצַד הַכֹּתֶל נִטְמָא כָּל שֶׁבְּאֹהֶל שֶׁהַטֻּמְאָה יוֹצְאָה לוֹ. וְחַלּוֹן הֶעָשׂוּי לְאוֹרָה הוּא שֶׁאֵין עָלָיו תִּקְרָה אֶלָּא גָּלוּי הוּא לַשֶּׁמֶשׁ:","חַלּוֹן הַנַּעֲשֶׂה שֶׁלֹּא בִּידֵי אָדָם כְּגוֹן שֶׁחָרְרוּהוּ מַיִם אוֹ שְׁרָצִים אוֹ שֶׁאֲכָלַתּוּ מְלַחַת אוֹ שֶׁהָיָה חַלּוֹן פָּקוּק וְנִטַּל הַפְּקָק אוֹ שֶׁהָיְתָה בּוֹ זְכוּכִית וְנִשְׁבְּרָה שִׁעוּרוֹ מְלֹא אֶגְרוֹף וְהוּא כְּרֹאשׁ גָּדוֹל שֶׁל אָדָם. וְהוּא שֶׁלֹּא חָשַׁב עָלָיו לְתַשְׁמִישׁ אֲבָל אִם חָשַׁב עָלָיו לְתַשְׁמִישׁ שִׁעוּרוֹ בְּפוֹתֵחַ טֶפַח. חָשַׁב עָלָיו לְמָאוֹר שִׁעוּרוֹ בְּפוּנְדְיוֹן שֶׁהַמַּחְשָׁבָה כָּאן כְּמַעֲשֶׂה:","מָאוֹר שֶׁהִתְחִיל לְסָתְמוֹ וְלֹא הִסְפִּיק לְגָמְרוֹ מִפְּנֵי שֶׁלֹּא הָיָה לוֹ טִיט אוֹ שֶׁקְּרָאוֹ חֲבֵרוֹ אוֹ שֶׁחָשְׁכָה לֵילֵי שַׁבָּת וְנִשְׁאַר מִמֶּנּוּ מְעַט. אִם נִשְׁאַר מִמֶּנּוּ רוּם אֶצְבָּעַיִם עַל רֹחַב הַגּוּדָל מֵבִיא אֶת הַטֻּמְאָה. פָּחוֹת מִכָּאן הֲרֵי הוּא כְּסָתוּם:","חַלּוֹן גָּדוֹל הֶעָשׂוּי לְאוֹרָה וְהָיָה בָּהּ שְׂבָכָה וְכַיּוֹצֵא בָּהּ. אִם יֵשׁ שָׁם בְּמָקוֹם אֶחָד מִמֶּנָּה כְּפוּנְדְיוֹן מֵבִיא אֶת הַטֻּמְאָה וּמוֹצִיא אֶת הַטֻּמְאָה. הָיוּ נִקְבֵי הַשְּׂבָכָה דַּקִּים וְאֵין בְּאֶחָד מֵהֶן כְּפוּנְדְיוֹן הֲרֵי זוֹ כִּסְתוּמָה. וְכֵן חַלּוֹן הָעֲשׂוּיָה לְתַשְׁמִישׁ וּבָהּ סְכָכוֹת וּרְפָפוֹת אִם יֵשׁ בְּמָקוֹם אֶחָד טֶפַח עַל טֶפַח מְרֻבָּע מֵבִיא וּמוֹצִיא וְאִם לָאו הֲרֵי הִיא כִּסְתוּמָה:","חַלּוֹן שֶׁהִיא גְּלוּיָה לָאֲוִיר שִׁעוּרָהּ כְּפוּנְדְיוֹן מִפְּנֵי שֶׁאֵינָהּ עֲשׂוּיָה אֶלָּא לְאוֹרָה כְּמוֹ שֶׁאָמַרְנוּ. בָּנָה בַּיִת חוּצָה לָהּ וְנַעֲשֵׂית חַלּוֹן זוֹ תַּחַת תִּקְרָה וַהֲרֵי הִיא בֵּין שְׁנֵי בָּתִּים שִׁעוּרָהּ בְּפוֹתֵחַ טֶפַח. נָתַן אֶת הַתִּקְרָה בְּאֶמְצַע הַחַלּוֹן הַתַּחְתּוֹן שֶׁתַּחַת הַתִּקְרָה שִׁעוּרוֹ בְּפוֹתֵחַ טֶפַח. וְהָעֶלְיוֹן שֶׁלְּמַעְלָה מִן הַתִּקְרָה שִׁעוּרוֹ כְּפוּנְדְיוֹן מִפְּנֵי שֶׁהוּא גָּלוּי לָאֲוִיר:","הַחֹר שֶׁבַּדֶּלֶת אוֹ שֶׁשִּׁיֵּר בָּהּ הֶחָרָשׁ מָקוֹם פָּתוּחַ מִלְּמַעְלָה אוֹ מִלְּמַטָּה אוֹ שֶׁהֵגִיף אֶת הַדֶּלֶת וְלֹא גָּמַר לְהַדְּקָהּ וְנִשְׁאַר אֲוִיר בֵּין שְׁתֵּי הַדְּלָתוֹת. אוֹ שֶׁסָּגַר הַדֶּלֶת וּפְתָחוֹ הָרוּחַ. בְּכָל אֵלּוּ אִם הָיָה הַפּוֹתֵחַ כְּאֶגְרוֹף הַטֻּמְאָה יוֹצְאָה מִמֶּנּוּ וְנִכְנֶסֶת לָהּ בְּמָקוֹם פָּתוּחַ זֶה. וְאִם הָיָה פָּחוֹת מִכְּאֶגְרוֹף הֲרֵי הוּא כְּסָתוּם:","הָעוֹשֶׂה חֹר בַּכֹּתֶל כְּדֵי לְהַנִּיחַ בּוֹ קָנֶה אוֹ מַסְמֵר גָּדוֹל אוֹ לִרְאוֹת מִמֶּנּוּ הָעוֹבְרִים וְהַשָּׁבִים אוֹ לְדַבֵּר עִם חֲבֵרוֹ. הֲרֵי זֶה כְּחַלּוֹן הָעֲשׂוּיָה לְתַשְׁמִישׁ וְשִׁעוּרָהּ בְּפוֹתֵחַ טֶפַח:"],"Mishneh Torah, Defilement by a Corpse 25":["עַמּוּד הָעוֹמֵד בְּתוֹךְ הַבַּיִת וְטֻמְאָה רְצוּצָה תַּחְתָּיו. טֻמְאָה בּוֹקַעַת וְעוֹלָה בּוֹקַעַת וְיוֹרֶדֶת. וְאֵינוֹ מְטַמֵּא אֶלָּא כְּנֶגֶד הַטֻּמְאָה בִּלְבַד. וְאִם הָיָה פֶּרַח יוֹצֵא מֵעַמּוּד זֶה וְכֵלִים תַּחַת הַפֶּרַח הַכֵּלִים טְהוֹרִים שֶׁאֵינוֹ מְטַמֵּא אֶלָּא כְּנֶגֶד הַטֻּמְאָה:","[וְאִם יֵשׁ בִּמְקוֹם הַטֻּמְאָה] טֶפַח עַל טֶפַח עַל רוּם טֶפַח הֲרֵי הוּא כְּקֶבֶר סָתוּם וּמְטַמֵּא מִכָּל סְבִיבָיו. וְהַבַּיִת כֻּלּוֹ טָמֵא שֶׁהֲרֵי הֶאֱהִיל עַל הַקֶּבֶר:","טֻמְאָה שֶׁבְּתוֹךְ הַכֹּתֶל וּמְקוֹמָהּ טֶפַח עַל טֶפַח עַל רוּם טֶפַח כָּל הָעֲלִיּוֹת הַבְּנוּיוֹת עַל כֹּתֶל זֶה אֲפִלּוּ עֶשֶׂר טְמֵאוֹת. שֶׁהֲרֵי הַכֹּתֶל כֻּלּוֹ קֶבֶר סָתוּם עַד סוֹפוֹ וְהוּא כֹּתֶל הָעֲלִיּוֹת וְכָל עֲלִיָּה מֵהֶן מַאֲהֶלֶת עַל הַקֶּבֶר. בָּנָה בַּיִת בְּצַד הַכֹּתֶל מִכָּאן וּבַיִת מִכָּאן וּבָנָה עֲלִיָּה עַל גַּבֵּי שְׁנֵי הַבָּתִּים עַד שֶׁנִּמְצָא רֹאשׁ הַכֹּתֶל הַטָּמֵא הוּא בְּאֶמְצַע קַרְקַע הָעֲלִיָּה. הֲרֵי הָעֲלִיָּה טְמֵאָה שֶׁהֲרֵי הֶאֱהִילָה עַל הַקֶּבֶר. וְהָעֲלִיָּה הַשְּׁנִיָּה הַבְּנוּיָה עַל גַּבָּהּ טְהוֹרָה מִפְּנֵי שֶׁהֵן זוֹ עַל גַּבֵּי זוֹ וְאֵין הַכֹּתֶל הַטָּמֵא כָּתְלָהּ:","חֹר גָּדוֹל שֶׁבָּעֳבִי הַכְּתָלִים שֶׁדֶּרֶךְ בְּנֵי אָדָם לַעֲשׂוֹתוֹ לְתַשְׁמִישׁ. וְהוּא הַנִּקְרָא פַּרְדַּסִּיק. שֶׁהָיְתָה טֻמְאָה מֻנַּחַת בְּתוֹכוֹ וְיֵשׁ עָלָיו דְּלָתוֹת סְגוּרוֹת. הַבַּיִת טָהוֹר. הָיְתָה הַטֻּמְאָה רְצוּצָה בְּקַרְקָעִיתוֹ אוֹ בִּכְתָלָיו אוֹ בְּגַגּוֹ רוֹאִין אֶת כָּל הַחֹר כֻּלּוֹ כְּאִלּוּ הוּא אָטוּם וְרוֹאִין מְקוֹם הַטֻּמְאָה אִם הוּא בַּחֲצִי עֳבִי הַכֹּתֶל שֶׁלְּפָנִים הַבַּיִת טָמֵא. וְאִם הָיְתָה טֻמְאָה מֵחֲצִי כֹּתֶל וְלַחוּץ הַבַּיִת טָהוֹר. מֶחֱצָה לְמֶחֱצָה הַבַּיִת טָמֵא:","שְׁנֵי פַּרְדַּסְקִין זֶה בְּצַד זֶה אוֹ זֶה עַל גַּב זֶה וְטֻמְאָה מֻנַּחַת בְּאַחַת מֵהֶן וְנִפְתַּח. הוּא וְהַבַּיִת טָמֵא וַחֲבֵרוֹ טָהוֹר. הָיְתָה טֻמְאָה רְצוּצָה בְּתוֹךְ הַבִּנְיָן רוֹאִין אֶת הַפַּרְדַּסְקִין כְּאִלּוּ הֵן אֲטוּמִין וְיִדּוֹן מֶחֱצָה לְמֶחֱצָה:","כְּזַיִת מִן הַמֵּת מֻדְבָּק בְּאַסְקֻפַּת הַבַּיִת מִבַּחוּץ הַבַּיִת טָהוֹר. הָיָה רָצוּץ תַּחַת הָאַסְקֻפָּה יִדּוֹן מֶחֱצָה לְמֶחֱצָה. הָיָה מֻדְבָּק לַמַּשְׁקוֹף הַבַּיִת טָמֵא:","כֶּלֶב שֶׁאָכַל בְּשַׂר הַמֵּת וּמֵת בְּתוֹךְ שְׁלֹשָׁה יָמִים וַהֲרֵי הוּא מֻטָּל עַל הָאַסְקֻפָּה רוֹאִין חֲלַל הַטֻּמְאָה מִגּוּפוֹ אִם הוּא כְּנֶגֶד הַמַּשְׁקוֹף וְלִפְנִים הַבַּיִת טָמֵא וּמִכְּנֶגֶד הַמַּשְׁקוֹף וְלַחוּץ הַבַּיִת טָהוֹר:","הָאִשָּׁה שֶׁמֵּת עֵבָּרָהּ בְּתוֹךְ מֵעֶיהָ אִם נַעֲשֵׂית רֹאשׁ הַנֵּפֶל כְּפִיקָה שֶׁל שְׁתִי כֵּיוָן שֶׁנִּפְתַּח הָרֶחֶם עַד שֶׁנִּרְאֶה הָרֹאשׁ נִטְמָא הַבַּיִת מִפְּנֵי הָעֻבָּר אַף עַל פִּי שֶׁעֲדַיִן לֹא יָצָא:","הָאִשָּׁה שֶׁמַּקְשָׁה לֵילֵד וְיָצְאָה מִבַּיִת לְבַיִת וְהִפִּילָה נֵפֶל מֵת בְּבַיִת שֵׁנִי הַבַּיִת הָרִאשׁוֹן טָמֵא בְּסָפֵק. שֶׁמָּא כְּשֶׁהָיְתָה בּוֹ יָצָא רֹאשׁוֹ שֶׁל נֵפֶל הַזֶּה. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁלֹּא הָיָה רֹאשׁ הַנֵּפֶל כְּפִיקָה שֶׁל שְׁתִי. אֲבָל אִם הֶעֱגֵיל רֹאשׁ הַנֵּפֶל כְּפִיקָה הַבַּיִת הָרִאשׁוֹן טָהוֹר שֶׁאִלּוּ נִפְתַּח רַחְמָהּ שָׁם לֹא הָיְתָה יְכוֹלָה לְהַלֵּךְ עַל רַגְלֶיהָ. לְפִיכָךְ אִם הָיְתָה נִטֶּלֶת בַּאֲגַפַּיִים וְהוֹצִיאוּהָ מִבַּיִת לְבַיִת הַבַּיִת הָרִאשׁוֹן טָמֵא בְּסָפֵק אַף עַל פִּי שֶׁהֶעֱגֵיל רֹאשׁ הַנֵּפֶל כְּפִיקָה שֶׁל שְׁתִי:","הָאִשָּׁה שֶׁהִפִּילָה שִׁלְיָא הַבַּיִת טָמֵא וַדַּאי. חֲזָקָה הוּא שֶׁאֵין שִׁלְיָא בְּלֹא וָלָד:","מִי שֶׁיָּלְדָה שְׁנֵי יְלָדִים אֶחָד חַי וְאֶחָד מֵת. אִם הַמֵּת יָצָא רִאשׁוֹן הַחַי טָהוֹר שֶׁהֲרֵי לֹא נָגַע בּוֹ מִשֶּׁיָּצָא לַאֲוִיר הָעוֹלָם. וְאִם הַחַי יָצָא רִאשׁוֹן הֲרֵי הוּא טָמֵא שֶׁהֲרֵי אִי אֶפְשָׁר שֶׁלֹּא יִגַּע בּוֹ הַמֵּת מִשֶּׁיֵּצֵא לַאֲוִיר הָעוֹלָם מִפְּנֵי שֶׁהוּא מִתְגַּלְגֵּל אַחֲרָיו כְּאֶבֶן שֶׁאֵין בּוֹ רוּחַ חַיִּים כְּדֵי לְהַעֲמִיד עַצְמוֹ:","הָאִשָּׁה שֶׁיָּלְדָה וָלָד מֵת אֲפִלּוּ נֵפֶל קָטָן כְּמוֹ שֶׁבֵּאַרְנוּ הֲרֵי הִיא טְמֵאָה טֻמְאַת ז'. מֵת עֻבָּרָהּ בְּתוֹךְ מֵעֶיהָ וּפָשְׁטָה הַחַיָּה אֶת יָדָהּ וְנָגְעָה בּוֹ הַחַיָּה טְמֵאָה ז' וְהָאִשָּׁה טְהוֹרָה עַד שֶׁיֵּצֵא הַוָּלָד. וְטֻמְאַת הַחַיָּה מִדִּבְרֵיהֶם גְּזֵרָה שֶׁמָּא תִּגַּע בּוֹ מִשֶּׁיֵּצֵא לַפְּרוֹזְדוֹר. אֲבָל מִן הַתּוֹרָה אֵין מַגַּע בֵּית הַסְּתָרִים מַגָּע הוֹאִיל וְהוּא בְּתוֹךְ הַמֵּעַיִם הַנּוֹגֵעַ בּוֹ טָהוֹר. וְכֵן הַבּוֹלֵעַ טַבַּעַת טְמֵאָה וְחָזַר וּבָלַע אַחֲרֶיהָ טַבַּעַת טְהוֹרָה אַף עַל פִּי שֶׁנָּגְעוּ זוֹ בָּזוֹ בְּוַדַּאי בְּתוֹךְ מֵעָיו אֵינוֹ מַגָּע וְהַטֻּמְאָה בְּטֻמְאָתָהּ וּטְהוֹרָה בְּטָהֳרָתָהּ: סְלִיקוּ לְהוּ הִלְכוֹת טֻמְאַת מֵת"],"Mishneh Torah, Defilement of Foods 13":["הַמְמַלֵא בַּקִּילוֹן הַמַּיִם הַנִּשְׁאָרִים בַּקִּילוֹן הֲרֵי הֵן תְּלוּשִׁין בְּרָצוֹן עַד שְׁלֹשָׁה יָמִים אֲבָל אַחַר שְׁלֹשָׁה יָמִים אֵינָן תְּלוּשִׁין בְּרָצוֹן אֶלָּא אִם נִשְׁאַר שָׁם מַשְׁקֶה אֵינוֹ מַכְשִׁיר:","עֵצִים שֶׁנָּפְלוּ עֲלֵיהֶן מַשְׁקִין בְּרָצוֹן וְיָרְדוּ עֲלֵיהֶן גְּשָׁמִים שֶׁלֹּא לְרָצוֹן אִם רַבּוּ הֲרֵי כֻּלָּן שֶׁלֹּא לְרָצוֹן. הוֹצִיאָן שֶׁיֵּרְדוּ עֲלֵיהֶן גְּשָׁמִים אַף עַל פִּי שֶׁרַבּוּ הֲרֵי כֻּלָּן לְרָצוֹן. הָיוּ רַגְלָיו אוֹ רַגְלֵי בְּהֶמְתּוֹ מְלֵאוֹת טִיט וְעָבַר בַּנָּהָר וְרָחֲצוּ אִם שָׂמַח הֲרֵי הַמַּיִם הָעוֹלִין עֲלֵיהֶן תְּלוּשִׁין בְּרָצוֹן וְאִם לָאו אֵינָן בְּרָצוֹן:","הַמּוֹרִיד אֶת הַגַּלְגַּלִּים וְאֶת כְּלֵי הַבָּקָר בִּשְׁעַת הַקָּדִים לַמַּיִם כְּדֵי שֶׁיִּסָּתְמוּ הַסְּדָקִין שֶׁבָּעֵץ הֲרֵי הַמַּיִם הָעוֹלִין בָּהֶן תְּלוּשִׁין בְּרָצוֹן:","הַמּוֹרִיד אֶת הַבְּהֵמָה לִשְׁתּוֹת הַמַּיִם הָעוֹלִין בְּפִיהָ תְּלוּשִׁין בְּרָצוֹן וּבְרַגְלֶיהָ אֵינָן כִּתְלוּשִׁין בְּרָצוֹן אֶלָּא אִם חִשֵּׁב שֶׁיּוּדְחוּ רַגְלֶיהָ. וּבִשְׁעַת הַחֹרֶף וְהַדַּיִשׁ אַף שֶׁבְּרַגְלֶיהָ תְּלוּשִׁין בְּרָצוֹן. הוֹרִידָהּ חֵרֵשׁ שׁוֹטֶה וְקָטָן אַף עַל פִּי שֶׁחָשַׁב שֶׁיּוּדְחוּ רַגְלֶיהָ הַמַּיִם הָעוֹלִין בְּרַגְלֶיהָ אֵינָן תְּלוּשִׁין בְּרָצוֹן שֶׁיֵּשׁ לָהֶן מַעֲשֶׂה וְאֵין לָהֶן מַחֲשָׁבָה:","הַטּוֹבֵל בְּמַיִם הֲרֵי כָּל הַמַּיִם שֶׁעַל בְּשָׂרוֹ תְּלוּשִׁין בְּרָצוֹן. אֲבָל הָעוֹבֵר בְּמַיִם כָּל הַמַּיִם שֶׁעַל בְּשָׂרוֹ אֵינָן תְּלוּשִׁין בְּרָצוֹן:","מִי שֶׁטָּבַל בַּנָּהָר וְהָיָה לְפָנָיו נָהָר אַחֵר וְעָבַר בּוֹ בִּטְּלוּ הַשְּׁנִיִּים אֶת הָרִאשׁוֹנִים וַהֲרֵי הַמַּיִם שֶׁעָלָיו אֵינָן תְּלוּשִׁין בְּרָצוֹן. וְכֵן אִם דָּחָהוּ חֲבֵרוֹ לִשַׁבְּרוֹ אוֹ לִשַׁבֵּר בְּהֶמְתּוֹ בָּטְלוּ הַמַּיִם הָרִאשׁוֹנִים. אֲבָל אִם דָּחָהוּ דֶּרֶךְ שְׂחוֹק לֹא בָּטְלוּ אֶלָּא הֲרֵי הַמַּיִם שֶׁעָלָיו תְּלוּשִׁין לְרָצוֹן. טָבַל בַּנָּהָר וְעָלָה וְיָרְדוּ עָלָיו גְּשָׁמִים אִם רַבּוּ עָלָיו גְּשָׁמִים הֲרֵי בָּטְלוּ מַיִם הָרִאשׁוֹנִים וַהֲרֵי כָּל הַמַּיִם שֶׁעָלָיו אֵינָן תְּלוּשִׁין בְּרָצוֹן:","הַשָּׁט עַל פְּנֵי הַמַּיִם הַמַּיִם הַנִּתָּזִין אֵינָן תְּלוּשִׁין בְּרָצוֹן. וְהַמַּיִם הָעוֹלִין עָלָיו תְּלוּשִׁין בְּרָצוֹן. אִם נִתְכַּוֵּן לְהַתִּיז עַל חֲבֵרוֹ אַף הַנִּתָּזִין תְּלוּשִׁין בְּרָצוֹן:","הָעוֹשֶׂה צִפּוֹר בַּמַּיִם הַמַּיִם הַנִּתָּזִין וְאֶת שֶׁבָּהּ אֵינָם תְּלוּשִׁין בְּרָצוֹן:","הַמּוֹדֵד אֶת הַבּוֹר לֵידַע עָמְקוֹ מַיִם הָעוֹלִין בְּיָדוֹ וּבַדָּבָר שֶׁמָּדַד בּוֹ תְּלוּשִׁין בְּרָצוֹן. וְאִם מָדַד רָחְבּוֹ מַיִם הָעוֹלִין בְּיָדָיו אוֹ בְּדָבָר שֶׁמָּדַד בּוֹ אֵינָן תְּלוּשִׁין בְּרָצוֹן. פָּשַׁט יָדוֹ אוֹ רַגְלוֹ לַבּוֹר לֵידַע אִם יֵשׁ בּוֹ מַיִם הֲרֵי הַמַּיִם הָעוֹלִין בְּיָדוֹ אוֹ בְּרַגְלוֹ אֵינָן תְּלוּשִׁין בְּרָצוֹן. פְּשָׁטָן לֵידַע כַּמָּה מַיִם שָׁם הָעוֹלִין בָּהֶן תְּלוּשִׁין בְּרָצוֹן. זָרַק אֶבֶן לַבּוֹר לֵידַע אִם יֵשׁ בּוֹ מַיִם מַיִם הַנִּתָּזִין אֵינָן בְּרָצוֹן וְשֶׁעַל הָאֶבֶן אֵינָן כִּתְלוּשִׁין:","הַחוֹבֵט עַל הַשֶּׁלַח חוּץ לַמַּיִם הַנִּתָּזִין מִמֶּנּוּ תְּלוּשִׁין בְּרָצוֹן שֶׁהֲרֵי רְצוֹנוֹ שֶׁיֵּצְאוּ. חָבַט עָלָיו וְהוּא בְּתוֹךְ הַמַּיִם אֵינָן תְּלוּשִׁין בְּרָצוֹן:","הַמַּיִם הָעוֹלִין בַּסְּפִינָה וּבָעֶקֶל וּבַמְּשׁוֹטוֹת אֵינָן תְּלוּשִׁין בְּרָצוֹן. וּבַמְּצוּדוֹת וּבָרְשָׁתוֹת וּבַמִּכְמוֹרוֹת אֵינָם תְּלוּשִׁין בְּרָצוֹן. וְאִם נִעֵר תְּלוּשִׁין בְּרָצוֹן. וְכֵן הַמַּיִם שֶׁעַל הַקַּסְיָה [שֶׁל] שֻׁלְחָנוֹת וְעַל הַשָּׂפָה שֶׁל לְבֵנִים אֵינָן בְּרָצוֹן. וְאִם נִעֵר הֲרֵי אֵלּוּ בְּרָצוֹן:","הַמּוֹלִיךְ אֶת הַסְּפִינָה לַיָּם הַגָּדוֹל לְצָרְפָהּ. הַמּוֹצִיא מַסְמֵר לַגְּשָׁמִים לְצָרְפוֹ. הַמַּנִּיחַ אֶת הָאוּד בַּגְּשָׁמִים לַעֲשׂוֹתוֹ [פֶּחָם]. הֲרֵי הַמַּיִם שֶׁעֲלֵיהֶן תְּלוּשִׁין בְּרָצוֹן. אֲבָל הַמּוֹצִיא אֶת הַמַּסְמֵר וְאֶת הָאוּד לַגְּשָׁמִים לְכַבּוֹתָן אֵין הַמַּיִם שֶׁעֲלֵיהֶן תְּלוּשִׁין בְּרָצוֹן:","שִׁלְשֵׁל אֶת הַמְּשׁוֹלֶת לַבּוֹר לְהַעֲלוֹת בָּהּ כְּלִי אוֹ קִיתוֹן. שִׁלְשֵׁל אֶת הַכַּלְכָּלָה לַבּוֹר כְּדֵי שֶׁתֵּשֵׁב עָלֶיהָ (אֶת) הַתַּרְנְגלֶת. אֵין הַמַּיִם שֶׁעָלֶיהָ תְּלוּשִׁין בְּרָצוֹן:","הַמְמַחֵק אֶת הַכְּרֵישָׁה לְהָסִיר הַמַּיִם שֶׁעָלֶיהָ וְהַסּוֹחֵט שְׂעָרוֹ בִּכְסוּתוֹ הַמַּיִם הַיּוֹצְאִין תְּלוּשִׁין בְּרָצוֹן. וְהַנִּשְׁאָרִין אֵינָן תְּלוּשִׁין בְּרָצוֹן מִפְּנֵי שֶׁרְצוֹנוֹ שֶׁיֵּצְאוּ מִכֻּלָּן. וּכְרֵישָׁה עַצְמָהּ הֻכְשְׁרָה שֶׁבִּשְׁעַת פְּרִישָׁתָהּ מַכְשִׁירִין. וְאִם נִתֵּק הַמַּיִם מֵעָלֶיהָ בְּכָל כֹּחוֹ לֹא הֻכְשְׁרָה:","הַמַּרְעִיד אֶת הָאִילָן לְהַשִּׁיר מִמֶּנּוּ אֳכָלִין אוֹ לְהַשִּׁיר טֻמְאָה הַמַּיִם הַנִּתָּזִין מִמֶּנָּה אֵינָן תְּלוּשִׁין בְּרָצוֹן. הִרְעִידוֹ לְהַשִּׁיר מִמֶּנּוּ מַשְׁקִין הַיּוֹצְאִין הֲרֵי הֵן תְּלוּשִׁין. וְהַנִּשְׁאָרִין בּוֹ אַף עַל פִּי שֶׁנָּשְׁרוּ מִמָּקוֹם לְמָקוֹם אֵינָן תְּלוּשִׁין בְּרָצוֹן. מִפְּנֵי שֶׁהוּא מִתְכַּוֵּן שֶׁיֵּצְאוּ מִכֻּלּוֹ. וְכֵן אִם נִתְּזוּ עַל הַמְחֻבָּרִין אֵינָן תְּלוּשִׁין בְּרָצוֹן:","הַמַּרְעִיד אֶת הָאִילָן וְנָפַל עַל חֲבֵרוֹ אוֹ סֻכָּה וְנָפְלָה עַל חֲבֶרְתָּהּ וְתַחְתֵּיהֶן זְרָעִים וִירָקוֹת מְחֻבָּרִים לַקַּרְקַע וְנָפְלוּ הַמַּיִם עַל הַפֵּרוֹת הַמְחֻבָּרִין שֶׁתַּחְתֵּיהֶן אוֹתָן הַמַּיִם שֶׁבַּזְּרָעִים וְשֶׁבַּיְרָקוֹת אֵינָן תְּלוּשִׁין בְּרָצוֹן:","שְׁמָרִים שֶׁל תְּרוּמָה שֶׁנָּתַן עֲלֵיהֶן מַיִם כְּבָר בֵּאַרְנוּ בִּתְרוּמוֹת שֶׁהָרִאשׁוֹן וְהַשֵּׁנִי אָסוּר לְזָרִים וְשֶׁל הֶקְדֵּשׁ בֶּדֶק הַבַּיִת אַף הַשְּׁלִישִׁי אָסוּר. וְשֶׁל קָדְשֵׁי מִזְבֵּחַ לְעוֹלָם אָסוּר. וְשֶׁל מַעֲשֵׂר שֵׁנִי הַוַּדַּאי רִאשׁוֹן בִּלְבַד אָסוּר. כְּשֵׁם שֶׁאָמְרוּ לְעִנְיַן אִסּוּרָן כָּךְ אָמְרוּ לְעִנְיַן הֶכְשֵׁרָן. כְּגוֹן שֶׁנִּתְמְדוּ מֵאֲלֵיהֶן וְהָיְתָה בְּהֵמָה שׁוֹתָה רִאשׁוֹן רִאשׁוֹן. שֶׁאִם הָיָה הָאָדָם הוּא שֶׁמֵּסִיר הַמַּיִם הָרִאשׁוֹנִים אַף עַל פִּי שֶׁמֵּאֲלֵיהֶן נָפְלוּ כֵּיוָן שֶׁחֲשָׁבָן וְהִקְפִּיד עֲלֵיהֶן מַכְשִׁירִין:"],"Mishneh Torah, Diverse Species 1":["הַזּוֹרֵעַ שְׁנֵי מִינֵי זְרָעִים כְּאֶחָד בְּאֶרֶץ יִשְׂרָאֵל לוֹקֶה שֶׁנֶּאֱמַר (ויקרא יט יט) \"שָׂדְךָ לֹא תִזְרַע כִּלְאָיִם\":","וְאֶחָד הַזּוֹרֵעַ אוֹ הַמְנַכֵּשׁ אוֹ הַמְחַפֶּה כְּגוֹן שֶׁהָיְתָה חִטָּה אַחַת וּשְׂעוֹרָה אַחַת אוֹ פּוֹל אֶחָד וַעֲדָשָׁה אַחַת מֻנָּחִין עַל הָאָרֶץ וְחִפָּה אוֹתָן בֶּעָפָר בֵּין בְּיָדוֹ בֵּין בְּרַגְלוֹ בֵּין בִּכְלִי הֲרֵי זֶה לוֹקֶה. וְאֶחָד הַזּוֹרֵעַ בָּאָרֶץ אוֹ בֶּעָצִיץ נָקוּב. אֲבָל הַזּוֹרֵעַ בֶּעָצִיץ שֶׁאֵינוֹ נָקוּב מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","אָסוּר לִזְרֹעַ כִּלְאַיִם לְנָכְרִי. וּמֻתָּר לוֹמַר לְנָכְרִי לִזְרֹעַ לוֹ כִּלְאֵי זְרָעִים. וְאָסוּר לְאָדָם לְקַיֵּם כִּלְאֵי זְרָעִים בְּשָׂדֵהוּ אֶלָּא עוֹקְרָן וְאִם קִיְּמָן אֵינוֹ לוֹקֶה. וּמֻתָּר לְיִשְׂרָאֵל לִזְרֹעַ כִּלְאֵי זְרָעִים בְּיָדוֹ בְּחוּצָה לָאָרֶץ וַאֲפִלּוּ לְעָרֵב הַזְּרָעִים לְכַתְּחִלָּה וּלְזָרְעָן בְּחוּצָה לָאָרֶץ מֻתָּר וּדְבָרִים אֵלּוּ דִּבְרֵי קַבָּלָה:","אֵין אָסוּר מִשּׁוּם כִּלְאֵי זְרָעִים אֶלָּא הַזְּרָעִים הָרְאוּיִין לְמַאֲכַל אָדָם. אֲבָל עֲשָׂבִים הַמָּרִים וְכַיּוֹצֵא בָּהֶן מִן הָעִקָּרִין שֶׁאֵינָן רְאוּיִין אֶלָּא לִרְפוּאָה וְכַיּוֹצֵא בָּהֶן אֵין בָּהֶן מִשּׁוּם כִּלְאֵי זְרָעִים:","כִּלְאֵי הָאִילָנוֹת הֲרֵי הֵם בִּכְלַל מַה שֶּׁנֶּאֱמַר (ויקרא יט יט) \"שָׂדְךָ לֹא תִזְרַע כִּלְאָיִם\". כֵּיצַד. הַמַּרְכִּיב אִילָן בָּאִילָן כְּגוֹן שֶׁהִרְכִּיב יִחוּר שֶׁל תַּפּוּחַ בְּאֶתְרוֹג אוֹ אֶתְרוֹג בְּתַפּוּחַ הֲרֵי זֶה לוֹקֶה מִן הַתּוֹרָה בְּכָל מָקוֹם בֵּין בָּאָרֶץ בֵּין בְּחוּצָה לָאָרֶץ. וְכֵן הַמַּרְכִּיב יָרָק בְּאִילָן אוֹ אִילָן בְּיָרָק לוֹקֶה בְּכָל מָקוֹם:","וְאָסוּר לְיִשְׂרָאֵל לְהָנִיחַ לְנָכְרִי שֶׁיַּרְכִּיב לוֹ אִילָנוֹת כִּלְאַיִם. וּמֻתָּר לִזְרֹעַ זְרָעִים וְזֶרַע אִילָן כְּאֶחָד וְכֵן מֻתָּר לְעָרֵב זַרְעֵי אִילָנוֹת וּלְזָרְעָן כְּאֶחָד שֶׁאֵין לְךָ כִּלְאַיִם בָּאִילָנוֹת אֶלָּא הַרְכָּבָה בִּלְבַד:","הַזּוֹרֵעַ זְרָעִים כִּלְאַיִם וְכֵן הַמַּרְכִּיב אִילָנוֹת כִּלְאַיִם אַף עַל פִּי שֶׁהוּא לוֹקֶה הֲרֵי אֵלּוּ מֻתָּרִין בַּאֲכִילָה וַאֲפִלּוּ לָזֶה שֶׁעָבַר וּזְרָעָן שֶׁלֹּא נֶאֱסַר אֶלָּא זְרִיעָתָן בִּלְבַד. וּמֻתָּר לִטַּע יִחוּר מִן הָאִילָן שֶׁהֻרְכַּב כִּלְאַיִם וְלִזְרֹעַ מִזֶּרַע הַיָּרָק שֶׁנִּזְרַע כִּלְאַיִם:","הַזֵּרְעוֹנִין נֶחֱלָקִין לִשְׁלֹשָׁה חֲלָקִים. הָאֶחָד מֵהֶם הוּא הַנִּקְרָא תְּבוּאָה וְהִיא חֲמִשָּׁה מִינִין הַחִטִּים וְהַכֻּסְּמִין וְהַשְּׂעוֹרִין וְשִׁבּלֶת שׁוּעָל וְהַשִּׁיפוֹן. וְהַשֵּׁנִי מֵהֶן הוּא הַנִּקְרָא קִטְנִית. וְהֵן כָּל זְרָעִים הַנֶּאֱכָל לְאָדָם חוּץ מִן הַתְּבוּאָה. כְּגוֹן הַפּוֹל וְהָאֲפוּנִים וְהָעֲדָשִׁים וְהַדֹּחַן וְהָאֹרֶז וְהַשֻּׁמְשְׁמִין וְהַפְּרָגִין וְהַסַּפִּיר וְכַיּוֹצֵא בָּהֶן. וְהַשְּׁלִישִׁי מֵהֶן הוּא הַנִּקְרָא זֵרְעוֹנֵי גִּנָּה. וְהֵן שְׁאָר זֵרְעוֹנִין שֶׁאֵינָן רְאוּיִין לְמַאֲכַל אָדָם. וְהַפְּרִי שֶׁל אוֹתוֹ הַזֶּרַע מַאֲכַל אָדָם. כְּגוֹן זֶרַע הַבְּצָלִים וְהַשּׁוּמִין וְזֶרַע הֶחָצִיר וְהַקֶּצַח וְזֶרַע לֶפֶת וְכַיּוֹצֵא בָּהֶן. וְזֶרַע פִּשְׁתָּן הֲרֵי הוּא בִּכְלַל זֵרְעוֹנֵי גִּנָּה. כְּשֶׁיִּזָרְעוּ כָּל מִינֵי זֵרְעוֹנִים אֵלּוּ וְיִצְמְחוּ נִקְרָא הַצֶּמַח כֻּלּוֹ כָּל זְמַן שֶׁלֹּא נִכָּר הַזֶּרַע דֶּשֶׁא וְנִקְרָא יֶרֶק:","וְיֵשׁ מִזֵּרְעוֹנֵי גִּנָּה זֵרְעוֹנִים שֶׁדַּרְכָּן לִזְרֹעַ מֵהֶן שָׂדוֹת כְּגוֹן הַפִּשְׁתָּן וְהַחַרְדָּל וְאֵלּוּ הֵן הַנִּקְרָאִים מִינֵי זְרָעִים. וְיֵשׁ מִזֵּרְעוֹנֵי גִּנָּה זֵרְעוֹנִים שֶׁאֵין דֶּרֶךְ בְּנֵי אָדָם לִזְרֹעַ מֵהֶם אֶלָּא עֲרוּגוֹת עֲרוּגוֹת קְטַנּוֹת כְּגוֹן הַלֶּפֶת וְהַצְּנוֹן וְהַתְּרָדִים וְהַבְּצָלִים וְהַכֻּסְבַּר וְהַכַּרְפַּס וְהַמָּרוֹר וְכַיּוֹצֵא בָּהֶן וְאֵלּוּ הֵן הַנִּקְרָאִים מִינֵי יְרָקוֹת:"],"Mishneh Torah, Divorce 11":["אֵין נוֹשְׂאִין אֶת הַקְּטנָּה. וְהַנּוֹשֵׂא קְטַנָּה יְתוֹמָה וְלֹא רָצְתָה בַּבַּעַל הֲרֵי זוֹ מְמָאֶנֶת וְהוֹלֶכֶת וְאֵינָהּ צְרִיכָה מִמֶּנּוּ גֵּט. שֶׁאֵין קִדּוּשִׁין שֶׁל קְטַנָּה קִדּוּשִׁין גְּמוּרִין כְּמוֹ שֶׁבֵּאַרְנוּ. וְכֵן קְטַנָּה שֶׁהִשִּׂיאָהּ אָבִיהָ וְנִתְאַלְמְנָה אוֹ נִתְגָּרְשָׁה כְּשֶׁהִיא קְטַנָּה הֲרֵי הִיא כִּיתוֹמָה בְּחַיֵּי אָבִיהָ. וְאִם נִשֵּׂאת כְּשֶׁהִיא קְטַנָּה הֲרֵי זוֹ מְמָאֶנֶת:","הַחֵרֶשֶׁת אַף עַל פִּי שֶׁנִּשּׂוּאֶיהָ מִדִּבְרֵי סוֹפְרִים כְּנִשּׂוּאֵי קְטַנָּה לֹא תִּקְּנוּ לָהּ שֶׁתְּמָאֵן כְּדֵי שֶׁלֹּא יִמָּנְעוּ מִלְּנָשְׂאָהּ:","מְמָאֶנֶת הִיא הַקְּטַנָּה בֵּין מִן הָאֵרוּסִין בֵּין מִן הַנִּשּׂוּאִין. בֵּין בִּפְנֵי בַּעְלָהּ בֵּין שֶׁלֹּא בְּפָנָיו. וּכְשֵׁם שֶׁמְּמָאֶנֶת בְּבַעַל כָּךְ מְמָאֶנֶת בְּיָבָם. וּמְמָאֶנֶת בְּבַעַל זֶה וּמְמָאֶנֶת בְּשֵׁנִי אִם נִשֵּׂאת לְאַחֵר וְכֵן בִּשְׁלִישִׁי אֲפִלּוּ כַּמָּה פְּעָמִים כָּל זְמַן שֶׁהִיא קְטַנָּה יֵשׁ לָהּ לְמָאֵן. וּקְטַנָּה שֶׁלֹּא מֵאֲנָה אַף עַל פִּי שֶׁהִיא נְשׂוּאָה וְהָלְכָה וְנִתְקַדְּשָׁה לְאַחֵר כְּשֶׁהִיא קְטַנָּה קִדּוּשֶׁיהָ הֵם הֵם מֵאוּנֶיהָ:","עַד מָתַי הַבַּת מְמָאֶנֶת. כָּל זְמַן שֶׁהִיא קְטַנָּה עַד שֶׁתִּהְיֶה נַעֲרָה אוֹ עַד שֶׁיִּוָּדַע שֶׁהִיא אַיְלוֹנִית. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁלֹּא בָּא עָלֶיהָ הַבַּעַל אַחַר שֶׁנַּעֲשֵׂית בַּת י״‎ב שָׁנָה וְיוֹם אֶחָד. אֲבָל אִם הִגִּיעָה לַזְּמַן הַזֶּה וְנִבְעֲלָה הוֹאִיל וְהַבְּעִילָה קוֹנָה מִן הַתּוֹרָה כְּמוֹ שֶׁבֵּאַרְנוּ הֲרֵי זוֹ אֵינָהּ מְמָאֶנֶת. וְאֵינָהּ צְרִיכָה בְּדִיקָה לְמֵאוּן שֶׁחֶזְקָתָהּ שֶׁהֵבִיאָה סִימָנִין:","הֲרֵי שֶׁנִּבְדְּקָה וְלֹא נִמְצְאוּ לָהּ סִימָנִים הוֹאִיל וְנִבְעֲלָה אַחַר שֶׁהִגִּיעָה לַזְּמַן הָרָאוּי לְסִימָנִין הֲרֵי זוֹ חוֹשְׁשִׁין לָהּ שֶׁמָּא הֵבִיאָה וְנָשְׁרוּ. וּלְפִיכָךְ צְרִיכָה גֵּט מִסָּפֵק. וְאִם מֵאֲנָה אַחַר שֶׁנִּבְדְּקָה וְנִתְקַדְּשָׁה לְאַחֵר צְרִיכָה מִמֶּנּוּ גֵּט מִסָּפֵק. וְאִם נִשֵּׂאת תֵּצֵא מִזֶּה וּמִזֶּה וְהַוָּלָד סְפֵק מַמְזֵר מִשְּׁנֵיהֶם:","קְטַנָּה שֶׁלֹּא מֵאֲנָה וְהִגְדִּילָה וְאַף עַל פִּי שֶׁלֹּא בְּעָלָהּ בַּעְלָהּ מִשֶּׁנַּעֲשֵׂית בַּת שְׁתֵּים עֶשְׂרֵה שָׁנָה וְיוֹם אֶחָד הֲרֵי זוֹ אֵינָהּ מְמָאֶנֶת שֶׁהֲרֵי הִגְדִּילָה. וּצְרִיכָה גֵּט מִדִּבְרֵי סוֹפְרִים שֶׁהֲרֵי לֹא בָּא עָלֶיהָ אַחַר שֶׁהִגִּיעָה לִשְׁנֵי נַעֲרוּת עַד שֶׁנָּחוּשׁ לָהּ שֶׁמָּא הֵבִיאָה סִימָנִין וְתִהְיֶה סָפֵק מְקֻדֶּשֶׁת, וְלֹא בָּא עָלֶיהָ אַחַר שֶׁהִגְדִּילָה כְּדֵי שֶׁתִּהְיֶה אֵשֶׁת אִישׁ גְּמוּרָה. וְנִמְצֵאת שֶׁאֵינָהּ צְרִיכָה גֵּט אֶלָּא מִנִּשּׂוּאֵי קַטְנוּת שֶׁהֵן מִדִּבְרֵי סוֹפְרִים. לְפִיכָךְ אִם עָמְדָה וְנִתְקַדְּשָׁה אַחַר שֶׁגָּדְלָה תּוֹפְסִין בָּהּ קִדּוּשִׁין שֶׁל שֵׁנִי. וְאִם גֵּרֵשׁ הָרִאשׁוֹן יִכְנֹס הַשֵּׁנִי. אֲבָל אִם גֵּרֵשׁ שֵׁנִי לֹא יְקַיֵּם רִאשׁוֹן שֶׁמָּא יֹאמְרוּ הֶחֱזִיר גְּרוּשָׁתוֹ מֵאַחַר שֶׁנִּתְאָרְסָה. וְאִם בָּא עָלֶיהָ שֵׁנִי קֹדֶם שֶׁיְּגָרֵשׁ רִאשׁוֹן תֵּצֵא מִזֶּה וּמִזֶּה מִפְּנֵי שֶׁדּוֹמֶה לְאִשָּׁה שֶׁשָּׁמְעָה שֶׁמֵּת בַּעְלָהּ וְנִשֵּׂאת וְאַחַר כָּךְ בָּא בַּעְלָהּ. וְאֵין הַוָּלָד מִן הַשֵּׁנִי מַמְזֵר. וְאִם בָּא עָלֶיהָ רִאשׁוֹן קֹדֶם שֶׁגֵּרֵשׁ שֵׁנִי הַוָּלָד מַמְזֵר:","אֵי זוֹ הִיא קְטַנָּה שֶׁצְּרִיכָה לְמָאֵן. מִבַּת שֵׁשׁ עַד בַּת עֶשֶׂר שָׁנִים בּוֹדְקִין אוֹתָהּ לְפִי יְפִי דַּעְתָּהּ אִם יוֹדַעַת לִשְׁמֹר קִדּוּשֶׁיהָ וְשֶׁהֵן קִדּוּשִׁין לֹא שֶׁתִּשְׁמֹר אוֹתָן כְּדֶרֶךְ שֶׁמְּשַׁמֶּרֶת הָאֱגוֹז וּתְמָרָה וְכַיּוֹצֵא בָּהֶן הֲרֵי זוֹ צְרִיכָה מֵאוּן. וְאִם אֵינָהּ יוֹדַעַת לִשְׁמֹר קִדּוּשֶׁיהָ אֵינָהּ צְרִיכָה לְמָאֵן אֶלָּא הוֹלֶכֶת לְבֵית אִמָּהּ כְּאִלּוּ לֹא נִתְקַדְּשָׁה מֵעוֹלָם. וּפְחוּתָה מִבַּת שֵׁשׁ אֲפִלּוּ יוֹדַעַת לִשְׁמֹר אֵינָהּ צְרִיכָה מֵאוּן. וִיתֵרָה עַל בַּת עֶשֶׂר אֲפִלּוּ סְכָלָה בְּיוֹתֵר צְרִיכָה מֵאוּן. וְכָל מִי שֶׁהִשִּׂיאוּהָ אַחֶיהָ אוֹ אִמָּהּ אוֹ קְרוֹבֶיהָ שֶׁלֹּא לְדַעְתָּהּ אֵינָהּ צְרִיכָה לְמָאֵן:","כֵּיצַד מְמָאֶנֶת. אוֹמֶרֶת בִּפְנֵי שְׁנֵי עֵדִים אֵין רְצוֹנִי בִּפְלוֹנִי בַּעְלִי. אוֹ אֵין רְצוֹנִי בַּקִּדּוּשִׁין שֶׁקִּדְּשׁוּנִי אִמִּי אוֹ אַחַי. וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ. אֲפִלּוּ הָיוּ אוֹרְחִין מְסֻבִּין בְּבֵית בַּעְלָהּ וְהִיא עוֹמֶדֶת וּמַשְׁקָה עֲלֵיהֶן וְאָמְרָה אֵינִי רוֹצָה בִּפְלוֹנִי בַּעְלִי הֲרֵי זֶה מֵאוּן:","הַשְּׁנַיִם שֶׁמְּמָאֶנֶת הַקְּטַנָּה בִּפְנֵיהֶן כּוֹתְבִין לָהּ בְּיוֹם פְּלוֹנִי מֵאֲנָה פְּלוֹנִית בַּת פְּלוֹנִי בְּפָנֵינוּ בִּפְלוֹנִי בַּעְלָהּ וְחוֹתְמִין וְנוֹתְנִין לָהּ. וְזֶה הוּא גּוּפוֹ שֶׁל גֵּט מֵאוּן. וְגֵט מֵאוּן אֵינוֹ כְּגֵט הַגֵּרוּשִׁין שֶׁנְּתִינָתוֹ מְגָרְשָׁהּ. וְאֵינוֹ צָרִיךְ כְּתִיבָה לִשְׁמָהּ וְלֹא מְסִירָה וְלֹא דָּבָר מִמִּשְׁפְּטֵי גֵּט הַגֵּרוּשִׁין. וְאֵין כּוֹתְבִין בּוֹ טָפְסֵי הַגֵּט שֶׁמָּא יֵרָאֶה כְּגֵט גֵּרוּשִׁין לְפִי שֶׁאֵינוֹ אֶלָּא כְּמַעֲשֵׂה בֵּית דִּין:","הַשְּׁנַיִם שֶׁמְּמָאֶנֶת בִּפְנֵיהֶן צְרִיכִין שֶׁיְּהוּ מַכִּירִין אוֹתָהּ וְאֶת בַּעְלָהּ שֶׁמֵּאֲנָה בּוֹ. לְפִיכָךְ כָּל מִי שֶׁרָאָה אוֹתָהּ שֶׁמֵּאֲנָה וְשָׁמַע מֵאוּנֶיהָ יֵשׁ לוֹ לִכְתֹּב גֵּט מֵאוּן לָהּ אַף עַל פִּי שֶׁאֵין מַכִּירָהּ. וּכְבָר נָהֲגוּ יִשְׂרָאֵל לִכְתֹּב גֵּט מֵאוּן בְּנֹסַח זֶה:","גט מאון:בְּכָךְ בְּשַׁבָּת כָּךְ וְכָךְ יוֹם לְחֹדֶשׁ פְּלוֹנִי שְׁנַת כָּךְ וְכָךְ לְמִנְיַן פְּלוֹנִי מֵאֲנָה פְּלוֹנִית בַּת פְּלוֹנִי בְּפָנֵינוּ וְאָמְרָה שֶׁאִמִּי אוֹ אַחַי הִטְעוּנִי וְהִשִּׂיאוּנִי אוֹ קִדְּשׁוּנִי וַאֲנִי קְטַנָּה לִפְלוֹנִי בַּר פְּלוֹנִי וְהַשְׁתָּא גִּלִּיתִי דַּעְתִּי קָדֳמֵיכוֹן דְּלָא צָבִינָא בֵּיהּ וְלֹא קָאֵימְנָא עִמֵּיהּ. וּבְדַקְנָא פְּלוֹנִית דָּא וְאִתְבָּרֵר לָנָא דַּעֲדַיִן קְטַנָּה הִיא וּכְתַבְנָא וַחֲתַמְנָא וְיָהִיבְנָא לָהּ לִזְכוּת וְלִרְאָיָה בְּרוּרָה: פְּלוֹנִי בַּר פְּלוֹנִי עֵד: פְּלוֹנִי בַּר פְּלוֹנִי עֵד:","הַמְגָרֵשׁ אֶת אִשְׁתּוֹ וְנִתְקַדְּשָׁה לְאַחֵר אַף עַל פִּי שֶׁלֹּא בְּעָלָהּ נֶאֶסְרָה עַל הָרִאשׁוֹן. וְאִם הֶחֱזִיר הָרִאשׁוֹן וּבְעָלָהּ לוֹקֶה וְכוֹפִין אוֹתוֹ לְהוֹצִיא שֶׁנֶּאֱמַר (דברים כד ד) ״‎לֹא יוּכַל בַּעְלָהּ הָרִאשׁוֹן״‎ וְגוֹ':","זִנְּתָה עִם אַחֵר כְּשֶׁהִיא גְּרוּשָׁה מֻתֶּרֶת לַחֲזֹר לְבַעְלָהּ שֶׁנֶּאֱמַר (דברים כד ב) ״‎וְיָצְאָה מִבֵּיתוֹ וְהָלְכָה וְהָיְתָה לְאִישׁ אַחֵר״‎. הֲוָיָתָהּ לְאִישׁ אַחֵר שֶׁהִיא הַקִּדּוּשִׁין הִיא שֶׁאוֹסֶרֶת אוֹתָהּ עַל בַּעְלָהּ לַחֲזֹר לוֹ:","וּבִכְלַל לָאו זֶה שֶׁכָּל אִשָּׁה שֶׁזִּנְּתָה תַּחַת בַּעְלָהּ נֶאֶסְרָה עָלָיו וְלוֹקֶה עָלֶיהָ שֶׁנֶּאֱמַר (דברים כד ד) ״‎אַחֲרֵי אֲשֶׁר הֻטַּמָּאָה״‎ וַהֲרֵי נִטְמְאָה. אֶלָּא אִם כֵּן הָיְתָה אֵשֶׁת יִשְׂרָאֵל שֶׁנֶּאֶנְסָה. לְפִיכָךְ כָּל אִשָּׁה שֶׁנֶּאֶסְרָה עַל בַּעְלָהּ עַל יְדֵי קִנּוּי וּסְתִירָה אִם בָּעַל אוֹתָהּ מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת. וְאִם עָבַר וְהֶחֱזִירָהּ אַחַר שֶׁגֵּרְשָׁהּ יוֹצִיא בְּגֵט:","חֵרֵשׁ שֶׁגֵּרֵשׁ בִּרְמִיזָה כְּמוֹ שֶׁבֵּאַרְנוּ וְהָלְכָה וְנִתְקַדְּשָׁה לְחֵרֵשׁ אַחֵר וְאֵין צָרִיךְ לוֹמַר לְפִקֵּחַ אֲסוּרָה לַחֲזֹר לְבַעְלָהּ הַחֵרֵשׁ. אֲבָל אִשְׁתּוֹ שֶׁל פִּקֵּחַ שֶׁנִּתְגָּרְשָׁה וְהָלְכָה וְנִשֵּׂאת לְחֵרֵשׁ וְנִתְגָּרְשָׁה מֻתֶּרֶת לַחֲזֹר לְבַעְלָהּ הַפִּקֵּחַ:","הַמְמָאֶנֶת בְּאִישׁ אֵינָהּ מְגֹרֶשֶׁת מִמֶּנּוּ. וְדִינָהּ עִם בַּעְלָהּ שֶׁמֵּאֲנָה בּוֹ כְּדִינָהּ עִם מִי שֶׁלֹּא קִדְּשָׁהּ מֵעוֹלָם. הִיא מֻתֶּרֶת בִּקְרוֹבָיו וְהוּא מֻתָּר בִּקְרוֹבוֹתֶיהָ וְלֹא פְּסָלָהּ מִן הַכְּהֻנָּה. וְאִם נִשֵּׂאת לְאַחֵר וְגֵרְשָׁהּ הָאַחֵר אוֹ מֵת אוֹ מֵאֲנָה בּוֹ מֻתֶּרֶת לַחֲזֹר לָרִאשׁוֹן. וְלֹא עוֹד אֶלָּא אֲפִלּוּ גֵּרְשָׁהּ הָרִאשׁוֹן וְהֶחֱזִירָהּ וּמֵאֲנָה בּוֹ וְנִשֵּׂאת לְאַחֵר אַחַר שֶׁמֵּאֲנָה בּוֹ וְגֵרְשָׁהּ הָאַחֵר מֻתֶּרֶת לַחֲזֹר לָרִאשׁוֹן. שֶׁכָּל הַיּוֹצֵאת בְּמֵאוּן אַף עַל פִּי שֶׁקְּדָמוֹ גֵּט הֲרֵי זוֹ כְּמִי שֶׁלֹּא נִתְגָּרְשָׁה מִמֶּנּוּ בְּגֵט מֵעוֹלָם וּמֻתֶּרֶת לַחֲזֹר לוֹ. אֲבָל הַמְגָרֵשׁ אֶת הַקְּטַנָּה בְּגֵט וְנִשֵּׂאת לְאַחֵר וּמֵאֲנָה בּוֹ אֲסוּרָה לַחֲזֹר לָרִאשׁוֹן מִפְּנֵי שֶׁיָּצָאת מִמֶּנּוּ בְּגֵט אַף עַל פִּי שֶׁיָּצָאת מִן הָאַחֲרוֹן בְּמֵאוּן. וְאֵין צָרִיךְ לוֹמַר אִם גֵּרְשָׁהּ הָאַחֲרוֹן אוֹ מֵת. וְכֵן אֲסוּרָה לַאֲבִי הָרִאשׁוֹן וְלִבְנוֹ וּלְאָחִיו כִּשְׁאָר הַגְּרוּשׁוֹת אַף עַל פִּי שֶׁיָּצָאת מִן הָאַחֲרוֹן בְּמֵאוּן:","הַמְמָאֶנֶת בְּיָבָם אֲסוּרָה לְאָבִיו מִפְּנֵי שֶׁנִּרְאֵית כְּכַלָּתוֹ בְּעֵת שֶׁמֵּת בְּנוֹ. אֲבָל לִשְׁאָר קְרוֹבִים מֻתֶּרֶת. לְפִיכָךְ אִם מֵאֲנָה בְּאֶחָד מִן הַיָּבָמִין מֻתֶּרֶת לְאֶחָיו:","כָּל אִשָּׁה שֶׁנִּתְגָּרְשָׁה אוֹ שֶׁנִּתְאַלְמְנָה הֲרֵי זוֹ לֹא תִּנָּשֵׂא וְלֹא תִּתְאָרֵס עַד שֶׁתַּמְתִּין תִּשְׁעִים יוֹם חוּץ מִיּוֹם שֶׁנִּתְגָּרְשָׁה אוֹ שֶׁמֵּת בַּעְלָהּ בּוֹ וְחוּץ מִיּוֹם שֶׁנִּתְאָרְסָה בּוֹ. כְּדֵי שֶׁיִּוָּדַע אִם הִיא מְעֻבֶּרֶת אוֹ אֵינָהּ מְעֻבֶּרֶת לְהַבְחִין בֵּין זַרְעוֹ שֶׁל רִאשׁוֹן לְזַרְעוֹ שֶׁל שֵׁנִי:","וּמִיּוֹם כְּתִיבַת הַגֵּט מוֹנִין לִמְגֹרֶשֶׁת. וַאֲפִלּוּ הָיָה עַל תְּנַאי אוֹ שֶׁלֹּא הִגִּיעַ לְיָדָהּ אֶלָּא לְאַחַר כַּמָּה שָׁנִים מִיּוֹם הַכְּתִיבָה מוֹנִין. שֶׁהֲרֵי אֵינוֹ מִתְיַחֵד עִמָּהּ מִשֶּׁכְּתָבוֹ לָהּ:","וּגְזֵרַת חֲכָמִים הִיא שֶׁאֲפִלּוּ אִשָּׁה שֶׁאֵינָהּ רְאוּיָה לֵילֵד וַאֲפִלּוּ נִתְגָּרְשָׁה אוֹ נִתְאַלְמְנָה מִן הָאֵרוּסִין צְרִיכָה לְהַמְתִּין תִּשְׁעִים יוֹם. אֲפִלּוּ קְטַנָּה אוֹ זְקֵנָה אוֹ עֲקָרָה אוֹ אַיְלוֹנִית. וַאֲפִלּוּ בַּעְלָהּ בִּמְדִינַת הַיָּם אוֹ חוֹלֶה אוֹ חָבוּשׁ בְּבֵית הַאֲסּוּרִין וַאֲפִלּוּ בְּתוּלָה מִן הָאֵרוּסִין צְרִיכוֹת לְהַמְתִּין תִּשְׁעִים יוֹם:","שִׁפְחָה שֶׁנִּשְׁתַּחְרְרָה וְגִיּוֹרֶת שֶׁנִּתְגַּיְּרָה מַמְתִּינִין תִּשְׁעִים יוֹם. וַאֲפִלּוּ גֵּר וְאִשְׁתּוֹ שֶׁנִּתְגַּיְּרוּ מַפְרִישִׁין אוֹתָן תִּשְׁעִים יוֹם כְּדֵי לְהַבְחִין בֵּין זֶרַע שֶּׁנִּזְרַע בִּקְדֻשָּׁה לְזֶרַע שֶׁלֹּא נִזְרַע בִּקְדֻשָּׁה. וְכֵן יְפַת תֹּאַר אַף עַל פִּי שֶׁנָּתְנָה לָהּ תּוֹרָה שְׁלֹשִׁים יוֹם לְתַקָּנַת עַצְמָהּ צְרִיכָה לְהַמְתִּין תִּשְׁעִים יוֹם לְתַקָּנַת הַוָּלָד. וְהַשְּׁלֹשִׁים מִכְּלַל הַתִּשְׁעִים:","הַמְמָאֶנֶת אֵינָהּ צְרִיכָה לְהַמְתִּין. לֹא גָּזְרוּ אֶלָּא בִּגְרוּשָׁה. וְכֵן הַמְזַנָּה אֵינָהּ צְרִיכָה לְהַמְתִּין מִפְּנֵי שֶׁמְּשַׁמֶּרֶת עַצְמָהּ שֶׁלֹּא תִּתְעַבֵּר. וְכֵן אֲנוּסָה וּמְפֻתָּה אֵינָן צְרִיכוֹת לְהַמְתִּין:","מִי שֶׁנִּשֵּׂאת בְּטָעוּת וְנוֹדַע שֶׁהִיא אֲסוּרָה לְבַעְלָהּ וְהוֹצִיאוּהָ בֵּית דִּין מִתַּחְתָּיו. אִם הָיְתָה קְטַנָּה שֶׁאֵינָהּ רְאוּיָה לֵילֵד אֵינָהּ צְרִיכָה לְהַמְתִּין. שֶׁזֶּה דָּבָר שֶׁאֵינוֹ מָצוּי הוּא וְכָל דָּבָר שֶׁאֵינוֹ מָצוּי בְּרֹב לֹא גָּזְרוּ בּוֹ:","הַמְאָרֵס בְּתוֹךְ תִּשְׁעִים יוֹם מְנַדִּין אוֹתוֹ. אֵרֵס וּבָרַח אֵין מְנַדִּין אוֹתוֹ. כָּנַס בְּתוֹךְ תִּשְׁעִים יוֹם מַפְרִישִׁין אוֹתָן עַד אַחַר זְמַן וְיַעֲמֹד עִם אִשְׁתּוֹ:","וְכֵן גָּזְרוּ חֲכָמִים שֶׁלֹּא יִשָּׂא אָדָם מְעֻבֶּרֶת חֲבֵרוֹ וּמֵינֶקֶת חֲבֵרוֹ. וְאַף עַל פִּי שֶׁהַזֶּרַע יָדוּעַ לְמִי הִיא מְעֻבֶּרֶת. שֶׁמָּא יַזִּיק הַוָּלָד בִּשְׁעַת תַּשְׁמִישׁ שֶׁאֵינוֹ מַקְפִּיד עַל בֶּן חֲבֵרוֹ. וּמֵינִיקָה שֶׁמָּא יִתְעַכֵּר הֶחָלָב וְהוּא אֵינוֹ מַקְפִּיד לְרַפְּאוֹת הֶחָלָב בִּדְבָרִים הַמּוֹעִילִין לֶחָלָב כְּשֶׁיִּתְעַכֵּר:","כַּמָּה הוּא זְמַן הַיְנִיקָה. כ״‎ד חֹדֶשׁ חוּץ מִיּוֹם שֶׁנּוֹלַד בּוֹ וּמִיּוֹם שֶׁנִּתְאָרְסָה בּוֹ:","כְּשֵׁם שֶׁאָסוּר לִשָּׂא כָּךְ אָסוּר לְאָרֵס עַד אַחַר זְמַן זֶה. אֲפִלּוּ נָתְנָה בְּנָהּ לְמֵינִיקָה אוֹ שֶׁגְּמָלַתּוּ בְּתוֹךְ כ״‎ד חֹדֶשׁ לֹא תִּנָּשֵׂא. מֵת בְּנָהּ מֻתֶּרֶת לִנָּשֵׂא. וְאֵין חוֹשְׁשִׁין שֶׁמָּא תַּהַרְגֶנּוּ:","עָבַר וְנָשָׂא מְעֻבֶּרֶת אוֹ מֵינִיקָה בְּתוֹךְ זְמַן זֶה יוֹצִיא בְּגֵט וַאֲפִלּוּ הָיָה כֹּהֵן. וְאִם הָיָה יִשְׂרָאֵל יַחֲזִירֶנָהּ אַחַר כ״‎ד חֹדֶשׁ שֶׁל מֵינִיקָה. נָשָׂא וּבָרַח וּלְאַחַר זְמַן בָּא וְיָשַׁב עִם אִשְׁתּוֹ אֵין בְּכָךְ כְּלוּם. אֵרֵס מְעֻבֶּרֶת אוֹ מֵינִיקָה אֵין כּוֹפִין אוֹתוֹ לְהוֹצִיא וְלֹא לִכְנֹס עַד אַחַר זְמַן הַיְנִיקָה אוֹ עַד שֶׁיָּמוּת הַוָּלָד:"],"Mishneh Torah, Eruvin 2":["אַנְּשֵׁי הֶחָצֵר שֶׁעֵרְבוּ כֻּלָּן חוּץ מֵאֶחָד מֵהֶן שֶׁלֹּא עֵרֵב עִמָּהֶן בֵּין מֵזִיד בֵּין שׁוֹכֵחַ הֲרֵי זֶה אוֹסֵר עֲלֵיהֶן. וְאָסוּר לְכֻלָּן לְהוֹצִיא מִבָּתֵּיהֶן לֶחָצֵר אוֹ מֵחָצֵר לְבָתֵּיהֶן. בִּטֵּל לָהֶן זֶה שֶׁלֹּא עֵרֵב רְשׁוּת חֲצֵרוֹ בִּלְבַד הֲרֵי אֵלּוּ מֻתָּרִין לְהוֹצִיא וּלְהַכְנִיס מִבָּתֵּיהֶן לֶחָצֵר וּמֵחָצֵר לְבָתֵּיהֶן אֲבָל לְבֵיתוֹ אָסוּר. בִּטֵּל לָהֶן רְשׁוּת בֵּיתוֹ וּרְשׁוּת חֲצֵרוֹ הֲרֵי כֻּלָּם מֻתָּרִין. הֵן מִפְּנֵי שֶׁעֵרְבוּ וַהֲרֵי בִּטֵּל לָהֶן רְשׁוּת בֵּיתוֹ וַחֲצֵרוֹ. וְגַם הוּא מֻתָּר מִפְּנֵי שֶׁלֹּא נִשְׁאַר לוֹ רְשׁוּת וַהֲרֵי הוּא כְּאוֹרֵחַ אֶצְלָם וְהָאוֹרֵחַ אֵינוֹ אוֹסֵר:","הַמְבַטֵּל רְשׁוּתוֹ סְתָם רְשׁוּת חֲצֵרוֹ בִּטֵּל רְשׁוּת בֵּיתוֹ לֹא בִּטֵּל. וְהַמְבַטֵּל רְשׁוּתוֹ לִבְנֵי חָצֵר צָרִיךְ לְבַטֵּל לְכָל אֶחָד וְאֶחָד בְּפֵרוּשׁ וְאוֹמֵר רְשׁוּתִי מְבֻטֶּלֶת לְךָ וּלְךָ וּלְךָ. וְהַיּוֹרֵשׁ מְבַטֵּל רְשׁוּת אַף עַל פִּי שֶׁמֵּת מוֹרִישׁוֹ בְּשַׁבָּת שֶׁהַיּוֹרֵשׁ קָם תַּחַת מוֹרִישׁוֹ לְכָל דָּבָר. וּבִטּוּל רְשׁוּת בְּשַׁבָּת מֻתָּר לְכַתְּחִלָּה:","בִּטְּלוּ אֵלּוּ הַמְעָרְבִין רְשׁוּתָן לְזֶה שֶׁלֹּא עֵרֵב. הוּא מֻתָּר שֶׁהֲרֵי נִשְׁאָר לְבַדּוֹ. וְהֵם אֲסוּרִין שֶׁלֹּא נִשְׁאָר לָהֶן רְשׁוּת. וְאֵין אוֹמְרִים יִהְיוּ כְּאוֹרְחִים אֶצְלוֹ שֶׁאֵין רַבִּים אוֹרְחִין אֵצֶל אֶחָד:","הָיוּ אֵלּוּ שֶׁלֹּא עֵרְבוּ שְׁנַיִם אוֹ יֶתֶר. אִם בִּטְּלוּ רְשׁוּתָם לַמְעָרְבִין הַמְעָרְבִין מֻתָּרִין וְאֵלּוּ שֶׁלֹּא עֵרְבוּ אֲסוּרִין. וְאֵין הַמְעָרְבִין יְכוֹלִים לְבַטֵּל רְשׁוּתָם לִשְׁנַיִם שֶׁלֹּא עֵרְבוּ שֶׁכָּל אֶחָד מֵהֶן אוֹסֵר עַל חֲבֵרוֹ. וַאֲפִלּוּ חָזַר הָאֶחָד שֶׁלֹּא עֵרֵב וּבִטֵּל רְשׁוּתוֹ לַשֵּׁנִי שֶׁלֹּא עֵרֵב הֲרֵי זֶה אוֹסֵר שֶׁבְּשָׁעָה שֶׁבִּטְּלוּ לוֹ הַמְעָרְבִין אָסוּר הָיָה. אֶחָד שֶׁעֵרֵב אֵינוֹ מְבַטֵּל רְשׁוּתוֹ לְאֶחָד שֶׁלֹּא עֵרֵב אֲבָל הָאֶחָד שֶׁלֹּא עֵרֵב מְבַטֵּל רְשׁוּתוֹ לְאֶחָד שֶׁעֵרֵב:","כְּשֵׁם שֶׁבַּעַל הַבַּיִת זֶה מְבַטֵּל רְשׁוּתוֹ לְבַעַל הַבַּיִת זֶה בְּחָצֵר אַחַת כָּךְ מְבַטְּלִין מֵחָצֵר לֶחָצֵר. וּמְבַטְּלִין וְחוֹזְרִין וּמְבַטְּלִין. כֵּיצַד. שְׁנַיִם שֶׁשְּׁרוּיִים בֶּחָצֵר וְלֹא עֵרֵב. אֶחָד מֵהֶן מְבַטֵּל רְשׁוּתוֹ לַשֵּׁנִי וְנִמְצָא הַשֵּׁנִי מְטַלְטֵל בִּרְשׁוּתוֹ שֶׁבִּטֵּל לוֹ חֲבֵרוֹ עַד שֶׁיַּעֲשֶׂה צְרָכָיו. וְחוֹזֵר הַשֵּׁנִי וּמְבַטֵּל רְשׁוּתוֹ לָרִאשׁוֹן וּמְטַלְטֵל הָרִאשׁוֹן בִּרְשׁוּתוֹ שֶׁבִּטֵּל לוֹ. וְכֵן כַּמָּה פְּעָמִים. וְיֵשׁ בִּטּוּל רְשׁוּת בְּחֻרְבָּה כְּדֶרֶךְ שֶׁהוּא בְּחָצֵר:","מִי שֶׁבִּטֵּל רְשׁוּתוֹ וְחָזַר וְטִלְטֵל בִּרְשׁוּתוֹ שֶׁבִּטֵּל. אִם בְּמֵזִיד הוֹצִיא הֲרֵי זֶה אוֹסֵר עֲלֵיהֶן שֶׁהֲרֵי לֹא עָמַד בְּבִטּוּלוֹ. וְאִם בְּשׁוֹגֵג הוֹצִיא אֵינוֹ אוֹסֵר שֶׁהֲרֵי הוּא עוֹמֵד בְּבִטּוּלוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁלֹּא קָדְמוּ וְהֶחֱזִיקוּ אֵלּוּ שֶׁבִּטֵּל לָהֶן. אֲבָל אִם קָדְמוּ וְהֶחֱזִיקוּ וְהוֹצִיאוּ אִם חָזַר הוּא וְהוֹצִיא בֵּין בְּשׁוֹגֵג בֵּין בְּמֵזִיד אֵינוֹ אוֹסֵר עֲלֵיהֶן:","שְׁנֵי בָּתִּים בִּשְׁנֵי צִדֵּי רְשׁוּת הָרַבִּים וֶהֱקִיפוּם נָכְרִים מְחִצָּה בְּשַׁבָּת אֵין מְבַטְּלִין זֶה לָזֶה הוֹאִיל וְאִי אֶפְשָׁר לָהֶם לְעָרֵב מֵאֶמֶשׁ. אֶחָד מִבְּנֵי חָצֵר שֶׁמֵּת וְהֵנִיחַ רְשׁוּתוֹ לְאֶחָד מִן הַשּׁוּק. אִם מֵת מִבְּעוֹד יוֹם הֲרֵי הַיּוֹרֵשׁ שֶׁאֵינוֹ מִבְּנֵי הֶחָצֵר אוֹסֵר עֲלֵיהֶם. וְאִם מֵת מִשֶּׁחֲשֵׁכָה אֵינוֹ אוֹסֵר עֲלֵיהֶם. וְאֶחָד מִן הַשּׁוּק שֶׁמֵּת וְהֵנִיחַ רְשׁוּתוֹ לְאֶחָד מִבְּנֵי הֶחָצֵר. אִם מִבְּעוֹד יוֹם מֵת אֵינוֹ אוֹסֵר עֲלֵיהֶם שֶׁהֲרֵי כֻּלָּן מְעֹרָבִים. וְאִם מֵת מִשֶּׁחֲשֵׁכָה אוֹסֵר עֲלֵיהֶם עַד שֶׁיְּבַטֵּל רְשׁוּת מוֹרִישׁוֹ לָהֶן:","יִשְׂרָאֵל וְגֵר שֶׁשְּׁרוּיִים בִּמְעָרָה אַחַת וּמֵת הַגֵּר מִבְּעוֹד יוֹם אַף עַל פִּי שֶׁלֹּא הֶחֱזִיק יִשְׂרָאֵל אַחֵר בִּנְכָסָיו עַד שֶׁחֲשֵׁכָה הֲרֵי זֶה הַמַּחֲזִיק אוֹסֵר עַד שֶׁיְּבַטֵּל שֶׁהֲרֵי הוּא כְּיוֹרֵשׁ. וְאִם מֵת הַגֵּר מִשֶּׁחֲשֵׁכָה אַף עַל פִּי שֶׁהֶחֱזִיק יִשְׂרָאֵל אַחֵר בִּנְכָסָיו אֵינוֹ אוֹסֵר עָלָיו אֶלָּא בְּהֶתֵּרוֹ הָרִאשׁוֹן הוּא עוֹמֵד:","יִשְׂרָאֵל הַדָּר עִם הָעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת אוֹ עִם גֵּר תּוֹשָׁב בְּחָצֵר אֵינוֹ אוֹסֵר עָלָיו שֶׁדִּירַת הָעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת אֵינָהּ דִּירָה אֶלָּא כִּבְהֵמָה הוּא חָשׁוּב. וְאִם הָיוּ שְׁנֵי יִשְׂרְאֵלִים אוֹ יָתֵר וְעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת שָׁכֵן עִמָּהֶן הֲרֵי זֶה אוֹסֵר עֲלֵיהֶם. וְדָבָר זֶה גְּזֵרָה שֶׁלֹּא יַשְׁכִּינוּ עוֹבֵד כּוֹכָבִים וּמַזָּלוֹת עִמָּהֶן שֶׁלֹּא יִלְמְדוּ מִמַּעֲשָׂיו. וְלָמָּה לֹא גָּזְרוּ בְּיִשְׂרָאֵל אֶחָד וְעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת אֶחָד. מִפְּנֵי שֶׁאֵינוֹ דָּבָר מָצוּי. שֶׁהֲרֵי יִפְחַד שֶׁמָּא יִתְיַחֵד עִמּוֹ וְיַהַרְגֶּנּוּ וּכְבָר אָסְרוּ לְהִתְיַחֵד עִם הָעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת:","שְׁנֵי יִשְׂרְאֵלִים וְעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת הַשּׁוֹכְנִים בְּחָצֵר אַחַת וְעֵרְבוּ הַיִּשְׂרְאֵלִים לְעַצְמָן לֹא הוֹעִילוּ כְּלוּם. וְכֵן אִם בִּטְּלוּ לְעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת אוֹ בִּטֵּל לָהֶן אוֹ בִּטְּלוּ הַיִּשְׂרְאֵלִים זֶה לָזֶה וְנַעֲשׂוּ כְּיָחִיד עִם הָעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת לֹא הוֹעִילוּ כְּלוּם. שֶׁאֵין עֵרוּב מוֹעִיל בִּמְקוֹם עוֹבֵד כּוֹכָבִים וּמַזָּלוֹת. וְאֵין בִּטּוּל רְשׁוּת מוֹעִיל בִּמְקוֹם עוֹבֵד כּוֹכָבִים וּמַזָּלוֹת. וְאֵין לָהֶן תַּקָּנָה אֶלָּא שֶׁיִּשְׂכְּרוּ מִמֶּנּוּ רְשׁוּתוֹ וְיֵעָשֶׂה הָעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת כְּאִלּוּ הוּא אוֹרֵחַ עִמָּהֶן. וְכֵן אִם הָיוּ עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת רַבִּים מַשְׂכִּירִין רְשׁוּתָם לְיִשְׂרְאֵלִים וְהַיִּשְׂרְאֵלִים מְעָרְבִין וּמֻתָּרִין. וְיִשְׂרָאֵל אֶחָד שֶׁשָּׂכַר מִן הָעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת מְעָרֵב עִם שְׁאָר הַיִּשְׂרְאֵלִים וְיֻתְּרוּ כֻּלָּם. וְאֵין כָּל אֶחָד צָרִיךְ לִשְׂכֹּר מִן הָעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת:","שְׁתֵּי חֲצֵרוֹת זוֹ לִפְנִים מִזּוֹ וְיִשְׂרָאֵל וְעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת דָּרִים בַּפְּנִימִית וְיִשְׂרָאֵל אַחֵר בַּחִיצוֹנָה. אוֹ שֶׁהָיָה יִשְׂרָאֵל וְעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת בַּחִיצוֹנָה וְיִשְׂרָאֵל אַחֵר בַּפְּנִימִית הֲרֵי זֶה אוֹסֵר עַל הַחִיצוֹנָה עַד שֶׁיִּשְׂכֹּר מִמֶּנּוּ. שֶׁהֲרֵי רַגְלֵי שְׁנֵי יִשְׂרְאֵלִים וְעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת מְצוּיִים שָׁם. וְהַפְּנִימִי מֻתָּר בַּפְּנִימִית:","שׂוֹכְרִין מִן הָעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת אֲפִלּוּ בְּשַׁבָּת. שֶׁהַשְּׂכִירוּת כְּבִטּוּל רְשׁוּת הִיא שֶׁאֵינָהּ שְׂכִירוּת וַדָּאִית אֶלָּא הֶכֵּר בִּלְבַד. לְפִיכָךְ שׂוֹכְרִין מִן הָעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת אֲפִלּוּ בְּפָחוֹת מִשְּׁוֵה פְּרוּטָה. וְאִשְׁתּוֹ שֶׁל עוֹבֵד כּוֹכָבִים וּמַזָּלוֹת מַשְׂכֶּרֶת שֶׁלֹּא לְדַעְתּוֹ. וְכֵן שְׂכִירוֹ וְשַׁמָּשׁוֹ מַשְׂכִּירִין שֶׁלֹּא לְדַעְתּוֹ. וַאֲפִלּוּ הָיָה שְׂכִירוֹ אוֹ שַׁמָּשׁוֹ יִשְׂרְאֵלִי הֲרֵי זֶה מַשְׂכִּיר שֶׁלֹּא לְדַעְתּוֹ. שָׁאַל מִן הָעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת מָקוֹם לְהַנִּיחַ בּוֹ חֲפָצָיו וְהִשְׁאִילוֹ הֲרֵי נִשְׁתַּתֵּף עִמּוֹ בִּרְשׁוּתוֹ וּמַשְׂכִּיר שֶׁלֹּא לְדַעְתּוֹ. הָיוּ לְעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת זֶה שְׂכִירִים אוֹ שַׁמָּשִׁים אוֹ נָשִׁים רַבִּים אִם הִשְׂכִּיר אֶחָד מֵהֶן דַּיּוֹ:","שְׁנֵי יִשְׂרְאֵלִים וְעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת הַדָּרִים בְּחָצֵר אַחַת וְשָׂכְרוּ מִן הָעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת בְּשַׁבָּת חוֹזֵר הָאֶחָד וּמְבַטֵּל רְשׁוּתוֹ לַשֵּׁנִי וּמֻתָּר. וְכֵן אִם מֵת הָעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת בְּשַׁבָּת מְבַטֵּל הַיִּשְׂרְאֵלִי לַיִּשְׂרְאֵלִי הָאַחֵר וְיִהְיֶה מֻתָּר לְטַלְטֵל:","עוֹבֵד כּוֹכָבִים וּמַזָּלוֹת שֶׁהִשְׂכִּיר לְעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת אִם אֵין הָרִאשׁוֹן יָכוֹל לְהוֹצִיא הָעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת הַשֵּׁנִי עַד שֶׁיַּשְׁלִים זְמַן שְׂכִירוּתוֹ שׂוֹכְרִין מִזֶּה הָעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת הַשֵּׁנִי שֶׁהֲרֵי נִכְנַס תַּחַת הַבְּעָלִים. וְאִם יֵשׁ רְשׁוּת לָרִאשׁוֹן לְהוֹצִיא הָעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת הַשּׂוֹכֵר מִמֶּנּוּ בְּכָל עֵת שֶׁיִּרְצֶה. אִם לֹא הָיָה הַשֵּׁנִי עוֹמֵד וְשָׂכְרוּ הַיִּשְׂרְאֵלִים מִן הָרִאשׁוֹן הֲרֵי אֵלּוּ מֻתָּרִין:","חָצֵר שֶׁיִּשְׂרְאֵלִים וְעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת שְׁרוּיִין בָּהּ וְהָיוּ חַלּוֹנוֹת פְּתוּחוֹת מִבֵּית יִשְׂרְאֵלִי זֶה לְבֵית יִשְׂרְאֵלִי זֶה וְעָשׂוּ עֵרוּב דֶּרֶךְ חַלּוֹנוֹת. אַף עַל פִּי שֶׁהֵן מֻתָּרִין לְהוֹצִיא מִבַּיִת לְבַיִת דֶּרֶךְ חַלּוֹנוֹת הֲרֵי הֵן אֲסוּרִין לְהוֹצִיא מִבַּיִת לְבַיִת דֶּרֶךְ פְּתָחִים מִפְּנֵי הָעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת עַד שֶׁיַּשְׂכִּיר. שֶׁאֵין רַבִּים נַעֲשִׂים בְּעֵרוּב כְּיָחִיד בִּמְקוֹם הָעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת:","יִשְׂרָאֵל שֶׁהוּא מְחַלֵּל שַׁבָּת בְּפַרְהֶסְיָא אוֹ שֶׁהוּא עוֹבֵד עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת הֲרֵי הוּא כְּעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת לְכָל דְּבָרָיו. וְאֵין מְעָרְבִין עִמּוֹ וְאֵינוֹ מְבַטֵּל רְשׁוּת אֶלָּא שׂוֹכְרִין מִמֶּנּוּ כְּעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת. אֲבָל אִם הָיָה מִן הָאֶפִּיקוֹרוֹסִין שֶׁאֵין עוֹבְדִין עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת וְאֵין מְחַלְּלִין שַׁבָּת כְּגוֹן צְדוֹקִין וּבַיְתוֹסִין וְכָל הַכּוֹפְרִים בַּתּוֹרָה שֶׁבְּעַל פֶּה, כְּלָלוֹ שֶׁל דָּבָר כָּל מִי שֶׁאֵינוֹ מוֹדֶה בְּמִצְוַת עֵרוּב, אֵין מְעָרְבִין עִמּוֹ לְפִי שֶׁאֵינוֹ מוֹדֶה בָּעֵרוּב. וְאֵין שׂוֹכְרִין מִמֶּנּוּ לְפִי שֶׁאֵינוֹ כְּעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת. אֲבָל מְבַטֵּל הוּא רְשׁוּתוֹ לְיִשְׂרָאֵל הַכָּשֵׁר וְזוֹ הִיא תַּקָּנָתוֹ. וְכֵן אִם הָיָה יִשְׂרָאֵל אֶחָד כָּשֵׁר וְזֶה הַצְּדוֹקִי בֶּחָצֵר הֲרֵי זֶה אוֹסֵר עָלָיו עַד שֶׁיְּבַטֵּל לוֹ רְשׁוּתוֹ:"],"Mishneh Torah, Festival Offering 1":["שָׁלֹשׁ מִצְוֹת עֲשֵׂה נִצְטַוּוּ יִשְׂרָאֵל בְּכָל רֶגֶל מִשָּׁלֹשׁ רְגָלִים וְאֵלּוּ הֵן. הָרְאִיָּה שֶׁנֶּאֱמַר (שמות כג יז) (שמות לד כג) (דברים טז טז) \"יֵרָאֶה כָּל זְכוּרְךָ\". וְהַחֲגִיגָה שֶׁנֶּאֱמַר (דברים טז טו) \"תָּחֹג לַה' אֱלֹהֶיךָ\". וְהַשִּׂמְחָה שֶׁנֶּאֱמַר (דברים טז יד) \"וְשָׂמַחְתָּ בְּחַגֶּךָ\". הָרְאִיָּה הָאֲמוּרָה בַּתּוֹרָה הִיא שֶׁנִּרְאָה פָּנָיו בָּעֲזָרָה בְּיוֹם טוֹב הָרִאשׁוֹן שֶׁל חַג וְיָבִיא עִמּוֹ קָרְבַּן עוֹלָה בֵּין מִן הָעוֹף בֵּין מִן הַבְּהֵמָה. וּמִי שֶׁבָּא לָעֲזָרָה בְּיוֹם רִאשׁוֹן וְלֹא הֵבִיא עוֹלָה לֹא דַּיּוֹ שֶׁלֹּא עָשָׂה מִצְוַת עֲשֵׂה אֶלָּא עוֹבֵר עַל לֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (שמות כג טו) (שמות לד כ) \"לֹא יֵרָאוּ פָנַי רֵיקָם\". וְאֵינוֹ לוֹקֶה עַל לָאו זֶה שֶׁהֲרֵי לֹא עָשָׂה מַעֲשֶׂה. הַחֲגִיגָה הָאֲמוּרָה בַּתּוֹרָה הִיא שֶׁיַּקְרִיב שְׁלָמִים בְּיוֹם טוֹב הָרִאשׁוֹן שֶׁל חַג בְּבוֹאוֹ לְהֵרָאוֹת. וְהַדָּבָר יָדוּעַ שֶׁאֵין הַשְּׁלָמִים בָּאִים אֶלָּא מִן הַבְּהֵמָה. וּשְׁתֵּי מִצְוֹת אֵלּוּ שֶׁהֵן הָרְאִיָּה וְהַחֲגִיגָה אֵין הַנָּשִׁים חַיָּבוֹת בָּהֶן. וְהַשִּׂמְחָה הָאֲמוּרָה בָּרְגָלִים הִיא שֶׁיַּקְרִיב שְׁלָמִים יֶתֶר עַל שַׁלְמֵי חֲגִיגָה. וְאֵלּוּ הֵם הַנִּקְרָאִים שַׁלְמֵי שִׂמְחַת חֲגִיגָה שֶׁנֶּאֱמַר (דברים כז ז) \"וְזָבַחְתָּ שְׁלָמִים וְאָכַלְתָּ שָּׁם וְשָׂמַחְתָּ לִפְנֵי ה' אֱלֹהֶיךָ\". וְנָשִׁים חַיָּבוֹת בְּמִצְוָה זוֹ:","הָרְאִיָּה וְהַחֲגִיגָה אֵין לָהֶן שִׁעוּר מִן הַתּוֹרָה שֶׁנֶּאֱמַר (דברים טז יז) \"אִישׁ כְּמַתְּנַת יָדוֹ\" וְגוֹ'. אֲבָל מִדִּבְרֵי סוֹפְרִים שֶׁלֹּא יְהֵא קָרְבַּן עוֹלַת רְאִיָּה פָּחוֹת מִשְּׁוֵה מָעָה כֶּסֶף וְלֹא שַׁלְמֵי חֲגִיגָה פָּחוֹת מִשְּׁוֵה שְׁתֵּי כֶּסֶף. וּמִצְוָה לְהָבִיא כְּפִי עָשְׁרוֹ שֶׁנֶּאֱמַר כְּמַתְּנַת יָדוֹ:","שַׁלְמֵי שִׂמְחָה לֹא נָתְנוּ בָּהֶן חֲכָמִים שִׁעוּר. בְּעֵת שֶׁיַּעֲלֶה אָדָם לִירוּשָׁלַיִם לָחֹג אִם הָיוּ בְּיָדוֹ קָרְבְּנוֹת הָרְאִיָּה יְבִיאֵם אוֹ יַעֲלֶה עִמּוֹ כֶּסֶף לִקְנוֹת בּוֹ הַקָּרְבָּן. וְאִם אֵין בְּיָדוֹ כֶּסֶף לֹא יָבִיא שְׁוֵה כֶּסֶף אֲפִלּוּ הָיָה בְּיָדוֹ שְׁוֵה כַּמָּה זְהוּבִים אָסוּר לוֹ לַעֲלוֹת רֵיקָם בְּלֹא כֶּסֶף וְלֹא קָרְבָּן. וְלָמָּה אָסְרוּ שֶׁיַּעֲלֶה בְּיָדוֹ שְׁוֵה כֶּסֶף גְּזֵרָה שֶׁמָּא לֹא יִמְצָא לִמְכֹּר אוֹ שֶׁמָּא יִמָּצְאוּ הַמָּעוֹת סִיגִים:","מִי שֶׁלֹּא הִקְרִיב בְּיוֹם טוֹב הָרִאשׁוֹן עוֹלַת רְאִיָּתוֹ וְשַׁלְּמִי חֲגִיגָתוֹ הֲרֵי זֶה מַקְרִיבָן בִּשְׁאָר יְמוֹת הָרֶגֶל שֶׁנֶּאֱמַר (דברים טז טו) \"שִׁבְעַת יָמִים תָּחֹג לַה' אֱלֹהֶיךָ\" מְלַמֵּד שֶׁכֻּלָּן רְאוּיִין לַחֲגִיגָה וְכֻלָּן תַּשְׁלוּמֵי רִאשׁוֹן הֵם:","וּמִצְוָה לְהַקְדִּים וּלְהַקְרִיב בָּרִאשׁוֹן. לֹא הִקְרִיב בָּרִאשׁוֹן בֵּין שׁוֹגֵג בֵּין מֵזִיד יַקְרִיב בַּשֵּׁנִי. וְכָל הַמְּאַחֵר הֲרֵי זֶה מְגֻנֶּה וְעָלָיו נֶאֱמַר (צפניה ג יח) \"נוּגֵי מִמּוֹעֵד אָסַפְתִּי\":","עָבַר הָרֶגֶל וְלֹא חָג אֵינוֹ חַיָּב בְּאַחֲרָיוּתוֹ וְעַל זֶה וְכַיּוֹצֵא בּוֹ נֶאֱמַר (קהלת א טו) \"מְעֻוָּת לֹא יוּכַל לִתְקֹן\":","מִי שֶׁלֹּא חָג בְּיוֹם טוֹב הָרִאשׁוֹן שֶׁל חַג הַסֻּכּוֹת חוֹגֵג אֶת כָּל הָרֶגֶל וּבַיּוֹם טוֹב הָאַחֲרוֹן שֶׁהוּא שְׁמִינִי וְאַף הַשְּׁמִינִי תַּשְׁלוּמֵי רִאשׁוֹן הוּא. וְכֵן מִי שֶׁלֹּא חָג בְּיוֹם חַג הַשָּׁבוּעוֹת חוֹגֵג כָּל שִׁבְעָה וְיֵשׁ לוֹ תַּשְׁלוּמִין כָּל שֵׁשֶׁת יָמִים שֶׁלְּאַחַר חַג הַשָּׁבוּעוֹת. וְדָבָר זֶה מִפִּי הַשְּׁמוּעָה נֶאֱמַר שֶׁחַג הַשָּׁבוּעוֹת כְּחַג הַמַּצּוֹת לְתַשְׁלוּמִין:","עוֹלַת רְאִיָּה וְשַׁלְמֵי חֲגִיגָה אֵינָן דּוֹחִין לֹא אֶת הַשַּׁבָּת וְלֹא אֶת הַטֻּמְאָה לְפִי שֶׁאֵין לָהֶן זְמַן קָבוּעַ כְּקָרְבְּנוֹת הַצִּבּוּר. שֶׁאִם אֵינוֹ חוֹגֵג הַיּוֹם חוֹגֵג לְמָחָר כְּמוֹ שֶׁבֵּאַרְנוּ. אֲבָל דּוֹחִין אֶת יוֹם טוֹב וְאַף עַל פִּי שֶׁאֵין מַקְרִיבִין בְּיוֹם טוֹב נְדָרִים וּנְדָבוֹת מַקְרִיבִין עוֹלַת רְאִיָּה וְשַׁלְמֵי חֲגִיגָה וְשַׁלְמֵי שִׂמְחָה שֶׁאֵין אֵלּוּ נְדָרִים וּנְדָבוֹת אֶלָּא חוֹבוֹת:","כְּשֶׁמַּקְרִיב הַמַּקְרִיב עוֹלַת רְאִיָּתוֹ וְשַׁלְמֵי חֲגִיגָתוֹ וְשִׂמְחָתוֹ בְּיוֹם טוֹב. סוֹמֵךְ עֲלֵיהֶן בְּכָל כֹּחוֹ כְּדֶרֶךְ שֶׁעוֹשֶׂה בִּשְׁאָר הַיָּמִים. אַף עַל פִּי שֶׁסְּמִיכָה אֵינָהּ מְעַכֶּבֶת כְּמוֹ שֶׁבֵּאַרְנוּ בְּמַעֲשֵׂה הַקָּרְבָּנוֹת לֹא גָּזְרוּ עָלֶיהָ מִשּׁוּם שְׁבוּת:","הַמַּפְרִישׁ עוֹלַת רְאִיָּתוֹ וּמֵת. הַיּוֹרְשִׁין חַיָּבִין לַהֲבִיאָהּ. מֻתָּר לְהַקְרִיב בְּחֻלּוֹ שֶׁל מוֹעֵד נְדָרִים וּנְדָבוֹת שֶׁנֶּאֱמַר (במדבר כט לט) \"אֵלֶּה תַּעֲשׂוּ לַה' בְּמוֹעֲדֵיכֶם לְבַד מִנִּדְרֵיכֶם וְנִדְבֹתֵיכֶם\" מִכְּלַל שֶׁקְּרֵבִין בָּרֶגֶל. (במדבר כט לט) \"לְעלֹתֵיכֶם\" כְּמוֹ עוֹלַת מְצֹרָע וְעוֹלַת יוֹלֶדֶת. (במדבר כט לט) \"וּלְמִנְחֹתֵיכֶם\" לְהָבִיא מִנְחַת חוֹטֵא וּמִנְחַת קְנָאוֹת. (במדבר כט לט) \"וּלְשַׁלְמֵיכֶם\" לְרַבּוֹת שַׁלְמֵי נָזִיר הַכּל קְרֵבִין בַּמּוֹעֵד וְאֵין קְרֵבִין בְּיוֹם טוֹב:","וּמִי שֶׁהָיָה לוֹ אוֹכְלִים מְרֻבִּים וּנְכָסִים מוּעָטִין מֵבִיא שַׁלְמֵי חֲגִיגָה מְרֻבִּין וְעוֹלוֹת רְאִיָּה מוּעָטִין. הָיוּ לוֹ אוֹכְלִין מוּעָטִין וּנְכָסִים מְרֻבִּין מֵבִיא עוֹלוֹת רְאִיָּה מְרֻבּוֹת וְשַׁלְמֵי חֲגִיגָה מוּעָטוֹת. הָיוּ זֶה וְזֶה מוּעָט עַל זֶה אָמְרוּ לֹא יִפְחֹת מִמָּעָה לְעוֹלָה וּשְׁתֵּי כֶּסֶף לִשְׁלָמִים. זֶה וְזֶה מְרֻבֶּה עַל זֶה נֶאֱמַר (דברים טז יז) \"כְּבִרְכַּת ה' אֱלֹהֶיךָ אֲשֶׁר נָתַן לָךְ\":"],"Mishneh Torah, First Fruits and other Gifts to Priests Outside the Sanctuary 7":["שְׁתֵּי עִסּוֹת שֶׁיֵּשׁ בִּשְׁתֵּיהֶן שִׁעוּר הַחַיָּב בְּחַלָּה וְאֵין בְּאַחַת מֵהֶן כַּשִּׁעוּר וְנָגְעוּ זוֹ בְּזוֹ וְנָשְׁכוּ זוֹ אֶת זוֹ אִם הָיוּ שֶׁל שְׁנַיִם אֲפִלּוּ הֵן מִמִּין אֶחָד פְּטוּרִין מִן הַחַלָּה. שֶׁסְּתָם שְׁנַיִם מַקְפִּידִין. וְאִם יָדוּעַ שֶׁאֵינָן מַקְפִּידִין עַל עֵרוּב הָעִסּוֹת הֲרֵי אֵלּוּ מִצְטָרְפוֹת:","הָיוּ שְׁתֵּיהֶן שֶׁל אִישׁ אֶחָד אִם הָיוּ מִמִּין אֶחָד מִצְטָרְפִין וְחַיָּבוֹת בְּחַלָּה וְאִם מִשְּׁנֵי מִינִין הָיוּ אֵין מִצְטָרְפִין. שֶׁסְּתָם אֶחָד אֵינוֹ מַקְפִּיד. וְאִם הָיָה מַקְפִּיד שֶׁלֹּא תִּגַּע עִסָּה זוֹ בְּזוֹ וְלֹא תִּתְעָרֵב עִמָּהּ אֲפִלּוּ הָיוּ מִמִּין אֶחָד אֵין מִצְטָרְפוֹת:","וְכֵיצַד מִצְטָרְפוֹת. אִם הָיוּ שֶׁל אֶחָד מִמִּין אֶחָד עִסַּת הַחִטִּים שֶׁנָּגְעָה בְּעִסַּת הַכֻּסְּמִין מִצְטָרְפוֹת. נָגְעָה בִּשְׁאָר הַמִּינִין אֵין מִצְטָרְפוֹת. וְכֵן עִסַּת שְׂעוֹרִין שֶׁנָּגְעָה בְּעִסַּת הַכֻּסְּמִין אוֹ שִׁבּלֶת שׁוּעָל אוֹ שִׁיפוֹן וְכֵן עִסַּת כֻּסְמִין וְשֶׁל שִׁבּלֶת שׁוּעָל וְשֶׁל שִׁיפוֹן שֶׁנָּגְעָה כָּל אַחַת מִשְּׁלָשְׁתָּן בַּחֲבֶרְתָּהּ הֲרֵי אֵלּוּ מִצְטָרְפוֹת:","עִסַּת חָדָשׁ אֵינָהּ מִצְטָרֶפֶת לְשֶׁל יָשָׁן אַף עַל פִּי שֶׁהֵן מִמִּין אֶחָד. כְּדֵי שֶׁלֹּא יֹאמְרוּ תּוֹרְמִין מִן הֶחָדָשׁ עַל הַיָּשָׁן. וְלֹא יִתְרֹם מֵאֶמְצַע שְׁתֵּיהֶן אֶלָּא יָבִיא עִסָּה אַחֶרֶת חָדָשׁ אוֹ יָשָׁן וְיִצְטָרֵף לָהֶם לְהַשְׁלִים הַשִּׁעוּר. בַּמֶּה דְּבָרִים אֵמוּרִים בְּעִסָּה שֶׁנָּגְעָה בְּעִסָּה אַחֶרֶת. אֲבָל הַבּוֹלֵל קֶמַח חֲמֵשֶׁת הַמִּינִין וְעוֹשֶׂה מֵהֶם עִסָּה אַחַת הֲרֵי חֲמִשְּׁתָּן מִצְטָרְפִין לְשִׁעוּר עִסַּת חַלָּה כְּמוֹ שֶׁבֵּאַרְנוּ:","עִסָּה שֶׁהִיא פְּחוּתָה מִכַּשִּׁעוּר מִכָּאן. וְעִסָּה פְּחוּתָה מִכַּשִּׁעוּר מִכָּאן. וְעִסָּה שֶׁאֵינָהּ חַיֶּבֶת בְּחַלָּה בְּאֶמְצַע כְּגוֹן עִסַּת אֹרֶז אוֹ עִסַּת תְּרוּמָה אוֹ מְדֻמָּע אוֹ עִסַּת עַכּוּ\"ם. אַף עַל פִּי שֶׁנּוֹגְעוֹת זוֹ בָּזוֹ אֵינָן מִצְטָרְפוֹת שֶׁהֲרֵי דָּבָר הַפָּטוּר מִן הַחַלָּה מַבְדִּיל בָּאֶמְצַע:","הָיָה בָּאֶמְצַע עִסָּה שֶׁהוּרְמָה חַלָּתָהּ מִצְטָרְפוֹת שֶׁהָעִסָּה שֶׁבֵּינֵיהֶן כְּבָר הָיְתָה מְחֻיֶּבֶת בְּחַלָּה. וְכֵן אִם הָיָה בֵּינֵיהֶן עִסַּת הֶקְדֵּשׁ מִצְטָרְפוֹת מִפְּנֵי שֶׁרָאוּי לִפְדּוֹתָהּ וְתִתְחַיֵּב בְּחַלָּה. וְכֵן אִם הָיְתָה בֵּינֵיהֶן עִסַּת מִין אַחֵר אוֹ עִסַּת אִישׁ אַחֵר אוֹ עִסַּת חָדָשׁ הֲרֵי שְׁתֵּי הָעִסּוֹת שֶׁבַּצְּדָדִין מִצְטָרְפוֹת לְחַלָּה:","שְׁתֵּי עִסּוֹת שֶׁכָּל אַחַת מֵהֶן פְּחוּתָה מִכַּשִּׁעוּר שֶׁהִפְרִישׁ חַלָּה מִזּוֹ וְחַלָּה מִזּוֹ וְחָזְרוּ וְנָגְעוּ זוֹ בָּזוֹ וַהֲרֵי בִּשְׁתֵּיהֶם כַּשִּׁעוּר חַיָּבִין לְהַפְרִישׁ מֵהֶן חַלָּה שֶׁהַחַלּוֹת הָרִאשׁוֹנוֹת אֵינָן כְּלוּם:","שְׁנֵי עַכּוּ\"ם שֶׁעָשׂוּ עִסָּה כַּשִּׁעוּר וְחִלְּקוּהָ וְאַחַר כָּךְ נִתְגַּיְּרוּ. וְהוֹסִיף כָּל אֶחָד עַל חֶלְקוֹ אַחַר שֶׁנִּתְגַּיֵּר עַד שֶׁהִשְׁלִימוּ לַשִּׁעוּר הֲרֵי זוֹ חַיֶּבֶת. שֶׁלֹּא הָיְתָה לָהּ שְׁעַת חוֹבָה כְּשֶׁהָיוּ עַכּוּ\"ם שֶׁהֲרֵי פָּחוֹת מִכַּשִּׁעוּר הָיָה בְּיַד כָּל אֶחָד מֵהֶן:","אֲבָל שְׁנֵי יִשְׂרְאֵלִים שֶׁעָשׂוּ כָּךְ וְחָזַר כָּל אֶחָד אַחַר שֶׁחִלְּקוּ וְהוֹסִיף עַל חֶלְקוֹ עַד שֶׁהִשְׁלִימוֹ לַשִּׁעוּר הֲרֵי זוֹ פְּטוּרָה. שֶׁכְּבָר הָיְתָה לָהּ שְׁעַת חוֹבָה וְהֵן הָיוּ פְּטוּרִין בְּאוֹתָהּ שָׁעָה מִפְּנֵי שֶׁעֲשָׂאוּהָ לְחַלֵּק:","הָיְתָה הָעִסָּה בְּיַד הָעַכּוּ\"ם וְהַיִּשְׂרָאֵל בְּשֻׁתָּפוּת וְחִלְּקוּ. וְאַחַר כָּךְ נִתְגַּיֵּר הָעַכּוּ\"ם וְהוֹסִיף הַגֵּר עַל שֶׁלּוֹ [וְיִשְׂרָאֵל עַל שֶׁלּוֹ] עַד שֶׁהִשְׁלִים כָּל אֶחָד עִסָּתוֹ לַשִּׁעוּר שֶׁל יִשְׂרָאֵל חַיֶּבֶת וְשֶׁל עַכּוּ\"ם פְּטוּרָה:","הַנּוֹטֵל שְׂאוֹר מֵעִסָּה שֶׁלֹּא הוּרְמָה חַלָּתָהּ וּנְתָנוֹ לְתוֹךְ עִסָּה שֶׁהוּרְמָה חַלָּתָהּ הֲרֵי זֶה מֵבִיא עִסָּה שְׁנִיָּה שֶׁיִּהְיֶה בָּהּ עִם שְׂאוֹר זֶה שִׁעוּר עִסָּה שֶׁחַיֶּבֶת בְּחַלָּה וְנוֹתְנָהּ בְּתוֹךְ הָעִסָּה שֶׁהוּרְמָה חַלָּתָהּ. וּמַפְרֵשׁ מִן הָעִסָּה הַשְּׁנִיָּה שִׁעוּר חַלָּה עָלֶיהָ וְעַל הַשְּׂאוֹר כְּדֵי שֶׁיִּטּל מִן הַמֻּקָּף. וְאִם אֵין לוֹ עִסָּה שְׁנִיָּה נַעֲשֵׂית זוֹ כֻּלָּהּ טֶבֶל וּמַפְרִישׁ חַלָּה עַל הַכּל שֶׁהַטֶּבֶל בְּמִינוֹ אוֹסֵר בְּכָל שֶׁהוּא:","עִסָּה הַטְּבוּלָה לְחַלָּה אֵינָהּ כְּחַלָּה. וַהֲרֵי הִיא כְּחֻלִּין לְעִנְיַן הַטֻּמְאָה. שֶּׁאֵין הַשֵּׁנִי עוֹשֶׂה שְׁלִישִׁי בְּחֻלִּין כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ. וּמֻתָּר לִגְרֹם טֻמְאָה לְחֻלִּין שֶׁבְּאֶרֶץ יִשְׂרָאֵל. לְפִיכָךְ שְׁתֵּי עִסּוֹת אַחַת טְמֵאָה וְאַחַת טְהוֹרָה נוֹטֵל כְּדֵי חַלַּת שְׁתֵּיהֶם מֵעִסָּה שֶׁלֹּא הוּרְמָה חַלָּתָהּ וְנוֹתְנוֹ בָּאֶמְצַע סָמוּךְ לָעִסָּה הַטְּהוֹרָה וּמוֹשֵׁךְ מִן הַטְּמֵאָה לַטְּהוֹרָה כְּדֵי בֵּיצָה כְּדֵי לִתְרֹם מִן הַמֻּקָּף:","עוֹשֶׂה אָדָם עִסָּה טְהוֹרָה וְאֵינוֹ מַפְרִישׁ חַלָּתָהּ וּמַנִּיחָהּ אוֹ מַנִּיחַ מִקְּצָתָהּ לִהְיוֹת מַפְרִישׁ עָלֶיהָ וְהוֹלֵךְ חַלּוֹת שֶׁל עִסּוֹת אֲחֵרוֹת. וַאֲפִילוּ נִטְמְאוּ הָעִסּוֹת עַד שֶׁתֵּעָשֶׂה הָעִסָּה שֶׁהִנִּיחַ כֻּלָּהּ חַלָּה וְיִתְּנֶנָּה לַכֹּהֵן. וְהוּא שֶׁלֹּא תִּפָּסֵל מֵאֹכֶל אָדָם. אֲבָל מִשֶּׁתִּסְרַח אֵינוֹ מַפְרִישׁ עָלֶיהָ. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיוּ אוֹתָם הָעִסּוֹת שֶׁמַּפְרִישׁ עֲלֵיהֶן סָפֵק אִם הוּרְמָה חַלָּה מֵהֶן אוֹ לֹא הוּרְמָה שֶׁחַלַּת דְּמַאי נִטֶּלֶת מִן הַטָּהוֹר עַל הַטָּמֵא לְכַתְּחִלָּה וְשֶׁלֹּא מִן הַמֻּקָּף:"],"Mishneh Torah, Forbidden Foods 10":["כָּל אִסּוּרִין שֶׁאָמַרְנוּ הֵן בְּמִינֵי נֶפֶשׁ חַיָּה. וְיֵשׁ אִסּוּרִין אֲחֵרִים שֶׁל תּוֹרָה בְּזֶרַע הָאָרֶץ וְהֵן הֶחָדָשׁ וְכִלְאֵי הַכֶּרֶם וְהַטֶּבֶל וְהָעָרְלָה:","הֶחָדָשׁ כֵּיצַד. כָּל אֶחָד מֵחֲמִשָּׁה מִינֵי תְּבוּאָה בִּלְבַד אָסוּר לֶאֱכל מֵהֶחָדָשׁ שֶׁלּוֹ קֹדֶם שֶׁיִּקָּרֵב הָעֹמֶר בְּט\"ז בְּנִיסָן שֶׁנֶּאֱמַר (ויקרא כג יד) \"וְלֶחֶם וְקָלִי וְכַרְמֶל לֹא תֹאכְלוּ\". וְכָל הָאוֹכֵל כְּזַיִת חָדָשׁ קֹדֶם הַקְרָבַת הָעֹמֶר לוֹקֶה מִן הַתּוֹרָה בְּכָל מָקוֹם וּבְכָל זְמַן בֵּין בָּאָרֶץ בֵּין בְּחוּצָה לָאָרֶץ בֵּין בִּפְנֵי הַבַּיִת בֵּין שֶׁלֹּא בִּפְנֵי הַבַּיִת. אֶלָּא שֶׁבִּזְמַן שֶׁיֵּשׁ מִקְדָּשׁ מִשֶּׁיִּקָּרֵב הָעֹמֶר הֻתַּר הֶחָדָשׁ בִּירוּשָׁלַיִם. וְהַמְּקוֹמוֹת הָרְחוֹקִין מֻתָּרִין אַחַר חֲצוֹת שֶׁאֵין בֵּית דִּין מִתְעַצְּלִין בּוֹ עַד אַחַר חֲצוֹת. וּבִזְמַן שֶׁאֵין בֵּית הַמִּקְדָּשׁ כָּל הַיּוֹם כֻּלּוֹ אָסוּר מִן הַתּוֹרָה. וּבַזְּמַן הַזֶּה בִּמְקוֹמוֹת שֶׁעוֹשִׂין שְׁנֵי יָמִים טוֹבִים הֶחָדָשׁ אָסוּר כָּל יוֹם י\"ז בְּנִיסָן עַד לָעֶרֶב מִדִּבְרֵי סוֹפְרִים:","הָאוֹכֵל לֶחֶם וְקָלִי וְכַרְמֶל כְּזַיִת מִכָּל אֶחָד וְאֶחָד לוֹקֶה שָׁלֹשׁ מַלְקִיּוֹת שֶׁנֶּאֱמַר (ויקרא כג יד) \"וְלֶחֶם וְקָלִי וְכַרְמֶל לֹא תֹאכְלוּ\". מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁשְּׁלָשְׁתָּן בַּלָּאוִין חֲלוּקִין זֶה מִזֶּה:","כָּל תְּבוּאָה שֶׁהִשְׁרִישָׁה קֹדֶם הַקְרָבַת הָעֹמֶר אַף עַל פִּי שֶׁלֹּא נִגְמְרָה אֶלָּא אַחַר שֶׁקָּרַב מֻתֶּרֶת בַּאֲכִילָה מִשֶּׁקָּרַב הָעֹמֶר. וּתְבוּאָה שֶׁהִשְׁרִישָׁה אַחַר שֶׁקָּרַב הָעֹמֶר אַף עַל פִּי שֶׁהָיְתָה זְרוּעָה קֹדֶם שֶׁקָּרַב הָעֹמֶר הֲרֵי זוֹ אֲסוּרָה עַד שֶׁיִּקָּרֵב הָעֹמֶר שֶׁל שָׁנָה הַבָּאָה. וְדִין זֶה בְּכָל מָקוֹם וּבְכָל זְמַן מִן הַתּוֹרָה:","תְּבוּאָה שֶׁהִשְׁרִישָׁה אַחַר הָעֹמֶר וּקְצָרָה וְזָרַע מִן הַחִטִּים בַּקַּרְקַע. וְאַחַר כָּךְ קָרַב הָעֹמֶר הַבָּא וַעֲדַיִן הַחִטִּים בַּקַּרְקַע. הֲרֵי אֵלּוּ סָפֵק אִם הִתִּירָן הָעֹמֶר כְּאִלּוּ הָיוּ מֻנָּחִין בְּכַד. אוֹ לֹא יַתִּיר אוֹתָן מִפְּנֵי שֶׁבָּטְלוּ בַּקַּרְקַע. לְפִיכָךְ אִם לִקֵּט מֵהֶם וְאָכַל אֵינוֹ לוֹקֶה. וּמַכִּין אוֹתוֹ מַכַּת מַרְדּוּת. וְכֵן שִׁבּלֶת שֶׁהֵבִיאָה שְׁלִישׁ מִלִּפְנֵי הָעֹמֶר וַעֲקָרָהּ וּשְׁתָלָהּ אַחַר שֶׁקָּרַב הָעֹמֶר וְהוֹסִיפָה הֲרֵי זוֹ סָפֵק אִם תִּהְיֶה אֲסוּרָה מִפְּנֵי הַתּוֹסֶפֶת עַד שֶׁיָּבוֹא הָעֹמֶר הַבָּא אוֹ לֹא תִּהְיֶה אֲסוּרָה שֶׁהֲרֵי הִשְׁרִישָׁה קֹדֶם הָעֹמֶר:","כִּלְאֵי הַכֶּרֶם כֵּיצַד. מִין מִמִּינֵי תְּבוּאָה אוֹ מִינֵי יְרָקוֹת שֶׁנִּזְרְעוּ עִם הַגֶּפֶן. בֵּין שֶׁזָּרַע יִשְׂרָאֵל בֵּין שֶׁזָּרַע נָכְרִי. בֵּין שֶׁעָלוּ מֵאֲלֵיהֶן. בֵּין שֶׁנָּטַע הַגֶּפֶן בְּתוֹךְ הָיָּרָק. שְׁנֵיהֶם אֲסוּרִין בַּאֲכִילָה וּבַהֲנָיָה שֶׁנֶּאֱמַר (דברים כב ט) \"פֶּן תִּקְדַּשׁ הַמְּלֵאָה הַזֶּרַע אֲשֶׁר תִּזְרָע וּתְבוּאַת הַכָּרֶם\". כְּלוֹמַר פֶּן תִּתְרַחֵק וְתֶאֱסֹר שְׁנֵיהֶם:","וְהָאוֹכֵל כְּזַיִת מִכִּלְאֵי הַכֶּרֶם בֵּין מִן הַיָּרָק בֵּין מִן הָעֲנָבִים לוֹקֶה מִן הַתּוֹרָה. וּשְׁנֵיהֶם מִצְטָרְפִין זֶה עִם זֶה:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁנִּזְרְעוּ בְּאֶרֶץ יִשְׂרָאֵל. אֲבָל בְּחוּצָה לָאָרֶץ כִּלְאֵי הַכֶּרֶם מִדִּבְרֵי סוֹפְרִים. וּבְהִלְכוֹת כִּלְאַיִם יִתְבָּאֵר אֵי זֶה מִין אָסוּר בְּכִלְאֵי הַכֶּרֶם וְאֵי זֶה מִין אֵינוֹ אָסוּר וְהֵיאַךְ יֶאֱסֹר וּמָתַי יֵאָסֵר וְאֵי זֶה דָּבָר מְקַדֵּשׁ וְאֵי זֶה אֵינוֹ מְקַדֵּשׁ:","הָעָרְלָה כֵּיצַד. כָּל הַנּוֹטֵעַ אִילַן מַאֲכָל כָּל פֵּרוֹת שֶׁעוֹשֶׂה אוֹתוֹ אִילָן שָׁלֹשׁ שָׁנִים מִשֶּׁנָּטַע הֲרֵי הֵן אֲסוּרִין בַּאֲכִילָה וּבַהֲנָאָה שֶׁנֶּאֱמַר (ויקרא יט כג) \"שָׁלֹשׁ שָׁנִים יִהְיֶה לָכֶם עֲרֵלִים לֹא יֵאָכֵל\". וְכָל הָאוֹכֵל מֵהֶם כְּזַיִת לוֹקֶה מִן הַתּוֹרָה:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּנוֹטֵעַ בְּאֶרֶץ יִשְׂרָאֵל שֶׁנֶּאֱמַר (ויקרא יט כג) \"כִּי תָבֹאוּ אֶל הָאָרֶץ\" וְגוֹ'. אֲבָל אִסּוּר עָרְלָה בְּחוּצָה לָאָרֶץ הֲלָכָה לְמשֶׁה מִסִּינַי שֶׁוַּדַּאי הָעָרְלָה בְּחוּצָה לָאָרֶץ אֲסוּרָה וּסְפֵקָהּ מֻתָּר. וּבְהִלְכוֹת מַעֲשֵׂר שֵׁנִי יִתְבָּאֵר דְּבָרִים הָאֲסוּרִין מִשּׁוּם עָרְלָה וּדְבָרִים הַמֻּתָּרִין:","סְפֵק עָרְלָה וְכִלְאֵי הַכֶּרֶם בְּאֶרֶץ יִשְׂרָאֵל אָסוּר. בְּסוּרְיָא וְהִיא אֲרָצוֹת שֶׁכָּבַשׁ דָּוִד מֻתָּר. כֵּיצַד. הָיָה כֶּרֶם וְעָרְלָה וַעֲנָבִים נִמְכָּרוֹת חוּצָה לוֹ. הָיָה יָרָק זָרוּעַ בְּתוֹכוֹ וְיָרָק נִמְכָּר חוּצָה לוֹ. שֶׁמָּא מִמֶּנּוּ הוּא זֶה שֶׁמָּא מֵאַחֵר. בְּסוּרְיָא מֻתָּר. וּבְחוּץ לָאָרֶץ אֲפִלּוּ רָאָה הָעֲנָבִים יוֹצְאוֹת מִכֶּרֶם עָרְלָה אוֹ יָרָק יוֹצֵא מִן הַכֶּרֶם לוֹקֵחַ מֵהֶן. וְהוּא שֶׁלֹּא יִרְאֶה אוֹתוֹ בּוֹצֵר מִן הָעָרְלָה אוֹ לוֹקֵט הַיָּרָק בְּיָדוֹ:","כֶּרֶם שֶׁהוּא סְפֵק עָרְלָה אוֹ סְפֵק כִּלְאַיִם בְּאֶרֶץ יִשְׂרָאֵל אָסוּר וּבְסוּרְיָא מֻתָּר. וְאֵין צָרִיךְ לוֹמַר בְּחוּצָה לָאָרֶץ:","חָבִית יַיִן הַנִּמְצֵאת טְמוּנָה בְּפַרְדֵּס שֶׁל עָרְלָה אֲסוּרָה בִּשְׁתִיָּה וּמֻתֶּרֶת בַּהֲנָיָה שֶׁאֵין הַגַּנָּב גּוֹנֵב מִמָּקוֹם וְטוֹמֵן בּוֹ. אֲבָל עֲנָבִים הַנִּמְצָאִין טְמוּנִים שָׁם אֲסוּרִים שֶׁמָּא מִשָּׁם נִלְקְטוּ וְהִצְנִיעָן שָׁם:","נָכְרִי וְיִשְׂרָאֵל שֶׁהָיוּ שֻׁתָּפִין בִּנְטִיעָה אִם הִתְנוּ מִתְּחִלַּת הַשֻּׁתָּפוּת שֶׁיִּהְיֶה הַנָּכְרִי אוֹכֵל שְׁנֵי עָרְלָה וְיִשְׂרָאֵל אוֹכֵל שָׁלֹשׁ שָׁנִים מִשְּׁנֵי הֶתֵּר כְּנֶגֶד שְׁנֵי הָעָרְלָה הֲרֵי זֶה מֻתָּר. וְאִם לֹא הִתְנוּ מִתְּחִלָּה אָסוּר וּבִלְבַד שֶׁלֹּא יָבֹאוּ לְחֶשְׁבּוֹן. כֵּיצַד. כְּגוֹן שֶׁיַּחְשֹׁב כַּמָּה פֵּרוֹת אָכַל הַנָּכְרִי בִּשְׁנֵי עָרְלָה עַד שֶׁיֹּאכַל יִשְׂרָאֵל כְּנֶגֶד אוֹתָן הַפֵּרוֹת. אִם הִתְנוּ כָּזֶה אָסוּר שֶׁהֲרֵי זֶה כְּמַחֲלִיף פֵּרוֹת עָרְלָה:","יֵרָאֶה לִי שֶׁאֵין דִּין נֶטַע רְבָעִי נוֹהֵג בְּחוּצָה לָאָרֶץ אֶלָּא אוֹכֵל פֵּרוֹת שָׁנָה רְבִיעִית בְּלֹא פִּדְיוֹן כְּלָל שֶׁלֹּא אָמְרוּ אֶלָּא הָעָרְלָה. וְקַל וָחֹמֶר הַדְּבָרִים וּמַה סּוּרְיָא שֶׁהִיא חַיֶּבֶת בְּמַעַשְׂרוֹת וּבִשְׁבִיעִית מִדִּבְרֵיהֶם אֵינָהּ חַיֶּבֶת בְּנֶטַע רְבָעִי כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת מַעֲשֵׂר שֵׁנִי. חוּצָה לָאָרֶץ לֹא כָּל שֶׁכֵּן שֶׁלֹּא יִהְיֶה נֶטַע רְבָעִי נוֹהֵג בָּהּ. אֲבָל בְּאֶרֶץ יִשְׂרָאֵל נוֹהֵג בָּהּ בֵּין בִּפְנֵי הַבַּיִת בֵּין שֶׁלֹּא בִּפְנֵי הַבַּיִת. וְהוֹרוּ מִקְצָת גְּאוֹנִים שֶׁכֶּרֶם רְבָעִי לְבַדּוֹ פּוֹדִין אוֹתוֹ בְּחוּצָה לָאָרֶץ וְאַחַר כָּךְ יִהְיֶה מֻתָּר בַּאֲכִילָה. וְאֵין לְדָבָר זֶה עִקָּר:","פֵּרוֹת שָׁנָה רְבִיעִית כֻּלָּהּ אָסוּר לֶאֱכל מֵהֶן בְּאֶרֶץ יִשְׂרָאֵל עַד שֶׁיִּפָּדוּ. וּבְהִלְכוֹת מַעֲשֵׂר שֵׁנִי יִתְבָּאֵר מִשְׁפְּטֵי פִּדְיוֹנָן וְדִין אֲכִילָתָן וּמֵאֵימָתַי מוֹנִין לְעָרְלָה וְלִרְבָעִי:","כֵּיצַד פּוֹדִין פֵּרוֹת נֶטַע רְבָעִי בַּזְּמַן הַזֶּה. אַחַר שֶׁאוֹסֵף אוֹתָן מְבָרֵךְ. בָּרוּךְ אַתָּה ה' אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ עַל פִּדְיוֹן נֶטַע רְבָעִי. וְאַחַר כָּךְ פּוֹדֶה אֶת כֻּלָּן וַאֲפִלּוּ בִּפְרוּטָה אַחַת וְאוֹמֵר הֲרֵי אֵלּוּ פְּדוּיִין בִּפְרוּטָה זוֹ וּמַשְׁלִיךְ אוֹתָהּ פְּרוּטָה לְיָם הַמֶּלַח אוֹ מְחַלְּלָן עַל שְׁוֵה פְּרוּטָה מִפֵּרוֹת אֲחֵרוֹת. וְאוֹמֵר הֲרֵי כָּל הַפֵּרוֹת הָאֵלּוּ מְחֻלָּלִין עַל חִטִּים אֵלּוּ אוֹ עַל שְׂעוֹרִים אֵלּוּ וְכַיּוֹצֵא בָּהֶן. וְשׂוֹרֵף אוֹתָן כְּדֵי שֶׁלֹּא יִהְיוּ תַּקָּלָה לַאֲחֵרִים. וְאוֹכֵל כָּל הַפֵּרוֹת:","הוֹרוּ מִקְצָת הַגְּאוֹנִים שֶׁאַף עַל פִּי שֶׁפָּדָה פֵּרוֹת שָׁנָה רְבִיעִית אוֹ חִלְּלָן אָסוּר לְאָכְלָן עַד שֶׁתִּכָּנֵס שָׁנָה חֲמִישִׁית. וְדָבָר זֶה אֵין לוֹ עִקָּר. וְיֵרָאֶה לִי שֶׁזּוֹ שִׁגְגַת הוֹרָאָה וְהַטַּעַם לְפִי שֶׁכָּתוּב (ויקרא יט כה) \"וּבַשָּׁנָה הַחֲמִישִׁת תֹּאכְלוּ אֶת פִּרְיוֹ\" וְאֵין עִנְיָן הַכָּתוּב אֶלָּא שֶׁבַּשָּׁנָה הַחֲמִישִׁית תֹּאכְלוּ פִּרְיוֹ בְּלֹא פִּדְיוֹן כְּכָל חֻלִּין שֶׁבָּעוֹלָם. וְאֵין רָאוּי לָחוּשׁ לְהוֹרָאָה זוֹ:","הַטֶּבֶל כֵּיצַד. כָּל אֹכֶל שֶׁהוּא חַיָּב לְהַפְרִישׁ מִמֶּנּוּ תְּרוּמָה וּמַעַשְׂרוֹת קֹדֶם שֶׁיַּפְרִישׁ מִמֶּנּוּ נִקְרָא טֶבֶל וְאָסוּר לֶאֱכל מִמֶּנּוּ שֶׁנֶּאֱמַר (ויקרא כב טו) \"וְלֹא יְחַלְּלוּ אֶת קָדְשֵׁי בְּנֵי יִשְׂרָאֵל אֵת אֲשֶׁר יָרִימוּ לַה'\". כְּלוֹמַר לֹא יִנְהֲגוּ בָּהֶן מִנְהַג חֻלִּין וַעֲדַיִן קָדָשִׁים שֶׁעֲתִידִין לְהִתָּרֵם לֹא הוּרְמוּ. וְהָאוֹכֵל כְּזַיִת מִן הַטֶּבֶל קֹדֶם שֶׁיַּפְרִישׁ מִמֶּנּוּ תְּרוּמָה גְּדוֹלָה וּתְרוּמַת מַעֲשֵׂר חַיָּב מִיתָה בִּידֵי שָׁמַיִם שֶׁנֶּאֱמַר וְלֹא יְחַלְּלוּ אֶת קָדְשֵׁי בְּנֵי יִשְׂרָאֵל וְגוֹ' וְהִשִּׂיאוּ אוֹתָם עֲוֹן אַשְׁמָה:","אֲבָל הָאוֹכֵל מִדָּבָר שֶׁנִּטְּלָה מִמֶּנּוּ תְּרוּמָה גְּדוֹלָה וּתְרוּמַת מַעֲשֵׂר וַעֲדַיִן לֹא הִפְרִישׁ מִמֶּנּוּ מַעַשְׂרוֹת וַאֲפִלּוּ לֹא נִשְׁאַר בּוֹ אֶלָּא מַעֲשַׂר עָנִי הֲרֵי זֶה לוֹקֶה מִשּׁוּם אוֹכֵל טֶבֶל. וְאֵין בּוֹ מִיתָה שֶׁאֵין עֲוֹן מִיתָה אֶלָּא בִּתְרוּמָה גְּדוֹלָה וּתְרוּמַת מַעֲשֵׂר:","אַזְהָרָה לָאוֹכֵל טֶבֶל שֶׁלֹּא הוּרְמוּ מִמֶּנּוּ מַעַשְׂרוֹת בִּכְלָל שֶׁנֶּאֱמַר (דברים יב יז) \"לֹא תוּכַל לֶאֱכל בִּשְׁעָרֶיךָ מַעֲשַׂר דְּגָנְךָ\" וְגוֹ'. וּבְהִלְכוֹת תְּרוּמוֹת וּמַעַשְׂרוֹת יִתְבָּאֵר אֵיזֶה דָּבָר חַיָּב בִּתְרוּמָה וּבְמַעַשְׂרוֹת וְאֵי זֶה דָּבָר פָּטוּר. וְאֵי זֶה דָּבָר הוּא חַיָּב מִן הַתּוֹרָה וְאֵי זֶהוּ הַחַיָּב מִדִּבְרֵי סוֹפְרִים. וְהָאוֹכֵל כְּזַיִת מִטֶּבֶל שֶׁל דִּבְרֵיהֶם אוֹ מִכִּלְאֵי הַכֶּרֶם וְעָרְלָה שֶׁל חוּצָה לָאָרֶץ מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","הַטֶּבֶל וְהֶחָדָשׁ וְהַהֶקְדֵּשׁ וּסְפִיחֵי שְׁבִיעִית וְהַכִּלְאַיִם וְהָעָרְלָה מַשְׁקִין הַיּוֹצְאִין מִפֵּרוֹתֵיהֶן אֲסוּרִים כְּמוֹתָן וְאֵין לוֹקִין עֲלֵיהֶן. חוּץ מִיַּיִן וְשֶׁמֶן שֶׁל עָרְלָה וְיַיִן שֶׁל כִּלְאֵי הַכֶּרֶם שֶׁלּוֹקִין עֲלֵיהֶן כְּדֶרֶךְ שֶׁלּוֹקִין עַל הַזֵּיתִים וְעַל הָעֲנָבִים שֶׁלָּהֶן:","וְיֵשׁ בְּקָדָשִׁים אִסּוּרִין אֲחֵרִים בְּמַאֲכָלוֹת וְכֻלָּן שֶׁל תּוֹרָה הֵן. כְּגוֹן אִסּוּרִין שֶׁיֵּשׁ בַּאֲכִילַת תְּרוּמוֹת וּבִכּוּרִים וְחַלָּה וּמַעֲשֵׂר שֵׁנִי. וְאִסּוּרִין שֶׁיֵּשׁ בְּקָדְשֵׁי מִזְבֵּחַ כְּגוֹן פִּגּוּל וְנוֹתָר וְטָמֵא. וְכָל אֶחָד מֵהֶן יִתְבָּאֵר בִּמְקוֹמוֹ:","וְשִׁעוּר כָּל אֲכִילָה מֵהֶן כְּזַיִת בֵּין לְמַלְקוֹת בֵּין לְכָרֵת. וּכְבָר בֵּאַרְנוּ אִסּוּר חָמֵץ בְּפֶסַח וְדִינָיו בְּהִלְכוֹת חָמֵץ וּמַצָּה. אֲבָל אִסּוּר אֲכִילָה בְּיוֹם הַכִּפּוּרִים אִסּוּר מִין בִּפְנֵי עַצְמוֹ. וְכֵן אִסּוּר יוֹצֵא מִגֶּפֶן עַל הַנָּזִיר אֵינוֹ שָׁוֶה בַּכּל. וּלְפִיכָךְ יִתְבָּאֵר אִסּוּר כָּל אֶחָד מֵהֶן וְשִׁעוּרוֹ וְדִינָיו בִּמְקוֹמוֹ הָרָאוּי לוֹ:"],"Mishneh Torah, Forbidden Foods 6":["הָאוֹכֵל כְּזַיִת מִן הַדָּם בְּמֵזִיד חַיָּב כָּרֵת בְּשׁוֹגֵג מֵבִיא חַטָּאת קְבוּעָה. וְדָבָר מְפֹרָשׁ בַּתּוֹרָה שֶׁאֵינוֹ חַיָּב אֶלָּא עַל דַּם בְּהֵמָה חַיָּה וְעוֹף בִּלְבַד בֵּין טְמֵאִין בֵּין טְהוֹרִין שֶׁנֶּאֱמַר (ויקרא ז כו) \"וְכָל דָּם לֹא תֹאכְלוּ בְּכל מוֹשְׁבֹתֵיכֶם לָעוֹף וְלַבְּהֵמָה\". וְחַיָּה בִּכְלַל בְּהֵמָה שֶׁנֶּאֱמַר (דברים יד ד) \"זֹאת הַבְּהֵמָה אֲשֶׁר תֹּאכֵלוּ שׁוֹר\" וְגוֹ' (דברים יד ה) \"אַיָּל וּצְבִי\" וְגוֹ'. אֲבָל דַּם דָּגִים וַחֲגָבִים וּשְׁקָצִים וּרְמָשִׂים וְדַם הָאָדָם אֵין חַיָּבִין עָלָיו מִשּׁוּם דָּם. לְפִיכָךְ דַּם דָּגִים וַחֲגָבִים טְהוֹרִים מֻתָּר לְאָכְלוֹ וַאֲפִלּוּ כְּנָסוֹ בִּכְלִי וְשָׁתָהוּ מֻתָּר. וְדַם חֲגָבִים וְדָגִים טְמֵאִים אָסוּר מִשּׁוּם שֶׁהוּא תַּמְצִית גּוּפָן כַּחֲלֵב בְּהֵמָה טְמֵאָה. וְדַם שְׁקָצִים כִּבְשָׂרָן כְּמוֹ שֶׁבֵּאַרְנוּ:","דַּם הָאָדָם אָסוּר מִדִּבְרֵי סוֹפְרִים אִם פֵּרַשׁ. וּמַכִּין עָלָיו מַכַּת מַרְדּוּת. אֲבָל דַּם הַשִּׁנַּיִם בּוֹלְעוֹ וְאֵינוֹ נִמְנַע. הֲרֵי שֶׁנָּשַׁךְ בְּפַת וּמָצָא עָלֶיהָ דָּם גּוֹרֵר אֶת הַדָּם וְאַחַר כָּךְ אוֹכֵל שֶׁהֲרֵי פֵּרַשׁ:","אֵין חַיָּבִין כָּרֵת אֶלָּא עַל דָּם הַיּוֹצֵא בִּשְׁעַת שְׁחִיטָה וּנְחִירָה אוֹ הַתָּזַת הָרֹאשׁ כָּל זְמַן שֶׁיֵּשׁ בּוֹ אַדְמוּמִית. וְעַל הַדָּם הַכָּנוּס בְּתוֹךְ הַלֵּב. וְעַל דַּם הַקָּזָה כָּל זְמַן שֶׁהוּא מְקַלֵּחַ וְיוֹצֵא. אֲבָל הַדָּם הַשּׁוֹתֵת בִּתְחִלַּת הַקָּזָה קֹדֶם שֶׁיַּתְחִיל לְקַלֵּחַ וְדָם הַשּׁוֹתֵת בְּסוֹף הַקָּזָה כְּשֶׁיַּתְחִיל הַדָּם לִפְסֹק אֵין חַיָּבִין עָלָיו וַהֲרֵי הוּא כְּדַם הָאֵיבָרִים. שֶׁדַּם הַקִּלּוּחַ הוּא הַדָּם שֶׁהַנֶּפֶשׁ יוֹצְאָה בּוֹ:","דַּם הַתַּמְצִית וְדַם הָאֵיבָרִין כְּגוֹן דַּם הַטְּחוֹל וְדַם הַכְּלָיוֹת וְדַם בֵּיצִים וְדָם הַמִּתְכַּנֵּס לַלֵּב בִּשְׁעַת שְׁחִיטָה וְדָם הַנִּמְצָא בַּכָּבֵד אֵין חַיָּבִין עָלָיו כָּרֵת. אֲבָל הָאוֹכֵל מִמֶּנּוּ כְּזַיִת לוֹקֶה שֶׁנֶּאֱמַר (ויקרא ג יז) (ויקרא ז כו) \"וְכָל דָּם לֹא תֹאכֵלוּ\". וּבְחִיּוּב כָּרֵת הוּא אוֹמֵר (ויקרא יז יא) \"כִּי נֶפֶשׁ הַבָּשָׂר בַּדָּם הִיא\" אֵינוֹ חַיָּב כָּרֵת אֶלָּא עַל הַדָּם שֶׁהַנֶּפֶשׁ יוֹצְאָה בּוֹ:","הַשָּׁלִיל הַנִּמְצָא בִּמְעֵי הַבְּהֵמָה הֲרֵי דָּמוֹ כְּדַם הַיָּלוּד. לְפִיכָךְ הַדָּם הַנִּמְצָא כָּנוּס בְּתוֹךְ לִבּוֹ חַיָּבִין עָלָיו כָּרֵת אֲבָל שְׁאָר דָּמוֹ הֲרֵי הוּא כְּדַם הָאֵיבָרִין:","הַלֵּב בֵּין לְצָלִי בֵּין לִקְדֵרָה קוֹרְעוֹ וּמוֹצִיא אֶת דָּמוֹ וְאַחַר כָּךְ מוֹלְחוֹ. וְאִם בִּשֵּׁל הַלֵּב וְלֹא קְרָעוֹ קוֹרְעוֹ אַחַר שֶׁבִּשְּׁלוֹ וּמֻתָּר. וְאִם לֹא קְרָעוֹ וַאֲכָלוֹ אֵינוֹ חַיָּב עָלָיו כָּרֵת. בַּמֶּה דְּבָרִים אֲמוּרִים בְּלֵב הָעוֹף שֶׁאֵין בּוֹ כְּזַיִת דָּם. אֲבָל אִם הָיָה לֵב בְּהֵמָה חַיָּב כָּרֵת שֶׁהֲרֵי יֵשׁ בּוֹ כְּזַיִת מִדָּם שֶׁבְּתוֹךְ הַלֵּב שֶׁחַיָּבִין עָלָיו כָּרֵת:","הַכָּבֵד אִם חֲתָכָהּ וְהִשְׁלִיכָהּ לְתוֹךְ הַחֹמֶץ אוֹ לְתוֹךְ מַיִם רוֹתְחִין עַד שֶׁתִּתְלַבֵּן הֲרֵי זוֹ מֻתֶּרֶת לְבַשֵּׁל אוֹתָהּ אַחַר כֵּן. וּכְבָר נָהֲגוּ כָּל יִשְׂרָאֵל לְהַבְהֲבָהּ עַל הָאוּר וְאַחַר כָּךְ מְבַשְּׁלִין אוֹתָהּ בֵּין שֶׁבִּשְּׁלָהּ לְבַדָּהּ בֵּין שֶׁבִּשְּׁלָהּ עִם בָּשָׂר אַחֵר. וְכֵן מִנְהָג פָּשׁוּט שֶׁאֵין מְבַשְּׁלִין הַמֹּחַ שֶׁל רֹאשׁ וְלֹא קוֹלִין אוֹתוֹ עַד שֶׁמְּהַבְהֲבִין אוֹתוֹ בָּאוּר:","הַכָּבֵד שֶׁבִּשְּׁלָהּ וְלֹא הִבְהֲבָהּ עַל הָאוּר וְלֹא חֲלָטָהּ בְּחֹמֶץ אוֹ בְּרוֹתְחִין הֲרֵי הַקְּדֵרָה כֻּלָּהּ אֲסוּרָה הַכָּבֵד וְכָל שֶׁנִתְבַּשֵּׁל עִמָּהּ. וּמֻתָּר לִצְלוֹת כָּבֵד עִם הַבָּשָׂר בְּשִׁפּוּד אֶחָד וְהוּא שֶׁתִּהְיֶה הַכָּבֵד לְמַטָּה. וְאִם עָבַר וּצְלָאָהּ לְמַעְלָה מִבָּשָׂר הֲרֵי זֶה אוֹכְלוֹ:","הַטְּחוֹל מֻתָּר לְבַשְּׁלוֹ אֲפִלּוּ עִם הַבָּשָׂר שֶׁאֵינוֹ דָּם אֶלָּא בָּשָׂר הַדּוֹמֶה לְדָם. הַשּׁוֹבֵר מִפְרֶקֶת בְּהֵמָה קֹדֶם שֶׁתֵּצֵא נַפְשָׁהּ הֲרֵי הַדָּם נִבְלַע בָּאֵיבָרִים וְאָסוּר לֶאֱכל מִמֶּנָּה בָּשָׂר חַי וַאֲפִלּוּ חֲלָטוֹ. אֶלָּא כֵּיצַד יַעֲשֶׂה. יַחְתֹּךְ הַחֲתִיכָה וְיִמְלַח יָפֶה יָפֶה וְאַחַר כָּךְ יְבַשֵּׁל אוֹ יִצְלֶה. וּכְבָר בֵּאַרְנוּ שֶׁהַשּׁוֹחֵט בְּהֵמָה חַיָּה וְעוֹף וְלֹא יָצָא מֵהֶן דָּם שֶׁהֵן מֻתָּרִין:","אֵין הַבָּשָׂר יוֹצֵא מִידֵי דָּמוֹ אֶלָּא אִם כֵּן מוֹלְחוֹ יָפֶה יָפֶה וּמְדִיחוֹ יָפֶה יָפֶה. כֵּיצַד עוֹשֶׂה. מֵדִיחַ הַבָּשָׂר תְּחִלָּה וְאַחַר כָּךְ מוֹלְחוֹ יָפֶה יָפֶה וּמַנִּיחוֹ בְּמִלְחוֹ כְּדֵי הִלּוּךְ מִיל. וְאַחַר כָּךְ מְדִיחוֹ יָפֶה יָפֶה עַד שֶׁיֵּצְאוּ הַמַּיִם זַכִּים וּמַשְׁלִיכוֹ מִיָּד לְתוֹךְ מַיִם רוֹתְחִין אֲבָל לֹא לְפוֹשְׁרִין כְּדֵי שֶׁיִּתְלַבֵּן מִיָּד וְלֹא יֵצֵא דָּם:","כְּשֶׁמּוֹלְחִין הַבָּשָׂר אֵין מוֹלְחִין אוֹתוֹ אֶלָּא בִּכְלִי מְנֻקָּב. וְאֵין מוֹלְחִין אֶלָּא בְּמֶלַח עָבֶה כְּחוֹל הַגַּס. שֶׁהַמֶּלַח דַּק כְּקֶמַח יִבָּלַע בַּבָּשָׂר וְלֹא יוֹצִיא דָּם. וְצָרִיךְ לְנַפֵּץ הַבָּשָׂר מִן הַמֶּלַח וְאַחַר כָּךְ יְדִיחֶנּוּ:","כָּל הַדְּבָרִים הָאֵלּוּ לְבָשָׂר שֶׁצָּרִיךְ לְבַשְּׁלוֹ אֲבָל לְצָלִי מוֹלֵחַ וְצוֹלֶה מִיָּד. וְהָרוֹצֶה לֶאֱכל בָּשָׂר חַי מוֹלְחוֹ יָפֶה יָפֶה וּמְדִיחוֹ יָפֶה יָפֶה וְאַחַר כָּךְ יֹאכַל. וְאִם חֲלָטוֹ בְּחֹמֶץ מֻתָּר לְאָכְלוֹ כְּשֶׁהוּא חַי. וּמֻתָּר לִשְׁתּוֹת הַחֹמֶץ שֶׁחֲלָטוֹ בּוֹ שֶׁאֵין הַחֹמֶץ מוֹצִיא הַדָּם:","חֹמֶץ שֶׁחָלַט בּוֹ בָּשָׂר לֹא יַחְלֹט בּוֹ פַּעַם שְׁנִיָּה. וַחֲתִיכָה שֶׁהֶאֱדִימָה בְּתוֹךְ הַחֹמֶץ הִיא וְהַחֹמֶץ אֲסוּרִין עַד שֶׁיִּמְלַח אוֹתָהּ יָפֶה יָפֶה וְיִצְלֶה. בָּשָׂר שֶׁהֶאְדִּים וְכֵן בֵּיצֵי בְּהֵמָה וְחַיָּה בִּקְלִיפָה שֶׁעֲלֵיהֶן. וְכֵן הָעֹרֶף שֶׁבּוֹ הַמִּזְרָקִים שֶׁהֵן מְלֵאִים דָּם. אִם חֲתָכָן וּמְלָחָן כַּדָּת מֻתָּר לְבַשְּׁלָן. וְאִם לֹא חֲתָכָן וּצְלָאָן בְּשִׁפּוּד וְצָלָה הָעֹרֶף וּפִיו לְמַטָּה אוֹ שֶׁצְּלָאָן כֻּלָּן עַל הַגֶּחָלִים הֲרֵי אֵלּוּ מֻתָּרִין:","רֹאשׁ הַבְּהֵמָה שֶׁצָּלָהוּ בְּתַנּוּר אוֹ בְּכִבְשָׁן אִם תָּלָהוּ וּבֵית שְׁחִיטָתוֹ לְמַטָּה מֻתָּר שֶׁהַדָּם יוֹצֵא וְשׁוֹתֵת. וְאִם הָיָה בֵּית הַשְּׁחִיטָה מִן הַצַּד מֹחוֹ אָסוּר. שֶׁהַדָּם מִתְקַבֵּץ לְתוֹכוֹ. וּשְׁאָר הַבָּשָׂר שֶׁעַל הָעֲצָמוֹת מִבַּחוּץ מֻתָּר. הִנִּיחַ חָטְמוֹ לְמַטָּה אִם הִנִּיחַ בּוֹ גֶּמִי אוֹ קָנֶה כְּדֵי שֶׁיִּשָּׁאֵר פָּתוּחַ וְיֵצֵא דָּמוֹ דֶּרֶךְ חָטְמוֹ מֻתָּר וְאִם לָאו מֹחוֹ אָסוּר:","אֵין מַנִּיחִין כְּלִי תַּחַת הַצָּלִי לְקַבֵּל מֵימָיו עַד שֶׁתִּכְלֶה כָּל מַרְאֶה אַדְמוּמִית שֶׁבּוֹ. וְכֵיצַד עוֹשִׂין. מַשְׁלִיכִין לְתוֹךְ הַכְּלִי מְעַט מֶלַח וּמַנִּיחַ הַכְּלִי עַד שֶׁיִּצָּלֶה וְלוֹקֵחַ הַשַּׁמְנוּנִית שֶׁל מַעְלָה וְהַמַּיִם שֶׁל מַטָּה שֶׁתַּחַת הַשַּׁמְנוּנִית אֲסוּרָה:","פַּת שֶׁחָתַךְ עָלֶיהָ בָּשָׂר צָלִי מֻתָּר לְאָכְלָהּ שֶׁאֵינָהּ אֶלָּא שַׁמְנוּנִית [א. ב] דָּגִים וְעוֹפוֹת שֶׁמְּלָחָן זֶה עִם זֶה אֲפִלּוּ בִּכְלִי מְנֻקָּב הַדָּגִים אֲסוּרִין שֶׁהַדָּג רָפֶה וּבוֹלֵעַ דָּם הַיּוֹצֵא מִן הָעוֹף. וְאֵין צָרִיךְ לוֹמַר אִם מָלַח דָּג עִם בְּשַׂר בְּהֵמָה אוֹ חַיָּה:","עוֹפוֹת שֶׁהִנִּיחָן שְׁלֵמִים וּמִלֵּא חֲלָלָן בָּשָׂר וּבֵיצִים וּבִשְּׁלָן אֲסוּרוֹת שֶׁהֲרֵי דָּם יוֹצֵא לְתוֹכָן וְאַף עַל פִּי שֶׁמְּלָחָן יָפֶה יָפֶה. וַאֲפִלּוּ הָיָה הַבָּשָׂר שֶׁבְּתוֹכָן שָׁלוּק אוֹ צָלוּי. וְאִם צְלָאָן הֲרֵי אֵלּוּ מֻתָּרוֹת אַף עַל פִּי שֶׁהַבָּשָׂר שֶׁבְּתוֹכָן חַי וַאֲפִלּוּ פִּיהֶן לְמַעְלָה:","בְּנֵי מֵעַיִם שֶׁמִּלְּאָן עַל דֶּרֶךְ זוֹ בְּבָשָׂר צָלוּי אוֹ שָׁלוּק אוֹ שֶׁמִּלְּאָן בְּבֵיצִים וּשְׁלָקָן אוֹ קְלָאָן הֲרֵי אֵלּוּ מֻתָּרִין שֶׁאֵין מַחֲזִיקִין דָּם בִּבְנֵי מֵעַיִם. וְכֵן הוֹרוּ הַגְּאוֹנִים:","עוֹפוֹת שֶׁטְּפָלָן בְּבָצֵק וּצְלָאָן בֵּין שְׁלֵמִים בֵּין מְחֻתָּכִין אִם טְפָלָן בְּסלֶת גַּסָּה אֲפִלּוּ הִסְמִיקָה הַטְּפֵלָה אוֹכֵל אֶת הַטְּפֵלָה מִפְּנֵי שֶׁסּלֶת גַּסָּה מִתְפָּרֶרֶת וְיוֹצֵא הַדָּם. וְאִם טְפָלָן בְּקֶמַח חִטִּים שֶׁלָּתְתָן אִם הָיְתָה הַטְּפֵלָה לְבָנָה כְּמוֹ הַכֶּסֶף מֻתָּר לֶאֱכל מִמֶּנָּה וְאִם לָאו אֲסוּרָה. טְפָלָן בִּשְׁאָר קְמָחִין אִם הֶאְדִּימוּ אֲסוּרִין וְאִם לֹא הֶאְדִּימוּ מֻתָּרִין:","סַכִּין שֶׁשָּׁחַט בָּהּ אָסוּר לַחְתֹּךְ בָּהּ רוֹתֵחַ עַד שֶׁיְּלַבֵּן הַסַּכִּין בָּאוּר אוֹ יַשְׁחִיזֶנָּה בְּמַשְׁחֶזֶת אוֹ יִנְעָצֶנָּה בְּקַרְקַע קָשָׁה עֶשֶׂר פְּעָמִים. וְאִם חָתַךְ בָּהּ רוֹתֵחַ מֻתָּר. וְכֵן אֵינוֹ חוֹתֵךְ בָּהּ צְנוֹן וְכַיּוֹצֵא בּוֹ מִדְּבָרִים הַחֲרִיפִים לְכַתְּחִלָּה. וְאִם הֵדִיחַ הַסַּכִּין אוֹ שֶׁקִּנְּחָהּ בִּכְלִי מֻתָּר לַחְתֹּךְ בּוֹ צְנוֹן וְכַיּוֹצֵא בּוֹ אֲבָל לֹא רוֹתֵחַ:","קְעָרָה שֶׁמָּלַח בָּהּ בָּשָׂר אֲפִלּוּ הָיְתָה שׁוֹעָה בַּאֲבָר אָסוּר לֶאֱכל בָּהּ רוֹתֵחַ לְעוֹלָם שֶׁכְּבָר נִבְלַע הַדָּם בַּחֲרָסֶיהָ:"],"Mishneh Torah, Forbidden Intercourse 17":["שָׁלֹשׁ נָשִׁים נֶאֶסְרוּ עַל כָּל הַכֹּהֲנִים. גְּרוּשָׁה זוֹנָה וַחְללָה. וִעַל כֹּהֵן גָּדוֹל אַרְבַּע. אֵלּוּ הַשָּׁלֹשׁ וְהָאַלְמָנָה. אֶחָד כֹּהֵן גָּדוֹל מָשׁוּחַ בְּשֶׁמֶן הַמִּשְׁחָה אוֹ הַמְרֻבֶּה בְּגָדִים. וְאֶחָד כֹּהֵן הָעוֹבֵד וְאֶחָד כֹּהֵן גָּדוֹל שֶׁמִּנּוּהוּ וְעָבַר. וְכֵן כֹּהֵן מְשׁוּחַ מִלְחָמָה. כֻּלָּן מְצֻוִּין עַל הַבְּתוּלָה וַאֲסוּרִין בְּאַלְמָנָה:","כָּל כֹּהֵן שֶׁנָּשָׂא אַחַת מֵהַשָּׁלֹשׁ נָשִׁים אֵלּוּ בֵּין גָּדוֹל בֵּין הֶדְיוֹט וּבָעַל לוֹקֶה. וְאִם בָּא עָלֶיהָ דֶּרֶךְ זְנוּת אֵינוֹ לוֹקֶה מִשּׁוּם זוֹנָה אוֹ גְּרוּשָׁה אוֹ חֲלָלָה שֶׁנֶּאֱמַר (ויקרא כא ז) \"לֹא יִקָּחוּ\" עַד שֶׁיִּקַּח וְיִבְעל:","אֲבָל כֹּהֵן גָּדוֹל שֶׁבָּא עַל אַלְמָנָה לוֹקֶה אַחַת אַף עַל פִּי שֶׁלֹּא קִדֵּשׁ שֶׁנֶּאֱמַר (ויקרא כא טו) \"לֹא יְחַלֵּל\" כֵּיוָן שֶׁבְּעָלָהּ חִלְּלָהּ וּפְסָלָהּ לִכְהֻנָּה. אֲבָל זוֹנָה וַחֲלָלָה וּגְרוּשָׁה הֲרֵי הֵן מְחֻלָּלוֹת וְעוֹמְדוֹת קֹדֶם בְּעִילָתוֹ. וּלְפִיכָךְ לוֹקֶה כֹּהֵן גָּדוֹל לְבַדּוֹ עַל בְּעִילַת אַלְמָנָה לְבַדָּהּ אַף עַל פִּי שֶׁאֵין שָׁם קִדּוּשִׁין שֶׁהֲרֵי חִלְּלָהּ וְהוּא מֻזְהָר שֶׁלֹּא יְחַלֵּל כְּשֵׁרִים לֹא אִשָּׁה וְלֹא זַרְעוֹ:","קִדֵּשׁ כֹּהֵן גָּדוֹל אַלְמָנָה וּבְעָלָהּ לוֹקֶה שְׁתַּיִם. אַחַת מִשּׁוּם (ויקרא כא יד) \"אַלְמָנָה לֹא יִקָּח\". וְאַחַת מִשּׁוּם (ויקרא כא טו) \"לֹא יְחַלֵּל\". וּבֵין כֹּהֵן גָּדוֹל וּבֵין כֹּהֵן הֶדְיוֹט שֶׁנָּשָׂא אִשָּׁה מִן הָאַרְבַּע וְלֹא בָּעַל אֵינוֹ לוֹקֶה:","וְכָל מָקוֹם שֶׁהוּא לוֹקֶה הִיא לוֹקָה. וְכָל מָקוֹם שֶׁהוּא אֵינוֹ לוֹקֶה הִיא אֵינָהּ לוֹקָה. שֶׁאֵין הֶפְרֵשׁ בֵּין אִישׁ לְאִשָּׁה לָעֳנָשִׁין זוּלָתִי בְּשִׁפְחָה חֲרוּפָה בִּלְבַד כְּמוֹ שֶׁבֵּאַרְנוּ:","כָּל כֹּהֵן הַבָּא עַל הַכּוּתִית בֵּין גָּדוֹל בֵּין הֶדְיוֹט לוֹקֶה מִשּׁוּם זוֹנָה. שֶׁהֲרֵי אֵינָהּ בַּת קִדּוּשִׁין וְהוּא אָסוּר בִּבְעִילַת זוֹנָה בֵּין יִשְׂרְאֵלִית בֵּין כּוּתִית:","הַחֲלוּצָה אֲסוּרָה לְכֹהֵן מִדִּבְרֵי סוֹפְרִים מִפְּנֵי שֶׁהִיא כִּגְרוּשָׁה וּמַכִּין אוֹתוֹ מַכַּת מַרְדּוּת מִדִּבְרֵיהֶם. כֹּהֵן שֶׁנָּשָׂא סְפֵק חֲלוּצָה אֵין מוֹצִיאִין אוֹתָהּ מִתַּחְתָּיו וְהִיא כְּשֵׁרָה וּוְלָדָהּ כָּשֵׁר. מִפְּנֵי שֶׁלֹּא גָּזְרוּ עַל סְפֵק חֲלוּצָה אֶלָּא עַל חֲלוּצָה וַדָּאִית. וְכֵן מִי שֶׁהָיְתָה סְפֵק גְּרוּשָׁה אוֹ סְפֵק אַלְמָנָה אוֹ סְפֵק זוֹנָה וּסְפֵק חֲלָלָה מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת וּמוֹצִיא בְּגֵט:","כְּלָל גָּדוֹל הוּא בְּכָל אִסּוּרִים שֶׁבַּתּוֹרָה שֶׁאֵין אִסּוּר חָל עַל אִסּוּר אֶלָּא אִם כֵּן הָיוּ שְׁנֵי אִסּוּרִין בָּאִין כְּאַחַת. אוֹ שֶׁהָיָה הָאִסּוּר הָאֶחָד מוֹסִיף דְּבָרִים אֲחֵרִים עַל אוֹתוֹ הָאִסּוּר. אוֹ אִם הָיָה כּוֹלֵל דְּבָרִים אֲחֵרִים עִם אִסּוּר זֶה:","לְפִיכָךְ אִשָּׁה שֶׁהָיְתָה אַלְמָנָה וְנַעֲשֵׂית גְּרוּשָׁה וְנַעֲשֵׂית חֲלָלָה וְנַעֲשֵׂית זוֹנָה וּבָא עָלֶיהָ כֹּהֵן גָּדוֹל אַחַר כָּךְ לוֹקֶה אַרְבַּע מַלְקִיּוֹת עַל בִּיאָה אַחַת. לְפִי שֶׁהָאַלְמָנָה אֲסוּרָה לְכֹהֵן גָּדוֹל וּמֻתֶּרֶת לְהֶדְיוֹט.","חָזְרָה לִהְיוֹת גְּרוּשָׁה נוֹסָף בָּהּ אִסּוּר וְנֶאֱסֶרֶת לְכֹהֵן הֶדְיוֹט. לְפִיכָךְ נוֹסָף בָּהּ אִסּוּר אַחֵר עַל אִסּוּר הָאַלְמָנָה וַעֲדַיִן הִיא מֻתֶּרֶת לֶאֱכל בִּתְרוּמָה. נַעֲשֵׂית חֲלָלָה נוֹסָף בָּהּ אִסּוּר שֶׁהֲרֵי נֶאֱסֶרֶת בִּתְרוּמָה וַעֲדַיִן הִיא מֻתֶּרֶת לְיִשְׂרָאֵל. נַעֲשֵׂית זוֹנָה הוֹאִיל וְיֵשׁ שֵׁם זְנוּת שֶׁאוֹסְרָהּ עַל יִשְׂרָאֵל אִם זִנְּתָה אִשְׁתּוֹ בְּרָצוֹן נוֹסָף בָּהּ אִסּוּר אַחֵר. וְהוּא הַדִּין לְכֹהֵן הֶדְיוֹט שֶׁבָּא עַל הַגְּרוּשָׁה שֶׁנַּעֲשֵׂית חֲלָלָה וְאַחַר כָּךְ זוֹנָה שֶׁהוּא לוֹקֶה שָׁלֹשׁ עַל בִּיאָה אַחַת. אֲבָל אִם נִשְׁתַּנָּה סֵדֶר זֶה אֵינוֹ לוֹקֶה אֶלָּא אַחַת:","מִי שֶׁנִּתְאַלְמְנָה מֵאֲנָשִׁים הַרְבֵּה אוֹ נִתְגָּרְשָׁה מֵאֲנָשִׁים הַרְבֵּה אֵין לוֹקִין עָלֶיהָ אֶלָּא אַחַת עַל כָּל בִּיאָה. אַלְמָנָה בֵּין מִן הָאֵרוּסִין בֵּין מִן הַנִּשּׂוּאִין אֲסוּרָה:","כֹּהֵן גָּדוֹל שֶׁמֵּת אָחִיו אַף עַל פִּי שֶׁהוּא מִן הָאֵרוּסִין הֲרֵי זֶה לֹא יְיַבֵּם אֶלָּא חוֹלֵץ. נָפְלָה לוֹ יְבָמָה וְהוּא כֹּהֵן הֶדְיוֹט וְנִתְמַנָּה לִהְיוֹת כֹּהֵן גָּדוֹל אַף עַל פִּי שֶׁעָשָׂה בָּהּ מַאֲמָר כְּשֶׁהוּא כֹּהֵן הֶדְיוֹט הֲרֵי זֶה לֹא יְיַבֵּם אַחַר שֶׁנִּתְמַנָּה. אֲבָל אִם אֵרֵס אֶת הָאַלְמָנָה וְנִתְמַנָּה לִהְיוֹת כֹּהֵן גָּדוֹל הֲרֵי זֶה יִכְנֹס אַחַר שֶׁנִּתְמַנָּה. הָיְתָה מְקֻדֶּשֶׁת סְפֵק קִדּוּשִׁין וּמֵת אֲרוּסָהּ הֲרֵי זוֹ סְפֵק אַלְמָנָה:","מִצְוַת עֲשֵׂה עַל כֹּהֵן גָּדוֹל שֶׁיִּשָּׂא נַעֲרָה בְּתוּלָה. וּמִשֶּׁתִּבְגֹּר תֵּאָסֵר עָלָיו שֶׁנֶּאֱמַר (ויקרא כא יג) \"וְהוּא אִשָּׁה בִבְתוּלֶיהָ יִקָּח\". אִשָּׁה לֹא קְטַנָּה. בִּבְתוּלֶיהָ וְלֹא בּוֹגֶרֶת. הָא כֵּיצַד. יָצָאת מִכְּלַל קַטְנוּת וְלִכְלַל בַּגְרוּת לֹא בָּאָה זוֹ נַעֲרָה. וְאֵינוֹ נוֹשֵׂא שְׁתֵּי נָשִׁים לְעוֹלָם כְּאַחַת שֶׁנֶּאֱמַר אִשָּׁה אַחַת וְלֹא שְׁתַּיִם:","כֹּהֵן גָּדוֹל לֹא יִשָּׂא מֻכַּת עֵץ אַף עַל פִּי שֶׁלֹּא נִבְעֲלָה. [נִבְעֲלָה שֶׁלֹּא כְּדַרְכָּהּ הֲרֵי זוֹ כְּנִבְעֲלָה כְּדַרְכָּהּ. נִבְעֲלָה לִבְהֵמָה הֲרֵי זוֹ מֻתֶּרֶת]:","כֹּהֵן גָּדוֹל שֶׁנָּשָׂא בְּעוּלָה אֵינוֹ לוֹקֶה אֲבָל מוֹצִיא בְּגֵט. נָשָׂא בּוֹגֶרֶת אוֹ מֻכַּת עֵץ הֲרֵי זֶה יְקַיֵּם. אֵרֵס בְּעוּלָה וְנִתְמַנָּה כֹּהֵן גָּדוֹל הֲרֵי זֶה יִכְנֹס אַחַר שֶׁנִּתְמַנָּה:","אָנַס נַעֲרָה בְּתוּלָה אוֹ פִּתָּה אוֹתָהּ אֲפִלּוּ אֲנָסָהּ אוֹ פִּתָּה אוֹתָהּ כְּשֶׁהוּא כֹּהֵן הֶדְיוֹט וְנִתְמַנָּה כֹּהֵן גָּדוֹל קֹדֶם שֶׁיִּכְנֹס הֲרֵי זֶה לֹא יִכְנֹס. וְאִם כָּנַס מוֹצִיא:","אֵרֵס אֶת הַקְּטַנָּה וּבָגְרָה תַּחְתָּיו קֹדֶם נִשּׂוּאִין הֲרֵי זֶה לֹא יִכְנֹס מִפְּנֵי שֶׁנִּשְׁתַּנָּה גּוּפָהּ. וְאִם כָּנַס לֹא יוֹצִיא:","אַחַת גְּרוּשָׁה מִן הָאֵרוּסִין אוֹ מִן הַנִּשּׂוּאִין. אֲבָל הַמְמָאֶנֶת אֲפִלּוּ גֵּרְשָׁהּ בְּגֵט וְהֶחֱזִירָהּ וּמֵאֲנָה בּוֹ הֲרֵי זוֹ מֻתֶּרֶת לְכֹהֵן כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת גֵּרוּשִׁין. וְכָל מִי שֶׁאֵינָהּ רְאוּיָה לַחֲלִיצָה אִם נֶחְלְצָה לֹא נִפְסְלָה לִכְהֻנָּה:","יָצָא עָלֶיהָ קוֹל אִישׁ פְּלוֹנִי כֹּהֵן כָּתַב גֵּט לְאִשְׁתּוֹ אוֹ נָתַן גֵּט לְאִשְׁתּוֹ וַהֲרֵי הִיא יוֹשֶׁבֶת תַּחְתָּיו וּמְשַׁמַּשְׁתּוֹ. אֵין מוֹצִיאִין אוֹתָהּ מִתַּחַת בַּעְלָהּ. וְאִם נִשֵּׂאת לְכֹהֵן אַחֵר תֵּצֵא מִן הַשֵּׁנִי:","יָצָא שְׁמָהּ בָּעִיר שֶׁנִּתְקַדְּשָׁה וְנִתְגָּרְשָׁה מִן הַקִּדּוּשִׁין חוֹשְׁשִׁין לָהּ כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת גֵּרוּשִׁין. אֲבָל אִם יָצָא עָלֶיהָ קוֹל שֶׁהִיא חֲלוּצָה אֵין חוֹשְׁשִׁין לָהּ:","יָצָא קוֹל עַל הַבְּתוּלָה שֶׁהִיא בְּעוּלָה אֵין חוֹשְׁשִׁין לָהּ וְתִנָּשֵׂא לְכֹהֵן גָּדוֹל. יָצָא עָלֶיהָ קוֹל שֶׁהִיא שִׁפְחָה אֵין חוֹשְׁשִׁין לָהּ וְתִנָּשֵׂא אֲפִלּוּ לְכֹהֵן. יָצָא לָהּ שֵׁם מְזַנָּה בָּעִיר אֵין חוֹשְׁשִׁין לָהּ. וַאֲפִלּוּ הוֹצִיאָהּ בַּעְלָהּ מִשּׁוּם שֶׁעָבְרָה עַל דַּת יְהוּדִית אוֹ בְּעֵדֵי דָּבָר מְכֹעָר וּמֵת קֹדֶם שֶׁיִּתֵּן לָהּ גֵּט הֲרֵי זוֹ מֻתֶּרֶת לְכֹהֵן. שֶׁאֵין אוֹסְרִין אִשָּׁה מֵאֵלּוּ אֶלָּא בְּעֵדוּת בְּרוּרָה אוֹ בִּהוֹדָאַת פִּיהָ:"],"Mishneh Torah, Forbidden Intercourse 8":["יֵשׁ אִשָּׁה שֶׁיֵּשׁ לָהּ וֶסֶת וְיֵשׁ אִשָּׁה שֶׁאֵין לָהּ וֶסֶת אֶלָּא לֹא תַּרְגִּישׁ בְּעַצְמָהּ עַד שֶׁיֵּצֵא הַדָּם וְאֵין לָהּ יוֹם קָבוּעַ לִרְאִיָּתָהּ. וְזֶהוּ שֶׁיֵּשׁ לָהּ וֶסֶת הִיא שֶׁיֵּשׁ לָהּ יוֹם קָבוּעַ. אוֹ מֵעֶשְׂרִים יוֹם לְעֶשְׂרִים יוֹם. אוֹ מִכ\"ד יוֹם לְכ\"ד יוֹם. אוֹ פָּחוֹת אוֹ יוֹתֵר:","וְקֹדֶם שֶׁיָּבוֹא הַדָּם תַּרְגִּישׁ בְּעַצְמָהּ. מְפַהֶקֶת וּמִתְעַטֶּשֶׁת וְחוֹשֶׁשֶׁת פִּי כְּרֵסָהּ וְשִׁפּוּלֵי מֵעֶיהָ וְיִסְתַּמֵּר שַׂעֲרַת בְּשָׂרָהּ אוֹ יֵחַם בְּשָׂרָהּ וְכַיּוֹצֵא בִּמְאֹרָעוֹת אֵלּוּ. וְיָבוֹאוּ לָהּ וְסָתוֹת אֵלּוּ אוֹ אֶחָד מֵהֶן בְּשָׁעָה הַקְּבוּעָה לָהּ מִיּוֹם וֶסְתָּהּ:","כְּבָר בֵּאַרְנוּ שֶׁכָּל אִשָּׁה שֶׁאֵין לָהּ וֶסֶת אֲסוּרָה לְשַׁמֵּשׁ עַד שֶׁתִּבְדֹּק עַצְמָהּ תְּחִלָּה. וְשֶׁיֵּשׁ לָהּ וֶסֶת אֲסוּרָה לְשַׁמֵּשׁ בְּכָל עוֹנַת הַוֶּסֶת. אִם וֶסְתָּהּ בַּיּוֹם אֲסוּרָה לְשַׁמֵּשׁ כָּל אוֹתוֹ הַיּוֹם. וְאִם וֶסְתָּהּ בַּלַּיְלָה אֲסוּרָה לְשַׁמֵּשׁ כָּל אוֹתוֹ הַלַּיְלָה. וּמִתְּחִלַּת יוֹם הַוֶּסֶת תִּסְפֹּר יְמֵי נִדָּתָהּ וִימֵי זִיבָתָהּ לְעוֹלָם:","לְפִיכָךְ צְרִיכוֹת הַנָּשִׁים לְהִזָּהֵר בִּוְסָתוֹת עַד שֶׁתֵּדַע הַיּוֹם וְהַשָּׁעָה שֶׁנִּקְבְּעָה בָּהּ וֶסְתָּהּ. הָיָה דַּרְכָּהּ לִרְאוֹת בְּיוֹם עֶשְׂרִים וּבָא יוֹם עֶשְׂרִים וְלֹא רָאֲתָה וּבָא יוֹם שְׁלֹשָׁה וְעֶשְׂרִים וְרָאֲתָה הֲרֵי יוֹם עֶשְׂרִים וְיוֹם שְׁלֹשָׁה וְעֶשְׂרִים שְׁנֵיהֶן אֲסוּרִין. וְכֵן אִם רָאֲתָה פַּעַם שְׁנִיָּה בְּיוֹם כ\"ג וְלֹא רָאֲתָה בְּיוֹם עֶשְׂרִים עֲדַיִן שְׁנֵיהֶן אֲסוּרִין. רָאֲתָה פַּעַם שְׁלִישִׁית בְּיוֹם שְׁלֹשָׁה וְעֶשְׂרִים וְלֹא רָאֲתָה בְּיוֹם עֶשְׂרִים טָהַר יוֹם עֶשְׂרִים וְנֶעֱקָר הַוֶּסֶת לְיוֹם שְׁלֹשָׁה וְעֶשְׂרִים. שֶׁאֵין הָאִשָּׁה קוֹבַעַת וֶסֶת עַד שֶׁתִּקְבָּעֶנּוּ שָׁלֹשׁ פְּעָמִים. וְאֵינָהּ מִטַּהֶרֶת מִן הַוֶּסֶת עַד שֶׁתֵּעָקֵר מִמֶּנָּה שָׁלֹשׁ פְּעָמִים:","כָּל וֶסֶת שֶׁנִּקְבַּע מֵחֲמַת אֹנֶס אֲפִלּוּ רָאֲתָה בּוֹ כַּמָּה פְּעָמִים אֵינוֹ וֶסֶת שֶׁמִּפְּנֵי הָאֹנֶס רָאֲתָה. קָפְצָה וְרָאֲתָה קָפְצָה וְרָאֲתָה קָבְעָה לָהּ וֶסֶת לְיָמִים בְּלֹא קְפִיצוֹת. כֵּיצַד. קָפְצָה בְּאֶחָד בְּשַׁבָּת וְרָאֲתָה דָּם. וּלְאַחַר עֶשְׂרִים יוֹם קָפְצָה בְּאֶחָד בְּשַׁבָּת וְרָאֲתָה דָּם. וּלְאַחַר י\"ט קָפְצָה בְּיוֹם הַשַּׁבָּת וְלֹא רָאֲתָה דָּם וּלְאַחַר שַׁבָּת רָאֲתָה בְּלֹא קְפִיצָה. הֲרֵי נִקְבָּע אֶחָד בְּשַׁבָּת אַחַר עֶשְׂרִים. שֶׁהֲרֵי נוֹדַע שֶׁהַיּוֹם גָּרַם לָהּ לִרְאוֹת וְלֹא הַקְּפִיצָה. וּכְבָר נִקְבַּע יוֹם זֶה שָׁלֹשׁ פְּעָמִים. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","רָאֲתָה יוֹם ט\"ו בְּחֹדֶשׁ זֶה וְיוֹם ט\"ז בְּחֹדֶשׁ שֶׁל אַחֲרָיו וְיוֹם י\"ז בְּחֹדֶשׁ שֶׁל אַחֲרָיו וְיוֹם י\"ח לְחֹדֶשׁ שֶׁל אַחֲרָיו הֲרֵי קָבְעָה לָהּ וֶסֶת לְדִלּוּג. בָּא חֹדֶשׁ רְבִיעִי וְרָאֲתָה בְּיוֹם י\"ז עֲדַיִן לֹא נִקְבָּע לָהּ וֶסֶת. וְכָל יוֹם שֶׁרָאֲתָה בּוֹ חוֹשֶׁשֶׁת לוֹ לְהַבָּא. כֵּיוָן שֶׁיַּגִּיעַ אוֹתוֹ הַיּוֹם וְלֹא תִּרְאֶה טָהַר אוֹתוֹ הַיּוֹם מִן הַוֶּסֶת שֶׁאֵין צָרִיךְ עֲקִירַת שָׁלשׁ פְּעָמִים אֶלָּא יוֹם שֶׁנִּקְבַּע שָׁלֹשׁ פְּעָמִים:","הָיָה דַּרְכָּהּ לִהְיוֹת רוֹאָה יוֹם ט\"ו וְשִׁנְּתָה לְט\"ז שְׁנֵיהֶם אֲסוּרִין. שִׁנְּתָה לְי\"ז הֻתַּר ט\"ז וְנֶאֱסַר י\"ז וְט\"ו בְּאִסּוּרוֹ עוֹמֵד. שִׁנְּתָה לְי\"ח נֶאֱסַר י\"ח וְהֻתְּרוּ כֻּלָּם:","הָיָה דַּרְכָּהּ לִרְאוֹת יוֹם עֶשְׂרִים וְשִׁנְּתָה לְיוֹם כ\"ב שְׁנֵיהֶם אֲסוּרִין. הִגִּיעַ עֶשְׂרִים וְלֹא רָאֲתָה כ\"ב וְרָאֲתָה עֲדַיִן שְׁנֵיהֶן אֲסוּרִין. הִגִּיעַ יוֹם עֶשְׂרִים וְרָאֲתָה טָהַר יוֹם כ\"ב. שֶׁהֲרֵי חָזְרָה לְוֶסְתָּהּ הַקָּבוּעַ וְנֶעֱקַר כ\"ב מִפְּנֵי שֶׁלֹּא נִקְבַּע שָׁלֹשׁ פְּעָמִים:","אֵין הָאִשָּׁה קוֹבַעַת לָהּ וֶסֶת בְּתוֹךְ יְמֵי נִדָּתָהּ שֶׁרָאֲתָה בָּהֶן. כֵּיוָן שֶׁרָאֲתָה יוֹם אֶחָד אֵינָהּ קוֹבַעַת לָהּ וֶסֶת בְּכָל הַשִּׁבְעָה. וְכֵן אֵין הָאִשָּׁה קוֹבַעַת וֶסֶת בִּימֵי זִיבָתָהּ שֶׁהֵן אַחַד עָשָׂר יוֹם. אֲבָל קוֹבַעַת הִיא וֶסֶת בִּימֵי נִדָּתָהּ שֶׁאֵינָהּ רוֹאָה בָּהֶן. וְאִם נִקְבָּע לָהּ וֶסֶת בִּימֵי זִיבָתָהּ הֲרֵי זוֹ חוֹשֶׁשֶׁת לְוֶסְתָּהּ. וְכָל וֶסֶת שֶׁקָּבְעָה בִּימֵי זִיבָתָהּ אִם נֶעֶקְרָה אֲפִלּוּ פַּעַם אַחַת נֶעֶקְרָה וְאֵינָהּ צְרִיכָה לְהֵעָקֵר שָׁלֹשׁ פְּעָמִים שֶׁחֶזְקַת דָּמִים מְסֻלָּקִין הֵן לְיָמִים אֵלּוּ:","כֵּיצַד חוֹשֶׁשֶׁת לְוֶסֶת. אִם רָאֲתָה דָּם בְּוֶסֶת זוֹ אֲפִלּוּ יוֹם אֶחָד תֵּשֵׁב לְנִדָּתָהּ מִסָּפֵק וַאֲסוּרָה לְשַׁמֵּשׁ בְּאוֹתוֹ הַיּוֹם. וַאֲפִלּוּ לֹא רָאֲתָה בִּשְׁאָר יְמֵי הַוְּסָתוֹת. וְאִם רָאֲתָה שְׁלֹשָׁה יָמִים הֲרֵי זוֹ זָבָה:","כָּל אִשָּׁה שֶׁמַּרְבָּה לִבְדֹּק עַצְמָהּ תָּמִיד הֲרֵי זוֹ מְשֻׁבַּחַת וְאַף עַל פִּי שֶׁיֵּשׁ לָהּ וֶסֶת קְבוּעָה. שֶׁאֶפְשָׁר שֶׁיָּבוֹא דָּם בְּלֹא שְׁעַת הַוֶּסֶת. וְכָל י\"א יוֹם שֶׁל יְמֵי זִיבָתָהּ הֲרֵי הִיא בָּהֶן בְּחֶזְקַת טָהֳרָה וְאֵינָהּ צְרִיכָה בְּדִיקָה. אֲבָל אַחַר יְמֵי זִיבָתָהּ צְרִיכָה לִבְדֹּק:","שָׁכְחָה וְלֹא בָּדְקָה בֵּין בְּאֹנֶס בֵּין בְּרָצוֹן הֲרֵי זוֹ בְּחֶזְקַת טָהֳרָה עַד שֶׁתִּבְדֹּק וְתִמָּצֵא טְמֵאָה:","הָאִשָּׁה שֶׁלֹּא בָּדְקָה עַצְמָהּ בִּשְׁעַת וֶסְתָּהּ וּלְאַחַר יָמִים בָּדְקָה וּמָצְאָה טָמֵא אַף עַל פִּי שֶׁהִיא טְמֵאָה לְמַפְרֵעַ עַד שְׁעַת וֶסְתָּהּ כְּמוֹ שֶׁיִּתְבָּאֵר בְּעִנְיַן טֻמְאָה וְטָהֳרָה. הֲרֵי זוֹ אֵינָהּ מְטַמְּאָה אֶת בּוֹעֲלָהּ לְמַפְרֵעַ. וְאֵינָהּ מוֹנָה אֶלָּא מִשָּׁעָה שֶׁרָאֲתָה דָּם. וְאִם מָצְאָה עַצְמָהּ טְהוֹרָה הֲרֵי זוֹ בְּחֶזְקַת טְהוֹרָה:","וְכֵן אִשָּׁה שֶׁרָאֲתָה דָּם מֵחֲמַת מַכָּה שֶׁיֵּשׁ לָהּ בַּמָּקוֹר אַף עַל פִּי שֶׁרָאֲתָה בִּשְׁעַת וֶסְתָּהּ הִיא טְהוֹרָה וְהַדָּם טָהוֹר. שֶׁהַוְּסָתוֹת מִדִּבְרֵיהֶם כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת מְטַמְּאֵי מִשְׁכָּב וּמוֹשָׁב:","הַסּוּמָא בּוֹדֶקֶת עַצְמָהּ וּמַרְאָה לַחֲבֵרְתָהּ. אֲבָל הַחֵרֶשֶׁת וְהַשּׁוֹטָה צְרִיכוֹת פִּקְחוֹת לִבְדֹּק אוֹתָן וְלִקְבֹּעַ לָהֶן וְסָתוֹת וְאַחַר כָּךְ יִהְיוּ מֻתָּרוֹת לְבַעְלֵיהֶן:","כָּל אִשָּׁה שֶׁטָּעֲתָה וְלֹא יָדְעָה עֵת וֶסְתָּהּ וְרָאֲתָה דָּם חוֹשֶׁשֶׁת לְזִיבוּת. לְפִיכָךְ אִם רָאֲתָה יוֹם אֶחָד אוֹ שְׁנַיִם יוֹשֶׁבֶת תַּשְׁלוּם שִׁבְעָה שֶׁמָּא דָּם זֶה בִּימֵי נִדָּתָהּ הִיא. וְאִם רָאֲתָה שְׁלֹשָׁה יָמִים סוֹפֶרֶת שִׁבְעַת יָמִים נְקִיִּים שֶׁמָּא בִּימֵי זִיבָתָהּ הִיא עוֹמֶדֶת:","וְכֵיצַד הִיא עוֹשָׂה לְתַקֵּן וֶסְתָּהּ וְלֵידַע אִם הִיא זָבָה וַדָּאִית אוֹ סְפֵק זָבָה וְלֵידַע יְמֵי זִיבָתָהּ. הַכּל לְפִי יָמִים שֶׁתִּרְאֶה בָּהֶן. כֵּיצַד. רָאֲתָה יוֹם אֶחָד אוֹ שְׁנַיִם מַשְׁלֶמֶת עֲלֵיהֶן הַשִּׁבְעָה וְתַתְחִיל לִמְנוֹת הָאַחַד עָשָׂר יוֹם מֵאַחַר הַשִּׁבְעָה:","רָאֲתָה שְׁלֹשָׁה יָמִים הֲרֵי זוֹ סְפֵק זָבָה שֶׁמָּא יוֹם אֶחָד מֵהֶן קֹדֶם נִדָּתָהּ וּשְׁנַיִם בִּתְחִלַּת הַנִּדָּה. וְכֵן אִם רָאֲתָה אַרְבָּעָה שֶׁמָּא שְׁנַיִם קֹדֶם הַנִּדָּה וּשְׁנַיִם מִתְּחִלַּת הַנִּדָּה וְיוֹשֶׁבֶת חֲמִשָּׁה תַּשְׁלוּם יְמֵי נִדָּה וְאַחַד עָשָׂר יְמֵי זִיבָה אַחַר הַחֲמִשָּׁה:","וְכֵן אִם רָאֲתָה תִּשְׁעָה יָמִים הֲרֵי זוֹ סְפֵק זָבָה שֶׁמָּא שְׁנַיִם קֹדֶם יְמֵי נִדָּה וְשִׁבְעָה שֶׁל נִדָּה וּמַתְחֶלֶת לִמְנוֹת אַחַד עָשָׂר יוֹם מֵאַחַר הַתִּשְׁעָה שֶׁפָּסַק הַדָּם. וְכֵן אִם רָאֲתָה אַחַד עָשָׂר יוֹם הֲרֵי זוֹ סְפֵק זָבָה. שֶׁמָּא שְׁנַיִם קֹדֶם הַנִּדָּה וְשִׁבְעָה שֶׁל נִדָּה וּשְׁנַיִם שֶׁל אַחַר הַנִּדָּה וְנִשְׁאַר לָהּ מִימֵי זִיבָתָהּ תִּשְׁעָה:","רָאֲתָה שְׁנֵים עָשָׂר יוֹם הֲרֵי זוֹ זָבָה וַדָּאִית. שֶׁאֲפִלּוּ הָיוּ מֵהֶן שְׁנַיִם לִפְנֵי הַנִּדָּה וְשִׁבְעָה שֶׁל נִדָּה הֲרֵי שְׁלֹשָׁה לְאַחַר הַנִּדָּה וְיִשָּׁאֵר לָהּ מִימֵי זִיבָתָהּ שְׁמוֹנָה. וְכֵן אִם רָאֲתָה שְׁלֹשָׁה עָשָׂר יוֹם יִשָּׁאֵר לָהּ מִימֵי זִיבָתָהּ שִׁבְעָה וְהֵן יְמֵי הַסְּפִירָה:","מָשְׁכָה בִּרְאִיַּת הַדָּם אֲפִלּוּ רָאֲתָה אֶלֶף יוֹם כְּשֶׁיִּפְסֹק הַדָּם סוֹפֶרֶת שִׁבְעַת יָמִים נְקִיִּים. וְאַחַר הַשִּׁבְעָה יַתְחִילוּ יְמֵי הַנִּדָּה לְזוֹ שֶׁטָּעֲתָה:","הִנֵּה לָמַדְתָּ שֶׁכָּל הַטּוֹעָה אֵינָהּ מוֹנָה מִשֶּׁיִּפְסֹק הַדָּם פָּחוֹת מִשִּׁבְעָה וְלֹא יוֹתֵר עַל י\"ז וְיָבוֹאוּ יְמֵי נִדָּתָהּ. כֵּיצַד. רָאֲתָה יוֹם אֶחָד וּפָסַק הַדָּם מוֹנָה י\"ז שִׁשָּׁה לְתַשְׁלוּם נִדָּתָהּ וְי\"א יְמֵי זִיבָתָהּ וְיָבוֹאוּ יְמֵי נִדָּתָהּ. וְאִם רָאֲתָה י\"ג אוֹ יֶתֶר מוֹנָה שִׁבְעָה מִשֶּׁיִּפְסֹק הַדָּם וְיָבוֹאוּ יְמֵי נִדָּתָהּ כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Foreign Worship and Customs of the Nations 8":["כָּל שֶׁאֵין בּוֹ תְּפִיסַת יַד אָדָם וְלֹא עֲשָׂהוּ אָדָם אַף עַל פִּי שֶׁנֶּעֱבַד הֲרֵי זֶה מֻתָּר בַּהֲנָאָה. לְפִיכָךְ עוֹבְדֵי כּוֹכָבִים הָעוֹבְדִים אֶת הֶהָרִים וְאֶת הַגְּבָעוֹת וְאֶת הָאִילָנוֹת הַנְּטוּעִין מִתְּחִלָּתָן לְפֵרוֹת וְאֶת הַמַּעְיָנוֹת הַנּוֹבְעִין לָרַבִּים וְאֶת הַבְּהֵמָה הֲרֵי אֵלּוּ מֻתָּרִין בַּהֲנָאָה וּמֻתָּר לֶאֱכל אוֹתָן הַפֵּרוֹת שֶׁנֶּעֶבְדוּ בִּמְקוֹם גְּדִילָתָן וְאוֹתָהּ הַבְּהֵמָה. וְאֵין צָרִיךְ לוֹמַר הַבְּהֵמָה שֶׁהֻקְצַת לַעֲבוֹדַת כּוֹכָבִים שֶׁהִיא מֻתֶּרֶת בַּאֲכִילָה בֵּין שֶׁהִקְצוּהָ לְעָבְדָהּ בֵּין שֶׁהִקְצוּהָ לְהַקְרִיבָהּ הֲרֵי זוֹ מֻתֶּרֶת. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁאֵין הַבְּהֵמָה נֶאֱסֶרֶת בְּשֶׁלֹּא עָשָׂה בָּהּ מַעֲשֶׂה לְשֵׁם עֲבוֹדַת כּוֹכָבִים אֲבָל עָשָׂה בָּהּ מַעֲשֶׂה כָּל שֶׁהוּא אֲסָרָהּ. כֵּיצַד, כְּגוֹן שֶׁשָּׁחַט בָּהּ סִימָן לַעֲבוֹדַת כּוֹכָבִים. עֲשָׂאָהּ חֲלִיפִין לַעֲבוֹדַת כּוֹכָבִים אֲסָרָהּ. וְכֵן חֲלִיפֵי חֲלִיפִין. מִפְּנֵי שֶׁנַּעֲשִׂים דְּמֵי עֲבוֹדַת כּוֹכָבִים. בַּמֶּה דְּבָרִים אֲמוּרִים בְּבֶהֱמַת עַצְמוֹ. אֲבָל אִם שָׁחַט בֶּהֱמַת חֲבֵרוֹ לַעֲבוֹדַת כּוֹכָבִים אוֹ הֶחֱלִיפָהּ לֹא נֶאֶסְרָה שֶׁאֵין אָדָם אוֹסֵר דָּבָר שֶׁאֵינוֹ שֶׁלּוֹ. הַמִּשְׁתַּחֲוֶה לְקַרְקַע עוֹלָם לֹא אֲסָרָהּ. חָפַר בָּהּ בּוֹרוֹת שִׁיחִין וּמְעָרוֹת לְשֵׁם עֲבוֹדַת כּוֹכָבִים אֲסָרָהּ:","מַיִם שֶׁעֲקָרָן הַגַּל וְהִשְׁתַּחֲוָה לָהֶן לֹא אֲסָרָן. נְטָלָן בְּיָדוֹ וְהִשְׁתַּחֲוָה לָהֶן אֲסָרָן. אַבְנֵי הַר שֶׁנִּדַּלְדְּלוּ וַעֲבָדָן בִּמְקוֹמָם מֻתָּרוֹת שֶׁהֲרֵי אֵין בָּהֶן תְּפִיסַת יַד אָדָם:","יִשְׂרָאֵל שֶׁזָּקַף לְבֵנָה לְהִשְׁתַּחֲווֹת לָהּ וְלֹא הִשְׁתַּחֲוָה לָהּ וּבָא עוֹבֵד כּוֹכָבִים וְהִשְׁתַּחֲוָה לָהּ אֲסָרָהּ בַּהֲנָאָה שֶׁזְּקִיפָתָהּ מַעֲשֶׂה. וְכֵן אִם זָקַף בֵּיצָה וּבָא עוֹבֵד כּוֹכָבִים וְהִשְׁתַּחֲוָה לָהּ אֲסָרָהּ. חָתַךְ דְּלַעַת וְכַיּוֹצֵא בָּהּ וְהִשְׁתַּחֲוָה לָהּ אֲסָרָהּ. הִשְׁתַּחֲוָה לַחֲצִי דְּלַעַת וַחֲצִי הָאַחֵר מְעֹרֶה בּוֹ הֲרֵי זֶה אָסוּר מִסָּפֵק שֶׁמָּא זֶה הַחֵצִי כְּמוֹ יָד לַחֵצִי הַנֶּעֱבָד. אִילָן שֶׁנְּטָעוֹ מִתְּחִלָּה שֶׁיִּהְיֶה נֶעֱבָד אָסוּר בַּהֲנָאָה וְזוֹ הִיא אֲשֵׁרָה הָאֲמוּרָה בַּתּוֹרָה. הָיָה אִילָן נָטוּעַ וּגְדָעוֹ וּפְסָלוֹ לְשֵׁם עֲבוֹדַת כּוֹכָבִים אֲפִלּוּ הִבְרִיךְ וְהִרְכִּיב בְּגוּפוֹ שֶׁל אִילָן וְהוֹצִיא שָׂרִיגִים כּוֹרֵת אֶת הַשָּׂרִיגִים וְהֵם אֲסוּרִים בַּהֲנָאָה וּשְׁאָר הָאִילָן מֻתָּר. וְכֵן הַמִּשְׁתַּחֲוֶה לְאִילָן אַף עַל פִּי שֶׁלֹּא נֶאֱסַר גּוּפוֹ כָּל הַשָּׂרִיגִים וְהֶעָלִים וְהַלּוּלָבִין וְהַפֵּרוֹת שֶׁיּוֹצִיא כָּל זְמַן שֶׁהוּא נֶעֱבָד הֲרֵי אֵלּוּ אֲסוּרִין בַּהֲנָאָה. אִילָן שֶׁהָיוּ הָעוֹבְדֵי כּוֹכָבִים מְשַׁמְּרִין אֶת פֵּרוֹתָיו וְאוֹמְרִים שֶׁהֵם מוּכָנִים לַעֲשׂוֹת שֵׁכָר לְבֵית עֲבוֹדַת כּוֹכָבִים פְּלוֹנִי וְעוֹשִׂין מֵהֶן שֵׁכָר וְשׁוֹתִים אוֹתוֹ בְּיוֹם חַגָּם הֲרֵי זֶה הָאִילָן אָסוּר בַּהֲנָאָה מִפְּנֵי שֶׁסְּתָמוֹ שֶׁהוּא אֲשֵׁרָה וּלְפִיכָךְ עוֹשִׂין בְּפֵרוֹתָיו כָּךְ שֶׁזּוֹ הִיא חֻקָּהּ שֶׁל אֲשֵׁרָה:","אִילָן שֶׁמַּעֲמִידִין תַּחְתָּיו עֲבוֹדַת כּוֹכָבִים כָּל זְמַן שֶׁהִיא תַּחְתָּיו אָסוּר בַּהֲנָאָה. נְטָלָהּ מִתַּחְתָּיו הֲרֵי זֶה מֻתָּר מִפְּנֵי שֶׁאֵין הָאִילָן עַצְמוֹ הוּא הַנֶּעֱבָד. בַּיִת שֶׁבְּנָאוֹ הָעוֹבֵד כּוֹכָבִים מִתְּחִלָּה שֶׁיְּהֵא הַבַּיִת עַצְמוֹ נֶעֱבָד וְכֵן הַמִּשְׁתַּחֲוֶה לְבַיִת בָּנוּי הֲרֵי זֶה אָסוּר בַּהֲנָאָה. הָיָה בָּנוּי וְסִיְּדוֹ וְכִיְּרוֹ לְשֵׁם עֲבוֹדַת כּוֹכָבִים עַד שֶׁנִּתְחַדֵּשׁ נוֹטֵל מַה שֶּׁחִדֵּשׁ וְהַחִדּוּשׁ אָסוּר בַּהֲנָאָה מִפְּנֵי שֶׁעֲשָׂאָהוּ לְעָבְדוֹ וּשְׁאָר הַבַּיִת מֻתָּר. הִכְנִיס עֲבוֹדַת כּוֹכָבִים לְתוֹךְ הַבַּיִת כָּל זְמַן שֶׁהִיא שָׁם הַבַּיִת אָסוּר בַּהֲנָאָה. הוֹצִיאָהּ הֻתַּר הַבַּיִת. וְכֵן אֶבֶן שֶׁחֲצָבָהּ מִתְּחִלָּה לְעָבְדָהּ אֲסוּרָה בַּהֲנָאָה. הָיְתָה חֲצוּבָה וְצִיְּרָהּ וְכִיְּרָהּ שֶׁתֵּעָבֵד אֲפִלּוּ צִיֵּר וְכִיֵּר בְּגוּף הָאֶבֶן וְאֵין צָרִיךְ לוֹמַר אִם כִּיֵּר עָלֶיהָ נוֹטֵל מַה שֶּׁחִדֵּשׁ וְהוּא אָסוּר בַּהֲנָאָה הוֹאִיל וְנַעֲשָׂה שֶׁיֵּעָבֵד וּשְׁאָר הָאֶבֶן מֻתָּר:","אֶבֶן שֶׁהֶעֱמִיד עָלֶיהָ עֲבוֹדַת כּוֹכָבִים הֲרֵי זוֹ אֲסוּרָה כָּל זְמַן שֶׁהִיא עָלֶיהָ. סֻלְּקָה הָאֶבֶן מֻתֶּרֶת. מִי שֶׁהָיָה בֵּיתוֹ סָמוּךְ לַעֲבוֹדַת כּוֹכָבִים וְנָפַל אָסוּר לִבְנוֹתוֹ. כֵּיצַד יַעֲשֶׂה. כּוֹנֵס לְתוֹךְ שֶׁלּוֹ וּבוֹנֶה וְאוֹתוֹ הָרֶוַח מְמַלְּאֵהוּ קוֹצִים אוֹ צוֹאָה. כְּדֵי שֶׁלֹּא יַרְחִיב לְבֵית עֲבוֹדַת כּוֹכָבִים. הָיָה הַכֹּתֶל שֶׁלּוֹ וְשֶׁל עֲבוֹדַת כּוֹכָבִים יִדּוֹן מֶחֱצָה לְמֶחֱצָה, מֶחֱצָה שֶׁלּוֹ מֻתָּר בַּהֲנָאָה וְשֶׁל עֲבוֹדַת כּוֹכָבִים הַכּל אָסוּר בַּהֲנָאָה. אֲבָנָיו עֵצָיו וַעֲפָרוֹ הַכּל אָסוּר בַּהֲנָאָה:","כֵּיצַד מְאַבֵּד עֲבוֹדַת כּוֹכָבִים וּשְׁאָר דְּבָרִים הָאֲסוּרִים בִּגְלָלָהּ כְּגוֹן מְשַׁמְּשֶׁיהָ וְתִקְרֹבֶת שֶׁלָּהּ. שׁוֹחֵק וְזוֹרֶה לָרוּחַ אוֹ שׂוֹרֵף וּמֵטִיל לְיָם הַמֶּלַח:","דָּבָר שֶׁאֵין בּוֹ תְּפִיסַת יַד אָדָם שֶׁנֶּעֱבַד כְּגוֹן הָרִים וּבְהֵמָה וְאִילָן אַף עַל פִּי שֶׁהַנֶּעֱבָד עַצְמוֹ מֻתָּר בַּהֲנָאָה צִפּוּיוֹ אָסוּר בַּהֲנָאָה וְהַנֶּהֱנֶה בְּכָל שֶׁהוּא מֵהֶן לוֹקֶה שֶׁנֶּאֱמַר (דברים ז כה) \"לֹא תַחְמֹד כֶּסֶף וְזָהָב עֲלֵיהֶם\". וְכָל צִפּוּיֵי עֲבוֹדַת כּוֹכָבִים הֲרֵי הֵן בִּכְלַל מְשַׁמְּשֶׁיהָ:","עֲבוֹדַת כּוֹכָבִים שֶׁל עוֹבְדֵי כּוֹכָבִים שֶׁבִּטְּלוּהָ קֹדֶם שֶׁתָּבוֹא לִידֵי יִשְׂרָאֵל הֲרֵי זוֹ מֻתֶּרֶת בַּהֲנָאָה שֶׁנֶּאֱמַר (דברים ז כה) \"פְּסִילֵי אֱלֹהֵיהֶם תִּשְׂרְפוּן בָּאֵשׁ\", כְּשֶׁבָּאוּ לְיָדֵינוּ וְהֵן נוֹהֲגִין בָּהֶם אֱלֹהוּת, אֲבָל אִם בִּטְּלוּם הֲרֵי אֵלּוּ מֻתָּרִין:","עֲבוֹדַת כּוֹכָבִים שֶׁל יִשְׂרָאֵל אֵינָהּ בְּטֵלָה לְעוֹלָם אֲפִלּוּ הָיָה לְעוֹבֵד כּוֹכָבִים בָּהּ שֻׁתָּפוּת אֵין בִּטּוּלוֹ מוֹעִיל כְּלוּם אֶלָּא אֲסוּרָה בַּהֲנָאָה לְעוֹלָם וּטְעוּנָה גְּנִיזָה. וְכֵן עֲבוֹדַת כּוֹכָבִים שֶׁל עוֹבֵד כּוֹכָבִים שֶׁבָּאת לְיַד יִשְׂרָאֵל וְאַחַר כָּךְ בִּטְּלָהּ הָעוֹבֵד כּוֹכָבִים אֵין בִּטּוּלוֹ מוֹעִיל כְּלוּם אֶלָּא אֲסוּרָה בַּהֲנָאָה לְעוֹלָם. וְאֵין יִשְׂרָאֵל מְבַטֵּל עֲבוֹדַת כּוֹכָבִים וַאֲפִלּוּ בִּרְשׁוּת עוֹבֵד כּוֹכָבִים. עוֹבֵד כּוֹכָבִים קָטָן אוֹ שׁוֹטֶה אֵינוֹ מְבַטֵּל עֲבוֹדַת כּוֹכָבִים. וְעוֹבֵד כּוֹכָבִים שֶׁבִּטֵּל עֲבוֹדַת כּוֹכָבִים בֵּין שֶׁלּוֹ בֵּין שֶׁל עוֹבְדֵי כּוֹכָבִים אֲחֵרִים בְּעַל כָּרְחוֹ אַף עַל פִּי שֶׁאֲנָסוֹ יִשְׂרָאֵל עַל כָּךְ הֲרֵי זוֹ בְּטֵלָה. וּבִלְבַד שֶׁיְּהֵא הָעוֹבֵד כּוֹכָבִים הַמְבַטֵּל עוֹבֵד עֲבוֹדַת כּוֹכָבִים. אֲבָל מִי שֶׁאֵינוֹ עוֹבֵד עֲבוֹדַת כּוֹכָבִים אֵין בִּטּוּלוֹ בִּטּוּל. הַמְבַטֵּל עֲבוֹדַת כּוֹכָבִים בִּטֵּל מְשַׁמְּשֶׁיהָ. בִּטֵּל מְשַׁמְּשֶׁיהָ מְשַׁמְּשֶׁיהָ מֻתָּרִים וְהִיא אֲסוּרָה בַּהֲנָאָה כְּמוֹ שֶׁהָיְתָה עַד שֶׁיְּבַטְּלֶנָּה. וְתִקְרֹבֶת עֲבוֹדַת כּוֹכָבִים אֵינָהּ בְּטֵלָה לְעוֹלָם:","כֵּיצַד מְבַטְּלָהּ. קָטַע רֹאשׁ חָטְמָהּ רֹאשׁ אָזְנָהּ רֹאשׁ אֶצְבָּעָהּ פָּחֲסָה בְּפָנֶיהָ אַף עַל פִּי שֶׁלֹּא חִסְּרָהּ אוֹ שֶׁמְּכָרָהּ לְצוֹרֵף יִשְׂרָאֵל הֲרֵי זוֹ בְּטֵלָה. אֲבָל אִם מִשְׁכְּנָהּ אוֹ מְכָרָהּ לְעוֹבֵד כּוֹכָבִים אוֹ לְיִשְׂרָאֵל שֶׁאֵינוֹ צוֹרֵף אוֹ שֶׁנָּפְלָה עָלֶיהָ מַפּלֶת וְלֹא פִּנָּה. גְּנָבוּהָ לִסְטִים וְלֹא תְּבָעוּהָ. רָקַק בְּפָנֶיהָ. הִשְׁתִּין בְּפָנֶיהָ. גְּרָרָהּ. זָרַק בָּהּ אֶת הַצּוֹאָה הֲרֵי זוֹ אֵינָהּ בְּטֵלָה:","עֲבוֹדַת כּוֹכָבִים שֶׁהֱנִיחוּהָ עוֹבְדֶיהָ בִּשְׁעַת שָׁלוֹם מֻתֶּרֶת בַּהֲנָאָה שֶׁהֲרֵי בִּטְּלוּהָ. בִּשְׁעַת מִלְחָמָה אֲסוּרָה מִפְּנֵי שֶׁלֹּא הֱנִיחוּהָ אֶלָּא מִפְּנֵי הַמִּלְחָמָה. עֲבוֹדַת כּוֹכָבִים שֶׁנִּשְׁבְּרָה מֵאֵלֶיהָ שְׁבָרֶיהָ אֲסוּרִים בַּהֲנָאָה עַד שֶׁיְּבַטְּלוּהָ. לְפִיכָךְ הַמּוֹצֵא שִׁבְרֵי עֲבוֹדַת כּוֹכָבִים הֲרֵי אֵלּוּ אֲסוּרִין בַּהֲנָאָה שֶׁמָּא לֹא בִּטְּלוּהָ הָעוֹבְדֵי כּוֹכָבִים. וְאִם הָיְתָה שֶׁל פְּרָקִים וְהֶדְיוֹט יָכוֹל לְהַחֲזִירָם צָרִיךְ לְבַטֵּל כָּל פֶּרֶק וּפֶרֶק מִפְּרָקֶיהָ וְאִם אֵינוֹ יָכוֹל לְהַחֲזִיר כֵּיוָן שֶׁבִּטֵּל אֵיבָר אֶחָד מִמֶּנָּה בָּטְלוּ כָּל הַשְּׁבָרִים:","מִזְבַּח עֲבוֹדַת כּוֹכָבִים שֶׁנִּפְגַּם עֲדַיִן הוּא אָסוּר בַּהֲנָאָה עַד שֶׁיִּנָּתֵץ רֻבּוֹ בְּיַד עוֹבֵד כּוֹכָבִים. וּבִימוֹס שֶׁנִּפְגַּם מֻתָּר. אֵי זֶהוּ בִּימוֹס וְאֵי זֶהוּ מִזְבֵּחַ. בִּימוֹס אֶבֶן אַחַת. מִזְבֵּחַ אֲבָנִים הַרְבֵּה. וְכֵיצַד מְבַטְּלִין אַבְנֵי מַרְקוּלִיס. כֵּיוָן שֶׁבָּנָה מֵהֶם בִּנְיָן אוֹ חִפָּה בָּהֶן אֶת הַדְּרָכִים וְכַיּוֹצֵא בְּאֵלּוּ הֲרֵי הֵן מֻתָּרִים בַּהֲנָאָה. כֵּיצַד מְבַטְּלִים אֶת הָאֲשֵׁרָה. קִרְסֵם מִמֶּנָּה עָלֶה אוֹ זָרַק מִמֶּנָּה יוֹנֵק נָטַל מִמֶּנָּה מַקֵּל אוֹ שַׁרְבִיט אוֹ שֶׁשְּׁפָאָהּ שֶׁלֹּא לְצָרְכָּהּ הֲרֵי זוֹ בְּטֵלָה. שְׁפָאָהּ לְצָרְכָּהּ הִיא אֲסוּרָה וּשְׁפָאֶיהָ מֻתָּרִים. וְאִם הָיְתָה שֶׁל יִשְׂרָאֵל בֵּין לְצָרְכָּהּ בֵּין שֶׁלֹּא לְצָרְכָּהּ בֵּין הִיא וּבֵין שְׁפָאֶיהָ אֲסוּרָה לְעוֹלָם שֶׁעֲבוֹדַת כּוֹכָבִים שֶׁל יִשְׂרָאֵל אֵין לָהּ בִּטּוּל לְעוֹלָם:"],"Mishneh Torah, Fringes 1":["עָנָף שֶׁעוֹשִׂין עַל כְּנַף הַבֶּגֶד מִמִּין הַבֶּגֶד הוּא הַנִּקְרָא צִיצִית מִפְּנֵי שֶׁהוּא דּוֹמֶה לְצִיצִית שֶׁל רֹאשׁ. שֶׁנֶּאֱמַר (יחזקאל ח ג) ״וַיִּקָּחֵנִי בְּצִיצִת רָאשִׁי״. וְזֶה הֶעָנָף הוּא הַנִּקְרָא לָבָן מִפְּנֵי שֶׁאֵין אָנוּ מְצֻוִּין לְצָבְעוֹ. וְאֵין לְחוּטֵי הֶעָנָף מִנְיָן מִן הַתּוֹרָה:","וְלוֹקְחִין חוּט צֶמֶר שֶׁנִּצְבַּע כְּעֵין הָרָקִיעַ וְכוֹרְכִין אוֹתוֹ עַל הֶעָנָף וְחוּט זֶה הוּא הַנִּקְרָא תְּכֵלֶת. וְאֵין לְמִנְיַן הַכְּרִיכוֹת שֶׁכּוֹרֵךְ חוּט זֶה שִׁעוּר מִן הַתּוֹרָה:","נִמְצְאוּ בְּמִצְוָה זוֹ שְׁנֵי צַוִּים. שֶׁיַּעֲשֶׂה עַל הַכָּנָף עָנָף יוֹצֵא מִמֶּנָּה. וְשֶׁיִּכְרֹךְ עַל הֶעָנָף חוּט תְּכֵלֶת שֶׁנֶּאֱמַר (במדבר טו לח) ״וְעָשׂוּ לָהֶם צִיצִת״ (במדבר טו לח) ״וְנָתְנוּ עַל צִיצִת הַכָּנָף פְּתִיל תְּכֵלֶת״:","וְהַתְּכֵלֶת אֵינוֹ מְעַכֵּב אֶת הַלָּבָן וְהַלָּבָן אֵינוֹ מְעַכֵּב אֶת הַתְּכֵלֶת. כֵּיצַד. הֲרֵי שֶׁאֵין לוֹ תְּכֵלֶת עוֹשֶׂה לָבָן לְבַדּוֹ. וְכֵן אִם עָשָׂה לָבָן וּתְכֵלֶת וְנִפְסַק הַלָּבָן וְנִתְמַעֵט עַד הַכָּנָף וְנִשְׁאַר הַתְּכֵלֶת לְבַדּוֹ כָּשֵׁר:","אַף עַל פִּי שֶׁאֵין אֶחָד מֵהֶן מְעַכֵּב אֶת חֲבֵרוֹ אֵינָן שְׁתֵּי מִצְוֹת אֶלָּא מִצְוַת עֲשֵׂה אַחַת. אָמְרוּ חֲכָמִים הָרִאשׁוֹנִים (במדבר טו לט) ״וְהָיָה לָכֶם לְצִיצִית״ מְלַמֵּד שֶׁשְּׁנֵיהֶם מִצְוָה אַחַת. וְאַרְבַּע צִיצִיּוֹת מְעַכְּבוֹת זוֹ אֶת זוֹ שֶׁאַרְבַּעְתָּן מִצְוָה אַחַת. וְהַלּוֹבֵשׁ טַלִּית שֶׁיֵּשׁ בָּהּ לָבָן אוֹ תְּכֵלֶת אוֹ שְׁנֵיהֶם כְּאֶחָד הֲרֵי קִיֵּם מִצְוַת עֲשֵׂה אַחַת:","כֵּיצַד עוֹשִׂין אֶת הַצִּיצִית. מַתְחִיל מִזָּוִית שֶׁל טַלִּית שֶׁהִיא סוֹף הָאָרוּג וּמַרְחִיק מִמֶּנָּה לֹא יוֹתֵר עַל שָׁלֹשׁ אֶצְבָּעוֹת לְמַעְלָה וְלֹא פָּחוֹת מִקֶּשֶׁר גּוּדָל וּמַכְנִיס שָׁם אַרְבָּעָה חוּטִין וְכוֹפְלָן בָּאֶמְצַע. נִמְצְאוּ שְׁמוֹנָה חוּטִים מְשֻׁלָּשִׁין תְּלוּיִין מִן הַקֶּרֶן. וְאֹרֶךְ הַחוּטִים הַשְּׁמוֹנָה אֵין פָּחוֹת מֵאַרְבַּע אֶצְבָּעוֹת. וְאִם הָיוּ יוֹתֵר עַל כֵּן אֲפִלּוּ אַמָּה אוֹ שְׁתַּיִם כְּשֵׁרִין. וְכָל הָאֶצְבָּעוֹת בְּגוּדָל. וְיִהְיֶה אֶחָד מִשְּׁמוֹנָה הַחוּטִים חוּט תְּכֵלֶת וְהַשִּׁבְעָה לְבָנִים:","וְלוֹקֵחַ חוּט אֶחָד מִן הַלָּבָן וְכוֹרֵךְ בּוֹ כְּרִיכָה אַחַת עַל שְׁאָר הַחוּטִין בְּצַד הַבֶּגֶד וּמַנִּיחוֹ. וְלוֹקֵחַ חוּט הַתְּכֵלֶת וְכוֹרֵךְ בּוֹ שְׁתֵּי כְּרִיכוֹת בְּצַד כְּרִיכָה שֶׁל לָבָן וְקוֹשֵׁר. וְאֵלּוּ הַשָּׁלֹשׁ כְּרִיכוֹת הֵם הַנִּקְרָאִין חֻלְיָא. וּמַרְחִיק מְעַט וְעוֹשֶׂה חֻלְיָא שְׁנִיָּה בְּחוּט שֶׁל תְּכֵלֶת לְבַדּוֹ. וּמַרְחִיק מְעַט וְעוֹשֶׂה חֻלְיָא שְׁלִישִׁית וְכֵן עַד חֻלְיָא אַחֲרוֹנָה שֶׁהוּא כּוֹרֵךְ בָּהּ שְׁתֵּי כְּרִיכוֹת שֶׁל תְּכֵלֶת. וּכְרִיכָה אַחֲרוֹנָה שֶׁל לָבָן. מִפְּנֵי שֶׁהִתְחִיל בְּלָבָן מְסַיֵּם בּוֹ שֶׁמַּעֲלִין בַּקֹּדֶשׁ וְלֹא מוֹרִידִין. וְלָמָּה יַתְחִיל בְּלָבָן כְּדֵי שֶׁיְּהֵא סָמוּךְ לִכְנַף מִינָהּ. וְעַל דֶּרֶךְ זֶה הוּא עוֹשֶׂה בְּאַרְבַּע הַכְּנָפוֹת:","כַּמָּה חֻלְיוֹת הוּא עוֹשֶׂה בְּכָל כָּנָף. לֹא פָּחוֹת מִשֶּׁבַע וְלֹא יוֹתֵר מִשְּׁלֹשׁ עֶשְׂרֵה. וְזוֹ הִיא מִצְוָה מִן הַמֻּבְחָר. וְאִם לֹא כָּרַךְ עָלֶיהָ אֶלָּא חֻלְיָא אַחַת כְּשֵׁרָה. וְאִם כָּרַךְ הַתְּכֵלֶת עַל רֹב הַצִּיצִית כְּשֵׁרָה. וְנוֹי הַתְּכֵלֶת שֶׁיִּהְיוּ כָּל הַחֻלְיוֹת בִּשְׁלִישׁ הַחוּטִין הַמְשֻׁלְשָׁלִין וּשְׁנֵי שְׁלִישֵׁיהֶן עָנָף. וְצָרִיךְ לְפָרְדוֹ עַד שֶׁיִּהְיֶה כְּצִיצִית שְׂעַר הָרֹאשׁ:","הָעוֹשֶׂה לָבָן בְּלֹא תְּכֵלֶת לוֹקֵחַ אֶחָד מִשְּׁמוֹנָה הַחוּטִין וְכוֹרֵךְ אוֹתוֹ עַל שְׁאָר הַחוּטִין עַד שְׁלִישָׁן וּמַנִּיחַ שְׁנֵי שְׁלִישִׁיתָן עָנָף. וּכְרִיכָה זוֹ אִם רָצָה לִכְרֹךְ אוֹתָהּ חֻלְיוֹת חֻלְיוֹת כְּעֵין שֶׁכּוֹרֵךְ בַּתְּכֵלֶת הָרְשׁוּת בְּיָדוֹ וְזֶה הוּא מִנְהָגֵנוּ. וְאִם רָצָה לִכְרֹךְ בְּלֹא מִנְיַן חֻלְיוֹת עוֹשֶׂה. כְּלָלוֹ שֶׁל דָּבָר יִתְכַּוֵּן לִהְיוֹת הַכָּרוּךְ שְׁלִישׁ וְהֶעָנָף שְׁנֵי שְׁלִישִׁים. וְיֵשׁ מִי שֶׁאֵינוֹ מְדַקְדֵּק בְּדָבָר זֶה בְּלָבָן. וְאִם כָּרַךְ הַלָּבָן עַל רֹב הַחוּטִין אוֹ שֶׁלֹּא כָּרַךְ אֶלָּא חֻלְיָא אַחַת כְּשֵׁרָה:","אֶחָד חוּטֵי לָבָן וְאֶחָד חוּטֵי תְּכֵלֶת אִם רָצָה לַעֲשׂוֹת שְׁזוּרִין עוֹשֶׂה. אֲפִלּוּ הָיָה הַחוּט כָּפוּל מִשְּׁמוֹנָה חוּטִין וְשָׁזוּר עַד שֶׁנַּעֲשֶׂה פְּתִיל אֶחָד אֵינוֹ נֶחְשָׁב אֶלָּא חוּט אֶחָד:","חוּטֵי הַצִּיצִית בֵּין לָבָן בֵּין תְּכֵלֶת צְרִיכִין טְוִיָּה לְשֵׁם צִיצִית. וְאֵין עוֹשִׂין אוֹתָן לֹא מִן הַצֶּמֶר הַנֶּאֱחָז בַּקּוֹצִים כְּשֶׁהַצֹּאן רוֹבְצִין בֵּינֵיהֶם. וְלֹא מִן הַנִּימִין הַנִּתְלָשִׁין מִן הַבְּהֵמָה. וְלֹא מִשִּׁיּוּרֵי שְׁתִי שֶׁהָאוֹרֵג מְשַׁיֵּר בְּסוֹף הַבֶּגֶד. אֶלָּא מִן הַגִּזָּה שֶׁל צֶמֶר אוֹ מִן הַפִּשְׁתָּן. וְאֵין עוֹשִׂין אוֹתָן מִצֶּמֶר הַגָּזוּל וְלֹא מִשֶּׁל עִיר הַנִּדַּחַת וְלֹא מִשֶּׁל קָדָשִׁים. וְאִם עָשָׂה פָּסוּל. הַמִּשְׁתַּחֲוֶה לִבְהֵמָה צַמְרָהּ פָּסוּל לְצִיצִית. אֲבָל הַמִּשְׁתַּחֲוֶה לְפִשְׁתָּן הַנָּטוּעַ הֲרֵי זֶה כָּשֵׁר שֶׁהֲרֵי נִשְׁתַּנָּה:","צִיצִית שֶׁעָשָׂה אוֹתוֹ כּוּתִי פָּסוּל שֶׁנֶּאֱמַר (במדבר טו לח) ״דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל״ (במדבר טו לח) ״וְעָשׂוּ לָהֶם צִיצִת״. אֲבָל אִם עָשָׂה אוֹתָהּ יִשְׂרָאֵל בְּלֹא כַּוָּנָה כְּשֵׁרָה. וְצִיצִית שֶׁנַּעֲשָׂה מִן הֶעָשׂוּי מִקֹּדֶם פָּסוּל:","כֵּיצַד. הֵבִיא כָּנָף שֶׁיֵּשׁ בָּהּ צִיצִית וּתְפָרָהּ עַל הַבֶּגֶד אֲפִלּוּ יֵשׁ בְּאוֹתָהּ הַכָּנָף אַמָּה עַל אַמָּה פָּסוּל שֶׁנֶּאֱמַר (במדבר טו לח) ״וְעָשׂוּ לָהֶם צִיצִת״, לֹא מִן הֶעָשׂוּי, שֶׁהֲרֵי זֶה דּוֹמֶה לְמִי שֶׁנַּעֲשֵׂית מֵאֵלֶיהָ. וּמֻתָּר לְהַתִּיר צִיצִית מִבֶּגֶד זֶה וְלִתְלוֹתָם בְּבֶגֶד אַחֵר בֵּין לָבָן בֵּין תְּכֵלֶת:","תָּלָה הַחוּטִין בֵּין שְׁתֵּי כְּנָפַיִם מִזּוֹ לְזוֹ וְקָשַׁר כָּנָף זוֹ כְּהִלְכָתָהּ וְכָנָף זוֹ כְּהִלְכָתָהּ וְאַחַר כָּךְ חֲתָכָן בָּאֶמְצַע וְנִפְרְדוּ זֶה מִזֶּה פָּסוּל שֶׁהֲרֵי בְּעֵת שֶׁקְּשָׁרָן הָיוּ פְּסוּלִין לְפִי שֶׁשְּׁתֵּי הַכְּנָפַיִם מְעֹרוֹת זוֹ בָּזוֹ בַּחוּטִין שֶׁבֵּינֵיהֶן וּבְשָׁעָה שֶׁפְּסָקָן נַעֲשׂוּ שְׁתֵּי צִיצִיּוֹת נִמְצָא עוֹשֶׂה מִן הֶעָשׂוּי:","הִטִּיל צִיצִית עַל הַצִּיצִית אִם נִתְכַּוֵּן לְבַטֵּל אֶת הָרִאשׁוֹנוֹת מַתִּיר הָרִאשׁוֹנָה אוֹ חוֹתְכָהּ וּכְשֵׁרָה. וְאִם נִתְכַּוֵּן לְהוֹסִיף אַף עַל פִּי שֶׁחָתַךְ אַחַת מִשְּׁתֵּיהֶן הֲרֵי זוֹ פְּסוּלָה. שֶׁהֲרֵי כְּשֶׁהוֹסִיף פָּסַל אֶת הַכּל וּכְשֶׁהִתִּיר אוֹ חָתַךְ הַתּוֹסֶפֶת נִמְצָא הַשְּׁאָר נַעֲשָׂה מִן הֶעָשׂוּי שֶׁעֲשִׂיָּתוֹ הָרִאשׁוֹנָה פְּסוּלָה הָיְתָה:","וְכֵן הַמַּטִּיל לְבַעֲלַת שָׁלֹשׁ וְאַחַר כָּךְ הִשְׁלִימָהּ לְאַרְבַּע וְהִטִּיל לָרְבִיעִית כֻּלָּהּ פְּסוּלָה שֶׁנֶּאֱמַר (דברים כב יב) ״תַּעֲשֶׂה״ וְלֹא מִן הֶעָשׂוּי:","אֵין כּוֹפְלִין אֶת הַטַּלִּית לִשְׁנַיִם וּמַטִּילִין צִיצִית עַל אַרְבָּע כְּנָפֶיהָ כְּשֶׁהִיא כְּפוּלָה אֶלָּא אִם כֵּן תְּפָרָהּ כֻּלָּהּ וַאֲפִלּוּ מֵרוּחַ אַחַת:","נִפְסַק הַכָּנָף שֶׁיֵּשׁ בָּהּ צִיצִית חוּץ לְשָׁלֹשׁ אֶצְבָּעוֹת תּוֹפְרָהּ בִּמְקוֹמָהּ. בְּתוֹךְ שָׁלֹשׁ לֹא יִתְפֹּר. נִתְמַעֲטָה זָוִית שֶׁל בֶּגֶד שֶׁבֵּין חוּטֵי הַצִּיצִית וּבֵין סוֹף הָאָרוּג אֲפִלּוּ לֹא נִשְׁאַר מִן הָאָרוּג אֶלָּא כָּל שֶׁהוּא כָּשֵׁר. וְכֵן אִם נִתְמַעֲטוּ חוּטֵי הַצִּיצִית אֲפִלּוּ לֹא נִשְׁתַּיֵּר מֵהֶם אֶלָּא כְּדֵי עֲנִיבָה כָּשֵׁר. וְאִם נִפְסַק הַחוּט מֵעִקָּרוֹ אֲפִלּוּ חוּט אֶחָד פְּסוּלָה:"],"Mishneh Torah, Gifts to the Poor 9":["כָּל עִיר שֶׁיֵּשׁ בָּהּ יִשְׂרָאֵל חַיָּבִין לְהַעֲמִיד מֵהֶם גַּבָּאֵי צְדָקָה אֲנָשִׁים יְדוּעִים וְנֶאֱמָנִים שֶׁיִּהְיוּ מַחְזִירִין עַל הָעָם מֵעֶרֶב שַׁבָּת לְעֶרֶב שַׁבָּת וְלוֹקְחִין מִכָּל אֶחָד וְאֶחָד מַה שֶּׁהוּא רָאוּי לִתֵּן וְדָבָר הַקָּצוּב עָלָיו. וְהֵן מְחַלְּקִין הַמָּעוֹת מֵעֶרֶב שַׁבָּת לְעֶרֶב שַׁבָּת וְנוֹתְנִין לְכָל עָנִי וְעָנִי מְזוֹנוֹת הַמַּסְפִּיקִין לְשִׁבְעָה יָמִים. וְזוֹ הִיא הַנִּקְרֵאת קֻפָּה:","וְכֵן מַעֲמִידִין גַּבָּאִין שֶׁלּוֹקְחִין בְּכָל יוֹם וָיוֹם מִכָּל חָצֵר וְחָצֵר פַּת וּמִינֵי מַאֲכָל אוֹ פֵּרוֹת אוֹ מָעוֹת מִמִּי שֶׁמִּתְנַדֵּב לְפִי שָׁעָה. וּמְחַלְּקִין אֶת הַגָּבוּי לָעֶרֶב בֵּין הָעֲנִיִּים וְנוֹתְנִין לְכָל עָנִי מִמֶּנּוּ פַּרְנָסַת יוֹמוֹ. וְזֶהוּ הַנִּקְרָא תַּמְחוּי:","מֵעוֹלָם לֹא רָאִינוּ וְלֹא שָׁמַעְנוּ בְּקָהָל מִיִּשְׂרָאֵל שֶׁאֵין לָהֶן קֻפָּה שֶׁל צְדָקָה. אֲבָל תַּמְחוּי יֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ בּוֹ וְיֵשׁ מְקוֹמוֹת שֶׁלֹּא נָהֲגוּ בּוֹ. וְהַמִּנְהָג הַפָּשׁוּט הַיּוֹם שֶׁיִּהְיוּ גַּבָּאֵי הַקֻּפָּה מַחְזִירִין בְּכָל יוֹם וּמְחַלְּקִין מֵעֶרֶב שַׁבָּת לְעֶרֶב שַׁבָּת:","בְּתַעֲנִיּוֹת מְחַלְּקִים מְזוֹנוֹת לָעֲנִיִּים. וְכָל תַּעֲנִית שֶׁאָכְלוּ הָעָם וְלָנוּ וְלֹא חִלְּקוּ צְדָקָה לָעֲנִיִּים הֲרֵי אֵלּוּ כְּשׁוֹפְכֵי דָּמִים וַעֲלֵיהֶם נֶאֱמַר בַּקַּבָּלָה (ישעיה א כא) \"צֶדֶק יָלִין בָּהּ וְעַתָּה מְרַצְּחִים\". בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁלֹּא נָתְנוּ לָהֶן הַפַּת וְהַפֵּרוֹת שֶׁאוֹכְלִים בָּהֶם הַפַּת כְּגוֹן תְּמָרִים וַעֲנָבִים. אֲבָל אִם אֵחֲרוּ הַמָּעוֹת אוֹ הַחִטִּים אֵינָן כְּשׁוֹפְכֵי דָּמִים:","הַקֻּפָּה אֵינָהּ נִגְבֵּית אֶלָּא בִּשְׁנַיִם שֶׁאֵין עוֹשִׂים שְׂרָרָה עַל הַצִּבּוּר בְּמָמוֹן פָּחוֹת מִשְּׁנַיִם. וּמֻתָּר לְהַאֲמִין לְאֶחָד הַמָּעוֹת שֶׁל קֻפָּה. וְאֵינָהּ נֶחְלֶקֶת אֶלָּא בִּשְׁלֹשָׁה מִפְּנֵי שֶׁהִיא כְּדִינֵי מָמוֹנוֹת. שֶׁנּוֹתְנִים לְכָל אֶחָד דֵּי מַחֲסוֹרוֹ לְשַׁבָּת. והַתַּמְחוּי נִגְבֶּה בִּשְׁלֹשָׁה שֶׁאֵינוֹ דָּבָר קָצוּב. וּמִתְחַלֵּק בִּשְׁלֹשָׁה:","הַתַּמְחוּי נִגְבֶּה בְּכָל יוֹם. וְהַקֻּפָּה מֵעֶרֶב שַׁבָּת לְעֶרֶב שַׁבָּת. וְהַתַּמְחוּי לַעֲנִיֵּי עוֹלָם. וְהַקֻּפָּה לַעֲנִיֵּי אוֹתָהּ הָעִיר בִּלְבַד:","רַשָּׁאִין בְּנֵי הָעִיר לַעֲשׂוֹת קֻפָּה תַּמְחוּי. וְתַמְחוּי קֻפָּה. וּלְשַׁנּוֹתָן לְכָל מַה שֶּׁיִּרְצוּ מִצָּרְכֵי צִבּוּר. וְאַף עַל פִּי שֶׁלֹּא הִתְנוּ כֵּן בְּשָׁעָה שֶׁגָּבוּ. וְאִם הָיָה בַּמְּדִינָה חָכָם גָּדוֹל שֶׁהַכּל גּוֹבִין עַל דַּעְתּוֹ וְהוּא יְחַלֵּק לָעֲנִיִּים כְּפִי מַה שֶּׁיִּרְאֶה. הֲרֵי זֶה רַשַּׁאי לְשַׁנּוֹתָן לְכָל מַה שֶּׁיֵּרָאֶה לוֹ מִצָּרְכֵי צִבּוּר:","גַּבָּאֵי צְדָקָה אֵין רַשָּׁאִין לִפְרשׁ זֶה מִזֶּה בַּשּׁוּק. אֶלָּא כְּדֵי שֶׁיִּהְיֶה זֶה פּוֹרֵשׁ לַשַּׁעַר וְזֶה פּוֹרֵשׁ לַחֲנוּת וְגוֹבִין:","מָצָא הַגַּבַּאי מָעוֹת בַּשּׁוּק לֹא יִתְּנֵם לְתוֹךְ כִּיסוֹ אֶלָּא לְתוֹךְ אַרְנְקִי שֶׁל צְדָקָה. וּכְשֶׁיַּגִּיעַ לְבֵיתוֹ יִטְלֵם:","הָיָה הַגַּבַּאי נוֹשֶׁה בַּחֲבֵרוֹ מָנֶה וּפְרָעוֹ בַּשּׁוּק לֹא יִתְּנֵם לְתוֹךְ כִּיסוֹ אֶלָּא לְתוֹךְ אַרְנְקִי שֶׁל צְדָקָה. וּכְשֶׁיַּגִּיעַ לְבֵיתוֹ יִטְלֵם. וְלֹא יִמְנֶה מָעוֹת הַקֻּפָּה שְׁנַיִם שְׁנַיִם אֶלָּא אֶחָד אֶחָד מִפְּנֵי הַחֲשָׁד שֶׁנֶּאֱמַר (במדבר לב כב) \"וִהְיִיתֶם נְקִיִּים מֵה' וּמִיִּשְׂרָאֵל\":","גַּבָּאֵי צְדָקָה שֶׁאֵין לָהֶם עֲנִיִּים לְחַלֵּק מְצָרְפִין הַמָּעוֹת דִּינָרִין לַאֲחֵרִים אֲבָל לֹא לְעַצְמָן. גַּבָּאֵי תַּמְחוּי שֶׁאֵין לָהֶם עֲנִיִּים לְחַלֵּק מוֹכְרִים לַאֲחֵרִים וְאֵין מוֹכְרִים לְעַצְמָם. וְאֵין מְחַשְּׁבִים בִּצְדָקָה עִם גַּבָּאֵי צְדָקָה. וְלֹא בַּהֶקְדֵּשׁ עִם הַגִּזְבָּרִין. שֶׁנֶּאֱמַר (מלכים ב כב ז) \"אַךְ לֹא יֵחָשֵׁב אִתָּם הַכֶּסֶף הַנִּתָּן עַל יָדָם כִּי בֶּאֱמוּנָה הֵם עוֹשִׂים\":","מִי שֶׁיָּשַׁב בַּמְּדִינָה שְׁלֹשִׁים יוֹם כּוֹפִין אוֹתוֹ לִתֵּן צְדָקָה לַקֻּפָּה עִם בְּנֵי הַמְּדִינָה. יָשַׁב שָׁם שְׁלֹשָׁה חֳדָשִׁים כּוֹפִין אוֹתוֹ לִתֵּן הַתַּמְחוּי. יָשַׁב שָׁם שִׁשָּׁה חֳדָשִׁים כּוֹפִין אוֹתוֹ לִתֵּן צְדָקָה בִּכְסוּת שֶׁמְּכַסִּים בָּהּ עֲנִיֵּי הָעִיר. יָשַׁב שָׁם תִּשְׁעָה חֳדָשִׁים כּוֹפִין אוֹתוֹ לִתֵּן צְדָקָה לִקְבוּרָה שֶׁקּוֹבְרִין בָּהּ אֶת הָעֲנִיִּים וְעוֹשִׂין לָהֶם כָּל צָרְכֵי קְבוּרָה:","מִי שֶׁיֵּשׁ לוֹ מְזוֹן שְׁתֵּי סְעֻדּוֹת אָסוּר לוֹ לִטּל מִן הַתַּמְחוּי. הָיוּ לוֹ מְזוֹן אַרְבַּע עֶשְׂרֵה סְעֻדּוֹת לֹא יִטּל מִן הַקֻּפָּה. הָיוּ לוֹ מָאתַיִם זוּז אַף עַל פִּי שֶׁאֵינוֹ נוֹשֵׂא וְנוֹתֵן בָּהֶם [אוֹ שֶׁיֵּשׁ לוֹ חֲמִשִּׁים זוּז וְנוֹשֵׂא וְנוֹתֵן בָּהֶם] הֲרֵי זֶה לֹא יִטּל לֶקֶט שִׁכְחָה וּפֵאָה וּמַעֲשֵׂר עָנִי. הָיוּ לוֹ מָאתַיִם חָסֵר דִּינָר אֲפִלּוּ אֶלֶף נוֹתְנִין לוֹ כְּאֶחָד הֲרֵי זֶה מֻתָּר לִקַּח. הָיוּ בְּיָדוֹ מָעוֹת וַהֲרֵי הֵן עָלָיו חוֹב אוֹ שֶׁהָיוּ מְמֻשְׁכָּנִים לִכְתֻבַּת אִשְׁתּוֹ הֲרֵי זֶה מֻתָּר לִקַּח:","עָנִי שֶׁצָּרִיךְ וְיֵשׁ לוֹ חָצֵר וּכְלֵי בַּיִת אֲפִלּוּ הָיוּ לוֹ כְּלֵי כֶּסֶף וּכְלֵי זָהָב אֵין מְחַיְּבִין אוֹתוֹ לִמְכֹּר אֶת בֵּיתוֹ וְאֶת כְּלֵי תַּשְׁמִישׁוֹ אֶלָּא מֻתָּר לִקַּח. וּמִצְוָה לִתֵּן לוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים בִּכְלֵי אֲכִילָה וּשְׁתִיָּה וּמַלְבּוּשׁ וּמַצָּעוֹת וְכַיּוֹצֵא בָּהֶן. אֲבָל אִם הָיוּ כְּלֵי כֶּסֶף וּכְלֵי זָהָב כְּגוֹן מִגְרֶדֶת אוֹ עֵלִי וְכַיּוֹצֵא בָּהֶן מוֹכְרָן וְלוֹקֵחַ פָּחוֹת מֵהֶן. בַּמֶּה דְּבָרִים אֲמוּרִים קֹדֶם שֶׁיַּגִּיעַ לִגְבּוֹת מִן הָעָם. אֲבָל אַחַר שֶׁגָּבָה הַצְּדָקָה מְחַיְּבִים אוֹתוֹ לִמְכֹּר כֵּלָיו וְלִקַּח אֲחֵרִים פְּחוּתִין מֵהֶם וְאַחַר כָּךְ יִטּל:","בַּעַל הַבַּיִת שֶׁהָיָה מְהַלֵּךְ לָעִיר וְתַמּוּ לוֹ הַמָּעוֹת בַּדֶּרֶךְ וְאֵין לוֹ עַתָּה מַה יֹּאכַל הֲרֵי זֶה מֻתָּר לִקַּח לֶקֶט שִׁכְחָה וּפֵאָה וּמַעֲשַׂר עָנִי וְלֵהָנוֹת מִן הַצְּדָקָה. וְלִכְשֶׁיַּגִּיעַ לְבֵיתוֹ אֵינוֹ חַיָּב לְשַׁלֵּם שֶׁהֲרֵי עָנִי הָיָה בְּאוֹתָהּ שָׁעָה. הָא לְמָה זֶה דּוֹמֶה לֶעָנִי שֶׁהֶעֱשִׁיר שֶׁאֵינוֹ חַיָּב לְשַׁלֵּם:","מִי שֶׁהָיוּ לוֹ בָּתִּים שָׂדוֹת וּכְרָמִים וְאִם מוֹכְרָן בִּימֵי הַגְּשָׁמִים מוֹכְרָן בְּזוֹל וְאִם הִנִּיחָן עַד יְמוֹת הַחַמָּה מוֹכְרָן בְּשׁוְֹיֵהֶן. אֵין מְחַיְּבִין אוֹתוֹ לִמְכֹּר אֶלָּא מַאֲכִילִין אוֹתוֹ מַעֲשַׂר עָנִי עַד חֲצִי דְּמֵיהֶן וְלֹא יִדְחֹק עַצְמוֹ וְיִמְכֹּר שֶׁלֹּא בִּזְמַן מְכִירָה:","הָיוּ שְׁאָר הָאָדָם לוֹקְחִין בְּיֹקֶר וְהוּא אֵינוֹ מוֹצֵא שֶׁיִּקַּח מִמֶּנּוּ אֶלָּא בְּזוֹל מִפְּנֵי שֶׁהוּא דָּחוּק וְטָרוּד אֵין מְחַיְּבִין אוֹתוֹ לִמְכֹּר. אֶלָּא אוֹכֵל מַעֲשַׂר עָנִי וְהוֹלֵךְ עַד שֶׁיִּמְכֹּר בְּשָׁוֶה וְיֵדְעוּ הַכּל שֶׁאֵינוֹ דָּחוּק לִמְכֹּר:","עָנִי שֶׁגָּבוּ לוֹ כְּדֵי לְהַשְׁלִים מַחֲסוֹרוֹ וְהוֹתִירוּ עַל מַה שֶּׁהוּא צָרִיךְ הֲרֵי הַמּוֹתָר שֶׁלּוֹ. וּמוֹתַר עֲנִיִּים לָעֲנִיִּים. וּמוֹתַר שְׁבוּיִים לַשְּׁבוּיִים. מוֹתַר שָׁבוּי לְאוֹתוֹ שָׁבוּי. מוֹתַר מֵתִים לַמֵּתִים. מוֹתַר הַמֵּת לְיוֹרְשָׁיו:","עָנִי שֶׁנָּתַן פְּרוּטָה לַתַּמְחוּי אוֹ פְּרוּטָה לַקֻּפָּה מְקַבְּלִים מִמֶּנּוּ. וְאִם לֹא נָתַן אֵין מְחַיְּבִין אוֹתוֹ לִתֵּן. נָתְנוּ לוֹ בְּגָדִים חֲדָשִׁים וְהֶחֱזִיר לָהֶן אֶת הַשְּׁחָקִין מְקַבְּלִין מִמֶּנּוּ. וְאִם לֹא נָתַן אֵין מְחַיְּבִין אוֹתוֹ לִתֵּן:"],"Mishneh Torah, Heave Offerings 6":["תְּרוּמָה וּתְרוּמַת מַעֲשֵׂר נֶאֱכֶלֶת לְכֹהֲנִים בֵּין גְּדוֹלִים בֵּין קְטַנִּים בֵּין זְכָרִים בֵּין נְקֵבוֹת הֵם וְעַבְדֵיהֶם הַכְּנַעֲנִים וּבְהֶמְתָּן. שֶׁנֶּאֱמַר (ויקרא כב יא) \"וְכֹהֵן כִּי יִקְנֶה נֶפֶשׁ קִנְיַן כַּסְפּוֹ\" וְגוֹ'. עֶבֶד כֹּהֵן שֶׁבָּרַח וְאֵשֶׁת כֹּהֵן שֶׁמָּרְדָה הֲרֵי אֵלּוּ אוֹכְלִין:","תְּרוּמָה שֶׁל תּוֹרָה אֵין אוֹכֵל אוֹתָהּ אֶלָּא כֹּהֵן מְיֻחָס. אֲבָל כֹּהֲנֵי חֲזָקָה אוֹכְלִין בִּתְרוּמָה שֶׁל דִּבְרֵיהֶן בִּלְבַד. וּתְרוּמָה טְהוֹרָה בֵּין תְּרוּמָה גְּדוֹלָה בֵּין תְּרוּמַת מַעֲשֵׂר בֵּין שֶׁל תּוֹרָה בֵּין שֶׁל דִּבְרֵיהֶן אֵינָהּ נִתֶּנֶת אֶלָּא לְכֹהֵן תַּלְמִיד חָכָם. מִפְּנֵי שֶׁאָסוּר לֶאֱכל תְּרוּמָה טְמֵאָה. וְכָל עַמֵּי הָאָרֶץ בְּחֶזְקַת טֻמְאָה לְפִיכָךְ נוֹתְנִין תְּרוּמָה טְמֵאָה לְכָל כֹּהֵן שֶׁיִּרְצֶה:","יִשְׂרְאֵלִית שֶׁנִּשֵּׂאת לְכֹהֵן אֲפִלּוּ קְטַנָּה בַּת שָׁלֹשׁ שָׁנִים וְיוֹם אֶחָד תֹּאכַל בִּתְרוּמָה וְחָזֶה וְשׁוֹק. וְדִין תּוֹרָה שֶׁתֹּאכַל מִשֶּׁנִּתְאָרְסָה שֶׁהֲרֵי הִיא קִנְיָנוֹ. אֲבָל אָסְרוּ חֲכָמִים שֶׁתֹּאכַל עַד שֶׁתִּכָּנֵס לַחֻפָּה גְּזֵרָה שֶׁמָּא תַּאֲכִיל תְּרוּמָה לְאָבִיהָ וּלְאַחֶיהָ כְּשֶׁהִיא אֲרוּסָה בְּבֵית אָבִיהָ:","חֵרֶשֶׁת וְשׁוֹטָה שֶׁנִּשֵּׂאת לְכֹהֵן אֵינָהּ אוֹכֶלֶת בִּתְרוּמָה אֲפִלּוּ הִשִּׂיאָהּ אָבִיהָ גְּזֵרָה שֶׁמָּא יִשָּׂא חֵרֵשׁ כֹּהֵן חֵרֶשֶׁת וְיַאֲכִילֶנָּה. לְפִיכָךְ גָּזְרוּ שֶׁלֹּא תֹּאכַל חֵרֶשֶׁת בַּת יִשְׂרָאֵל כְּלָל:","הַזָּר אָסוּר לֶאֱכל תְּרוּמוֹת שֶׁנֶּאֱמַר (ויקרא כב י) \"וְכָל זָר לֹא יֹאכַל קֹדֶשׁ\" אֲפִלּוּ הָיָה תּוֹשַׁב כֹּהֵן אוֹ שְׂכִירוֹ שֶׁנֶּאֱמַר (ויקרא כב י) \"תּוֹשַׁב כֹּהֵן וְשָׂכִיר לֹא יֹאכַל קֹדֶשׁ\". תּוֹשָׁב זֶה שְׂכִיר עוֹלָם. שָׂכִיר זֶה שְׂכִיר שָׁנִים. וְעֶבֶד עִבְרִי הֲרֵי הוּא כְּתוֹשָׁב וְשָׂכִיר. וְכֹהֶנֶת אֵשֶׁת הַזָּר הֲרֵי הִיא כְּזָר שֶׁנֶּאֱמַר וְכָל זָר בֵּין הוּא בֵּין אִשְׁתּוֹ:","זָר שֶׁאָכַל תְּרוּמָה בְּזָדוֹן. בֵּין שֶׁהָיָה טָמֵא בֵּין שֶׁהָיָה טָהוֹר בֵּין שֶׁאָכַל תְּרוּמָה טְהוֹרָה בֵּין שֶׁאָכַל טְמֵאָה. חַיָּב מִיתָה בִּידֵי שָׁמַיִם שֶׁנֶּאֱמַר (ויקרא כב ט) \"וּמֵתוּ בוֹ כִּי יְחַלְּלֻהוּ\". וְלוֹקֶה עַל אֲכִילָתָהּ. וְאֵינוֹ מְשַׁלֵּם דְּמֵי מַה שֶּׁאָכַל שֶׁאֵינוֹ לוֹקֶה וּמְשַׁלֵּם. וְאִם אָכַל בִּשְׁגָגָה מוֹסִיף חֹמֶשׁ שֶׁנֶּאֱמַר (ויקרא כב יד) \"וְאִישׁ כִּי יֹאכַל קֹדֶשׁ בִּשְׁגָגָה וְיָסַף חֲמִשִׁיתוֹ\" וְגוֹ':","וּבַת כֹּהֵן כִּי תִהְיֶה לְאִישׁ זָר הִיא בִּתְרוּמַת הַקֳדָשִׁים לֹא תֹאכֵל. שְׁנֵי עִנְיָנִים נִכְלְלוּ בְּלָאו זֶה. שֶׁאִם תִּבָּעֵל לְאָסוּר לָהּ וְתֵעָשֶׂה זוֹנָה אוֹ חֲלָלָה כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת אִסּוּרֵי בִּיאָה הֲרֵי הִיא אֲסוּרָה לֶאֱכל בִּתְרוּמוֹת לְעוֹלָם כְּדִין כָּל חָלָל שֶׁהֶחָלָל כְּזָר לְכָל דָּבָר. וְאִם תִּנָּשֵׂא לְיִשְׂרָאֵל הֲרֵי הִיא אֲסוּרָה לֶאֱכל בַּמּוּרָם מִן הַקָּדָשִׁים שֶׁהוּא חָזֶה וְשׁוֹק לְעוֹלָם אַף עַל פִּי שֶׁגֵּרְשָׁהּ אוֹ מֵת:","אֲבָל הַתְּרוּמָה אוֹכֶלֶת אַחַר שֶׁגֵּרְשָׁהּ הַיִּשְׂרָאֵל אוֹ מֵת אִם לֹא הִנִּיחַ בֶּן מִמֶּנָּה. שֶׁנֶּאֱמַר (ויקרא כב יג) \"וּבַת כֹּהֵן כִּי תִהְיֶה אַלְמָנָה וּגְרוּשָׁה וְזֶרַע אֵין לָהּ וְשָׁבָה אֶל בֵּית אָבִיהָ כִּנְעוּרֶיהָ מִלֶּחֶם אָבִיהָ תֹּאכֵל\":","מִפִּי הַשְּׁמוּעָה לָמְדוּ (ויקרא כב יג) \"מִלֶּחֶם\" וְלֹא כָּל לֶחֶם. חוֹזֶרֶת הִיא לִתְרוּמָה וְלֹא לְחָזֶה וְשׁוֹק:","וְלֹא הַכֹּהֶנֶת בִּלְבַד אֶלָּא אֲפִלּוּ לְוִיָּה וְיִשְׂרְאֵלִית שֶׁנִּבְעֲלָה לְאָסוּר לָהּ הוֹאִיל וְנַעֲשֵׂית זוֹנָה אֲסוּרָה לֶאֱכל בִּתְרוּמָה לְעוֹלָם. וְאַף עַל פִּי שֶׁיֵּשׁ לָהּ זֶרַע מִכֹּהֵן:","לְפִיכָךְ הַשְּׁבוּיָה אֵינָהּ אוֹכֶלֶת בִּתְרוּמָה וְאַף עַל פִּי שֶׁאוֹמֶרֶת טְהוֹרָה אֲנִי. וְכָל שְׁבוּיָה שֶׁנֶּאֱמֶנֶת לוֹמַר טְהוֹרָה אֲנִי אוֹ שֶׁיֵּשׁ לָהּ עֵד כְּדֵי שֶׁתִּהְיֶה מֻתֶּרֶת לְבַעְלָהּ הֲרֵי זוֹ אוֹכֶלֶת בִּתְרוּמָה. וְהַנִּרְבַּעַת לִבְהֵמָה לֹא נִפְסְלָה מִן הַכְּהֻנָּה וְאוֹכֶלֶת:","יִשְׂרְאֵלִית שֶׁיֵּשׁ לָהּ זֶרַע מִכֹּהֵן אוֹכֶלֶת בִּשְׁבִיל בְּנָהּ בֵּין זָכָר בֵּין נְקֵבָה וַאֲפִלּוּ טֻמְטוּם וְאַנְדְּרוֹגִינוּס וַאֲפִלּוּ זֶרַע הַזֶּרַע עַד סוֹף כָּל הָעוֹלָם שֶׁנֶּאֱמַר (ויקרא כב יג) \"וְזֶרַע אֵין לָהּ\":","כְּשֵׁם שֶׁזֶּרַע יִשְׂרָאֵל מִכֹּהֶנֶת פּוֹסֵל אוֹתָהּ כָּךְ זֶרַע כֹּהֵן מִיִּשְׂרְאֵלִית מַאֲכִיל אוֹתָהּ וְאַף עַל פִּי שֶׁהוּא זֶרַע פָּסוּל. כֵּיצַד. בַּת יִשְׂרָאֵל שֶׁנִּשֵּׂאת לְכֹהֵן אוֹ כֹּהֶנֶת לְיִשְׂרָאֵל וְיָלְדָה מִמֶּנּוּ בַּת וּבָא עַל הַבַּת מִי שֶׁהוּא עֶרְוָה עָלֶיהָ אוֹ שֶׁנִּשֵּׂאת לְמַמְזֵר וּמֵתָה הַבַּת וַהֲרֵי הַמַּמְזֵר קַיָּם. הָיְתָה אֵם אִמּוֹ בַּת יִשְׂרָאֵל לְכֹהֵן תֹּאכַל בִּתְרוּמָה. בַּת כֹּהֵן לְיִשְׂרָאֵל לֹא תֹּאכַל:","הָא לָמַדְתָּ שֶׁהִיא אוֹכֶלֶת בִּשְׁבִיל זַרְעָהּ וְאַף עַל פִּי שֶׁאוֹתוֹ הַזֶּרַע פָּסוּל וַאֲפִלּוּ אֵינוֹ יִשְׂרָאֵל. וְאֵין צָרִיךְ לוֹמַר שֶׁאִם הָיְתָה לָהּ בַּת מִכֹּהֵן אַף עַל פִּי שֶׁהַבַּת נְשׂוּאָה לְיִשְׂרָאֵל וַאֲפִלּוּ נִתְחַלְּלָה הֲרֵי אִמָּהּ אוֹכֶלֶת בִּשְׁבִיל הַבַּת הַפְּסוּלָה:","כַּיּוֹצֵא בּוֹ הַכֹּהֶנֶת שֶׁאֵינָהּ אוֹכֶלֶת מִפְּנֵי זַרְעָהּ שֶׁמִּיִּשְׂרָאֵל אַף עַל פִּי שֶׁאוֹתוֹ הַזֶּרַע כֹּהֲנִים. כֵּיצַד. בַּת כֹּהֵן שֶׁנִּשֵּׂאת לְיִשְׂרָאֵל וְיָלְדָה מִמֶּנּוּ בַּת וְהָלְכָה הַבַּת וְנִשֵּׂאת לְכֹהֵן וְיָלְדָה מִמֶּנּוּ בֵּן. הֲרֵי זֶה רָאוּי לִהְיוֹת כֹּהֵן גָּדוֹל מַאֲכִיל אֶת אִמּוֹ וּפוֹסֵל אֶת אֵם אִמּוֹ וְאַף עַל פִּי שֶׁמֵּתָה אִמּוֹ וְזֹאת אוֹמֶרֶת לֹא כְּבֶן בִּתִּי כֹּהֵן גָּדוֹל שֶׁהוּא פּוֹסְלַנִי מִן הַתְּרוּמָה:","הָעֶבֶד אֵינוֹ פּוֹסֵל מִשּׁוּם זֶרַע וְאֵינוֹ מַאֲכִיל. כֵּיצַד. כֹּהֶנֶת שֶׁנִּשֵּׂאת לְיִשְׂרָאֵל אוֹ יִשְׂרְאֵלִית שֶׁנִּשֵּׂאת לְכֹהֵן וְיָלְדָה מִמֶּנּוּ בֵּן וְהָלַךְ הַבֵּן וְנִכְבַּשׁ עַל הַשִּׁפְחָה וְיָלְדָה מִמֶּנּוּ עֶבֶד וּמֵת הַבֵּן וַהֲרֵי הָעֶבֶד קַיָּם. הָיְתָה אֵם אָבִיו שֶׁל עֶבֶד זֶה בַּת יִשְׂרָאֵל לְכֹהֵן לֹא תֹּאכַל בִּתְרוּמָה. הָיְתָה בַּת כֹּהֵן לְיִשְׂרָאֵל תֹּאכַל שֶׁאֵין זֶה זֶרַע שֶׁהָעֲבָדִים אֵין לָהֶם יִחוּס:","בַּת יִשְׂרָאֵל שֶׁנִּשֵּׂאת לְכֹהֵן וּמֵת וְלָהּ מִמֶּנּוּ בֵּן וְחָזְרָה וְנִשֵּׂאת לְיִשְׂרָאֵל לֹא תֹּאכַל בִּתְרוּמָה. מֵת הַיִּשְׂרָאֵל וְלָהּ מִמֶּנּוּ בֵּן לֹא תֹּאכַל בִּתְרוּמָה מִפְּנֵי בְּנָהּ שֶׁמִּיִּשְׂרָאֵל. מֵת בְּנָהּ מִיִּשְׂרָאֵל אוֹכֶלֶת בִּשְׁבִיל בְּנָהּ הָרִאשׁוֹן:","בַּת כֹּהֵן שֶׁנִּשֵּׂאת לְיִשְׂרָאֵל וְיֵשׁ לָהּ מִמֶּנּוּ בֵּן וְחָזְרָה וְנִשֵּׂאת לְכֹהֵן תֹּאכַל בִּתְרוּמָה. מֵת וְלָהּ מִמֶּנּוּ בֵּן תֹּאכַל בִּתְרוּמָה. מֵת בְּנָהּ מִכֹּהֵן אֲסוּרָה לֶאֱכל מִפְּנֵי בְּנָהּ שֶׁמִּיִּשְׂרָאֵל. מֵת בְּנָהּ שֶׁמִּיִּשְׂרָאֵל חוֹזֶרֶת לְבֵית אָבִיהָ כִּנְעוּרֶיהָ וְאוֹכֶלֶת בִּתְרוּמָה לֹא בְּחָזֶה וְשׁוֹק:","בַּת יִשְׂרָאֵל שֶׁנִּשֵּׂאת לְיִשְׂרָאֵל תְּחִלָּה וְיֵשׁ לָהּ מִמֶּנּוּ בֵּן וְחָזְרָה וְנִשֵּׂאת לְכֹהֵן אוֹכֶלֶת בִּתְרוּמָה. מֵת וְלָהּ מִמֶּנּוּ בֵּן אוֹכֶלֶת מִפְּנֵי בְּנָהּ הָאַחֲרוֹן שֶׁהֲרֵי הוּא מַאֲכִילָהּ כְּמוֹ שֶׁהֶאֱכִילָהּ אָבִיו:"],"Mishneh Torah, Hiring 5":["הַשּׂוֹכֵר אֶת הַבְּהֵמָה וְחָלְתָה אוֹ נִשְׁתטֵּית אוֹ נִלְקְחָה לַעֲבוֹדַת הַמֶּלֶךְ אַף עַל פִּי שֶׁאֵין סוֹפָהּ לַחְזֹר אִם נִלְקְחָה דֶּרֶךְ הֲלִיכָה הֲרֵי הַמַּשְׂכִּיר אוֹמֵר לַשּׂוֹכֵר הֲרֵי שֶׁלְּךָ לְפָנֶיךָ וְחַיָּב לִתֵּן לוֹ שְׂכָרוֹ מִשָּׁלֵם. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁשְּׂכָרָהּ לָשֵׂאת עָלֶיהָ מַשּׂוֹי שֶׁאֶפְשָׁר לְהַשְׁלִיכוֹ בְּלֹא הַקְפָּדָה אֲבָל אִם שְׂכָרָהּ לִרְכֹּב עָלֶיהָ אוֹ לָשֵׂאת עָלֶיהָ כְּלֵי זְכוּכִית וְכַיּוֹצֵא בָּהֶן חַיָּב לְהַעֲמִיד לוֹ חֲמוֹר אַחֵר אִם שָׂכַר מִמֶּנּוּ חֲמוֹר וְאִם לֹא הֶעֱמִיד יַחְזִיר הַשָּׂכָר וְיַחְשֹׁב עִמּוֹ עַל שָׂכָר כַּמָּה שֶׁהָלַךְ בָּהּ:","מֵתָה הַבְּהֵמָה אוֹ נִשְׁבְּרָה בֵּין שֶׁשְּׂכָרָהּ לָשֵׂאת בֵּין שֶׁשְּׂכָרָהּ לִרְכֹּב אִם אָמַר לוֹ חֲמוֹר סְתָם אֲנִי מַשְׂכִּיר לְךָ חַיָּב לְהַעֲמִיד לוֹ חֲמוֹר אַחֵר מִכָּל מָקוֹם. וְאִם לֹא הֶעֱמִיד יֵשׁ לַשּׂוֹכֵר לִמְכֹּר הַבְּהֵמָה וְלִקַּח בָּהּ בְּהֵמָה אַחֶרֶת אוֹ שׂוֹכֵר בְּהֵמָה בְּדָמֶיהָ אִם אֵין בְּדָמֶיהָ לִקַּח עַד שֶׁיַּגִּיעַ לְמָקוֹם שֶׁפָּסַק בּוֹ. אָמַר לוֹ חֲמוֹר זֶה אֲנִי שׂוֹכֵר לְךָ אִם שְׂכָרָהּ לִרְכֹּב עָלֶיהָ אוֹ לִכְלֵי זְכוּכִית וּמֵתָה בַּחֲצִי הַדֶּרֶךְ אִם יֵשׁ בְּדָמֶיהָ לִקַּח בְּהֵמָה אַחֶרֶת יִקַּח וְאִם אֵין בְּדָמֶיהָ לִקַּח שׂוֹכֵר אֲפִלּוּ בִּדְמֵי כֻּלָּהּ עַד שֶׁיַּגִּיעַ לַמָּקוֹם שֶׁפָּסַק עִמּוֹ. וְאִם אֵין בְּדָמֶיהָ לֹא לִקַּח וְלֹא לִשְׂכֹּר נוֹתֵן לוֹ שְׂכָרוֹ שֶׁל חֲצִי הַדֶּרֶךְ וְאֵין לוֹ עָלָיו אֶלָּא תַּרְעֹמֶת. שְׂכָרָהּ לְמַשָּׂא הוֹאִיל וְאָמַר לוֹ חֲמוֹר זֶה וּמֵת בַּחֲצִי הַדֶּרֶךְ אֵינוֹ חַיָּב לְהַעֲמִיד לוֹ אַחֵר אֶלָּא נוֹתֵן לוֹ שְׂכָרוֹ שֶׁל חֲצִי הַדֶּרֶךְ וּמַנִּיחַ לוֹ נִבְלָתוֹ:","הַשּׂוֹכֵר אֶת הַסְּפִינָה וטָבְעָה לוֹ בַּחֲצִי הַדֶּרֶךְ. אִם אָמַר לוֹ סְפִינָה זוֹ אֲנִי מַשְׂכִּיר לְךָ וּשְׂכָרָהּ הַשּׂוֹכֵר לְהוֹלִיךְ בָּהּ יַיִן סְתָם אַף עַל פִּי שֶׁנָּתַן לוֹ הַשָּׂכָר יַחְזִיר כָּל הַשָּׂכָר שֶהֲרֵי זֶה אוֹמֵר לוֹ הָבֵא לִי הַסְּפִינָה עַצְמָהּ שֶשָּׂכַרְתִּי שֶׁהַקְפָּדָה גְּדוֹלָה יֵשׁ בִּסְפִינָה זוֹ וַאֲנִי אָבִיא יַיִן מִכָּל מָקוֹם וְאוֹלִיךְ בָּהּ. אָמַר לוֹ סְפִינָה סְתָם אֲנִי מַשְׂכִּיר לְךָ וּשְׂכָרָהּ הַשּׂוֹכֵר לְהוֹלִיךְ בָּהּ יַיִן זֶה אַף עַל פִּי שֶׁלֹּא נָתַן לוֹ מִן הַשָּׂכָר כְּלוּם חַיָּב לִתֵּן כָּל הַשָּׂכָר. שֶׁהֲרֵי אוֹמֵר לוֹ הָבֵא לִי הַיַּיִן עַצְמוֹ וַאֲנִי אָבִיא לְךָ סְפִינָה מִכָּל מָקוֹם וְאוֹלִיכוֹ. אֲבָל צָרִיךְ לְנַכּוֹת כְּדֵי הַטֹּרַח שֶׁל חֲצִי הַדֶּרֶךְ שֶׁאֵינוֹ דּוֹמֶה הַמְטַפֵּל בְּהוֹלָכַת הַסְּפִינָה לְיוֹשֵׁב וּבָטֵל. אָמַר לוֹ סְפִינָה זוֹ אֲנִי מַשְׂכִּיר וְשָׂכַר הַשּׂוֹכֵר לְהוֹלִיךְ בָּהּ יַיִן זֶה אִם נָתַן הַשָּׂכָר אֵינוֹ יָכוֹל לְהַחְזִירוֹ וְאִם לֹא נָתַן לֹא יִתֵּן שֶׁאֵין זֶה יָכוֹל לְהָבִיא הַסְּפִינָה עַצְמָהּ וְלֹא זֶה יָכוֹל לְהָבִיא יַיִן עַצְמוֹ. שָׂכַר סְפִינָה סְתָם לְיַיִן סְתָם הֲרֵי אֵלּוּ חוֹלְקִין הַשָּׂכָר:","הַשּׂוֹכֵר אֶת הַסְּפִינָה וּפָרְקָה בַּחֲצִי הַדֶּרֶךְ נוֹתֵן לוֹ שְׂכַר כָּל הַדֶּרֶךְ וְאִם מָצָא הַשּׂוֹכֵר מִי שֶׁיַּשְׂכִּיר אוֹתָהּ לוֹ עַד הַמָּקוֹם שֶׁפָּסַק שׂוֹכֵר וְיֵשׁ לְבַעַל הַסְּפִינָה עָלָיו תַּרְעֹמֶת. וְכֵן אִם מָכַר כָּל הַסְּחוֹרָה שֶׁבַּסְּפִינָה לְאִישׁ אַחֵר בַּחֲצִי הַדֶּרֶךְ וְיָרַד וְעָלָה הַלּוֹקֵחַ נוֹטֵל שְׂכַר חֲצִי הַדֶּרֶךְ מִן הָרִאשׁוֹן וּשְׂכַר הַחֵצִי מִזֶּה הָאַחֲרוֹן וְיֵשׁ לְבַעַל הַסְּפִינָה עָלָיו תַּרְעֹמֶת שֶׁגָּרַם לוֹ לִסְבֹּל דַּעַת אִישׁ אַחֵר שֶׁעֲדַיִן לֹא הֻרְגַּל בּוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","מִכָּאן אֲנִי אוֹמֵר שֶׁהַמַּשְׂכִּיר בַּיִת לַחֲבֵרוֹ עַד זְמַן קָצוּב וְרָצָה הַשּׂוֹכֵר לְהַשְׂכִּיר הַבַּיִת לְאַחֵר עַד סוֹף זְמַנּוֹ מַשְׂכִּיר לַאֲחֵרִים אִם יֵשׁ בְּנֵי בַּיִת כְּמִנְיַן בְּנֵי בֵּיתוֹ. אֲבָל אִם הָיוּ אַרְבָּעָה לֹא יִשְׂכֹּר לַחֲמִשָּׁה. שֶׁלֹּא אָמְרוּ חֲכָמִים אֵין הַשּׂוֹכֵר רַשַּׁאי לְהַשְׂכִּיר אֶלָּא מִטַּלְטְלִין שֶׁהֲרֵי אוֹמֵר לוֹ אֵין רְצוֹנִי שֶׁיְּהֵא פִּקְדוֹנִי בְּיַד אַחֵר אֲבָל בְּקַרְקַע אוֹ בִּסְפִינָה שֶׁהֲרֵי בַּעְלָהּ עִמָּהּ אֵין אוֹמֵר כֵּן. וְכֵן אֲנִי אוֹמֵר אִם אָמַר לוֹ בַּעַל הַבַּיִת לַשּׂוֹכֵר לָמָּה תִּטְרַח וְתַשְׂכִּיר בֵּיתִי לַאֲחֵרִים אִם לֹא תִּרְצֶה לַעֲמֹד בּוֹ צֵא הַנִּיחוֹ וְאַתָּה פָּטוּר מִשְּׂכִירָתוֹ אֵינוֹ יָכוֹל לְהַשְׂכִּירוֹ לְאַחֵר שֶׁזֶּה בְּאַל תִּמְנַע טוֹב מִבְּעָלָיו עַד שֶׁאַתָּה מַשְׂכִּירוֹ לְאַחֵר תַּנִּיחַ לָזֶה בֵּיתוֹ. וְיֵשׁ מִי שֶׁהוֹרָה שֶׁאֵינוֹ יָכוֹל לְהַשְׂכִּירוֹ לְאַחֵר כְּלָל וְיִתֵּן שְׂכָרוֹ עַד סוֹף זְמַנּוֹ וְלֹא יֵרָאֶה לִי שֶׁדִּין זֶה אֱמֶת:","בַּיִת זֶה אֲנִי מַשְׂכִּיר לְךָ וְאַחַר שֶׁהִשְׂכִּירוֹ נָפַל אֵינוֹ חַיָּב לִבְנוֹתוֹ אֶלָּא מְחַשֵּׁב עַל מַה שֶּׁנִּשְׁתַּמֵּשׁ בּוֹ וּמַחֲזִיר לוֹ שְׁאָר הַשְּׂכִירוּת. אֲבָל אִם סְתָרוֹ חַיָּב לְהַעֲמִיד לוֹ בַּיִת אַחֵר אוֹ יַשְׂכִּיר לוֹ כְּמוֹתוֹ. וְכֵן אִם חָזַר אַחַר שֶׁהִשְׂכִּירוֹ לָזֶה וְהִשְׂכִּירוֹ אוֹ מְכָרוֹ לְעַכּוּ\"ם אוֹ אַנָּס שֶׁהִפְקִיעַ שְׂכִירוּת הָרִאשׁוֹן הֲרֵי זֶה חַיָּב לְהַשְׂכִּיר לוֹ בַּיִת אַחֵר כְּמוֹתוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הִשְׂכִּיר לוֹ בַּיִת סְתָם וְאַחַר שֶׁנָּתַן לוֹ בַּיִת נָפַל חַיָּב לִבְנוֹתוֹ אוֹ יִתֵּן לוֹ בַּיִת אַחֵר. וְאִם הָיָה קָטָן מִן הַבַּיִת שֶׁנָּפַל אֵין הַשּׂוֹכֵר יָכוֹל לְעַכֵּב עָלָיו. וְהוּא שֶׁיִּהְיֶה קָרוּי בַּיִת שֶׁלֹּא הִשְׂכִּיר אֶלָּא בַּיִת סְתָם. אֲבָל אִם אָמַר לוֹ בַּיִת כָּזֶה אֲנִי מַשְׂכִּיר לְךָ חַיָּב לְהַעֲמִיד לוֹ בַּיִת כְּמִדַּת אָרְכּוֹ וּמִדַּת רָחְבּוֹ שֶׁל בַּיִת זֶה שֶׁהֶרְאָהוּ. וְאֵינוֹ יָכוֹל לוֹמַר לוֹ לֹא הָיָה עִנְיַן דְּבָרַי אֶלָּא שֶׁיִּהְיֶה קָרוֹב לַנָּהָר אוֹ לַשּׁוּק אוֹ לַמֶּרְחָץ כָּזֶה אֶלָּא חַיָּב לְהַעֲמִיד לוֹ בַּיִת כְּמִדָּתוֹ וּכְצוּרָתוֹ לְפִיכָךְ אִם הָיָה קָטָן לֹא יַעֲשֶׂנּוּ גָּדוֹל גָּדוֹל לֹא יַעֲשֶׂנּוּ קָטָן אֶחָד לֹא יַעֲשֶׂנּוּ שְׁנַיִם שְׁנַיִם לֹא יַעֲשֶׂנּוּ אֶחָד. וְלֹא יִפְחֹת מִן הַחַלּוֹנוֹת שֶׁהָיוּ בּוֹ וְלֹא יוֹסִיף עֲלֵיהֶן אֶלָּא מִדַּעַת שְׁנֵיהֶם:","הַמַּשְׂכִּיר עֲלִיָּה סְתָם חַיָּב לְהַעֲמִיד לוֹ עֲלִיָּה. אָמַר לוֹ עֲלִיָּה זוֹ שֶׁעַל גַּבֵּי בַּיִת זֶה אֲנִי מַשְׂכִּיר לְךָ הֲרֵי שִׁעְבֵּד בַּיִת לַעֲלִיָּה לְפִיכָךְ אִם נִפְחֲתָה הָעֲלִיָּה בְּאַרְבָּעָה טְפָחִים אוֹ יֶתֶר חַיָּב הַמַּשְׂכִּיר לְתַקֵּן וְאִם לֹא תִּקֵּן הֲרֵי הַשּׂוֹכֵר יוֹרֵד וְדָר בַּבַּיִת עִם בַּעַל הַבַּיִת עַד שֶׁיְּתַקֵּן. הָיוּ שְׁתֵּי עֲלִיּוֹת זוֹ עַל גַּבֵּי זוֹ וְנִפְחֲתָה הָעֶלְיוֹנָה דָּר בַּתַּחְתּוֹנָה. נִפְחֲתָה הַתַּחְתּוֹנָה הֲרֵי זֶה סָפֵק אִם יָדוּר בָּעֶלְיוֹנָה אוֹ בַּבַּיִת לְפִיכָךְ לֹא יָדוּר וְאִם דָּר אֵין מוֹצִיאִין אוֹתוֹ מִשָּׁם. מַעֲשֶׂה בְּאֶחָד שֶׁאָמַר לַחֲבֵרוֹ דַּלִּית זוֹ שֶׁעַל גַּבֵּי הַפַּרְסֵק הַזֶּה אֲנִי מַשְׂכִּיר לְךָ וְנֶעֱקַר אִילָן הַפַּרְסֵק מִמְּקוֹמוֹ וּבָא מַעֲשֶׂה לִפְנֵי חֲכָמִים וְאָמְרוּ לוֹ חַיָּב אַתָּה לְהַעֲמִיד הַפַּרְסֵק כָּל זְמַן שֶׁהַדַּלִּית קַיֶּמֶת. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:"],"Mishneh Torah, Immersion Pools 1":["כָּל הַטְּמֵאִין בֵּין אָדָם בֵּין כֵּלִים בֵּין שֶׁנִּטְמְאוּ טֻמְאָה חֲמוּרָה שֶׁל תּוֹרָה בֵּין שֶׁנִּטְמְאוּ בְּטֻמְאָה שֶׁל דִּבְרֵיהֶן אֵין לָהֶן טָהֳרָה אֶלָּא בִּטְבִילָה בְּמַיִם הַנִּקְוִין בְּקַרְקַע:","כָּל מָקוֹם שֶׁנֶּאֱמַר בַּתּוֹרָה רְחִיצַת בָּשָׂר וְכִבּוּס בְּגָדִים מִן הַטֻּמְאָה אֵינוֹ אֶלָּא טְבִילַת כָּל הַגּוּף בְּמִקְוֶה. וְזֶה שֶׁנֶּאֱמַר בְּזָב (ויקרא טו יא) \"וְיָדָיו לֹא שָׁטַף בַּמָּיִם\" כְּלוֹמַר שֶׁיִּטְבֹּל כָּל גּוּפוֹ. וְהוּא הַדִּין לִשְׁאָר הַטְּמֵאִין שֶׁאִם טָבַל כֻּלּוֹ חוּץ מֵרֹאשׁ אֶצְבַּע הַקְּטַנָּה עֲדַיִן הוּא בְּטֻמְאָתוֹ. וְכָל הַדְּבָרִים הָאֵלֶּה אַף עַל פִּי שֶׁהֵן מִפִּי הַשְּׁמוּעָה הֲרֵי נֶאֱמַר (ויקרא יא לב) \"בַּמַּיִם יוּבָא וְטָמֵא עַד הָעֶרֶב וְטָהֵר\" בִּנְיַן אָב לְכָל הַטְּמֵאִים שֶׁיָּבוֹאוּ בַּמַּיִם:","כָּל הַכֵּלִים שֶׁנִּטְמְאוּ יֵשׁ לָהֶן טָהֳרָה בְּמִקְוֶה חוּץ מִכְּלֵי חֶרֶס וּכְלֵי זְכוּכִית וְכֵן הַמַּפָּץ. כְּלִי חֶרֶס נֶאֱמַר בּוֹ (ויקרא יא לג) \"וְאֹתוֹ תִשְׁבֹּרוּ \"וְאֵין לוֹ טָהֳרָה אֶלָּא שְׁבִירָה. אֲפִלּוּ חִבְּרוֹ בְּקַרְקַע וַאֲפִלּוּ קְבָעוֹ בְּמַסְמֵר וַאֲפִלּוּ מִלְּאָהוּ סִיד אוֹ גְּפָסִים הֲרֵי הוּא כְּמוֹ שֶׁהָיָה עַד שֶׁיִּשָּׁבֵר. וּכְלֵי זְכוּכִית כִּכְלֵי חֶרֶס עֲשָׂאוּם בְּדָבָר זֶה:","הַמַּפָּץ אֵינוֹ בִּכְלַל הַכֵּלִים הַמְקַבְּלִים שְׁאָר כָּל הַטֻּמְאוֹת לְפִי שֶׁאֵינוֹ כְּלִי קִבּוּל אֵינוֹ מִכְּלַל כְּלֵי עֵץ הָאֲמוּרִין בַּתּוֹרָה וְהוֹאִיל וְהוּא רָאוּי לְמִשְׁכָּב נִתְרַבָּה לְטֻמְאַת מִדְרָס בִּלְבַד דִּין תּוֹרָה. וְכֵיוָן שֶׁאֵין לוֹ טֻמְאָה וְטָהֲרָה בְּפֵרוּשׁ וְנִתְרַבָּה לַטֻּמְאָה לֹא יִתְרַבֶּה לְטַהֵר בְּמִקְוֶה שֶׁאֵין מִתְטַהֵר בְּמִקְוֶה אֶלָּא הַכֵּלִים הָאֲמוּרִין בַּתּוֹרָה וְאֵין לַמַּפָּץ טָהֳרָה אֶלָּא קְרִיעָתוֹ עַד שֶׁיִּשָּׁאֵר פָּחוֹת מִשִּׁשָּׁה עַל שִׁשָּׁה טְפָחִים:","הַזָּב אֵין לוֹ טָהֳרָה אֶלָּא בְּמַעְיָן שֶׁהֲרֵי נֶאֱמַר בּוֹ (ויקרא טו יג) \"בְּמַיִם חַיִּים\" אֲבָל הַזָּבָה וּשְׁאָר הַטְּמֵאִין בֵּין אָדָם בֵּין כֵּלִים טוֹבְלִין אַף בְּמִקְוֶה:","כָּל חַיָּבֵי טְבִילוֹת טְבִילָתָן בַּיּוֹם חוּץ מִנִּדָּה וְיוֹלֶדֶת שֶׁטְּבִילָתָן בַּלַּיְלָה כְּמוֹ שֶׁבֵּאַרְנוּ בְּעִנְיַן נִדָּה. וּבַעַל קֶרִי טוֹבֵל וְהוֹלֵךְ כָּל הַיּוֹם כֻּלּוֹ מִתְּחִלַּת הַלַּיְלָה שֶׁנֶּאֱמַר (דברים כג יב) \"וְהָיָה לִפְנוֹת עֶרֶב יִרְחַץ בַּמָּיִם\" מְלַמֵּד שֶׁטּוֹבֵל וְהוֹלֵךְ מִתְּחִלַּת הַלַּיְלָה עַד הַעֲרֵב שֶׁמֶשׁ:","כָּל הַטּוֹבֵל צָרִיךְ שֶׁיִּטְבֹּל כָּל גּוּפוֹ כְּשֶׁהוּא עָרוּם בְּבַת אַחַת. וְאִם הָיָה בַּעַל שֵׂעָר יַטְבִּיל כָּל שְׂעַר רֹאשׁוֹ וַהֲרֵי הוּא כְּגוּפוֹ דִּין תּוֹרָה. וְכָל הַטְּמֵאִין שֶׁטָּבְלוּ בְּבִגְדֵיהֶן עָלְתָה לָהֶן טְבִילָה מִפְּנֵי שֶׁהַמַּיִם בָּאִין בָּהֶן וְאֵינָן חוֹצְצִין. וְכֵן הַנִּדָּה שֶׁטָּבְלָה בִּבְגָדֶיהָ מֻתֶּרֶת לְבַעֲלָהּ:","כָּל הַטּוֹבֵל צָרִיךְ לְהִתְכַּוֵּן לִטְבִילָה וְאִם לֹא נִתְכַּוֵּן עָלְתָה לוֹ טְבִילָה לְחֻלִּין. אֲפִלּוּ נִדָּה שֶׁטָּבְלָה בְּלֹא כַּוָּנָה כְּגוֹן שֶׁנָּפְלָה לְתוֹךְ הַמַּיִם אוֹ יָרְדָה לְהָקֵר הֲרֵי זוֹ מֻתֶּרֶת לְבַעֲלָהּ. אֲבָל לִתְרוּמָה וּלְקָדָשִׁים אֵינָהּ טְהוֹרָה עַד שֶׁתִּטְבֹּל בְּכַוָּנָה:","הַכּוֹפֵת יָדָיו וְרַגְלָיו וְיָשַׁב לוֹ בְּאַמַּת הַמַּיִם אִם נִכְנְסוּ מַיִם דֶּרֶךְ כֻּלּוֹ טָהוֹר. הַקּוֹפֵץ לְתוֹךְ הַמִּקְוֶה הֲרֵי זֶה מְגֻנֶּה. וְהַטּוֹבֵל פַּעֲמַיִם בַּמִּקְוֶה הֲרֵי זֶה מְגֻנֶּה. וְהָאוֹמֵר לַחֲבֵרוֹ כְּבשׁ יָדְךָ עָלַי בַּמִּקְוֶה הֲרֵי זֶה מְגֻנֶּה:","בֵּית הַסְּתָרִים וּבֵית הַקְּמָטִים אֵינָן צְרִיכִין שֶׁיָּבוֹאוּ בָּהֶן הַמַּיִם שֶׁנֶּאֱמַר (ויקרא טו יא) \"וְיָדָיו לֹא שָׁטַף בַּמָּיִם\" אֵיבָרִים הַנִּרְאִים בִּלְבַד. וְאַף עַל פִּי כֵן צְרִיכִין לִהְיוֹת רְאוּיִין שֶׁיָּבוֹאוּ בָּהֶן הַמַּיִם וְלֹא יִהְיֶה דָּבָר חוֹצֵץ לְפִיכָךְ אָמְרוּ חֲכָמִים לְעוֹלָם יִלְמֹד אָדָם בְּתוֹךְ בֵּיתוֹ שֶׁתִּהְיֶה אִשָּׁה מְדִיחָה בֵּין קְמָטֶיהָ בְּמַיִם וְאַחַר כָּךְ תִּטְבֹּל. וְהָאִשָּׁה טוֹבֶלֶת כְּדֶרֶךְ גְּדִילָתָהּ כְּאוֹרֶגֶת וּכְמֵינִיקָה אֶת בְּנָהּ:","אִשָּׁה אֵינָהּ טוֹבֶלֶת בַּנָּמֵל מִפְּנֵי שֶׁמִּתְבַּיֶּשֶׁת מִבְּנֵי הָעִיר וְאֵינָהּ טוֹבֶלֶת כַּהֹגֶן. וְאִם הִקִּיף לָהּ מַפָּץ וְכַיּוֹצֵא בּוֹ כְּדֵי לְהַצְנִיעָהּ טוֹבֶלֶת בַּנָּמֵל. וְלֹא תִּטְבֹּל עַל גַּבֵּי כְּלִי חֶרֶס אוֹ סַל וְכַיּוֹצֵא בָּהֶן מִפְּנֵי שֶׁמְּפַחֶדֶת וְלֹא תַּעֲלֶה לָהּ טְבִילָה:","אֶחָד הָאָדָם אוֹ הַכֵּלִים לֹא יִהְיֶה דָּבָר חוֹצֵץ בֵּינָם וּבֵין הַמַּיִם. וְאִם הָיָה דָּבָר חוֹצֵץ בֵּינָם וּבֵין הַמַּיִם כְּגוֹן שֶׁהָיָה בָּצֵק אוֹ טִיט מֻדְבָּק עַל בְּשַׂר הָאָדָם אוֹ עַל גּוּף הַכְּלִי הֲרֵי זֶה טָמֵא כְּשֶׁהָיָה וְלֹא עָלְתָה לָהֶן טְבִילָה. דְּבַר תּוֹרָה אִם הָיָה דָּבָר הַחוֹצֵץ חוֹפֶה אֶת רֹב הָאָדָם אוֹ רֹב הַכְּלִי לֹא עָלְתָה לָהֶן טְבִילָה וְהוּא שֶׁיַּקְפִּיד עָלָיו וְרוֹצֶה לְהַעֲבִירוֹ. אֲבָל אִם אֵינוֹ מַקְפִּיד עָלָיו וְלֹא שָׂם אוֹתוֹ עַל לֵב בֵּין עָבַר בֵּין לֹא עָבַר אֵינוֹ חוֹצֵץ וְאַף עַל פִּי שֶׁחוֹפֶה אֶת רֻבּוֹ. וְכֵן אִם הָיָה חוֹפֶה מִעוּטוֹ אֵינוֹ חוֹצֵץ אַף עַל פִּי שֶׁהוּא מַקְפִּיד עָלָיו. מִדִּבְרֵי סוֹפְרִים שֶׁכָּל דָּבָר הַחוֹצֵץ אִם הָיָה מַקְפִּיד עָלָיו לֹא עָלְתָה לוֹ טְבִילָה אַף עַל פִּי שֶׁהוּא עַל מִעוּטוֹ גְּזֵרָה מִשּׁוּם רֻבּוֹ. וְכָל דָּבָר הַחוֹצֵץ אִם הָיָה חוֹפֶה אֶת רֻבּוֹ לֹא עָלְתָה לוֹ טְבִילָה אַף עַל פִּי שֶׁאֵינוֹ מַקְפִּיד עָלָיו גְּזֵרָה מִשּׁוּם רֻבּוֹ הַמַּקְפִּיד עָלָיו. נִמְצֵאתָ אוֹמֵר שֶׁאִם הָיָה עַל בְּשַׂר הָאָדָם אוֹ עַל גּוּף הַכְּלִי דָּבָר מִדְּבָרִים הַחוֹצְצִין כְּגוֹן בָּצֵק וְזֶפֶת וְכַיּוֹצֵא בָּהֶן אֲפִלּוּ טִפָּה כְּחַרְדָּל וְהוּא מַקְפִּיד עָלָיו לֹא עָלְתָה לוֹ טְבִילָה. וְאִם אֵינוֹ מַקְפִּיד עָלָיו עָלְתָה לוֹ טְבִילָה. אֶלָּא אִם כֵּן הָיָה חוֹפֶה רֹב הַכְּלִי אוֹ רֹב הָאָדָם כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Inheritances 10":["שְׁנֵּי אַחִים שֶׁחָלְקוּ וּבָא לָהֶן אָח מִמְּדִינַת הַיָּם. וְכֵן שְׁלֹשָׁה אַחִין שֶׁחָלְקוּ וּבָא בַּעַל חוֹב וְנָטַל חֶלְקוֹ שֶׁל אֶחָד מֵהֶן. אֲפִלּוּ נָטַל זֶה קַרְקַע וְזֶה כְּסָפִים בָּטְלָה מַחְלֹקֶת וְחוֹזְרִין וְחוֹלְקִין הַשְּׁאָר בְּשָׁוֶה:","מִי שֶׁצִּוָּה בִּשְׁעַת מִיתָתוֹ שֶׁיִּתְּנוּ לִפְלוֹנִי דֶּקֶל אוֹ שָׂדֶה מִנְּכָסָיו וְחָלְקוּ הָאַחִין וְלֹא נָתְנוּ לִפְלוֹנִי כְּלוּם. הֲרֵי הַמַּחֲלֹקֶת בְּטֵלָה. וְכֵיצַד עוֹשִׂין. נוֹתְנִין מַה שֶּׁצִּוָּה מוֹרִישָׁן וְאַחַר כָּךְ חוֹזְרִין וְחוֹלְקִין כַּתְּחִלָּה:","הָאַחִין שֶׁחָלְקוּ שָׁמִין לָהֶן מַה שֶּׁעֲלֵיהֶן. אֲבָל מַה שֶּׁעַל בְּנֵיהֶן וּבְנוֹתֵיהֶן שֶׁקָּנוּ לָהֶן מִתְּפִיסַת הַבַּיִת אֵין שָׁמִין. וְכֵן מַה שֶּׁעַל נְשׁוֹתֵיהֶן. שֶׁכְּבָר זָכוּ בָּהֶן לְעַצְמָן. בַּמֶּה דְּבָרִים אֲמוּרִים בְּבִגְדֵי חֹל. אֲבָל בְּבִגְדֵי שַׁבָּת וּמוֹעֵד שָׁמִין מַה שֶּׁעֲלֵיהֶן:","מִי שֶׁהִנִּיחַ יְתוֹמִים מִקְצָתָן גְּדוֹלִים וּמִקְצָתָן קְטַנִּים וְרָצוּ לַחְלֹק בְּנִכְסֵי אֲבִיהֶן כְּדֵי שֶׁיִּטְּלוּ הַגְּדוֹלִים חֶלְקָן. מַעֲמִידִין בֵּית דִּין אַפּוֹטְרוֹפּוֹס לַקְּטַנִּים וּבוֹרֵר לָהֶן הַחֵלֶק הַיָּפֶה. וְאִם הִגְדִּילוּ אֵינָן יְכוֹלִין לִמְחוֹת שֶׁהֲרֵי עַל פִּי בֵּית דִּין חָלְקוּ לָהֶם. וְאִם טָעוּ בֵּית דִּין בַּשּׁוּמָא וּפָחֲתוּ שְׁתוּת. יְכוֹלִין לִמְחוֹת וְחוֹלְקִין חֲלוּקָה אַחֶרֶת אַחַר שֶׁהִגְדִּילוּ:","מִי שֶׁמֵּת וְהִנִּיחַ יוֹרְשִׁין גְּדוֹלִים וּקְטַנִּים צָרִיךְ לְמַנּוֹת אַפּוֹטְרוֹפּוֹס שֶׁיִּהְיֶה מִתְעַסֵּק בְּחֵלֶק הַקָּטָן עַד שֶׁיַּגְדִּיל. וְאִם לֹא מִנָּה חַיָּבִין בֵּית דִּין לְהַעֲמִיד לָהֶן אַפּוֹטְרוֹפּוֹס עַד שֶׁיַּגְדִּילוּ. שֶׁבֵּית דִּין הוּא אֲבִיהֶן שֶׁל יְתוֹמִים:","צִוָּה הַמּוֹרִישׁ וְאָמַר יִנָּתֵן חֵלֶק הַקָּטָן לַקָּטָן וּמַה שֶּׁיִּרְצֶה יַעֲשֶׂה בָּהּ הָרְשׁוּת בְּיָדוֹ. וְכֵן אִם מִנָּה הַמּוֹרִישׁ אַפּוֹטְרוֹפּוֹס עַל הַקְּטַנִּים קָטָן אוֹ אִשָּׁה אוֹ עֶבֶד הָרְשׁוּת בְּיָדוֹ. אֲבָל אֵין בֵּית דִּין מְמַנִּין אַפּוֹטְרוֹפּוֹס לֹא אִשָּׁה וְלֹא עֶבֶד וְלֹא קָטָן וְלֹא עַם הָאָרֶץ. שֶׁהוּא בְּחֶזְקַת חָשׁוּד עַל הָעֲבֵרוֹת. אֶלָּא בּוֹדְקִין עַל אָדָם נֶאֱמָן וְאִישׁ חַיִל וְיוֹדֵעַ לְהַפֵּךְ בִּזְכוּת הַיְתוֹמִים וְטוֹעֵן טַעֲנָתָם וְשֶׁיֵּשׁ לוֹ כֹּחַ בְּעִסְקֵי הָעוֹלָם כְּדֵי לִשְׁמֹר נְכָסִים וּלְהַרְוִיחַ בָּהֶן וּמַעֲמִידִין אוֹתוֹ עַל הַקְּטַנִּים. בֵּין שֶׁיִּהְיֶה רָחוֹק בֵּין שֶׁיִּהְיֶה קָרוֹב לַקָּטָן. אֶלָּא שֶׁאִם הָיָה קָרוֹב לֹא יֵרֵד לַקַּרְקָעוֹת:","בֵּית דִּין שֶׁהֶעֱמִידוּ אַפּוֹטְרוֹפּוֹס וְשָׁמְעוּ עָלָיו שֶׁהוּא אוֹכֵל וְשׁוֹתֶה וּמוֹצִיא הוֹצָאוֹת יֶתֶר מִדָּבָר שֶׁהָיָה אָמוּד בּוֹ יֵשׁ לָהֶן לָחוּשׁ לוֹ שֶׁמָּא מִנִּכְסֵי יְתוֹמִים הוּא אוֹכֵל וּמְסַלְּקִין אוֹתוֹ וּמַעֲמִידִין אַחֵר. אֲבָל אִם מִנָּהוּ אֲבִי יְתוֹמִים אֵין מְסַלְּקִין אוֹתוֹ שֶׁמָּא מְצִיאָה מָצָא. אֲבָל אִם בָּאוּ עֵדִים שֶׁהוּא מַפְסִיד נִכְסֵי יְתוֹמִים מְסַלְּקִין אוֹתוֹ. וּכְבָר הִסְכִּימוּ הַגְּאוֹנִים שֶׁמַּשְׁבִּיעִין אוֹתוֹ הוֹאִיל וּמַפְסִיד. וְהוּא הַדִּין לְאַפּוֹטְרוֹפּוֹס שֶׁמִּנָּהוּ אֲבִי יְתוֹמִים וְהָיְתָה שְׁמוּעָתוֹ טוֹבָה וְהָיָה יָשָׁר וְרוֹדֵף מִצְוֹת וְחָזַר לִהְיוֹת זוֹלֵל וְסוֹבֵא וְהוֹלֵךְ בְּדַרְכֵי הַחֲשָׁד אוֹ שֶׁפָּרַץ בִּנְדָרִים וּבַאֲבַק גֵּזֶל בֵּית דִּין חַיָּבִים לְסַלֵּק אוֹתוֹ וּלְהַשְׁבִּיעוֹ. וּלְמַנּוֹת לָהֶן אַפּוֹטְרוֹפּוֹס כָּשֵׁר. וְכָל הַדְּבָרִים הָאֵלּוּ כְּפִי מַה שֶּׁיֵּרָאֶה לַדַּיָּן שֶׁכָּל בֵּית דִּין וּבֵית דִּין הוּא אֲבִיהֶן שֶׁל יְתוֹמִים:","קָטָן שֶׁהִגְדִּיל אֲפִלּוּ הָיָה אוֹכֵל וְשׁוֹתֶה יוֹתֵר מִדַּאי וּמַפְסִיד וְהוֹלֵךְ בְּדֶרֶךְ רָעָה אֵין בֵּית דִּין מוֹנְעִין מִמֶּנּוּ מָמוֹנוֹ וְאֵין מַעֲמִידִין לוֹ אַפּוֹטְרוֹפּוֹס. אֶלָּא אִם כֵּן צִוָּה אָבִיו אוֹ מוֹרִישׁוֹ שֶׁלֹּא יִתְּנוּ לוֹ אֶלָּא אִם כֵּן יִהְיֶה כָּשֵׁר וּמַצְלִיחַ אוֹ שֶׁלֹּא יִתְּנוּ לוֹ עַד זְמַן מְרֻבֶּה. וְהַשּׁוֹטֶה וְהַחֵרֵשׁ הֲרֵי הֵן כִּקְטַנִּים וּמַעֲמִידִין לָהֶן אַפּוֹטְרוֹפּוֹס:"],"Mishneh Torah, Kings and Wars 11":["הַמֶּלֶךְ הַמָּשִׁיחַ עָתִיד לַעֲמֹד וּלְהַחְזִיר מַלכוּת דָּוִד לְיָשְׁנָהּ לַמֶּמְשָׁלָה הָרִאשׁוֹנָה. וּבוֹנֶה הַמִּקְדָּשׁ וּמְקַבֵּץ נִדְחֵי יִשְׂרָאֵל. וְחוֹזְרִין כָּל הַמִּשְׁפָּטִים בְּיָמָיו כְּשֶׁהָיוּ מִקֹּדֶם. מַקְרִיבִין קָרְבָּנוֹת. וְעוֹשִׂין שְׁמִטִּין וְיוֹבְלוֹת כְּכָל מִצְוָתָן הָאֲמוּרָה בַּתּוֹרָה. וְכָל מִי שֶׁאֵינוֹ מַאֲמִין בּוֹ. אוֹ מִי שֶׁאֵינוֹ מְחַכֶּה לְבִיאָתוֹ. לֹא בִּשְׁאָר נְבִיאִים בִּלְבַד הוּא כּוֹפֵר. אֶלָּא בַּתּוֹרָה וּבְמשֶׁה רַבֵּנוּ. שֶׁהֲרֵי הַתּוֹרָה הֵעִידָה עָלָיו שֶׁנֶּאֱמַר (דברים ל, ג) \"וְשָׁב ה' אֱלֹהֶיךָ אֶת שְׁבוּתְךָ וְרִחֲמֶךָ וְשָׁב וְקִבֶּצְךָ\" וְגוֹ' (דברים ל, ד) \"אִם יִהְיֶה נִדַּחֲךָ בִּקְצֵה הַשָּׁמָיִם\" וְגוֹ' (דברים ל, ה) \"וֶהֱבִיאֲךָ ה'\". וְאֵלּוּ הַדְּבָרִים הַמְפֹרָשִׁים בַּתּוֹרָה הֵם כּוֹלְלִים כָּל הַדְּבָרִים שֶׁנֶּאֶמְרוּ עַל יְדֵי כָּל הַנְּבִיאִים. אַף בְּפָרָשַׁת בִּלְעָם נֶאֱמַר וְשָׁם נִבֵּא בִּשְׁנֵי הַמְּשִׁיחִים. בַּמָּשִׁיחַ הָרִאשׁוֹן שֶׁהוּא דָּוִד שֶׁהוֹשִׁיעַ אֶת יִשְׂרָאֵל מִיַּד צָרֵיהֶם. וּבַמָּשִׁיחַ הָאַחֲרוֹן שֶׁעוֹמֵד מִבָּנָיו שֶׁמּוֹשִׁיעַ אֶת יִשְׂרָאֵל [בָּאַחֲרוֹנָה]. וְשָׁם הוּא אוֹמֵר (במדבר כד, יז) \"אֶרְאֶנּוּ וְלֹא עַתָּה\" זֶה דָּוִד. (במדבר כד, יז) \"אֲשׁוּרֶנּוּ וְלֹא קָרוֹב\" זֶה מֶלֶךְ הַמָּשִׁיחַ. (במדבר כד, יז) \"דָּרַךְ כּוֹכָב מִיַּעֲקֹב\" זֶה דָּוִד. (במדבר כד, יז) \"וְקָם שֵׁבֶט מִיִּשְׂרָאֵל\" זֶה מֶלֶךְ הַמָּשִׁיחַ. (במדבר כד, יז) \"וּמָחַץ פַּאֲתֵי מוֹאָב\" זֶה דָּוִד. וְכֵן הוּא אוֹמֵר (שמואל ב ח, ב) \"וַיַּךְ אֶת מוֹאָב וַיְמַדְּדֵם בַּחֶבֶל\" (במדבר כד, יז) \"וְקַרְקַר כָּל בְּנֵי שֵׁת\" זֶה הַמֶּלֶךְ הַמָּשִׁיחַ שֶׁנֶּאֱמַר בּוֹ (זכריה ט, י) \"וּמָשְׁלוֹ מִיָּם עַד יָם\". (במדבר כד, יח) \"וְהָיָה אֱדוֹם יְרֵשָׁה\" זֶה דָּוִד. שֶׁנֶּאֱמַר (שמואל ב ח, יד) \"וַתְּהִי אֱדוֹם לְדָוִד לַעֲבָדִים\" וְגוֹ'. (במדבר כד, יח) \"וְהָיָה יְרֵשָׁה\" וְגוֹ' זֶה הַמֶּלֶךְ הַמָּשִׁיחַ שֶׁנֶּאֱמַר (עובדיה א, כא) \"וְעָלוּ מוֹשִׁעִים בְּהַר צִיּוֹן\" וְגוֹ':","אַף בְּעָרֵי מִקְלָט הוּא אוֹמֵר (דברים יט, ח) \"אִם יַרְחִיב ה' אֱלֹהֶיךָ אֶת גְּבֻלְךָ\" (דברים יט, ט) \"וְיָסַפְתָּ לְךָ עוֹד שָׁלֹשׁ עָרִים\" וְגוֹ'. וּמֵעוֹלָם לֹא הָיָה דָּבָר זֶה. וְלֹא צִוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לְתֹהוּ. אֲבָל בְּדִבְרֵי הַנְּבִיאִים אֵין הַדָּבָר צָרִיךְ רְאָיָה שֶׁכָּל הַסְּפָרִים מְלֵאִים בְּדָבָר זֶה:","וְאַל יַעֲלֶה עַל דַּעְתְּךָ שֶׁהַמֶּלֶךְ הַמָּשִׁיחַ צָרִיךְ לַעֲשׂוֹת אוֹתוֹת וּמוֹפְתִים וּמְחַדֵּשׁ דְּבָרִים בָּעוֹלָם אוֹ מְחַיֶּה מֵתִים וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ [ב.] אֵין הַדָּבָר כָּךְ. שֶׁהֲרֵי רַבִּי עֲקִיבָא חָכָם גָּדוֹל מֵחַכְמֵי מִשְׁנָה הָיָה. וְהוּא הָיָה נוֹשֵׂא כֵּלָיו שֶׁל בֶּן כּוֹזִיבָא הַמֶּלֶךְ. וְהוּא הָיָה אוֹמֵר עָלָיו שֶׁהוּא הַמֶּלֶךְ הַמָּשִׁיחַ. וְדִמָּה הוּא וְכָל חַכְמֵי דּוֹרוֹ שֶׁהוּא הַמֶּלֶךְ הַמָּשִׁיחַ. עַד שֶׁנֶּהֱרַג בַּעֲוֹנוֹת. כֵּיוָן שֶׁנֶּהֱרַג נוֹדַע לָהֶם שֶׁאֵינוֹ. וְלֹא שָׁאֲלוּ מִמֶּנּוּ חֲכָמִים לֹא אוֹת וְלֹא מוֹפֵת. וְעִקַּר הַדְּבָרִים כָּכָה הֵן. שֶׁהַתּוֹרָה הַזֹּאת חֻקֶּיהָ וּמִשְׁפָּטֶיהָ לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים. וְאֵין מוֹסִיפִין עֲלֵיהֶן וְלֹא גּוֹרְעִין מֵהֶן:","וְאִם יַעֲמֹד מֶלֶךְ מִבֵּית דָּוִד הוֹגֶה בַּתּוֹרָה וְעוֹסֵק בְּמִצְוֹת כְּדָוִד אָבִיו. כְּפִי תּוֹרָה שֶׁבִּכְתָב וְשֶׁבְּעַל פֶּה. וְיָכֹף כָּל יִשְׂרָאֵל לֵילֵךְ בָּהּ וּלְחַזֵּק בִּדְקָהּ. וְיִלָּחֵם מִלְחֲמוֹת ה'. הֲרֵי זֶה בְּחֶזְקַת שֶׁהוּא מָשִׁיחַ. (אִם עָשָׂה וְהִצְלִיחַ וּבָנָה מִקְדָּשׁ בִּמְקוֹמוֹ וְקִבֵּץ נִדְחֵי יִשְׂרָאֵל הֲרֵי זֶה מָשִׁיחַ בְּוַדַּאי. וִיתַקֵּן אֶת הָעוֹלָם כֻּלּוֹ לַעֲבֹד אֶת ה' בְּיַחַד שֶׁנֶּאֱמַר כִּי אָז אֶהְפֹּךְ אֶל עַמִּים שָׂפָה בְרוּרָה לִקְרֹא כֻלָּם בְּשֵׁם ה' וּלְעָבְדוֹ שְׁכֶם אֶחָד):","וְאִם לֹא הִצְלִיחַ עַד כֹּה, אוֹ נֶהֱרָג, בְּיָדוּעַ שֶׁאֵינוֹ זֶה שֶׁהִבְטִיחָה עָלָיו תּוֹרָה, וַהֲרֵי הוּא כְּכָל מַלְכֵי בֵּית דָּוִד הַשְּׁלֵמִים הַכְּשֵׁרִים שֶׁמֵּתוּ. וְלֹא הֶעֱמִידוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא אֶלָּא לְנַסּוֹת בּוֹ רַבִּים, שֶׁנֶּאֱמַר \"וּמִן הַמַּשְׂכִּילִים יִכָּשְׁלוּ לִצְרוֹף בָּהֶן וּלְבָרֵר וְלַלְבֵּן עַד עֵת קֵץ כִּי עוֹד לַמּוֹעֵד\".","אַף יֵשׁוּעַ הַנּוֹצְרִי שֶׁדִּימָה שֶׁיִּהְיֶה מָשִׁיחַ, וְנֶהֱרָג בְּבֵית דִּין, כְּבָר נִתְנַבֵּא בּוֹ דָּנִיֵּאל, שֶׁנֶּאֱמַר \"וּבְנֵי פָּרִיצֵי עַמְּךָ יִנַּשְּׂאוּ לְהַעֲמִיד חָזוֹן וְנִכְשָׁלוּ\" (דניאל יא, יד). וְכִי יֵשׁ מִכְשׁוֹל גָּדוֹל מִזֶּה, שֶׁכָּל הַנְּבִיאִים דִּבְּרוּ שֶׁהַמָּשִׁיחַ גּוֹאֵל יִשְׂרָאֵל וּמוֹשִׁיעָם, וּמְקַבֵּץ נִדְחֵיהֶם וּמְחַזֵּק מִצְוָתָן, וְזֶה גָּרַם לְאַבֵּד יִשְׂרָאֵל בַּחֶרֶב, וּלְפַזֵּר שְׁאֵרִיתָם וּלְהַשְׁפִּילָם, וּלְהַחֲלִיף הַתּוֹרָה, וּלְהַטְעוֹת רוֹב הָעוֹלָם לַעֲבֹד אֱלוֹהַּ מִבַּלְעֲדֵי ה'.","אֲבָל מַחְשְׁבוֹת בּוֹרֵא עוֹלָם אֵין כּוֹחַ בָּאָדָם לְהַשִּׂיגָם, כִּי לֹא דְּרָכֵינוּ דְּרָכָיו וְלֹא מַחְשְׁבוֹתֵינוּ מַחְשְׁבוֹתָיו. וְכָל הַדְּבָרִים הָאֵלּוּ שֶׁל יֵשׁוּעַ הַנּוֹצְרִי, וְשֶׁל זֶה הַיִּשְׁמְעֵאלִי שֶׁעָמַד אַחֲרָיו, אֵינָן אֶלָּא לְיַשֵּׁר דֶּרֶךְ לַמֶּלֶךְ הַמָּשִׁיחַ, וּלְתַקֵּן אֶת הָעוֹלָם כֻּלּוּ לַעֲבֹד אֶת ה' בְּיַחַד: שֶׁנֶּאֱמַר \"כִּי אָז אֶהְפֹּךְ אֶל עַמִּים שָׂפָה בְרוּרָה לִקְרֹא כֻּלָּם בְּשֵׁם ה' וּלְעוֹבְדוֹ שְׁכֶם אֶחָד\" (ראה צפניה ג, ט).","כֵּיצַד: כְּבָר נִתְמַלֵּא הָעוֹלָם כֻּלּוֹ מִדִּבְרֵי הַמָּשִׁיחַ, וּמִדִּבְרֵי הַתּוֹרָה וּמִדִּבְרֵי הַמִּצְווֹת, וּפָשְׁטוּ דְּבָרִים אֵלּוּ בְּאִיִּים רְחוֹקִים, וּבְעַמִּים רַבִּים עַרְלֵי לֵב; וְהֵם נוֹשְׂאִים וְנוֹתְנִים בִּדְבָרִים אֵלּוּ וּבְמִצְווֹת הַתּוֹרָה, אֵלּוּ אוֹמְרִים מִצְווֹת אֵלּוּ אֱמֶת הָיוּ, וּכְבָר בָּטְלוּ בַּזְּמַן הַזֶּה, וְלֹא הָיוּ נוֹהֲגוֹת לְדוֹרוֹת. וְאֵלּוּ אוֹמְרִים דְּבָרִים נִסְתָּרוֹת יֵשׁ בָּהֶם, וְאֵינָן כִּפְשׁוּטָן, וּכְבָר בָּא מָשִׁיחַ, וְגִלָּה נִסְתְּרֵיהֶם.","וּכְשֶׁיַּעֲמוֹד הַמֶּלֶךְ הַמָּשִׁיחַ בֶּאֱמֶת, וְיַצְלִיחַ וְיָרוּם וְיִינָשֵׂא, מִיַּד הֵם כּוּלָן חוֹזְרִין וְיוֹדְעִים שֶׁשֶּׁקֶר נָחֲלוּ אֲבוֹתֵיהֶם, וְשֶׁנְּבִיאֵיהֶם וַאֲבוֹתֵיהֶם הִטְעוּם."],"Mishneh Torah, Leavened and Unleavened Bread 3":["כְּשֶׁבוֹדֵק אָדָם וּמְחַפֵּשׂ בְּלֵילֵי אַרְבָּעָה עָשָׂר מוֹצִיא אֶת הֶחָמֵץ מִן הַחוֹרִים וּמִן הַמַּחֲבוֹאוֹת וּמִן הַזָּוִיּוֹת וּמְקַבֵּץ הַכּל וּמַנִּיחוֹ בְּמָקוֹם אֶחָד עַד תְּחִלַּת שָׁעָה שִׁשִּׁית בַּיּוֹם וּמְבָעֲרוֹ. וְאִם רָצָה לְבַעֲרוֹ בְּלֵילֵי אַרְבָּעָה עָשָׂר מְבַעֲרוֹ:","הֶחָמֵץ שֶׁמַּנִּיחַ בְּלֵילֵי אַרְבָּעָה עָשָׂר כְּדֵי שֶׁיֹּאכַל מִמֶּנּוּ לְמָחָר עַד אַרְבַּע שָׁעוֹת אֵינוֹ מַנִּיחוֹ מְפֻזָּר וּמְפֹרָד בְּכָל מָקוֹם אֶלָּא מַצְנִיעוֹ בִּכְלִי אוֹ בְּזָוִית יְדוּעָה וְיִזָּהֵר בּוֹ. שֶׁאִם לֹא נִזְהַר בּוֹ וּמְצָאוֹ חָסֵר צָרִיךְ לְחַפֵּשׂ אַחֲרָיו וְלִבְדֹּק פַּעַם אַחֶרֶת שֶׁמָּא גְּרָרוּהוּ הָעַכְבָּרִים:","חָל אַרְבָּעָה עָשָׂר לִהְיוֹת בְּשַׁבָּת בּוֹדְקִין אֶת הֶחָמֵץ בְּלֵילֵי עֶרֶב שַׁבָּת שֶׁהוּא לֵיל שְׁלֹשָׁה עָשָׂר וּמַנִּיחַ מִן הֶחָמֵץ כְּדֵי לֶאֱכל מִמֶּנּוּ עַד אַרְבַּע שָׁעוֹת בְּיוֹם הַשַּׁבָּת. וּמַנִּיחוֹ בְּמָקוֹם מֻצְנָע וְהַשְּׁאָר מְבָעֲרוֹ מִלִּפְנֵי הַשַּׁבָּת. וְאִם נִשְׁאַר מִן הֶחָמֵץ בְּיוֹם הַשַּׁבָּת אַחַר אַרְבַּע שָׁעוֹת מְבַטְּלוֹ וְכוֹפֶה עָלָיו כְּלִי עַד מוֹצָאֵי יוֹם טוֹב הָרִאשׁוֹן וּמְבָעֲרוֹ:","הָיוּ לוֹ כִּכָּרוֹת רַבּוֹת שֶׁל תְּרוּמָה וְצָרִיךְ לְשָׂרְפָהּ עֶרֶב שַׁבָּת לֹא יְעָרֵב הַטְּהוֹרָה עִם הַטְּמֵאָה וְיִשְׂרֹף אֶלָּא שׂוֹרֵף טְמֵאָה לְעַצְמָהּ וּטְהוֹרָה לְעַצְמָהּ וּתְלוּיָה לְעַצְמָהּ. וּמַנִּיחַ מִן הַטְּהוֹרָה כְּדֵי לֶאֱכל עַד אַרְבַּע שָׁעוֹת בְּיוֹם הַשַּׁבָּת בִּלְבַד:","מִי שֶׁשָּׁכַח אוֹ הֵזִיד וְלֹא בָּדַק בְּלֵיל אַרְבָּעָה עָשָׂר בּוֹדֵק אַרְבָּעָה עָשָׂר בְּשַׁחֲרִית. לֹא בָּדַק בְּשַׁחֲרִית בּוֹדֵק בִּשְׁעַת הַבִּעוּר. לֹא בָּדַק בִּשְׁעַת הַבִּעוּר בּוֹדֵק בְּתוֹךְ הֶחָג. עָבַר הָרֶגֶל וְלֹא בָּדַק בּוֹדֵק אַחַר הָרֶגֶל כְּדֵי שֶׁיְּבָעֵר מַה שֶּׁיִּמְצָא מֵחָמֵץ שֶׁעָבַר עָלָיו הַפֶּסַח מִפְּנֵי שֶׁהוּא אָסוּר בַּהֲנָיָה:","כְּשֶׁבּוֹדֵק הֶחָמֵץ בְּלֵילֵי אַרְבָּעָה עָשָׂר אוֹ בְּיוֹם אַרְבָּעָה עָשָׂר אוֹ בְּתוֹךְ הָרֶגֶל מְבָרֵךְ קֹדֶם שֶׁיַּתְחִיל לִבְדֹּק בָּרוּךְ אַתָּה ה' אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ עַל בִּעוּר חָמֵץ. וּבוֹדֵק וּמְחַפֵּשׂ בְּכָל הַמְּקוֹמוֹת שֶׁמַּכְנִיסִין לָהֶם חָמֵץ כְּמוֹ שֶׁבֵּאַרְנוּ. וְאִם בָּדַק לְאַחַר הָרֶגֶל אֵינוֹ מְבָרֵךְ:","וּכְשֶׁגּוֹמֵר לִבְדֹּק אִם בָּדַק בְּלֵיל אַרְבָּעָה עָשָׂר אוֹ בְּיוֹם אַרְבָּעָה עָשָׂר קֹדֶם שֵׁשׁ שָׁעוֹת צָרִיךְ לְבַטֵּל כָּל חָמֵץ שֶׁנִּשְׁאַר בִּרְשׁוּתוֹ וְאֵינוֹ רוֹאֵהוּ. וְיֹאמַר כָּל חָמֵץ שֶׁיֵּשׁ בִּרְשׁוּתִי שֶׁלֹּא רְאִיתִיו הֲרֵי הוּא בָּטֵל וַהֲרֵי הוּא כְּעָפָר. אֲבָל אִם בָּדַק מִתְּחִלַּת שָׁעָה שִׁשִּׁית וּלְמַעְלָה אֵינוֹ יָכוֹל לְבַטֵּל שֶׁהֲרֵי אֵינוֹ בִּרְשׁוּתוֹ שֶׁכְּבָר נֶאֱסַר בַּהֲנָיָה:","לְפִיכָךְ אִם לֹא בִּטֵּל קֹדֶם שֵׁשׁ וּמִשֵּׁשׁ שָׁעוֹת וּלְמַעְלָה מָצָא חָמֵץ שֶׁהָיָה דַּעְתּוֹ עָלָיו וְהָיָה בְּלִבּוֹ וּשְׁכָחוֹ בִּשְׁעַת הַבִּעוּר וְלֹא בִּעֲרוֹ הֲרֵי זֶה עָבַר עַל (שמות יג ז) (דברים טז ד) \"לֹא יֵרָאֶה\" וְ (שמות יב יט) \"לֹא יִמָּצֵא\" שֶׁהֲרֵי לֹא בִּעֵר וְלֹא בִּטֵּל. וְאֵין הַבִּטּוּל עַתָּה מוֹעִיל לוֹ כְּלוּם לְפִי שֶׁאֵינוֹ בִּרְשׁוּתוֹ וְהַכָּתוּב עֲשָׂהוּ כְּאִלּוּ הוּא בִּרְשׁוּתוֹ לְחַיְּבוֹ מִשּׁוּם לֹא יֵרָאֶה וְלֹא יִמָּצֵא. וְחַיָּב לְבַעֲרוֹ בְּכָל עֵת שֶׁיִּמְצָאֶנּוּ. וְאִם מְצָאוֹ בְּיוֹם טוֹב כּוֹפֶה עָלָיו כְּלִי עַד לָעֶרֶב וּמְבַעֲרוֹ. וְאִם שֶׁל הֶקְדֵּשׁ הוּא אֵינוֹ צָרִיךְ לִכְפּוֹת עָלָיו כְּלִי שֶׁהַכּל פּוֹרְשִׁין מִמֶּנּוּ:","מִי שֶׁיָּצָא מִבֵּיתוֹ קֹדֶם שְׁעַת הַבִּעוּר לַעֲשׂוֹת מִצְוָה אוֹ לֶאֱכל סְעֻדָּה שֶׁל מִצְוָה כְּגוֹן סְעֻדַּת אֵרוּסִין וְנִשּׂוּאִין וְנִזְכַּר שֶׁיֵּשׁ לוֹ חָמֵץ בְּתוֹךְ בֵּיתוֹ. אִם יָכוֹל לַחֲזֹר וּלְבָעֵר וְלַחֲזֹר לְמִצְוָתוֹ יַחֲזֹר וְאִם לָאו יְבַטֵּל בְּלִבּוֹ. יָצָא לְהַצִּיל מִיַּד הַגַּיִס מִן הַנָּהָר מִן הַדְּלֵקָה וּמִן הַמַּפּלֶת יְבַטֵּל בְּלִבּוֹ וְדַיּוֹ. יָצָא לְצֹרֶךְ עַצְמוֹ וְנִזְכַּר שֶׁיֵּשׁ לוֹ חָמֵץ בְּתוֹךְ בֵּיתוֹ יַחֲזֹר מִיָּד. וְעַד כַּמָּה הוּא חוֹזֵר עַד כְּבֵיצָה. הָיָה פָּחוֹת מִכְּבֵיצָה מְבַטְּלוֹ בְּלִבּוֹ וְדַיּוֹ:","מִי שֶׁהִנִּיחַ עִסָּה מְגֻלְגֶּלֶת בְּתוֹךְ בֵּיתוֹ וְיָצָא וְנִזְכַּר אַחַר שֶׁיָּצָא וְהוּא יוֹשֵׁב לִפְנֵי רַבּוֹ וְהָיָה יָרֵא שֶׁמָּא תַּחֲמִיץ קֹדֶם שֶׁיָּבֹא הֲרֵי זֶה מְבַטְּלוֹ בְּלִבּוֹ קֹדֶם שֶׁתַּחֲמִיץ. אֲבָל אִם הֶחְמִיצָה אֵין הַבִּטּוּל מוֹעִיל כְּלוּם אֶלָּא כְּבָר עָבַר עַל (שמות יג ז) (דברים טז ד) \"לֹא יֵרָאֶה\" וְ (שמות יב יט) \"לֹא יִמָּצֵא\" וְחַיָּב לְבַעֵר מִיָּד כְּשֶׁיַּחֲזֹר לְבֵיתוֹ:","כֵּיצַד בִּעוּר חָמֵץ. שׂוֹרְפוֹ אוֹ פּוֹרֵר וְזוֹרֶה לָרוּחַ אוֹ זוֹרְקוֹ לַיָּם. וְאִם הָיָה הֶחָמֵץ קָשֶׁה וְאֵין הַיָּם מְחַתְּכוֹ בִּמְהֵרָה הֲרֵי זֶה מְפָרְרוֹ וְאַחַר כָּךְ זוֹרְקוֹ לַיָּם. חָמֵץ שֶׁנָּפְלָה עָלָיו מַפּלֶת וְנִמְצָא עָלָיו עָפָר שְׁלֹשָׁה טְפָחִים אוֹ יוֹתֵר הֲרֵי הוּא כִּמְבֹעָר וְצָרִיךְ לְבַטֵּל בְּלִבּוֹ אִם עֲדַיִן לֹא נִכְנְסָה שָׁעָה שִׁשִּׁית. נְתָנוֹ לְעַכּוּ\"ם קֹדֶם שָׁעָה שִׁשִּׁית אֵינוֹ צָרִיךְ לְבָעֵר. וְאִם שְׂרָפוֹ קֹדֶם שָׁעָה שִׁשִּׁית הֲרֵי זֶה מֻתָּר לֵהָנוֹת בַּפֶּחָמִין שֶׁלּוֹ בְּתוֹךְ הַפֶּסַח. אֲבָל אִם שְׂרָפוֹ מִשָּׁעָה שִׁשִּׁית וּלְמַעְלָה הוֹאִיל וְהוּא אָסוּר בַּהֲנָיָה הֲרֵי זֶה לֹא יַסִּיק בּוֹ תַּנּוּר וְכִירַיִם וְלֹא יֹאפֶה בּוֹ וְלֹא יְבַשֵּׁל. וְאִם בִּשֵּׁל אוֹ אָפָה אוֹתָהּ הַפַּת וְאוֹתוֹ הַתַּבְשִׁיל אָסוּר בַּהֲנָיָה. וְכֵן הַפֶּחָמִין שֶׁלּוֹ אֲסוּרִין בַּהֲנָיָה הוֹאִיל וְשׂוֹרְפוֹ אַחַר שֶׁנֶּאֱסַר בַּהֲנָיָה:"],"Mishneh Torah, Levirate Marriage and Release 6":["יֵשׁ אַחִין שֶׁרְאוּיִין לְיִבּוּם אוֹ לַחֲלִיצָה. וְיֵשׁ אַחִין שֶׁאֵינָן רְאוּיִין לֹא לְיִבּוּם וְלֹא לַחֲלִיצָה וְאֵין לָהֶן זִקָּה כְּלָל אֶלָּא יְבִמְתּוֹ מֻתֶּרֶת לְזָר. וְיֵשׁ אַחִין שֶׁרְאוּיִין לַחֲלִיצָה וְאֵינָן רְאוּיִין לְיִבּוּם. וְיֵשׁ אַחִין שֶׁהֵן רְאוּיִין לְיִבּוּם וְאֵינָן רְאוּיִין לַחֲלִיצָה:","וְאֵלּוּ הֵם שֶׁאֵין לָהֶן זִקָּה כְּלָל. סְרִיס חַמָּה וְאַנְדְּרוֹגִינוּס מִפְּנֵי שֶׁאֵינָן רְאוּיִין לֵילֵד וְלֹא הָיָה לָהֶן שְׁעַת הַכּשֶׁר:","וְאֵלּוּ מְיַבְּמִין וְלֹא חוֹלְצִין. הַחֵרֵשׁ וְהַשּׁוֹטֶה וְהַקָּטָן מִפְּנֵי שֶׁאֵין בָּהֶן דַּעַת לַחֲלֹץ. וּכְשֶׁיִּבֵּם הַחֵרֵשׁ אֵינוֹ מוֹצִיא לְעוֹלָם שֶׁבְּעִילָתוֹ עוֹשָׂה אוֹתָהּ אֵשֶׁת אִישׁ גְּמוּרָה וְאֵין גֵּרוּשָׁיו גֵּרוּשִׁין גְּמוּרִין. וּבֶן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד שֶׁיִּבֵּם אֵינוֹ יָכוֹל לְגָרֵשׁ עַד שֶׁיַּגְדִּיל כְּמוֹ שֶׁבֵּאַרְנוּ:","וְאֵלּוּ חוֹלְצִין וְלֹא מְיַבְּמִין. הַסְּפֵקוֹת כְּגוֹן שֶׁהָיְתָה סְפֵק עֶרְוָה עַל אָחִיו. וּפְצוּעַ דַּכָּא וּכְרוּת שָׁפְכָה וְכַיּוֹצֵא בָּהֶן מִמִּינֵי הַסֵּרוּס. וְהַזָּקֵן בְּיוֹתֵר שֶׁתָּשַׁשׁ כֹּחוֹ וְכָשַׁל. וְאִם בָּעַל סְרִיס אָדָם קָנָה שֶׁהֲרֵי הָיְתָה לוֹ שְׁעַת הַכּשֶׁר וּמוֹצִיא בְּגֵט מִפְּנֵי שֶׁהוּא אָסוּר לָבוֹא בַּקָּהָל. וְהַטֻּמְטוּם חוֹלֵץ וְלֹא מְיַבֵּם מִפְּנֵי שֶׁהוּא סָפֵק. וְאִם נִקְרַע וְנִמְצָא זָכָר רָצָה חוֹלֵץ רָצָה מְיַבֵּם. וּשְׁאָר הָאַחִין אוֹ חוֹלְצִין אוֹ מְיַבְּמִין:","יֵשׁ יְבָמוֹת שֶׁהֵן רְאוּיוֹת לַחֲלִיצָה אוֹ לְיִבּוּם. וְיֵשׁ יְבָמוֹת שֶׁאֵינָן רְאוּיוֹת לֹא לַחֲלִיצָה וְלֹא לְיִבּוּם וְאֵין עֲלֵיהֶן זִקָּה כְּלָל וּמֻתָּרוֹת לְהִנָּשֵׂא לְזָר. וְיֵשׁ יְבָמוֹת שֶׁהֵן רְאוּיוֹת לַחֲלִיצָה אֲבָל לֹא לְיִבּוּם. וְיֵשׁ יְבָמוֹת שֶׁהֵן רְאוּיוֹת לְיִבּוּם אֲבָל לֹא לַחֲלִיצָה:","וְאֵלּוּ שֶׁמִּתְיַבְּמוֹת וְלֹא חוֹלְצוֹת. הַחֵרֶשֶׁת וְהַשּׁוֹטָה וְהַקְּטַנָּה לְפִי שֶׁאֵין בָּהֶן דַּעַת לִקְרוֹת וּלְהָבִין. וְאִם רָצָה הַיָּבָם לְגָרֵשׁ הַחֵרֶשֶׁת בְּגֵט אַחַר שֶׁיִּבְעל אוֹתָהּ הֲרֵי זֶה מְגָרֵשׁ:","וְאֵלּוּ שֶׁחוֹלְצוֹת וְלֹא מִתְיַבְּמוֹת. אִסּוּרֵי לָאוִין וְהַשְּׁנִיּוֹת וְאִסּוּרֵי עֲשֵׂה כְּמוֹ שֶׁיִּתְבָּאֵר. וְכָל אִשָּׁה שֶׁהִיא סְפֵק מְגֹרֶשֶׁת חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת שֶׁמָּא יִפְגַּע בְּעֶרְוָה. שֶׁאֵשֶׁת אָחִיו שֶׁגֵּרְשָׁהּ אֲסוּרָה עָלָיו מִשּׁוּם עֶרְוָה. אֲבָל מִי שֶׁהִיא מְקֻדֶּשֶׁת לְאָחִיו בִּסְפֵק קִדּוּשִׁין הֲרֵי הִיא כִּשְׁאָר כָּל הַיְבָמוֹת וְחוֹלֶצֶת אוֹ מִתְיַבֶּמֶת שֶׁאֵין כָּאן דָּבָר לָחוּשׁ לוֹ. וְכֵן אֵשֶׁת הַחֵרֵשׁ וּזְקֵנָה וַעֲקָרָה הֲרֵי הֵן כִּשְׁאָר כָּל הַיְבָמוֹת. רָצָה חוֹלֵץ רָצָה מְיַבֵּם. שֶׁזְּקֵנָה וַעֲקָרָה הָיְתָה לָהֶן שְׁעַת הַכּשֶׁר:","וְאֵלּוּ הֵן שֶׁהֵן פְּטוּרוֹת מִן הַחֲלִיצָה וּמִן הַיִּבּוּם. אֵשֶׁת סְרִיס חַמָּה וְאַנְדְּרוֹגִינוּס וְאֵשֶׁת הַשּׁוֹטֶה וְאֵשֶׁת הַקָּטָן וְאַיְלוֹנִית וּמִי שֶׁהִיא עֶרְוָה. שֶׁנֶּאֱמַר (דברים כה ו) ״וְלֹא יִמָּחֶה שְׁמוֹ מִיִּשְׂרָאֵל״‎‎ פְּרָט לִסְרִיס חַמָּה וְאַנְדְּרוֹגִינוּס שֶׁשְּׁמָם מָחוּי הוֹאִיל וְאֵינָן רְאוּיִין לֵילֵד מִתְּחִלַּת בְּרִיָּתָן הֲרֵי הֵן כְּמִין בִּפְנֵי עַצְמוֹ. (דברים כה ו) ״וְהָיָה הַבְּכוֹר אֲשֶׁר תֵּלֵד״‎‎ פְּרָט לְאַיְלוֹנִית שֶׁאֵינָהּ רְאוּיָה לֵילֵד מִתְּחִלַּת בְּרִיָּתָהּ. (דברים כה ה) ״לֹא תִּהְיֶה אֵשֶׁת הַמֵּת״‎‎ פְּרָט לְאֵשֶׁת שׁוֹטֶה וְקָטָן מִפְּנֵי שֶׁאֵין לָהֶם אִישׁוּת כְּלָל. (דברים כה ה) ״וּלְקָחָהּ לוֹ לְאִשָּׁה״‎‎ פְּרָט לְעֶרְוָה שֶׁאֵין לוֹ בָּהּ לִקּוּחִין:","כֵּיצַד. יְבָמָה שֶׁהִיא עֶרְוָה עַל יְבָמָהּ כְּגוֹן שֶׁהָיְתָה אֲחוֹת אִשְׁתּוֹ אוֹ אִמָּהּ אוֹ בִּתָּהּ הֲרֵי זוֹ פְּטוּרָה מִן הַחֲלִיצָה וּמִן הַיִּבּוּם וְאֵין לוֹ עָלֶיהָ זִקָּה כְּלָל שֶׁנֶּאֱמַר (דברים כה ה) ״וּלְקָחָהּ לוֹ לְאִשָּׁה וְיִבְּמָהּ״‎‎. מִי שֶׁרְאוּיָה לְלִקּוּחִין וְקִדּוּשִׁין תּוֹפְסִין בָּהּ הִיא זְקוּקָה לְיָבָם:","הָיְתָה הַיְבָמָה אֲסוּרָה עַל יְבָמָהּ אִסּוּר לָאו אוֹ אִסּוּר עֲשֵׂה אוֹ שֶׁהָיְתָה שְׁנִיָּה הֲרֵי זוֹ חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת. וּמִפְּנֵי מָה צְרִיכָה חֲלִיצָה מִפְּנֵי שֶׁיֵּשׁ בָּהּ לִקּוּחִין הוֹאִיל וְקִדּוּשִׁין תּוֹפְסִין בָּהֶן הֲרֵי הֵן זְקוּקוֹת לְיָבָם. וּמִן הַדִּין הָיָה שֶׁיִּתְיַבְּמוּ שֶׁהַיִּבּוּם מִצְוַת עֲשֵׂה וְכָל מָקוֹם שֶׁאַתָּה מוֹצֵא עֲשֵׂה וְלֹא תַּעֲשֶׂה יָבֹא עֲשֵׂה וְיִדְחֶה אֶת לֹא תַּעֲשֶׂה. אֲבָל חֲכָמִים גָּזְרוּ שֶׁלֹּא יִתְיַבְּמוּ חַיָּבֵי לָאוִין וְלֹא שְׁנִיּוֹת גְּזֵרָה שֶׁמָּא יָבוֹא עָלֶיהָ פַּעַם שְׁנִיָּה וַהֲרֵי בִּיאָתָהּ אֲסוּרָה וְאֵין שָׁם מִצְוָה שֶׁאֵין מִצְוַת עֲשֵׂה אֶלָּא בִּיאָה רִאשׁוֹנָה בִּלְבַד. לְפִיכָךְ אִם עָבַר וּבָעַל יְבִמְתּוֹ הָאֲסוּרָה לוֹ מִשּׁוּם לָאו אוֹ מִשּׁוּם עֲשֵׂה וְאֵין צָרִיךְ לוֹמַר שְׁנִיָּה הֲרֵי זֶה קָנָה קִנְיָן גָּמוּר וּמוֹצִיאָהּ בְּגֵט וְהִיא וְכָל צָרוֹתֶיהָ מֻתָּרוֹת לְזָר שֶׁהֲרֵי נִפְטְרוּ:","וִיבָמָה שֶׁהִיא אַלְמָנָה מִן הַנִּשּׂוּאִין וּבָא עָלֶיהָ כֹּהֵן גָּדוֹל לֹא נִפְטְרָה צָרָתָהּ שֶׁאֵין עֲשֵׂה דּוֹחֶה אֶת לֹא תַּעֲשֶׂה וַעֲשֵׂה. וְהוֹאִיל וְלֹא קָנָה מִן הַתּוֹרָה קִנְיָן גָּמוּר לֹא הֻתְּרָה צָרָתָהּ לְזָר עַד שֶׁתַּחֲלֹץ:","הָיְתָה הַיְבָמָה עֶרְוָה עַל בַּעְלָהּ. כְּגוֹן שֶׁעָבַר אוֹ טָעָה וְלָקַח אֲחוֹתוֹ מֵאָבִיו וְנָפְלָה לִפְנֵי אָחִיו. אֵין זוֹ אִשְׁתּוֹ שֶׁאֵין קִדּוּשִׁין תּוֹפְסִין בָּהּ וְאֵינָהּ לֹא בַּת יִבּוּם וְלֹא בַּת חֲלִיצָה. וְאִם הָיְתָה לָהּ צָרָה חוֹלֶצֶת [אוֹ] מִתְיַבֶּמֶת. וְאִם הָיְתָה זוֹ שֶׁהִיא עֶרְוָה עַל הַבַּעַל מֻתֶּרֶת לַיָּבָם וְרָצָה הַיָּבָם לִשָּׂא אוֹתָהּ וּלְיַבֵּם צָרָתָהּ הָרְשׁוּת בְּיָדוֹ:","הָיְתָה הַיְבָמָה אֲסוּרָה עַל בַּעְלָהּ מִשּׁוּם לָאו אוֹ מִשּׁוּם עֲשֵׂה אוֹ שֶׁהָיְתָה שְׁנִיָּה לַבַּעַל וְלֹא הָיְתָה אֲסוּרָה עַל הַיָּבָם מִצַּד אֵלּוּ הַצְּדָדִים הֲרֵי זוֹ מֻתֶּרֶת לַיָּבָם. חוּץ מִמַּחֲזִיר גְּרוּשָׁתוֹ מִשֶּׁנִּשֵּׂאת וּמֵת שֶׁהִיא חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת. וְכֵן יְבָמָה שֶׁהִיא סְפֵק עֶרְוָה עַל הַיָּבָם אוֹ סְפֵק עֶרְוָה עַל בַּעְלָהּ הֲרֵי זוֹ חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת. לְפִיכָךְ מִי שֶׁקִּדֵּשׁ אִשָּׁה בִּסְפֵק קִדּוּשִׁין וְאַחַר כָּךְ מֵת אָחִיו שֶׁהָיָה נוֹשֵׂא אֲחוֹתָהּ וְנָפְלָה לוֹ לְיִבּוּם שֶׁהִיא סְפֵק אֲחוֹת אִשְׁתּוֹ הֲרֵי זוֹ חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת. וּמוֹצִיא אֶת אִשְׁתּוֹ בְּגֵט מִסָּפֵק וּשְׁתֵּיהֶן אֲסוּרוֹת עָלָיו. יְבִמְתּוֹ מִפְּנֵי שֶׁהִיא סְפֵק עֶרְוָה וַאֲרוּסָתוֹ מִפְּנֵי שֶׁהִיא סְפֵק קְרוֹבַת חֲלוּצָתוֹ שֶׁהִיא כִּשְׁנִיָּה כְּמוֹ שֶׁבֵּאַרְנוּ:","מִי שֶׁמֵּת אָחִיו וְהִנִּיחַ שְׁתֵּי נָשִׁים הָאַחַת אֲסוּרָה עָלָיו מִשּׁוּם עֶרְוָה וְהַשְּׁנִיָּה אֵינָהּ עֶרְוָה. כְּשֵׁם שֶׁהָעֶרְוָה פְּטוּרָה מִן הַחֲלִיצָה וּמִן הַיִּבּוּם כָּךְ צָרָתָהּ פְּטוּרָה וְלֹא נָפְלָה לוֹ זִקָּה כְּלָל עַל בַּיִת זֶה. שֶׁנֶּאֱמַר (דברים כה ט) ״אֲשֶׁר לֹא יִבְנֶה אֶת בֵּית אָחִיו״‎‎ בַּיִת שֶׁיֵּשׁ לוֹ לִקּוּחִין בְּאֵי זֶה מֵהֶן שֶׁיִּרְצֶה הוּא שֶׁיֵּשׁ לוֹ עָלָיו זִקָּה. וּבַיִת שֶׁמִּקְצָתוֹ אֵינוֹ יָכוֹל לִבְנוֹתוֹ שֶׁהֲרֵי אֵין לוֹ בָּהּ לִקּוּחִין אֵינוֹ בּוֹנֶה אֲפִלּוּ מִקְצָתוֹ שֶׁהוּא מֻתָּר. וְנִמְצֵאת צָרַת הָעֶרְוָה עֶרְוָה עָלָיו מִשּׁוּם אֵשֶׁת אָחִיו שֶׁהֲרֵי אֵין לוֹ עָלֶיהָ זִקָּה:","לְפִיכָךְ רְאוּבֵן שֶׁמֵּת וְהִנִּיחַ שְׁתֵּי נָשִׁים הָאַחַת עֶרְוָה עַל שִׁמְעוֹן וּשְׁתֵּיהֶן רְאוּיוֹת לְלֵוִי אֵין לְשִׁמְעוֹן זִקָּה עַל בַּיִת זֶה וַהֲרֵי שְׁתֵּיהֶן תַּחַת זִקַּת לֵוִי. יִבֵּם לֵוִי הָאַחַת מֵהֶן שֶׁהִיא צָרַת עֶרְוָה שֶׁל שִׁמְעוֹן וְהָיְתָה לוֹ אִשָּׁה אַחֶרֶת וּמֵת לֵוִי וְנָפְלוּ שְׁתֵּיהֶן לִפְנֵי שִׁמְעוֹן שְׁתֵּיהֶן פְּטוּרוֹת מִן הַחֲלִיצָה וּמִן הַיִּבּוּם מִשִּׁמְעוֹן. הָאַחַת מִפְּנֵי שֶׁהָיְתָה צָרַת עֶרְוָה וְהַשְּׁנִיָּה מִפְּנֵי שֶׁהִיא צָרָתָהּ. וְכֵן הַדִּין בְּצָרַת צָרָתָהּ עַד סוֹף הָעוֹלָם. שֶׁכָּל אִשָּׁה שֶׁאֵין לוֹ עָלֶיהָ זִקָּה בְּאִסּוּר אֵשֶׁת אָח עוֹמֶדֶת לְעוֹלָם:","וְכֵן אֵשֶׁת אָחִיו שֶׁלֹּא הָיָה בְּעוֹלָמוֹ הוֹאִיל וְאֵין לוֹ עָלֶיהָ זִקָּה שֶׁנֶּאֱמַר (דברים כה ה) ״כִּי יֵשְׁבוּ אַחִים יַחְדָּו״‎‎ עַד שֶׁיֵּשְׁבוּ שְׁנֵיהֶם בָּעוֹלָם הֲרֵי זוֹ עֶרְוָה עָלָיו לְעוֹלָם מִשּׁוּם אֵשֶׁת אָח וּפוֹטֶרֶת צָרָתָהּ:","כֵּיצַד. רְאוּבֵן שֶׁמֵּת וְהִנִּיחַ אִשָּׁה וְנָפְלָה לִפְנֵי שִׁמְעוֹן וְאַחַר שֶׁמֵּת רְאוּבֵן נוֹלַד לֵוִי. בֵּין שֶׁנּוֹלַד לֵוִי קֹדֶם שֶׁיִּבֵּם לָהּ שִׁמְעוֹן בֵּין שֶׁנּוֹלַד אַחַר שֶׁיִּבְּמָהּ. הֲרֵי אֵשֶׁת רְאוּבֵן עֶרְוָה עַל לֵוִי לְעוֹלָם. לְפִיכָךְ אִם מֵת שִׁמְעוֹן וְנָפְלָה זוֹ וְצָרָתָהּ לִפְנֵי לֵוִי שְׁתֵּיהֶן פְּטוּרוֹת מִן הַחֲלִיצָה וּמִן הַיִּבּוּם:","עָשָׂה שִׁמְעוֹן מַאֲמָר בִּיבִמְתּוֹ אֵשֶׁת רְאוּבֵן וּמֵת קֹדֶם שֶׁיִּכְנֹס אוֹתָהּ הֲרֵי לֵוִי חוֹלֵץ לְצָרָתָהּ וְלֹא מְיַבֵּם. שֶׁאֵין הַמַּאֲמָר קוֹנֶה בַּיְבָמָה קִנְיָן גָּמוּר כְּמוֹ שֶׁבֵּאַרְנוּ:","אִשָּׁה שֶׁזִּנְּתָה תַּחַת בַּעְלָהּ בְּרָצוֹן וּבְעֵדִים וּמֵת קֹדֶם שֶׁיְּגָרְשֶׁנָּה וְנָפְלָה לִפְנֵי יָבָם הֲרֵי הִיא פְּטוּרָה מִן הַחֲלִיצָה וּמִן הַיִּבּוּם. וְכֵן צָרָתָהּ כְּאִלּוּ הָיְתָה עֶרְוָה עַל הַיָּבָם מִפְּנֵי שֶׁטֻּמְאָה כְּתוּבָה בָּהּ כַּעֲרָיוֹת שֶׁנֶּאֱמַר (במדבר ה יג יד) ״וְהִיא נִטְמָאָה״‎‎. אֲבָל סוֹטָה שֶׁמֵּת בַּעְלָהּ קֹדֶם שֶׁיַּשְׁקֶנָּה מֵי הַמָּרִים אוֹ שֶׁאֵינָהּ בַּת שְׁתִיָּה אֶלָּא בַּת גֵּרוּשִׁין הֲרֵי זוֹ חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת. וְאִם הָיְתָה לָהּ צָרָה הֲרֵי צָרָתָהּ מֻתֶּרֶת וְחוֹלֶצֶת אוֹ מִתְיַבֶּמֶת:","וְכֵן שְׁתֵּי יְבָמוֹת הַבָּאוֹת מִבַּיִת אֶחָד שֶׁהָיְתָה הָאַחַת מֵהֶן שְׁנִיָּה עַל הַיָּבָם אוֹ מֵחַיָּבֵי לָאוִין אוֹ מֵחַיָּבֵי עֲשֵׂה אוֹ אַיְלוֹנִית הֲרֵי צָרָתָהּ מֻתֶּרֶת וְחוֹלֶצֶת אוֹ מִתְיַבֶּמֶת. אֲבָל הַחוֹלֵץ לִיבִמְתּוֹ וְהָלְכָה אֲחוֹת חֲלוּצָתוֹ אוֹ אִמָּהּ וְכַיּוֹצֵא בָּהֶן וְנִשֵּׂאת לְאָחִיו וְלוֹ אִשָּׁה אַחֶרֶת וָמֵת וְנָפְלוּ שְׁתֵּיהֶן לְפָנָיו. כְּשֵׁם שֶׁקְּרוֹבַת חֲלוּצָתוֹ אֲסוּרָה עָלָיו כָּךְ צָרָתָהּ אֲסוּרָה. וַהֲרֵי שְׁתֵּיהֶן כִּשְׁנִיּוֹת לוֹ וְחוֹלְצוֹת וְלֹא מִתְיַבְּמוֹת. וּמִפְּנֵי מָה אָסְרוּ צָרַת קְרוֹבַת חֲלוּצָתוֹ. מִפְּנֵי שֶׁמִּתְחַלֶּפֶת בְּצָרַת חֲלוּצָתוֹ:","שְׁתֵּי יְבָמוֹת הַבָּאוֹת מִבַּיִת אֶחָד שֶׁהָאַחַת מֵהֶן עֶרְוָה עַל הַיָּבָם וַהֲרֵי הָעֶרְוָה אַיְלוֹנִית. צָרָתָהּ מֻתֶּרֶת וְחוֹלֶצֶת אוֹ מִתְיַבֶּמֶת. הוֹאִיל וְהָאַיְלוֹנִית אֵינָהּ בַּת יִבּוּם וַחֲלִיצָה הֲרֵי זוֹ כְּמִי שֶׁאֵינָהּ. וְנָפְלָה זִקָּתוֹ עַל צָרָתָהּ בִּלְבַד. וְכֵן אִם גֵּרֵשׁ אָחִיו אֶת הָעֶרְוָה אוֹ מֵאֲנָה בּוֹ קֹדֶם שֶׁיָּמוּת. אוֹ שֶׁמֵּתָה בְּחַיֵּי בַּעְלָהּ וְאַחַר כָּךְ מֵת אָחִיו. הֲרֵי צָרָתָהּ מֻתֶּרֶת וְחוֹלֶצֶת אוֹ מִתְיַבֶּמֶת. וְאֵין אוֹמְרִין הוֹאִיל וְנַעֲשֵׂית צָרָה לְעֶרְוָה שָׁעָה אַחַת תֵּאָסֵר לְעוֹלָם. שֶׁאֵין הַצָּרָה אֲסוּרָה עַד שֶׁתִּהְיֶה צָרַת עֶרְוָה בִּשְׁעַת נְפִילָה לְיִבּוּם:","הָיְתָה זוֹ שֶׁהִיא עֶרְוָה עַל הַיָּבָם מְקֻדֶּשֶׁת לְאָחִיו שֶׁמֵּת בְּסָפֵק אוֹ מְגֹרֶשֶׁת מִמֶּנּוּ בְּסָפֵק. אוֹ שֶׁהָיְתָה קְטַנָּה הָרְאוּיָה לְמָאֵן וְלֹא מֵאֲנָה בְּאָחִיו בְּחַיָּיו. אַף עַל פִּי שֶׁמֵּאֲנָה בַּיָּבָם צָרָתָהּ חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת:","הָלְכָה צָרַת עֶרְוָה וְנִשֵּׂאת לְאַחֵר וְאַחַר כָּךְ נִמְצֵאת הָעֶרְוָה אַיְלוֹנִית. תֵּצֵא הַצָּרָה מִבַּעְלָהּ וּמִיבָמָהּ וּצְרִיכָה גֵּט מִבַּעְלָהּ וַחֲלִיצָה מִיבָמָהּ כְּדֵי לְהַתִּירָהּ לַשּׁוּק:","יִבֵּם הַיָּבָם הַצָּרָה מִפְּנֵי שֶׁדִּמּוּ שֶׁהָעֶרְוָה אַיְלוֹנִית וְנִמְצֵאת הָעֶרְוָה שֶׁאֵינָהּ אַיְלוֹנִית תֵּצֵא מִיבָמָהּ בְּגֵט וְהַוָּלָד מַמְזֵר:","שְׁלֹשָׁה אַחִין. שְׁנַיִם מֵהֶן נְשׂוּאִין שְׁתֵּי אֲחָיוֹת וְאֶחָד מֵהֶן נָשׂוּי נָכְרִית. מֵת הַנָּשׂוּי נָכְרִית וְאַחַר כָּךְ מֵת אֶחָד מִבַּעֲלֵי אֲחָיוֹת. הֲרֵי הַנָּכְרִית חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת מִפְּנֵי שֶׁהִיא צָרַת אֲחוֹת אִשְׁתּוֹ בְּזִקַּת אָחִיו שֶׁמֵּת אַחֲרוֹן. וְלֹא עוֹד אֶלָּא אֲפִלּוּ גֵּרֵשׁ אֶחָד מִבַּעֲלֵי אֲחָיוֹת אֶת אִשְׁתּוֹ אַחַר שֶׁמֵּת הַנָּשׂוּי נָכְרִית וּמֵת הַמְגָרֵשׁ הֲרֵי הַנָּכְרִית חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת הוֹאִיל וְנַעֲשֵׂית צָרַת אָחוֹת אִשְׁתּוֹ בְּזִקָּה שָׁעָה אַחַת. שֶׁאִם תִּתְיַבֵּם שֶׁמָּא יָבֹא לְיַבֵּם אוֹתָהּ. וַאֲפִלּוּ לֹא גֵּרֵשׁ זֶה שֶׁמֵּת אַחֲרוֹן אֶת אִשְׁתּוֹ:","וּמִפְּנֵי מָה לֹא גָּזְרוּ דָּבָר זֶה בַּנִּשּׂוּאִין שֶׁהֲרֵי צָרַת עֶרְוָה בַּנִּשּׂוּאִין אִם גֵּרֵשׁ אֶת הָעֶרְוָה וּמֵת צָרָתָהּ מֻתֶּרֶת לַיָּבָם כְּמוֹ שֶׁבֵּאַרְנוּ. מִפְּנֵי שֶׁאִסּוּר צָרַת הָעֶרְוָה בַּנִּשּׂוּאִין יָדוּעַ לַכּל וְאֵינָן בָּאִין לְהַתִּיר הַצָּרָה אִם לֹא גֵּרֵשׁ הָעֶרְוָה. וְאִסּוּר צָרַת עֶרְוָה בְּזִיקָה אֵינוֹ יָדוּעַ לַכּל וּבָאִין לְהַתִּיר הַצָּרָה וַאֲפִלּוּ לֹא נִתְגָּרְשָׁה הָעֶרְוָה:","שְׁלֹשָׁה אַחִין נְשׂוּאִין שָׁלֹשׁ נָשִׁים נָכְרִיּוֹת. מֵת אֶחָד מֵהֶן וְעָשָׂה הַשֵּׁנִי מַאֲמָר בִּיבִמְתּוֹ וּמֵת קֹדֶם שֶׁיִּכְנֹס וְנָפְלוּ שְׁתֵּיהֶן לִפְנֵי הַיָּבָם הֲרֵי אֵלּוּ חוֹלְצוֹת וְלֹא מִתְיַבְּמוֹת. מִפְּנֵי שֶׁבַּעֲלַת הַמַּאֲמָר עָלֶיהָ זִקַּת שְׁנֵי יְבָמִין. וְנִמְצֵאת כְּאִלּוּ הִיא אֵשֶׁת שְׁנֵי מֵתִים. וְדָרְשׁוּ חֲכָמִים וְאָמְרוּ (דברים כה ה) ״אֵשֶׁת הַמֵּת״‎‎ וְלֹא אֵשֶׁת שְׁנֵי מֵתִים. לְפִיכָךְ כָּל אִשָּׁה שֶׁעָלֶיהָ זִקַּת שְׁנֵי יְבָמִין חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת וְכֵן צָרָתָהּ. וְאִסּוּרָן מִדִּבְרֵי סוֹפְרִים:","וּמִפְּנֵי מָה לֹא יַחֲלֹץ לְבַעֲלַת הַמַּאֲמָר שֶׁעָלֶיהָ זִקַּת שְׁנֵי יְבָמִין וִייַבֵּם צָרָתָהּ. גְּזֵרָה שֶׁלֹּא יֹאמְרוּ שְׁתֵּי יְבָמוֹת הַבָּאוֹת מִבַּיִת אֶחָד אַחַת חוֹלֶצֶת וְאַחַת מִתְיַבֶּמֶת. וּלְפִיכָךְ אָסְרוּ אַף צָרָתָהּ:","עָשָׂה מַאֲמָר בִּיבִמְתּוֹ וְנָתַן גֵּט לְמַאֲמָרוֹ וּמֵת חָזְרָה לְהֶתֵּרָהּ. שֶׁהַמַּאֲמָר שֶׁאֲסָרָהּ הֲרֵי בִּטְּלוֹ. וְרָצָה חוֹלֵץ רָצָה מְיַבֵּם:","בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד שֶׁבָּא עַל יְבִמְתּוֹ וּמֵת כְּשֶׁהוּא קָטָן וְנָפְלָה פַּעַם שְׁנִיָּה לִפְנֵי אָחִיו הַגָּדוֹל הֲרֵי זוֹ חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת. שֶׁבִּיאַת בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד כְּמַאֲמָר מִן הַגָּדוֹל כְּמוֹ שֶׁבֵּאַרְנוּ וְנִמְצָא עָלֶיהָ זִקַּת שְׁנֵי יְבָמִין:","מִי שֶׁחֶצְיָהּ שִׁפְחָה וְחֶצְיָהּ בַּת חוֹרִין שֶׁנִּתְקַדְּשָׁה לִרְאוּבֵן וְנִשְׁתַּחְרְרָה וְחָזְרָה וְנִתְקַדְּשָׁה לְשִׁמְעוֹן וּמֵתוּ שְׁנֵיהֶם מִתְיַבֶּמֶת לְלֵוִי וְאֵינָהּ אֵשֶׁת שְׁנֵי מֵתִים. אִם קִדּוּשֵׁי רְאוּבֵן קִדּוּשִׁין אֵין קִדּוּשֵׁי שִׁמְעוֹן כְּלוּם. וְאִם קִדּוּשֵׁי שִׁמְעוֹן קִדּוּשִׁין אֵין קִדּוּשֵׁי רְאוּבֵן כְּלוּם:"],"Mishneh Torah, Marriage 18":["אַלְמָנָּה נִזּוֹנֶת מִנִּכְסֵי יוֹרְשִׁין כָּל זְמַן אַלְמְנוּתָהּ עַד שֶׁתִּטּל כְּתֻבָּתָהּ. וּמִשֶּׁתִּתְבַּע כְּתֻבָּתָהּ בְּבֵית דִּין אֵין לָהּ מְזוֹנוֹת. וְכֵן אִם מָכְרָה כְּתֻבָּתָהּ כֻּלָּהּ אוֹ מִשְׁכְּנָה כְּתֻבָּתָהּ אוֹ עָשְׂתָה כְּתֻבָּתָהּ אַפּוֹתִיקִי לְאַחֵר. וְהוּא שֶׁתֹּאמַר לוֹ פֹּה תִּגְבֶּה חוֹבְךָ. בֵּין שֶׁעָשְׂתָה דְּבָרִים אֵלּוּ בְּבֵית דִּין מֻמְחִין בֵּין שֶׁלֹּא בְּבֵית דִּין בֵּין שֶׁעָשְׂתָה בְּחַיֵּי בַּעְלָהּ בֵּין שֶׁעָשְׂתָה לְאַחַר מִיתַת בַּעְלָהּ אֵין לָהּ מְזוֹנוֹת מִן הַיּוֹרְשִׁים. אֲבָל אִם מָכְרָה מִקְצָתָהּ יֵשׁ לָהּ מְזוֹנוֹת. וּמִשֶּׁתִּתְאָרֵס הָאַלְמָנָה אִבְּדָה מְזוֹנוֹתֶיהָ:","כְּשֵׁם שֶׁנִּזֹּנֶת אַחַר מוֹתוֹ מִנְּכָסָיו כָּךְ נוֹתְנִין לָהּ כְּסוּת וּכְלֵי תַּשְׁמִישׁ וּמָדוֹר (אוֹ יוֹשֶׁבֶת בְּמָדוֹר) שֶׁהָיְתָה בּוֹ בְּחַיֵּי בַּעְלָהּ וּמִשְׁתַּמֶּשֶׁת בְּכָרִים וּכְסָתוֹת בַּעֲבָדִים וּבִשְׁפָחוֹת שֶׁנִּשְׁתַּמְּשָׁה בָּהֶן בְּחַיֵּי בַּעְלָהּ. נָפַל הַמָּדוֹר אֵין הַיּוֹרְשִׁין חַיָּבִין לִבְנוֹתוֹ. וְאִם אָמְרָה הָנִיחוּ לִי וַאֲנִי אֶבְנֶנּוּ מִשֶּׁלִּי אֵין שׁוֹמְעִין לָהּ. וְכֵן לֹא תְּחַזֵּק בִּדְקוֹ וְלֹא תִּטְחֶה אוֹתוֹ אֶלָּא תֵּשֵׁב בּוֹ כְּמָה שֶׁהוּא אוֹ תֵּצֵא. וְיֹורְשִׁין שֶׁמָּכְרוּ מְדוֹר אַלְמָנָה לֹא עָשׂוּ וְלֹא כְּלוּם:","נָפַל הַבַּיִת אוֹ שֶׁלֹּא הָיָה לְבַעְלָהּ בַּיִת אֶלָּא בְּשָׂכָר נוֹתְנִין לָהּ מָדוֹר לְפִי כְּבוֹדָהּ. וְכֵן מְזוֹנוֹתֶיהָ וּכְסוּתָהּ לְפִי כְּבוֹדָהּ. וְאִם הָיָה כְּבוֹד הַבַּעַל גָּדוֹל מִכְּבוֹדָהּ נוֹתְנִין לָהּ לְפִי כְּבוֹדוֹ מִפְּנֵי שֶׁעוֹלָה עִמּוֹ וְאֵינָהּ יוֹרֶדֶת אֲפִלּוּ לְאַחַר מִיתָה:","בִּרְכַּת הַבַּיִת מְרֻבָּה כֵּיצַד. חֲמִשָּׁה שֶׁהָיָה מְזוֹנוֹת כָּל אֶחָד מֵהֶן קַב בְּשֶׁיֹּאכַל לְבַדּוֹ אִם הָיוּ חֲמִשְּׁתָּן בְּבַיִת אֶחָד וְאוֹכְלִין בְּעֵרוּב מַסְפִּיק לָהֶן אַרְבַּע קַבִּין. וְהוּא הַדִּין לִשְׁאָר צָרְכֵי הַבַּיִת. לְפִיכָךְ אַלְמָנָה שֶׁאָמְרָה אֵינֶנִּי זָזָה מִבֵּית אָבִי פִּסְקוּ לִי מְזוֹנוֹת וּתְנוּ לִי שָׁם. יְכוֹלִין הַיּוֹרְשִׁין לוֹמַר לָהּ אִם אַתְּ אֶצְלֵנוּ יֵשׁ לָךְ מְזוֹנוֹת וְאִם לָאו אֵין אָנוּ נוֹתְנִים לָךְ אֶלָּא כְּפִי בִּרְכַּת הַבַּיִת. וְאִם הָיְתָה טוֹעֶנֶת מִפְּנֵי שֶׁהִיא יַלְדָּה וְהֵם יְלָדִים נוֹתְנִין לָהּ מְזוֹנוֹת הַמַּסְפִּיקִין לָהּ לְבַדָּהּ וְהִיא בְּבֵית אָבִיהָ. וּמוֹתַר מְזוֹנוֹת הָאַלְמָנָה וּמוֹתַר הַכְּסוּת לַיּוֹרְשִׁין:","אַלְמָנָה שֶׁחָלְתָה אִם צְרִיכָה לִרְפוּאָה שֶׁאֵין לָהּ קִצְבָה הֲרֵי זוֹ כִּמְזוֹנוֹת וְיוֹרְשִׁין חַיָּבִין בָּהּ. וְאִם הִיא צְרִיכָה רְפוּאָה שֶׁיֵּשׁ לָהּ קִצְבָה הֲרֵי זוֹ מִתְרַפְּאָה מִכְּתֻבָּתָהּ. נִשְׁבֵּית אֵין הַיּוֹרְשִׁין חַיָּבִין לִפְדּוֹתָהּ אֲפִלּוּ הָיְתָה יְבָמָה וַאֲפִלּוּ נִשְׁבֵּית בְּחַיֵּי בַּעְלָהּ וָמֵת וְהִיא בַּשִּׁבְיָהּ אֵין חַיָּבִין לִפְדּוֹתָהּ מִנְּכָסָיו אֶלָּא נִפְדֵּית מִשֶּׁל עַצְמָהּ אוֹ תִּטּל כְּתֻבָּתָהּ וְתִפְדֶּה עַצְמָהּ:","מֵתָה הָאַלְמָנָה יוֹרְשֵׁי הַבַּעַל חַיָּבִין בִּקְבוּרָתָהּ. וְאִם נִשְׁבְּעָה שְׁבוּעַת אַלְמָנָה וְאַחַר כָּךְ מֵתָה יוֹרְשֶׁיהָ יוֹרְשִׁין כְּתֻבָּתָהּ וְהֵן חַיָּבִין בִּקְבוּרָתָהּ אֲבָל לֹא יוֹרְשֵׁי הַבַּעַל. מַעֲשֵׂה יְדֵי הָאַלְמָנָה לַיּוֹרְשִׁין. וְיוֹרֵשׁ שֶׁאָמַר לָאַלְמָנָה טְלִי מַעֲשֵׂה יָדַיִךְ בִּמְזוֹנוֹתַיִךְ אֵין שׁוֹמְעִין לוֹ. אֲבָל הִיא שֶׁרָצְתָה בָּזֶה שׁוֹמְעִין לָהּ:","וְכָל מְלָאכוֹת שֶׁהָאִשָּׁה עוֹשָׂה לְבַעְלָהּ אַלְמָנָה עוֹשָׂה לִיתוֹמִים חוּץ מִמְּזִיגַת הַכּוֹס וְהַצָּעַת הַמִּטָּה וְהַרְחָצַת פָּנָיו יָדָיו וְרַגְלָיו:","מְצִיאַת הָאַלְמָנָה וּפֵרוֹת נְכָסִים שֶׁהִכְנִיסָה לַבַּעַל לְעַצְמָהּ וְאֵין לַיּוֹרֵשׁ בָּהֶם כְּלוּם:","וְהַנְּכָסִים עַצְמָם שֶׁהֵם נְדֻנְיָתָהּ נוֹטֶלֶת אוֹתָן בְּלֹא שְׁבוּעָה וְאֵין לַיּוֹרְשִׁים בָּהֶם דִּין לְעוֹלָם אֶלָּא אִם כֵּן הוֹתִירוּ בְּחַיֵּי הַבַּעַל וְהָיוּ נִכְסֵי צֹאן בַּרְזֶל שֶׁהַמּוֹתָר לַבַּעַל. וְאִם מֵתָה הָאַלְמָנָה בְּלֹא שְׁבוּעָה יוֹרְשֶׁיהָ יוֹרְשִׁים נְדֻנְיָתָהּ אַף עַל פִּי שֶׁהוּא נִכְסֵי צֹאן בַּרְזֶל. וְאִם הָיָה בָּהֶן מוֹתָר הַמּוֹתָר לְיוֹרְשֵׁי הַבַּעַל:","אַלְמָנָה שֶׁתָּפְסָה מִטַּלְטְלִין כְּדֵי שֶׁתִּזּוֹן מֵהֶן בֵּין שֶׁתָּפְסָה מֵחַיִּים בֵּין שֶׁתָּפְסָה אַחַר מוֹתוֹ אֲפִלּוּ תָּפְסָה כִּכַּר זָהָב אֵין מוֹצִיאִין מִיָּדָהּ אֶלָּא כּוֹתְבִין עָלֶיהָ בֵּית דִּין מַה שֶּׁתָּפְסָה וּפוֹסְקִין לָהּ מְזוֹנוֹת וּמְחַשְּׁבִין עִמָּהּ וְהִיא נִזּוֹנֶת מִמַּה שֶּׁבְּיָדָהּ עַד שֶׁתָּמוּת אוֹ עַד שֶׁלֹּא יִהְיוּ לָהּ מְזוֹנוֹת. וְיִקְחוּ הַיּוֹרְשִׁין אֶת הַשְּׁאָר:","וְכֵן אִם תָּפְסָה מִטַּלְטְלִין בִּכְתֻבָּתָהּ בְּחַיֵּי בַּעְלָהּ וָמֵת גּוֹבָה מֵהֶן. אֲבָל אִם תָּפְסָה אַחַר מוֹתוֹ לִכְתֻבָּתָהּ אֵינָהּ גּוֹבָה מֵהֶן אַף עַל גַּב שֶׁתִּקְּנוּ הַגְּאוֹנִים שֶׁתִּגְבֶּה הַכְּתֻבָּה וּתְנָאֵי הַכְּתֻבָּה מִן הַמִּטַּלְטְלִין. לְפִיכָךְ תִּזּוֹן הָאַלְמָנָה מִן הַמִּטַּלְטְלִין אַף עַל פִּי שֶׁלֹּא תָּפְסָה:","וְאִם הִנִּיחַ בַּעְלָהּ מִטַּלְטְלִין וְלֹא תָּפְסָה אוֹתָן הַיּוֹרְשִׁים נוֹטְלִין אוֹתָן וְהֵן מַעֲלִין לָהּ מְזוֹנוֹת וְאֵינָהּ יְכוֹלָה לְעַכֵּב עֲלֵיהֶן וְלוֹמַר יִהְיוּ הַמִּטַּלְטְלִין מֻנָּחִין בְּבֵית דִּין עַד שֶׁאִזּוֹן מֵהֶן שֶׁמָּא יֹאבְדוּ וְלֹא יִהְיוּ לִי מְזוֹנוֹת. וַאֲפִלּוּ הִתְנְתָה עָלָיו בְּפֵרוּשׁ שֶׁתִּזּוֹן מִן הַמִּטַּלְטְלִין אֵינָהּ מְעַכֶּבֶת. וְכָזֶה דָּנִין תָּמִיד בְּכָל בָּתֵּי דִּינִין:","אֲבָל אִם הִנִּיחַ קַרְקַע יְכוֹלָה הִיא לְעַכֵּב עֲלֵיהֶן שֶׁלֹּא יִמְכְּרוּ וְאִם מָכְרוּ אֵינָהּ מוֹצִיאָה מִיַּד הַלָּקוֹחוֹת שֶׁאֵין הָאִשָּׁה וְהַבָּנוֹת נִזּוֹנוֹת אֶלָּא מִנְּכָסִים בְּנֵי חוֹרִין:","הִנִּיחַ נָשִׁים רַבּוֹת אַף עַל פִּי שֶׁנְּשָׂאָן זוֹ אַחַר זוֹ נִזּוֹנוֹת בְּשָׁוֶה (כְּמוֹ) שֶׁאֵין דִּין קְדִימָה בְּמִטַּלְטְלִין:","אַלְמָנָה שֶׁנָּפְלָה לִפְנֵי יָבָם בִּשְׁלֹשָׁה חֳדָשִׁים הָרִאשׁוֹנִים נִזּוֹנֶת מִשֶּׁל בַּעַל. וְאִם הֻכַּר הָעֻבָּר וְכֵן אִם הֱנִיחָהּ מְעֻבֶּרֶת נִזּוֹנֶת וְהוֹלֶכֶת עַד שֶׁתֵּלֵד. יָלְדָה בֵּן שֶׁל קַיָּמָא נִזּוֹנֶת וְהוֹלֶכֶת כָּל יְמֵי אַלְמְנוּתָהּ כִּשְׁאָר כָּל הַנָּשִׁים. לֹא נִמְצֵאת מְעֻבֶּרֶת אַחַר שְׁלֹשָׁה חֳדָשִׁים אוֹ שֶׁהִפִּילָה אֵינָהּ נִזּוֹנֶת לֹא מִשֶּׁל בַּעַל וְלֹא מִשֶּׁל יָבָם אֶלָּא תּוֹבַעַת יְבָמָהּ לִכְנֹס אוֹ לַחֲלֹץ:","תָּבְעָה יְבָמָהּ לִכְנֹס אוֹ לַחֲלֹץ וְעָמַד בְּבֵית דִּין וּבָרַח אוֹ שֶׁחָלָה אוֹ שֶׁהָיָה הַיָּבָם בִּמְדִינַת הַיָּם הֲרֵי זוֹ נִזּוֹנֶת מִשֶּׁל יָבָם בְּלֹא שְׁבוּעָה כְּלָל:","נָפְלָה לִפְנֵי יָבָם קָטָן אֵין לָהּ מְזוֹנוֹת עַד שֶׁיִּגְדַּל וְיִהְיֶה כִּשְׁאָר הַיָּבָמִין:","מִי שֶׁיִּחֵד קַרְקַע לְאִשְׁתּוֹ בִּמְזוֹנוֹתֶיהָ בִּשְׁעַת מִיתָה וְאָמַר יִהְיֶה מָקוֹם פְּלוֹנִי לִמְזוֹנוֹת הֲרֵי רִבָּה לָהּ מְזוֹנוֹת. וְאִם הָיָה שְׂכָרוֹ פָּחוֹת מִמְּזוֹנוֹת הָרְאוּיוֹת לָהּ נוֹטֶלֶת הַשְּׁאָר מִשְּׁאָר נְכָסִים. וְאִם הָיָה שְׂכָרוֹ יוֹתֵר מִן הָרָאוּי לָהּ נוֹטֶלֶת הַכּל. אֲבָל אִם אָמַר לָהּ יִהְיֶה בְּמָקוֹם פְּלוֹנִי בִּמְזוֹנוֹתֶיהָ וְשָׁתְקָה אֵין לָהּ אֶלָּא פֵּרוֹת אוֹתוֹ מָקוֹם בִּלְבַד שֶׁהֲרֵי קָצַץ לָהּ מְזוֹנוֹת:","אַלְמָנָה שֶׁבָּאָה לְבֵית דִּין לִתְבֹּעַ מְזוֹנוֹת יֵשׁ מִי שֶׁהוֹרָה שֶׁפּוֹסְקִין לָהּ מְזוֹנוֹת וְאֵין מַשְׁבִּיעִין אוֹתָהּ. וְאֵין רָאוּי לִסְמֹךְ עַל הוֹרָאָה זוֹ מִפְּנֵי שֶׁנִּתְחַלֵּף לוֹ הַדָּבָר בְּאִשָּׁה שֶׁהָלַךְ בַּעְלָהּ לִמְדִינַת הַיָּם. וְרַבּוֹתַי הוֹרוּ שֶׁאֵין לָהּ מְזוֹנוֹת מִבֵּית דִּין עַד שֶׁתִּשָּׁבַע שֶׁהֲרֵי זוֹ בָּאָה לְהִפָּרַע מִנִּכְסֵי יְתוֹמִים וְכָל הַנִּפְרָע מִנִּכְסֵי יְתוֹמִים לֹא יִפָּרַע אֶלָּא בִּשְׁבוּעָה. וְלָזֶה דַּעְתִּי נוֹטָה וְכֵן רָאוּי לָדוּן:","אַלְמָנָה שֶׁבָּאָה לְבֵית דִּין לִתְבֹּעַ מְזוֹנוֹת מַשְׁבִּיעִין אוֹתָהּ בַּתְּחִלָּה וּמוֹכְרִין בְּלֹא הַכְרָזָה וְנוֹתְנִין לָהּ מְזוֹנוֹת. וְכֵן יֵשׁ לָהּ לִמְכֹּר לִמְזוֹנוֹת שֶׁלֹּא בְּבֵית דִּין מֻמְחִין אֶלָּא בִּשְׁלֹשָׁה אֲנָשִׁים נֶאֱמָנִים בְּלֹא הַכְרָזָה. וְכֵן אִם מָכְרָה לִמְזוֹנוֹת בֵּינָהּ לְבֵין עַצְמָהּ שָׁוֶה בְּשָׁוֶה מִכְרָהּ קַיָּם וּכְשֶׁיָּבֹאוּ הַיֹּרְשִׁין לְהַשְׁבִּיעַ אוֹתָהּ נִשְׁבַּעַת:","וְכַמָּה מוֹכְרִין לִמְזוֹנוֹת כְּדֵי לָזוּן מֵהֶם שִׁשָּׁה חֳדָשִׁים לֹא יוֹתֵר עַל זֶה. וּמוֹכְרִין עַל מְנָת שֶׁיִּהְיֶה הַלּוֹקֵחַ נוֹתֵן לָהּ מְזוֹן שְׁלֹשִׁים יוֹם וְחוֹזֶרֶת וּמוֹכֶרֶת פַּעַם שְׁנִיָּה לְשִׁשָּׁה חֳדָשִׁים. וְכֵן מוֹכֶרֶת וְהוֹלֶכֶת לְעוֹלָם עַד שֶׁיִּשָּׁאֵר מִן הַנְּכָסִים כְּדֵי כְּתֻבָּתָהּ גּוֹבָה כְּתֻבָּתָהּ מִן הַשְּׁאָר וְהוֹלֶכֶת לָהּ:","אַלְמָנָה שֶׁפָּסְקוּ לָהּ בֵּית דִּין מְזוֹנוֹת אֵין מְחַשְּׁבִין עִמָּהּ עַל מַעֲשֵׂה יָדֶיהָ עַד שֶׁיָּבוֹאוּ הַיּוֹרְשִׁים וְיִתְבְּעוּהָ. אִם מָצְאוּ לָהּ מַעֲשֵׂה יָדֶיהָ נוֹטְלִין אוֹתוֹ וְאִם לָאו הוֹלְכִין לְדַרְכָּם. וַאֲנִי אוֹמֵר שֶׁאִם הָיוּ הַיּוֹרְשִׁים קְטַנִּים בֵּית דִּין מְחַשְּׁבִין עִמָּהּ וּפוֹסְקִין מַעֲשֵׂה יָדֶיהָ כְּדֶרֶךְ שֶׁפּוֹסְקִין לָהּ מְזוֹנוֹת:","אַלְמָנָה שֶׁאֵין שְׁטַר כְּתֻבָּה יוֹצֵא מִתַּחַת יָדָהּ אֵין לָהּ מְזוֹנוֹת שֶׁמָּא מָחֲלָה כְּתֻבָּתָהּ אוֹ מָכְרָה אוֹ מִשְׁכְּנָה אוֹתָהּ. אַף עַל פִּי שֶׁלֹּא טָעַן יוֹרֵשׁ טוֹעֲנִין אָנוּ לוֹ וְאוֹמְרִים לָהּ הָבִיאִי כְּתֻבָּתֵךְ וְהִשָּׁבְעִי וּטְלִי מְזוֹנוֹתֶיךָ אֶלָּא אִם אֵין דַּרְכָּם לִכְתֹּב כְּתֻבָּה:","הָאִשָּׁה שֶׁהָלְכָה הִיא וּבַעְלָהּ לִמְדִינַת הַיָּם וּבָאָה וְאָמְרָה מֵת בַּעְלִי רָצְתָה נִזּוֹנֶת כְּדִין כָּל הָאַלְמָנוֹת רָצְתָה נוֹטֶלֶת כְּתֻבָּה. אָמְרָה גֵּרְשַׁנִי בַּעְלִי אֵינָהּ נֶאֱמֶנֶת וְנִזּוֹנֶת מִנְּכָסָיו עַד כְּדֵי כְּתֻבָּתָהּ מִכָּל פָּנִים. שֶׁאִם עֲדַיִן הִיא אִשְׁתּוֹ יֵשׁ לָהּ מְזוֹנוֹת. וְאִם גֵּרְשָׁהּ כְּמוֹ שֶׁאָמְרָה יֵשׁ לָהּ כְּתֻבָּה שֶׁהֲרֵי כְּתֻבָּתָהּ בְּיָדָהּ. לְפִיכָךְ נוֹטֶלֶת מְזוֹנוֹת עַד כְּדֵי כְּתֻבָּתָהּ וְהוֹלֶכֶת לָהּ:","הָאִשָּׁה שֶׁהָיָה לָהּ סְפֵק גֵּרוּשִׁין וּמֵת בַּעְלָהּ אֵינָהּ נִזּוֹנֶת מִנְּכָסָיו שֶׁאֵין מוֹצִיאִין מִיַּד הַיּוֹרֵשׁ מִסָּפֵק. אֲבָל בְּחַיֵּי בַּעְלָהּ יֵשׁ לָהּ מְזוֹנוֹת עַד שֶׁתִּתְגָּרֵשׁ גֵּרוּשִׁין גְּמוּרִין:","אַלְמָנָה עֲנִיָּה שֶׁשָּׁהֲתָה שְׁתֵּי שָׁנִים וְלֹא תָּבְעָה מְזוֹנוֹת אוֹ עֲשִׁירָה שֶׁשָּׁהֲתָה שָׁלֹשׁ שָׁנִים וְלֹא תָּבְעָה וִתְּרָה וְאֵין לָהּ מְזוֹנוֹת בַּשָּׁנִים שֶׁעָבְרוּ אֶלָּא מִשָּׁעָה שֶׁתָּבְעָה. וְאִם שָׁהֲתָה פָּחוֹת מִזֶּה אֲפִלּוּ בְּיוֹם אֶחָד לֹא וִתְּרָה אֶלָּא תּוֹבַעַת וְנוֹטֶלֶת מְזוֹן הַשָּׁנִים שֶׁעָבְרוּ:","אַלְמָנָה שֶׁתָּבְעָה מְזוֹנוֹת מִן הַיּוֹרְשִׁים הֵם אוֹמְרִים נָתַנְנוּ וְהִיא אוֹמֶרֶת לֹא נָטַלְתִּי כָּל זְמַן שֶׁלֹּא נִשֵּׂאת עַל הַיְתוֹמִים לְהָבִיא רְאָיָה אוֹ תִּשָּׁבַע שְׁבוּעַת הֶסֵּת וְתִטּל. מִשֶּׁנִּשֵּׂאת עָלֶיהָ לְהָבִיא רְאָיָה אוֹ יִשָּׁבְעוּ הַיּוֹרְשִׁים שְׁבוּעַת הֶסֵּת שֶׁנָּתְנוּ לָהּ:","דִּין תּוֹסֶפֶת כְּתֻבָּה כְּדִין הָעִקָּר. לְפִיכָךְ אַלְמָנָה שֶׁתָּבְעָה אוֹ מָכְרָה אוֹ מָחֲלָה אוֹ מִשְׁכְּנָה תּוֹסֶפֶת כְּתֻבָּתָהּ עִם הָעִקָּר אֵין לָהּ מְזוֹנוֹת. וְאִם תָּבְעָה מִקְצָת וְהִנִּיחָה מִקְצָת הֲרֵי זוֹ כְּמִי שֶׁתָּבְעָה מִקְצָת הָעִקָּר וְהִנִּיחָה מִקְצָתוֹ. וְכָל הַמּוֹכֶרֶת אוֹ הַמּוֹחֶלֶת סְתָם מָכְרָה וּמָחֲלָה הַתּוֹסֶפֶת עִם הָעִקָּר שֶׁשְּׁנֵיהֶם כְּתֻבָּה שְׁמָם בְּכָל מָקוֹם:"],"Mishneh Torah, Marriage 6":["הַמְקַדֵשׁ עַל תְּנַאי אִם נִתְקַיֵּם הַתְּנַאי מְקֻדֶּשֶׁת וְאִם לָאו אֵינָהּ מְקֻדֶּשֶׁת בֵּין שֶׁיִּהְיֶה הַתְּנַאי מִן הָאִישׁ בֵּין שֶׁיִּהְיֶה מִן הָאִשָּׁה. וְכָל תְּנַאי שֶׁבָּעוֹלָם בֵּין בְּקִדּוּשִׁין בֵּין בְּגֵּרוּשִׁין בֵּין בְּמִקָּח בֵּין בְּמִמְכָּר בֵּין בִּשְׁאָר דִּינֵי מָמוֹן צָרִיךְ לִהְיוֹת בִּתְנָאֵי אַרְבָּעָה דְּבָרִים:","וְאֵלּוּ הֵן הַד' דְּבָרִים שֶׁל כָּל תְּנַאי. שֶׁיִּהְיֶה כָּפוּל. וְשֶׁיִּהְיֶה הֵן שֶׁלּוֹ קוֹדֵם לַלָּאו. וְשֶׁיִּהְיֶה הַתְּנַאי קוֹדֵם לַמַּעֲשֶׂה. וְשֶׁיִּהְיֶה הַתְּנַאי דָּבָר שֶׁאֶפְשָׁר לְקַיְּמוֹ. וְאִם חָסֵר הַתְּנַאי אֶחָד מֵהֶן הֲרֵי הַתְּנַאי בָּטֵל וּכְאִלּוּ אֵין שָׁם תְּנַאי כְּלָל אֶלָּא תִּהְיֶה זוֹ מְקֻדֶּשֶׁת אוֹ מְגֹרֶשֶׁת מִיָּד וְיִתְקַיֵּם הַמִּקָּח אוֹ הַמַּתָּנָה מִיָּד וּכְאִלּוּ לֹא הִתְנָה כְּלָל הוֹאִיל וְחָסֵר הַתְּנַאי אֶחָד מִן הָאַרְבָּעָה:","כֵּיצַד. הָאוֹמֵר לְאִשָּׁה אִם תִּתְּנִי לִי מָאתַיִם זוּז הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי בְּדִינָר זֶה וְאִם לֹא תִּתְּנִי לִי לֹא תִּהְיִי מְקֻדֶּשֶׁת וְאַחַר שֶׁהִתְנָה תְּנַאי זֶה נָתַן לָהּ הַדִּינָר. הֲרֵי הַתְּנַאי קַיָּם וַהֲרֵי זוֹ מְקֻדֶּשֶׁת עַל תְּנַאי. וְאִם נָתְנָה לוֹ מָאתַיִם זוּז תִּהְיֶה מְקֻדֶּשֶׁת וְאִם לֹא נָתְנָה לוֹ אֵינָהּ מְקֻדֶּשֶׁת:","אֲבָל אִם אָמַר לָהּ הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי בְּדִינָר זֶה וְנָתַן הַדִּינָר בְּיָדָהּ וְהִשְׁלִים הַתְּנַאי וְאָמַר אִם תִּתְּנִי לִי מָאתַיִם זוּז תִּהְיִי מְקֻדֶּשֶׁת וְאִם לֹא תִּתְּנִי לִי לֹא תִּהְיִי מְקֻדֶּשֶׁת הֲרֵי הַתְּנַאי בָּטֵל מִפְּנֵי שֶׁהִקְדִּים הַמַּעֲשֶׂה וְנָתַן בְּיָדָהּ וְאַחַר כָּךְ הִתְנָה. וְאַף עַל פִּי שֶׁהַכּל בְּתוֹךְ כְּדֵי דִּבּוּר הֲרֵי זוֹ מְקֻדֶּשֶׁת מִיָּד וְאֵינָהּ צְרִיכָה לִתֵּן לוֹ כְּלוּם:","וְכֵן אִם אָמַר לָהּ אִם תִּתְּנִי לִי מָאתַיִם זוּז הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי בְּדִינָר זֶה וְאַחַר כָּךְ נָתַן הַדִּינָר בְּיָדָהּ הֲרֵי הַתְּנַאי בָּטֵל מִפְּנֵי שֶׁלֹּא כָּפַל תְּנָאוֹ. שֶׁהֲרֵי לֹא אָמַר לָהּ וְאִם לֹא תִּתְּנִי לֹא תִּהְיִי מְקֻדֶּשֶׁת וַהֲרֵי זוֹ מְקֻדֶּשֶׁת מִיָּד וְאֵינָהּ צְרִיכָה לִתֵּן לוֹ כְּלוּם:","וְכֵן אִם אָמַר לָהּ אִם לֹא תִּתְּנִי לִי מָאתַיִם זוּז לֹא תִּהְיִי מְקֻדֶּשֶׁת לִי וְאִם תִּתְּנִי לִי מָאתַיִם זוּז הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי בְּדִינָר זֶה וְאַחַר כָּךְ נָתַן הַדִּינָר בְּיָדָהּ הֲרֵי הַתְּנַאי בָּטֵל לְפִי שֶׁהִקְדִּים לָאו לְהֵן וַהֲרֵי זוֹ מְקֻדֶּשֶׁת מִיָּד וְאֵינָהּ צְרִיכָה לִתֵּן לוֹ כְּלוּם:","וְכֵן אִם אָמַר לָהּ אִם תַּעֲלִי לָרָקִיעַ אוֹ תֵּרְדִי לַתְּהוֹם הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי בְּדִינָר זֶה וְאִם לֹא תַּעֲלִי לָרָקִיעַ וְלֹא תֵּרְדִי לַתְּהוֹם לֹא תִּהְיִי מְקֻדֶּשֶׁת וְאַחַר כָּךְ נָתַן הַדִּינָר בְּיָדָהּ הֲרֵי הַתְּנַאי בָּטֵל וַהֲרֵי הִיא מְקֻדֶּשֶׁת מִיָּד שֶׁהַדָּבָר יָדוּעַ שֶׁאִי אֶפְשָׁר לָהּ לְקַיֵּם תְּנַאי זֶה וְאֵין זֶה אֶלָּא כְּמַפְלִיגָהּ בִּדְבָרִים דֶּרֶךְ שְׂחוֹק וְהִתּוּל:","הֲרֵי שֶׁהִתְנָה בְּדָבָר שֶׁאֶפְשָׁר לַעֲשׂוֹתוֹ אֶלָּא שֶׁהַתּוֹרָה אָסְרָה אוֹתוֹ כְּגוֹן שֶׁאָמַר לְאִשָּׁה אִם תֹּאכְלִי חֵלֶב וְדָם הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי בְּדִינָר זֶה וְאִם לֹא תֹּאכְלִי לֹא תִּהְיִי מְקֻדֶּשֶׁת. אִם תֹּאכְלִי בְּשַׂר חֲזִיר הֲרֵי זֶה גִּטֵּךְ וְאִם לֹא תֹּאכְלִי לֹא יְהֵא גֵּט. וְאַחַר שֶׁהִתְנָה נָתַן הַדִּינָר אוֹ הַגֵּט בְּיָדָהּ הֲרֵי הַתְּנַאי קַיָּם. וְאִם עָבְרָה וְאָכְלָה תִּהְיֶה מְקֻדֶּשֶׁת אוֹ מְגֹרֶשֶׁת. וְאִם לֹא אָכְלָה אֵינָהּ מְקֻדֶּשֶׁת וְאֵינָהּ מְגֹרֶשֶׁת. וְאֵין אוֹמְרִים בָּזֶה הֲרֵי הִתְנָה עַל מַה שֶּׁכָּתוּב בַּתּוֹרָה שֶׁהֲרֵי בְּיָדָהּ שֶׁלֹּא תֹּאכַל וְשֶׁלֹּא תִּתְקַדֵּשׁ וְלֹא תִּתְגָּרֵשׁ:","וּבַמֶּה אָמְרוּ חֲכָמִים כָּל הַמַּתְנֶה עַל מַה שֶּׁכָּתוּב בַּתּוֹרָה תְּנָאוֹ בָּטֵל חוּץ מִדָּבָר שֶׁבְּמָמוֹן שֶׁתְּנָאוֹ קַיָּם. כְּגוֹן שֶׁקִּדֵּשׁ אוֹ גֵּרֵשׁ אוֹ נָתַן אוֹ מָכַר עַל תְּנַאי שֶׁהוּא רוֹצֶה בִּתְנָאוֹ שֶׁיְּזַכֶּה עַצְמוֹ בְּדָבָר שֶׁלֹּא זִכְּתָה לוֹ תּוֹרָה וּמָנְעָה מִמֶּנּוּ אוֹ יִפְטֹר עַצְמוֹ בִּתְנָאוֹ מִדָּבָר שֶׁחִיְּבָה אוֹתוֹ בּוֹ הַתּוֹרָה שֶׁאוֹמְרִין לוֹ תְּנָאֲךָ בָּטֵל וּכְבָר נִתְקַיְּמוּ מַעֲשֶׂיךָ וְאֵין אַתָּה נִפְטָר מִדָּבָר שֶׁחִיְּבָה אוֹתְךָ בּוֹ הַתּוֹרָה וְלֹא תִּזְכֶּה בְּדָבָר שֶׁמָּנְעָה אוֹתְךָ מִמֶּנּוּ:","כֵּיצַד. כְּגוֹן שֶׁקִּדֵּשׁ אִשָּׁה עַל תְּנַאי שֶׁאֵין לָהּ עָלָיו שְׁאֵר כְּסוּת וְעוֹנָה. שֶׁאוֹמְרִין לוֹ בִּכְסוּת וּשְׁאֵר שֶׁהוּא תְּנַאי שֶׁבְּמָמוֹן תְּנָאֲךָ קַיָּם אֲבָל בְּעוֹנָה תְּנָאֲךָ בָּטֵל שֶׁהַתּוֹרָה חִיְּבָה אוֹתְךָ בְּעוֹנָה וַהֲרֵי זוֹ מְקֻדֶּשֶׁת וְאַתָּה חַיָּב בְּעוֹנָתָהּ וְאֵין בְּיָדְךָ לִפְטֹר עַצְמְךָ בִּתְנָאֲךָ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְכֵן הַמְקַדֵּשׁ יְפַת תֹּאַר עַל תְּנַאי שֶׁיִּתְעַמֵּר בָּהּ הֲרֵי זוֹ מְקֻדֶּשֶׁת וְאֵין לוֹ לְהִתְעַמֵּר בָּהּ שֶׁהֲרֵי הַתּוֹרָה מָנְעָה אוֹתוֹ מִלְּהִשְׁתַּעְבֵּד בָּהּ אַחַר שֶׁנִּבְעֲלָה. וְלֹא מִפְּנֵי תְּנָאוֹ יִזְכֶּה בְּדָבָר שֶׁמָּנְעָה אוֹתוֹ תּוֹרָה אֶלָּא תְּנָאוֹ בָּטֵל וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הִתְנָה עַל הָאִשָּׁה בִּשְׁעַת קִדּוּשִׁין אוֹ בִּשְׁעַת גֵּרוּשִׁין שֶׁתִּבָּעֵל לְאָבִיהָ וּלְאָחִיהָ אוֹ לִבְנָהּ וְכַיּוֹצֵא בָּזֶה הֲרֵי זֶה כְּמִי שֶׁהִתְנָה עָלֶיהָ שֶׁתַּעֲלֶה לָרָקִיעַ אוֹ שֶׁתֵּרֵד לַתְּהוֹם וּתְנָאוֹ בָּטֵל שֶׁאֵין בְּיָדָהּ שֶׁיַּעַבְרוּ אֲחֵרִים וְיָבֹאוּ עַל הָעֶרְוָה וְנִמְצָא שֶׁהִתְנָה עִמָּהּ בְּדָבָר שֶׁאֵינוֹ בְּיָדָהּ לְקַיְּמוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","אֲבָל אִם הִתְנָה עָלֶיהָ שֶׁיִּתֵּן לִי פְּלוֹנִי חֲצֵרוֹ אוֹ שֶׁיַּשִּׂיא בִּתּוֹ לִבְנִי וְכַיּוֹצֵא בָּזֶה תְּנָאוֹ קַיָּם שֶׁהֲרֵי אֶפְשָׁר בְּיָדָהּ לְקַיְּמוֹ וְתִתֵּן לִפְלוֹנִי מָמוֹן רַב עַד שֶׁיִּתֵּן לוֹ חֲצֵרוֹ וְעַד שֶׁיַּשִּׂיא בִּתּוֹ לִבְנוֹ שֶׁהֲרֵי אֵין כָּאן עֲבֵרָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","שִׂים כָּל אֵלּוּ הַדְּבָרִים שֶׁל תְּנָאִים לְנֶגֶד עֵינֶיךָ תָּמִיד. וְכָל מָקוֹם שֶׁאַתָּה שׁוֹמֵעַ הַמְקַדֵּשׁ עַל תְּנַאי כָּךְ וְכָךְ אוֹ הַנּוֹתֵן גֵּט עַל תְּנַאי כָּךְ וְכָךְ אוֹ הַמּוֹכֵר אוֹ הַנּוֹתֵן עַל תְּנַאי תֵּדַע שֶׁהַתְּנַאי יֵשׁ בּוֹ אַרְבָּעָה דְּבָרִים אֵלּוּ שֶׁבֵּאַרְנוּ כְּדֵי שֶׁלֹּא נִהְיֶה צְרִיכִין לְפָרֵשׁ אוֹתָן בְּכָל מָקוֹם. וְאִם חָסֵר אֶחָד מֵהֶן אֵין כָּאן תְּנַאי:","יֵשׁ מִקְצָת גְּאוֹנִים אַחֲרוֹנִים שֶׁאָמְרוּ שֶׁאֵין צָרִיךְ אָדָם לִכְפּל תְּנָאוֹ אֶלָּא בְּגִטִּין וְקִדּוּשִׁין בִּלְבַד אֲבָל בְּדִינֵי מָמוֹן אֵינוֹ צָרִיךְ לִכְפּל. וְאֵין רָאוּי לִסְמֹךְ עַל דָּבָר זֶה שֶׁכְּפִילַת הַתְּנַאי עִם שְׁאָר הָאַרְבָּעָה דְּבָרִים מִתְּנַאי בְּנֵי גָּד וּבְנֵי רְאוּבֵן לָמְדוּ אוֹתָן חֲכָמִים (במדבר לב כט) \"אִם יַעַבְרוּ בְּנֵי גָּד\" וְגוֹ' (במדבר לב ל) \"וְאִם לֹא יַעַבְרוּ\" וּתְנַאי זֶה לֹא הָיָה לֹא בְּגִטִּין וְלֹא בְּקִדּוּשִׁין. וְכָזֶה הוֹרוּ גְּדוֹלֵי הַגְּאוֹנִים הָרִאשׁוֹנִים וְכֵן רָאוּי לַעֲשׂוֹת:","הַמְקַדֵּשׁ עַל תְּנַאי כְּשֶׁיִּתְקַיֵּם הַתְּנַאי תִּהְיֶה מְקֻדֶּשֶׁת מִשָּׁעָה שֶׁנִּתְקַיֵּם הַתְּנַאי לֹא מִשָּׁעָה שֶׁנִּתְקַדְּשָׁה. כֵּיצַד. הָאוֹמֵר לְאִשָּׁה אִם אֶתֵּן לִיךְ מָאתַיִם זוּז בְּשָׁנָה זוֹ הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי בְּדִינָר זֶה וְאִם לֹא אֶתֵּן לִיךְ לֹא תִּהְיִי מְקֻדֶּשֶׁת וְנָתַן הַדִּינָר לְיָדָהּ בְּנִיסָן וְנָתַן לָהּ הַמָּאתַיִם זוּז שֶׁהִתְנָה עִמָּהּ בֶּאֱלוּל הֲרֵי זוֹ מְקֻדֶּשֶׁת מֵאֱלוּל. לְפִיכָךְ אִם קִדְּשָׁהּ אַחֵר קֹדֶם שֶׁיִּתְקַיֵּם הַתְּנַאי שֶׁל רִאשׁוֹן הֲרֵי זוֹ מְקֻדֶּשֶׁת לַשֵּׁנִי. וְכֵן הַדִּין בְּגִטִּין וּבְמָמוֹנוֹת בְּשָׁעָה שֶׁיִּתְקַיֵּם הַתְּנַאי הוּא שֶׁיִּהְיֶה גֵּט אוֹ יִתְקַיֵּם הַמִּקָּח אוֹ הַמַּתָּנָה:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהָיָה שָׁם תְּנַאי וְלֹא אָמַר מֵעַכְשָׁו. אֲבָל אִם אָמַר לָהּ הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי מֵעַכְשָׁו בְּדִינָר זֶה אִם אֶתֵּן לִיךְ מָאתַיִם זוּז וּלְאַחַר זְמַן נָתַן לָהּ מָאתַיִם זוּז הֲרֵי זוֹ מְקֻדֶּשֶׁת לְמַפְרֵעַ מִשְּׁעַת הַקִּדּוּשִׁין אַף עַל פִּי שֶׁלֹּא נַעֲשָׂה תְּנָאוֹ אֶלָּא לְאַחַר זְמַן מְרֻבֶּה. לְפִיכָךְ אִם קִדְּשָׁהּ הַשֵּׁנִי קֹדֶם שֶׁיַּעֲשֶׂה הַתְּנַאי אֵינָהּ מְקֻדֶּשֶׁת. וְכֵן הַדִּין בְּגִטִּין וּבְמָמוֹן:","כָּל הָאוֹמֵר מֵעַכְשָׁו לֹא יִצְטָרֵךְ לִכְפּל תְּנָאוֹ וְלֹא לְהַקְדִּים הַתְּנַאי עַל הַמַּעֲשֶׂה אֶלָּא אַף עַל פִּי שֶׁהִקְדִּים הַמַּעֲשֶׂה תְּנָאוֹ קַיָּם. אֲבָל צָרִיךְ לְהַתְנוֹת בְּדָבָר שֶׁאֶפְשָׁר לְקַיְּמוֹ. וְאִם הִתְנָה בְּדָבָר שֶׁאִי אֶפְשָׁר לְקַיְּמוֹ הֲרֵי זֶה כְּמַפְלִיג בִּדְבָרִים וְאֵין שָׁם תְּנַאי. וְכָל הָאוֹמֵר עַל מְנָת כְּאוֹמֵר מֵעַכְשָׁו וְאֵינוֹ צָרִיךְ לִכְפּל הַתְּנַאי וְלֹא לְהַקְדִּימוֹ לַמַּעֲשֶׂה:","כֵּיצַד. הָאוֹמֵר לְאִשָּׁה הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי עַל מְנָת שֶׁתִּתְּנִי לִי מָאתַיִם זוּז. הֲרֵי זֶה גִּטֵּךְ עַל מְנָת שֶׁתִּתְּנִי לִי מָאתַיִם זוּז. הֲרֵי חָצֵר זוֹ נְתוּנָה לִיךְ בְּמַתָּנָה עַל מְנָת שֶׁתִּתְּנִי לִי מָאתַיִם זוּז. הֲרֵי תְּנָאוֹ קַיָּם וְנִתְקַדְּשָׁה אוֹ נִתְגָּרְשָׁה וְזָכְתָה זוֹ בֶּחָצֵר וְהֵם יִתְּנוּ הַמָּאתַיִם זוּז. וְאִם לֹא נָתְנוּ לֹא תִּהְיֶה זוֹ מְקֻדֶּשֶׁת וְלֹא מְגֹרֶשֶׁת וְלֹא תִּזְכֶּה זוֹ בֶּחָצֵר. וְאַף עַל פִּי שֶׁלֹּא כָּפַל תְּנָאוֹ וְאַף עַל פִּי שֶׁהִקְדִּים הַמַּעֲשֶׂה לַתְּנַאי וְנָתַן הַקִּדּוּשִׁין אוֹ הַגֵּט בְּיָדָהּ וְהֶחֱזִיקָה זוֹ בֶּחָצֵר וְאַחַר כָּךְ הִשְׁלִים תְּנָאוֹ. שֶׁהֲרֵי כְּשֶׁיִּתְקַיֵּם הַתְּנַאי תִּזְכֶּה זוֹ בֶּחָצֵר וְתִתְקַדֵּשׁ זוֹ וְתִתְגָּרֵשׁ מִשָּׁעָה רִאשׁוֹנָה שֶׁבָּהּ נַעֲשָׂה הַמַּעֲשֶׂה כְּאִלּוּ לֹא הָיָה שָׁם תְּנַאי כְּלָל:"],"Mishneh Torah, Mourning 4":["מִנְּהַג יִשְׂרָאֵל בְּמֵתִים וּבִקְבוּרָה כָּךְ הוּא. מְאַמְּצִין עֵינָיו שֶׁל מֵת. וְאִם נִפְתַּח פִּיו קוֹשְׁרִין אֶת לְחָיָיו. וּפוֹקְקִין אֶת נְקָבָיו אַחַר שֶׁמְּדִיחִין אוֹתוֹ. וְסָכִין אוֹתוֹ בְּמִינֵי בְּשָׂמִים. וְגוֹזְזִין שְׂעָרוֹ. וּמַלְבִּישִׁין אוֹתוֹ תַּכְרִיכִין תְּפוּרִין בְּחוּט שֶׁל פִּשְׁתָּן לְבָנִים. וְלֹא יִהְיוּ דְּמֵיהֶן יְקָרִים. וְנָהֲגוּ חֲכָמִים בְּסוּדָר שְׁוֵה זוּז שֶׁלֹּא לְבַיֵּשׁ אֶת מִי שֶׁאֵין לוֹ. וּמְכַסִּין פְּנֵי הַמֵּת שֶׁלֹּא לְבַיֵּשׁ אֶת הָעֲנִיִּים שֶׁפְּנֵיהֶם מֻשְׁחָרִין בָּרָעָב:","וְאָסוּר לִקְבֹּר בְּתַכְרִיכִין שֶׁל מֶשִׁי וּבְגָדִים הַמֻּזְהָבִין הָרְקוּמִין אֲפִלּוּ לְנָשִׂיא שֶׁבְּיִשְׂרָאֵל. שֶׁזֶּהוּ גַּסּוּת הָרוּחַ וְהַשְׁחָתָה וּמַעֲשֵׂה עַכּוּ\"ם. וְסוֹבְלִין אֶת הַמֵּת עַל הַכָּתֵף עַד בֵּית הַקְּבָרוֹת:","וְנוֹשְׂאֵי הַמִּטָּה אֲסוּרִין בִּנְעִילַת הַסַּנְדָּל שֶׁמָּא תִּפָּסֵק רְצוּעָה מִסַּנְדָּלוֹ שֶׁל אֶחָד מֵהֶן וְנִמְצָא מִתְעַכֵּב מִן הַמִּצְוָה:","וְחוֹפְרִין בַּעֲפַר מְעָרוֹת וְעוֹשִׂין כּוּךְ בְּצַד הַמְּעָרָה וְקוֹבְרִין אוֹתוֹ בּוֹ וּפָנָיו לְמַעְלָה. וּמַחְזִירִין הֶעָפָר וְהָאֲבָנִים עָלָיו. וְיֵשׁ לָהֶן לִקְבֹּר בְּאָרוֹן שֶׁל עֵץ. וְהַמְלַוִּין אוֹתוֹ אוֹמְרִין לוֹ לֵךְ בְּשָׁלוֹם שֶׁנֶּאֱמַר (בראשית טו טו) \"וְאַתָּה תָּבוֹא אֶל אֲבֹתֶיךָ בְּשָׁלוֹם\". וּמְצַיְּנִין אֶת כָּל בֵּית הַקְּבָרוֹת וּבוֹנִין נֶפֶשׁ עַל הַקֶּבֶר. וְהַצַּדִּיקִים אֵין בּוֹנִים לָהֶם נֶפֶשׁ עַל קִבְרוֹתֵיהֶם שֶׁדִּבְרֵיהֶם הֵם זִכְרוֹנָם. וְלֹא יִפְנֶה אָדָם לְבַקֵּר הַקְּבָרוֹת:","הַגּוֹסֵס הֲרֵי הוּא כְּחַי לְכָל דָּבָר. אֵין קוֹשְׁרִין לְחָיָיו וְאֵין פּוֹקְקִין נְקָבָיו וְאֵין מַנִּיחִין כְּלִי מַתָּכוֹת וּכְלִי מֵיקֵר עַל טַבּוּרוֹ שֶׁלֹּא יִתְפַּח. וְלֹא סָכִין אוֹתוֹ. וְלֹא מְדִיחִין אוֹתוֹ. וְלֹא מְטִילִין אוֹתוֹ עַל הַחוֹל וְלֹא עַל הַמֶּלַח עַד שָׁעָה שֶׁיָּמוּת. וְהַנּוֹגֵעַ בּוֹ הֲרֵי זֶה שׁוֹפֵךְ דָּמִים. לְמָה זֶה דּוֹמֶה לְנֵר שֶׁמְּטַפְטֵף כֵּיוָן שֶׁיִּגַּע בּוֹ אָדָם יִכְבֶּה. וְכָל הַמְאַמֵּץ עֵינָיו עִם יְצִיאַת נֶפֶשׁ הֲרֵי זֶה שׁוֹפֵךְ דָּמִים אֶלָּא יִשְׁהֶא מְעַט שֶׁמָּא נִתְעַלֵּף. וְכֵן אֵין קוֹרְעִין עָלָיו. וְלֹא חוֹלְצִין כָּתֵף. וְלֹא מַסְפִּידִין. וְלֹא מַכְנִיסִין עִמּוֹ אָרוֹן וְתַכְרִיכִין בַּבַּיִת עַד שֶׁיָּמוּת:","מִי שֶׁמֵּתוֹ מֻטָּל לְפָנָיו אוֹכֵל בְּבַיִת אַחֵר. אֵין לוֹ בַּיִת אַחֵר עוֹשֶׂה מְחִצָּה וְאוֹכֵל. אֵין לוֹ דָּבָר לַעֲשׂוֹת מְחִצָּה מַחְזִיר פָּנָיו וְאוֹכֵל. וּבֵין כָּךְ וּבֵין כָּךְ אֵינוֹ מֵסֵב וְאוֹכֵל. וְלֹא אוֹכֵל בָּשָׂר. וְלֹא שׁוֹתֶה יַיִן. וְאֵינוֹ מְבָרֵךְ. וְאֵינוֹ מְזַמֵּן. וְאֵין מְבָרְכִין עָלָיו וְאֵין מְזַמְּנִין עָלָיו. וּפָטוּר מִקְּרִיאַת שְׁמַע וּמִן הַתְּפִלָּה וּמִתְּפִלִּין וּמִכָּל מִצְוֹת הָאֲמוּרוֹת בַּתּוֹרָה. בְּשַׁבָּת מֵסֵב וְאוֹכֵל בָּשָׂר וְשׁוֹתֶה יַיִן. וּמְבָרֵךְ. וּמְזַמֵּן. וּמְבָרְכִין עָלָיו וּמְזַמְּנִין עָלָיו. וְחַיָּב בְּכָל מִצְוֹת הָאֲמוּרוֹת בַּתּוֹרָה חוּץ מִתַּשְׁמִישׁ הַמִּטָּה. נִקְבַּר הַמֵּת הֲרֵי זֶה מֻתָּר לֶאֱכל בָּשָׂר וְלִשְׁתּוֹת יַיִן מְעַט כְּדֵי לִשְׁרוֹת אֲכִילָה שֶׁבְּמֵעָיו אֲבָל לֹא לִרְווֹת:","אֵין מַשְׁהִין אֶת הַמֵּת אֶלָּא מַדְחִין מִטָּתוֹ מִיָּד. וְכָל הַמַּדְחֶה מִטָּתוֹ הֲרֵי זֶה מְשֻׁבָּח. וְעַל אָבִיו וְעַל אִמּוֹ הֲרֵי זֶה מְגֻנֶּה:","הָיָה עֶרֶב שַׁבָּת אוֹ עֶרֶב יוֹם טוֹב אוֹ שֶׁהָיוּ גְּשָׁמִים מְזַלְּפִין עַל הַמִּטָּה מֻתָּר. שֶׁלֹּא מִהֵר אֶלָּא לִכְבוֹד אָבִיו וְאִמּוֹ. וְכָל הַמֵּלִין אֶת מֵתוֹ עוֹבֵר בְּלֹא תַּעֲשֶׂה אֶלָּא אִם כֵּן הֱלִינוֹ לִכְבוֹדוֹ וּלְהַשְׁלִים צְרָכָיו:","הָאָבֵל בְּיוֹם רִאשׁוֹן בִּלְבַד אָסוּר לְהָנִיחַ תְּפִלִּין וּלֶאֱכל מִשֶּׁלּוֹ. וְחַיָּב לֵישֵׁב עַל מִטָּה כְּפוּיָה. וּבִשְׁאָר יְמֵי הָאֵבֶל מֻתָּר לוֹ לֶאֱכל מִשֶּׁלּוֹ וְלֵישֵׁב עַל גַּבֵּי מַפַּץ אוֹ קַרְקַע. וּמֵנִיחַ תְּפִלִּין. וּמִנַּיִן שֶׁהוּא אָסוּר בְּיוֹם רִאשׁוֹן לְהָנִיחַ תְּפִלִּין. שֶׁהֲרֵי נֶאֱמַר לִיחֶזְקֵאל (יחזקאל כד יז) \"פְּאֵרְךָ חֲבוֹשׁ עָלֶיךָ\" מִכְלַל שֶׁכָּל הָעָם אֲסוּרִין. וְנֶאֱמַר לוֹ (יחזקאל כד יז) \"וְלֶחֶם אֲנָשִׁים לֹא תֹאכֵל\" מִכְלַל שֶׁכָּל הָעָם אוֹכְלִין מִשֶּׁל אֲחֵרִים בְּיוֹם רִאשׁוֹן וַאֲסוּרִין לֶאֱכל מִשֶּׁל עַצְמָן:"],"Mishneh Torah, Murderer and the Preservation of Life 3":["הַמַּכֶּה אֶת חֲבֵרוֹ בְּזָדוֹן בְּאֶבֶן אוֹ בְּעֵץ וֶהֱמִיתוֹ. אוֹמְדִין דָּבָר שֶׁהִכָּהוּ בּוֹ וּמָקוֹם שֶׁהִכָּה עָלָיו. אִם רָאוּי אוֹתוֹ חֵפֶץ לְהָמִית בְּאֵיבָר זֶה אוֹ אֵינוֹ רָאוּי. שֶׁנֶּאֱמַר (במדבר לה יז) \"בְּאֶבֶן יָד אֲשֶׁר יָמוּת בָּהּ הִכָּהוּ\" (במדבר לה יח) \"אוֹ בִּכְלִי עֵץ יָד אֲשֶׁר יָמוּת בּוֹ הִכָּהוּ\". עַד שֶׁיִּהְיֶה בּוֹ כְּדֵי לְהָמִית. וְאֵינוֹ דּוֹמֶה מַכֵּהוּ עַל לִבּוֹ לְמַכֵּהוּ עַל יְרֵכוֹ:","הוֹאִיל וְנֶאֱמַר (במדבר לה יז) \"אֲשֶׁר יָמוּת בָּהּ\" מִכָּאן שֶׁאוֹמְדִין מְקוֹם הַמַּכָּה. וּכְשֵׁם שֶׁאוֹמְדִין הַחֵפֶץ שֶׁהִכָּה בּוֹ וּמְקוֹם הַמַּכָּה כָּךְ אוֹמְדִין כֹּחַ הַהַכָּאָה שֶׁנֶּאֱמַר (במדבר לה יז) \"בְּאֶבֶן יָד\" מִכָּאן שֶׁמְּשַׁעֲרִין אֶת הַיָּד. אֵינוֹ דּוֹמֶה זוֹרֵק אֶבֶן בַּחֲבֵרוֹ בְּרִחוּק שְׁתֵּי אַמּוֹת לְזוֹרֵק בּוֹ בְּרִחוּק עֶשֶׂר שֶׁבְּרִחוּק עֶשֶׂר יִהְיֶה כֹּחָהּ יָתֵר. וְאֵינוֹ דּוֹמֶה זוֹרֵק בְּרִחוּק עֶשֶׂר לְזוֹרֵק בְּרִחוּק מֵאָה שֶׁבְּרִחוּק הַמָּקוֹם בְּיוֹתֵר יִתְמַעֵט כֹּחַ הַהַכָּאָה:","וְכֵן מְשַׁעֲרִין הַמַּכָּה עַצְמָהּ וּמְשַׁעֲרִין כֹּחַ הַהוֹרֵג וְכֹחַ הַנֶּהֱרָג. אִם הוּא גָּדוֹל אוֹ קָטָן אוֹ חָזָק אוֹ חַלָּשׁ אוֹ בָּרִיא אוֹ חוֹלֶה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. שֶׁנֶּאֱמַר (במדבר לה יז) \"אֲשֶׁר יָמוּת בָּהּ\". מִיתָתוֹ שֶׁל זֶה מְשַׁעֲרִין כָּל סִבּוֹתֶיהָ:","כְּלִי בַּרְזֶל לֹא נָתְנָה בּוֹ תּוֹרָה שִׁעוּר. שֶׁנֶּאֱמַר (במדבר לה טז) \"וְאִם בִּכְלִי בַרְזֶל הִכָּהוּ וַיָּמֹת רֹצֵחַ הוּא\". וַאֲפִלּוּ בְּמַחַט. וְהוּא שֶׁיִּהְיֶה לוֹ חֹד כְּמוֹ מַחַט אוֹ שִׁפּוּד אוֹ סַכִּין וְכַיּוֹצֵא בָּהֶן. אֲבָל אִם הִכָּהוּ בְּעֶשֶׁת שֶׁל בַּרְזֶל וְכַיּוֹצֵא בָּהּ אוֹמְדִין אוֹתָהּ כְּדֶרֶךְ שֶׁאוֹמְדִין הָעֵץ אוֹ הָאֶבֶן:","הַמַּכֶּה אֶת חֲבֵרוֹ בְּלֹא כְּלִי וֶהֱמִיתוֹ. כְּגוֹן שֶׁהִכָּהוּ בְּיָדוֹ אוֹ בְּרַגְלוֹ אוֹ נְגָפוֹ בְּרֹאשׁוֹ וֶהֱמִיתוֹ מְשַׁעֲרִין כֹּחַ הַמַּכֶּה וְכֹחַ הַנֶּהֱרָג וּמְקוֹם הַמַּכָּה. אֵינוֹ דּוֹמֶה דּוֹחֵף חֲבֵרוֹ בְּאֶצְבָּעוֹ לְבוֹעֵט בּוֹ בְּרַגְלוֹ בְּכָל כֹּחוֹ. וְאֵינוֹ דּוֹמֶה מַכֵּהוּ עַל לִבּוֹ לְמַכֵּהוּ עַל מָתְנָיו. וְאֵינוֹ דּוֹמֶה חַלָּשׁ הַמַּכֶּה אֶת הַבָּרִיא הֶחָזָק לְבָרִיא חָזָק הַמַּכֶּה חַלָּשׁ אוֹ חוֹלֶה:","וּמִנַּיִן שֶׁמְּשַׁעֲרִין בְּכָל אֵלּוּ שֶׁנֶּאֱמַר (במדבר לה כא) \"אוֹ בְאֵיבָה הִכָּהוּ בְיָדוֹ וַיָּמֹת מוֹת יוּמַת הַמַּכֶּה\". אַף עַל פִּי שֶׁנֶּאֱמַר בְּיָדוֹ הִצְרִיךְ הַכָּתוּב לִהְיוֹת הַהַכָּאָה בְּאֵיבָה מִכְּלָל שֶׁמְּשַׁעֲרִין כֹּחַ הַהַכָּאָה:","וְכֵן הַדּוֹחֵף אֶת חֲבֵרוֹ מֵרֹאשׁ הַגַּג וְנָפַל וּמֵת מְשַׁעֲרִין גֹּבַהּ הַמָּקוֹם שֶׁהִפִּילוֹ מֵעָלָיו וְכֹחַ הַנִּדְחָף. שֶׁאֵינוֹ דּוֹמֶה בֶּן יוֹמוֹ שֶׁנָּפַל לְגָדוֹל שֶׁנָּפַל. וּמִנַּיִן שֶׁמְּשַׁעֲרִין גֹּבַהּ הַמָּקוֹם. שֶׁנֶּאֱמַר (במדבר לה כ) \"וְאִם בְּשִׂנְאָה יֶהְדָּפֶנּוּ\". וְיֵרָאֶה לִי שֶׁכָּל מָקוֹם שֶׁאֵין בְּגָבְהוֹ עֲשָׂרָה טְפָחִים אֵין בּוֹ כְּדֵי לְהָמִית כְּמוֹ שֶׁאָמְרוּ בְּבוֹר לְעִנְיַן בְּהֵמָה:","אֶחָד הַמַּכֶּה אֶת חֲבֵרוֹ בְּאֶבֶן אוֹ בְּעֵץ. אוֹ שֶׁהִכָּהוּ בְּגוּשׁ עָפָר אוֹ בְּגוּשׁ מֶלַח וְגָפְרִית אוֹ בְּסַל מָלֵא עָפָר אוֹ צְרוֹרוֹת וַאֲפִלּוּ בְּפֶלַח דְּבֵלָה. שֶׁנֶּאֱמַר (במדבר לה יז) \"אֲשֶׁר יָמוּת בָּהּ\" כָּל שֶׁהוּא רָאוּי לְהָמִית וְהַכֹּבֶד הוּא שֶׁמֵּמִית:","הַדּוֹחֵף אֶת חֲבֵרוֹ לְתוֹךְ הַמַּיִם אוֹ לְתוֹךְ הָאֵשׁ אוֹמְדִין אוֹתוֹ אִם יָכוֹל לַעֲלוֹת מִשָּׁם פָּטוּר מִמִּיתַת בֵּית דִּין וְאִם לָאו חַיָּב. וְכֵן אִם כָּבַשׁ עָלָיו [בְּתוֹךְ הַמַּיִם אוֹ] בְּתוֹךְ הָאֵשׁ עַד שֶׁלֹּא נִשְׁאַר בּוֹ כֹּחַ לַעֲלוֹת וּמֵת חַיָּב. אַף עַל פִּי שֶׁאֵינוֹ הוּא הַדּוֹחֵף בַּתְּחִלָּה. וְהוּא הַדִּין לְמַנִּיחַ יָדוֹ עַל פִּי חֲבֵרוֹ וְחָטְמוֹ עַד שֶׁהִנִּיחוֹ מְפַרְפֵּר וְאֵינוֹ יָכוֹל לְחַיּוֹת. אוֹ שֶׁכְּפָתוֹ וְהִנִּיחוֹ בַּצִּנָּה אוֹ בַּחַמָּה עַד שֶׁמֵּת. אוֹ שֶׁבָּנָה עָלָיו מָקוֹם עַד שֶׁמָּנַע מִמֶּנּוּ הָרוּחַ. אוֹ שֶׁהִכְנִיסוֹ לַמְּעָרָה אוֹ לַבַּיִת וְעִשֵּׁן עָלָיו עַד שֶׁמֵּת. אוֹ שֶׁהִכְנִיסוֹ לְבַיִת שֶׁל שַׁיִשׁ וְהִדְלִיק עָלָיו נֵר עַד שֶׁהֱמִיתוֹ הַהֶבֶל. בְּכָל אֵלּוּ נֶהֱרָג עָלָיו שֶׁזֶּה כְּמִי שֶׁחֲנָקוֹ בְּיָדוֹ:","אֲבָל הַכּוֹפֵת אֶת חֲבֵרוֹ וְהִנִּיחוֹ בָּרָעָב עַד שֶׁמֵּת. אוֹ שֶׁכְּפָתוֹ וְהִנִּיחוֹ בְּמָקוֹם שֶׁסּוֹף הַצִּנָּה אוֹ הַחַמָּה לָבוֹא לְשָׁם וּבָאָה וֶהֱמִיתַתּוּ. אוֹ שֶׁכָּפָה עָלָיו גִּגִּית. אוֹ שֶׁפָּרַע עָלָיו אֶת הַמַּעֲזִיבָה. אוֹ שֶׁהִשִּׁיךְ עָלָיו אֶת הַנָּחָשׁ. וְאֵין צָרִיךְ לוֹמַר אִם שִׁסָּה בּוֹ כֶּלֶב אוֹ נָחָשׁ. בְּכָל אֵלּוּ אֵין מְמִיתִין אוֹתוֹ. וַהֲרֵי הוּא רוֹצֵחַ. וְדוֹרֵשׁ דָּמִים דּוֹרֵשׁ מִמֶּנּוּ דָּם:","וְכֵן הַדּוֹחֵף חֲבֵרוֹ בְּבוֹר וְהָיָה שָׁם סֻלָּם שֶׁיָּכוֹל לַעֲלוֹת עָלָיו. אוֹ שֶׁזָּרַק בּוֹ חֵץ וְהָיָה תְּרִיס בְּיָדוֹ לְהָגֵן עָלָיו. וּבָא אַחֵר וְסִלֵּק אֶת הַסֻּלָּם וְהֵסִיר אֶת הַתְּרִיס. שְׁנֵיהֶן אֵין נֶהֱרָגִין בְּבֵית דִּין. אֲפִלּוּ הָיָה הַדּוֹחֵף עַצְמוֹ הוּא שֶׁחָזַר וְסִלֵּק הַסֻּלָּם פָּטוּר מִמִּיתַת בֵּית דִּין. וְנִדְרָשׁ מִמֶּנּוּ הַדָּם:","הַזּוֹרֵק צְרוֹר בַּכֹּתֶל וְחָזְרָה הָאֶבֶן לַאֲחוֹרֶיהָ וְהָרְגָה חַיָּב מִיתַת בֵּית דִּין שֶׁמִּכֹּחוֹ הִיא בָּאָה. וְכֵן אֵלּוּ שֶׁמְּשַׂחֲקִין בְּכַדּוּר שֶׁהִתְרוּ בָּהֶן וְהָרְגוּ. בְּתוֹךְ אַרְבַּע אַמּוֹת פְּטוּרִין. חוּץ לְאַרְבַּע אַמּוֹת אֲפִלּוּ לְסוֹף מֵאָה אַמָּה חַיָּבִין. וְהוּא שֶׁיֵּשׁ בָּהּ כְּדֵי לְהָמִית כְּמוֹ שֶׁבֵּאַרְנוּ:","זָרַק אֶבֶן לְמַעְלָה וְהָלְכָה לַצְּדָדִין וְהָרְגָה חַיָּב. הַכּוֹפֵת אֶת חֲבֵרוֹ וְהִנִּיחוֹ בְּמָקוֹם שֶׁאֵינוֹ יָכוֹל לִבְרֹחַ וְהֵצִיף עָלָיו מַיִם וּמֵת הֲרֵי זֶה נֶהֱרָג עָלָיו. וְהוּא שֶׁיָּמוּת מִכֹּחַ רִאשׁוֹן הַבָּא מִמַּעֲשָׂיו:"],"Mishneh Torah, Nazariteship 5":["שְׁלֹשָׁה מִינִין אֲסוּרִין לְנָזִיר. הַטֻּמְאָה. וְהַתִּגְלַחַת. וְהַיּוֹצֵא מִן הַגֶּפֶן. בֵּין פְּרִי בֵּין פְּסלֶת פְּרִי. אֲבָל הַשֵּׁכָר שֶׁל תְּמָרִים אוֹ שֶׁל גְּרוֹגָרוֹת וְכַיּוֹצֵא בָּהֶן מֻתָּר לְנָזִיר. וְ (במדבר ו ג) \"שֵׁכָר\" זֶה שֶׁנֶּאֱסַר עָלָיו בַּתּוֹרָה הוּא הַשֵּׁכָר שֶׁל תַּעֲרֹבֶת הַיַּיִן:","הַיּוֹצֵא מִן הַגֶּפֶן כֵּיצַד. נָזִיר שֶׁאָכַל כְּזַיִת מִן הַפְּרִי שֶׁהוּא עֲנָבִים לַחִים אוֹ יְבֵשִׁים אוֹ בֹּסֶר. אוֹ שֶׁאָכַל כְּזַיִת מִפְּסלֶת הַפְּרִי שֶׁהִיא הַזַּגִּין וְהֵם הַקְּלִפָּה הַחִיצוֹנָה. אוֹ הַחַרְצַנִּים וְהֵם הַזַּגִּין הַפְּנִימִין שֶׁזּוֹרְעִים אוֹתָן הֲרֵי זֶה לוֹקֶה. וְכֵן אִם שָׁתָה רְבִיעִית יַיִן אוֹ אָכַל כְּזַיִת מִיַּיִן קָרוּשׁ שֶׁהוּא הַפְּרִי אוֹ שָׁתָה רְבִיעִית חֹמֶץ שֶׁהוּא פְּסלֶת הַפְּרִי הֲרֵי זֶה לוֹקֶה. אֲבָל הֶעָלִין וְהַלּוּלָבִים וּמֵי גְּפָנִים וְהַסְּמָדַר הֲרֵי אֵלּוּ מֻתָּרִין לְנָזִיר שֶׁאֵינָן לֹא פְּרִי וְלֹא פְּסלֶת פְּרִי אֶלָּא מִן הָעֵץ הֵן נֶחְשָׁבִין:","כָּל אִסּוּרֵי גֶפֶן מִצְטָרְפִין זֶה עִם זֶה. כֵּיצַד. הֲרֵי שֶׁצֵּרֵף עֲנָבִים לַחִים עִם יְבֵשִׁים אוֹ עִם בֹּסֶר וְחַרְצָן וְזָג וְאָכַל מִן הַתַּעֲרֹבֶת כְּזַיִת לוֹקֶה. וְכֵן אִם אָכְלָם זֶה אַחַר זֶה עַד שֶׁאָכַל מִן הַכּל כְּזַיִת לוֹקֶה. וְכֵן אִם שָׁתָה רְבִיעִית תַּעֲרֹבֶת יַיִן וְחֹמֶץ לוֹקֶה:","דָּבָר הַמֻּתָּר אֵינוֹ מִצְטָרֵף לְדָבָר הָאָסוּר בְּנָזִיר. כֵּיצַד. יַיִן שֶׁנִּתְעָרֵב בִּדְבַשׁ אַף עַל פִּי שֶׁטַּעַם הַכּל טַעַם יַיִן וְשָׁתָה מִן הַתַּעֲרֹבֶת. וְכֵן הַצִּמּוּקִין שֶׁדְּרָסָן עִם הַגְּרוֹגָרוֹת וְטַעַם הַכּל טַעַם צִמּוּקִין וְאָכַל מִן הַתַּעֲרֹבֶת אֵינוֹ לוֹקֶה. עַד שֶׁיִּהְיֶה מִדָּבָר הָאָסוּר בַּתַּעֲרֹבֶת כְּזַיִת בִּכְדֵי שָׁלֹשׁ בֵּיצִים וְאָכַל כְּשָׁלֹשׁ בֵּיצִים. כִּשְׁאָר הָאִסּוּרִין הַשָּׁוִים בְּכָל אָדָם כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת מַאֲכָלוֹת אֲסוּרוֹת:","וְכֵן אִם שָׁרָה פִּתּוֹ בְּיַיִן וְהָיָה הָרְבִיעִית יַיִן בִּכְדֵי פְּרָס מִן הַפַּת וְאָכַל כְּדֵי פְּרָס שֶׁנִּמְצָא שֶׁאָכַל רְבִיעִית יַיִן הֲרֵי זֶה לוֹקֶה. וְעַל זֶה וְכַיּוֹצֵא בּוֹ נֶאֱמַר בַּתּוֹרָה (במדבר ו ג) \"וְכָל מִשְׁרַת עֲנָבִים\". לֶאֱסֹר דָּבָר שֶׁנִּתְעָרֵב בּוֹ הַיַּיִן וְטַעְמוֹ כְּטַעַם הַיַּיִן וְהוּא שֶׁיִּהְיֶה טַעֲמוֹ וּמַמָּשׁוֹ כִּשְׁאָר אִסּוּרֵי מַאֲכָלוֹת:","נִתְעָרֵב יַיִן וְכַיּוֹצֵא בּוֹ בִּדְבַשׁ וְאֵין שָׁם טַעַם יַיִן הֲרֵי זֶה מֻתָּר לְנָזִיר. לֹא יִהְיֶה זֶה חָמוּר מֵחֵלֶב וְדָם:","הָיָה בּוֹ טַעַם יַיִן וְאֵין שָׁם רְבִיעִית בִּכְדֵי אֲכִילַת פְּרָס הֲרֵי זֶה אָסוּר מִדִּבְרֵי סוֹפְרִים כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת מַאֲכָלוֹת אֲסוּרוֹת. וּמַכִּין אוֹתוֹ אִם אָכַל מַכַּת מַרְדּוּת:","נָזִיר שֶׁאָכַל כְּזַיִת עֲנָבִים וּכְזַיִת חַרְצָן וּכְזַיִת זָג וּכְזַיִת צִמּוּקִים וְשָׁתָה רְבִיעִית יַיִן וַאֲפִלּוּ סָחַט אֶשְׁכּוֹל וְשָׁתָה מִמֶּנּוּ רְבִיעִית הֲרֵי זֶה לוֹקֶה חָמֵשׁ מַלְקִיּוֹת. שֶׁכָּל אֶחָד מֵהֶן בְּלָאו אֶחָד הוּא. וְלוֹקֶה מַלְקוּת שִׁשִּׁית מִשּׁוּם (במדבר ל ג) \"לֹא יַחֵל דְּבָרוֹ\" שֶׁהוּא שָׁוֶה בְּכָל הַנְּדָרִים. וְכֵן אִם אָכַל כְּזַיִת זָג אוֹ כְּזַיִת עֲנָבִים לוֹקֶה שְׁתַּיִם אַחַת מִשּׁוּם זָג אוֹ מִשּׁוּם עֲנָבִים וְאַחַת מִשּׁוּם לֹא יַחֵל דְּבָרוֹ. וְהוּא הַדִּין לְנָזִיר שֶׁגִּלֵּחַ אוֹ נִטְמָא שֶׁהוּא לוֹקֶה שְׁתַּיִם. אַחַת עַל הָאִסּוּר הַמְיֻחָד בּוֹ וְאַחַת עַל הָאִסּוּר הַשָּׁוֶה בְּכָל הַנְּדָרִים שֶׁהוּא לֹא יַחֵל דְּבָרוֹ:","נָזִיר שֶׁשָּׁתָה רְבִיעִית יַיִן וּרְבִיעִית חֹמֶץ אֵינוֹ לוֹקֶה אֶלָּא אַחַת שֶׁאֵינוֹ חַיָּב עַל הַיַּיִן בִּפְנֵי עַצְמוֹ וְעַל הַחֹמֶץ בִּפְנֵי עַצְמוֹ. שֶׁאֵין כָּתוּב יַיִן לֹא יִשְׁתֶּה וְחֹמֶץ לֹא יִשְׁתֶּה אֶלָּא כָּךְ חֹמֶץ יַיִן וְחֹמֶץ שֵׁכָר לֹא יִשְׁתֶּה כְּלוֹמַר לֹא יִשְׁתֶּה יַיִן וְלֹא דָּבָר שֶׁנִּתְעָרֵב בּוֹ הַיַּיִן וְהוּא הַשֵּׁכָר וַאֲפִלּוּ הֶחְמִיצוּ וְהוֹאִיל וְלֹא כָּפַל אֶלָּא הַחֹמֶץ שֶׁהוּא שֵׁם אֶחָד אֵינוֹ לוֹקֶה עַל זֶה בִּפְנֵי עַצְמוֹ וְעַל זֶה בִּפְנֵי עַצְמוֹ:","נָזִיר שֶׁהָיָה שׁוֹתֶה בְּיַיִן כָּל הַיּוֹם כֻּלּוֹ אַף עַל פִּי שֶׁהוּא חַיָּב לַשָּׁמַיִם עַל כָּל רְבִיעִית וּרְבִיעִית אֵינוֹ לוֹקֶה אֶלָּא אַחַת מִשּׁוּם (במדבר ו ד) \"יַיִן\" וְאַחַת דְּ (במדבר ל ג) \"לָא יַחֵל דְּבָרוֹ\" כְּמוֹ שֶׁבֵּאַרְנוּ. וְאִם הִתְרוּ בּוֹ עַל כָּל רְבִיעִית וּרְבִיעִית וְאָמְרוּ לוֹ אַל תִּשְׁתֶּה אַל תִּשְׁתֶּה וְהוּא שׁוֹתֶה חַיָּב עַל כָּל אֶחָד וְאֶחָד. מִדִּבְרֵי סוֹפְרִים שֶׁאָסוּר לְנָזִיר לַעֲמֹד בְּמוֹשַׁב שׁוֹתֵי יַיִן וְיִתְרַחֵק מִמֶּנּוּ הַרְבֵּה שֶׁהֲרֵי מִכְשׁוֹל לְפָנָיו. אָמְרוּ חֲכָמִים סָבִיב לַכֶּרֶם לֹא יִקְרַב:","נָזִיר שֶׁגִּלֵּחַ שְׂעָרָה אַחַת לוֹקֶה בֵּין בְּתַעַר בֵּין בְּזוּג וְהוּא שֶׁקִּצְּצָה מֵעִקָּרָהּ כְּעֵין תַּעַר. וְכֵן אִם תְּלָשָׁהּ בְּיָדוֹ לוֹקֶה. אֶחָד הַמְגַלֵּחַ וְאֶחָד הַמִּתְגַּלֵּחַ שֶׁנֶּאֱמַר (במדבר ו ה) \"תַּעַר לֹא יַעֲבֹר עַל רֹאשׁוֹ\". וְאִם הִנִּיחַ מִמֶּנּוּ כְּדֵי לָכֹף רֹאשָׁהּ לְעִקָּרָהּ אֵינוֹ לוֹקֶה שֶׁאֵין זֶה כְּעֵין תַּעַר:","הֶעֱבִיר עַל רֹאשׁוֹ סַם שֶׁמַּשִּׁיר אֶת הַשֵּׂעָר וְהִשִּׁיר אֶת הַשֵּׂעָר אֵינוֹ לוֹקֶה אֶלָּא בִּטֵּל מִצְוַת עֲשֵׂה שֶׁנֶּאֱמַר (במדבר ו ה) \"גַּדֵּל פֶּרַע שְׂעַר רֹאשׁוֹ\":","נָזִיר שֶׁגִּלֵּחַ כָּל רֹאשׁוֹ אֵינוֹ לוֹקֶה מִשּׁוּם הַתִּגְלַחַת אֶלָּא אַחַת. וְאִם הִתְרוּ בּוֹ עַל כָּל שֵׂעָר וְשֵׂעָר וְאָמְרוּ לוֹ אַל תְּגַלֵּחַ אַל תְּגַלֵּחַ וְהוּא מְגַלֵּחַ לוֹקֶה עַל כָּל אַחַת וְאַחַת:","נָזִיר חוֹפֵף עַל שְׂעָרוֹ בְּיָדוֹ וְחוֹכֵךְ בְּצִפָּרְנָיו וְאִם נָפַל שֵׂעָר אֵינוֹ חוֹשֵׁשׁ שֶׁהֲרֵי אֵין כַּוָּנָתוֹ לְהַשִּׁיר וְאֶפְשָׁר שֶׁלֹּא יַשִּׁיר. אֲבָל לֹא יִסְרֹק בְּמַסְרֵק וְלֹא יָחֹף בַּאֲדָמָה מִפְּנֵי שֶׁמַּשֶּׁרֶת אֶת הַשֵּׂעָר וַדַּאי. וְאִם עָשָׂה כֵן אֵינוֹ לוֹקֶה:","נָזִיר שֶׁנִּטְמָא לְמֵת טֻמְאַת שִׁבְעָה. בֵּין בְּטֻמְאוֹת שֶׁהוּא מְגַלֵּחַ עֲלֵיהֶן כְּמוֹ שֶׁיִּתְבָּאֵר בֵּין בְּטֻמְאוֹת שֶׁאֵינוֹ מְגַלֵּחַ עֲלֵיהֶן. הֲרֵי זֶה לוֹקֶה:","נִטְמָא לְמֵת פְּעָמִים הַרְבֵּה אַף עַל פִּי שֶׁהוּא חַיָּב מַלְקוֹת עַל כָּל אַחַת וְאַחַת לַשָּׁמַיִם אֵין בֵּית דִּין מַלְקִין אוֹתוֹ אֶלָּא אַחַת. וְאִם הִתְרוּ בּוֹ עַל כָּל פַּעַם וּפַעַם וְהוּא מִטַּמֵּא לוֹקֶה [עַל] כָּל אַחַת וְאַחַת:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁנִּטְמָא וּפֵרַשׁ וְחָזַר וְנָגַע אוֹ נָשָׂא אוֹ הֶאֱהִיל. אֲבָל אִם הָיָה נוֹגֵעַ בְּמֵת וַעֲדַיִן הַמֵּת בְּיָדוֹ וְנָגַע בְּמֵת אַחֵר אֵינוֹ חַיָּב אֶלָּא אַחַת אַף עַל פִּי שֶׁהִתְרוּ בּוֹ עַל כָּל נְגִיעָה וּנְגִיעָה שֶׁהֲרֵי מְחֻלָּל וְעוֹמֵד:","נָזִיר שֶׁנִּכְנַס לְבַיִת וְשָׁהָה שָׁם עַד שֶׁמֵּת שָׁם הַמֵּת. אוֹ שֶׁנִּכְנַס לְאֹהֶל הַמֵּת בְּשִׁדָּה תֵּבָה וּמִגְדָּל וּבָא חֲבֵרוֹ וּפָרַע גַּג הַתֵּבָה מֵעָלָיו מִדַּעְתּוֹ. הֲרֵי זֶה לוֹקֶה שְׁתַּיִם אַחַת מִשּׁוּם (במדבר ו ו) \"לֹא יָבֹא\" וְאַחַת מִשּׁוּם (במדבר ו ז) \"לֹא יִטַּמָּא\". שֶׁהֲרֵי טֻמְאָה וּבִיאָה בָּאִין כְּאַחַת. אֲבָל אִם נִכְנַס כְּדַרְכּוֹ טֻמְאָתוֹ קוֹדֶמֶת לְבִיאָתוֹ שֶׁמֵּעֵת שֶׁיַּכְנִיס חָטְמוֹ אוֹ אֶצְבְּעוֹת רַגְלָיו נִטְמָא וְאֵינוֹ חַיָּב מִשּׁוּם בִּיאָה עַד שֶׁיָּבוֹא כֻּלּוֹ:","נִכְנַס לְאֹהֶל הַמֵּת אוֹ לְבֵית הַקְּבָרוֹת בִּשְׁגָגָה. וְאַחַר שֶׁנּוֹדַע לוֹ הִתְרוּ בּוֹ וְלֹא קָפַץ וְיָצָא אֶלָּא עָמַד שָׁם הֲרֵי זֶה לוֹקֶה. וְהוּא שֶׁיִּשְׁהֶא שָׁם כְּדֵי הִשְׁתַּחֲוָיָה כְּמוֹ טָמֵא שֶׁנִּכְנַס לַמִּקְדָּשׁ:","הַמְטַמֵּא אֶת הַנָּזִיר. אִם הָיָה הַנָּזִיר מֵזִיד הַנָּזִיר לוֹקֶה וְזֶה שֶׁטִּמְּאוֹ עוֹבֵר מִשּׁוּם (ויקרא יט יד) \"וְלִפְנֵי עִוֵּר לֹא תִתֵּן מִכְשׁל\". וְאִם הָיָה הַנָּזִיר שׁוֹגֵג וְזֶה שֶׁטִּמְּאוֹ מֵזִיד אֵין אֶחָד מֵהֶם לוֹקֶה. וְלָמָּה לֹא יִלְקֶה הַמְטַמֵּא אֶת הַנָּזִיר. לְפִי שֶׁנֶּאֱמַר (במדבר ו ט) \"וְטִמֵּא אֶת רֹאשׁ נִזְרוֹ\" אֵינוֹ לוֹקֶה עַד שֶׁיְּטַמֵּא עַצְמוֹ מִדַּעְתּוֹ:","נָזִיר טָהוֹר שֶׁטִּמֵּא עַצְמוֹ לוֹקֶה אַף מִשּׁוּם (דברים כג כב) \"לֹא תְאַחֵר לְשַׁלְּמוֹ\". שֶׁהֲרֵי אִחֵר נְזִירוּת טָהֳרָה וְעָשָׂה מַעֲשֶׂה. וְכֵן אִם נָדַר בְּבֵית הַקְּבָרוֹת לוֹקֶה אַף מִשּׁוּם לֹא תְאַחֵר. הָא לָמַדְתָּ שֶׁהַנָּזִיר שֶׁטִּמֵּא עַצְמוֹ לוֹקֶה אַרְבַּע מַלְקִיּוֹת מִשּׁוּם (במדבר ו ז) \"לֹא יִטַּמָּא\" וּמִשּׁוּם (במדבר ל ג) \"לֹא יַחֵל דְּבָרוֹ\" וּמִשּׁוּם לֹא תְאַחֵר לְשַׁלְּמוֹ וּמִשּׁוּם (במדבר ו ו) \"לֹא יָבֹא\" אִם הָיְתָה בִּיאָה וְטֻמְאָה כְּאַחַת כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Negative Mitzvot 105":["שלא ייתן עליו לבונה, שנאמר \"ולא ייתן עליו לבונה\" (במדבר ה,טו)."],"Mishneh Torah, Negative Mitzvot 116":["שלא להניח אימורי הפסח עד שיפסלו בלינה, שנאמר \"ולא ילין חלב חגי, עד בוקר\" (שמות כג,יח)."],"Mishneh Torah, Negative Mitzvot 127":["שלא יאכל הערל בשר הפסח, שנאמר \"כל ערל, לא יאכל בו\" (שמות יב,מח)."],"Mishneh Torah, Negative Mitzvot 138":["שלא תיאכל מנחת כוהן, שנאמר \"וכל מנחת כוהן כליל תהיה, לא תיאכל\" (ויקרא ו,טז)."],"Mishneh Torah, Negative Mitzvot 149":["שלא יאכל כוהן ביכורים קודם הנחה בעזרה, שנאמר \"לא תוכל . . . ותרומת ידך\" (דברים יב,יז); אלו הביכורים."],"Mishneh Torah, Negative Mitzvot 16":["שלא להסית אדם מישראל אחר עבודה זרה, שנאמר במסית \"ולא יוסיפו לעשות\" (דברים יג,יב)."],"Mishneh Torah, Negative Mitzvot 170":["שלא ייקח כל שבט לוי חלק בביזה בשעת כיבוש הארץ, שנאמר \"לא יהיה לכוהנים הלויים . . . חלק ונחלה\" (דברים יח,א)."],"Mishneh Torah, Negative Mitzvot 181":["שלא לאכול טריפה, שנאמר \"ובשר בשדה טריפה לא תאכלו\" (שמות כב,ל)."],"Mishneh Torah, Negative Mitzvot 192":["שלא לאכול עורלה, שנאמר \"שלוש שנים, יהיה לכם ערלים--לא ייאכל\" (ויקרא יט,כג)."],"Mishneh Torah, Negative Mitzvot 202":["שלא ישתה הנזיר יין, ולא דבר שנתערב בו יין וטעמו כטעם יין, שנאמר \"וכל משרת ענבים\" (במדבר ו,ג); ואפילו החמיץ היין או דבר שנתערב בו היין, הרי זה אסור עליו, שנאמר \"חומץ יין וחומץ שיכר לא ישתה\" (שם)."],"Mishneh Torah, Negative Mitzvot 213":["שלא ללקוט פרט הכרם, שנאמר \"ופרט כרמך לא תלקט\" (ויקרא יט,י)."],"Mishneh Torah, Negative Mitzvot 224":["שלא לעבוד בשנת יובל בין אדמה בין אילן, שנאמר בה \"לא תזרעו\" (ויקרא כה,יא)."],"Mishneh Torah, Negative Mitzvot 235":["שלא להלוות בריבית לישראל, שנאמר \"את כספך--לא תיתן לו, בנשך\" (ויקרא כה,לז)."],"Mishneh Torah, Negative Mitzvot 246":["שלא להסיג גבול, שנאמר \"לא תסיג גבול ריעך\" (דברים יט,יד)."],"Mishneh Torah, Negative Mitzvot 257":["שלא לעבוד בעבד עברי כעבודת עבד, שנאמר \"לֹא תַעֲבֹד בּוֹ עֲבוֹדַת עָבֶד\" (ויקרא כה, לט)."],"Mishneh Torah, Negative Mitzvot 268":["שלא ייקח השכיר יתר על אכילתו, שנאמר \"וְאָכַלְתָּ עֲנָבִים כְּנַפְשְׁךָ שָׂבְעֶךָ\" (דברים כג, כה)."],"Mishneh Torah, Negative Mitzvot 279":["שלא לרחם על המזיק בדיני קנסות, שנאמר \"לֹא תָחוֹס עֵינְךָ\" (דברים יט, כא)."],"Mishneh Torah, Negative Mitzvot 29":["שלא נימנע מהריגת נביא השקר ולא נירא ממנו, שנאמר \"לא תגור ממנו\" (דברים יח,כב)."],"Mishneh Torah, Negative Mitzvot 30":["שלא ללכת בחוקות עובדי עבודה זרה ולא במנהגותם, שנאמר \"ולא תלכו בחוקות הגוי\" (ויקרא כ,כג)."],"Mishneh Torah, Negative Mitzvot 310":["שלא להחיות מכשף, שנאמר \"מכשפה, לא תחייה\" (שמות כב,יז)."],"Mishneh Torah, Negative Mitzvot 321":["שלא להלך חוץ לתחום מדינה כהולכי דרכים בשבת, שנאמר \"אל ייצא איש ממקומו\" (שמות טז,כט)."],"Mishneh Torah, Negative Mitzvot 332":["שלא לגלות ערוות אחות, שנאמר \"ערוות אחותך . . . לא תגלה\" (ויקרא יח,ט)."],"Mishneh Torah, Negative Mitzvot 343":["שלא לגלות ערוות אשת הבן, שנאמר \"ערוות כלתך, לא תגלה\" (ויקרא יח,טו)."],"Mishneh Torah, Negative Mitzvot 354":["שלא יישא ממזר בת ישראל, שנאמר \"לא יבוא ממזר, בקהל ה'\" (דברים כג,ג)."],"Mishneh Torah, Negative Mitzvot 365":["שלא ירבה לו המלך כסף וזהב, שנאמר \"וכסף וזהב, לא ירבה לו מאוד\" (דברים יז,יז)."],"Mishneh Torah, Negative Mitzvot 47":["שלא לתור אחר מחשבות הלב וראיית העיניים, שנאמר \"ולא תתורו . . .\" (במדבר טו,לט)."],"Mishneh Torah, Negative Mitzvot 58":["שלא ייראו אנשי המלחמה ולא יפחדו מאויביהם בשעת מלחמה, שנאמר \"לא תערוץ, מפניהם\" (דברים ז,כא), \"לא, תיראום\" (דברים ג,כב)."],"Mishneh Torah, Negative Mitzvot 69":["שלא יכנס בעל מום מן המזבח ולפנים, שנאמר \"אַךְ אֶל הַפָּרֹכֶת לֹא יָבֹא\" (ויקרא כא, כג)."],"Mishneh Torah, Negative Mitzvot 8":["שלא לעשות מעשה אוב, שנאמר \"אל תפנו אל האובות\" (ויקרא יט,לא)."],"Mishneh Torah, Negative Mitzvot 90":["שלא לשחוט קודשים בחוץ, שנאמר \"איש . . . אשר ישחט שור או כשב\" (ויקרא יז,ג) \"ואל פתח אוהל מועד, לא הביאו . . . ונכרת\" (ויקרא יז,ד)."],"Mishneh Torah, Neighbors 11":["מִי שֶׁעָשָׂה גֹּרֶן בְּתוֹךְ שֶׁלּוֹ. אוֹ קָבַע בֵּית הַכִּסֵּא. אוֹ מְלָאכָה שֶׁיֵּשׁ בָּהּ אָבָק וְעָפָר וְכַיּוֹצֵא בָּהֶן. צָרִיךְ לְהַרְחִיק כְּדֵי שֶׁלֹּא יַגִּיעַ הֶעָפָר אוֹ רֵיחַ בֵּית הַכִּסֵּא אוֹ הָאָבָק לַחֲבֵרוֹ כְּדֵי שֶׁלֹּא יַזִּיקוֹ. אֲפִלּוּ הָיְתָה הָרוּחַ הוּא שֶׁמְּסַיֵּעַ אוֹתוֹ בְּעֵת שֶׁעוֹשֶׂה מְלַאכְתּוֹ וּמוֹלִיכָה אֶת הֶעָפָר אוֹ נְעֹרֶת הַפִּשְׁתָּן וְהַמּוֹץ וְכַיּוֹצֵא בָּהֶן וּמַגִּיעָתָן לַחֲבֵרוֹ הֲרֵי זֶה חַיָּב לְהַרְחִיק כְּדֵי שֶׁלֹּא יַגִּיעוּ וְלֹא יַזִּיקוּ. וַאֲפִלּוּ עַל יְדֵי הָרוּחַ מְצוּיָה שֶׁכָּל אֵלּוּ כְּמִי שֶׁהִזִּיקוּ בְּחִצָּיו הֵן:","אַף עַל פִּי שֶׁהוּא חַיָּב לְהַרְחִיק כָּל כָּךְ אִם הוֹלִיכָה הָרוּחַ הַמְצוּיָה הַמּוֹץ וְאֶת הֶעָפָר וְהִזִּיקָה בָּהֶן פָּטוּר מִלְּשַׁלֵּם שֶׁהָרוּחַ הוּא שֶׁסִּיֵּעַ אוֹתוֹ וְאֵין נֵזֶק זֶה בָּא מִכֹּחַ מַזִּיק עַצְמוֹ:","הַכּוֹתֵשׁ אֶת הָרִיפוֹת וְכַיּוֹצֵא בָּהֶן בְּתוֹךְ שֶׁלּוֹ וּבְעֵת שֶׁמַּכֶּה מְנַדְנֵד לַחֲצַר חֲבֵרוֹ עַד שֶׁנִּדְנְדָה כִּסּוּי הֶחָבִית עַל פִּי הֶחָבִית הֲרֵי זֶה מַזִּיק בְּחִצָּיו וְחַיָּב לְהַרְחִיק כְּדֵי שֶׁלֹּא יִנְדֹּד אוֹ יְבַטֵּל מְלַאכְתּוֹ שֶׁמַּזֶּקֶת. וְאִם הִזִּיק בְּעֵת הַנִּדְנוּד חַיָּב לְשַׁלֵּם שֶׁהֲרֵי מִכֹּחוֹ בָּא הַנֵּזֶק:","כָּל הַהַרְחָקוֹת הָאֲמוּרוֹת בַּפְּרָקִים שֶׁל מַעְלָה אִם לֹא הִרְחִיק וְרָאָה חֲבֵרוֹ וְשָׁתַק הֲרֵי זֶה מָחַל וְאֵינוֹ יָכוֹל לַחְזֹר וּלְהַצְרִיכוֹ וּלְהַרְחִיקוֹ. וְהוּא שֶׁיֵּרָאֶה מִמֶּנּוּ שֶׁמָּחַל כְּגוֹן שֶׁסִּיֵּעַ עִמּוֹ מִיָּד אוֹ שֶׁאָמַר לוֹ לַעֲשׂוֹת אוֹ שֶׁרָאָהוּ שֶׁעָשָׂה בְּצִדּוֹ בְּלֹא הַרְחָקָה וְשָׁתַק וְלֹא הִקְפִּיד עַל זֶה זָכָה. שֶׁכָּל הַמַּחֲזִיק בְּנֵזֶק זָכָה בּוֹ כְּמוֹ שֶׁבֵּאַרְנוּ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהֶחְזִיק בִּשְׁאָר נְזָקִין חוּץ מֵאַרְבָּעָה מִינֵי נְזָקִין אֵלּוּ הָאֲמוּרִים בְּפֶרֶק זֶה שֶׁהֵן הֶעָשָׁן וְרֵיחַ בֵּית הַכִּסֵּא וְהֶאָבָק וְכַיּוֹצֵא בּוֹ וְנִדְנוּד הַקַּרְקַע. שֶׁכָּל אֶחָד מֵאֵלּוּ אֵין לוֹ חֲזָקָה. וַאֲפִלּוּ שָׁתַק הַנִּזָּק כַּמָּה שָׁנִים הֲרֵי זֶה חוֹזֵר וְכוֹפֵהוּ לְהַרְחִיק. וְכֵן הֶזֵּק רְאִיָּה בְּמָקוֹם שֶׁצָּרִיךְ מְחִצָּה כּוֹפֵהוּ לַעֲשׂוֹת מְחִצָּה בְּכָל עֵת שֶׁיִּרְצֶה כְּמוֹ שֶׁבֵּאַרְנוּ. וְלָמָּה שִׁנּוּ נְזָקִים אֵלּוּ מִשְּׁאָר נְזָקִין לְפִי שֶׁאֵין דַּעְתּוֹ שֶׁל אָדָם סוֹבֶלֶת נֵזֶק מֵאֵלּוּ וְחֶזְקָתוֹ שֶׁאֵינוֹ מוֹחֵל שֶׁהֶזֵּקוֹ הֶזֵּק קָבוּעַ. וְאִם קָנוּ מִיָּדוֹ שֶׁמָּחַל בִּנְזָקִים אֵלּוּ אֵינוֹ יָכוֹל לַחְזֹר בּוֹ:","מִי שֶׁהֶחְזִיק לַעֲשׂוֹת מְלֶאכֶת דָּם אוֹ נְבֵלוֹת וְכַיּוֹצֵא בָּהֶן בִּמְקוֹמָן וְיָבוֹאוּ הָעוֹרְבִים וְכַיּוֹצֵא בָּהֶן בִּגְלַל הַדָּם וְיֹאכְלוּ וַהֲרֵי הֵן מְצֵרִין לַחֲבֵרוֹ בְּקוֹלָם וְצִפְצוּפָם אוֹ בַּדָּם שֶׁבְּרַגְלֵיהֶם שֶׁהֵן יוֹשְׁבִין עַל הָאִילָנוֹת וּמְלַכְלְכִין פֵּרוֹתֵיהֶם. אִם הָיָה חֲבֵרוֹ קַפְּדָן אוֹ חוֹלֶה שֶׁצִּפְצוּף הַזֶּה מַזִּיקוֹ אוֹ שֶׁפֵּרוֹת שֶׁלּוֹ נִפְסָדִין לוֹ בַּדָּם חַיָּב לְבַטֵּל אוֹתָהּ הַמְּלָאכָה אוֹ יַרְחִיק עַד שֶׁלֹּא יָבוֹא לוֹ הֶזֵּק מֵחֲמָתוֹ. שֶׁהֶזֵּק זֶה דּוֹמֶה לְרֵיחַ בֵּית הַכִּסֵּא וְכַיּוֹצֵא בּוֹ שֶׁאֵין לוֹ חֲזָקָה. וְכֵן בְּנֵי מָבוֹי אוֹ בְּנֵי חָצֵר שֶׁנַּעֲשָׂה אֶחָד מֵהֶן אֻמָּן וְלֹא מִחוּ בּוֹ שֶׁהֲרֵי הֻחְזַק וְהָיוּ הָעָם נִכְנָסִין וְיוֹצְאִין לִקְנוֹת וְשָׁתְקוּ לֹא הֶחֱזִיק בְּדָבָר זֶה וְיֵשׁ לָהֶם בְּכָל עֵת לְעַכֵּב וְלוֹמַר אֵין אָנוּ יְכוֹלִין לִישֹׁן מִקּוֹל הַנִּכְנָסִין וְהַיּוֹצְאִין שֶׁזֶּה הֶזֵּק קָבוּעַ הוּא כְּמוֹ הֶעָשָׁן וְהֶאָבָק. וְכָזֶה הוֹרוּ הַגְּאוֹנִים:","מִי שֶׁהֶחְזִיק בְּנֵזֶק שֶׁיֵּשׁ לוֹ חֲזָקָה כְּגוֹן שֶׁפָּתַח חַלּוֹן אוֹ הֶעֱבִיר אַמַּת הַמַּיִם אוֹ שֶׁלֹּא הִרְחִיק מַה שֶּׁרָאוּי לְהַרְחִיק וַהֲרֵי הַמַּחֲזִיק טוֹעֵן אַתָּה אָמַרְתָּ לִי לַעֲשׂוֹת אוֹ מָחַלְתָּ לִי אַחַר שֶׁרָאִיתָ אוֹ הֻכַּר הַנֵּזֶק וְשָׁתַקְתָּ וְלֹא מָחִיתָ בִּי. וְהַנִּזָּק אוֹמֵר עַכְשָׁו הוּא שֶׁרָאִיתִי וְלֹא יָדַעְתִּי מִקֹּדֶם. אוֹ שֶׁאָמַר כְּשֶׁרָאִיתִי מָחִיתִי בְּךָ וְאַתָּה אָמַרְתָּ עַתָּה אַרְחִיק אוֹ אֶסְתֹּם וְאַתָּה מַדְחֶה אוֹתִי מִיּוֹם אֶל יוֹם כְּדֵי שֶׁתִּקְבַּע הֶזֵּקְךָ. בְּכָל אֵלּוּ וְכַיּוֹצֵא בָּהֶן עַל הַנִּזָּק לְהָבִיא רְאָיָה. וְאִם לֹא הֵבִיא יִשָּׁבַע הַמַּזִּיק הֶסֵּת וְיִפָּטֵר:","הֶחֱזִיק בְּנֵזֶק שֶׁאֵין לוֹ חֲזָקָה כְּגוֹן עָשָׁן וּבֵית הַכִּסֵּא וְכַיּוֹצֵא בָּהֶן וְטָעַן הַמַּזִּיק שֶׁקָּנָה מִיָּדוֹ שֶׁל נִזָּק עַל הַמַּזִּיק לְהָבִיא רְאָיָה שֶׁקָּנוּ מִיָּדוֹ. וְאִם לֹא הֵבִיא יִשָּׁבַע הַנִּזָּק הֶסֵּת שֶׁלֹּא קָנוּ מִיָּדוֹ עַל כָּךְ וִיסַלֵּק זֶה הֶזֵּקוֹ:"],"Mishneh Torah, Oaths 1":["אַרְבָּעָה מִינֵי שְׁבוּעוֹת הֵן. שְׁבוּעַת בִּטּוּי וּשְׁבוּעַת שָׁוְא וּשְׁבוּעַת הַפִּקָּדוֹן וּשְׁבוּעַת הָעֵדוּת. שְׁבוּעַת בִּטּוּי הוּא שֶׁנֶּאֱמַר בַּתּוֹרָה (ויקרא ה ד) \"אוֹ נֶפֶשׁ כִּי תִשָּׁבַע לְבַטֵּא בִשְׂפָתַיִם לְהָרַע אוֹ לְהֵיטִיב\". וְהִיא נֶחְלֶקֶת לְאַרְבָּעָה חֲלָקִים. שְׁתַּיִם לְהַבָּא. וּשְׁתַּיִם לְשֶׁעָבַר. כְּגוֹן שֶׁנִּשְׁבַּע עַל דָּבָר שֶׁעָבַר שֶׁנַּעֲשָׂה אוֹ שֶׁלֹּא נַעֲשָׂה. וְעַל דָּבָר שֶׁעָתִיד לִהְיוֹת שֶׁיֵּעָשֶׂה וְשֶׁלֹּא יֵעָשֶׂה:","וְאֵין שְׁבוּעַת בִּטּוּי נוֹהֶגֶת אֶלָּא בִּדְבָרִים שֶׁאֶפְשָׁר לוֹ לַעֲשׂוֹתָן בֵּין לְהַבָּא בֵּין לְשֶׁעָבַר. כֵּיצַד לְשֶׁעָבַר. שֶׁאָכַלְתִּי. אוֹ שֶׁזָּרַקְתִּי אֶבֶן לַיָּם. אוֹ שֶׁדִּבֵּר פְּלוֹנִי עִם פְּלוֹנִי. אוֹ שֶׁלֹּא אָכַלְתִּי. אוֹ שֶׁלֹּא זָרַק אֶבֶן לַיָּם. אוֹ שֶׁלֹּא דִּבֵּר פְּלוֹנִי עִם פְּלוֹנִי. כֵּיצַד לְהַבָּא. שֶׁאֹכַל אוֹ שֶׁלֹּא אֹכַל. אוֹ שֶׁאֶזְרֹק אוֹ שֶׁלֹּא אֶזְרֹק אֶבֶן לַיָּם. הֲרֵי אֵלּוּ שְׁתַּיִם לְשֶׁעָבַר וּשְׁתַּיִם לְהַבָּא:","נִשְׁבַּע אַחַת מֵאַרְבַּע מַחֲלוֹקוֹת אֵלּוּ וְהֶחְלִיף כְּגוֹן שֶׁנִּשְׁבַּע שֶׁלֹּא יֹאכַל וְאָכַל אוֹ שֶׁיֹּאכַל וְלֹא אָכַל אוֹ שֶׁאָכַלְתִּי וְהוּא לֹא אָכַל שֶׁלֹּא אָכַלְתִּי וְאָכַל הֲרֵי זוֹ שְׁבוּעַת שֶׁקֶר. וְעַל זֶה וְכַיּוֹצֵא בּוֹ נֶאֱמַר (ויקרא יט יב) \"לֹא תִשָּׁבְעוּ בִשְׁמִי לַשָּׁקֶר\". וְאִם נִשְׁבַּע לַשֶּׁקֶר בְּמֵזִיד לוֹקֶה. בְּשׁוֹגֵג מֵבִיא קָרְבַּן עוֹלֶה וְיוֹרֵד שֶׁנֶּאֱמַר (ויקרא ה ד) \"וְנֶעְלַם מִמֶּנּוּ וְהוּא יָדַע וְאָשֵׁם\" וְגוֹ':","שְׁבוּעַת שָׁוְא נֶחְלֶקֶת לְאַרְבַּע מַחֲלוֹקוֹת. הָאַחַת שֶׁנִּשְׁבַּע עַל דָּבָר הַיָּדוּעַ שֶׁאֵין כֵּן. כֵּיצַד. כְּגוֹן שֶׁנִּשְׁבַּע עַל הָאִישׁ שֶׁהוּא אִשָּׁה. וְעַל הָאִשָּׁה שֶׁהוּא אִישׁ. וְעַל עַמּוּד שֶׁל שַׁיִשׁ שֶׁהוּא שֶׁל זָהָב. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַשְּׁנִיָּה שֶׁנִּשְׁבַּע עַל דָּבָר יָדוּעַ שֶׁאֵין בּוֹ סָפֵק לְאָדָם שֶׁהוּא כֵּן. כְּגוֹן שֶׁנִּשְׁבַּע עַל הַשָּׁמַיִם שֶׁהוּא שָׁמַיִם. וְעַל הָאֶבֶן זוֹ שֶׁהִיא אֶבֶן. וְעַל הַשְּׁנַיִם שֶׁהֵם שְׁנַיִם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. שֶׁזֶּה הַדָּבָר אֵין בּוֹ סָפֵק לְאָדָם שָׁלֵם כְּדֵי לְצַדֵּק הַדָּבָר בִּשְׁבוּעָה:","שְׁלִישִׁית שֶׁנִּשְׁבַּע לְבַטֵּל אֶת הַמִּצְוָה. כֵּיצַד. כְּגוֹן שֶׁנִּשְׁבַּע שֶׁלֹּא יִתְעַטֵּף בְּצִיצִית. שֶׁלֹּא יִלְבַּשׁ תְּפִלִּין. וְשֶׁלֹּא יֵשֵׁב בַּסֻּכָּה בְּחַג הַסֻּכּוֹת. וְלֹא יֹאכַל מַצָּה בְּלֵילֵי הַפֶּסַח. אוֹ שֶׁיִּתְעַנֶּה בְּשַׁבָּתוֹת וּבְיָמִים טוֹבִים. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","רְבִיעִית שֶׁנִּשְׁבַּע עַל דָּבָר שֶׁאֵין כֹּחַ בּוֹ לַעֲשׂוֹת. כֵּיצַד. כְּגוֹן שֶׁנִּשְׁבַּע שֶׁלֹּא יִישַׁן שְׁלֹשָׁה יָמִים לַיְלָה וָיוֹם רְצוּפִים. אוֹ שֶׁלֹּא יִטְעוֹם כְּלוּם שִׁבְעָה יָמִים רְצוּפִים. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. כָּל הַנִּשְׁבָּע שְׁבוּעַת שָׁוְא מֵאַרְבַּע שְׁבוּעוֹת אֵלּוּ עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (שמות כ ז) (דברים ה יא) \"לֹא תִשָּׂא אֶת שֵׁם ה' אֱלֹהֶיךָ לַשָּׁוְא\". וְאִם הָיָה מֵזִיד לוֹקֶה וְאִם הָיָה שׁוֹגֵג פָּטוּר מִכְּלוּם:","שְׁבוּעַת הַפִּקָּדוֹן כֵּיצַד. כָּל מִי שֶׁיֵּשׁ מָמוֹן חֲבֵרוֹ בְּיָדוֹ בֵּין פִּקָּדוֹן בֵּין מִלְוֶה אוֹ שֶׁגְּזָלוֹ אוֹ עֲשָׁקוֹ אוֹ מָצָא לוֹ אֲבֵדָה וְלֹא הֶחֱזִירָהּ וְכַיּוֹצֵא בָּזֶה וְתָבַע מִמֶּנּוּ מָמוֹן שֶׁיֵּשׁ לוֹ בְּיָדוֹ וְכָפַר בּוֹ הֲרֵי זֶה עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (ויקרא יט יא) \"לֹא תְכַחֲשׁוּ\" זוֹ אַזְהָרָה לִכְפִירַת מָמוֹן. וְאֵין לוֹקִין עַל לָאו זֶה. וְאִם נִשְׁבַּע לוֹ עַל שֶׁקֶר עַל מָמוֹן שֶׁכָּפַר בּוֹ הֲרֵי זֶה עוֹבֵר בְּלָאו אַחֵר וְעַל זֶה נֶאֱמַר (ויקרא יט יא) \"לֹא תְשַׁקְּרוּ אִישׁ בַּעֲמִיתוֹ\" זוֹ אַזְהָרָה לְנִשְׁבַּע עַל כְּפִירַת מָמוֹן. וּשְׁבוּעָה זוֹ הִיא הַנִּקְרֵאת שְׁבוּעַת הַפִּקָּדוֹן:","וּמַה הוּא חַיָּב עַל שְׁבוּעַת הַפִּקָּדוֹן שֶׁשִּׁקֵּר בָּהּ. מְשַׁלֵּם אֶת הַקֶּרֶן שֶׁכָּפַר בּוֹ עִם תּוֹסֶפֶת חֹמֶשׁ. וּמַקְרִיב אָשָׁם וַדַּאי בֵּין שֶׁהָיָה מֵזִיד בֵּין שֶׁהָיָה שׁוֹגֵג שֶׁנֶּאֱמַר (ויקרא ה כא) \"וְכִחֵשׁ בַּעֲמִיתוֹ בְּפִקָּדוֹן אוֹ בִתְשׂוּמֶת יָד אוֹ בְגָזֵל\" וְגוֹ' (ויקרא ה כג) \"וְהָיָה כִּי יֶחֱטָא וְאָשֵׁם\". וְלֹא נֶאֱמַר בּוֹ וְנֶעְלַם מִמֶּנּוּ, לְחַיֵּב מֵזִיד כְּשׁוֹגֵג:","וְהוּא שֶׁיָּזִיד בְּפִקָּדוֹן אוֹ בְּמָמוֹן שֶׁנִּתְחַיֵּב בּוֹ וְיָדַע בּוֹ בִּשְׁעַת שְׁבוּעָה. אֲבָל אִם שָׁגַג וְשָׁכַח שֶׁיֵּשׁ לוֹ אֶצְלוֹ מָמוֹן וְכָפַר וְנִשְׁבַּע וְאַחַר כָּךְ יָדַע הֲרֵי זֶה אָנוּס וּפָטוּר מִכְּלוּם. וְכֵן אִם לֹא יָדַע שֶׁאָסוּר לִשָּׁבַע לַשֶּׁקֶר עַל כְּפִירַת מָמוֹן הֲרֵי זֶה אָנוּס וּפָטוּר:","אִם כֵּן הֵיאַךְ הִיא שִׁגְגַת שְׁבוּעַת הַפִּקָּדוֹן. כְּגוֹן שֶׁנֶּעֱלַם מִמֶּנּוּ אִם חַיָּבִין עָלֶיהָ קָרְבָּן אִם לָאו וְיָדַע שֶׁהִיא אֲסוּרָה וְשֶׁיֵּשׁ לוֹ אֶצְלוֹ מָמוֹן זוֹ הִיא שִׁגְגָתָהּ. וּזְדוֹנָהּ שֶׁיָּדַע שֶׁחַיָּבִין עָלֶיהָ קָרְבָּן:","שְׁבוּעַת הָעֵדוּת כֵּיצַד. הָעֵדִים שֶׁיָּדְעוּ עֵדוּת מָמוֹן וּתְבָעָם בַּעַל הָעֵדוּת לְהָעִיד לוֹ וְכָפְרוּ בְּעֵדוּתָן וְלֹא הֵעִידוּ וְנִשְׁבְּעוּ שֶׁאֵינָן יוֹדְעִין לוֹ עֵדוּת זוֹ הִיא נִקְרֵאת שְׁבוּעַת הָעֵדוּת. וְחַיָּבִין עַל שְׁבוּעָה זוֹ קָרְבָּן עוֹלֶה וְיוֹרֵד בֵּין שֶׁהָיוּ מְזִידִין בֵּין שֶׁהָיוּ שׁוֹגְגִים שֶׁנֶּאֱמַר (ויקרא ה א) \"נֶפֶשׁ כִּי תֶחֱטָא וְשָׁמְעָה קוֹל אָלָה וְהוּא עֵד\" וְלֹא נֶאֱמַר בָּהּ וְנֶעְלַם, לְחַיֵּב עַל הַזָּדוֹן כִּשְׁגָגָה:","כֵּיצַד שִׁגְגַת שְׁבוּעַת הָעֵדוּת. כְּגוֹן שֶׁנֶּעֱלַם מִמֶּנּוּ שֶׁחַיָּבִין עָלֶיהָ קָרְבָּן וְיָדַע שֶׁשְּׁבוּעָה זוֹ אֲסוּרָה וְשֶׁהִיא שֶׁקֶר. וּזְדוֹנָהּ שֶׁיָּדַע שֶׁחַיָּבִין עָלֶיהָ קָרְבָּן. אֲבָל אִם לֹא יָדַע שֶׁהִיא אֲסוּרָה אוֹ שֶׁשָּׁכְחוּ הָעֵדוּת וְנִשְׁבְּעוּ וְאַחַר כָּךְ נוֹדַע לָהֶם שֶׁהֵן יוֹדְעִין לוֹ עֵדוּת וְשֶׁנִּשְׁבְּעוּ עַל שֶׁקֶר הֲרֵי אֵלּוּ אֲנוּסִין וּפְטוּרִין אַף מִן הַקָּרְבָּן:"],"Mishneh Torah, Offerings for Those with Incomplete Atonement 1":["אַרְבָעָה הֵן הַנִּקְרָאִין מְחֻסְּרֵי כַּפָּרָה. הַזָּבָה. וְהַיּוֹלֶדֶת. וְהַזָּב. וְהַמְצֹרָע. וְלָמָּה נִקְרָאוּ מְחֻסְּרֵי כַּפָּרָה שֶׁכָּל אֶחָד מֵהֶן אַף עַל פִּי שֶׁטָּהַר מִטֻּמְאָתוֹ וְטָבַל וְהֶעֱרִיב שִׁמְשׁוֹ עֲדַיִן הוּא חָסֵר וְלֹא גָּמְרָה טָהֳרָתוֹ כְּדֵי לֶאֱכל בְּקָדָשִׁים עַד שֶׁיָּבִיא קָרְבָּנוֹ. וְקֹדֶם שֶׁיָּבִיא כַּפָּרָתוֹ אָסוּר הוּא לֶאֱכל בְּקָדָשִׁים כְּמוֹ שֶׁבֵּאַרְנוּ בִּפְסוּלֵי הַמֻּקְדָּשִׁין:","גֵּר שֶׁמָּל וְטָבַל וַעֲדַיִן לֹא הֵבִיא קָרְבָּנוֹ. אַף עַל פִּי שֶׁהוּא אָסוּר לֶאֱכל בְּקָדָשִׁים עַד שֶׁיָּבִיא קָרְבָּנוֹ אֵינוֹ מִמְּחֻסְּרֵי כַּפָּרָה. שֶׁקָּרְבָּנוֹ עִכְּבוֹ לִהְיוֹת גֵּר גָּמוּר וְלִהְיוֹת כְּכָל כְּשֵׁרֵי יִשְׂרָאֵל וּמִפְּנֵי זֶה אֵינוֹ אוֹכֵל בְּקָדָשִׁים שֶׁעֲדַיִן לֹא נַעֲשָׂה כִּכְשֵׁרֵי יִשְׂרָאֵל. וְכֵיוָן שֶׁיָּבִיא קָרְבָּנוֹ וְיֵעָשֶׂה יִשְׂרָאֵל כָּשֵׁר אוֹכֵל בְּקָדָשִׁים. הֵבִיא פְּרֵדָה אַחַת בְּשַׁחֲרִית אוֹכֵל בְּקָדָשִׁים לָעֶרֶב וְיָבִיא פְּרֵדָה שְׁנִיָּה. שֶׁקָּרְבָּנוֹ שֶׁל גֵּר עוֹלַת בְּהֵמָה אוֹ שְׁנֵי בְּנֵי יוֹנָה אוֹ שְׁתֵּי תּוֹרִים וּשְׁנֵיהֶן עוֹלָה. כְּמוֹ שֶׁבֵּאַרְנוּ בְּמַעֲשֵׂה הַקָּרְבָּנוֹת:","הַזָּב וְהַזָּבָה קָרְבָּן כָּל אַחַת מֵהֶן שְׁתֵּי תּוֹרִים אוֹ שְׁנֵי בְּנֵי יוֹנָה אֶחָד עוֹלָה וְאֶחָד חַטָּאת. וְהַיּוֹלֶדֶת קָרְבָּנָהּ כֶּבֶשׂ עוֹלָה וּבֶן יוֹנָה אוֹ תּוֹר חַטָּאת. וְאִם אֵין יָדָהּ מַשֶּׂגֶת מְבִיאָה שְׁתֵּי תּוֹרִים אוֹ שְׁנֵי בְּנֵי יוֹנָה אֶחָד עוֹלָה וְאֶחָד חַטָּאת. וְהַמְצֹרָע קָרְבָּנוֹ שְׁלֹשָׁה כְּבָשִׂים אֶחָד עוֹלָה וְאֶחָד אָשָׁם. וְכִשְׂבָּה לְחַטָּאת. וְאִם אֵין יָדוֹ מַשֶּׂגֶת מֵבִיא קֵן אֶחָד עוֹלָה וְאֶחָד חַטָּאת וְכֶבֶשׂ לְאָשָׁם:","הַזָּב וְהַזָּבָה וְהַמְצֹרָע מֵבִיא כָּל אֶחָד מִשְּׁלָשְׁתָּן כַּפָּרָתוֹ בַּיּוֹם הַשְּׁמִינִי לְטָהֳרָתוֹ שֶׁכָּל אֶחָד מֵהֶן סוֹפֵר שִׁבְעָה יְמֵי טָהֳרָה וְטוֹבֵל בַּיּוֹם הַשְּׁבִיעִי וּמַעֲרִיב שִׁמְשׁוֹ וּמַקְרִיב קָרְבְּנוֹתָיו בַּיּוֹם הַשְּׁמִינִי:","הַיּוֹלֶדֶת אֵינָהּ מְבִיאָה קָרְבָּנָהּ בְּיוֹם אַרְבָּעִים לְזָכָר אוֹ בְּיוֹם שְׁמוֹנִים לִנְקֵבָה. אֶלָּא מַעֲרֶבֶת שִׁמְשָׁהּ וּמְבִיאָהּ קָרְבָּנָהּ לְמָחָר שֶׁהוּא יוֹם אַרְבָּעִים וְאֶחָד לְזָכָר וְיוֹם שְׁמוֹנִים וְאֶחָד לִנְקֵבָה וְהוּא הַיּוֹם שֶׁנֶּאֱמַר בּוֹ (ויקרא יב ו) \"וּבִמְלֹאת יְמֵי טָהֳרָהּ לְבֵן אוֹ לְבַת תָּבִיא\" וְגוֹ'. וְאִם הֵבִיאָה קָרְבָּנָהּ תּוֹךְ יְמֵי מְלֹאת לֹא יָצָאת אֲפִלּוּ הֵבִיאָה עַל וְלָדוֹת הָרִאשׁוֹנִים בְּתוֹךְ יְמֵי מְלֹאת שֶׁל וָלָד זֶה לֹא יָצָאת. עָבְרוּ יָמִים אֵלּוּ וְלֹא הֵבִיאוּ כַּפָּרָתָן הֲרֵי אֵלּוּ מַקְרִיבִין כַּפָּרָתָן לְאַחַר זְמַן. וְכָל זְמַן שֶׁלֹּא הִקְרִיבוּ חַטָּאתָם אֲסוּרִים לֶאֱכל בְּקָדָשִׁים. אֲבָל הָעוֹלָה (וְהָאָשָׁם) אֵינָן מְעַכְּבִין. כְּבָר בֵּאַרְנוּ בְּמַעֲשֵׂה הַקָּרְבָּנוֹת שֶׁכָּל מְחֻיְּבֵי קָרְבָּן אֵין מַקְרִיבִין עַל יָדָן אֶלָּא מִדַּעְתָּן. חוּץ מִמְּחֻסְּרֵי כַּפָּרָה שֶׁאֵין צְרִיכִין דַּעַת בְּעָלִים שֶׁהֲרֵי אָדָם מֵבִיא קָרְבָּן עַל בָּנָיו וּבְנוֹתָיו הַקְּטַנִּים אִם הָיוּ מְחֻסְּרֵי כַּפָּרָה וּמַאֲכִילָן בִּזְבָחִים:","אֵי זוֹ הִיא זָבָה. זוֹ שֶׁזָּב דָּמָהּ שְׁלֹשָׁה יָמִים זֶה אַחַר זֶה בְּלֹא עֵת נִדָּתָהּ. וְזוֹ הִיא זָבָה גְּדוֹלָה שֶׁצְּרִיכָה סְפִירַת שִׁבְעָה וְחַיֶּבֶת בְּקָרְבָּן. וּכְבָר בֵּאַרְנוּ בְּעִנְיַן הַנִּדָּה אֵימָתַי תִּהְיֶה הָאִשָּׁה זָבָה בְּדָמִים שֶׁתִּרְאֶה וְאֵימָתַי לֹא תִּהְיֶה זָבָה אֶלָּא נִדָּה אוֹ טְהוֹרָה וּמָתַי תִּהְיֶה סְפֵק זָבָה. כָּל מָקוֹם שֶׁאָמַרְנוּ שֶׁהִיא זָבָה וְסוֹפֶרֶת שִׁבְעָה הֲרֵי הִיא חַיֶּבֶת לְהָבִיא קָרְבָּן וְחַטָּאתָהּ נֶאֱכֶלֶת. וְכָל מָקוֹם שֶׁאָמַרְנוּ שֶׁהִיא סְפֵק זָבָה הֲרֵי זוֹ מְבִיאָה קָרְבָּן וְאֵין חַטָּאתָה נֶאֱכֶלֶת. שֶׁכְּבָר בֵּאַרְנוּ שֶׁחַטַּאת הָעוֹף הַבָּאָה עַל הַסָּפֵק תִּשָּׂרֵף. וְשָׁם בֵּאַרְנוּ מַה תֵּלֵד הָאִשָּׁה אוֹ מַה תַּפִּיל וְתִהְיֶה טְמֵאָה לֵידָה וּמַה תֵּלֵד אוֹ תַּפִּיל וְלֹא תִּהְיֶה טְמֵאָה לֵידָה. וְכָל מָקוֹם שֶׁאָמַרְנוּ שֶׁהִיא טְמֵאָה לֵידָה הֲרֵי זוֹ מְבִיאָה קָרְבָּן וְחַטָּאתָהּ נֶאֱכֶלֶת. וְכָל מָקוֹם שֶׁאָמַרְנוּ שֶׁאֵינָהּ טְמֵאָה לֵידָה הֲרֵי זוֹ פְּטוּרָה מִן הַקָּרְבָּן:","הָאִשָּׁה שֶׁלֹּא הֻחְזְקָה עֵבָּרָה וְהִפִּילָה וְלֹא יָדְעָה מַה הִפִּילָה. אִם נֵפֶל שֶׁחַיֶּבֶת עָלָיו קָרְבָּן אוֹ דָּבָר שֶׁאֵינָהּ חַיֶּבֶת עָלָיו קָרְבָּן. הֲרֵי זוֹ סְפֵק יוֹלֶדֶת וּמְבִיאָהּ קָרְבָּן וְאֵין חַטָּאתָה נֶאֱכֶלֶת. וְכֵן שְׁתֵּי נָשִׁים שֶׁהִפִּילוּ שְׁנֵי נְפָלִים נֵפֶל אֶחָד רָאוּי לְהַקְרִיב עָלָיו וְהַנֵּפֶל הָאַחֵר פְּטוּרָה עָלָיו וְאֵין אַחַת מֵהֶן מַכֶּרֶת נִפְלָהּ. כָּל אַחַת מִשְּׁתֵּיהֶן מְבִיאָה קָרְבָּן מִסָּפֵק וְאֵין חַטַּאת אַחַת מִשְּׁתֵּיהֶן נֶאֱכֶלֶת שֶׁחַטַּאת הָעוֹף הַבָּאָה עַל הַסָּפֵק נִשְׂרֶפֶת שֶׁמָּא אֵינָהּ חַיֶּבֶת וְנִמְצֵאת חַטָּאת זוֹ חֻלִּין שֶׁנִּשְׁחֲטוּ בָּעֲזָרָה שֶׁהֵן אֲסוּרִין בַּהֲנָאָה כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת שְׁחִיטָה:","אַחַת הַיּוֹלֶדֶת וְאַחַת הַמַּפֶּלֶת וָלָד אֶחָד אוֹ וְלָדוֹת הַרְבֵּה הֲרֵי זוֹ מְבִיאָה קָרְבָּן אֶחָד לְכֻלָּן וְהוּא שֶׁתֵּלֵד כֻּלָּן בְּתוֹךְ יְמֵי מְלֹאת. אֲבָל אִם הִפִּילָה אַחַר יְמֵי מְלֹאת מְבִיאָה אַף עַל הַשֵּׁנִי. כֵּיצַד. יָלְדָה נְקֵבָה כָּל נְפָלִים שֶׁתַּפִּיל מִיּוֹם הַלֵּידָה עַד סוֹף יוֹם שְׁמוֹנִים הֲרֵי הֵן נֶחְשָׁבִין עִם הַוָּלָד הָרִאשׁוֹן וּכְאִלּוּ יָלְדָה תְּאוֹמִים זֶה אַחַר זֶה וְאֵינָהּ מְבִיאָה אֶלָּא קָרְבָּן אֶחָד. הִפִּילָה נֵפֶל בְּיוֹם שְׁמוֹנִים וְאֶחָד וּמִיּוֹם אֶחָד וּשְׁמוֹנִים וָהָלְאָה אִם הִיא רְאוּיָה לְקָרְבַּן הֲרֵי זוֹ מְבִיאָה עָלָיו בִּפְנֵי עַצְמוֹ. יָלְדָה נְקֵבָה וּלְאַחַר שִׁשִּׁים אוֹ שִׁבְעִים יוֹם הִפִּילָה נְקֵבָה שְׁנִיָּה. כָּל נֵפֶל שֶׁתַּפִּיל בְּתוֹךְ שְׁמוֹנִים שֶׁל נְקֵבָה זוֹ הַשְּׁנִיָּה פְּטוּרָה עָלָיו. וְכֵן אִם הִפִּילָה נְקֵבָה שְׁלִישִׁית אַחַר שִׁשִּׁים אוֹ שִׁבְעִים יוֹם שֶׁל נְקֵבָה שְׁנִיָּה. הֲרֵי כָּל נֵפֶל שֶׁתַּפִּיל בְּתוֹךְ שְׁמוֹנִים שֶׁל נְקֵבָה שְׁלִישִׁית פְּטוּרָה עָלָיו מִפְּנֵי שֶׁהוּא חָשׁוּב עִם הַנֵּפֶל הַשְּׁלִישִׁי וְהַנֵּפֶל הַשְּׁלִישִׁי חָשׁוּב עִם הַשֵּׁנִי מִפְּנֵי שֶׁהוּא בְּתוֹךְ יְמֵי מְלֹאת שֶׁלּוֹ וְהַשֵּׁנִי חָשׁוּב עִם הָרִאשׁוֹנָה וְאֵינָהּ מְבִיאָה אֶלָּא קָרְבָּן אֶחָד עַל הַכּל:","הַיּוֹלֶדֶת טֻמְטוּם אוֹ אַנְדְּרוֹגִינוּס וְהִפִּילָה נֵפֶל אַחַר אַרְבָּעִים מִיּוֹם לֵידָתוֹ. הֲרֵי זוֹ מְבִיאָה קָרְבָּן עַל נֵפֶל זֶה שֶׁמָּא זָכָר הוּא הָרִאשׁוֹן וַהֲרֵי הִפִּילָה אַחַר מְלֹאת. וְאֵין חַטָּאתָהּ נֶאֱכֶלֶת שֶׁמָּא נְקֵבָה הִיא הָרִאשׁוֹנָה וּבְתוֹךְ מְלֹאת הִפִּילָה שֶׁהִיא פְּטוּרָה מִקָּרְבָּן שֵׁנִי:","הָאִשָּׁה שֶׁיֵּשׁ עָלֶיהָ סְפֵק חָמֵשׁ לֵידוֹת אוֹ סְפֵק חָמֵשׁ זִיבוֹת. מְבִיאָה קָרְבָּן אֶחָד וְאוֹכֶלֶת בִּזְבָחִים וְאֵין הַשְּׁאָר עָלֶיהָ חוֹבָה. הָיוּ עָלֶיהָ חָמֵשׁ לֵידוֹת וַדָּאוֹת וְחָמֵשׁ זָבוֹת וַדָּאוֹת מְבִיאָה קָרְבָּן אֶחָד וְאוֹכֶלֶת בִּזְבָחִים וְהַשְּׁאָר עָלֶיהָ חוֹבָה. וְכֵן הַדִּין בְּזָב. הָיוּ עָלֶיהָ חָמֵשׁ לֵידוֹת וַדָּאוֹת וְחָמֵשׁ לֵידוֹת סָפֵק אוֹ חָמֵשׁ לֵידוֹת וַדָּאוֹת וְחָמֵשׁ זִיבוֹת סָפֵק. מְבִיאָה שְׁנֵי קָרְבָּנוֹת אֶחָד עַל הַוַּדַּאי וְנֶאֱכָל וּשְׁאָר הַוַּדָּאוֹת עָלֶיהָ חוֹבָה וְאֶחָד עַל הַסָּפֵק וְאֵינוֹ נֶאֱכָל וְאֵין הַשְּׁאָר עָלֶיהָ חוֹבָה וְאוֹכֶלֶת בִּזְבָחִים:","הָאִשָּׁה שֶׁנִּתְגַּיְּרָה וְאֵין יָדוּעַ אִם עַד שֶׁלֹּא נִתְגַּיְּרָה יָלְדָה אוֹ מִשֶּׁנִּתְגַּיְּרָה יָלְדָה. הֲרֵי זוֹ מְבִיאָה קָרְבָּן מִסָּפֵק וְאֵין חַטָּאתָהּ נֶאֱכֶלֶת. כְּבָר בֵּאַרְנוּ בְּהִלְכוֹת שְׁגָגוֹת שֶׁכָּל מְחֻסְּרֵי כַּפָּרָה מִסָּפֵק שֶׁעָבַר עֲלֵיהֶם [יוֹם הַכִּפּוּרִים] חַיָּבִין לְהָבִיא אַחַר יוֹם הַכִּפּוּרִים. שֶׁקָּרְבָּן זֶה מַכְשִׁירָן לֶאֱכל בְּקָדָשִׁים:","הָאִשָּׁה שֶׁיֵּשׁ עָלֶיהָ לֵידָה אוֹ זִיבָה. מְבִיאָה מְעוֹת הַקִּנִּים וְנוֹתֶנֶת בַּשּׁוֹפָר וְאוֹכֶלֶת בְּקָדָשִׁים לָעֶרֶב חֲזָקָה שֶׁאֵין בֵּית דִּין שֶׁל כֹּהֲנִים עוֹמְדִין מִשָּׁם עַד שֶׁיִּכְלוּ כָּל הַמָּעוֹת שֶׁבַּשּׁוֹפָר וְיַקְרִיבוּ כְּנֶגְדָּן קִנִּים. כְּמוֹ שֶׁבֵּאַרְנוּ בִּשְׁקָלִים וּבְהִלְכוֹת כְּלֵי הַמִּקְדָּשׁ וְהָעוֹבְדִין בּוֹ:","הָאִשָּׁה שֶׁהֵבִיאָה חַטָּאתָהּ וּמֵתָה יָבִיאוּ הַיּוֹרְשִׁים עוֹלָתָהּ. אַף עַל פִּי שֶׁלֹּא הִפְרִישָׁה אוֹתָהּ מֵחַיִּים כְּבָר נִשְׁתַּעַבְּדוּ נְכָסֶיהָ לַקָּרְבָּן. וְהַשִּׁעְבּוּד דִּין תּוֹרָה הוּא:"],"Mishneh Torah, Offerings for Unintentional Transgressions 2":["אֵין אָדָם חַיָּב חַטָּאת עַל שִׁגְגָתוֹ עַד שֶׁיִּהְיֶה שׁוֹגֵג מִתְּחִלָּה וְעַד סוֹף אֲבָל אִם שָׁגַג בַּתְּחִלָּה וְהֵזִיד בַּסּוֹף אוֹ הֵזִיד בַּתְּחִלָּה וְשָׁגַג בַּסּוֹף פָּטוּר מִקָּרְבַּן חַטָּאת. כֵּיצַד. כְּגוֹן שֶׁהוֹצִיא חֵפֶץ מֵרְשׁוּת לִרְשׁוּת בְּשַׁבָּת עָקַר בְּזָדוֹן וְהִנִּיחַ בִּשְׁגָגָה אוֹ שֶׁעָקַר בִּשְׁגָגָה וְהִנִּיחַ בְּזָדוֹן פָּטוּר עַד שֶׁיַּעֲקֹר בִּשְׁגָגָה וְיַנִּיחַ בִּשְׁגָגָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","עָבַר עֲבֵרָה וְיוֹדֵעַ שֶׁהִיא בְּלֹא תַּעֲשֶׂה אֲבָל אֵינוֹ יוֹדֵעַ שֶׁחַיָּבִין עָלֶיהָ כָּרֵת הֲרֵי זוֹ שְׁגָגָה וּמֵבִיא חַטָּאת. אֲבָל אִם יָדַע שֶׁהִיא בְּכָרֵת וְשָׁגַג בְּקָרְבָּן וְלֹא יָדַע אִם חַיָּבִין עָלֶיהָ קָרְבָּן אִם לָאו הֲרֵי זֶה מֵזִיד. שֶׁשִּׁגְגַת קָרְבָּן אֵינָהּ שְׁגָגָה בַּעֲבֵרוֹת אֵלּוּ שֶׁחַיָּבִין עֲלֵיהֶן כָּרֵת:","מִי שֶׁלֹּא נוֹדַע לוֹ עַצְמוֹ שֶׁל חֵטְא שֶׁחָטָא. אַף עַל פִּי שֶׁיָּדַע בְּוַדַּאי שֶׁעָבַר עַל לֹא תַּעֲשֶׂה שֶׁיֵּשׁ בּוֹ כָּרֵת. הֲרֵי זֶה פָּטוּר מִקָּרְבַּן חַטָּאת. שֶׁנֶּאֱמַר (ויקרא ד כג) \"אֲשֶׁר חָטָא בָּהּ\" עַד שֶׁיֵּדַע הַחֵטְא שֶׁחָטָא בּוֹ. כֵּיצַד. חֵלֶב וְנוֹתָר לְפָנָיו וְאָכַל אֶת אֶחָד מֵהֶם וְאֵין יָדוּעַ אֵי זֶה אָכַל. אִשְׁתּוֹ נִדָּה וַאֲחוֹתוֹ בַּבַּיִת וְשָׁגַג וּבָא עַל אַחַת מֵהֶן וְאֵין יָדוּעַ אֵי זוֹ מֵהֶן בָּעַל. שַׁבָּת וְיוֹם הַכִּפּוּרִים לְפָנָיו וְעָשָׂה מְלָאכָה בְּאֶחָד מֵהֶן וְאֵין יָדוּעַ בְּאֵי זֶה מֵהֶן עָשָׂה הֲרֵי זֶה פָּטוּר מִקָּרְבַּן חַטָּאת:","חָטָא וְנוֹדַע לוֹ חַטָּאתוֹ וְחָזַר וּשְׁכָחוֹ הֲרֵי זֶה מֵבִיא חַטָּאת לְשֵׁם מַה שֶּׁהוּא וְתֵאָכֵל כִּשְׁאָר חַטָּאוֹת הַנֶּאֱכָלוֹת:","שָׁגַג בְּשֵׁם אֶחָד וְהֵם שְׁנֵי גּוּפִין חַיָּב. כֵּיצַד. שְׁתֵּי נִדּוֹת וְשָׁגַג בְּאַחַת מֵהֶן וְאֵין יָדוּעַ אֵי זוֹ הִיא. שְׁתֵּי אֲחָיוֹת וְשָׁגַג בְּאַחַת מֵהֶן וְאֵין יָדוּעַ אֵי זוֹ הִיא חַיָּב חַטָּאת שֶׁהֲרֵי יָדַע עַצְמוֹ שֶׁל חֵטְא. לְמָה זֶה דּוֹמֶה לִשְׁתֵּי נֵרוֹת דּוֹלְקוֹת שֶׁכִּבָּה אַחַת מֵהֶן וְאֵין יָדוּעַ אֵי זוֹ נֵר הִיא. אוֹ לִשְׁנֵי תַּמְחוּיִין שֶׁל חֵלֶב שֶׁאָכַל מֵאֶחָד מֵהֶן וְאֵין יָדוּעַ מֵאֵי זֶה תַּמְחוּי מֵהֶן אָכַל שֶׁהוּא חַיָּב. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","כָּל הַמְחֻיָּב חַטָּאת קְבוּעָה עַל שִׁגְגָתוֹ וְעָשָׂה בִּשְׁגָגָה וְנוֹדַע לוֹ אַחַר שֶׁחָטָא אַף עַל פִּי שֶׁלֹּא הָיְתָה לוֹ יְדִיעָה בַּתְּחִלָּה שֶׁזֶּה חֵטְא הוּא הֲרֵי זֶה חַיָּב חַטָּאת. כֵּיצַד. תִּינוֹק שֶׁנִּשְׁבָּה לְבֵין הָעַכּוּ\"ם וְגָדַל וְהוּא אֵינוֹ יוֹדֵעַ מַה הֵם יִשְׂרָאֵל וְלֹא דָּתָם וְעָשָׂה מְלָאכָה בְּשַׁבָּת וְאָכַל חֵלֶב וְדָם וְכַיּוֹצֵא בָּהֶן. כְּשֶׁיִּוָּדַע לוֹ שֶׁהוּא יִשְׂרָאֵל ומְצֻוֶּה עַל כָּל אֵלּוּ חַיָּב לְהָבִיא חַטָּאת עַל כָּל עֲבֵרָה וַעֲבֵרָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַשּׁוֹגֵג בְּלֹא כַּוָּנָה בַּעֲרָיוֹת אוֹ בְּמַאֲכָלוֹת אֲסוּרוֹת חַיָּב חַטָּאת. בְּשַׁבָּת פָּטוּר מֵחַטָּאת. כֵּיצַד. הָיָה מִתְעַסֵּק עִם אִשָּׁה וּבְעָלָהּ בְּלֹא כַּוָּנָה לִבְעִילָה וַהֲרֵי הִיא עֶרְוָה עָלָיו. דִּמָּה שֶׁזֶּה שֶׁבְּפִיו רֹק הוּא וּבְלָעוֹ בְּלֹא כַּוָּנָה לְשֵׁם אֲכִילָה בָּעוֹלָם וַהֲרֵי הוּא חֵלֶב הֲרֵי זֶה חַיָּב חַטָּאת. נִתְכַּוִּן לְהַגְבִּיהַּ אֶת הַתָּלוּשׁ וְחָתַךְ אֶת הַמְחֻבָּר בְּלֹא כַּוָּנָה לַחֲתִיכָתוֹ פָּטוּר. מְלֶאכֶת מַחֲשֶׁבֶת אָסְרָה תּוֹרָה כְּמוֹ שֶׁבֵּאַרְנוּ בִּמְקוֹמוֹ:","כָּל הָעוֹשֶׂה מִצְוָה מִן הַמִּצְוֹת וּבִכְלַל עֲשִׂיָּתָהּ נַעֲשֵׂית עֲבֵרָה שֶׁחַיָּבִין עָלֶיהָ כָּרֵת בִּשְׁגָגָה הֲרֵי זֶה פָּטוּר מֵחַטָּאת מִפְּנֵי שֶׁעָשָׂה בִּרְשׁוּת. כֵּיצַד. הַבָּא עַל יְבִמְתּוֹ וַהֲרֵי הִיא נִדָּה וְהוּא לֹא יָדַע. הֲרֵי זֶה פָּטוּר מֵחַטָּאת שֶׁהֲרֵי עֲשָׂאָהּ בִּרְשׁוּת. אֲבָל אִם בָּא עַל אִשְׁתּוֹ וַהֲרֵי הִיא נִדָּה חַיָּב חַטָּאת מִפְּנֵי שֶׁלֹּא שְׁאָלָהּ וְאַחַר כָּךְ יִבְעֹל. אֲבָל יְבִמְתּוֹ אֵינוֹ רָגִיל בָּהּ כְּדֵי שֶׁיִּשְׁאַל לָהּ. וְכֵן מִי שֶׁהָיוּ לוֹ שְׁנֵי תִּינוֹקוֹת אֶחָד לָמוּל בְּשַׁבָּת וְאֶחָד לָמוּל בְּעֶרֶב שַׁבָּת אוֹ בְּאֶחָד בְּשַׁבָּת וְשָׁכַח וּמָל שְׁנֵיהֶן בְּשַׁבָּת. פָּטוּר מֵחַטָּאת שֶׁהֲרֵי יֵשׁ לוֹ רְשׁוּת לָמוּל אֶחָד מֵהֶן בְּשַׁבָּת וְשַׁבָּת דְּחוּיָה הִיא אֶצְלוֹ וּמִצְוָה עָשָׂה אַף עַל פִּי שֶׁהֵם שְׁנֵי גּוּפִין הוֹאִיל וּזְמַנּוֹ בָּהוּל אֵינוֹ מְדַקְדֵּק. אֲבָל אִם לֹא הָיָה אֶחָד מֵהֶן רָאוּי לָמוּל בְּשַׁבָּת וְשָׁכַח וּמָל בְּשַׁבָּת מִי שֶׁאֵינוֹ רָאוּי לָמוּל בְּשַׁבָּת חַיָּב חַטָּאת:","אֻמָּן שֶׁבָּא לָמוּל לִפְנוֹת הַיּוֹם בְּיוֹם הַשַּׁבָּת וְאָמְרוּ לוֹ לֹא נִשְׁאַר פְּנַאי בַּיּוֹם כְּדֵי שֶׁתָּמוּל וְאִם תַּתְחִיל לָמוּל לֹא תַּשְׁלִים עַד יְצִיאַת הַשַּׁבָּת וְנִמְצֵאתָ חוֹבֵל בְּשַׁבָּת וְלֹא עוֹשֶׂה מִצְוָה. וְאָמַר רָגִיל אֲנִי וְזָרִיז וּבִמְהֵרָה אָמוּל. אִם לֹא הִשְׁלִים אֶלָּא עַד יְצִיאַת הַשַּׁבָּת הֲרֵי זֶה חַיָּב חַטָּאת שֶׁהֲרֵי הִתְרוּ בּוֹ:","הַמּוֹצִיא אֶת הַלּוּלָב בְּיוֹם טוֹב הָרִאשׁוֹן שֶׁל חַג שֶׁחָל לִהְיוֹת בְּשַׁבָּת כְּדֵי לְצֵאת בּוֹ וְהֶעֱבִירוֹ אַרְבַּע אַמּוֹת בִּרְשׁוּת הָרַבִּים בְּשׁוֹגֵג פָּטוּר שֶׁהֲרֵי בִּרְשׁוּת הוֹצִיא. וְכֵן הַשּׁוֹחֵט אֶת הַפֶּסַח בְּיוֹם אַרְבָּעָה עָשָׂר שֶׁחָל לִהְיוֹת בְּשַׁבָּת וְנוֹדַע לוֹ אַחַר כֵּן שֶׁמָּשְׁכוּ הַבְּעָלִים אֶת יְדֵיהֶם אוֹ שֶׁמֵּתוּ אוֹ נִטְמְאוּ קֹדֶם שְׁחִיטָה. אוֹ שֶׁנִּמְצָא טְרֵפָה בַּסֵּתֶר כְּגוֹן נְקוּב מֵעַיִם אוֹ רֵאָה. הֲרֵי זֶה פָּטוּר מִפְּנֵי שֶׁשָּׁחַט בִּרְשׁוּת. אֲבָל נִמְצָא בַּעַל מוּם אוֹ שֶׁהָיְתָה טְרֵפָה גְּלוּיָה הֲרֵי זֶה חַיָּב חַטָּאת מִפְּנֵי שֶׁהָיָה לוֹ לִבְדֹּק וְאַחַר כָּךְ יִשְׁחֹט. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","שָׁחַט אֶת הַפֶּסַח בְּשַׁבָּת שֶׁלֹּא לִשְׁמוֹ בְּטָעוּת פָּטוּר מִפְּנֵי שֶׁהַזֶּבַח כָּשֵׁר שֶׁעֲקִירַת שְׁמוֹ בְּטָעוּת אֵינוֹ עֲקִירָה כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת פְּסוּלֵי הַמֻּקְדָּשִׁין:","שָׁחַט זְבָחִים אֲחֵרִים לְשֵׁם פֶּסַח בְּטָעוּת. אִם רְאוּיִין הֵם לְקָרְבַּן פֶּסַח פָּטוּר מִקָּרְבַּן חַטָּאת מִפְּנֵי שֶׁשָּׁחַט בִּרְשׁוּת. אִם אֵינָן רְאוּיִין כְּגוֹן שֶׁהָיְתָה נְקֵבָה אוֹ בֶּן שְׁתַּיִם חַיָּב חַטָּאת שֶׁהֲרֵי אֵינוֹ רָאוּי לְקָרְבַּן פֶּסַח. וְכֵן אִם שָׁגַג וּשְׁחָטוֹ בְּשַׁבָּת שֶׁלֹּא לְאוֹכְלָיו אוֹ שֶׁלֹּא לִמְנוּיָיו אוֹ לַעֲרֵלִים אוֹ לִטְמֵאִים חַיָּב חַטָּאת. שְׁחָטוֹ לְאוֹכְלָיו וְשֶׁלֹּא לְאוֹכְלָיו לִמְנוּיָיו וְשֶׁלֹּא לִמְנוּיָיו לְמוּלִים וְלַעֲרֵלִים לִטְמֵאִים וְלִטְהוֹרִים פָּטוּר. שֶׁהֲרֵי הַפֶּסַח כָּשֵׁר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַשּׁוֹחֵט בְּשַׁבָּת קָרְבַּן צִבּוּר שֶׁלֹּא לִשְׁמוֹ הֲרֵי זֶה חַיָּב חַטָּאת וְיַקְטִיר אֵימוּרִים לָעֶרֶב. וְכֵן אִם שָׁחַט יֶתֶר עַל חוֹבַת הַיּוֹם חַיָּב חַטָּאת עַל הַתּוֹסֶפֶת:","שָׁחַט קָרְבְּנוֹת יָחִיד שֶׁאֵין דּוֹחִים אֶת הַשַּׁבָּת בְּשַׁבָּת בִּשְׁגָגָה חַיָּב חַטָּאת וְהַבָּשָׂר מֻתָּר בַּהֲנָאָה. וְאֵין זוֹרְקִין אֶת הַדָּם. וְאִם עָבַר וְזָרַק דָּמָם לִשְׁמָן בֵּין בְּשׁוֹגֵג בֵּין בְּמֵזִיד עָלוּ לַבְּעָלִים לְשֵׁם חוֹבָה. וְיַקְטִיר אֵימוּרִין לָעֶרֶב וְהַבָּשָׂר יֵאָכֵל וְיָבִיא הַשּׁוֹחֵט חַטָּאת עַל שִׁגְגָתוֹ:","הָיוּ לְפָנָיו שְׁתֵּי בְּהֵמוֹת שֶׁל צִבּוּר אַחַת כְּחוּשָׁה וְאַחַת שְׁמֵנָה וְהָיְתָה חוֹבַת הַיּוֹם בְּאַחַת בֵּין חַטָּאת בֵּין עוֹלָה וְשָׁגַג וְשָׁחַט הַשְּׁתַּיִם. אִם שָׁחַט כְּחוּשָׁה בַּתְּחִלָּה וְאַחַר כָּךְ שָׁחַט הַשְּׁמֵנָה פָּטוּר מִקָּרְבַּן חַטָּאת וְלֹא עוֹד אֶלָּא שֶׁאוֹמְרִים לוֹ הָבֵא שְׁמֵנָה וּשְׁחֹט לְכַתְּחִלָּה. אֲבָל אִם שָׁחַט הַשְּׁמֵנָה תְּחִלָּה וְאַחַר כָּךְ הַכְּחוּשָׁה חַיָּב חַטָּאת עַל הַתּוֹסֶפֶת. נִמְצֵאת הָרִאשׁוֹנָה הַשְּׁמֵנָה טְרֵפָה בִּבְנֵי מֵעַיִם אַף עַל פִּי שֶׁלֹּא יָדַע שֶׁהִיא טְרֵפָה בְּעֵת שֶׁשָּׁחַט הַכְּחוּשָׁה וְלֹא לָזֶה נִתְכַּוֵּן הוֹאִיל וְנִשְׁחֲטָה הָאַחֲרוֹנָה כְּמִצְוָתָהּ הֲרֵי זֶה פָּטוּר מֵחַטָּאת. וְכֵן הַפּוֹרֵס מְצוּדָה לְהַעֲלוֹת דָּגִים מִן הַיָּם בִּשְׁגָגָה וְהֶעֱלָה תִּינוֹק עִם הַדָּגִים בֵּין שֶׁשָּׁמַע שֶׁטָּבַע תִּינוֹק בֵּין שֶׁלֹּא שָׁמַע הוֹאִיל וְהֶעֱלָה תִּינוֹק הֲרֵי זֶה פָּטוּר מֵחַטָּאת אַף עַל פִּי שֶׁלֹּא הָיְתָה כַּוָּנָתוֹ אֶלָּא לָצוּד מִפְּנֵי שֶׁהָיָה שׁוֹגֵג. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","מִי שֶׁהָיָה לְפָנָיו בְּלֵילֵי הַפֶּסַח צָלִי שֶׁל פֶּסַח וְנוֹתָר מִן הַקָּדָשִׁים וְנִתְכַּוֵּן לֶאֱכל צָלִי שֶׁהוּא מִצְוָה וְשָׁגַג וְאָכַל הַנּוֹתָר הֲרֵי זֶה חַיָּב חַטָּאת שֶׁהֲרֵי לֹא עָשָׂה מִצְוָה בַּאֲכִילָה זוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:"],"Mishneh Torah, One Who Injures a Person or Property 5":["אָסוּר לְאָדָם לַחֲבל בֵּין בְּעַצְמוֹ בֵּין בַּחֲבֵרוֹ. וְלֹא הַחוֹבֵל בִּלְבַד אֶלָּא כָּל הַמַּכֶּה אָדָם כָּשֵׁר מִיִּשְׂרָאֵל בֵּין קָטָן בֵּין גָּדוֹל בֵּין אִישׁ בֵּין אִשָּׁה דֶּרֶךְ נִצָּיוֹן הֲרֵי זֶה עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (דברים כה ג) \"לֹא יֹסִיף\" (דברים כה ג) \"לְהַכֹּתוֹ\". אִם הִזְהִירָה תּוֹרָה מִלְּהוֹסִיף בְּהַכָּאַת הַחוֹטֵא קַל וָחֹמֶר לְמַכֶּה אֶת הַצַּדִּיק:","אֲפִלּוּ לְהַגְבִּיהַּ יָדוֹ עַל חֲבֵרוֹ אָסוּר וְכָל הַמַּגְבִּיהַּ יָדוֹ עַל חֲבֵרוֹ אַף עַל פִּי שֶׁלֹּא הִכָּהוּ הֲרֵי זֶה רָשָׁע:","הַמַּכֶּה אֶת חֲבֵרוֹ הַכָּאָה שֶׁאֵין בָּהּ שְׁוֵה פְּרוּטָה לוֹקֶה שֶׁהֲרֵי אֵין כָּאן תַּשְׁלוּמִין כְּדֵי שֶׁיִּהְיֶה לָאו זֶה נִתָּן לְתַשְׁלוּמִין. וַאֲפִלּוּ הִכָּה עֶבֶד חֲבֵרוֹ הַכָּאָה שֶׁאֵין בָּהּ שְׁוֵה פְּרוּטָה לוֹקֶה שֶׁהֲרֵי יֶשְׁנוֹ בְּמִקְצָת מִצְוֹת. וְעַכּוּ\"ם שֶׁהִכָּה אֶת יִשְׂרָאֵל חַיָּב מִיתָה שֶׁנֶּאֱמַר (שמות ב יב) \"וַיִּפֶן כֹּה וָכֹה\" (שמות ב יב) \"וַיַּךְ אֶת הַמִּצְרִי\":","קְנָס קָנְסוּ חֲכָמִים לְאֵלּוּ הַשּׁוֹטִים בַּעֲלֵי זְרוֹעַ שֶׁיִּהְיֶה הַנֶּחְבָּל נֶאֱמָן וְנִשְׁבָּע בִּנְקִיטַת חֵפֶץ שֶׁזֶּה חָבַל בּוֹ חֲבָל זֶה וְנוֹטֵל מַה שֶּׁרָאוּי לוֹ. וְהוּא שֶׁיִּהְיוּ שָׁם עֵדִים. כֵּיצַד. הָיוּ שְׁנֵי עֵדִים מְעִידִין אוֹתוֹ שֶׁנִּכְנַס לְתוֹךְ יָדוֹ שָׁלֵם וְיָצָא חָבוּל וְלֹא רָאוּהוּ בְּעֵת שֶׁחָבַל בּוֹ וְהוּא אוֹמֵר לֹא חָבַלְתִּי וְהַלָּה אוֹמֵר אַתָּה חָבַלְתָּ בִּי הֲרֵי זֶה נִשְׁבָּע וְנוֹטֵל:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיְתָה הַמַּכָּה בְּמָקוֹם שֶׁאֶפְשָׁר לוֹ לְהַכּוֹת בְּעַצְמוֹ אוֹ שֶׁהָיָה עִמָּהֶם שְׁלִישִׁי שֶׁאֶפְשָׁר שֶׁזֶּה הַנֶּחְבָּל אָמַר לוֹ לַחֲבל בּוֹ וּלְהִתְרַעֵם עַל אַחֵר. אֲבָל אִם אֵין עִמָּהֶם אַחֵר וְהָיְתָה הַמַּכָּה בְּמָקוֹם שֶׁאֵינוֹ יָכוֹל לַעֲשׂוֹת בְּעַצְמוֹ כְּגוֹן שֶׁהָיְתָה נְשִׁיכָה בֵּין כְּתֵפָיו וְכַיּוֹצֵא בָּזֶה הֲרֵי זֶה נוֹטֵל בְּלֹא שְׁבוּעָה:","הוֹדָה הַחוֹבֵל שֶׁהוּא חָבַל מְשַׁלֵּם חֲמִשָּׁה דְּבָרִים שֶׁהֲרֵי הָעֵדִים הָיוּ שָׁם שֶׁנִּכְנַס לְתוֹךְ יָדוֹ שָׁלֵם בִּשְׁעַת הַמְּרִיבָה וְיָצָא חָבוּל. אֲבָל אִם לֹא הָיוּ שָׁם עֵדִים כְּלָל הוּא אוֹמֵר חָבַלְתָּ בִּי וְהוֹדָה מֵעַצְמוֹ פָּטוּר מִן הַנֵּזֶק וּמִן הַצַּעַר וְחַיָּב בְּשֶׁבֶת וּבְבשֶׁת וּבְרִפּוּי עַל פִּי עַצְמוֹ. לְפִיכָךְ אִם כָּפַר וְאָמַר לֹא חָבַלְתִּי נִשְׁבָּע שְׁבוּעַת הֶסֵּת:","וְלָמָּה מְשַׁלֵּם אָדָם שְׁלֹשָׁה דְּבָרִים אֵלּוּ עַל פִּי עַצְמוֹ. שֶׁהַשֶּׁבֶת וְהָרִפּוּי מָמוֹן הוּא וְלֹא קְנָס. שֶׁאִם לֹא יִתֵּן לוֹ הֲרֵי חִסְּרוֹ מָמוֹן שֶׁהוּא מִתְרַפֵּא בּוֹ וּבִטֵּל מִמְּלַאכְתּוֹ. וְהַבּשֶׁת לֹא הִגִּיעָה לוֹ אֶלָּא בְּשָׁעָה שֶׁהוֹדָה בְּפָנֵינוּ שֶׁהוּא חָבַל בּוֹ. שֶׁהַנֶּחְבָּל שֶׁלֹּא חָבַל בּוֹ [בִּפְנֵי] אָדָם אֵין לוֹ בֹּשֶׁת וְהוֹדָאָתוֹ בְּבֵית דִּין הִיא שֶׁבִּיְּשָׁה אוֹתוֹ:","נִמְצֵאתָ לָמֵד שֶׁאֵין הֶפְרֵשׁ בְּבשֶׁת בֵּין בּשֶׁת הַמַּגִּיעַ לוֹ אִם חָבַל בּוֹ בִּפְנֵי אֲחֵרִים וּבֵין בּשֶׁת הַמַּגִּיעַ לוֹ בְּעֵת שֶׁהוֹדָה בִּפְנֵי אֲחֵרִים שֶׁחָבַל בּוֹ. לְפִיכָךְ מְשַׁלֵּם אָדָם בּשֶׁת עַל פִּי עַצְמוֹ:","אֵינוֹ דּוֹמֶה מַזִּיק חֲבֵרוֹ בְּגוּפוֹ לְמַזִּיק מָמוֹנוֹ. שֶׁהַמַּזִּיק מָמוֹן חֲבֵרוֹ כֵּיוָן שֶׁשִּׁלֵּם מַה שֶּׁהוּא חַיָּב לְשַׁלֵּם נִתְכַּפֵּר לוֹ. אֲבָל חָבַל בַּחֲבֵרוֹ אַף עַל פִּי שֶׁנָּתַן לוֹ חֲמִשָּׁה דְּבָרִים אֵין מִתְכַּפֵּר לוֹ. וַאֲפִלּוּ הִקְרִיב כָּל אֵילֵי נְבָיוֹת אֵינוֹ מִתְכַּפֵּר לוֹ וְלֹא נִמְחַל עֲוֹנוֹ עַד שֶׁיְּבַקֵּשׁ מִן הַנֶּחְבָּל וְיִמְחל לוֹ:","וְאָסוּר לַנֶּחְבָּל לִהְיוֹת אַכְזָרִי וְלֹא יִמְחל אֵין זוֹ דֶּרֶךְ זֶרַע יִשְׂרָאֵל אֶלָּא כֵּיוָן שֶׁבִּקֵּשׁ מִמֶּנּוּ הַחוֹבֵל וְנִתְחַנֵּן לוֹ פַּעַם רִאשׁוֹנָה וּשְׁנִיָּה וְיָדַע שֶׁהוּא שָׁב מֵחֶטְאוֹ וְנִחָם עַל רָעָתוֹ יִמְחל לוֹ. וְכָל הַמְמַהֵר לִמְחל הֲרֵי הוּא מְשֻׁבָּח וְרוּחַ חֲכָמִים נוֹחָה הֵימֶנּוּ:","וְעוֹד יֵשׁ הֶפְרֵשׁ בֵּין נִזְקֵי גּוּפוֹ לְנִזְקֵי מָמוֹנוֹ. שֶׁהָאוֹמֵר לַחֲבֵרוֹ סַמֵּא אֶת עֵינִי קְטַע אֶת יָדִי עַל מְנָת שֶׁאַתָּה פָּטוּר הֲרֵי זֶה חַיָּב בַּחֲמִשָּׁה דְּבָרִים שֶׁהַדָּבָר יָדוּעַ שֶׁאֵין אָדָם רוֹצֶה בְּכָךְ. אֲבָל הָאוֹמֵר לַחֲבֵרוֹ קְרַע אֶת כְּסוּתִי שְׁבֹר אֶת כַּדִּי עַל מְנָת שֶׁאַתָּה פָּטוּר הֲרֵי זֶה פָּטוּר. וְאִם לֹא אָמַר לוֹ עַל מְנָת שֶׁאַתָּה פָּטוּר הֲרֵי זֶה חַיָּב לְשַׁלֵּם אַף עַל פִּי שֶׁהִרְשָׁהוּ לְהַשְׁחִית:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁבָּאוּ הַכֵּלִים לְיָדוֹ תְּחִלָּה בְּתוֹרַת שְׁמִירָה. כְּגוֹן שֶׁהָיוּ שְׁאוּלִין אוֹ מֻפְקָדִין אֶצְלוֹ וְאָמַר לוֹ שְׁבֹר וּקְרַע וְעָשָׂה כֵן חַיָּב לְשַׁלֵּם עַד שֶׁיֹּאמַר לוֹ עַל מְנָת שֶׁאַתָּה פָּטוּר. אֲבָל אִם אָמַר לוֹ קַח כְּלִי זֶה וְשָׁבְרוֹ. בֶּגֶד זֶה וְקָרְעוֹ. וְעָשָׂה כֵן הֲרֵי זֶה פָּטוּר:","הָאוֹמֵר לַחֲבֵרוֹ שְׁבֹר כֵּלָיו שֶׁל פְּלוֹנִי עַל מְנָת שֶׁאַתָּה פָּטוּר וְעָשָׂה הֲרֵי זֶה חַיָּב לְשַׁלֵּם. וּכְאִלּוּ אָמַר לוֹ סַמֵּא עֵינוֹ שֶׁל פְּלוֹנִי עַל מְנָת שֶׁאַתָּה פָּטוּר. וְאַף עַל פִּי שֶׁהָעוֹשֶׂה הוּא חַיָּב לְשַׁלֵּם. הֲרֵי זֶה הָאוֹמֵר לוֹ שֻׁתָּפוֹ בָּעָוֹן וְרָשָׁע הוּא. שֶׁהֲרֵי הִכְשִׁיל עִוֵּר וְחִזֵּק יְדֵי עוֹבְרֵי עֲבֵרָה:"],"Mishneh Torah, Other Sources of Defilement 17":["כְּזַיִת מִן הַמֵּת בְּפִי הָעוֹרֵב סָפֵק הֶאֱהִיל עַל הָאָדָם וְעַל הַכֵּלִים בִּרְשׁוּת הַיָּחִיד סָפֵק שֶׁלֹּא הֶאֱהִיל הֲרֵי הָאָדָם טָמֵא מִסָּפֵק וְהוּא שֶׁיִּהְיֶה בּוֹ דַּעַת לִשָּׁאֵל וְהַכֵּלִים טְהוֹרִים מִפְּנֵי שֶׁאֵין לָהֶן דַּעַת לִשָּׁאֵל. וְכֵן הַמְמַלֵּא בִּכְלִי וְנָתַן בַּעֲשָׂרָה כֵּלִים וְנִמְצָא הַשֶּׁרֶץ בְּאֶחָד מֵהֶן הוּא טָמֵא וְהַכֵּלִים טְהוֹרִין אַף עַל פִּי שֶׁכֻּלָּן סָפֵק שֶׁמָּא הַשֶּׁרֶץ בַּכְּלִי שֶׁמִּלֵּא בּוֹ הָיָה תְּחִלָּה מִפְּנֵי שֶׁהֵן כֵּלִים וְאֵין בָּהֶן דַּעַת לִשָּׁאֵל. וְאִם הָיָה לַכְּלִי שֶׁמִּלֵּא בּוֹ אָזְנַיִם הוֹאִיל וְאֶפְשָׁר שֶׁיֵּצְאוּ הַמַּיִם וְיִתְאַחֵר בּוֹ הַשֶּׁרֶץ כֻּלָּן טְמֵאִים. וְכֵן הַמְמַלֵּא בַּעֲשָׂרָה דְּלָיִים זֶה אַחַר זֶה וְנָתַן בַּעֲשָׂרָה כֵּלִים מִדְּלִי אֶחָד לִכְלִי אַחֵר וְאֵין יָדוּעַ הָרִאשׁוֹן מִן הָאַחֲרוֹן וְנִמְצָא הַשֶּׁרֶץ בִּכְלִי אֶחָד מֵהֶן הֲרֵי הַתִּשְׁעָה כֵּלִים עִם עֲשֶׂרֶת הַדְּלָיִים טְהוֹרִין שֶׁאֲנִי אוֹמֵר שֶׁמָּא בִּכְלִי זֶה הָיָה הַשֶּׁרֶץ מִתְּחִלָּתוֹ. וְאִם יֵשׁ לַדְּלָיִים אָזְנַיִם הֲרֵי כָּל הַדְּלָיִים עִם כָּל הַכֵּלִים טְמֵאִין. הַמְעָרֶה מִכְּלִי לִכְלִי וְנִמְצָא הַשֶּׁרֶץ בַּתַּחְתּוֹן הָעֶלְיוֹן טָהוֹר. וְאֵין אוֹמְרִין מֵהָעֶלְיוֹן נָפַל אֶלָּא שֶׁמָּא בַּתַּחְתּוֹן הָיָה מִפְּנֵי שֶׁהֵן כֵּלִים וְאֵין לָהֶן דַּעַת לִשָּׁאֵל. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","קֻפָּה שֶׁנִּשְׁתַּמֵּשׁ בָּהּ בְּטָהֳרוֹת וְנִמְצָא בָּהּ שֶׁרֶץ אִם יֵשׁ לָהּ שׁוּלַיִם אוֹ אָזְנַיִם אַף עַל פִּי שֶׁאֵין לָהּ שׁוּלַיִם הֲרֵי כָּל הַטָּהֳרוֹת שֶׁנִּשְׁתַּמְּשׁוּ בָּהּ טְמֵאוֹת. אֲפִלּוּ הָיְתָה בְּדוּקָה וּמְכֻסָּה שֶׁמָּא עִם הַגְבָּהַת יָדוֹ מִן הַבְּדִיקָה נָפַל הַשֶּׁרֶץ. וַאֲפִלּוּ נִשְׁתַּמֵּשׁ בָּהּ בְּטָהֳרוֹת בְּזָוִית זוֹ וְטִלְטְלָהּ לְזָוִית אַחֶרֶת וְנִמְצָא בָּהּ הַשֶּׁרֶץ כֻּלָּן טְמֵאוֹת לְפִי שֶׁמַּחֲזִיקִין טֻמְאָה מִמָּקוֹם לְמָקוֹם לִתְלוֹת אֲבָל לֹא לִשְׂרֹף:","הַזּוֹלֵף אֶת הַבּוֹר וּמְמַלֵּא מִמֶּנּוּ חָבִיּוֹת אִם הָיָה מַשְׁקִיעַ כָּל חָבִית וְחָבִית בַּבּוֹר וּמְמַלֵּא אוֹתָן וְנִמְצָא הַשֶּׁרֶץ בָּרִאשׁוֹנָה כֻּלָּן טְמֵאוֹת. נִמְצָא בָּאַחֲרוֹנָה הִיא טְמֵאָה וְכֻלָּן טְהוֹרוֹת שֶׁאֲנִי אוֹמֵר אַחַר שֶׁמִּלֵּא אֶת הָרִאשׁוֹנוֹת נָפַל שֶׁרֶץ לַבּוֹר. הָיָה זוֹלֵף בִּכְלִי וְנוֹתֵן לְתוֹךְ הֶחָבִיּוֹת עַד שֶׁמִּלְּאָן וְנִמְצָא הַשֶּׁרֶץ בְּאַחַת מֵהֶן הִיא בִּלְבַד טְמֵאָה וְכֻלָּן טְהוֹרוֹת שֶׁאֲנִי אוֹמֵר בְּזוֹ בִּלְבַד נָפַל הַשֶּׁרֶץ אוֹ הָיָה בָּהּ עַד שֶׁלֹּא זִלֵּף לְתוֹכָהּ. לְפִיכָךְ אִם הָיָה בּוֹדֵק כָּל חָבִית מֵהֶן וְאַחַר כָּךְ נוֹתֵן בָּהּ הַיַּיִן וּמְכַסֶּה אוֹתָהּ אַחַר שֶׁזּוֹלֵף לְתוֹכָהּ וְנִמְצָא הַשֶּׁרֶץ בְּאַחַת מֵהֶן כֻּלָּן טְמֵאוֹת. וְכֵן אִם נִמְצָא הַשֶּׁרֶץ בַּבּוֹר אוֹ בַּכְּלִי שֶׁזּוֹלֵף בּוֹ הַכּל טָמֵא:","הָיָה קוֹצֶה זֵיתִים מִן הַמַּעֲטָן וּמַעֲלֶה אוֹתָן לַגַּג וְנִמְצָא הַשֶּׁרֶץ בַּגַּג זֵיתִים שֶׁבַּמַּעֲטָן טְהוֹרִים. נִמְצָא בַּמַּעֲטָן הַמַּעֲטָן טָמֵא. נִמְצָא בֵּין כֹּתֶל לַזֵּיתִים הַזֵּיתִים טְהוֹרִים. נִמְצָא הַשֶּׁרֶץ בְּתוֹךְ גּוּשׁ שֶׁל זֵיתִים וְהַגּוּשׁ בַּגַּג אִם בְּתוֹךְ שְׁלֹשֶׁת יָמִים אַף הַמַּעֲטָן טָמֵא. שֶׁאֲנִי אוֹמֵר גּוּשׁ זֶה מִן הַמַּעֲטָן עָלָה וְהַשֶּׁרֶץ בְּתוֹכוֹ. וְאִם נִמְצָא אַחַר שְׁלֹשָׁה יָמִים מִשֶּׁהֶעֱלָה זֵיתִים לַגַּג הֲרֵי הַמַּעֲטָן טָהוֹר שֶׁמָּא בַּגַּג נִתְקַבְּצוּ וְנַעֲשׂוּ גּוּשׁ בְּתוֹךְ הַשְּׁלֹשָׁה יָמִים:","הַקּוֹרֵץ מִקְרֶצֶת מִן הָעִסָּה וְנִמְצָא שֶׁרֶץ בַּמִּקְרֶצֶת הַמִּקְרֶצֶת לְבַדָּהּ טְמֵאָה. נִמְצָא בָּעִסָּה הָעִסָּה לְבַדָּהּ טְמֵאָה. נִמְצָא בְּתוֹךְ הַמִּקְרֶצֶת אַף הָעִסָּה טְמֵאָה:","אֹכֶל טָמֵא שֶׁנִּמְצָא גַּרְעִינָה שֶׁלּוֹ בְּתוֹךְ הַכִּכָּר אוֹ עַל גַּבֵּי תַּבְשִׁיל רוֹתֵחַ אַף עַל פִּי שֶׁאֵין עָלֶיהָ מַשְׁקֶה טוֹפֵחַ הֲרֵי הֵן טְמֵאִים. שֶׁאֲנִי אוֹמֵר הָאוֹכֵל כֻּלּוֹ נָפַל שָׁם וְנִמּוֹחַ בְּתוֹךְ הַכִּכָּר אוֹ מֵחֲמַת הָרְתִיחָה וְנִשְׁאֲרָה גַּרְעִינָתוֹ. נִמְצֵאת הַגַּרְעִינָה עַל גַּבֵּי הַכִּכָּר אוֹ בְּתוֹךְ תַּבְשִׁיל צוֹנֵן הֲרֵי אֵלּוּ טְהוֹרִין אַף עַל פִּי שֶׁיֵּשׁ עָלֶיהָ מַשְׁקֶה שֶׁאֲנִי אוֹמֵר גַּרְעִינָה זוֹ לְבַדָּהּ נָפְלָה אַחַר שֶׁאָבַד הָאוֹכֵל מֵעָלֶיהָ שֶׁהֲרֵי אֵינָהּ מְטַמְּאָה:","הָיוּ בַּבַּיִת אֳכָלִין טְמֵאִין וָאֳכָלִין טְהוֹרִים וְנִמְצֵאת גַּרְעִינָה בַּבַּיִת הוֹלְכִין אַחַר הָרֹב. וְכֵן אִם הָיוּ דָּמִים טְהוֹרִים וְדָמִים טְמֵאִים בְּתוֹךְ הַבַּיִת וְנִמְצָא דָּם עַל הָאֹכֶל הוֹלְכִים אַחַר הָרֹב. מַעֲשֶׂה הָיָה בְּכִכָּר שֶׁל תְּרוּמָה שֶׁנִּמְצָא עָלָיו דָּם וּבָא מַעֲשֶׂה לִפְנֵי חֲכָמִים וְטִהֲרוּהוּ. שֶׁאֲפִלּוּ נֹאמַר דַּם שֶׁרֶץ הוּא הֲרֵינִי אוֹמֵר דַּם שֶׁרֶץ חַי הוּא שֶׁהוּא טָהוֹר:","עִיר שֶׁיֵּשׁ בָּהּ נְבֵלוֹת וּשְׁחוּטוֹת. בָּשָׂר הַנִּמְצָא בָּהּ הוֹלְכִים אַחַר הָרֹב. וְכֵן אִם הָיָה הַנִּמְצָא בָּהּ סְפֵק שֶׁרֶץ סְפֵק צְפַרְדֵּעַ הוֹלְכִין אַחַר הָרֹב שֶׁיֵּשׁ בְּאוֹתָהּ הָעִיר בְּאוֹתוֹ הַזְּמַן. זֶה הַכְּלָל בְּנִמְצָא הַלֵּךְ אַחַר הָרֹב:","הָאִשָּׁה שֶׁמְּגַבֶּבֶת גְּבָבָה בֶּחָצֵר וְנִמְצָא שֶׁרֶץ בְּתוֹךְ גְּבָבָה הֲרֵי זוֹ טְהוֹרָה שֶׁאֵין הַשֶּׁרֶץ מְטַמֵּא בְּמַשָּׂא. נִמְצָא עַל גַּבֵּי גְּבָבָה הֲרֵי זוֹ טְמֵאָה שֶׁמָּא נָגְעָה בּוֹ. הָיְתָה כּוֹבֶרֶת בִּכְבָרָה וְנִמְצָא שֶׁרֶץ בְּתוֹךְ הַפֵּרוֹת שֶׁבַּכְּבָרָה הֲרֵי זוֹ טְהוֹרָה. נִמְצָא עַל גַּבֵּי הַכְּבָרָה הֲרֵי זוֹ סָפֵק טְמֵאָה שֶׁמָּא נָגְעָה בּוֹ וְכָל סָפֵק בִּרְשׁוּת הַיָּחִיד טָמֵא כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Overview of Mishneh Torah Contents 1":["וראיתי לחלק חיבור זה לארבעה עשר ספרים:","ספר ראשון. אכלול בו כל המצוות שהן עיקר דת משה רבנו, וצריך אדם לידע אותם תחילת הכול – כגון ייחוד שמו ברוך הוא, ואיסור עבודה זרה. וקראתי שם ספר זה ספר המדע.","ספר שני. אכלול בו המצוות שהן תדירות, שנצטווינו בהם כדי לאהוב את המקום ולזוכרו תמיד – כגון קרית שמע, ותפילה, ותפילין, וברכות; ומילה בכלל, לפי שהיא אות בבשרנו להזכיר תמיד בשעה שאין שם לא תפילין ולא ציצית וכיוצא בהן. וקראתי שם ספר זה ספר אהבה.","ספר שלישי. אכלול בו כל המצוות שהן בזמנים ידועים – כגון שבת, ומועדות. וקראתי שם ספר זה ספר זמנים.","ספר רביעי. אכלול בו המצוות של בעילה – כגון קידושין וגירושין, וייבום וחליצה. וקראתי שם ספר זה ספר נשים.","ספר חמישי. אכלול בו מצוות של ביאות אסורות, ומצוות של מאכלות אסורות – לפי שבשני עניינים האלו קידשנו המקום והבדילנו מן האומות בעריות ובמאכלות אסורות, ובשניהם נאמר \"ואבדיל אתכם מן העמים\" (ויקרא כ, כו), \"אשר הבדלתי אתכם מן העמים\" (ויקרא כ,כד). וקראתי שם ספר זה ספר קדושה.","ספר שישי. אכלול בו מצוות שיתחייב אדם בהן מי שאסר עצמו בדברים – כגון שבועות ונדרים. וקראתי שם ספר זה ספר הפלאה.","ספר שביעי. אכלול בו מצוות שהם בזרע הארץ – כגון שמיטין ויובלות, ומעשרות ותרומות, ושאר מצוות הנכללים עימהן מעניינם. וקראתי שם ספר זה ספר זרעים.","ספר שמיני. אכלול בו מצוות שהן בבניין מקדש וקרבנות ציבור התמידין. וקראתי שם ספר זה ספר עבודה.","ספר תשיעי. אכלול בו מצוות שהן בקרבנות היחיד. וקראתי שם ספר זה ספר קרבנות.","ספר עשירי. אכלול בו מצוות שהן בטהרות וטמאות. וקראתי שם ספר זה ספר טהרה.","ספר אחד עשר. אכלול בו מצוות שבין אדם לחברו, ויש בהם היזק תחילה בממון או בגוף. וקראתי שם ספר זה ספר נזקים.","ספר שנים עשר. אכלול בו מצוות מכירה וקנייה. וקראתי שם ספר זה ספר קניין.","ספר שלושה עשר. אכלול בו מצוות שבין אדם לחברו, בשאר דינין שאין בתחילתן היזק – כגון שומרין, ובעלי חובות, וטענות וכפירות. וקראתי שם ספר זה ספר משפטים.","ספר ארבעה עשר. אכלול בו מצוות שהן מסורין לסנהדרין – כגון מיתות בית דין, וקבלת עדות, ודין המלך ומלחמותיו. וקראתי שם ספר זה ספר שופטים.","וזה הוא חילוק הלכות של חיבור זה לפי ענייני הספרים, וחילוק המצוות לפי ענייני ההלכות.","ספר המדע הלכותיו חמש, וזה הוא סידורן: הלכות יסודי התורה, הלכות דעות, הלכות תלמוד תורה, הלכות עבודה זרה וחוקות הגוים, הלכות תשובה.","הלכות יסודי התורה יש בכללן עשר מצוות: שש מצוות עשה, וארבע מצוות לא תעשה. וזה הוא פרטן: (א) לידע שיש שם אלוה. (ב) שלא יעלה במחשבה שיש שם אלוה זולתי יי. (ג) לייחדו. (ד) לאהבו. (ה) ליראה ממנו. (ו) לקדש שמו. (ז) שלא לחלל את שמו. (ח) שלא לאבד דברים שנקרא שמו עליהם. (ט) לשמוע מן הנביא המדבר בשמו. (י) שלא לנסותו.","הלכות דעות יש בכללן אחת עשרה מצוות: חמש מצוות עשה, ושש מצוות לא תעשה. וזה הוא פרטן: (א) להדמות בדרכיו. (ב) להדבק ביודעיו. (ג) לאהוב את רעים. (ד) לאהוב את הגרים. (ה) שלא לשנוא אחים. (ו) להוכיח. (ז) שלא להלבין פנים. (ח) שלא לענות אמללין. (ט) שלא להלוך רכיל. (י) שלא לנקום. (יא) שלא לנטור.","הלכות תלמוד תורה יש בכללן שתי מצוות עשה: ראשונה ללמוד תורה, שניה לכבד מלמדיה ויודעיה.","הלכות עבודה זרה וחוקות הגויים יש בכללן אחת וחמישים מצוות: שתי מצוות עשה, ותשע וארבעים מצוות לא תעשה. וזה הוא פרטן: (א) שלא לפנות אחר עבודה זרה. (ב) שלא לתור אחר הרהור הלב וראיית העיניים. (ג) שלא לגדף. (ד) שלא יעבוד אותה כדרך עבודתה. (ה) שלא ישתחוה לה. (ו) שלא לעשות פסל לעצמו. (ז) שלא לעשות פסל אפילו לאחרים. (ח) שלא לעשות צורות אפילו לנואי. (ט) שלא להדיח אחרים אחריה. (י) לשרוף עיר הנידחת. (יא) שלא לבנותה. (יב) שלא ליהנות מכל ממונה. (יג) שלא להסית יחיד לעובדה. (יד) שלא לאהוב המסית. (טו) שלא לעזוב שנאתו. (טז) שלא להצילו. (יז) שלא ללמד עליו זכות. (יח) שלא ימנע מללמד עליו חובה. (יט) שלא להתנבא בשמה. (כ) שלא לשמוע מן המתנבא בשמה. (כא) שלא להתנבא בשקר, ואפילו בשם יי. (כב) שלא לגור מהריגת נביא שקר. (כג) שלא לישבע בשם עבודה זרה. (כד) שלא לעשות אוב. (כה) שלא לעשות ידעוני. (כו) שלא להעביר למולך. (כז) שלא להקים מצבה. (כח) שלא להשתחוות על אבן משכית. (כט) שלא ליטע אשרה. (ל) לאבד עבודה זרה וכל הנעשה בשבילה. (לא) שלא ליהנות בעבודה זרה ובכל משמשיה. (לב) שלא ליהנות בציפויי נֶעבד. (לג) שלא לכרות ברית לעובדי עבודה זרה. (לד) שלא לחון עליהם. (לה) שלא ישבו בארצנו. (לו) שלא להדמות במנהגותן ובמלבושן. (לז) שלא לנחש. (לח) שלא לקסום. (לט) שלא לעונן. (מ) שלא לחבור חבר. (מא) שלא לדרוש אל המתים. (מב) שלא לשאול באוב. (מג) שלא לשאול בידעוני. (מד) שלא לכשף. (מה) שלא להקיף פאת ראש. (מו) שלא להשחית פאת הזקן. (מז) שלא יעדה איש עדי אישה. (מח) שלא תעדה אישה עדי איש. (מט) שלא לכתוב קעקע. (נ) שלא להתגודד. (נא) שלא לעשות קורחה על מת.","הלכות תשובה מצוַת עשה אחת, והיא שישוב החוטא מחטאו לפני יי ויתוַדה.","נמצאו כל המצוות הנכללות בספר זה חמש ושבעים: שש עשרה מהן מצוות עשה, ותשע וחמישים מצוות לא תעשה."],"Mishneh Torah, Overview of Mishneh Torah Contents 8":["ספר עבודה","הלכותיו תשע, וזה הוא סידורן: הלכות בית הבחירה, הלכות כלי המקדש והעובדים בו, הלכות ביאת המקדש, הלכות איסורי המזבח, הלכות מעשה הקרבנות, הלכות תמידין ומוספין, הלכות פסולי המוקדשין, הלכות עבודת יום הכיפורים, הלכות מעילה.","הלכות בית הבחירה. יש בכללן שש מצוות – שלוש מצוות עשה, ושלוש מצוות לא תעשה; וזה הוא פרטן: (א) לבנות מקדש; (ב) שלא לבנות המזבח גזית; (ג) שלא לעלות במעלות עליו; (ד) ליראה מן המקדש; (ה) לשמור את המקדש סביב; (ו) שלא להשבית שמירת המקדש.","הלכות כלי המקדש והעובדים בו. יש בכללן ארבע עשרה מצוות – שש מצוות עשה, ושמונה מצוות לא תעשה; וזה הוא פרטן: (א) לעשות שמן המשחה; (ב) שלא לעשות כמוהו; (ג) שלא לסוך ממנו; (ד) שלא לעשות כמתכונת הקטורת; (ה) שלא להקטיר על מזבח הזהב חוץ מן הקטורת; (ו) לשאת הארון על הכתף; (ז) שלא יסורו הבדים ממנו; (ח) שיעבוד הלוי במקדש; (ט) שלא יעשה אחד במלאכת חברו במקדש; (י) לקדש הכוהן לעבודה; (יא) שיהיו כל המשמרות שוות ברגלים; (יב) ללבוש בגדי כהונה לעבודה; (יג) שלא ייקרע המעיל; (יד) שלא ייזח החושן מעל האיפוד.","הלכות ביאת המקדש. יש בכללן חמש עשרה מצוות – שתי מצוות עשה, ושלוש עשרה מצוות לא תעשה; וזה הוא פרטן: (א) שלא ייכנס כוהן שיכור למקדש; (ב) שלא ייכנס לו כוהן פרוע ראש; (ג) שלא ייכנס לו כוהן קרוע בגדים; (ד) שלא ייכנס כוהן בכל עת אל ההיכל; (ה) שלא ייצא כוהן מן המקדש בשעת העבודה; (ו) לשלח טמאים מן המקדש; (ז) שלא ייכנס טמא למקדש; (ח) שלא ייכנס טמא להר הבית; (ט) שלא ישמש טמא; (י) שלא ישמש טבול יום; (יא) לקדש העובד ידיו ורגליו; (יב) שלא ייכנס בעל מום להיכל ולמזבח; (יג) שלא יעבוד בעל מום; (יד) שלא יעבוד בעל מום עובר; (טו) שלא יעבוד זר.","הלכות איסורי מזבח. יש בכללן ארבע עשרה מצוות – ארבע מצוות עשה, ועשר מצוות לא תעשה; וזה הוא פרטן: (א) להקריב כל הקרבנות תמימין; (ב) שלא להקדיש בעל מום למזבח; (ג) שלא ישחוט; (ד) שלא יזרוק דמו; (ה) שלא יקטיר חלבו; (ו) שלא יקריב בעל מום עובר; (ז) שלא יקריב בעל מום, אפילו בקרבנות הגויים; (ח) שלא יטיל מום בקודשים; (ט) לפדות פסולי המוקדשים; (י) להקריב מיום השמיני והלאה, וקודם זמן זה הוא הנקרא מחוסר זמן ואין מקריבין אותו; (יא) שלא להקריב אתנן ומחיר; (יב) שלא להקטיר שאור ודבש; (יג) למלוח כל הקרבנות; (יד) שלא להשבית מלח מעל הקרבנות.","הלכות מעשה הקרבנות. יש בכללן שלוש ועשרים מצוות – עשר מצוות עשה, ושלוש עשרה מצוות לא תעשה; וזה הוא פרטן: (א) לעשות העולה כמעשיה הכתובים על הסדר; (ב) שלא לאכול בשר העולה; (ג) סדר החטאת; (ד) שלא לאכול מבשר חטאת הפנימית; (ה) שלא יבדיל בחטאת העוף; (ו) סדר האשם; (ז) שיאכלו הכוהנים בשר קודשי קודשים במקדש; (ח) שלא יאכלום חוץ לעזרה; (ט) שלא יאכל זר מקודשי קודשים; (י) סדר השלמים; (יא) שלא לאכול בשר קודשים קלים קודם זריקת דמים; (יב) לעשות כל מנחה כסדר מעשיה הכתובים בתורה; (יג) שלא ישים שמן על מנחת חוטא; (יד) שלא ייתן עליה לבונה; (טו) שלא תיאכל מנחת כוהן; (טז) שלא תיאפה מנחת חמץ; (יז) שיאכלו הכוהנים שיירי מנחות; (יח) שיביא כל נדריו ונדבותיו ברגל שפגע בו ראשון; (יט) שלא יאחר נדרו ונדבתו ושאר דברים שהוא חייב בהן; (כ) להקריב כל הקרבנות בבית הבחירה; (כא) להביא קודשי חוצה לארץ לבית הבחירה; (כב) שלא לשחוט קרבנות חוץ לעזרה; (כג) שלא להקריב קרבן חוץ לעזרה.","הלכות תמידין ומוספין. יש בכללן תשע עשרה מצוות – שמונה עשרה מצוות עשה, ואחת מצות לא תעשה; וזה הוא פרטן: (א) להקריב שני כבשים בכל יום עולות; (ב) להדליק אש על המזבח בכל יום; (ג) שלא לכבותה; (ד) להרים את הדשן בכל יום; (ה) להקטיר קטורת בכל יום; (ו) להדליק נרות בכל יום; (ז) שיקריב כוהן גדול מנחה בכל יום, והיא הנקראת חביתין; (ח) להוסיף שני כבשים עולות בשבת; (ט) לעשות לחם הפנים; (י) מוסף ראשי חודשים; (יא) מוסף הפסח; (יב) להקריב עומר התנופה; (יג) לספור כל איש ואיש שבעה שבועות מיום הקרבת העומר; (יד) מוסף עצרת; (טו) להביא שתי הלחם עם הקרבנות הבאות בגלל הלחם ביום עצרת; (טז) מוסף ראש השנה; (יז) מוסף יום צום; (יח) מוסף החג; (יט) מוסף שמיני עצרת.","הלכות פסולי המוקדשין. יש בכללן שמונה מצוות – שתי מצוות עשה, ושש מצוות לא תעשה; וזה הוא פרטן: (א) שלא לאכול קודשים שנפסלו ושהוטל בהם מום; (ב) שלא לאכול פיגול; (ג) שלא יותיר קודשים לאחר זמנן; (ד) שלא יאכל נותר; (ה) שלא יאכל קודשים שנטמאו; (ו) שלא יאכל אדם שנטמא את הקודשים; (ז) לשרוף את הנותר; (ח) לשרוף את הטמא.","הלכות עבודת יום הכיפורים. מצות עשה אחת – והיא שיעשה מעשה יום הכיפורים כולו על הסדר כמו שכתוב בפרשת אחרי מות, הקרבנות והווידויין ושילוח השעיר ושאר העבודה.","הלכות מעילה. יש בכללן שלוש מצוות – אחת מצות עשה, ושתיים מצוות לא תעשה; וזה הוא פרטן: (א) לשלם המועל אשר חטא בתוספת חומש וקרבן, וזה הוא דין המועל; (ב) שלא לעבוד בקודשים; (ג) שלא לגוז קודשים.","נמצאו כל המצוות הנכללות בספר זה, מאה ושלוש – מהם שבע וארבעים מצוות עשה, ושש וחמישים מצוות לא תעשה."],"Mishneh Torah, Ownerless Property and Gifts 8":["הַסוּמָא אוֹ הַפִּסֵּחַ. אוֹ הַגִּדֵּם. אוֹ הַחוֹשֵׁשׁ בְּרֹאשׁוֹ. אוֹ בְּעֵינוֹ. אוֹ בְּיָדוֹ אוֹ בְּרַגְלוֹ וְכַיּוֹצֵא בָּהֶן הֲרֵי הוּא כְּבָרִיא לְכָל דְּבָרָיו בְּמִקָּחוֹ אוֹ בְּמִמְכָּרוֹ וּמַתְּנוֹתָיו:","אֲבָל הַחוֹלֶה שֶׁתָּשַׁשׁ כֹּחַ כָּל הַגּוּף. וְכָשַׁל כֹּחוֹ מֵחֲמַת הַחֹלִי עַד שֶׁאֵינוֹ יָכוֹל לְהַלֵּךְ עַל רַגְלוֹ בַּשּׁוּק וַהֲרֵי הוּא נוֹפֵל עַל הַמִּטָּה. הוּא [הַנִּקְרָא] שְׁכִיב מֵרַע. וּמִשְׁפְּטֵי מַתְּנוֹתָיו אֵינָם כְּמַתְּנַת בָּרִיא. כֵּיצַד. שְׁכִיב מֵרַע שֶׁצִּוָּה וְאָמַר לִתֵּן לִפְלוֹנִי כָּךְ וְכָךְ בֵּין בְּחל בֵּין בְּשַׁבָּת. בֵּין כָּתַב בֵּין לֹא כָּתַב. זָכוּ הַכּל כְּשֶׁיָּמוּת בְּכָל מַה שֶּׁנָּתַן לָהֶם וְאֵינוֹ צָרִיךְ קִנְיָן. שֶׁדִּבְרֵי שְׁכִיב מֵרַע כִּכְתוּבִין וְכִמְסוּרִין הֵן. וְדָבָר זֶה מִדִּבְרֵי סוֹפְרִים. וְאַף עַל פִּי שֶׁאֵינוֹ אֶלָּא מִדִּבְרֵיהֶם עָשׂוּ אוֹתָהּ כְּשֶׁל תּוֹרָה. כְּדֵי שֶׁלֹּא תִּטָּרֵף דַּעְתּוֹ עָלָיו כְּשֶׁיֵּדַע שֶׁאֵין דְּבָרָיו קַיָּמִים:","לְפִיכָךְ אִם אָמַר קְנוּ מִמֶּנִּי. אֲפִלּוּ בְּשַׁבָּת קוֹנִין מִמֶּנּוּ, שֶׁזֶּה הַקִּנְיָן אֵינוֹ צָרִיךְ:","וְאֵין שְׁכִיב מֵרַע צָרִיךְ לוֹמַר אַתֶּם עֵדַי. אֶלָּא כָּל הַשּׁוֹמֵעַ אֶת דְּבָרָיו הֲרֵי זֶה עֵד. שֶׁאֵין אָדָם מְשַׁטֶּה בִּשְׁעַת מִיתָה:","שְׁכִיב מֵרַע שֶׁצִּוָּה לָתֵת מַתָּנָה לְעֻבָּר שֶׁבִּמְעֵי אִמּוֹ. זָכָה הָעֻבָּר מִפְּנֵי שֶׁדַּעְתּוֹ שֶׁל אָדָם קְרוֹבָה אֵצֶל בְּנוֹ כְּמוֹ שֶׁבֵּאַרְנוּ:","אָמַר אִם יָלְדָה אִשְׁתִּי זָכָר יִטּל מָנֶה וְאִם נְקֵבָה מָאתַיִם. וְיָלְדָה זָכָר. נוֹטֵל מָנֶה. יָלְדָה נְקֵבָה נוֹטֶלֶת מָאתַיִם. יָלְדָה זָכָר וּנְקֵבָה הַזָּכָר נוֹטֵל מָנֶה וְהַנְּקֵבָה מָאתַיִם. יָלְדָה טֻמְטוּם וְאַנְדְּרוֹגִינוּס נוֹטֵל כַּפָּחוּת שֶׁבִּשְׁנֵיהֶם:","שְׁכִיב מֵרַע שֶׁאָמְרוּ לוֹ נְכָסָיו לְמִי. וְאָמַר לָהֶם דּוֹמֶה שֶׁיֵּשׁ לוֹ בֵּן אוֹ שֶׁאִשְׁתּוֹ מְעֻבֶּרֶת. עַכְשָׁו שֶׁאֵין לוֹ בֵּן אוֹ שֶׁאֵין אִשְׁתּוֹ מְעֻבֶּרֶת נְכָסָיו לִפְלוֹנִי. וְנוֹדַע שֶׁיֵּשׁ לוֹ בֵּן אוֹ שֶׁהָיְתָה אִשְׁתּוֹ מְעֻבֶּרֶת אַף עַל פִּי שֶׁהִפִּילָה אוֹ מֵת הַבֵּן אַחַר כָּךְ. אֵין מַתְּנָתוֹ מַתָּנָה:","מַתְּנַת שְׁכִיב מֵרַע אֵינָהּ קוֹנָה אֶלָּא לְאַחַר מִיתָה. וְאֵין אַחֵר זוֹכֶה בַּדָּבָר שֶׁצִּוָּה לוֹ בֵּין מְקַרְקְעִין בֵּין מִטַּלְטְלִין אֶלָּא לְאַחַר מִיתָה:","לְפִיכָךְ מוֹצִיאִין לִכְתֻבַּת הָאִשָּׁה וּמְזוֹן הָאַלְמָנָה וְהַבָּנוֹת מִיַּד אֵלּוּ שֶׁצִּוָּה לָתֵת לָהֶם. שֶׁהֲרֵי בְּמִיתָתוֹ נִתְחַיְּבוּ הַנְּכָסִים בִּכְתֻבָּה וּבִמְזוֹנוֹת. וְאֵלּוּ שֶׁנָּתַן לָהֶם לֹא יִקְנוּ אֶלָּא לְאַחַר מִיתָה:","מַתְּנַת שְׁכִיב מֵרַע שֶׁכָּתוּב בָּהּ קִנְיָן. בֵּין שֶׁהָיְתָה בְּמִקְצָת נְכָסָיו בֵּין שֶׁהָיְתָה בְּכָל נְכָסָיו. חוֹשְׁשִׁין לָהּ שֶׁמָּא לֹא גָּמַר לְהַקְנוֹתוֹ אֶלָּא בִּשְׁטָר. וְהוֹאִיל וּמַתָּנָה זוֹ לֹא תִּקָּנֶה אֶלָּא לְאַחַר מִיתָה. אֵין שְׁטָר לְאַחַר מִיתָה וַהֲרֵי הַמַּתָּנָה בְּטֵלָה:","וְאִם קָנוּ מִמֶּנּוּ כְּדֵי לְיַפּוֹת כֹּחַ הַמְקַבֵּל. כְּגוֹן שֶׁכָּתוּב וְקָנִינוּ מִמֶּנּוּ מוֹסִיף עַל מַתָּנָה זוֹ. הֲרֵי הִיא קַיֶּמֶת:","שְׁכִיב מֵרַע שֶׁאָמַר כִּתְבוּ וּתְנוּ לִפְלוֹנִי מָנֶה. וּמֵת קֹדֶם שֶׁיִּכְתְּבוּ וְיִתְּנוּ לוֹ. אֵין כּוֹתְבִין וְאֵין נוֹתְנִין. שֶׁמָּא לֹא גָּמַר לְהַקְנוֹתוֹ אֶלָּא בִּשְׁטָר וְאֵין שְׁטָר לְאַחַר מִיתָה:","וְאִם אָמַר כִּתְבוּ. כְּדֵי לְיַפּוֹת כֹּחַ הַמְקַבֵּל. כְּגוֹן שֶׁאָמַר תְּנוּ מָנֶה לִפְלוֹנִי וְאָמַר וְאַף כִּתְבוּ וּתְנוּ לוֹ. הֲרֵי אֵלּוּ כּוֹתְבִין וְחוֹתְמִין וְנוֹתְנִין לְאַחַר מִיתָה:","שְׁכִיב מֵרַע שֶׁכָּתַב כָּל נְכָסָיו מַתָּנָה סְתָם וְלֹא שִׁיֵּר כְּלוּם. אִם עָמַד חוֹזֵר. וַאֲפִלּוּ קָנוּ מִיָּדוֹ כְּדֵי לְיַפּוֹת אֶת כֹּחוֹ. בֵּין שֶׁהִקְנָה כָּל נְכָסָיו לְאֶחָד בֵּין שֶׁכְּתָבָם לִשְׁנַיִם. שֶׁאֹמֶד דַּעַת הוּא שֶׁלֹּא נָתַן זֶה הַכּל אֶלָּא שֶׁנִּתְכַּוֵּן שֶׁלֹּא יִקְנוּ כְּלוּם אֶלָּא לְאַחַר מוֹתוֹ:","שִׁיֵּר כְּלוּם לְעַצְמוֹ בֵּין קַרְקַע בֵּין מִטַּלְטְלִין. הֲרֵי זוֹ מַתָּנָה בְּמִקְצָת וּסְתָמָהּ כְּמַתְּנַת בָּרִיא שֶׁקּוֹנֶה מִזְּמַן הַכְּתִיבָה. לְפִיכָךְ אֵינוֹ חוֹזֵר. וְהוּא שֶׁקָּנוּ מִיָּדוֹ. שֶׁמַּתְּנַת שְׁכִיב מֵרַע בְּמִקְצָת צְרִיכָה קִנְיָן. בֵּין עָמַד בֵּין לֹא עָמַד:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁנָּתַן סְתָם. שֶׁהֲרֵי אָנוּ אוֹמְדִין דַּעְתּוֹ וְאוֹמְרִין הוֹאִיל וְשִׁיֵּר לֹא נִתְכַּוֵּן אֶלָּא לְהַקְנוֹת לוֹ מֵחַיִּים בְּמַתְּנַת בָּרִיא:","אֲבָל אִם נָתַן לוֹ הַמִּקְצָת בְּפֵרוּשׁ בְּמַתְּנַת שְׁכִיב מֵרַע שֶׁאֵינוֹ אֶלָּא לְאַחַר מִיתָה אֵינוֹ צָרִיךְ קִנְיָן. וְאִם עָמַד חוֹזֵר. וְאִם לֹא עָמַד קָנָה זֶה הַמִּקְצָת. וְאִם הָיָה בָּהּ קִנְיָן לֹא קָנָה אֶלָּא אִם כֵּן הָיָה מְיַפֶּה כֹּחוֹ כְּמוֹ שֶׁבֵּאַרְנוּ:","אַל תִּטְעֶה בִּשְׁכִיב מֵרַע שֶׁכָּתַב כָּל נְכָסָיו וּפֵרֵשׁ שֶׁנָּתַן הַכּל מֵעַכְשָׁו וְהִקְנָה מֵחַיִּים. שֶׁאֵין זֶה מַתְּנַת שְׁכִיב מֵרַע אֶלָּא כִּשְׁאָר כָּל מַתְּנוֹת הַבְּרִיאִים. שֶׁאִם הִגִּיעַ הַשְּׁטָר לְיַד הַמְקַבֵּל אוֹ שֶׁקָּנוּ מִיַּד הַנּוֹתֵן קָנָה הַכּל וְאֵין יָכוֹל לַחְזֹר בּוֹ:","הַנּוֹתֵן מַתָּנָה כְּשֶׁהוּא שְׁכִיב מֵרַע וְכָתַב בָּהּ בַּחַיִּים וּבַמָּוֶת אוֹ מֵחַיִּים וּבַמָּוֶת. בֵּין בַּכּל בֵּין בְּמִקְצָת. הוֹאִיל וְכָתוּב בּוֹ וּבַמָּוֶת הֲרֵי זוֹ מַתְּנַת שְׁכִיב מֵרַע. שֶׁזּוֹ שֶׁכָּתוּב בָּהּ וּבַמָּוֶת שֶׁלֹּא יִקְנֶה אֶלָּא לְאַחַר מִיתָה. וְזֶה שֶׁכָּתוּב בָּהּ מֵחַיִּים סִימָן לְיַשֵּׁב אֶת דַּעְתּוֹ שֶׁיִּחְיֶה מֵחֹלִי זֶה:","שְׁכִיב מֵרַע שֶׁנָּתַן הַנְּכָסִים שֶׁהַדָּבָר גָּלוּי שֶׁהֵן כָּל נְכָסִים שֶׁיֵּשׁ לוֹ. הֲרֵי זֶה כְּמַתָּנָה בְּמִקְצָת וְאִם קָנוּ מִיָּדוֹ וְעָמַד אֵינוֹ חוֹזֵר. חוֹשְׁשִׁין אָנוּ שֶׁמָּא נִשְׁאֲרוּ לוֹ נְכָסִים אֲחֵרִים בִּמְדִינַת הַיָּם. עַד שֶׁיֹּאמַר כָּל נְכָסַי שֶׁהֵן אֵלּוּ אוֹ שֶׁהָיָה מֻחְזָק שֶׁאֵין לוֹ נְכָסִים אֶלָּא אֵלּוּ. וְאַחַר כָּךְ תִּהְיֶה הַמַּתָּנָה בַּכּל:","שְׁכִיב מֵרַע שֶׁכָּתַב כָּל נְכָסָיו לַאֲחֵרִים. רוֹאִין. אִם כִּמְחַלֵּק כְּתָבָם. מֵת קָנוּ כֻּלָּן. עָמַד חוֹזֵר בְּכֻלָּן. וְאִם כְּנִמְלַךְ אַחַר שֶׁשִּׁיֵּר חָזַר וְכָתַב וְקָנוּ מִיָּדוֹ עַל כָּל אֶחָד וְאֶחָד. מֵת קָנוּ כֻּלָּן. עָמַד אֵינוֹ חוֹזֵר אֶלָּא בָּאַחֲרוֹן שֶׁהֲרֵי נָתַן לוֹ כָּל הַנְּכָסִים הַנִּשְׁאָרִים:","הַכּוֹתֵב כָּל נְכָסָיו לְעַבְדּוֹ וְעָמַד חוֹזֵר בַּנְּכָסִים וְאֵינוֹ חוֹזֵר בָּעֶבֶד. שֶׁהֲרֵי יָצָא עָלָיו שֵׁם בֶּן חוֹרִין:","שְׁכִיב מֵרַע שֶׁצִּוָּה מֵחֲמַת מִיתָה. כְּגוֹן שֶׁהָיְתָה דַּעְתּוֹ נוֹטָה שֶׁהוּא מֵת וַדַּאי. וְנִכָּר דָּבָר זֶה מִכְּלַל דְּבָרָיו. אַף עַל פִּי שֶׁקָּנוּ מִיָּדוֹ בְּמִקְצָת אִם עָמַד חוֹזֵר:","וְהַמְפָרֵשׁ בַּיָּם. וְהַיּוֹצֵא בְּשַׁיָּרָא. וְהַיּוֹצֵא בְּקוֹלָר. וְהַמְסֻכָּן וְהוּא שֶׁקָּפַץ עָלָיו הַחֹלִי וְהִכְבִּיד עָלָיו חָלְיוֹ. כָּל אֶחָד מֵאַרְבַּעְתָּן כִּמְצַוֶּה מֵחֲמַת מִיתָה. וַהֲרֵי דְּבָרָיו כִּכְתוּבִין וְכִמְסוּרִין וּמְקַיְּמִין אוֹתָן אִם מֵת. וְאִם נִצַּל וְעָמַד אֲפִלּוּ קָנוּ מִיָּדוֹ בְּמִקְצָת חוֹזֵר. כְּדִין כָּל מְצַוֶּה מֵחֲמַת מִיתָה:","שְׁכִיב מֵרַע שֶׁנִּתַּק מֵחֹלִי לְחֹלִי. אִם לֹא עָמַד וְלֹא הָלַךְ עַל מִשְׁעַנְתּוֹ בַּשּׁוּק מַתְּנָתוֹ מַתָּנָה:","עָמַד בֵּין הַחֹלִי שֶׁצִּוָּה בּוֹ וּבֵין הַחֹלִי שֶׁמֵּת מִמֶּנּוּ וְהָלַךְ עַל מִשְׁעַנְתּוֹ. אוֹמְדִין אוֹתוֹ עַל פִּי רוֹפְאִים. אִם מֵחֲמַת חֹלִי הָרִאשׁוֹן מֵת מַתְּנָתוֹ קַיֶּמֶת וְאִם לָאו אֵין מַתְּנָתוֹ קַיֶּמֶת. וְאִם הָלַךְ בַּשּׁוּק בְּלֹא מִשְׁעֶנֶת אֵינוֹ צָרִיךְ אֹמֶד אֶלָּא בָּטְלוּ מַתְּנוֹתָיו הָרִאשׁוֹנוֹת:","מַתְּנַת שְׁכִיב מֵרַע שֶׁאֵין כָּתוּב בָּהּ שֶׁמִּתּוֹךְ הַחֹלִי הַזֶּה שֶׁצִּוָּה בּוֹ מֵת וְאֵין הָעֵדִים מְצוּיִין לִשְׁאל לָהֶם. אַף עַל פִּי שֶׁהֲרֵי זֶה הַמְצַוֶּה מֵת. הֲרֵי הַמַּתָּנָה בְּטֵלָה. שֶׁאֵין מִיתָתוֹ רְאָיָה. שֶׁמָּא מֵחֹלִי שֶׁנָּתַן בּוֹ הַמַּתָּנָה נִרְפָּא וְאַחַר כָּךְ חָלָה חֹלִי אַחֵר וּמֵת. לְפִיכָךְ הַנְּכָסִים בְּחֶזְקַת הַיּוֹרְשִׁין. עַד שֶׁיָּבִיא רְאָיָה שֶׁמִּתּוֹךְ הַחֹלִי הַזֶּה שֶׁנָּתַן בּוֹ מַתָּנָה זוֹ מֵת:"],"Mishneh Torah, Plaintiff and Defendant 1":["הַטוֹעֵן אֶת חֲבֵרוֹ בְּמִטַּלְטְלִין וְהוֹדָה לוֹ בְּמִקְצָת הֲרֵי זֶה מְשַׁלֵּם מַה שֶּׁהוֹדָה בּוֹ וְנִשְׁבָּע עַל הַשְּׁאָר מִן הַתּוֹרָה שֶׁנֶּאֱמַר (שמות כב ח) \"אֲשֶׁר יֹאמַר כִּי הוּא זֶה\". וְכֵן אִם כָּפַר בַּכּל וְאוֹמֵר לֹא הָיוּ דְּבָרִים מֵעוֹלָם וְעֵד אֶחָד מֵעִיד [שֶׁהוּא חַיָּב לוֹ] הֲרֵי זֶה נִשְׁבָּע מִן הַתּוֹרָה. ומִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁכָּל מָקוֹם שֶׁשְּׁנַיִם מְחַיְּבִין אוֹתוֹ מָמוֹן אֶחָד מְחַיְּבוֹ שְׁבוּעָה. וְכֵן לָמְדוּ מִפִּי הַשְּׁמוּעָה שֶׁעֵד אֶחָד לְכָל עָוֹן וּלְכָל חַטָּאת אֵינוֹ קָם אֲבָל קָם הוּא לִשְׁבוּעָה:","אֵין לְךָ מְחֻיָּב שְׁבוּעָה מִן הַתּוֹרָה חוּץ מִשְּׁלֹשָׁה. מִי שֶׁהוֹדָה בְּמִקְצָת הַמִּטַּלְטְלִין. וּמִי שֶׁחִיְּבוֹ עֵד אֶחָד. וְהַשּׁוֹמֵר. שֶׁהֲרֵי נֶאֱמַר בְּשׁוֹמֵר (שמות כב י) \"שְׁבֻעַת ה' תִּהְיֶה בֵּין שְׁנֵיהֶם\". וּכְבָר בֵּאַרְנוּ שְׁבוּעַת הַשּׁוֹמְרִין בְּהִלְכוֹת שְׂכִירוּת. וְכָל אֶחָד מִן הַשְּׁלֹשָׁה נִשְׁבָּע וְנִפְטָר מִלְּשַׁלֵּם. אֲבָל כָּל הַנִּשְׁבָּעִין וְנוֹטְלִין כְּגוֹן שָׂכִיר וְנֶחְבָּל וּפוֹגֵם אֶת שְׁטָרוֹ וְכַיּוֹצֵא בּוֹ. וְכֵן כָּל הַנִּשְׁבָּעִין בְּטַעֲנַת סָפֵק כְּגוֹן הַשֻּׁתָּפִין וְהָאֲרִיסִין. כֻּלָּן נִשְׁבָּעִין בְּתַקָּנַת חֲכָמִים. וְכָל אֵלּוּ הַשְּׁבוּעוֹת אַף עַל פִּי שֶׁהֵן מִדִּבְרֵי סוֹפְרִים הֲרֵי הֵן כְּעֵין שֶׁל תּוֹרָה בִּנְקִיטַת חֵפֶץ:","הַטּוֹעֵן מִטַּלְטְלִין עַל חֲבֵרוֹ וְכָפַר בַּכּל וְאָמַר לֹא הָיוּ דְּבָרִים מֵעוֹלָם. אוֹ שֶׁהוֹדָה בְּמִקְצָת וּנְתָנוֹ מִיָּד וְאָמַר אֵין לְךָ בְּיָדִי אֶלָּא זֶה וְהֵילָךְ. אוֹ שֶׁאָמַר אֱמֶת שֶׁהָיָה לְךָ אֶצְלִי אֲבָל מָחַלְתָּ לִי אוֹ נָתַתָּ לִי אוֹ מָכַרְתָּ לִי אוֹ הֶחְזַרְתִּי לְךָ. אוֹ שֶׁטְּעָנוֹ חִטִּים וְהוֹדָה לוֹ בִּשְׂעוֹרִים. בְּכָל אֵלּוּ פָּטוּר מִשְּׁבוּעַת הַתּוֹרָה. אֲבָל חַכְמֵי הַגְּמָרָא תִּקְּנוּ שֶׁיִּשָּׁבַע הַנִּתְבָּע בְּכָל אֵלּוּ שְׁבוּעַת הֶסֵּת וְיִפָּטֵר. וְאֵינוֹ כְּעֵין שֶׁל תּוֹרָה לְפִי שֶׁאֵין בָּהֶן נְקִיטַת חֵפֶץ. וּכְבָר בֵּאַרְנוּ דֶּרֶךְ שְׁבוּעָה שֶׁל תּוֹרָה וְדֶרֶךְ שְׁבוּעַת הֶסֵּת בְּהִלְכוֹת שְׁבוּעוֹת:","כָּל מִי שֶׁנִּתְחַיֵּב שְׁבוּעָה מִן הַתּוֹרָה הֲרֵי זֶה נִשְׁבָּע וְנִפְטָר. וְאִם לֹא רָצָה לְהִשָּׁבַע יוֹרְדִין לִנְכָסָיו וְגוֹבִין מֵהֶם כָּל מַה שֶּׁתָּבַע חֲבֵרוֹ עָלָיו. שֶׁהֲרֵי הַתּוֹבֵעַ אוֹמֵר לוֹ אֵינִי זָז מִדִּין תּוֹרָה אוֹ הִשָּׁבַע אוֹ תֵּן לִי. וְיֵשׁ לוֹ לְהַחֲרִים עַל מִי שֶׁטָּעַן עָלָיו דָּבָר שֶׁאֵינוֹ כֵּן וְנוֹתֵן. אֲבָל מִי שֶׁנִּתְחַיֵּב שְׁבוּעָה מִדִּבְרֵיהֶן אִם הָיָה מִן הַנִּשְׁבָּעִין וְנוֹטְלִין אֵינוֹ יָכוֹל לְהַפֵּךְ אֶת הַשְּׁבוּעָה שֶׁהֲרֵי הַנִּתְבָּע אוֹמֵר לוֹ הִשָּׁבַע וְטל כְּמוֹ שֶׁתִּקְּנוּ לְךָ. וְאִם לֹא רָצָה לְהִשָּׁבַע יֵלֵךְ לוֹ. וְהוֹרוּ רַבּוֹתַי שֶׁאִם אָמַר הַתּוֹבֵעַ אֵינִי רוֹצֶה בְּתַקָּנָה זוֹ שֶׁתִּקְּנוּ לִי חֲכָמִים אֶלָּא הֲרֵינִי כִּשְׁאָר הַתּוֹבְעִים הֲרֵי זֶה מַשְׁבִּיעַ אֶת הַנִּתְבָּע הֶסֵּת. וְאִם רָצָה לְהָפְכָהּ עַל הַתּוֹבֵעַ מְחַיְּבִין אֶת הַתּוֹבֵעַ לְהִשָּׁבַע אוֹ יֵלֵךְ לוֹ:","הָיָה מְחֻיָּב שְׁבוּעָה מִדִּבְרֵיהֶם מִן הַנִּשְׁבָּעִין וְנִפְטָרִין כְּגוֹן הַנִּשְׁבָּעִין עַל טַעֲנַת סָפֵק אוֹ מִן הַנִּשְׁבָּעִין הֶסֵּת וְלֹא רָצָה לְהִשָּׁבַע מְשַׁמְּתִין אוֹתוֹ שְׁלֹשִׁים יוֹם אִם לֹא בָּא וְלֹא תָּבַע נִדּוּיוֹ מַלְקִין אוֹתוֹ מַכַּת מַרְדּוּת. וְכָל מִי שֶׁחָלָה עָלָיו שַׁמְתָּא שְׁלֹשִׁים יוֹם מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת וְאַחַר כָּךְ מַתִּירִין נִדּוּיוֹ. וְאֵין יוֹרְדִין לִנְכָסָיו לְפִי שֶׁאֵינוֹ מְחֻיָּב שְׁבוּעָה מִן הַתּוֹרָה:","כָּל הַמְחֻיָּב שְׁבוּעַת הֶסֵּת אִם רָצָה לַהֲפֹךְ הַשְּׁבוּעָה עַל הַתּוֹבֵעַ הֲרֵי הַתּוֹבֵעַ נִשְׁבָּע הֶסֵּת וְנוֹטֵל מֵחֲבֵרוֹ. וְאֵין לְךָ מִי שֶׁנִּשְׁבָּע הֶסֵּת וְנוֹטֵל מֵחֲבֵרוֹ אֶלָּא זֶה שֶׁנֶּהְפְּכָה עָלָיו שְׁבוּעַת הֶסֵּת. וְאֵין לְךָ שְׁבוּעָה שֶׁתֵּהָפֵךְ אֶלָּא שְׁבוּעַת הֶסֵּת בִּלְבַד. אֲבָל שְׁבוּעָה שֶׁל תּוֹרָה אוֹ שֶׁל דִּבְרֵיהֶם שֶׁהִיא כְּעֵין שֶׁל תּוֹרָה אֵין הוֹפְכִין שְׁבוּעָתָן:","אֵין מַשְׁבִּיעִין שְׁבוּעַת הֶסֵּת אֶלָּא עַל טַעֲנַת וַדַּאי אֲבָל עַל טַעֲנַת סָפֵק פָּטוּר. כֵּיצַד. כִּמְדֻמֶּה לִי שֶׁיֵּשׁ לִי אֶצְלְךָ מָנֶה אוֹ שֶׁאָמַר מָנֶה הִלְוֵיתִיךָ וְכִמְדֻמֶּה לִי שֶׁלֹּא פְּרַעְתַּנִי. אָמַר לִי אַבָּא שֶׁיֵּשׁ לִי אֶצְלְךָ מָנֶה אוֹ צִוָּה לִי בִּפְנֵי עֵדִים שֶׁיֵּשׁ לִי אֶצְלְךָ מָנֶה. דָּבָר פְּלוֹנִי נִגְנַב מִבֵּיתִי וְלֹא הָיָה שָׁם אֶלָּא אַתָּה קָרוֹב בְּעֵינֵי שֶׁאַתָּה גְּנָבַתּוּ. חִשַּׁבְתִּי מָעוֹת וּמָצָאתִי חָסֵר שֶׁמָּא אַתָּה הִטְעֵיתַנִי בְּחֶשְׁבּוֹן. וְהַנִּתְבָּע אוֹמֵר אֵין לְךָ בְּיָדִי כְּלוּם הֲרֵי זֶה פָּטוּר אַף מִשְּׁבוּעַת הֶסֵּת. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","כּוֹר חִטִּים יֵשׁ לִי בְּיָדְךָ בְּוַדַּאי וְהַנִּתְבָּע אוֹמֵר אֵינִי יוֹדֵעַ שֶׁמָּא יֵשׁ לְךָ שֶׁמָּא אֵין לְךָ הֲרֵי הַנִּתְבָּע יִשָּׁבַע שְׁבוּעַת הֶסֵּת שֶׁאֵינוֹ יוֹדֵעַ וְנִפְטָר. לְפִי שֶׁלֹּא חִיֵּב עַצְמוֹ בְּוַדַּאי. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. כּוֹר חִטִּים יֵשׁ לִי בְּיָדְךָ בְּוַדַּאי וְהַנִּתְבָּע אוֹמֵר אֵינִי יוֹדֵעַ אִם חִטִּים הוּא אוֹ שְׂעוֹרִים הֲרֵי זֶה נִשְׁבָּע הֶסֵּת שֶׁאֵינוֹ יוֹדֵעַ וּמְשַׁלֵּם שְׂעוֹרִין. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","מָנֶה יֵשׁ לִי בְּיָדְךָ בְּוַדַּאי וְהַנִּתְבָּע אוֹמֵר כֵּן הָיָה לְךָ בְּיָדִי אֲבָל אֵינִי יוֹדֵעַ אִם הֶחְזַרְתִּי לְךָ אוֹ עֲדַיִן לֹא הֶחְזַרְתִּי לְךָ חַיָּב לְשַׁלֵּם וְלֹא יִשָּׁבַע הַתּוֹבֵעַ כְּלָל אֲפִלּוּ שְׁבוּעַת הֶסֵּת. מִפְּנֵי שֶׁהוּא יוֹדֵעַ בְּוַדַּאי שֶׁהוּא חַיָּב וַהֲרֵי זֶה טוֹעֵן אוֹתוֹ טַעֲנַת וַדַּאי וְנִסְתַּפֵּק אִם נִפְטַר אוֹ לֹא נִפְטַר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. אֲבָל אִם אֵין לוֹ תּוֹבֵעַ וְהוֹדָה מֵעַצְמוֹ וְאָמַר גְּזַלְתִּיךָ אוֹ הִלְוֵיתַנִי מָנֶה. אָבִיךָ הִפְקִיד אֶצְלִי מָנֶה וְאֵינִי יוֹדֵעַ אִם הֶחְזַרְתִּיו אוֹ לֹא הֶחְזַרְתִּיו. אֵינוֹ חַיָּב לְשַׁלֵּם. וְאִם בָּא לָצֵאת יְדֵי שָׁמַיִם חַיָּב לְשַׁלֵּם:","מָנֶה לִי בְּיָדְךָ. אֵין לְךָ בְּיָדִי כְּלוּם. הִשָּׁבַע הֶסֵּת וְלֵךְ. הִשָּׁבַע אַתָּה הֶסֵּת וְטל. וְאָמַר הַתּוֹבֵעַ אֵינִי רוֹצֶה לְהִשָּׁבַע הֲרֵי הַנִּתְבָּע אוֹמֵר לוֹ הִשָּׁבַע וְטל אוֹ תֵּלֵךְ בְּלֹא כְּלוּם. וְאֵין שָׁם הִפּוּךְ אַחֵר וְיֵשׁ לוֹ לְהַחֲרִים סְתָם עַל מִי שֶׁהוּא חַיָּב לִי וְלֹא יִתֵּן לִי:","הוֹרוּ רַבּוֹתַי שֶׁכָּל מִי שֶׁנִּתְחַיֵּב שְׁבוּעָה בֵּין שֶׁל תּוֹרָה בֵּין שֶׁל דִּבְרֵיהֶם אֲפִלּוּ הֶסֵּת. יֵשׁ לוֹ לְהַחֲרִים סְתָם קֹדֶם שֶׁיִּשָּׁבַע עַל מִי שֶׁיִּטְעֹן עָלָיו דָּבָר שֶׁאֵינוֹ חַיָּב בּוֹ כְּדֵי שֶׁיַּשְׁבִּיעַ אוֹתוֹ בְּחִנָּם וְיַעֲנֶה הַמַּשְׁבִּיעַ אָמֵן וְאַחַר יִשָּׁבַע. וְתַקָּנָה טוֹבָה לְבַעֲלֵי דִּינִין כְּדֵי שֶׁיִּמָּנְעוּ מִטַּעֲנַת שֶׁקֶר וְלֹא יִגְרְמוּ לְהוֹצִיא שֵׁם שָׁמַיִם לְבַטָּלָה וְלֹא יַשִּׂיאוֹ שֵׁמַע שָׁוְא:","כָּל מִי שֶׁנִּתְחַיֵּב שְׁבוּעָה בֵּין שֶׁל תּוֹרָה בֵּין שֶׁל דִּבְרֵיהֶם מְגַלְגֵּל עָלָיו הַמַּשְׁבִּיעַ כָּל מַה שֶּׁיִּרְצֶה מִדְּבָרִים שֶׁאִם יוֹדֶה בָּהֶן יִתְחַיֵּב מָמוֹן. וְעַד הֵיכָן כֹּחַ גִּלְגּוּל עַד שֶׁיֹּאמַר וּבִכְלַל שְׁבוּעָה זוֹ שֶׁלֹּא נִמְכַּרְתָּ לִי בְּעֶבֶד עִבְרִי וַעֲדַיִן עַבְדִּי אַתָּה. וּכְבָר בֵּאַרְנוּ שֶׁאֵין מְגַלְגְּלִין עַל הַשָּׂכִיר:","מִי שֶׁנִּתְחַיֵּב שְׁבוּעָה אֲפִלּוּ הֶסֵּת וְהִתְחִיל הַתּוֹבֵעַ לְגַלְגֵּל עָלָיו דְּבָרִים אֲחֵרִים שֶׁלֹּא טָעַן אוֹתָם. וְרָאָה הַנִּתְבָּע כָּךְ וְאָמַר אֵינִי רוֹצֶה לְהִשָּׁבַע אֶלָּא הֲרֵינִי מְשַׁלֵּם הַטַּעֲנָה הָרִאשׁוֹנָה שֶׁנִּתְחַיַּבְתִּי עַל כְּפִירָתָהּ שְׁבוּעָה. אֵין שׁוֹמְעִין לוֹ אֶלָּא אוֹמְרִים לַנִּתְבָּע אוֹ תֵּן לוֹ כָּל מַה שֶּׁגִּלְגֵּל עָלֶיךָ מִטְּעָנוֹת הַוַּדָּאִיּוֹת אוֹ הִשָּׁבַע וְהִפָּטֵר:","הַטּוֹעֵן אֶת חֲבֵרוֹ טְעָנוֹת הַרְבֵּה אֵין מַשְׁבִּיעִין אוֹתוֹ עַל כָּל טַעֲנָה וְטַעֲנָה אֶלָּא שְׁבוּעָה אַחַת עַל הַכּל. נִתְחַיֵּב שְׁתֵּי שְׁבוּעוֹת עַל שְׁתֵּי טְעָנוֹת קַלָּה וַחֲמוּרָה. מַשְׁבִּיעִין אוֹתוֹ עַל הַחֲמוּרָה וּמְגַלְגְּלִין בָּהּ שְׁאָר דְּבָרִים:","כָּל הַטּוֹעֵן אֶת חֲבֵרוֹ טַעֲנָה שֶׁאִם הוֹדָה אֵינוֹ חַיָּב לְשַׁלֵּם מָמוֹן. אַף עַל פִּי שֶׁכָּפַר אֵין מְחַיְּבִין אוֹתוֹ שְׁבוּעַת הֶסֵּת וְלֹא חֵרֶם סְתָם. כֵּיצַד. אָמַרְתָּ שֶׁתִּתֵּן לִי מָנֶה. לֹא הָיוּ דְּבָרִים מֵעוֹלָם. אֵין מַשְׁבִּיעִין אוֹתוֹ הֶסֵּת וְלֹא חֵרֶם שֶׁאִלּוּ הוֹדָה בְּדָבָר זֶה אֵינוֹ חַיָּב כְּלוּם. אַתָּה קִלַּלְתָּ אוֹתִי אַתָּה הוֹצֵאתָ עָלַי שֵׁם רַע לֹא הָיוּ דְּבָרִים מֵעוֹלָם אֵין מַחְרִימִין עַל זֶה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה מִדְּבָרִים אֵלּוּ:","אַתָּה חָבַלְתָּ בִּי לֹא הָיוּ דְּבָרִים מֵעוֹלָם הֲרֵי זֶה נִשְׁבָּע הֶסֵּת שֶׁאַף עַל פִּי שֶׁאֵינוֹ מְשַׁלֵּם קְנָס עַל פִּי עַצְמוֹ מְשַׁלֵּם שֶׁבֶת וְרִפּוּי וּבשֶׁת. אַתָּה בִּיַּשְׁתַּנִי לֹא הָיוּ דְּבָרִים מֵעוֹלָם. אִם הָיוּ בְּמָקוֹם שֶׁגּוֹבִין בּוֹ קְנָסוֹת הֲרֵי זֶה נִשְׁבָּע הֶסֵּת. שֶׁאִלּוּ הוֹדָה הָיָה מְשַׁלֵּם הַבֹּשֶׁת:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁהַמּוֹדֶה בִּקְנָס פָּטוּר כְּשֶׁהוֹדָה בְּדָבָר שֶׁחַיָּב עָלָיו קְנָס כְּגוֹן שֶׁאָמַר חָבַלְתִּי בָּזֶה. אֲבָל אִם אָמַר חָבַלְתִּי בָּזֶה וְהֵבִיא עָלַי עֵדִים בְּבֵית דִּין וְחִיְּבוּנִי לִתֵּן כָּךְ וְכָךְ בִּנְזָקַי הֲרֵי זֶה חַיָּב לְשַׁלֵּם. לְפִיכָךְ אִם טָעַן הַטּוֹעֵן שֶׁבֵּית דִּין חִיְּבוּךָ לְשַׁלֵּם לִי מֵאָה דִּינָרִין מִשּׁוּם שֶׁחָבַלְתָּ בִּי וְהוּא אוֹמֵר לֹא הָיוּ דְּבָרִים מֵעוֹלָם. הֲרֵי זֶה נִשְׁבָּע הֶסֵּת. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:"],"Mishneh Torah, Plaintiff and Defendant 6":["בַּעֲלֵי דִּינִין שֶׁבָּאוּ לְבֵית דִּין טָעַן הָאֶחָד וְאָמַר מָנֶה יֵשׁ לִי אֵצֶל זֶה שֶׁהִלְוֵיתִיו אוֹ שֶׁהִפְקַדְתִּי אֶצְלוֹ אוֹ שֶׁגָּזַל מִמֶּנִּי אוֹ שֶׁיֵּשׁ לִי אֶצְלוֹ בְּשָׂכָר וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְהֵשִׁיב הַנִּטְעָן וְאָמַר אֵינִי חַיָּב כְּלוּם אוֹ אֵין לְךָ בְּיָדִי כְּלוּם אוֹ שֶׁקֶר אַתָּה טוֹעֵן. אֵין זוֹ תְּשׁוּבָה נְכוֹנָה אֶלָּא אוֹמְרִים בֵּית דִּין לַנִּטְעָן הָשֵׁב עַל טַעֲנָתוֹ וּפָרֵשׁ הַתְּשׁוּבָה כְּמוֹ שֶׁפֵּרֵשׁ זֶה טַעֲנָתוֹ וֶאֱמֹר אִם לָוִיתָ מִמֶּנּוּ אִם לֹא לָוִיתָ. הִפְקִיד אֶצְלְךָ אוֹ לֹא הִפְקִיד. גְּזַלְתּוֹ אוֹ לֹא גְּזַלְתּוֹ. שְׂכַרְתּוֹ אוֹ לֹא שְׂכַרְתּוֹ. וְכֵן שְׁאָר הַטְּעָנוֹת. וּמִפְּנֵי מָה אֵין מְקַבְּלִים מִמֶּנּוּ תְּשׁוּבָה זוֹ. שֶׁמָּא טוֹעֶה הוּא בְּדַעְתּוֹ וְיָבוֹא לְהִשָּׁבַע עַל שֶׁקֶר שֶׁהֲרֵי אֶפְשָׁר שֶׁהִלְוָהוּ כְּמוֹ שֶׁטָּעַן וְהֶחְזִיר זֶה אֶת הַחוֹב לִבְנוֹ אוֹ לְאִשְׁתּוֹ אוֹ שֶׁנָּתַן לוֹ בְּמַתָּנָה כְּנֶגֶד הַחוֹב וִידַמֶּה בְּדַעְתּוֹ שֶׁנִּפְטַר מִן הַחוֹב. לְפִיכָךְ אוֹמְרִים לוֹ הֵיאַךְ תֹּאמַר אֵינִי חַיָּב כְּלוּם שֶׁמָּא אַתָּה מִתְחַיֵּב מִן הַדִּין לְשַׁלֵּם וְאֵין אַתָּה יוֹדֵעַ אֶלָּא הוֹדַע לַדַּיָּנִין פֵּרוּשׁ הַדְּבָרִים וְהֵם יוֹדִיעוּךָ אִם אַתָּה חַיָּב אוֹ אֵין אַתָּה חַיָּב. וַאֲפִלּוּ הָיָה חָכָם גָּדוֹל אוֹמְרִים לוֹ אֵין לְךָ הֶפְסֵד שֶׁתָּשִׁיב עַל טַעֲנָתוֹ וְתוֹדִיעֶנּוּ כֵּיצַד אֵין אַתָּה חַיָּב לוֹ מִפְּנֵי שֶׁלֹּא הָיוּ דְּבָרִים מֵעוֹלָם אוֹ מִפְּנֵי שֶׁהָיוּ וְהֶחֱזַרְתָּ לוֹ שֶׁהֲרֵי אָנוּ דָּנִין בְּמִתּוֹךְ שֶׁיָּכוֹל לוֹמַר בְּכָל מָקוֹם. וְכֵן אִם טָעַן הַטּוֹעֵן וְאָמַר זֶה חַיָּב לִי מָנֶה. אוֹ מָנֶה יֵשׁ לִי אֶצְלוֹ. אוֹמְרִים לוֹ מֵאֵי זֶה פָּנִים. הִלְוֵיתָ אוֹתוֹ. אוֹ הִפְקַדְתָּ אֶצְלוֹ. אוֹ הִזִּיק מָמוֹנְךָ. אֱמֹר הֵיאַךְ נִתְחַיֵּב לְךָ. שֶׁהֲרֵי אֶפְשָׁר שֶׁיִּדְמֶה לוֹ שֶׁהוּא חַיָּב לוֹ וְהוּא אֵינוֹ חַיָּב כְּגוֹן שֶׁחֲשָׁדוֹ שֶׁגְּנָבוֹ אוֹ שֶׁאָמַר לוֹ שֶׁאֶתֵּן לְךָ מָנֶה וְכַיּוֹצֵא בָּזֶה. הֲרֵי שֶׁטָּעַן עָלָיו שֶׁהִלְוָהוּ מָנֶה וְהֵשִׁיב זֶה וְאָמַר לוֹ לֹא הָיוּ דְּבָרִים מֵעוֹלָם וְאַחַר כָּךְ הֵבִיא הַטּוֹעֵן עֵדִים שֶׁהִלְוָהוּ בִּפְנֵיהֶם וְחָזַר הַנִּטְעָן וְאָמַר כֵּן הָיָה וְלָוִיתִי וּפָרַעְתִּי אֵין מְקַבְּלִין מִמֶּנּוּ אֶלָּא הֻחְזַק כַּפְרָן וּמְשַׁלֵּם. אֲבָל אִם הֵשִׁיב אֵינִי חַיָּב אוֹ אֵין לְךָ בְּיָדִי כְּלוּם אוֹ שֶׁקֶר אַתָּה טוֹעֵן. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְהָלַךְ הַתּוֹבֵעַ וְהֵבִיא עֵדִים שֶׁהִלְוָהוּ בִּפְנֵיהֶם וְאָמַר (הַנִּתְבָּע) כֵּן הָיָה אֲבָל הֶחְזַרְתִּי לוֹ פִּקְדוֹנוֹ אוֹ פְּרַעְתִּיו חוֹבוֹ לֹא הֻחְזַק כַּפְרָן וְנִשְׁבָּע הֶסֵּת וְנִפְטָר:","רָאוּהוּ עֵדִים שֶׁמָּנָה לוֹ מָעוֹת וְלֹא יָדְעוּ מַה הֵן. וּתְבָעוֹ בְּדִין וְאָמַר לוֹ תֵּן לִי מְעוֹתַי שֶׁהִלְוֵיתִיךָ. וְאָמַר מַתָּנָה נָתַתָּ לִי אוֹ פֵּרָעוֹן הָיוּ. הֲרֵי זֶה נֶאֱמָן וְנִשְׁבָּע הֶסֵּת וְנִפְטָר. אָמַר לֹא הָיוּ דְּבָרִים מֵעוֹלָם וְאַחַר כָּךְ בָּאוּ עֵדִים שֶׁמָּנָה לוֹ בִּפְנֵיהֶם הֻחְזַק כַּפְרָן. וּלְעוֹלָם אֵין אָדָם מֻחְזָק כַּפְרָן עַד שֶׁיִּכְפֹּר בְּבֵית דִּין וְיָבוֹאוּ שְׁנֵי עֵדִים וְיַכְחִישׁוּהוּ בְּמַה שֶּׁכָּפַר:","מָנֶה הִלְוֵיתִיךָ כָּפַר בְּבֵית דִּין וְאָמַר לֹא הָיוּ דְּבָרִים מֵעוֹלָם. וּבָאוּ שְׁנֵי עֵדִים שֶׁלָּוָה מִמֶּנּוּ מָנֶה וּפְרָעוֹ. וְהַמַּלְוֶה אוֹמֵר לֹא נִפְרַעְתִּי. הֲרֵי זֶה חַיָּב לְשַׁלֵּם. שֶׁכָּל הָאוֹמֵר לֹא לָוִיתִי וּבָאוּ עֵדִים שֶׁלָּוָה כְּאוֹמֵר לֹא פָּרַעְתִּי דָּמִי. וְנִמְצָא הַלּוֶֹה אוֹמֵר לֹא פָּרַעְתִּי וְהָעֵדִים מְעִידִים אוֹתוֹ שֶׁפְּרָעוֹ הוֹדָאַת בַּעַל דִּין כְּמֵאָה עֵדִים דָּמֵי וְאֵין הַמַּלְוֶה חַיָּב שְׁבוּעָה שֶׁהֲרֵי הֻחְזַק זֶה כַּפְרָן. וְכֵן אִם הוֹצִיא עָלָיו כְּתַב יָדוֹ שֶׁהוּא חַיָּב לוֹ וְאָמַר לֹא הָיוּ דְּבָרִים מֵעוֹלָם וְזֶה אֵינוֹ כְּתַב יָדִי. אִם הֻחְזַק כְּתַב יָדוֹ בְּבֵית דִּין אוֹ שֶׁבָּאוּ עֵדִים שֶׁהוּא כְּתַב יָדוֹ הֲרֵי זֶה הֻחְזַק כַּפְרָן וּמְשַׁלֵּם:","מָנֶה הִלְוֵיתִיךָ וְהוּא לִי בְּיָדְךָ אָמַר לוֹ הַנִּטְעָן וַהֲלֹא פְּרַעְתִּיךָ בִּפְנֵי פְּלוֹנִי וּפְלוֹנִי. וּבָאוּ עֵדִים וְאָמְרוּ לֹא הָיוּ דְּבָרִים מֵעוֹלָם. לֹא הֻחְזַק כַּפְרָן שֶׁאֵין הָעֵדִים זוֹכְרִין אֶלָּא דָּבָר שֶׁהֵם עֵדִים בּוֹ לְפִיכָךְ לֹא הֻחְזַק כַּפְרָן וְיִשָּׁבַע הַלּוֶֹה הֶסֵּת וְיִפָּטֵר. כַּיּוֹצֵא בּוֹ תֵּן לִי מָנֶה שֶׁהִלְוֵיתִיךָ וְאַתָּה עָמַדְתָּ בְּצַד עַמּוּד זֶה וְאָמַר הַנִּטְעָן לֹא עָמַדְתִּי בְּצַד עַמּוּד זֶה מֵעוֹלָם וּבָאוּ עֵדִים שֶׁעָמַד לֹא הֻחְזַק כַּפְרָן. שֶׁאֵין אָדָם מֵשִׂים דַּעְתּוֹ לִדְבָרִים שֶׁאֵין בָּהֶן מַמָּשׁ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","תֵּן לִי מָנֶה שֶׁהִלְוֵיתִיךָ וַהֲרֵי הָעֵדִים וְאָמַר הַנִּטְעָן פְּרַעְתִּיךָ בִּפְנֵי פְּלוֹנִי וּפְלוֹנִי אוֹמְרִין לַלּוֶֹה הֲבִיאֵם וְהִפָּטֵר. לֹא בָּאוּ אוֹ שֶׁמֵּתוּ אוֹ שֶׁהָלְכוּ לִמְדִינָה אַחֶרֶת. יִשָּׁבַע הֶסֵּת שֶׁפְּרָעוֹ שֶׁאֵין אָנוּ מַצְרִיכִים אוֹתוֹ לַהֲבִיאָן אֶלָּא לְבָרֵר דְּבָרָיו וּלְהִפָּטֵר אַף מִשְּׁבוּעָה. שֶׁהַמַּלְוֶה אֶת חֲבֵרוֹ בְּעֵדִים אֵינוֹ צָרִיךְ לְפָרְעוֹ בְּעֵדִים כְּמוֹ שֶׁבֵּאַרְנוּ:","אָמַר לוֹ בִּפְנֵי עֵדִים מָנֶה לִי בְּיָדְךָ אָמַר לוֹ הֵן. לְמָחָר תְּבָעוֹ בְּדִין וְהֵבִיא עֵדִים וְאָמַר מְשַׁטֶּה הָיִיתִי בְּךָ וְאֵין לְךָ בְּיָדִי כְּלוּם. פָּטוּר וְנִשְׁבָּע הֶסֵּת שֶׁאֵין בְּיָדוֹ כְּלוּם. וַאֲפִלּוּ אָמַר לֹא הָיוּ דְּבָרִים מֵעוֹלָם שֶׁהֲרֵי לֹא אָמַר לָהֶם אַתֶּם עֵדַי וְדָבָר שֶׁאֵינוֹ עֵדוּת אֵין אָדָם זוֹכְרוֹ. וּלְפִיכָךְ אִם אָמַר לֹא הָיוּ דְּבָרִים מֵעוֹלָם לֹא הֻחְזַק כַּפְרָן:","וְלֹא עוֹד אֶלָּא אֲפִלּוּ הִטְמִין לוֹ עֵדִים אֲחוֹרֵי הַגָּדֵר וְאָמַר לוֹ מָנֶה לִי בְּיָדְךָ אָמַר לוֹ הֵן רְצוֹנְךָ שֶׁיָּעִידוּ בְּךָ פְּלוֹנִי וּפְלוֹנִי אָמַר לוֹ לֹא שֶׁמָּא תִּכְפֵּנִי בְּדִין לְמָחָר וְאֵין לִי מָה אֶתֵּן לְךָ וּלְמָחָר תְּבָעוֹ בְּדִין בְּאֵלּוּ הָעֵדִים. בֵּין שֶׁטָּעַן וְאָמַר מְשַׁטֶּה הָיִיתִי בּוֹ בֵּין שֶׁאָמַר לֹא הָיוּ דְּבָרִים מֵעוֹלָם הֲרֵי זֶה נִשְׁבָּע הֶסֵּת וְנִפְטָר. שֶׁאֵין כָּאן עֵדוּת עַד שֶׁיֹּאמַר הַלּוֶֹה אַתֶּם עֵדַי אוֹ יֹאמַר הַמַּלְוֶה בִּפְנֵי הַלּוֶֹה וְיִשְׁתֹּק הַלּוֶֹה אֲבָל בָּעֵדוּת הַזֶּה לֹא הֻחְזַק כַּפְרָן. מַעֲשֶׂה בְּאֶחָד שֶׁהָיוּ קוֹרִין אוֹתוֹ קַב רְשׁוּ כְּלוֹמַר שֶׁיֵּשׁ עָלָיו חוֹבוֹת הַרְבֵּה. אָמַר מִי הוּא שֶׁאֲנִי חַיָּב לוֹ אֶלָּא פְּלוֹנִי וּבָא אוֹתוֹ פְּלוֹנִי וּתְבָעוֹ וְאָמַר הוּא אֵינִי חַיָּב לוֹ כְּלוּם. וְאָמְרוּ חֲכָמִים יִשָּׁבַע הֶסֵּת וְיִפָּטֵר. וְכֵן אֶחָד הָיוּ אוֹמְרִים עָלָיו שֶׁהוּא בַּעַל מָמוֹן. בִּשְׁעַת מִיתָתוֹ אָמַר אִלּוּ הָיָה לִי מָמוֹן לֹא הָיִיתִי פּוֹרְעוֹ לִפְלוֹנִי וְלִפְלוֹנִי. וְאַחַר מִיתָתוֹ בָּאוּ פְּלוֹנִי וּפְלוֹנִי לִתְבֹּעַ וְאָמְרוּ חֲכָמִים אֵין לָהֶם כְּלוּם. שֶׁהָאָדָם עָשׂוּי לְהַרְאוֹת עַצְמוֹ שֶׁאֵינוֹ בַּעַל מָמוֹן וְשֶׁלֹּא הִנִּיחַ בָּנָיו בַּעֲלֵי מָמוֹן וְכָל כַּיּוֹצֵא בִּדְבָרִים אֵלּוּ:","אַף עַל פִּי שֶׁהַמַּטְמִין עֵדִים אֵינָהּ עֵדוּת וְכֵן הַמּוֹדֶה מֵעַצְמוֹ וְעֵדִים שׁוֹמְעִין אוֹתוֹ. וְכֵן הָאוֹמֵר לַחֲבֵרוֹ בִּפְנֵי עֵדִים מָנֶה לִי בְּיָדְךָ וְאָמַר לוֹ הֵן. בְּכָל הַדְּבָרִים וְכַיּוֹצֵא בָּהֶן כְּשֶׁיָּבוֹאוּ לְבֵית דִּין אוֹמְרִין לַנִּתְבָּע לָמָּה לֹא תִּתֵּן מַה שֶּׁיֵּשׁ לוֹ אֶצְלְךָ. אָמַר אֵין לוֹ אֶצְלִי כְּלוּם. אוֹמְרִים לוֹ וַהֲלֹא אַתָּה אָמַרְתָּ בִּפְנֵי אֵלּוּ כָּךְ וְכָךְ אוֹ הוֹדֵיתָ מֵעַצְמְךָ. אִם עָמַד וְשִׁלֵּם מוּטָב וְאִם לֹא טָעַן אֵין טוֹעֲנִין לוֹ. אֲבָל אִם טָעַן וְאָמַר מְשַׁטֶּה הָיִיתִי בּוֹ אוֹ לֹא הָיוּ דְּבָרִים מֵעוֹלָם אוֹ שֶׁלֹּא לְהַשְׁבִּיעַ אֶת עַצְמִי נִתְכַּוַּנְתִּי פָּטוּר וְנִשְׁבָּע הֶסֵּת כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Positive Mitzvot 106":["להיות זבה מטמאה."],"Mishneh Torah, Positive Mitzvot 117":["להיות מקדיש שדהו נותן בערך הקצוב בפרשה, שנאמר: \"וְהָיָה עֶרְכְּךָ כְּפִי זַרְעוֹ\" (ויקרא כז, טז)."],"Mishneh Torah, Positive Mitzvot 128":["להפריש מעשר שני להיאכל לבעליו בירושלים, שנאמר: \"עַשֵּׂר תְּעַשֵּׂר\" (דברים יד, כב) מפי השמועה למדו שזה הוא מעשר שני."],"Mishneh Torah, Positive Mitzvot 139":["להיות גאולה בבתי ערי חומה עד שנה, שנאמר: \"ואיש, כי ימכור בית מושב\" (ויקרא כה,כט)."],"Mishneh Torah, Positive Mitzvot 15":["לִקְבֹּעַ מְזוּזָה, שֶׁנֶּאֱמָר: \"וּכְתַבְתָּם עַל מְזוּזֹת בֵּיתֶךָ וּבִשְׁעָרֶיךָ\" (דברים ו ט; יא, כ)."],"Mishneh Torah, Positive Mitzvot 160":["לשבות בשביעי בו, שנאמר: \"וביום השביעי, מקרא קודש\" (שמות יב,טז; במדבר כח,כה)."],"Mishneh Torah, Positive Mitzvot 171":["ליתן מחצית השקל בכל שנה ושנה, שנאמר: \"זה ייתנו, כל העובר על הפקודים\" (שמות ל,יג)."],"Mishneh Torah, Positive Mitzvot 182":["להכין שש ערי מקלט, שנאמר: \"תכין לך, הדרך, ושילשת\" (דברים יט,ג)."],"Mishneh Torah, Positive Mitzvot 193":["להתקין יתד, שנאמר: \"ויתד תהיה לך, על אזנך\" (דברים כג,יד)."],"Mishneh Torah, Positive Mitzvot 203":["להקים המשא על הבהמה, שנאמר: \"הקם תקים, עימו\" (דברים כב,ד)."],"Mishneh Torah, Positive Mitzvot 214":["לשמח חתן את אשתו שנה, שנאמר: \"נקי יהיה לביתו שנה אחת\" (דברים כד, ה)."],"Mishneh Torah, Positive Mitzvot 225":["להגלות רוצח בשגגה, שנאמר: \"וישב בה, עד מות הכוהן\" (במדבר לה,כה)."],"Mishneh Torah, Positive Mitzvot 236":["להיות החובל משלם ממון, שנאמר: \"וכי יריבון אנשים--והכה איש\" (שמות כא,יח)."],"Mishneh Torah, Positive Mitzvot 247":["להציל הנרדף ואפילו בנפש הרודף, שנאמר: \"וקצותה, את כפה\" (דברים כה,יב)."],"Mishneh Torah, Positive Mitzvot 34":["לשאת הארון על הכתף כשנושאין אותו, שנאמר: \"בַּכָּתֵף יִשָּׂאוּ\" (במדבר ז, ט)."],"Mishneh Torah, Positive Mitzvot 45":["להוסיף קרבן ביום עצרת, שנאמר: \"וּבְיוֹם הַבִּכּוּרִים...\" (במדבר כח, כו) \"וְהִקְרַבְתֶּם עוֹלָה לְרֵיחַ...\" (במדבר כח, כז)."],"Mishneh Torah, Positive Mitzvot 56":["לאכול בשר הפסח צלי בלילי חמישה עשר מניסן, שנאמר: \"וְאָכְלוּ אֶת הַבָּשָׂר\" (שמות יב, ח)."],"Mishneh Torah, Positive Mitzvot 67":["מעשה המנחה, שנאמר: \"וְנֶפֶשׁ כִּי תַקְרִיב קָרְבַּן מִנְחָה\" (ויקרא ב, א)."],"Mishneh Torah, Positive Mitzvot 78":["לעשר הבהמה, שנאמר: \"וכל מעשר בקר וצאן\" (ויקרא כז,לב)."],"Mishneh Torah, Positive Mitzvot 89":["לאכול בשר חטאת ואשם, שנאמר: \"ואכלו אותם אשר כופר בהם\" (שמות כט,לג)."],"Mishneh Torah, Prayer and the Priestly Blessing 1":["מִצְוַת עֲשֵׂה לְהִתְפַּלֵּל בְּכָל יוֹם שֶׁנֶּאֱמַר (שמות כג כה) ״וַעֲבַדְתֶּם אֵת ה׳‎ אֱלֹהֵיכֶם״. מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁעֲבוֹדָה זוֹ הִיא תְּפִלָּה שֶׁנֶּאֱמַר (דברים יא יג) ״וּלְעָבְדוֹ בְּכָל לְבַבְכֶם״ אָמְרוּ חֲכָמִים אֵי זוֹ הִיא עֲבוֹדָה שֶׁבַּלֵּב זוֹ תְּפִלָּה. וְאֵין מִנְיַן הַתְּפִלּוֹת מִן הַתּוֹרָה. וְאֵין מִשְׁנֶה הַתְּפִלָּה הַזֹּאת מִן הַתּוֹרָה. וְאֵין לַתְּפִלָּה זְמַן קָבוּעַ מִן הַתּוֹרָה:","וּלְפִיכָךְ נָשִׁים וַעֲבָדִים חַיָּבִין בִּתְפִלָּה לְפִי שֶׁהִיא מִצְוַת עֲשֵׂה שֶׁלֹּא הַזְּמַן גְּרָמָא אֶלָּא חִיּוּב מִצְוָה זוֹ כָּךְ הוּא שֶׁיְּהֵא אָדָם מִתְחַנֵּן וּמִתְפַּלֵּל בְּכָל יוֹם וּמַגִּיד שִׁבְחוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וְאַחַר כָּךְ שׁוֹאֵל צְרָכָיו שֶׁהוּא צָרִיךְ לָהֶם בְּבַקָּשָׁה וּבִתְחִנָּה וְאַחַר כָּךְ נוֹתֵן שֶׁבַח וְהוֹדָיָה לַה׳‎ עַל הַטּוֹבָה שֶׁהִשְׁפִּיעַ לוֹ כָּל אֶחָד לְפִי כֹּחוֹ:","אִם הָיָה רָגִיל מַרְבֶּה בִּתְחִנָּה וּבַקָּשָׁה וְאִם הָיָה עֲרַל שְׂפָתַיִם מְדַבֵּר כְּפִי יְכָלְתּוֹ וּבְכָל עֵת שֶׁיִּרְצֶה. וְכֵן מִנְיַן הַתְּפִלּוֹת כָּל אֶחָד כְּפִי יְכָלְתּוֹ. יֵשׁ מִתְפַּלֵּל פַּעַם אַחַת בְּיוֹם. וְיֵשׁ מִתְפַּלְּלִין פְּעָמִים הַרְבֵּה. וְהַכּל יִהְיוּ מִתְפַּלְּלִין נֹכַח הַמִּקְדָּשׁ בְּכָל מָקוֹם שֶׁיִּהְיֶה. וְכֵן הָיָה הַדָּבָר תָּמִיד מִמּשֶׁה רַבֵּנוּ וְעַד עֶזְרָא:","כֵּיוָן שֶׁגָּלוּ יִשְׂרָאֵל בִּימֵי נְבוּכַדְנֶצַּר הָרָשָׁע נִתְעָרְבוּ בְּפָרַס וְיָוָן וּשְׁאָר הָאֻמּוֹת וְנוֹלְדוּ לָהֶם בָּנִים בְּאַרְצוֹת הַגּוֹיִם וְאוֹתָן הַבָּנִים נִתְבַּלְבְּלוּ שְׂפָתָם וְהָיְתָה שְׂפַת כָּל אֶחָד וְאֶחָד מְעֹרֶבֶת מִלְּשׁוֹנוֹת הַרְבֵּה וְכֵיוָן שֶׁהָיָה מְדַבֵּר אֵינוֹ יָכוֹל לְדַבֵּר כָּל צָרְכּוֹ בְּלָשׁוֹן אַחַת אֶלָּא בְּשִׁבּוּשׁ שֶׁנֶּאֱמַר (נחמיה יג כד) ״וּבְנֵיהֶם חֲצִי מְדַבֵּר אַשְׁדּוֹדִית״ וְגוֹ׳‎ (נחמיה יג כד) ״וְאֵינָם מַכִּירִים לְדַבֵּר יְהוּדִית וְכִלְשׁוֹן עַם וְעַם״. וּמִפְּנֵי זֶה כְּשֶׁהָיָה אֶחָד מֵהֶן מִתְפַּלֵּל תִּקְצַר לְשׁוֹנוֹ לִשְׁאל חֲפָצָיו אוֹ לְהַגִּיד שֶׁבַח הַקָּדוֹשׁ בָּרוּךְ הוּא בִּלְשׁוֹן הַקֹּדֶשׁ עַד שֶׁיֵּעָרְבוּ עִמָּהּ לְשׁוֹנוֹת אֲחֵרוֹת. וְכֵיוָן שֶׁרָאָה עֶזְרָא וּבֵית דִּינוֹ כָּךְ עָמְדוּ וְתִקְּנוּ לָהֶם שְׁמוֹנֶה עֶשְׂרֵה בְּרָכוֹת עַל הַסֵּדֶר. שָׁלֹשׁ רִאשׁוֹנוֹת שֶׁבַח לַה׳‎ וְשָׁלֹשׁ אַחֲרוֹנוֹת הוֹדָיָה. וְאֶמְצָעִיּוֹת יֵשׁ בָּהֶן שְׁאֵלַת כָּל הַדְּבָרִים שֶׁהֵן כְּמוֹ אָבוֹת לְכָל חֶפְצֵי אִישׁ וָאִישׁ וּלְצָרְכֵי הַצִּבּוּר כֻּלָּן, כְּדֵי שֶׁיִּהְיוּ עֲרוּכוֹת בְּפִי הַכּל וְיִלְמְדוּ אוֹתָן וְתִהְיֶה תְּפִלַּת אֵלּוּ הָעִלְּגִים תְּפִלָּה שְׁלֵמָה כִּתְפִלַּת בַּעֲלֵי הַלָּשׁוֹן הַצֶּחָה. וּמִפְּנֵי עִנְיָן זֶה תִּקְּנוּ כָּל הַבְּרָכוֹת וְהַתְּפִלּוֹת מְסֻדָּרוֹת בְּפִי כָּל יִשְׂרָאֵל כְּדֵי שֶׁיְּהֵא עִנְיַן כָּל בְּרָכָה עָרוּךְ בְּפִי הָעִלֵּג:","וְכֵן תִּקְּנוּ שֶׁיְּהֵא מִנְיַן הַתְּפִלּוֹת כְּמִנְיַן הַקָּרְבָּנוֹת. שְׁתֵּי תְּפִלּוֹת בְּכָל יוֹם כְּנֶגֶד שְׁנֵי תְּמִידִין. וְכָל יוֹם שֶׁיֵּשׁ קָרְבַּן מוּסָף תִּקְּנוּ בּוֹ תְּפִלָּה שְׁלִישִׁית כְּנֶגֶד קָרְבַּן מוּסָף. וּתְפִלָּה שֶׁהִיא כְּנֶגֶד תָּמִיד שֶׁל בֹּקֶר הִיא הַנִּקְרֵאת תְּפִלַּת הַשַּׁחַר. וּתְפִלָּה שֶׁכְּנֶגֶד תָּמִיד שֶׁל בֵּין הָעַרְבַּיִם הִיא הַנִּקְרֵאת תְּפִלַּת מִנְחָה וּתְפִלָּה שֶׁכְּנֶגֶד הַמּוּסָפִין הִיא נִקְרֵאת תְּפִלַּת הַמּוּסָפִין:","וְכֵן הִתְקִינוּ שֶׁיְּהֵא אָדָם מִתְפַּלֵּל תְּפִלָּה אַחַת בַּלַּיְלָה שֶׁהֲרֵי אֵיבְרֵי תָּמִיד שֶׁל בֵּין הָעַרְבַּיִם מִתְעַכְּלִין וְהוֹלְכִין כָּל הַלַּיְלָה שֶׁנֶּאֱמַר (ויקרא ו ב) ״הִיא הָעֹלָה״ וְגוֹ׳‎, כָּעִנְיָן שֶׁנֶּאֱמַר (תהילים נה יח) ״עֶרֶב וָבֹקֶר וְצָהֳרַיִם אָשִׂיחָה וְאֶהֱמֶה וַיִּשְׁמַע קוֹלִי״. וְאֵין תְּפִלַּת עַרְבִית חוֹבָה כִּתְפִלַּת שַׁחֲרִית וּמִנְחָה. וְאַף עַל פִּי כֵן נָהֲגוּ כָּל יִשְׂרָאֵל בְּכָל מְקוֹמוֹת מוֹשְׁבוֹתֵיהֶם לְהִתְפַּלֵּל עַרְבִית וְקִבְּלוּהָ עֲלֵיהֶם כִּתְפִלַּת חוֹבָה:","וְכֵן תִּקְּנוּ תְּפִלָּה אַחַר תְּפִלַּת מִנְחָה סָמוּךְ לִשְׁקִיעַת הַחַמָּה בְּיוֹם הַתַּעֲנִית בִּלְבַד כְּדֵי לְהוֹסִיף תְּחִנָּה וּבַקָּשָׁה מִפְּנֵי הַתַּעֲנִית וְזוֹ הִיא הַתְּפִלָּה הַנִּקְרֵאת תְּפִלַּת נְעִילָה כְּלוֹמַר נִנְעֲלוּ שַׁעֲרֵי שָׁמַיִם בְּעַד הַשֶּׁמֶשׁ וְנִסְתְּרָה, לְפִי שֶׁאֵין מִתְפַּלְּלִין אוֹתָהּ אֶלָּא סָמוּךְ לִשְׁקִיעַת הַחַמָּה:","נִמְצְאוּ הַתְּפִלּוֹת בְּכָל יוֹם שָׁלֹשׁ. עַרְבִית וְשַׁחֲרִית וּמִנְחָה. וּבַשַּׁבָּתוֹת וּבְמוֹעֲדִים וּבְרָאשֵׁי חֳדָשִׁים אַרְבַּע. שָׁלֹשׁ שֶׁל כָּל יוֹם וּתְפִלַּת הַמּוּסָפִין. וּבְיוֹם הַכִּפּוּרִים חָמֵשׁ. אַרְבַּע אֵלּוּ וּתְפִלַּת נְעִילָה:","תְּפִלּוֹת אֵלּוּ אֵין פּוֹחֲתִין מֵהֶן אֲבָל מוֹסִיפִין עֲלֵיהֶם. אִם רָצָה אָדָם לְהִתְפַּלֵּל כָּל הַיּוֹם כֻּלּוֹ הָרְשׁוּת בְּיָדוֹ. וְכָל אוֹתָן הַתְּפִלּוֹת שֶׁיּוֹסִיף כְּמוֹ מַקְרִיב נְדָבוֹת. לְפִיכָךְ צָרִיךְ שֶׁיְּחַדֵּשׁ דָּבָר בְּכָל בְּרָכָה וּבְרָכָה מִן הָאֶמְצָעִיּוֹת מֵעֵין הַבְּרָכוֹת. וְאִם חִדֵּשׁ אֲפִלּוּ בִּבְרָכָה אַחַת דַּיּוֹ כְּדֵי לְהוֹדִיעַ שֶׁהִיא נְדָבָה וְלֹא חוֹבָה. וְשָׁלֹשׁ רִאשׁוֹנוֹת וְשָׁלֹשׁ אַחֲרוֹנוֹת לְעוֹלָם אֵין מוֹסִיפִין בָּהֶן וְלֹא פּוֹחֲתִין מֵהֶן וְאֵין מְשַׁנִּין בָּהֶן דָּבָר:","אֵין הַצִּבּוּר מִתְפַּלְּלִין תְּפִלַּת נְדָבָה לְפִי שֶׁאֵין הַצִּבּוּר מְבִיאִין קָרְבַּן נְדָבָה. וְלֹא יִתְפַּלֵּל אֲפִלּוּ יָחִיד מוּסָף שְׁתַּיִם אַחַת חוֹבַת הַיּוֹם וְאַחַת נְדָבָה לְפִי שֶׁאֵין מִתְנַדְּבִין קָרְבַּן מוּסָף. וְיֵשׁ מִן הַגְּאוֹנִים מִי שֶׁהוֹרָה שֶׁאָסוּר לְהִתְפַּלֵּל תְּפִלַּת נְדָבָה בְּשַׁבָּתוֹת וְיָמִים טוֹבִים לְפִי שֶׁאֵין מַקְרִיבִין בָּהֶן נְדָבָה אֶלָּא חוֹבַת הַיּוֹם בִּלְבַד:"],"Mishneh Torah, Prayer and the Priestly Blessing 7":["כְּשֶׁתִּקְּנּוּ חֲכָמִים דִּבְרֵי תְּפִלּוֹת אֵלּוּ תִּקְּנוּ בְּרָכוֹת אֲחֵרוֹת לְבָרֵךְ אוֹתָן בְּכָל יוֹם, אֵלּוּ הֵן. כְּשֶׁיִּכָּנֵס אָדָם לְמִטָּתוֹ לִישֹׁן בַּלַּיְלָה מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם הַמַּפִּיל חֶבְלֵי שֵׁנָה עַל עֵינַי וְהַמַּשְׁקִיעַ שֵׁינַת תַּרְדֵּמָה וְהַמֵּאִיר לְאִישׁוֹן בַּת עַיִן. יְהִי רָצוֹן מִלְּפָנֶיךָ יְיָ׳‎ אֱלֹהַי שֶׁתַּצִּילֵנִי מִיֵּצֶר רַע וּמִפֶּגַע רַע וְאַל יְבַהֲלוּנִי חֲלוֹמוֹת רָעִים וְלֹא הִרְהוּרִים רָעִים וּתְהֵא מִטָּתִי שְׁלֵמָה לְפָנֶיךָ וְתַעֲמִידֵנִי מִמֶּנָּה לְחַיִּים וּלְשָׁלוֹם וְהָאִירָה עֵינַי פֶּן אִישַׁן הַמָּוֶת. בָּרוּךְ אַתָּה יְיָ׳‎ הַמֵּאִיר לָעוֹלָם כֻּלּוֹ בִּכְבוֹדוֹ:","וְקוֹרֵא פָּרָשָׁה רִאשׁוֹנָה מִקְּרִיאַת שְׁמַע וְיָשֵׁן. וַאֲפִלּוּ אִשְׁתּוֹ יְשֵׁנָה עִמּוֹ (קוֹרֵא פָּסוּק רִאשׁוֹן אוֹ פְּסוּקֵי רַחֲמִים וְאַחַר כָּךְ יִישַׁן). וְאִם אֲנָסַתּוּ שֵׁנָה קוֹרֵא אֲפִלּוּ פָּסוּק רִאשׁוֹן אוֹ פְּסוּקֵי רַחֲמִים וְאַחַר כָּךְ יִישַׁן:","בְּשָׁעָה שֶׁיִּיקַץ בְּסוֹף שְׁנָתוֹ מְבָרֵךְ וְהוּא עַל מִטָּתוֹ כָּךְ. אֱלֹהַי נְשָׁמָה שֶׁנָּתַתָּ בִּי טְהוֹרָה אַתָּה בְּרָאתָהּ וְאַתָּה יְצַרְתָּהּ וְאַתָּה נְפַחְתָּהּ בִּי וְאַתָּה מְשַׁמְּרָהּ בְּקִרְבִּי וְאַתָּה עָתִיד לִטְּלָהּ מִמֶּנִּי וְאַתָּה עָתִיד לְהַחֲזִירָהּ בִּי לֶעָתִיד לָבוֹא. כָּל זְמַן שֶׁהַנְּשָׁמָה תְּלוּיָה בְּקִרְבִּי מוֹדֶה אֲנִי לְפָנֶיךָ יְיָ׳‎ אֱלֹהַי רִבּוֹן כָּל הַמַּעֲשִׂים בָּרוּךְ אַתָּה יְיָ׳‎ הַמַּחֲזִיר נְשָׁמוֹת לִפְגָרִים מֵתִים:","כְּשֶׁשּׁוֹמֵעַ קוֹל הַתַּרְנְגוֹלִים מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם הַנּוֹתֵן לַשֶּׂכְוִי בִינָה לְהַבְחִין בֵּין יוֹם וּבֵין לָיְלָה. כְּשֶׁלּוֹבֵשׁ בְּגָדָיו מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם מַלְבִּישׁ עֲרוּמִים. כְּשֶׁמַּנִּיחַ סְדִינוֹ עַל רֹאשׁוֹ מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם עוֹטֵר יִשְׂרָאֵל בְּתִפְאָרָה. כְּשֶׁמַּעֲבִיר יָדָיו עַל עֵינָיו מְבָרֵךְ פּוֹקֵחַ עִוְרִים. כְּשֶׁיֵּשֵׁב עַל מִטָּתוֹ מְבָרֵךְ מַתִּיר אֲסוּרִים. כְּשֶׁמּוֹרִיד רַגְלָיו מִן הַמִּטָּה וּמַנִּיחָם עַל גַּבֵּי קַרְקַע מְבָרֵךְ רוֹקַע הָאָרֶץ עַל הַמָּיִם. כְּשֶׁעוֹמֵד מְבָרֵךְ זוֹקֵף כְּפוּפִים. כְּשֶׁנּוֹטֵל יָדָיו מְבָרֵךְ אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ עַל נְטִילַת יָדָיִם. כְּשֶׁרוֹחֵץ פָּנָיו מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם הַמַּעֲבִיר חֶבְלֵי שֵׁנָה מֵעֵינָי וּתְנוּמָה מֵעַפְעַפָּי, יְהִי רָצוֹן מִלְּפָנֶיךָ יְיָ׳‎ אֱלֹהַי וֵאלֹהֵי אֲבוֹתַי שֶׁתַּרְגִּילֵנִי לִדְבַר מִצְוָה וְאַל תַּרְגִּילֵנִי לִדְבַר עֲבֵרָה וְעָוֹן וְתַשְׁלֵט בִּי יֵצֶר טוֹב וְאַל יִשְׁלֹט בִּי יֵצֶר רָע וּתְחַזְּקֵנִי בְּמִצְוֹתֶיךָ וְתֵן חֶלְקִי בְּתוֹרָתֶךָ וְתִתְּנֵנִי לְחֵן וּלְחֶסֶד וּלְרַחֲמִים בְּעֵינֶיךָ וּבְעֵינֵי כָל רוֹאַי וְתִגְמְלֵנִי חֲסָדִים טוֹבִים, בָּרוּךְ אַתָּה יְיָ׳‎ גּוֹמֵל חֲסָדִים טוֹבִים:","וְכָל זְמַן שֶׁיִּכָּנֵס לְבֵית הַכִּסֵּא אוֹמֵר קֹדֶם שֶׁיִּכָּנֵס הִתְכַּבְּדוּ מְכֻבָּדִים קְדוֹשִׁים מְשָׁרְתֵי עֶלְיוֹן עִזְרוּנִי עִזְרוּנִי שִׁמְרוּנִי שִׁמְרוּנִי הַמְתִּינוּ לִי עַד שֶׁאֶכָּנֵס וְאֵצֵא שֶׁזֶּה דַּרְכָּן שֶׁל בְּנֵי אָדָם. וְאַחַר שֶׁיָּצָא מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר יָצַר אֶת הָאָדָם בְּחָכְמָה וּבָרָא בוֹ נְקָבִים נְקָבִים חֲלוּלִים חֲלוּלִים גָּלוּי וְיָדוּעַ לִפְנֵי כִסֵּא כְבוֹדֶךָ שֶׁאִם יִסָּתֵם אֶחָד מֵהֶם אוֹ אִם יִפָּתֵחַ אֶחָד מֵהֶם אִי אֶפְשָׁר לְהִתְקַיֵּם אֲפִלּוּ שָׁעָה אַחַת בָּרוּךְ אַתָּה יְיָ׳‎ רוֹפֵא כָל בָּשָׂר וּמַפְלִיא לַעֲשׂוֹת:","כְּשְׁחוֹגֵר חֲגוֹרוֹ מְבָרֵךְ אוֹזֵר יִשְׂרָאֵל בִּגְבוּרָה. כְּשֶׁלּוֹבֵשׁ נְעָלָיו מְבָרֵךְ שֶׁעָשִׂיתָ לִי כָּל צָרְכִּי. כְּשֶׁמְּהַלֵּךְ לָצֵאת לַדֶּרֶךְ מְבָרֵךְ הַמֵּכִין מִצְעֲדֵי גָבֶר. וּמְבָרֵךְ אָדָם בְּכָל יוֹם בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם שֶׁלֹּא עָשַׂנִי גּוֹי. בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם שֶׁלֹּא עָשַׂנִי אִשָּׁה. בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם שֶׁלֹּא עָשַׂנִי עָבֶד:","שְׁמוֹנֶה עֶשְׂרֵה בְּרָכוֹת אֵלּוּ אֵין לָהֶם סֵדֶר אֶלָּא מְבָרֵךְ כָּל אַחַת מֵהֶן עַל דָּבָר שֶׁהַבְּרָכָה בִּשְׁבִילוֹ בִּשְׁעָתוֹ. כֵּיצַד. הֲרֵי שֶׁחָגַר חֲגוֹרוֹ וְהוּא עַל מִטָּתוֹ מְבָרֵךְ אוֹזֵר יִשְׂרָאֵל בִּגְבוּרָה. שָׁמַע קוֹל הַתַּרְנְגוֹל מְבָרֵךְ הַנּוֹתֵן לַשֶּׂכְוִי בִינָה. וְכָל בְּרָכָה מֵהֶן שֶׁלֹּא נִתְחַיֵּב בָּהּ אֵינוֹ מְבָרֵךְ אוֹתָהּ:","כֵּיצַד. לָן בִּכְסוּתוֹ אֵינוֹ מְבָרֵךְ כְּשֶׁעוֹמֵד מַלְבִּישׁ עֲרוּמִים. הָלַךְ יָחֵף אֵינוֹ מְבָרֵךְ שֶׁעָשִׂיתָ לִי כָּל צָרְכִּי. בְּיוֹם הַכִּפּוּרִים וּבְתִשְׁעָה בְּאָב שֶׁאֵין שָׁם רְחִיצָה אֵינוֹ מְבָרֵךְ עַל נְטִילַת יָדַיִם וְלֹא הַמַּעֲבִיר חֶבְלֵי שֵׁנָה. אִם לֹא נִכְנַס לְבֵית הַכִּסֵּא אֵינוֹ מְבָרֵךְ אֲשֶׁר יָצַר אֶת הָאָדָם. וְכֵן שְׁאָר בְּרָכוֹת אֵלּוּ:","נָהֲגוּ הָעָם בְּרֹב עָרֵינוּ לְבָרֵךְ בְּרָכוֹת אֵלּוּ זוֹ אַחַר זוֹ בְּבֵית הַכְּנֶסֶת בֵּין נִתְחַיְּבוּ בָּהֶן בֵּין לֹא נִתְחַיְּבוּ בָּהֶן. וְטָעוּת הוּא וְאֵין רָאוּי לַעֲשׂוֹת כֵּן וְלֹא יְבָרֵךְ בְּרָכָה אֶלָּא אִם כֵּן נִתְחַיֵּב בָּהּ:","הַמַּשְׁכִּים לִקְרֹא בַּתּוֹרָה קֹדֶם שֶׁיִּקְרָא קְרִיאַת שְׁמַע בֵּין קָרָא בַּתּוֹרָה שֶׁבִּכְתָב בֵּין קָרָא בַּתּוֹרָה שֶׁבְּעַל פֶּה נוֹטֵל יָדָיו תְּחִלָּה וּמְבָרֵךְ שָׁלֹשׁ בְּרָכוֹת וְאַחַר כָּךְ קוֹרֵא. וְאֵלּוּ הֵן. אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ עַל דִּבְרֵי תוֹרָה. וְהַעֲרֶב נָא יְיָ׳‎ אֱלֹהֵינוּ אֶת דִּבְרֵי תוֹרָתְךָ בְּפִינוּ וּבְפִיפִּיּוֹת עַמְּךָ כָּל בֵּית יִשְׂרָאֵל וְנִהְיֶה אֲנַחְנוּ וְצֶאֱצָאֵינוּ וְצֶאֱצָאֵי עַמְּךָ יוֹדְעֵי שְׁמֶךָ וְעוֹסְקֵי תוֹרָתֶךָ לִשְׁמָהּ בָּרוּךְ אַתָּה יְיָ׳‎ הַמְלַמֵּד תּוֹרָה לְעַמּוֹ יִשְׂרָאֵל. בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר בָּחַר בָּנוּ מִכָּל הָעַמִּים וְנָתַן לָנוּ אֶת תּוֹרָתוֹ בָּרוּךְ אַתָּה יְיָ׳‎ נוֹתֵן הַתּוֹרָה:","בְּכָל יוֹם חַיָּב אָדָם לְבָרֵךְ שָׁלֹשׁ בְּרָכוֹת אֵלּוּ וְאַחַר כָּךְ קוֹרֵא מְעַט מִדִּבְרֵי תּוֹרָה. וְנָהֲגוּ הָעָם לִקְרֹא (במדבר ו כב כז) ״בִּרְכַּת כֹּהֲנִים״. וְיֵשׁ מְקוֹמוֹת שֶׁקּוֹרִין (במדבר כח ב) ״צַו אֶת בְּנֵי יִשְׂרָאֵל״. וְיֵשׁ מְקוֹמוֹת שֶׁקּוֹרִין שְׁתֵּיהֶן. וְקוֹרִין פְּרָקִים אוֹ הֲלָכוֹת מִן הַמִּשְׁנָה וּמִן הַבְּרַיְתּוֹת:","וְשִׁבְּחוּ חֲכָמִים לְמִי שֶׁקּוֹרֵא זְמִירוֹת מִסֵּפֶר תְּהִלִּים בְּכָל יוֹם וָיוֹם מִ(תהילים קמה א) ״תְּהִלָּה לְדָוִד״ עַד סוֹף הַסֵּפֶר. וּכְבָר נָהֲגוּ לִקְרוֹת פְּסוּקִים לִפְנֵיהֶם וּלְאַחֲרֵיהֶם וְתִקְּנוּ בְּרָכָה לִפְנֵי הַזְּמִירוֹת וְהִיא בָּרוּךְ שֶׁאָמַר וּבְרָכָה לְאַחֲרֵיהֶם וְהִיא יִשְׁתַּבַּח. וְאַחַר כָּךְ מְבָרֵךְ עַל קְרִיאַת שְׁמַע וְקוֹרֵא קְרִיאַת שְׁמַע:","יֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ בָּהֶן לִקְרוֹת בְּכָל יוֹם אַחַר שֶׁמְּבָרְכִין יִשְׁתַּבַּח (שמות טו א יט) ״שִׁירַת הַיָּם״ וְאַחַר כָּךְ מְבָרְכִין עַל שְׁמַע. וְיֵשׁ מְקוֹמוֹת שֶׁקּוֹרִין (דברים לב א מג) ״שִׁירַת הַאֲזִינוּ״. וְיֵשׁ יְחִידִים שֶׁקּוֹרִין שְׁתֵּי הַשִּׁירוֹת הַכּל לְפִי הַמִּנְהָג:","חַיָּב אָדָם לְבָרֵךְ מֵאָה בְּרָכוֹת בֵּין הַיּוֹם וְהַלַּיְלָה. וּמַה הֵן מֵאָה בְּרָכוֹת אֵלּוּ. כ״ג בְּרָכוֹת שֶׁמָּנִינוּ בְּפֶרֶק זֶה. וְשֶׁבַע בְּרָכוֹת שֶׁל קְרִיאַת שְׁמַע שֶׁל שַׁחֲרִית וְעַרְבִית לְפָנֶיהָ וּלְאַחֲרֶיהָ. וּכְשֶׁמִּתְעַטֵּף בַּצִּיצִית מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ לְהִתְעַטֵּף בְּצִיצִית. וּכְשֶׁלּוֹבֵשׁ תְּפִלִּין מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ לְהָנִיחַ תְּפִלִּין. וְשָׁלֹשׁ תְּפִלּוֹת שֶׁבְּכָל תְּפִלָּה מֵהֶן שְׁמוֹנֶה עֶשְׂרֵה בְּרָכוֹת הֲרֵי שְׁמוֹנִים וְשֵׁשׁ בְּרָכוֹת. וּכְשֶׁהוּא אוֹכֵל שְׁתֵּי סְעֻדּוֹת שֶׁל יוֹם וְהַלַּיְלָה מְבָרֵךְ אַרְבַּע עֶשְׂרֵה בְּרָכוֹת. שֶׁבַע בְּכָל סְעֻדָּה. אַחַת כְּשֶׁיִּטּל יָדָיו תְּחִלָּה. וְעַל הַמָּזוֹן אַחַת בַּתְּחִלָּה וְשָׁלֹשׁ בַּסּוֹף וְעַל הַיַּיִן לְפָנָיו וּלְאַחֲרָיו הֲרֵי שֶׁבַע בְּרָכוֹת הֲרֵי מֵאָה בְּרָכוֹת בֵּין הַכּל:","בַּזְּמַן הַזֶּה שֶׁתִּקְּנוּ בִּרְכַּת הָאֶפִּיקוֹרוֹסִין בַּתְּפִלָּה וְהוֹסִיפוּ הַטּוֹב וְהַמֵּיטִיב בְּבִרְכַּת הַמָּזוֹן נִמְצְאוּ חָמֵשׁ בְּרָכוֹת יְתֵרוֹת. בְּשַׁבָּתוֹת וְיָמִים טוֹבִים שֶׁהַתְּפִלָּה שֶׁבַע בְּרָכוֹת, וְכֵן אִם לֹא נִתְחַיֵּב בִּשְׁאָר הַיָּמִים בְּכָל הַבְּרָכוֹת הָאֵלּוּ כְּגוֹן שֶׁלֹּא יָשַׁן כָּל הַלַּיְלָה וְלֹא הִתִּיר חֲגוֹרוֹ וְלֹא נִכְנַס לְבֵית הַכִּסֵּא וְכַיּוֹצֵא בְּאֵלּוּ, צָרִיךְ לְהַשְׁלִים מֵאָה בְּרָכוֹת מִן הַפֵּרוֹת:","כֵּיצַד. אוֹכֵל מְעַט יָרָק וּמְבָרֵךְ לְפָנָיו וּלְאַחֲרָיו וְחוֹזֵר וְאוֹכֵל מְעַט מִפְּרִי זֶה וּמְבָרֵךְ לְפָנָיו וּלְאַחֲרָיו וּמוֹנֶה כָּל הַבְּרָכוֹת עַד שֶׁמַּשְׁלִים מֵאָה בְּכָל יוֹם:","סֵדֶר תְּפִלּוֹת כָּךְ הוּא. בַּשַּׁחַר מַשְׁכִּים אָדָם וּמְבָרֵךְ בְּרָכוֹת אֵלּוּ. וְקוֹרֵא הַזְּמִירוֹת וּמְבָרֵךְ לִפְנֵיהֶם וּלְאַחֲרֵיהֶם. וְקוֹרֵא אַחַר כָּךְ שְׁמַע וּמְבָרֵךְ לְפָנֶיהָ וּלְאַחֲרֶיהָ. וּמְדַלֵּג קְדֻשָּׁה מִן הַבְּרָכָה רִאשׁוֹנָה שֶׁלְּפָנֶיהָ שֶׁאֵין הַיָּחִיד אוֹמֵר קְדֻשָּׁה. וּכְשֶׁהוּא חוֹתֵם גָּאַל יִשְׂרָאֵל מִיָּד יַעֲמֹד כְּדֵי שֶׁיִּסְמֹךְ גְּאֻלָּה לִתְפִלָּה וּמִתְפַּלֵּל מְעֻמָּד כְּמוֹ שֶׁאָמַרְנוּ. וּכְשֶׁיַּשְׁלִים יֵשֵׁב וְיִפּל עַל פָּנָיו וּמִתְחַנֵּן וּמַגְבִּיהַּ רֹאשׁוֹ וּמִתְחַנֵּן מְעַט וְהוּא יוֹשֵׁב בְּדִבְרֵי תַּחֲנוּנִים. וְאַחַר כָּךְ יִקְרָא (תהילים קמה א) ״תְּהִלָּה לְדָוִד״ (מְיֻשָּׁב) וְיִתְחַנֵּן כְּפִי כֹּחוֹ וְיִפָּטֵר לְמַעֲשָׂיו:","וּבִתְפִלַּת הַמִּנְחָה מַתְחִיל לִקְרֹא (תהילים קמה א) ״תְּהִלָּה לְדָוִד״ מְיֻשָּׁב וְאַחַר כָּךְ עוֹמֵד וּמִתְפַּלֵּל תְּפִלַּת הַמִּנְחָה וּכְשֶׁמַּשְׁלִים נוֹפֵל עַל פָּנָיו וּמִתְחַנֵּן וּמַגְבִּיהַּ רֹאשׁוֹ וְיִתְחַנֵּן כְּפִי כֹּחוֹ וְיִפָּטֵר לְמַעֲשָׂיו. וּבִתְפִלַּת הָעֶרֶב קוֹרֵא קְרִיאַת שְׁמַע וּמְבָרֵךְ לְפָנֶיהָ וּלְאַחֲרֶיהָ וְסוֹמֵךְ גְּאֻלָּה לִתְפִלָּה וּמִתְפַּלֵּל מְעֻמָּד וּכְשֶׁיַּשְׁלִים יֵשֵׁב מְעַט וְיִפָּטֵר. וְהַמִּתְחַנֵּן אַחַר תְּפִלַּת עַרְבִית הֲרֵי זֶה מְשֻׁבָּח. וְאַף עַל פִּי שֶׁמְּבָרֵךְ הַשְׁכִּיבֵנוּ אַחַר גָּאַל יִשְׂרָאֵל אֵינָהּ הֶפְסֵק בֵּין גְּאֻלָּה לִתְפִלָּה וַהֲרֵי שְׁתֵּיהֶן כִּבְרָכָה אַחַת אֲרֻכָּה:"],"Mishneh Torah, Rebels 6":["כִּבּוּד אָב וָאֵם מִצְוַת עֲשֵׂה גְּדוֹלָה וְכֵן מוֹרָא אָב וָאֵם. שָׁקַל אוֹתָן הַכָּתוּב בִּכְבוֹדוֹ וּבְמוֹרָאוֹ. כָּתוּב (שמות כ יב) \"כַּבֵּד אֶת אָבִיךָ וְאֶת אִמֶּךָ\" וְכָתוּב (משלי ג ט) \"כַּבֵּד אֶת ה' מֵהוֹנֶךָ\". וּבְאָבִיו וְאִמּוֹ כָּתוּב (ויקרא יט ג) \"אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ\" וְכָתוּב (דברים ו יג) \"אֶת ה' אֱלֹהֶיךָ תִּירָא\". כְּדֶרֶךְ שֶׁצִּוָּה עַל כְּבוֹד שְׁמוֹ הַגָּדוֹל וּמוֹרָאוֹ כָּךְ צִוָּה עַל כְּבוֹדָם וּמוֹרָאָם:","הַמְקַלֵּל אָבִיו אוֹ אִמּוֹ בִּסְקִילָה וְהַמְגַדֵּף בִּסְקִילָה. הִנֵּה הִשְׁוָה אוֹתָן בָּעֹנֶשׁ. הִקְדִּים אָב לְאֵם לְכָבוֹד וְהִקְדִּים אֵם לְאָב לְמוֹרָא לְלַמֵּד שֶׁשְּׁנֵיהֶם שָׁוִים בֵּין לַמּוֹרָא בֵּין לְכָבוֹד:","אֵי זֶהוּ מוֹרָא וְאֵי זֶהוּ כָּבוֹד. מוֹרָא לֹא עוֹמֵד בִּמְקוֹמוֹ. וְלֹא יוֹשֵׁב בִּמְקוֹמוֹ. וְלֹא סוֹתֵר אֶת דְּבָרָיו וְלֹא מַכְרִיעַ אֶת דְּבָרָיו. וְלֹא יִקְרָא לוֹ בִּשְׁמוֹ לֹא בְּחַיָּיו וְלֹא בְּמוֹתוֹ. אֶלָּא אוֹמֵר אַבָּא מָרִי. הָיָה שֵׁם אָבִיו אוֹ שֵׁם רַבּוֹ כְּשֵׁם אֲחֵרִים מְשַׁנֶּה אֶת שְׁמָם. יֵרָאֶה לִי שֶׁאֵין נִזְהָר בְּכָךְ אֶלָּא בְּשֵׁם שֶׁהוּא פֶּלֶא שֶׁאֵין הַכּל דָּשִׁין בּוֹ. אֲבָל הַשֵּׁמוֹת שֶׁקּוֹרְאִים בָּהֶן אֶת הָעָם כְּגוֹן אַבְרָהָם יִצְחָק וְיַעֲקֹב משֶׁה וְכַיּוֹצֵא בָּהֶן בְּכָל לָשׁוֹן וּבְכָל זְמַן קוֹרֵא בָּהֶן לַאֲחֵרִים שֶׁלֹּא בְּפָנָיו וְאֵין בְּכָךְ כְּלוּם. אֵי זֶהוּ כָּבוֹד מַאֲכִיל וּמַשְׁקֵה מַלְבִּישׁ וּמְכַסֶּה מִשֶּׁל הָאָב. וְאִם אֵין מָמוֹן לָאָב וְיֵשׁ מָמוֹן לַבֵּן כּוֹפִין אוֹתוֹ וְזָן אָבִיו וְאִמּוֹ כְּפִי מַה שֶּׁהוּא יָכוֹל. וּמוֹצִיא וּמַכְנִיס וּמְשַׁמְּשׁוֹ בִּשְׁאָר הַדְּבָרִים שֶׁהַשַּׁמָּשִׁים מְשַׁמְּשִׁים בָּהֶן אֶת הָרַב. וְעוֹמֵד מִפָּנָיו כְּדֶרֶךְ שֶׁהוּא עוֹמֵד מִפְּנֵי רַבּוֹ:","וְהָאָב שֶׁהָיָה תַּלְמִיד בְּנוֹ אֵין הָאָב עוֹמֵד מִפְּנֵי הַבֵּן אֲבָל הַבֵּן עוֹמֵד מִפְּנֵי אָבִיו אַף עַל פִּי שֶׁהוּא תַּלְמִידוֹ וְחַיָּב לְכַבְּדוֹ בִּשְׁאָר דְּרָכָיו בִּשְׁעַת עֲשִׂיַּת מַשָּׂאוֹ וּמַתָּנוֹ וַעֲשִׂיַּת חֲפָצָיו. כֵּיצַד. הַנִּשְׁמָע בִּדְבַר אָבִיו לְמָקוֹם לֹא יֹאמַר מַהֲרוּנִי בִּשְׁבִיל עַצְמִי פִּטְרוּנִי בִּשְׁבִיל עַצְמִי. אֶלָּא מַהֲרוּנִי בִּשְׁבִיל אַבָּא פִּטְרוּנִי בִּשְׁבִיל אַבָּא. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. לְעוֹלָם יִכְלל בִּכְלַל דְּבָרָיו שֶׁהוּא חוֹשֵׁשׁ בִּכְבוֹד אָבִיו וְשֶׁמִּתְיָרֵא מִמֶּנּוּ:","וְחַיָּב לְכַבְּדוֹ אֲפִלּוּ לְאַחַר מוֹתוֹ. כֵּיצַד. הָיָה אוֹמֵר דְּבַר שְׁמוּעָה מִפִּיו לֹא יֹאמַר כָּךְ אָמַר אַבָּא. אֶלָּא אוֹמֵר כָּךְ אָמַר אַבָּא מָרִי אֲנִי כַּפָּרַת מִשְׁכָּבוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּתוֹךְ שְׁנֵים עָשָׂר חֹדֶשׁ שֶׁלְּאַחַר מִיתָתוֹ. אֲבָל לְאַחַר שְׁנֵים עָשָׂר חֹדֶשׁ אוֹמֵר זִכְרוֹנוֹ לְחַיֵּי הָעוֹלָם הַבָּא:","אֶחָד הָאִישׁ וְאֶחָד הָאִשָּׁה חַיָּבִין בְּמוֹרָא וְכָבוֹד. אֶלָּא שֶׁהָאִישׁ יֵשׁ בְּיָדוֹ לַעֲשׂוֹת וְהָאִשָּׁה אֵין בְּיָדָהּ לַעֲשׂוֹת שֶׁהֲרֵי רְשׁוּת אֲחֵרִים עָלֶיהָ. לְפִיכָךְ אִם נִתְגָּרְשָׁה אוֹ נִתְאַלְמְנָה הֲרֵי שְׁנֵיהֶם שָׁוִים:","עַד הֵיכָן הוּא כִּבּוּד אָב וְאֵם. אֲפִלּוּ נָטְלוּ כִּיס שֶׁל זְהוּבִים שֶׁלּוֹ וְהִשְׁלִיכוּ בְּפָנָיו לַיָּם לֹא יַכְלִימֵם וְלֹא יְצַעֵר בִּפְנֵיהֶם וְלֹא יִכְעֹס כְּנֶגְדָּם אֶלָּא יְקַבֵּל גְּזֵרַת הַכָּתוּב וְיִשְׁתֹּק. וְעַד הֵיכָן מוֹרָאָן אֲפִלּוּ הָיָה לוֹבֵשׁ בְּגָדִים חֲמוּדוֹת וְיוֹשֵׁב בָּרֹאשׁ בִּפְנֵי הַקָּהָל וּבָא אָבִיו וְאִמּוֹ וְקָרְעוּ בְּגָדָיו וְהִכּוּהוּ בְּרֹאשׁוֹ וְיָרְקוּ בְּפָנָיו לֹא יַכְלִימֵם אֶלָּא יִשְׁתֹּק וְיִירָא וְיִפְחַד מִמֶּלֶךְ מַלְכֵי הַמְּלָכִים שֶׁצִּוָּהוּ בְּכָךְ. שֶׁאִלּוּ מֶלֶךְ בָּשָׂר וָדָם גָּזַר עָלָיו דָּבָר שֶׁהוּא מְצַעֵר יֶתֶר מִזֶּה לֹא הָיָה יָכוֹל לְפַרְכֵּס בַּדָּבָר. קַל וָחֹמֶר לְמִי שֶׁאָמַר וְהָיָה הָעוֹלָם כִּרְצוֹנוֹ:","אַף עַל פִּי שֶׁבְּכָךְ נִצְטַוֵּינוּ אָסוּר לְאָדָם לְהַכְבִּיד עֵלּוֹ עַל בָּנָיו וּלְדַקְדֵּק בִּכְבוֹדוֹ עִמָּהֶם שֶׁלֹּא יְבִיאֵם לִידֵי מִכְשׁוֹל. אֶלָּא יִמְחל וְיִתְעַלֵּם שֶׁהָאָב שֶׁמָּחַל עַל כְּבוֹדוֹ כְּבוֹדוֹ מָחוּל:","וְהַמַּכֶּה בְּנוֹ גָּדוֹל מְנַדִּין אוֹתוֹ שֶׁהֲרֵי הוּא עוֹבֵר עַל וְלִפְנֵי עִוֵּר לֹא תִתֵּן מִכְשׁל:","מִי שֶׁנִּטְרְפָה דַּעְתּוֹ שֶׁל אָבִיו אוֹ שֶׁל אִמּוֹ מִשְׁתַּדֵּל לִנְהֹג עִמָּהֶם כְּפִי דַּעְתָּם עַד שֶׁיְּרֻחַם עֲלֵיהֶן. וְאִם אִי אֶפְשָׁר לוֹ לַעֲמֹד מִפְּנֵי שֶׁנִּשְׁתַּטּוּ בְּיוֹתֵר יְנִיחֵם וְיֵלֵךְ לוֹ וִיצַוֶּה אֲחֵרִים לְהַנְהִיגָם כָּרָאוּי לָהֶם:","הַמַּמְזֵר חַיָּב בִּכְבוֹד אָבִיו וּמוֹרָאוֹ אַף עַל פִּי שֶׁהוּא פָּטוּר עַל מַכָּתוֹ וְקִלְלָתוֹ עַד שֶׁיַּעֲשֶׂה תְּשׁוּבָה. אֲפִלּוּ הָיָה אָבִיו רָשָׁע וּבַעַל עֲבֵרוֹת מְכַבְּדוֹ וּמִתְיָרֵא מִמֶּנּוּ. רָאָהוּ עוֹבֵר עַל דִּבְרֵי תּוֹרָה לֹא יֹאמַר לוֹ אַבָּא עָבַרְתָּ עַל דִּבְרֵי תּוֹרָה אֶלָּא יֹאמַר לוֹ אַבָּא כָּתוּב בַּתּוֹרָה כָּךְ וְכָךְ כְּאִלּוּ הוּא שׁוֹאֵל מִמֶּנּוּ וְלֹא כְּמַזְהִירוֹ:","מִי שֶׁאָמַר לוֹ אָבִיו לַעֲבֹר עַל דִּבְרֵי תּוֹרָה בֵּין שֶׁאָמַר לוֹ לַעֲבֹר עַל מִצְוַת לֹא תַּעֲשֶׂה אוֹ לְבַטֵּל מִצְוַת עֲשֵׂה אֲפִלּוּ שֶׁל דִּבְרֵיהֶם. הֲרֵי זֶה לֹא יִשְׁמַע לוֹ שֶׁנֶּאֱמַר (ויקרא יט ג) \"אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ וְאֶת שַׁבְּתֹתַי תִּשְׁמֹרוּ\". כֻּלְּכֶם חַיָּבִין בִּכְבוֹדִי:","אָמַר לוֹ אָבִיו הַשְׁקֵנִי מַיִם וְיֵשׁ בְּיָדוֹ לַעֲשׂוֹת מִצְוָה אִם אֶפְשָׁר לַמִּצְוָה שֶׁתֵּעָשֶׂה עַל יְדֵי אֲחֵרִים תֵּעָשֶׂה וְיִתְעַסֵּק בִּכְבוֹד אָבִיו שֶׁאֵין מְבַטְּלִין מִצְוָה מִפְּנֵי מִצְוָה. וְאִם אֵין שָׁם אֲחֵרִים לַעֲשׂוֹתָהּ יִתְעַסֵּק בַּמִּצְוָה וְיָנִיחַ כָּבוֹד אָבִיו שֶׁהוּא וְאָבִיו חַיָּבִים בִּדְבַר מִצְוָה. וְתַלְמוּד תּוֹרָה גָּדוֹל מִכְּבוֹד אָב וָאֵם:","אָמַר לוֹ אָבִיו הַשְׁקֵנִי מַיִם וְאָמְרָה לוֹ אִמּוֹ הַשְׁקֵנִי מַיִם מֵנִיחַ כְּבוֹד אִמּוֹ וְעוֹסֵק בִּכְבוֹד אָבִיו תְּחִלָּה מִפְּנֵי שֶׁהוּא וְאִמּוֹ חַיָּבִין בִּכְבוֹד אָבִיו:","חַיָּב אָדָם לְכַבֵּד אֶת אֵשֶׁת אָבִיו אַף עַל פִּי שֶׁאֵינָהּ אִמּוֹ כָּל זְמַן שֶׁאָבִיו קַיָּם שֶׁזֶּה בִּכְלַל כְּבוֹד אָבִיו. וְכֵן מְכַבֵּד בַּעַל אִמּוֹ כָּל זְמַן שֶׁאִמּוֹ קַיֶּמֶת. אֲבָל לְאַחַר מִיתָתָהּ אֵינוֹ חַיָּב. וּמִדִּבְרֵי סוֹפְרִים שֶׁיִּהְיֶה אָדָם חַיָּב בִּכְבוֹד אָחִיו הַגָּדוֹל כִּכְבוֹד אָבִיו:"],"Mishneh Torah, Red Heifer 5":["כָּל הָעוֹסְקִין בַּפָּרָה מִתְּחִלָּה וְעַד סוֹף מְטַמְּאִין בְּגָדִים כָּל זְמַן עֲשִׂיָּתָן שֶׁנֶּאֱמַר בְּשׁוֹחֵט וּמַשְׁלִיךְ עֵץ אֶרֶז (ויקרא טו יג) \"וְכִבֶּס בְּגָדָיו וְרָחַץ בְּשָׂרוֹ\" וְנֶאֱמַר בְּשׂוֹרֵף (במדבר יט ח) \"וְהַשֹּׂרֵף אֹתָהּ יְכַבֵּס בְּגָדָיו\" וְנֶאֱמַר (במדבר יט י) \"וְכִבֶּס הָאֹסֵף אֶת אֵפֶר הַפָּרָה\" מְלַמֵּד שֶׁכָּל הָעוֹסְקִין בָּהּ מִתְּחִלָּה וְעַד סוֹף מְטַמְּאִים בְּגָדִים וּטְעוּנִין טְבִילָה וְהַעֲרֵב שֶׁמֶשׁ דִּין תּוֹרָה. אֲבָל הַמְשַׁמְּרָהּ בִּשְׁעַת עֲשִׂיָּתָהּ מְטַמֵּא בְּגָדִים מִדִּבְרֵיהֶם גְּזֵרָה שֶׁמָּא יָזִיז בָּהּ אֵיבָר:","כָּל מָקוֹם שֶׁנֶּאֱמַר בַּתּוֹרָה בְּטֻמְאוֹת יְכַבֵּס בְּגָדָיו לֹא בָּא לְלַמְּדֵנוּ שֶׁהַבְּגָדִים שֶׁעָלָיו בִּלְבַד הֵם טְמֵאִים. אֶלָּא לְלַמֵּד שֶׁכָּל בֶּגֶד אוֹ כְּלִי שֶׁיִּגַּע בּוֹ הַטָּמֵא הַזֶּה בִּשְׁעַת חִבּוּרוֹ בִּמְטַמְּאָיו הֲרֵי הֵן טְמֵאִים. אֲבָל אַחַר שֶׁיִּפְרשׁ מִמְּטַמְּאָיו אֵינוֹ מְטַמֵּא בְּגָדִים. כֵּיצַד. הַנּוֹשֵׂא אֶת הַנְּבֵלָה אֶחָד בֶּגֶד שֶׁעָלָיו אוֹ כְּלִי שֶׁיִּגַּע בּוֹ כָּל זְמַן שֶׁהוּא נוֹשְׂאָהּ הֲרֵי הֵן טְמֵאִין וַהֲרֵי הֵן רִאשׁוֹן לְטֻמְאָה. וְכֵן זֶה הַנּוֹשֵׂא הֲרֵי הוּא רִאשׁוֹן. פֵּרַשׁ מִמְּטַמְּאָיו וְהִשְׁלִיךְ אֶת הַנְּבֵלָה הֲרֵי הוּא רִאשׁוֹן כְּמוֹת שֶׁהָיָה. וְאִם יִגַּע בִּכְלִי אוֹ בֶּגֶד אֵינוֹ מְטַמֵּא אוֹתוֹ שֶׁאֵין וְלַד טֻמְאָה מְטַמֵּא כֵּלִים כְּמוֹ שֶׁבֵּאַרְנוּ בִּתְחִלַּת סֵפֶר זֶה. וְכֵן כָּל כַּיּוֹצֵא בִּנְבֵלָה. וְכֵן כָּל הָעוֹסְקִין בַּפָּרָה אִם נָגַע בְּבֶגֶד אוֹ בִּכְלִי בִּשְׁעַת שְׁחִיטָה אוֹ בִּשְׁעַת שְׂרֵפָה הֲרֵי הֵן טְמֵאִין. אֲבָל אַחַר שֶׁיִּפְרשׁ מִמַּעֲשֶׂיהָ אַף עַל פִּי שֶׁעֲדַיִן לֹא טָבַל אִם נָגַע בִּכְלִי אֵינוֹ מְטַמְּאוֹ מִפְּנֵי שֶׁהוּא וְלַד הַטֻּמְאָה. וְהַפָּרָה עַצְמָהּ אֵינָהּ מְטַמְּאָה לֹא אָדָם וְלֹא כֵּלִים שֶׁנָּגְעוּ בּוֹ. אֶלָּא הַמִּתְעַסֵּק בָּהּ בִּלְבַד הוּא הַטָּמֵא וְטָעוּן טְבִילָה וּמְטַמֵּא בְּגָדִים כָּל זְמַן שֶׁעוֹסֵק בָּהּ:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּזְמַן שֶׁנִּשְׂרֶפֶת כְּמִצְוָתָהּ. אֲבָל אִם נִפְסְלָה הַמִּתְעַסֵּק בָּהּ טָהוֹר. אֵרַע פִּסּוּל בִּשְׁחִיטָתָהּ אֵינָהּ מְטַמְּאָה בְּגָדִים. אֵרַע פִּסּוּל בְּהַזָּיָתָהּ כָּל הָעוֹסֵק בָּהּ לִפְנֵי פִּסּוּלָהּ מְטַמֵּא בְּגָדִים. לְאַחַר פִּסּוּלָהּ אֵינוֹ מְטַמֵּא בְּגָדִים:","הִשְׁלִים לִכְנֹס אֶת אֶפְרָהּ הַמִּתְעַסֵּק בָּהּ אַחַר כֵּן בְּחִלּוּק הֶעָפָר אוֹ בְּהַצְנָעָתוֹ וְכֵן הַנּוֹגֵעַ בּוֹ טָהוֹר. וְלֹא הַפָּרָה בִּלְבַד אֶלָּא כָּל הַחַטָּאוֹת הַנִּשְׂרָפוֹת מִן הַפָּרִים וּמִן הַשְּׂעִירִים הַשּׂוֹרְפָם מְטַמֵּא בְּגָדִים בִּשְׁעַת שְׂרֵפָתוֹ עַד שֶׁיֵּעָשׂוּ אֵפֶר. שֶׁהֲרֵי הוּא אוֹמֵר בְּפַר וְשָׂעִיר שֶׁל יוֹם הַכִּפּוּרִים (ויקרא טז כח) \"וְהַשֹּׂרֵף אֹתָם יְכַבֵּס\" מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזֶּה בִּנְיַן אָב לְכָל הַנִּשְׂרָפִים שֶׁיְּהוּ מְטַמְּאִין בְּגָדִים עַד שֶׁיֵּעָשׂוּ אֵפֶר. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁלֹּא אֵרַע לָהֶן פִּסּוּל וְנִשְׂרְפוּ כְּמִצְוָתָן בְּבֵית הַדֶּשֶׁן. אֲבָל אִם נִפְסְלוּ בָּעֲזָרָה נִשְׂרָפִין שָׁם כִּפְסוּלֵי הַמֻּקְדָּשִׁין וְשׂוֹרְפָן טָהוֹר. וְכֵן הַמִּתְעַסֵּק בָּהֶן מִשֶּׁיֵּעָשׂוּ אֵפֶר אֵינוֹ מְטַמֵּא בְּגָדִים. וְאֵי זֶהוּ שׂוֹרֵף זֶה הַמַּסִּיעַ בִּשְׂרֵפָה כְּגוֹן הַמְהַפֵּךְ בַּבָּשָׂר וְהַמַּשְׁלִיךְ עֵצִים וְהַמְהַפֵּךְ בָּאֵשׁ וְהַחוֹתֶה גֶּחָלִים כְּדֵי שֶׁתִּבְעַר הָאֵשׁ וְכַיּוֹצֵא בָּהֶן. אֲבָל הַמַּצִּית הָאוּר וְהַמְסַדֵּר אֶת הַמַּעֲרָכָה טָהוֹר. כָּךְ לָמְדוּ מִפִּי הַשְּׁמוּעָה שֶׁהַנּוֹשֵׂא פָּרִים וּשְׂעִירִים הַנִּשְׂרָפִין לְהוֹצִיאָן לְבֵית הַדֶּשֶׁן לְשָׂרְפָן טָמֵא וּמְטַמֵּא בְּגָדִים דִּין תּוֹרָה כָּל זְמַן שֶׁהוּא עוֹסֵק בְּהוֹלָכָתָן וְטָעוּן טְבִילָה וְהַעֲרֵב שֶׁמֶשׁ. כְּמוֹ הַמְשַׁלֵּחַ אֶת הַשָּׂעִיר לַעֲזָאזֵל שֶׁהוּא מְטַמֵּא כָּל בֶּגֶד וְכָל כְּלִי שֶׁיִּגַּע בּוֹ בְּכֵלִים שֶׁעָלָיו כָּל זְמַן שֶׁמִּתְעַסֵּק בִּשְׁלוּחוֹ שֶׁנֶּאֱמַר (ויקרא טז כו) \"וְהַמְשַׁלֵּחַ אֶת הַשָּׂעִיר לַעֲזָאזֵל יְכַבֵּס בְּגָדָיו\":","מֵאֵימָתַי מְטַמְּאִין בְּגָדִים הַנּוֹשְׂאִין פָּרִים וּשְׂעִירִים הַנִּשְׂרָפִים. מִשֶּׁיֵּצְאוּ בָּהֶן חוּץ לְחוֹמַת הָעֲזָרָה. נְשָׂאוּם בְּמוֹטוֹת וְיָצְאוּ מִקְצָת הַנּוֹשְׂאִים חוּץ לְחוֹמַת הָעֲזָרָה וְהָאַחֲרוֹנִים לֹא יָצְאוּ. אֵלּוּ שֶׁיָּצְאוּ מְטַמְּאִין בְּגָדִים וְאֵלּוּ שֶׁעֲדַיִן לֹא יָצְאוּ אֵינָן מְטַמְּאִין בְּגָדִים עַד שֶׁיֵּצְאוּ. יָצְאוּ וְחָזְרוּ לָעֲזָרָה הַנּוֹשֵׂא אוֹתָן בָּעֲזָרָה טָהוֹר עַד שֶׁיֵּצֵא בָּהֶן. הָיָה עוֹמֵד חוּץ לָעֲזָרָה וּמוֹשֵׁךְ אוֹתָם מִשָּׁם מֵאַחַר שֶׁחָזְרוּ הוֹאִיל וּכְבָר יָצְאוּ לַחוּץ וַהֲרֵי זֶה הַמּוֹשְׁכָם בַּחוּץ הֲרֵי הוּא סְפֵק טָמֵא:","וּמֵאֵימָתַי מְטַמֵּא בְּגָדִים הַמְשַׁלֵּחַ אֶת הַשָּׂעִיר. מִשֶּׁיֵּצֵא חוּץ לְחוֹמַת יְרוּשָׁלַיִם עַד שְׁעַת דְּחִיָּתוֹ לַעֲזָאזֵל. אֲבָל אַחַר שֶׁדָּחָהוּ אִם נָגַע בְּכֵלִים וּבִבְגָדִים טְהוֹרִים:","הַנּוֹגֵעַ בְּפָרִים וּבִשְׂעִירִין הַנִּשְׂרָפִין עַצְמָן אֲפִלּוּ אַחַר שֶׁיָּצְאוּ בֵּין אָדָם בֵּין כֵּלִים בֵּין אֳכָלִין בֵּין מַשְׁקִין הַכּל טָהוֹר. וְכֵן אִם נָגְעוּ בַּשָּׂעִיר הַמִּשְׁתַּלֵּחַ עַצְמוֹ בִּזְמַן הוֹלָכָתוֹ טְהוֹרִין. שֶׁאֵין אֵלּוּ מְטַמְּאִין אֶלָּא לַמִּתְעַסֵּק בָּהֶן בִּלְבַד שֶׁנֶּאֱמַר (במדבר יט ח) \"וְהַשֹּׂרֵף אֹתָהּ יְכַבֵּס בְּגָדָיו\" אֲבָל הַנּוֹגֵעַ טָהוֹר:"],"Mishneh Torah, Repentance 7":["הוֹאִיל וּרְשׁוּת כָּל אָדָם נְתוּנָה לוֹ כְּמוֹ שֶׁבֵּאַרְנוּ יִשְׁתַּדֵּל אָדָם לַעֲשׂוֹת תְּשׁוּבָה וּלְהִתְוַדּוֹת בְּפִיו מֵחֲטָאָיו וְלִנְעֹר כַּפָּיו מֵחֲטָאָיו כְּדֵי שֶׁיָּמוּת וְהוּא בַּעַל תְּשׁוּבָה וְיִזְכֶּה לְחַיֵּי הָעוֹלָם הַבָּא:","לְעוֹלָם יִרְאֶה אָדָם עַצְמוֹ כְּאִלּוּ הוּא נוֹטֶה לָמוּת וְשֶׁמָּא יָמוּת בִּשְׁעָתוֹ וְנִמְצָא עוֹמֵד בְּחֶטְאוֹ. לְפִיכָךְ יָשׁוּב מֵחֲטָאָיו מִיָּד וְלֹא יֵאָמֵר כְּשֶׁאַזְקִין אָשׁוּב שֶׁמָּא יָמוּת טֶרֶם שֶׁיַּזְקִין. הוּא שֶׁשְּׁלֹמֹה אָמַר בְּחָכְמָתוֹ (קהלת ט ח) \"בְּכָל עֵת יִהְיוּ בְגָדֶיךָ לְבָנִים\":","אַל תֹּאמַר שֶׁאֵין תְּשׁוּבָה אֶלָּא מֵעֲבֵרוֹת שֶׁיֵּשׁ בָּהֶן מַעֲשֶׂה כְּגוֹן זְנוּת וְגֵזֶל וּגְנֵבָה. אֶלָּא כְּשֵׁם שֶׁצָּרִיךְ אָדָם לָשׁוּב מֵאֵלּוּ כָּךְ הוּא צָרִיךְ לְחַפֵּשׂ בְּדֵעוֹת רָעוֹת שֶׁיֵּשׁ לוֹ וְלָשׁוּב מִן הַכַּעַס וּמִן הָאֵיבָה וּמִן הַקִּנְאָה וּמִן הַהִתּוּל וּמֵרְדִיפַת הַמָּמוֹן וְהַכָּבוֹד וּמֵרְדִיפַת הַמַּאֲכָלוֹת וְכַיּוֹצֵא בָּהֶן מִן הַכּל צָרִיךְ לַחֲזֹר בִּתְשׁוּבָה. וְאֵלּוּ הָעֲוֹנוֹת קָשִׁים מֵאוֹתָן שֶׁיֵּשׁ בָּהֶן מַעֲשֶׂה שֶׁבִּזְמַן שֶׁאָדָם נִשְׁקָע בְּאֵלּוּ קָשֶׁה הוּא לִפְרשׁ מֵהֶם. וְכֵן הוּא אוֹמֵר (ישעיה נה ז) \"יַעֲזֹב רָשָׁע\" וְגוֹ':","וְאַל יְדַמֶּה אָדָם בַּעַל תְּשׁוּבָה שֶׁהוּא מְרֻחָק מִמַּעֲלַת הַצַּדִּיקִים מִפְּנֵי הָעֲוֹנוֹת וְהַחֲטָאוֹת שֶׁעָשָׂה. אֵין הַדָּבָר כֵּן אֶלָּא אָהוּב וְנֶחְמָד הוּא לִפְנֵי הַבּוֹרֵא כְּאִלּוּ לֹא חָטָא מֵעוֹלָם. וְלֹא עוֹד אֶלָּא שֶׁשְּׂכָרוֹ הַרְבֵּה שֶׁהֲרֵי טָעַם טַעַם הַחֵטְא וּפֵרַשׁ מִמֶּנּוּ וְכָבַשׁ יִצְרוֹ. אָמְרוּ חֲכָמִים מָקוֹם שֶׁבַּעֲלֵי תְּשׁוּבָה עוֹמְדִין אֵין צַדִּיקִים גְּמוּרִין יְכוֹלִין לַעֲמֹד בּוֹ. כְּלוֹמַר מַעֲלָתָן גְּדוֹלָה מִמַּעֲלַת אֵלּוּ שֶׁלֹּא חָטְאוּ מֵעוֹלָם מִפְּנֵי שֶׁהֵן כּוֹבְשִׁים יִצְרָם יוֹתֵר מֵהֶם:","כָּל הַנְּבִיאִים כֻּלָּן צִוּוּ עַל הַתְּשׁוּבָה וְאֵין יִשְׂרָאֵל נִגְאָלִין אֶלָּא בִּתְשׁוּבָה. וּכְבָר הִבְטִיחָה תּוֹרָה שֶׁסּוֹף יִשְׂרָאֵל לַעֲשׂוֹת תְּשׁוּבָה בְּסוֹף גָּלוּתָן וּמִיָּד הֵן נִגְאָלִין שֶׁנֶּאֱמַר (דברים ל א) \"וְהָיָה כִי יָבֹאוּ עָלֶיךָ כָּל הַדְּבָרִים\" וְגוֹ' (דברים ל ב) \"וְשַׁבְתָּ עַד ה' אֱלֹהֶיךָ\" (דברים ל ג) \"וְשָׁב ה' אֱלֹהֶיךָ\" וְגוֹ':","גְּדוֹלָה תְּשׁוּבָה שֶׁמְּקָרֶבֶת אֶת הָאָדָם לַשְּׁכִינָה שֶׁנֶּאֱמַר (הושע יד ב) \"שׁוּבָה יִשְׂרָאֵל עַד ה' אֱלֹהֶיךָ\". וְנֶאֱמַר (עמוס ד ו) \"וְלֹא שַׁבְתֶּם עָדַי נְאֻם ה'\". וְנֶאֱמַר (ירמיה ד א) \"אִם תָּשׁוּב יִשְׂרָאֵל נְאֻם ה' אֵלַי תָּשׁוּב\". כְּלוֹמַר אִם תַּחֲזֹר בִּתְשׁוּבָה בִּי תִּדְבַּק. הַתְּשׁוּבָה מְקָרֶבֶת אֶת הָרְחוֹקִים. אֶמֶשׁ הָיָה זֶה שָׂנאוּי לִפְנֵי הַמָּקוֹם מְשֻׁקָּץ וּמְרֻחָק וְתוֹעֵבָה. וְהַיּוֹם הוּא אָהוּב וְנֶחְמָד קָרוֹב וְיָדִיד. וְכֵן אַתָּה מוֹצֵא שֶׁבְּלָשׁוֹן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַרְחִיק הַחוֹטְאִים בָּהּ מְקָרֵב אֶת הַשָּׁבִים בֵּין יָחִיד בֵּין רַבִּים. שֶׁנֶּאֱמַר (הושע ב א) \"וְהָיָה בִּמְקוֹם אֲשֶׁר יֵאָמֵר לָהֶם לֹא עַמִּי אַתֶּם יֵאָמֵר לָהֶם בְּנֵי אֵל חָי\". וְנֶאֱמַר בִּיכָנְיָהוּ בְּרִשְׁעָתוֹ (כְּתֹב) [כִּתְבוּ] (ירמיה כב ל) \"אֶת הָאִישׁ הַזֶּה עֲרִירִי גֶּבֶר לֹא יִצְלַח בְּיָמָיו\", (ירמיה כב כד) \"אִם יִהְיֶה כָּנְיָהוּ בֶּן יְהוֹיָקִים מֶלֶךְ יְהוּדָה חוֹתָם עַל יַד יְמִינִי\" וְגוֹ'. וְכֵיוָן שֶׁשָּׁב בְּגָלוּתוֹ נֶאֱמַר בִּזְרֻבָּבֶל בְּנוֹ (חגי ב כג) \"בַּיּוֹם הַהוּא נְאֻם ה' צְבָאוֹת אֶקָּחֲךָ זְרֻבָּבֶל בֶּן שְׁאַלְתִּיאֵל עַבְדִּי נְאֻם ה' וְשַׂמְתִּיךָ כַּחוֹתָם\":","כַּמָּה מְעֻלָּה מַעֲלַת הַתְּשׁוּבָה. אֶמֶשׁ הָיָה זֶה מֻבְדָּל מֵה' אֱלֹהֵי יִשְׂרָאֵל שֶׁנֶּאֱמַר (ישעיה נט ב) \"עֲוֹנוֹתֵיכֶם הָיוּ מַבְדִּלִים בֵּינֵכֶם לְבֵין אֱלֹהֵיכֶם\". צוֹעֵק וְאֵינוֹ נַעֲנֶה שֶׁנֶּאֱמַר (ישעיה א טו) \"כִּי תַרְבּוּ תְפִלָּה\" וְגוֹ'. וְעוֹשֶׂה מִצְוֹת וְטוֹרְפִין אוֹתָן בְּפָנָיו שֶׁנֶּאֱמַר (ישעיה א יב) \"מִי בִקֵּשׁ זֹאת מִיֶּדְכֶם רְמֹס חֲצֵרָי\", (מלאכי א י) \"מִי גַם בָּכֶם וְיִסְגֹּר דְּלָתַיִם\" וְגוֹ'. וְהַיּוֹם הוּא מֻדְבָּק בַּשְּׁכִינָה שֶׁנֶּאֱמַר (דברים ד ד) \"וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם\". צוֹעֵק וְנַעֲנֶה מִיָּד שֶׁנֶּאֱמַר (ישעיה סה כד) \"וְהָיָה טֶרֶם יִקְרָאוּ וַאֲנִי אֶעֱנֶה\". וְעוֹשֶׂה מִצְוֹת וּמְקַבְּלִין אוֹתָן בְּנַחַת וְשִׂמְחָה שֶׁנֶּאֱמַר (קהלת ט ז) \"כִּי כְבָר רָצָה הָאֱלֹהִים אֶת מַעֲשֶׂיךָ\". וְלֹא עוֹד אֶלָּא שֶׁמִּתְאַוִּים לָהֶם שֶׁנֶּאֱמַר (מלאכי ג ד) \"וְעָרְבָה לַה' מִנְחַת יְהוּדָה וִירוּשָׁלםִ כִּימֵי עוֹלָם וּכְשָׁנִים קַדְמֹנִיּוֹת\":","בַּעֲלֵי תְּשׁוּבָה דַּרְכָּן לִהְיוֹת שְׁפָלִים וַעֲנָוִים בְּיוֹתֵר. אִם חֵרְפוּ אוֹתָן הַכְּסִילִים בְּמַעֲשֵׂיהֶם הָרִאשׁוֹנִים וְאָמְרוּ לָהֶן אֶמֶשׁ הָיִיתָ עוֹשֶׂה כָּךְ וְכָךְ וְאֶמֶשׁ הָיִיתָ אוֹמֵר כָּךְ וְכָךְ. אַל יַרְגִּישׁוּ לָהֶן אֶלָּא שׁוֹמְעִין וּשְׂמֵחִים וְיוֹדְעִין שֶׁזּוֹ זְכוּת לָהֶם. שֶׁכָּל זְמַן שֶׁהֵם בּוֹשִׁים מִמַּעֲשֵׂיהֶם שֶׁעָבְרוּ וְנִכְלָמִים מֵהֶן זְכוּתָם מְרֻבָּה וּמַעֲלָתָם מִתְגַּדֶּלֶת. וְחֵטְא גָּמוּר הוּא לוֹמַר לְבַעַל תְּשׁוּבָה זְכֹר מַעֲשֶׂיךָ הָרִאשׁוֹנִים אוֹ לְהַזְכִּירָן לְפָנָיו כְּדֵי לְבַיְּשׁוֹ. אוֹ לְהַזְכִּיר דְּבָרִים וְעִנְיָנִים הַדּוֹמִין לָהֶם כְּדֵי לְהַזְכִּירוֹ מֶה עָשָׂה. הַכּל אָסוּר וּמֻזְהָר עָלָיו בִּכְלַל הוֹנָיַת דְּבָרִים שֶׁהִזְהִירָה תּוֹרָה עָלֶיהָ שֶׁנֶּאֱמַר (ויקרא כה יז) \"וְלֹא תוֹנוּ אִישׁ אֶת עֲמִיתוֹ\":"],"Mishneh Torah, Rest on the Tenth of Tishrei 2":["הָאוֹכֵל בְּיוֹם הַכִּפּוּרִים מַאֲכָלִין הָרְאוּיִין לֶאֱכל לָאָדָם כְּכוֹתֶבֶת הַגַּסָּה שֶׁהִיא פָּחוֹת מִכְּבֵיצָה כִּמְעַט הֲרֵי זֶה חַיָּב. וְכָל הָאֳכָלִים מִצְטָרְפִין לְשִׁעוּר זֶה. וְכֵן הַשּׁוֹתֶה מַשְׁקִין הָרְאוּיִין לִשְׁתִיַּת אָדָם כִּמְלוֹא לֻגְמָיו שֶׁל שׁוֹתֶה כָּל אֶחָד וְאֶחָד לְפִי לֻגְמָיו חַיָּב. וְכַמָּה מְלוֹא לֻגְמָיו כְּדֵי שֶׁיְּסַלְּקֵם לְצַד אֶחָד וְיֵרָאֶה מָלֵא לֻגְמָיו. וְשִׁעוּר זֶה בְּאָדָם בֵּינוֹנִי פָּחוֹת מֵרְבִיעִית. וְכָל הַמַּשְׁקִין מִצְטָרְפִין לְשִׁעוּר זֶה. וְהָאֲכִילָה וּשְׁתִיָּה אֵין מִצְטָרְפִין לְשִׁעוּר אֶחָד:","אֶחָד הָאוֹכֵל אֳכָלִים הַמֻּתָּרִים אוֹ שֶׁאָכַל דְּבָרִים הָאֲסוּרִין כְּגוֹן פִּגּוּל וְנוֹתַר וְטֶבֶל וּנְבֵלוֹת וּטְרֵפוֹת וְחֵלֶב אוֹ דָּם הוֹאִיל וְאָכַל אֳכָלִים הָרְאוּיִין לָאָדָם הֲרֵי זֶה חַיָּב כָּרֵת מִשּׁוּם אוֹכֵל בְּיוֹם הַכִּפּוּרִים:","אָכַל אוֹ שָׁתָה פָּחוֹת מִשִּׁעוּר זֶה אֵינוֹ חַיָּב כָּרֵת. אַף עַל פִּי שֶׁהוּא אָסוּר מִן הַתּוֹרָה בַּחֲצִי שִׁעוּר אֵין חַיָּבִין כָּרֵת אֶלָּא עַל כַּשִּׁעוּר. וְהָאוֹכֵל אוֹ הַשּׁוֹתֶה חֲצִי שִׁעוּר מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","אָכַל מְעַט וְחָזַר וְאָכַל אִם יֵשׁ מִתְּחִלַּת אֲכִילָה רִאשׁוֹנָה עַד סוֹף אֲכִילָה אַחֲרוֹנָה כְּדֵי אֲכִילַת שָׁלֹשׁ בֵּיצִים הֲרֵי אֵלּוּ מִצְטָרְפוֹת לְכַשִּׁעוּר וְאִם לָאו אֵין מִצְטָרְפוֹת לְכַשִּׁעוּר. שָׁתָה מְעַט וְחָזַר וְשָׁתָה אִם יֵשׁ מִתְּחִלַּת שְׁתִיָּה רִאשׁוֹנָה עַד סוֹף שְׁתִיָּה אַחֲרוֹנָה כְּדֵי שְׁתִיַּת רְבִיעִית מִצְטָרְפִין לְשִׁעוּר וְאִם לָאו אֵין מִצְטָרְפִין:","אָכַל אֳכָלִים שֶׁאֵינָן רְאוּיִין לְמַאֲכַל אָדָם כְּגוֹן עֲשָׂבִים הַמָּרִים אוֹ שְׂרָפִים הַבְּאוּשִׁין אוֹ שֶׁשָּׁתָה מַשְׁקִין שֶׁאֵינָן רְאוּיִין לִשְׁתִיָּה כְּגוֹן צִיר אוֹ מוּרְיָס וְחֹמֶץ חַי אֲפִלּוּ אָכַל וְשָׁתָה מֵהֶן הַרְבֵּה הֲרֵי זֶה פָּטוּר מִן הַכָּרֵת. אֲבָל מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","שָׁתָה חֹמֶץ מָזוּג בְּמַיִם חַיָּב. הַכּוֹסֵס פִּלְפְּלִין וְזַנְגְּבִיל יָבֵשׁ וְכַיּוֹצֵא בָּהֶן פָּטוּר. אֲבָל זַנְגְּבִיל רָטֹב חַיָּב. אָכַל עֲלֵי גְּפָנִים פָּטוּר. לוּלְבֵי גְּפָנִים חַיָּב. וְאֵלּוּ הֵן לוּלְבֵי גְּפָנִים כָּל שֶׁלִּבְלְבוּ בְּאֶרֶץ יִשְׂרָאֵל מֵרֹאשׁ הַשָּׁנָה וְעַד יוֹם הַכִּפּוּרִים. יֶתֶר עַל זֶה הֲרֵי הֵן כְּעֵצִים וּפָטוּר. וְכֵן כָּל כַּיּוֹצֵא בָּאֵלּוּ:","אָכַל צָלִי בְּמֶלַח מִצְטָרֵף הַמֶּלַח לַבָּשָׂר. צִיר שֶׁעַל גַּבֵּי יָרָק מִצְטָרֵף. מִפְּנֵי שֶׁמַּכְשִׁירֵי הָאֹכֶל הַמְעֹרָבִים עִם הָאֹכֶל כְּאֹכֶל הֵן חֲשׁוּבִים. הָיָה שָׂבֵעַ מֵאֲכִילָה גַּסָּה שֶׁאָכַל עַד שֶׁקָּץ בִּמְזוֹנוֹ וְאָכַל יֶתֶר עַל שָׂבְעוֹ פָּטוּר כְּמִי שֶׁאָכַל אֳכָלִין שֶׁאֵינָם רְאוּיִין לַאֲכִילָה. שֶׁאַף עַל פִּי שֶׁזֶּה הַמַּאֲכָל הַיָּתֵר רָאוּי לְרָעֵב אֵינוֹ רָאוּי לְכָל מִי שֶׁשָּׂבֵעַ כְּזֶה:","חוֹלֶה שֶׁיֵּשׁ בּוֹ סַכָּנָה שֶׁשָּׁאַל לֶאֱכל בְּיוֹם הַכִּפּוּרִים אַף עַל פִּי שֶׁהָרוֹפְאִים הַבְּקִיאִין אוֹמְרִין אֵינוֹ צָרִיךְ מַאֲכִילִין אוֹתוֹ עַל פִּי עַצְמוֹ עַד שֶׁיֹּאמַר דַּיִּי. אָמַר הַחוֹלֶה אֵינִי צָרִיךְ וְהָרוֹפֵא אוֹמֵר צָרִיךְ מַאֲכִילִין אוֹתוֹ עַל פִּיו. וְהוּא שֶׁיִּהְיֶה רוֹפֵא בָּקִי. רוֹפֵא אֶחָד אוֹמֵר צָרִיךְ וְאֶחָד אוֹמֵר אֵינוֹ צָרִיךְ מַאֲכִילִין אוֹתוֹ. מִקְצָת הָרוֹפְאִין אוֹמְרִין צָרִיךְ וּמִקְצָתָן אוֹמְרִין אֵינוֹ צָרִיךְ הוֹלְכִין אַחַר הָרֹב אוֹ אַחַר הַבְּקִיאִין. וּבִלְבַד שֶׁלֹּא יֹאמַר הַחוֹלֶה צָרִיךְ אֲנִי. אֲבָל אִם אָמַר צָרִיךְ אֲנִי מַאֲכִילִין אוֹתוֹ. לֹא אָמַר הַחוֹלֶה שֶׁהוּא צָרִיךְ וְנֶחְלְקוּ הָרוֹפְאִים וְהָיוּ כֻּלָּם בְּקִיאִין וְאֵלּוּ שֶׁאָמְרוּ אֵינוֹ צָרִיךְ כְּמִנְיָן שֶׁאָמְרוּ צָרִיךְ מַאֲכִילִין אוֹתוֹ:","עֻבָּרָה שֶׁהֵרִיחָה לוֹחֲשִׁין לָהּ בְּאָזְנָהּ שֶׁיּוֹם הַכִּפּוּרִים הוּא. אִם נִתְקָרְרָה דַּעְתָּהּ בְּזִכָּרוֹן זֶה מוּטָב וְאִם לָאו מַאֲכִילִין אוֹתָהּ עַד שֶׁתִּתְיַשֵּׁב נַפְשָׁהּ. וְכֵן מִי שֶׁאָחֲזוֹ בֻּלְמוֹס מַאֲכִילִין אוֹתוֹ עַד שֶׁיֵּאוֹרוּ עֵינָיו. וַאֲפִלּוּ נְבֵלוֹת וּשְׁקָצִים מַאֲכִילִין אוֹתוֹ מִיָּד וְאֵין מַשְׁהִין אוֹתוֹ עַד שֶׁיִּמְצְאוּ דְּבָרִים הַמֻּתָּרִין:","קָטָן בֶּן תֵּשַׁע שָׁנִים וּבֶן עֶשֶׂר שָׁנִים מְחַנְּכִין אוֹתוֹ לְשָׁעוֹת. כֵּיצַד. הָיָה רָגִיל לֶאֱכל בִּשְׁתֵּי שָׁעוֹת בַּיּוֹם מַאֲכִילִין אוֹתוֹ בְּשָׁלֹשׁ. הָיָה רָגִיל בְּשָׁלֹשׁ מַאֲכִילִין אוֹתוֹ בְּאַרְבַּע. לְפִי כֹּחַ הַבֵּן מוֹסִיפִין לְעַנּוֹת אוֹתוֹ בְּשָׁעוֹת. בֶּן אַחַת עֶשְׂרֵה שָׁנָה בֵּין זָכָר בֵּין נְקֵבָה מִתְעַנֶּה וּמַשְׁלִים מִדִּבְרֵי סוֹפְרִים כְּדֵי לְחַנְּכוֹ בְּמִצְוֹת:","בַּת שְׁתֵּים עֶשְׂרֵה שָׁנָה וְיוֹם אֶחָד וּבֶן שְׁלֹשׁ עֶשְׂרֵה שָׁנָה וְיוֹם אֶחָד שֶׁהֵבִיאוּ שְׁתֵּי שְׂעָרוֹת הֲרֵי הֵן כִּגְדוֹלִים לְכָל הַמִּצְוֹת וּמַשְׁלִימִין מִן הַתּוֹרָה. אֲבָל אִם לֹא הֵבִיאוּ שְׁתֵּי שְׂעָרוֹת עֲדַיִן קְטַנִּים הֵן וְאֵינָם מַשְׁלִימִין אֶלָּא מִדִּבְרֵי סוֹפְרִים. קָטָן שֶׁהוּא פָּחוֹת מִבֶּן תֵּשַׁע אֵין מְעַנִּין אוֹתוֹ בְּיוֹם הַכִּפּוּרִים כְּדֵי שֶׁלֹּא יָבֹא לִידֵי סַכָּנָה:"],"Mishneh Torah, Ritual Slaughter 6":["נְּקוּבָה כֵּיצַד. אַחַד עָשָׂר אֵיבָרִים הֵן שֶׁאִם נִקַּב אֶחָד מֵהֶן לַחֲלָלוֹ בְּמַשֶּׁהוּ טְרֵפָה. וְאֵלּוּ הֵן. תַּרְבַּץ הַוֵּשֶׁט. וּקְרוּם שֶׁל מֹחַ הָרֹאשׁ. וְהַלֵּב עִם הַקָּנֶה שֶׁלּוֹ. וְהַמָּרָה. וּקְנֵה הַכָּבֵד. וְהַקֵּבָה. וְהַכֶּרֶס. וְהֶמְסֵס. וּבֵית הַכּוֹסוֹת. וְהַדַּקִּין. וְהָרֵאָה עִם הַקָּנֶה שֶׁלָּהּ:","תַּרְבַּץ הַוֵּשֶׁט כְּבָר בֵּאַרְנוּ שִׁעוּרוֹ וְשֶׁהוּא הַמָּקוֹם מִן הַוֵּשֶׁט שֶׁאֵינוֹ רָאוּי לִשְׁחִיטָה לְמַעְלָה מִן הַוֵּשֶׁט. אִם נִקַּב לַחֲלָלוֹ בְּמַה שֶּׁהוּא טְרֵפָה:","שְׁנֵי קְרוּמוֹת יֵשׁ לַמֹּחַ שֶׁבָּרֹאשׁ. אִם נִקַּב הָעֶלְיוֹן הַסָּמוּךְ לָעֶצֶם בִּלְבַד הֲרֵי זוֹ מֻתֶּרֶת. וְאִם נִקַּב הַתַּחְתּוֹן הַסָּמוּךְ לַמֹּחַ טְרֵפָה. וּמִשֶּׁיַּתְחִיל הַמֹּחַ לְהִמָּשֵׁךְ לַשִּׁדְרָה וְהוּא מִחוּץ לַפּוֹלִין שֶׁהֵן תְּחִלַּת הָעֹרֶף יִהְיֶה לִקְרוּמוֹ דִּין אַחֵר. וְאִם נִקַּב חוּץ לַפּוֹלִין מֻתָּר:","הַמֹּחַ עַצְמוֹ שֶׁנִּקַּב אוֹ נִתְמַעֵךְ וְהַקְּרוּם קַיָּם כְּשֵׁרָה. וְאִם נִשְׁפַּךְ כַּמַּיִם אוֹ נָמֵס כַּדּוֹנַג טְרֵפָה:","הַלֵּב שֶׁנִּקַּב לְבֵית חֲלָלוֹ. בֵּין לְחָלָל גָּדוֹל שֶׁבִּשְׂמֹאל בֵּין לְחָלָל קָטָן שֶׁבְּיָמִין טְרֵפָה. אֲבָל אִם נִקַּב בְּשַׂר הַלֵּב וְלֹא הִגִּיעַ לַחֲלָלוֹ מֻתָּר. וּקְנֵה הַלֵּב וְהוּא הַמִּזְרָק הַגָּדוֹל שֶׁיּוֹצֵא מִמֶּנּוּ לָרֵאָה הֲרֵי הוּא כַּלֵּב וְאִם נִקַּב לַחֲלָלוֹ בְּמַשֶּׁהוּ טְרֵפָה:","מָרָה שֶׁנִּקְּבָה וְכָבֵד סוֹתְמָהּ מֻתֶּרֶת. וְאִם לֹא נִסְתַּם הַנֶּקֶב אַף עַל פִּי שֶׁהוּא סָמוּךְ לַכָּבֵד טְרֵפָה:","נְזִיָּה שֶׁנִּמְצֵאת בַּמָּרָה אִם הָיְתָה כְּמוֹ גַּרְעִינָהּ שֶׁל תְּמָרָה שֶׁאֵין רֹאשָׁהּ חַד מֻתֶּרֶת. וְאִם רֹאשָׁהּ חַד כְּגַרְעִינַת הַזַּיִת אֲסוּרָה. שֶׁהֲרֵי נִקְּבָה אוֹתָהּ כְּשֶׁנִּכְנְסָה. וְזֶה שֶׁלֹּא יֵרָאֶה הַנֶּקֶב מִפְּנֵי שֶׁהֻגְלַד פִּי הַמַּכָּה:","קְנֵי הַכָּבֵד וְהֵן הַמִּזְרְקִין שֶׁבּוֹ שֶׁבָּהֶן הַדָּם מִתְבַּשֵּׁל. אִם נִקַּב אֶחָד מֵהֶן בְּמַשֶּׁהוּ טְרֵפָה. לְפִיכָךְ מַחַט שֶׁנִּמְצֵאת בְּחִתּוּךְ הַכָּבֵד אִם הָיְתָה מַחַט גְּדוֹלָה וְהָיָה הַקָּצֶה הַחַד שֶׁלָּהּ לְפָנִים בְּיָדוּעַ שֶׁנִּקְּבָה כְּשֶׁנִּכְנְסָה. וְאִם הָיָה הָרֹאשׁ הֶעָגֹל לְפָנִים אוֹמְרִין דֶּרֶךְ סִמְפּוֹנוֹת הָלְכָה וּמֻתֶּרֶת:","הָיְתָה מַחַט קְטַנָּה הֲרֵי זוֹ טְרֵפָה מִפְּנֵי שֶׁשְּׁנֵי רָאשֶׁיהָ חַדִּין וַדַּאי נִקְּבָה. וְאִם נִמְצֵאת בַּסִּמְפּוֹן הַגָּדוֹל שֶׁבַּכָּבֵד וְהוּא הַקָּנֶה הָרָחָב שֶׁבָּאֶמְצַע שֶׁבּוֹ נִכְנַס הַמַּאֲכָל לַכָּבֵד הֲרֵי זוֹ מֻתֶּרֶת. וּבְשַׂר כָּבֵד שֶׁהִתְלִיעַ מֻתֶּרֶת:","קֵבָה שֶׁנִּקְּבָה וְחֵלֶב טָהוֹר סוֹתֵם אֶת הַנֶּקֶב מֻתֶּרֶת. וְכֵן כָּל נֶקֶב שֶׁהַבָּשָׂר אוֹ הַחֵלֶב הַמֻּתָּר בַּאֲכִילָה סוֹתֵם אוֹתוֹ הֲרֵי זֶה מֻתָּר. חוּץ מֵחֵלֶב הַלֵּב וְהַקְּרוּם שֶׁעַל הַלֵּב כֻּלּוֹ. וְהַמְּחִצָּה שֶׁבְּאֶמְצַע הַבֶּטֶן הַמַּבְדֶּלֶת בֵּין אֵיבְרֵי הַמַּאֲכָל וְאֵיבְרֵי הַנְּשִׁימָה. וְהִיא שֶׁקּוֹרְעִין אוֹתָהּ וְאַחַר כָּךְ תֵּרָאֶה הָרֵאָה. וְהִיא הַנִּקְרֵאת טַרְפַּשׁ הַכָּבֵד. וְהַמָּקוֹם הַלָּבָן שֶׁבְּאֶמְצָעָהּ. וְחֵלֶב הַמְּעִי הָאַחֲרוֹן שֶׁבְּאֵיבָרִים אֵלּוּ. אֵין מְגִנִּין לְפִי שֶׁהֵן קָשִׁין. וְנֶקֶב שֶׁנִּסְתַּם בְּאֶחָד מֵהֶן אֵינוֹ כְּסָתוּם. וְחֵלֶב חַיָּה שֶׁכְּנֶגְדּוֹ בִּבְהֵמָה אָסוּר אֵינוֹ סוֹתֵם אַף עַל פִּי שֶׁהוּא מֻתָּר בַּאֲכִילָה:","כֶּרֶס שֶׁנִּקַּב טְרֵפָה. וְאֵין לוֹ דָּבָר שֶׁיִּסְתֹּם אוֹתוֹ. שֶׁהֲרֵי הַחֵלֶב שֶׁעָלָיו אָסוּר. וְכֵן הֶמְסֵס וּבֵית הַכּוֹסוֹת שֶׁנִּקַּב אֶחָד מֵהֶן לַחוּץ טְרֵפָה. וְאִם נִקַּב אֶחָד מֵהֶן לְתוֹךְ חֲלַל חֲבֵרוֹ מֻתֶּרֶת:","מַחַט שֶׁנִּמְצֵאת בָּעֳבִי בֵּית הַכּוֹסוֹת מִצַּד אֶחָד כְּשֵׁרָה. וְאִם נִקְּבָה נֶקֶב מְפֻלָּשׁ לְתוֹךְ חֲלַל בֵּית הַכּוֹסוֹת וְנִמְצֵאת טִפַּת דָּם בִּמְקוֹם הַנֶּקֶב טְרֵפָה שֶׁוַּדַּאי קֹדֶם שְׁחִיטָה נִקַּב. אֲבָל אִם אֵין דָּם בִּמְקוֹם הַנֶּקֶב הֲרֵי זֶה מֻתָּר שֶׁוַּדַּאי אַחַר שְׁחִיטָה דָּחֲקָה הַמַּחַט וְנִקְּבָה:","בְּהֵמָה שֶׁהִלְעִיטָהּ דָּבָר שֶׁנּוֹקֵב בְּנֵי מֵעֶיהָ כְּגוֹן קֹרֶט שֶׁל חִלְתִּית וְכַיּוֹצֵא בּוֹ טְרֵפָה שֶׁוַּדַּאי נוֹקֵב. וְאִם הָיָה סָפֵק נוֹקֵב סָפֵק אֵינוֹ נוֹקֵב תִּבָּדֵק. כָּל אֶחָד מִן בְּנֵי הַמֵּעַיִם שֶׁפְּסלֶת הַמַּאֲכָל סוֹבֶבֶת בָּהֶן וְהֵן הַנִּקְרָאִים דַּקִּין שֶׁנִּקַּב טְרֵפָה. וְיֵשׁ מֵהֶן מְלֻפָּפִין וּמֻקָּפִין זוֹ לְפָנִים מִזּוֹ בְּעִגּוּל כְּמוֹ נָחָשׁ שֶׁנִּכְרָךְ וְאֵלּוּ הֵן הַנִּקְרָאִים הַדְרָא דְּכַנְתָּה. אִם נִקֵּב אֶחָד מֵהֶן לַחֲבֵרוֹ כְּשֵׁרָה. שֶׁהֲרֵי חֲבֵרוֹ מֵגֵן עָלָיו:","וּמֵעַיִם שֶׁנִּקְּבוּ וְלֵחָה סוֹתַמְתָּן טְרֵפָה שֶׁאֵין זוֹ סְתִימָה עוֹמֶדֶת. בְּנֵי מֵעַיִם שֶׁבָּא זְאֵב אוֹ כֶּלֶב וְכַיּוֹצֵא בָּהֶן וּנְטָלָן וַהֲרֵי הֵן נְקוּבִין אַחַר שֶׁהִנִּיחָן תּוֹלִין בּוֹ וּמֻתֶּרֶת וְאֵין אוֹמְרִין שֶׁמָּא בִּמְקוֹם נֶקֶב נִקַּב. נִמְצְאוּ נְקוּבִין וְלֹא נוֹדַע אִם קֹדֶם שְׁחִיטָה נִקְּבוּ אִם אַחַר שְׁחִיטָה נוֹקְבִין בָּהֶן נֶקֶב אַחֵר וּמְדַמִּין לוֹ. אִם הָיָה הַנֶּקֶב הָרִאשׁוֹן כְּמוֹתוֹ כְּשֵׁרָה. וְאִם הָיָה בֵּינֵיהֶן שִׁנּוּי קֹדֶם שְׁחִיטָה נִקַּב וּטְרֵפָה. וְאִם מִשְׁמְשׁוּ הַיָּדַיִם בְּנֶקֶב הַסָּפֵק כָּךְ צָרִיךְ לְמַשְׁמֵשׁ בַּנֶּקֶב שֶׁמְּדַמִּין לוֹ וְאַחַר כָּךְ עוֹרְכִין זֶה לָזֶה:","בְּנֵי מֵעַיִם שֶׁיָּצְאוּ לַחוּץ וְלֹא נִקְּבוּ מֻתֶּרֶת. וְאִם נִתְהַפְּכוּ אַף עַל פִּי שֶׁלֹּא נִקְּבוּ טְרֵפָה. שֶׁאִי אֶפְשָׁר שֶׁיַּחְזְרוּ כְּמוֹת שֶׁהָיוּ אַחַר שֶׁנֶּהֶפְכוּ וְאֵינָהּ חַיָּה:","הַמְּעִי הָאַחֲרוֹן שֶׁהוּא שָׁוֶה וְאֵין בּוֹ עִקּוּם וְהוּא שֶׁהָרְעִי יוֹצֵא בּוֹ מִן הָעֶרְוָה וְהוּא דָּבוּק בֵּין עִקְּרֵי הַיְרֵכַיִם הוּא הַנִּקְרָא חַלְחלֶת. אִם נִקַּב בְּמַשֶּׁהוּ טְרֵפָה כִּשְׁאָר הַמֵּעַיִם. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁנִּקַּב לַחֲלַל הַבֶּטֶן. אֲבָל אִם נִקַּב בַּמָּקוֹם הַדָּבוּק בַּיְרֵכַיִם מֻתֶּרֶת. וַאֲפִלּוּ נָטַל מִמֶּנּוּ מְקוֹם הַדֶּבֶק כֻּלּוֹ מֻתֶּרֶת. וְהוּא שֶׁיִּשְׁתַּיֵּר מֵאָרְכּוֹ בַּשּׁוֹר כְּמוֹ אַרְבַּע אֶצְבָּעוֹת:","הָעוֹף אֵין לוֹ כֶּרֶס וְלֹא הֶמְסֵס וְלֹא בֵּית הַכּוֹסוֹת. אֲבָל יֵשׁ לוֹ כְּנֶגְדָּן זֶפֶק וְקֻרְקְבָן. וְכָל הַטְּרֵפוֹת שָׁווֹת הֵן בִּבְהֵמָה חַיָּה וָעוֹף. וְזֶפֶק שֶׁנִּקַּב גַּגּוֹ בְּמַשֶּׁהוּ טְרֵפָה. וְאֵי זֶהוּ גַּגּוֹ שֶׁל זֶפֶק זֶה שֶׁיִּמָּתַח עִם הַוֵּשֶׁט כְּשֶׁיַּאֲרִיךְ הָעוֹף צַוָּארוֹ. אֲבָל שְׁאָר הַזֶּפֶק שֶׁנִּקַּב מֻתָּר:","שְׁנֵי כִּיסִין יֵשׁ בַּקֻּרְקְבָן. הַחִיצוֹן אָדֹם כְּמוֹ בָּשָׂר. וְהַפְּנִימִי לָבָן כְּמוֹ עוֹר. נִקַּב זֶה בְּלֹא זֶה מֻתֶּרֶת עַד שֶׁיִּנָּקְבוּ שְׁנֵיהֶן בְּמַשֶּׁהוּ. וְאִם נִקְּבוּ שְׁנֵיהֶן זֶה שֶׁלֹּא כְּנֶגֶד זֶה מֻתָּר:","הַטְּחוֹל אֵינוֹ מִן הָאֵיבָרִין שֶׁנְּקִיבָתָן בְּמַשֶּׁהוּ וּלְפִיכָךְ לֹא מָנוּ אוֹתוֹ חֲכָמִים בִּכְלָלָן אֶלָּא יֵשׁ לַנֶּקֶב שֶׁלּוֹ שִׁעוּר שֶׁאֵינוֹ שָׁוֶה בְּכֻלּוֹ. כֵּיצַד. הַטְּחוֹל רֹאשׁוֹ הָאֶחָד עָבֶה וְהַשֵּׁנִי דַּק כִּבְרִיַּת הַלָּשׁוֹן. אִם נִקַּב בָּרֹאשׁ הֶעָבֶה נֶקֶב מְפֻלָּשׁ טְרֵפָה. וְאִם נִקַּב נֶקֶב שֶׁאֵינוֹ מְפֻלָּשׁ אִם נִשְׁאָר תַּחְתָּיו כָּעֳבִי דִּינָר שֶׁל זָהָב מֻתָּר. פָּחוֹת מִכָּאן הֲרֵי הוּא כִּמְפֻלָּשׁ וּטְרֵפָה. אֲבָל אִם נִקַּב הַדַּק כְּשֵׁרָה:","כָּל אֵיבָר שֶׁאָמְרוּ חֲכָמִים בּוֹ שֶׁאִם נִקַּב בְּמַשֶּׁהוּ טְרֵפָה כָּךְ אִם נִטַּל כֻּלּוֹ טְרֵפָה. בֵּין שֶׁנִּטַּל בְּחלִי אוֹ בַּיָּד בֵּין שֶׁנִּבְרָא חָסֵר. וְכֵן אִם נִבְרָא בִּשְׁנֵי אֵיבָרִים מֵאוֹתוֹ אֵיבָר טְרֵפָה שֶׁכָּל הַיָּתֵר כְּנָטוּל הוּא חָשׁוּב. כֵּיצַד. נִטַּל אֶחָד מִן הַמֵּעַיִם אוֹ הַמָּרָה וְכַיּוֹצֵא בָּהֶן בֵּין בְּעוֹף בֵּין בִּבְהֵמָה טְרֵפָה. וְכֵן אִם נִמְצָא בָּהֶן שְׁתֵּי מְרָרוֹת אוֹ שְׁנֵי מֵעַיִם טְרֵפָה. וְכֵן כָּל כַּיּוֹצֵא בָּהֶן. אֲבָל אִם נִטַּל הַטְּחוֹל אוֹ שֶׁנִּמְצְאוּ שְׁנַיִם מֻתֶּרֶת שֶׁאֵינוֹ בִּכְלַל הַמְּנוּיִין:","הַמְּעִי הַיָּתֵר שֶׁתִּטָּרֵף בּוֹ הַבְּהֵמָה הוּא הַיָּתֵר מִתְּחִלָּתוֹ וְעַד סוֹפוֹ עַד שֶׁנִּמְצְאוּ שְׁנֵי מֵעַיִם זֶה בְּצַד זֶה מִתְּחִלָּה וְעַד סוֹף כִּמְעֵי הָעוֹף אוֹ שֶׁהָיָה הַמְּעִי יוֹצֵא כְּעָנָף מִן הַבַּד וַהֲרֵי הוּא מֻבְדָּל בֵּין בְּעוֹף בֵּין בִּבְהֵמָה. אֲבָל אִם חָזַר וְנִתְעָרֵב עִם הַמְּעִי וְנַעֲשָׂה אֶחָד מִשְּׁנֵי רָאשָׁיו וַהֲרֵי שְׁנֵיהֶם מֻבְדָּלִין בָּאֶמְצַע הֲרֵי זוֹ מֻתֶּרֶת וְאֵין כָּאן יָתֵר:"],"Mishneh Torah, Robbery and Lost Property 17":["כָּל מְצִיאָה שֶׁאָמַרְנוּ בָּהּ שֶׁהִיא שֶׁל מוֹצְאָהּ אֵינוֹ זוֹכֶה בָּהּ עַד שֶׁתַּגִּיעַ לְיָדוֹ אוֹ לִרְשׁוּתוֹ. אֲבָל אִם רָאָה אֶת הַמְּצִיאָה אֲפִלּוּ נָפַל עָלֶיהָ וּבָא אַחֵר וְהֶחֱזִיק בָּהּ הֲרֵי זֶה שֶׁהֶחְזִיק בָּהּ זָכָה בָּהּ:","הָיָה רוֹכֵב עַל גַּבֵּי בְּהֵמָה וְרָאָה אֶת הַמְּצִיאָה וְאָמַר לַחֲבֵרוֹ זְכֵה לִי בָּהּ כֵּיוָן שֶׁהִגְבִּיהָהּ לוֹ קָנָה הָרוֹכֵב וְאַף עַל פִּי שֶׁלֹּא הִגִּיעַ לְיָדוֹ. וְאִם אָמַר לוֹ תְּנָה לִי וּנְטָלָהּ וְאָמַר אֲנִי זָכִיתִי בָּהּ זָכָה בָּהּ הַנּוֹטֵל. וְאִם מִשֶּׁנְּתָנָהּ לָרוֹכֵב אָמַר אֲנִי זָכִיתִי בָּהּ תְּחִלָּה לֹא אָמַר כְּלוּם:","הַמַּגְבִּיהַּ מְצִיאָה לַחֲבֵרוֹ קָנָה חֲבֵרוֹ וְאַף עַל פִּי שֶׁלֹּא אָמַר לוֹ כְּלוּם [זָכָה בָּהּ]. הִגְבִּיהוּ הַמְּצִיאָה שְׁנַיִם קְנָאוּהָ שְׁנֵיהֶם:","הִגְבִּיהָהּ לוֹ חֵרֵשׁ אוֹ שׁוֹטֶה אוֹ קָטָן לֹא קָנָה הַפִּקֵּחַ לְפִי שֶׁאֵין לָהֶן דַּעַת. הִגְבִּיהָהּ חֵרֵשׁ וּפִקֵּחַ כְּאֶחָד מִתּוֹךְ שֶׁלֹּא קָנָה פִּקֵּחַ לֹא קָנָה חֵרֵשׁ. הָיוּ שְׁנֵיהֶם חֵרְשִׁים תִּקְּנוּ חֲכָמִים שֶׁיִּקְנוּ כְּדֵי שֶׁלֹּא יָבוֹאוּ לְהִנָּצוֹת:","שְׁנַיִם שֶׁרָאוּ גָּמָל אוֹ חֲמוֹר שֶׁל מְצִיאָה וְקָדְמוּ שְׁנֵיהֶם וְהִנְהִיגוּהוּ אוֹ מְשָׁכוּהוּ. אוֹ שֶׁהָיָה אֶחָד מַנְהִיג וְאֶחָד מוֹשֵׁךְ. קָנוּ שְׁנֵיהֶם. בַּמֶּה דְּבָרִים אֲמוּרִים בַּחֲמוֹר אֲבָל בְּגָמָל אִם הָיָה אֶחָד מַנְהִיג וְאֶחָד מוֹשֵׁךְ הַמּוֹשֵׁךְ קָנָה אֲבָל לֹא הַמַּנְהִיג:","בֶּהֱמַת מְצִיאָה שֶׁקָּדַם אֶחָד וְאָחַז בַּמּוֹסֵרָה לֹא קָנָה עַד שֶׁיִּמְשֹׁךְ אוֹ יַנְהִיג. וְכֵן בְּנִכְסֵי הַגֵּר. אֲבָל קָנָה הַמּוֹסֵרָה לְבַדָּהּ:","הָיָה אֶחָד רוֹכֵב וְאֶחָד אוֹחֵז בַּמּוֹסֵרָה הָרוֹכֵב קָנָה הַבְּהֵמָה וְהַמּוֹסֵרָה שֶׁעַל לְחָיֵי הַבְּהֵמָה בִּלְבַד. וְזֶה שֶׁאָחַז הַמּוֹסֵרָה קָנָה מִמֶּנָּה מַה שֶּׁאָחַז בְּיָדוֹ. וּשְׁאָר הַמּוֹסֵרָה לֹא קָנָהוּ אֶחָד מֵהֶן:","חֲצֵרוֹ שֶׁל אָדָם קוֹנָה לוֹ שֶׁלֹּא מִדַּעְתּוֹ. וְאִם נָפְלָה בָּהּ מְצִיאָה הֲרֵי הִיא שֶׁל בַּעַל הֶחָצֵר. בַּמֶּה דְּבָרִים אֲמוּרִים בְּחָצֵר הַמִּשְׁתַּמֶּרֶת. אֲבָל בְּשָׂדֶה וְגִנָּה וְכַיּוֹצֵא בָּהֶן אִם הָיָה עוֹמֵד בְּצַד שָׂדֵהוּ וְאָמַר זָכְתָה לִי שָׂדִי זָכָה בָּהּ. וְאִם אֵינוֹ עוֹמֵד שָׁם אוֹ שֶׁהָיָה עוֹמֵד וְלֹא אָמַר זָכְתָה לִי שָׂדִי כָּל הַקּוֹדֵם זָכָה. וְכֵן אַרְבַּע אַמּוֹת שֶׁל אָדָם שֶׁהוּא עוֹמֵד בְּצִדָּן הֲרֵי אֵלּוּ קוֹנִים לוֹ. וְאִם הִגִּיעָה הַמְּצִיאָה לְתוֹךְ אַרְבַּע אַמּוֹת שֶׁלּוֹ זָכָה בָּהּ:","חֲכָמִים תִּקְּנוּ דָּבָר זֶה כְּדֵי שֶׁלֹּא יָרִיבוּ הַמּוֹצְאִין זֶה עִם זֶה. בַּמֶּה דְּבָרִים אֲמוּרִים בְּסִמְטָא אוֹ בְּצִדֵּי רְשׁוּת הָרַבִּים שֶׁאֵין הָרַבִּים דּוֹחֲקִין בָּהֶן אוֹ בְּשָׂדֶה שֶׁאֵין לוֹ בְּעָלִים. אֲבָל הָעוֹמֵד בִּרְשׁוּת הָרַבִּים אוֹ בְּתוֹךְ שְׂדֵה חֲבֵרוֹ אֵין אַרְבַּע אַמּוֹת קוֹנוֹת לוֹ וְאֵינוֹ קוֹנֶה שָׁם עַד שֶׁתַּגִּיעַ מְצִיאָה לְיָדוֹ:","קְטַנָּה יֵשׁ לָהּ חָצֵר וְיֵשׁ לָהּ אַרְבַּע אַמּוֹת. וְקָטָן אֵין לוֹ חָצֵר וְאֵין לוֹ אַרְבַּע אַמּוֹת. מִפְּנֵי שֶׁחָצֵר שֶׁל קְטַנָּה מִיָּדָהּ לְמַדְנוּהָ. שֶׁכְּשֵׁם שֶׁהִיא מִתְגָּרֶשֶׁת בְּגֵט הַמַּגִּיעַ לְיָדָהּ כָּךְ מִתְגָּרֶשֶׁת בְּגֵט הַמַּגִּיעַ לַחֲצֵרָהּ. וּכְשֵׁם שֶׁיֵּשׁ לָהּ חָצֵר לְעִנְיַן הַגֵּט כָּךְ יֵשׁ לָהּ לְעִנְיַן מְצִיאָה. וְאַרְבַּע אַמּוֹת שֶׁל אָדָם כַּחֲצֵרוֹ לְעִנְיַן מְצִיאָה. אֲבָל הָאִישׁ לָמַדְנוּ שֶׁחֲצֵרוֹ קוֹנָה לוֹ מִשְּׁלוּחוֹ. כְּדֶרֶךְ שֶׁקּוֹנֶה לוֹ שְׁלוּחוֹ כָּךְ תִּקְנֶה לוֹ חֲצֵרוֹ. וְהַקָּטָן הוֹאִיל וְאֵינוֹ עוֹשֶׂה שָׁלִיחַ כָּךְ אֵין חֲצֵרוֹ וְלֹא אַרְבַּע אַמּוֹת שֶׁלּוֹ קוֹנִין לוֹ עַד שֶׁתַּגִּיעַ מְצִיאָה לְיָדוֹ:","מִי שֶׁרָאָה אֲחֵרִים רָצִים אַחַר הַמְּצִיאָה וַהֲרֵי הִיא צְבִי שָׁבוּר אוֹ גּוֹזָלוֹת שֶׁלֹּא פָּרְחוּ. אִם הָיָה עוֹמֵד בְּצַד שָׂדֵהוּ שֶׁהֵן בְּתוֹכָהּ וְאִלּוּ הָיָה רָץ הָיָה מַגִּיעָן וְאָמַר זָכְתָה לִי שָׂדִי זָכְתָה לוֹ שָׂדֵהוּ. וְאִם אֵינוֹ יָכוֹל לְהַגִּיעָן הֲרֵי אֵלּוּ כִּצְבִי שֶׁהוּא רָץ כְּדַרְכּוֹ וּכְגוֹזָלוֹת הַמַּפְרִיחִים וְלֹא אָמַר כְּלוּם אֶלָּא כָּל הַקּוֹדֵם בָּהֶן זָכָה. וְאִם נִתְּנוּ לוֹ בְּמַתָּנָה הוֹאִיל וְאַחֵר הִקְנָם לוֹ וַהֲרֵי הֵן מִתְגַּלְגְּלִין בְּתוֹךְ שָׂדֵהוּ קָנְתָה לוֹ שָׂדֵהוּ וְאִם הָיָה צְבִי רָץ כְּדַרְכּוֹ וְגוֹזָלוֹת מַפְרִיחִין לֹא קָנְתָה לוֹ שָׂדֵהוּ:","מְצִיאַת חֵרֵשׁ שׁוֹטֶה וְקָטָן יֵשׁ בָּהּ גֵּזֶל מִפְּנֵי דַּרְכֵי שָׁלוֹם. לְפִיכָךְ אִם עָבַר אַחֵר וּגְזָלָהּ מִיָּדָן אֵינָהּ יוֹצְאָה בְּדַיָּנִים. וְאִם כָּפַר בָּהּ וְנִשְׁבַּע אֵינוֹ חַיָּב בְּחֹמֶשׁ:","מְצִיאַת בְּנוֹ וּבִתּוֹ הַסְּמוּכִים עַל שֻׁלְחָנוֹ אַף עַל פִּי שֶׁהֵן גְּדוֹלִים וּמְצִיאַת בִּתּוֹ הַנַּעֲרָה אַף עַל פִּי שֶׁאֵינָהּ סוֹמֶכֶת עַל שֻׁלְחָנוֹ וַאֲפִלּוּ הָיְתָה מְכוּרָה אַמָּה וּמְצִיאַת עַבְדּוֹ וְשִׁפְחָתוֹ הַכְּנַעֲנִים וּמְצִיאַת אִשְׁתּוֹ הֲרֵי אֵלּוּ שֶׁלּוֹ. אֲבָל מְצִיאַת בְּנוֹ שֶׁאֵינוֹ סוֹמֵךְ עַל שֻׁלְחָנוֹ אַף עַל פִּי שֶׁהוּא קָטָן וּמְצִיאַת עַבְדּוֹ וְשִׁפְחָתוֹ הָעִבְרִים וּמְצִיאַת אִשְׁתּוֹ שֶׁהִיא מְגֹרֶשֶׁת וְאֵינָהּ מְגֹרֶשֶׁת כָּל אֵלּוּ הַמְּצִיאוֹת אֵינָן שֶׁלּוֹ:"],"Mishneh Torah, Sabbath 11":["הַשׁוֹחֵט חַיָּב. וְלֹא שׁוֹחִט בִּלְבַד אֶלָּא כָּל הַנּוֹטֵל נְשָׁמָה לְאֶחָד מִכָּל מִינֵי חַיָּה וּבְהֵמָה וְעוֹף וְדָג וְשֶׁרֶץ בֵּין בִּשְׁחִיטָה אוֹ בִּנְחִירָה אוֹ בְּהַכָּאָה חַיָּב. הַחוֹנֵק אֶת הַחַי עַד שֶׁיָּמוּת הֲרֵי זֶה תּוֹלֶדֶת שׁוֹחֵט. לְפִיכָךְ אִם הֶעֱלָה דָּג מִסֵּפֶל שֶׁל מַיִם וְהִנִּיחוֹ עַד שֶׁמֵּת חַיָּב מִשּׁוּם חוֹנֵק. וְלֹא עַד שֶׁיָּמוּת אֶלָּא כֵּיוָן שֶׁיָּבֵשׁ בּוֹ כְּסֶלַע בֵּין סְנַפִּירָיו חַיָּב שֶׁעוֹד אֵינוֹ יָכוֹל לִחְיוֹת. הוֹשִׁיט יָדוֹ לִמְעֵי הַבְּהֵמָה וְדִלְדֵּל עֵבָּר שֶׁבְּמֵעֶיהָ חַיָּב:","רְמָשִׂים שֶׁהֵן פָּרִין וְרָבִין מִזָּכָר וּנְקֵבָה אוֹ נֶהֱוִין מִן הֶעָפָר כְּמוֹ הַפַּרְעוֹשִׁין הַהוֹרֵג אוֹתָן חַיָּב כְּהוֹרֵג בְּהֵמָה וְחַיָּה. אֲבָל רְמָשִׂים שֶׁהֲוָיָתָן מִן הַגְּלָלִים וּמִן הַפֵּרוֹת שֶׁהִבְאִישׁוּ וְכַיּוֹצֵא בָּהֶן כְּגוֹן תּוֹלָעִים שֶׁל בָּשָׂר וְתוֹלָעִים שֶׁבְּתוֹךְ הַקִּטְנִיּוֹת הַהוֹרְגָן פָּטוּר:","הַמְפַלֶּה כֵּלָיו בְּשַׁבָּת מוֹלֵל אֶת הַכִּנִּים וְזוֹרְקָן. וּמֻתָּר לַהֲרֹג אֶת הַכִּנִּים בְּשַׁבָּת מִפְּנֵי שֶׁהֵן מִן הַזֵּעָה:","חַיָּה וְרֶמֶשׂ שֶׁהֵן נוֹשְׁכִין וּמְמִיתִין וַדַּאי כְּגוֹן זְבוּב שֶׁבְּמִצְרַיִם וְצִרְעָה שֶׁבְּנִינְוֵה וְעַקְרָב שֶׁבַּחֲדַיֵיב וְנָחָשׁ שֶׁבְּאֶרֶץ יִשְׂרָאֵל וְכֶלֶב שׁוֹטֶה בְּכָל מָקוֹם מֻתָּר לְהָרְגָן בְּשַׁבָּת כְּשֶׁיֵּרָאוּ. וּשְׁאָר כָּל הַמַּזִּיקִין אִם הָיוּ רָצִין אַחֲרָיו מֻתָּר לְהָרְגָן וְאִם הָיוּ יוֹשְׁבִין בִּמְקוֹמָן אוֹ בּוֹרְחִין מִלְּפָנָיו אָסוּר לְהָרְגָן. וְאִם דּוֹרְסָן לְפִי תֻּמּוֹ בִּשְׁעַת הִלּוּכוֹ וְהוֹרְגָן מֻתָּר:","הַמַּפְשִׁיט מִן הָעוֹר כְּדֵי לַעֲשׂוֹת קָמֵעַ חַיָּב. וְכֵן הַמְעַבֵּד מִן הָעוֹר כְּדֵי לַעֲשׂוֹת קָמֵעַ חַיָּב. וְאֶחָד הַמּוֹלֵחַ וְאֶחָד הַמְעַבֵּד שֶׁהַמְּלִיחָה מִין עִבּוּד הוּא וְאֵין עִבּוּד בָּאֳכָלִין. וְכֵן הַמּוֹחֵק מִן הָעוֹר כְּדֵי לַעֲשׂוֹת קָמֵעַ חַיָּב. וְאֵי זֶהוּ מוֹחֵק זֶה הַמַּעֲבִיר שֵׂעָר אוֹ הַצֶּמֶר מֵעַל הָעוֹר אַחַר מִיתָה עַד שֶׁיַּחֲלִיק פְּנֵי הָעוֹר:","הַמְפָרֵק דּוּכְסוּסְטוּס מֵעַל הַקְּלָף הֲרֵי זֶה תּוֹלֶדֶת מַפְשִׁיט וְחַיָּב. (הַמְפָרֵק מִן הָעוֹר כְּדֵי לַעֲשׂוֹת קָמֵעַ חַיָּב). הַדּוֹרֵס עַל הָעוֹר בְּרַגְלוֹ עַד שֶׁיִּתְקַשֶּׁה אוֹ הַמְרַכְּכוֹ בְּיָדוֹ וּמוֹשְׁכוֹ וּמַשְׁוֶה אוֹתוֹ כְּדֶרֶךְ שֶׁהָרַצְעָנִין עוֹשִׂין הֲרֵי זֶה תּוֹלֶדֶת מְעַבֵּד וְחַיָּב. הַמּוֹרֵט נוֹצָה מִן הָאֶבְרָה הֲרֵי זֶה תּוֹלֶדֶת מוֹחֵק וְחַיָּב. וְכֵן הַמְמָרֵחַ רְטִיָּה כָּל שֶׁהוּא אוֹ שַׁעֲוָה אוֹ זֶפֶת וְכַיּוֹצֵא בָּהֶן מִדְּבָרִים הַמִּתְמָרְחִין עַד שֶׁיַּחֲלִיק פְּנֵיהֶם חַיָּב מִשּׁוּם מוֹחֵק. וְכֵן הַשָּׁף בְּיָדוֹ עַל הָעוֹר הַמָּתוּחַ בֵּין הָעַמּוּדִים חַיָּב מִשּׁוּם מוֹחֵק:","הַמְחַתֵּךְ מִן הָעוֹר כְּדֵי לַעֲשׂוֹת קָמֵעַ חַיָּב. וְהוּא שֶׁיִּתְכַּוֵּן לְמִדַּת אָרְכּוֹ וּמִדַּת רָחְבּוֹ וְיַחְתֹּךְ בְּכַוָּנָה שֶׁהִיא מְלָאכָה. אֲבָל אִם חָתַךְ דֶּרֶךְ הֶפְסֵד אוֹ בְּלֹא כַּוָּנָה לְמִדָּתוֹ אֶלָּא כְּמִתְעַסֵּק אוֹ כִּמְשַׂחֵק הֲרֵי זֶה פָּטוּר. הַקּוֹטֵם אֶת הַכָּנָף הֲרֵי זֶה תּוֹלֶדֶת מְחַתֵּךְ וְחַיָּב. וְכֵן הַמְגָרֵד רָאשֵׁי כְּלוּנְסוֹת שֶׁל אֶרֶז חַיָּב מִשּׁוּם מְחַתֵּךְ. וְכֵן כָּל חֲתִיכָה שֶׁיַּחְתֹּךְ חָרַשׁ עֵץ מִן הָעֵצִים אוֹ חָרַשׁ מַתֶּכֶת מִן הַמַּתָּכוֹת חַיָּב מִשּׁוּם מְחַתֵּךְ. הַנּוֹטֵל קֵיסָם שֶׁל עֵץ מִלְּפָנָיו וּקְטָמוֹ לַחְצֹץ בּוֹ שִׁנָּיו אוֹ לִפְתֹּחַ בּוֹ אֶת הַדֶּלֶת חַיָּב:","כָּל דָּבָר שֶׁהוּא רָאוּי לְמַאֲכַל בְּהֵמָה כְּגוֹן תֶּבֶן וַעֲשָׂבִים לַחִים וְהוּצִין וְכַיּוֹצֵא בָּהֶן מֻתָּר לִקְטֹם אוֹתָן בְּשַׁבָּת מִפְּנֵי שֶׁאֵין בָּהֶן תִּקּוּן כֵּלִים. וּמֻתָּר לִקְטֹם עֲצֵי בְּשָׂמִים לְהָרִיחַ בָּהֶן אַף עַל פִּי שֶׁהֵן קָשִׁים וִיבֵשִׁין. וּמְפַשֵּׁחַ מֵהֶן כָּל מַה שֶּׁיִּרְצֶה בֵּין שֶׁפָּשַׁח עֵץ גָּדוֹל בֵּין שֶׁפָּשַׁח עֵץ קָטָן:","הַכּוֹתֵב שְׁתֵּי אוֹתִיּוֹת חַיָּב. הַמּוֹחֵק כְּתָב עַל מְנָת לִכְתֹּב בִּמְקוֹם הַמַּחַק שְׁתֵּי אוֹתִיּוֹת חַיָּב. הכּוֹתֵב אוֹת אַחַת גְּדוֹלָה כִּשְׁתַּיִם פָּטוּר. מָחַק אוֹת אַחַת גְּדוֹלָה וְיֵשׁ בִּמְקוֹמָהּ כְּדֵי לִכְתֹּב שְׁתַּיִם חַיָּב. כָּתַב אוֹת אַחַת וְהִשְׁלִים בָּהּ אֶת הַסֵּפֶר חַיָּב. הַכּוֹתֵב עַל מְנָת לְקַלְקֵל הָעוֹר חַיָּב שֶׁאֵין חִיּוּבוֹ עַל מְקוֹם הַכְּתָב אֶלָּא עַל הַכְּתָב. אֲבָל הַמּוֹחֵק עַל מְנָת לְקַלְקֵל פָּטוּר. נָפְלָה דְּיוֹ עַל גַּבֵּי סֵפֶר וּמָחַק אוֹתָהּ. נָפְלָה שַׁעֲוָה עַל גַּבֵּי הַפִּנְקָס וּמָחַק אוֹתָהּ. אִם יֵשׁ בִּמְקוֹמָהּ כְּדֵי לִכְתֹּב שְׁתֵּי אוֹתִיּוֹת חַיָּב:","הַכּוֹתֵב אוֹת כְּפוּלָה פַּעֲמַיִם וְהוּא שֵׁם אֶחָד כְּמוֹ דָּד תֵּת גַּג רָר שָׂשׂ סָס חָח חַיָּב. וְהַכּוֹתֵב בְּכָל כְּתָב וּבְכָל לָשׁוֹן חַיָּב וַאֲפִלּוּ מִשְּׁנֵי סִימָנִיּוֹת:","הַכּוֹתֵב אוֹת אַחַת סָמוּךְ לַכְּתָב אוֹ כְּתָב עַל גַּבֵּי כְּתָב וְהַמִּתְכַּוֵּן לִכְתֹּב חֵי\"ת וְכָתַב שְׁנֵי זַיִנִּי\"ן וְכֵן כַּיּוֹצֵא בָּזֶה בִּשְׁאָר אוֹתִיּוֹת וְהַכּוֹתֵב אוֹת אַחַת בָּאָרֶץ וְאוֹת אַחַת בַּקּוֹרָה שֶׁהֲרֵי אֵין נֶהֱגִין זֶה עִם זֶה אוֹ שֶׁכָּתַב שְׁתֵּי אוֹתִיּוֹת בִּשְׁנֵי דַּפֵּי פִּנְקָס וְאֵינָן נֶהֱגִין זֶה עִם זֶה פָּטוּר. כְּתָבָן בִּשְׁנֵי כָּתְלֵי זָוִית אוֹ בִּשְׁנֵי דַּפֵּי פִּנְקָס וְהֵן נֶהֱגִין זֶה עִם זֶה חַיָּב:","לָקַח גְּוִיל וְכַיּוֹצֵא בּוֹ וְכָתַב עָלָיו אוֹת אַחַת בִּמְדִינָה זוֹ וְהָלַךְ בְּאוֹתוֹ הַיּוֹם וְכָתַב אוֹת שְׁנִיָּה בִּמְדִינָה אַחֶרֶת בִּמְגִלָּה אַחֶרֶת חַיָּב. שֶׁבִּזְמַן שֶׁמְּקָרְבָן נֶהֱגִין זֶה עִם זֶה וְאֵינָן מְחֻסָּרִין מַעֲשֶׂה לִקְרִיבָתָן:","הַכּוֹתֵב אוֹת אַחַת אַף עַל פִּי שֶׁקּוֹרִים מִמֶּנָּה תֵּבָה שְׁלֵמָה פָּטוּר. כֵּיצַד. כְּגוֹן שֶׁכָּתַב מ' וְהַכּל קוֹרִין אוֹתָהּ מַעֲשֵׂר. אוֹ שֶׁכְּתָבָהּ בְּמָקוֹם מִנְיָן שֶׁהֲרֵי הִיא כְּמוֹ שֶׁכָּתַב אַרְבָּעִים הֲרֵי זֶה פָּטוּר. הַמַּגִּיהַּ אוֹת אַחַת וְעָשָׂה אוֹתָהּ שְׁתַּיִם כְּגוֹן שֶׁחִלֵּק גַּג הַחֵי\"ת וְנַעֲשֵׂית שְׁנֵי זַיִנִּי\"ן חַיָּב. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַכּוֹתֵב בִּשְׂמֹאלוֹ אוֹ לְאַחַר יָדוֹ בְּרַגְלוֹ בְּפִיו וּבְמַרְפֵּקוֹ פָּטוּר. אִטֵּר שֶׁכָּתַב בִּימִינוֹ שֶׁהִיא לוֹ כִּשְׂמֹאל כָּל אָדָם פָּטוּר. וְאִם כָּתַב בִּשְׂמֹאלוֹ חַיָּב. וְהַשּׁוֹלֵט בִּשְׁתֵּי יָדָיו בְּשָׁוֶה וְכָתַב בֵּין בִּימִינוֹ בֵּין בִּשְׂמֹאלוֹ חַיָּב. קָטָן אוֹחֵז בְּקֻלְמוֹס וְגָדוֹל אוֹחֵז בְּיָדוֹ וְכוֹתֵב חַיָּב. גָּדוֹל אוֹחֵז בְּקֻלְמוֹס וְקָטָן אוֹחֵז בְּיָדוֹ וְכוֹתֵב פָּטוּר:","אֵין הַכּוֹתֵב חַיָּב עַד שֶׁיִּכְתֹּב בְּדָבָר הָרוֹשֵׁם וְעוֹמֵד כְּגוֹן דְּיוֹ וְשָׁחוֹר וְסִקְרָא וְקוֹמוֹס וְקַנְקַנְתּוֹם וְכַיּוֹצֵא בָּהֶם. וְיִכְתֹּב עַל דָּבָר שֶׁמִּתְקַיֵּם הַכְּתָב עָלָיו כְּגוֹן עוֹר וּקְלָף וּנְיָר וְעֵץ וְכַיּוֹצֵא בָּהֶם. אֲבָל הַכּוֹתֵב בְּדָבָר שֶׁאֵין רִשּׁוּמוֹ עוֹמֵד כְּגוֹן מַשְׁקִין וּמֵי פֵּרוֹת. אוֹ שֶׁכָּתַב בִּדְיוֹ וְכַיּוֹצֵא בּוֹ עַל עֲלֵי יְרָקוֹת וְעַל כָּל דָּבָר שֶׁאֵינוֹ עוֹמֵד פָּטוּר. אֵינוֹ חַיָּב עַד שֶׁיִּכְתֹּב בְּדָבָר הָעוֹמֵד עַל דָּבָר הָעוֹמֵד. וְכֵן אֵין הַמּוֹחֵק חַיָּב עַד שֶׁיִּמְחֹק כְּתָב הָעוֹמֵד מֵעַל דָּבָר הָעוֹמֵד:","הַכּוֹתֵב עַל בְּשָׂרוֹ חַיָּב מִפְּנֵי שֶׁהוּא עוֹר אַף עַל פִּי שֶׁחֲמִימוּת בְּשָׂרוֹ מַעֲבֶרֶת הַכְּתָב לְאַחַר זְמַן הֲרֵי זֶה דּוֹמֶה לִכְתָב שֶׁנִּמְחַק. אֲבָל הַמְשָׂרֵט עַל בְּשָׂרוֹ צוּרַת כְּתָב פָּטוּר. הַקּוֹרֵעַ עַל הָעוֹר כְּתַבְנִית כְּתָב חַיָּב מִשּׁוּם כּוֹתֵב. הָרוֹשֵׁם עַל הָעוֹר כְּתַבְנִית כְּתָב פָּטוּר. הַמַּעֲבִיר דְּיוֹ עַל גַּבֵּי סִקְרָא חַיָּב שְׁתַּיִם אַחַת מִשּׁוּם כּוֹתֵב וְאַחַת מִשּׁוּם מוֹחֵק. הֶעֱבִיר דְּיוֹ עַל גַּבֵּי דְּיוֹ וְסִקְרָא עַל גַּבֵּי סִקְרָא אוֹ סִקְרָא עַל גַּבֵּי דְּיוֹ פָּטוּר:","רוֹשֵׁם תּוֹלֶדֶת כּוֹתֵב הוּא. כֵּיצַד. הָרוֹשֵׁם רְשָׁמִים וְצוּרוֹת בְּכֹתֶל וּבְשָׁשַׁר וְכַיּוֹצֵא בָּהֶן כְּדֶרֶךְ שֶׁהַצַּיָּרִין רוֹשְׁמִים הֲרֵי זֶה חַיָּב מִשּׁוּם כּוֹתֵב. וְכֵן הַמּוֹחֵק אֶת הָרִשּׁוּם לְתַקֵּן הֲרֵי זֶה תּוֹלֶדֶת מוֹחֵק וְחַיָּב. הַמְשַׂרְטֵט כְּדֵי לִכְתֹּב שְׁתֵּי אוֹתִיּוֹת תַּחַת אוֹתוֹ שִׂרְטוּט חַיָּב. חָרָשֵׁי הָעֵצִים שֶׁמַּעֲבִירִין חוּט שֶׁל סִקְרָא עַל גַּבֵּי הַקּוֹרָה כְּדֵי שֶׁיִּנְסֹר בְּשָׁוֶה הֲרֵי זֶה תּוֹלֶדֶת מְשַׂרְטֵט. וְכֵן הַגַּבָּלִים שֶׁעוֹשִׂים כֵּן בַּאֲבָנִים כְּדֵי שֶׁיְּפַצֵּל הָאֶבֶן בְּשָׁוֶה. וְאֶחָד הַמְשַׂרְטֵט בְּצֶבַע אוֹ בְּלֹא צֶבַע הֲרֵי זֶה חַיָּב:"],"Mishneh Torah, Sabbath 22":["רְדִיַּת הַפַּת אַף עַל פִּי שֶׁאֵינָהּ מְלָאכָה אָסְרוּ אוֹתָהּ חֲכָמִים שֶׁמָּא יָבוֹא לֶאֱפוֹת. הַמַּדְבִּיק פַּת בַּתַּנּוּר מִבְּעוֹד יוֹם וְקָדַשׁ עָלָיו הַיּוֹם מַצִּיל מִמֶּנָּה מָזוֹן שָׁלֹשׁ סְעֻדּוֹת וְאוֹמֵר לַאֲחֵרִים בּוֹאוּ וְהַצִּילוּ לָכֶם. וְאַף עַל פִּי שֶׁהָרְדִיָּה אֵינָהּ מְלָאכָה כְּשֶׁהוּא מַצִּיל לֹא יִרְדֶּה בְּמִרְדֶּה אֶלָּא בְּסַכִּין כְּדֵי לְשַׁנּוֹת:","מִפְּנֵי מָה אָסְרוּ חֲכָמִים לִכָּנֵס בַּמֶּרְחָץ בְּשַׁבָּת. מִפְּנֵי הַבַּלָּנִין שֶׁהָיוּ מְחִמִּין חַמִּין בְּשַׁבָּת וְאוֹמְרִין מֵעֶרֶב שַׁבָּת הוּחַמּוּ. לְפִיכָךְ גָּזְרוּ שֶׁלֹּא יִכָּנֵס אָדָם לַמֶּרְחָץ בְּשַׁבָּת אֲפִלּוּ לְהַזִּיעַ. וְגָזְרוּ שֶׁלֹּא יִשְׁתַּטֵּף כָּל גּוּפוֹ בְּחַמִּין וַאֲפִלּוּ בְּחַמִּין שֶׁהוּחַמּוּ מֵעֶרֶב שַׁבָּת. אֲבָל פָּנָיו יָדָיו וְרַגְלָיו מֻתָּר. בַּמֶּה דְּבָרִים אֲמוּרִים בְּחַמֵּי הָאוּר גְּזֵרָה מִשּׁוּם מֶרְחָץ. אֲבָל בְּחַמֵּי טְבֶרְיָא וְכַיּוֹצֵא בָּהֶן מֻתָּר לְהִשְׁתַּטֵּף בָּהֶן כָּל גּוּפוֹ. וְאָסוּר לִרְחֹץ בְּמַיִם חַמִּין שֶׁבַּמְּעָרוֹת מִפְּנֵי שֶׁהַמְּעָרָה יֵשׁ בָּהּ הֶבֶל וְיָבוֹא לִידֵי זֵעָה וְנִמְצֵאת כְּמֶרְחָץ:","מִתְחַמֵּם אָדָם כְּנֶגֶד הַמְּדוּרָה וְיוֹצֵא וּמִשְׁתַּטֵּף כָּל גּוּפוֹ בְּצוֹנֵן. אֲבָל אֵינוֹ מִשְׁתַּטֵּף כָּל גּוּפוֹ בְּצוֹנֵן וּמִתְחַמֵּם כְּנֶגֶד הַמְּדוּרָה מִפְּנֵי שֶׁמַּפְשִׁיר מַיִם שֶׁעָלָיו וְנִמְצָא כְּרוֹחֵץ כָּל גּוּפוֹ בְּחַמִּין. הַמֵּבִיא סִילוֹן שֶׁל צוֹנֵן בְּתוֹךְ מַיִם חַמִּין אֲפִלּוּ בְּתוֹךְ חַמֵּי טְבֶרְיָא הֲרֵי אֵלּוּ כְּחַמִּין שֶׁהוּחַמּוּ בְּשַׁבָּת וַאֲסוּרִין בִּרְחִיצָה וּבִשְׁתִיָּה:","מֵבִיא אָדָם קִיתוֹן שֶׁל מַיִם וּמַנִּיחוֹ כְּנֶגֶד הַמְּדוּרָה לֹא בִּשְׁבִיל שֶׁיֵּחַמּוּ אֶלָּא כְּדֵי שֶׁתָּפוּג צִנָּתָן. וְכֵן מַנִּיחַ פַּךְ שֶׁל שֶׁמֶן כְּנֶגֶד הַמְּדוּרָה כְּדֵי שֶׁיִּפְשַׁר לֹא שֶׁיֵּחַם. וְסָךְ אָדָם יָדוֹ בְּמַיִם אוֹ בְּשֶׁמֶן וּמְחַמֵּם כְּנֶגֶד הַמְּדוּרָה. וְהוּא שֶׁלֹּא יֵחַמּוּ הַמַּיִם שֶׁעַל יָדוֹ עַד שֶׁתְּהֵא כְּרֵסוֹ שֶׁל תִּינוֹק נִכְוֵית בָּהֶן. וּמְחַמֵּם בֶּגֶד וּמַנִּיחוֹ עַל גַּבֵּי מֵעַיִם בְּשַׁבָּת:","אַמְבְּטִי שֶׁל מֶרְחָץ שֶׁהִיא מְלֵאָה מַיִם חַמִּים אֵין נוֹתְנִין לָהּ מַיִם צוֹנֵן שֶׁהֲרֵי מְחַמְּמָן הַרְבֵּה. וְכֵן לֹא יִתֵּן לְתוֹכָהּ פַּךְ שֶׁל שֶׁמֶן מִפְּנֵי שֶׁהוּא כִּמְבַשְּׁלוֹ. אֲבָל נוֹתֵן הוּא מַיִם חַמִּין לְתוֹךְ אַמְבְּטִי שֶׁל צוֹנֵן:","מֵיחַם שֶׁפִּנָּה מִמֶּנּוּ מַיִם חַמִּין מֻתָּר לִתֵּן לְתוֹכוֹ מַיִם צוֹנֵן כְּדֵי לְהַפְשִׁירָן. וּמֻתָּר לִצֹּק מַיִם חַמִּין לְתוֹךְ מַיִם צוֹנֵן אוֹ צוֹנֵן לְתוֹךְ הַחַמִּין וְהוּא שֶׁלֹּא יִהְיוּ בִּכְלִי רִאשׁוֹן מִפְּנֵי שֶׁהוּא מְחַמְּמָן הַרְבֵּה. וְכֵן קְדֵרָה רוֹתַחַת אַף עַל פִּי שֶׁהוֹרִידָהּ מֵעַל הָאֵשׁ לֹא יִתֵּן לְתוֹכָהּ תַּבְלִין אֲבָל נוֹתֵן לְתוֹכָהּ מֶלַח שֶׁהַמֶּלַח אֵינוֹ מִתְבַּשֵּׁל אֶלָּא עַל גַּבֵּי אֵשׁ גְּדוֹלָה. וְאִם יָצַק הַתַּבְשִׁיל מִקְּדֵרָה לִקְעָרָה אַף עַל פִּי שֶׁהוּא רוֹתֵחַ בַּקְּעָרָה מֻתָּר לוֹ לִתֵּן לְתוֹךְ הַקְּעָרָה תַּבְלִין שֶׁכְּלִי שֵׁנִי אֵינוֹ מְבַשֵּׁל:","אֵין שׁוֹרִין אֶת הַחִלְתִּית בֵּין בְּפוֹשְׁרִין בֵּין בְּצוֹנֵן אֲבָל שׁוֹרֶה אוֹתוֹ בְּתוֹךְ הַחֹמֶץ. וְאִם שָׁתָהוּ בְּיוֹם חֲמִישִׁי וְשִׁשִּׁי הֲרֵי זֶה שׁוֹרֶה בְּשַׁבָּת בְּצוֹנֵן וּמַנִּיחוֹ בַּחַמָּה עַד שֶׁיֵּחַם וְשׁוֹתֶה. כְּדֵי שֶׁלֹּא יֶחֱלֶה אִם פָּסַק מִלִּשְׁתּוֹת:","דָּבָר שֶׁנִתְבַּשֵּׁל קֹדֶם הַשַּׁבָּת אוֹ נִשְׁרָה בְּחַמִּין מִלִּפְנֵי הַשַּׁבָּת אַף עַל פִּי שֶׁהוּא עַכְשָׁו צוֹנֵן מֻתָּר לִשְׁרוֹתוֹ בְּחַמִּין בְּשַׁבָּת. וְדָבָר שֶׁהוּא צוֹנֵן מֵעִקָּרוֹ וְלֹא בָּא בְּחַמִּין מֵעוֹלָם מְדִיחִין אוֹתוֹ בְּחַמִּין בְּשַׁבָּת אִם לֹא הָיְתָה הֲדָחָתוֹ גְּמַר מְלַאכְתּוֹ אֲבָל אֵין שׁוֹרִין אוֹתוֹ בְּחַמִּין:","מֻתָּר לְהָחֵם בַּחַמָּה אַף עַל פִּי שֶׁאָסוּר לְהָחֵם בְּתוֹלְדוֹת חַמָּה שֶׁאֵינוֹ בָּא לִטְעוֹת מֵחַמָּה לְאוּר. לְפִיכָךְ מֻתָּר לִתֵּן מַיִם צוֹנֵן בַּשֶּׁמֶשׁ כְּדֵי שֶׁיֵּחַמּוּ. וְכֵן נוֹתְנִין מַיִם יָפִים לְתוֹךְ מַיִם רָעִים בִּשְׁבִיל שֶׁיֵּצַנּוּ. וְנוֹתְנִין תַּבְשִׁיל לְתוֹךְ הַבּוֹר בִּשְׁבִיל שֶׁיְּהֵא שָׁמוּר:","מְעָרֵב אָדָם מַיִם וּמֶלַח וְשֶׁמֶן וְטוֹבֵל בּוֹ פִּתּוֹ אוֹ נוֹתְנוֹ לְתוֹךְ הַתַּבְשִׁיל. וְהוּא שֶׁיַּעֲשֶׂה מְעַט אֲבָל הַרְבֵּה אָסוּר מִפְּנֵי שֶׁנִּרְאֶה כְּעוֹשֶׂה מְלָאכָה מִמְּלֶאכֶת הַתַּבְשִׁיל. וְכֵן לֹא יַעֲשֶׂה מֵי מֶלַח עַזִּין וְהֵן שְׁנֵי שְׁלִישֵׁי מֶלַח וּשְׁלִישׁ מַיִם מִפְּנֵי שֶׁנִּרְאֶה כְּעוֹשֶׂה מוּרְיָס. וּמֻתָּר לִמְלֹחַ בֵּיצָה אֲבָל צְנוֹן וְכַיּוֹצֵא בּוֹ אָסוּר מִפְּנֵי שֶׁנִּרְאֶה כְּכוֹבֵשׁ כְּבָשִׁים בְּשַׁבָּת וְהַכּוֹבֵשׁ אָסוּר מִפְּנֵי שֶׁהוּא כִּמְבַשֵּׁל. וּמֻתָּר לִטְבּל צְנוֹן וְכַיּוֹצֵא בּוֹ בְּמֶלַח וְאוֹכֵל:","מֻתָּר לְעָרֵב יַיִן וּדְבַשׁ וּפִלְפְּלִין בְּשַׁבָּת לְאָכְלָן אֲבָל יַיִן וּמַיִם וְשֶׁמֶן אֲפַרְסְמוֹן אָסוּר שֶׁאֵין זֶה רָאוּי לַאֲכִילַת בְּרִיאִים. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","חַרְדָּל שֶׁלָּשׁוֹ מֵעֶרֶב שַׁבָּת לְמָחָר מְמַחוֹ בֵּין בְּיָד בֵּין בִּכְלִי וְנוֹתֵן לְתוֹכוֹ דְּבַשׁ וְלֹא יִטְרֹף אֶלָּא מְעָרֵב. שַׁחֲלַיִם שֶׁטְּרָפָן מֵעֶרֶב שַׁבָּת לְמָחָר נוֹתֵן לְתוֹכוֹ שֶׁמֶן וְחֹמֶץ וְתַבְלִין וְלֹא יִטְרֹף אֶלָּא מְעָרֵב. שׁוּם שֶׁרִסְּקוֹ מֵעֶרֶב שַׁבָּת לְמָחָר נוֹתְנוֹ לְתוֹךְ הַגְּרִיסִין וְלֹא יִשְׁחֹק אֶלָּא מְעָרֵב:","הַנּוֹטֵל שֵׂעָר מִגּוּף הָאָדָם חַיָּב מִשּׁוּם גּוֹזֵז. לְפִיכָךְ אָסוּר לִרְחֹץ אֶת הַיָּדַיִם בִּדְבַר שֶׁמַּשִּׁיר אֶת הַשֵּׂעָר וַדַּאי כְּגוֹן אָהֳלָה וְכַיּוֹצֵא בּוֹ. וּמֻתָּר לָחֹף אֶת הַיָּדַיִם בַּעֲפַר לְבוֹנָה וַעֲפַר פִּלְפְּלִין וַעֲפַר יַסְמִין וְכַיּוֹצֵא בָּהֶן וְאֵינוֹ חוֹשֵׁשׁ שֶׁמָּא יַשִּׁיר שֵׂעָר שֶׁעַל יָדוֹ שֶׁהֲרֵי אֵינוֹ מִתְכַּוֵּן. עֵרֵב דָּבָר שֶׁמַּשִּׁיר אֶת הַשֵּׂעָר וַדַּאי עִם דָּבָר שֶׁאֵינוֹ מַשִּׁיר וַדַּאי אִם הָיָה הָרֹב מִדָּבָר הַמַּשִּׁיר אָסוּר לָחֹף בּוֹ וְאִם לָאו מֻתָּר:","אָסוּר לִרְאוֹת בְּמַרְאָה שֶׁל מַתֶּכֶת בְּשַׁבָּת גְּזֵרָה שֶׁמָּא יַשִּׁיר בָּהּ נִימִין הַמְדֻלְדָּלִין מִן הַשֵּׂעָר וַאֲפִלּוּ קָבוּעַ בַּכֹּתֶל. אֲבָל מַרְאָה שֶׁאֵינָהּ שֶׁל מַתֶּכֶת מֻתָּר לִרְאוֹת בָּהּ אֲפִלּוּ אֵינָהּ קְבוּעָה:","הַמְכַבֵּס חַיָּב מִשּׁוּם מְלַבֵּן. וְהַסּוֹחֵט כְּסוּת חַיָּב מִפְּנֵי שֶׁהוּא מְכַבֵּס. לְפִיכָךְ אָסוּר לִדְחֹק מַטְלִית אוֹ מוֹךְ וְכַיּוֹצֵא בָּהֶן בְּפִי הָאֲשִׁישָׁה וְכַיּוֹצֵא בָּהּ כְּדֵי לְסָתְמָהּ שֶׁמָּא יָבֹא לִידֵי סְחִיטָה. וְאֵין מְקַנְּחִין בִּסְפוֹג אֶלָּא אִם כֵּן יֵשׁ לוֹ בֵּית אֲחִיזָה שֶׁלֹּא יִסְחֹט. וְאֵין מְכַסִּין חָבִית שֶׁל מַיִם וְכַיּוֹצֵא בָּהּ בְּבֶגֶד שֶׁאֵינוֹ מוּכָן לָהּ גְּזֵרָה שֶׁמָּא יִסְחֹט:","נִשְׁבְּרָה לוֹ חָבִית בְּשַׁבָּת מַצִּיל מִמֶּנָּה מַה שֶּׁהוּא צָרִיךְ לְשַׁבָּת לוֹ וּלְאוֹרְחָיו וּבִלְבַד שֶׁלֹּא יִסְפֹּג בְּיַיִן אוֹ יְטַפַּח בְּשֶׁמֶן שֶׁאִם יַעֲשֶׂה כְּדֶרֶךְ שֶׁהוּא עוֹשֶׂה בְּחל שֶׁמָּא יָבוֹא לִידֵי סְחִיטָה. וְכֵיצַד מַצִּיל מִמֶּנָּה. מֵבִיא כְּלִי וּמַנִּיחַ תַּחְתֶּיהָ. וְלֹא יָבִיא כְּלִי אַחֵר וְיִקְלֹט כְּלִי אַחֵר וִיצָרֵף גְּזֵרָה שֶׁמָּא יָבִיא כְּלִי דֶּרֶךְ רְשׁוּת הָרַבִּים. נִזְדַּמְּנוּ לוֹ אוֹרְחִים מֵבִיא כְּלִי אַחֵר וְקוֹלֵט כְּלִי אַחֵר וּמְצָרְפוֹ לָרִאשׁוֹן. וְלֹא יִקְלֹט וְאַחַר כָּךְ יַזְמִין אֶלָּא יַזְמִין וְאַחַר כָּךְ יִקְלֹט. וְאִם הֶעֱרִים בְּדָבָר זֶה מֻתָּר:","טִיט שֶׁעַל גַּבֵּי בִּגְדוֹ מְכַסְכְּסוֹ מִבִּפְנִים וְאֵינוֹ מְכַסְכְּסוֹ מִבַּחוּץ גְּזֵרָה שֶׁמָּא יְכַבֵּס. וּמֻתָּר לְגָרְדוֹ בְּצִפֹּרֶן וְאֵינוֹ חוֹשֵׁשׁ שֶׁמָּא יְלַבְּנוֹ. הַמְכַסְכֵּס אֶת הַסּוּדָר אָסוּר מִפְּנֵי שֶׁהוּא מְלַבְּנוֹ אֲבָל הֶחָלוּק מֻתָּר מִפְּנֵי שֶׁאֵין כַּוָּנָתוֹ אֶלָּא לְרַכְּכוֹ:","מִנְעָל אוֹ סַנְדָּל שֶׁנִּתְלַכְלֵךְ בְּטִיט וּבְצוֹאָה מֻתָּר לְשַׁכְשְׁכוֹ בְּמַיִם אֲבָל לְכַבְּסוֹ אָסוּר. וְאֵין מְגָרְדִּין לֹא מִנְעָלִים וְלֹא סַנְדָּלִים חֲדָשִׁים אֲבָל סָכִין (אוֹתָם) וּמְקַנְּחִין אֶת הַיְשָׁנִים. כַּר אוֹ כֶּסֶת שֶׁהָיָה עֲלֵיהֶן צוֹאָה אוֹ טִנּוּף מְקַנְּחוֹ בִּסְמַרְטוּט. וְאִם הָיְתָה עַל שֶׁל עוֹר נוֹתְנִין עָלֶיהָ מַיִם עַד שֶׁתִּכְלֶה:","מִי שֶׁנִּתְלַכְלְכָה יָדוֹ בְּטִיט מְקַנְּחָהּ בִּזְנַב הַסּוּס וּבִזְנַב הַפָּרָה וּבְמַפָּה הַקָּשָׁה הָעֲשׂוּיָה לֶאֱחֹז בָּהּ הַקּוֹצִים. אֲבָל לֹא בְּמַפָּה שֶׁמְּקַנְּחִין בָּהּ אֶת הַיָּדַיִם שֶׁלֹּא יַעֲשֶׂה כְּדֶרֶךְ שֶׁהוּא עוֹשֶׂה בְּחל וְיָבוֹא לְכַבֵּס אֶת הַמַּפָּה:","מִי שֶׁרָחַץ בְּמַיִם מִסְתַּפֵּג בַּאֲלֻנְטִיתוֹ וּמְבִיאָהּ בְּיָדוֹ וְאֵין חוֹשְׁשִׁין שֶׁמָּא יִסְחֹט. וְכֵן מִי שֶׁנָּשְׁרוּ כֵּלָיו בְּמַיִם מְהַלֵּךְ בָּהֶן וְאֵין חוֹשְׁשִׁין שֶׁמָּא יִסְחֹט. וְאָסוּר לוֹ לְשָׁטְחָן וַאֲפִלּוּ בְּתוֹךְ בֵּיתוֹ גְּזֵרָה שֶׁמָּא יֹאמַר הָרוֹאֶה הֲרֵי זֶה כִּבֵּס כְּסוּתוֹ בְּשַׁבָּת וּשְׁטָחָהּ לְיַבְּשָׁהּ. וְכָל מָקוֹם שֶׁאָסְרוּ חֲכָמִים מִפְּנֵי מַרְאִית הָעַיִן אֲפִלּוּ בְּחַדְרֵי חֲדָרִים אָסוּר:","שְׁתֵּי מְטַהְרוֹת זוֹ עַל גַּב זוֹ נוֹטֵל אֶת הַפְּקָק מִבֵּינְתַיִם וּמְשִׁיקָן וּמַחֲזִיר אֶת הַפְּקָק לִמְקוֹמוֹ מִפְּנֵי שֶׁאֵינוֹ בָּא לִידֵי סְחִיטָה שֶׁהֲרֵי דַּעְתּוֹ שֶׁיֵּצְאוּ הַמַּיִם. וּפוֹקְקִין אֶת הַבִּיב בְּסוּדָרִין וּבְכָל דָּבָר הַמִּטַּלְטֵל כְּדֵי שֶׁלֹּא יָצוּפוּ הַמַּיִם עַל הָאֳכָלִים וְעַל הַכֵּלִים. אֲבָל אֵין פּוֹקְקִין אֶת הַבִּיב כְּדֵי שֶׁיֵּרְדוּ הַמַּיִם לַבּוֹר שֶׁמָּא יִסְחֹט בְּעֵת שֶׁדּוֹחֵק שֶׁהֲרֵי הַפְּקָק שָׁרוּי בְּמַיִם:","אָסוּר לְתַקֵּן בֵּית יָד שֶׁל בְּגָדִים וּלְשַׁבְּרָם שְׁבָרִים שְׁבָרִים כְּדֶרֶךְ שֶׁמְּתַקְּנִין בְּחל הַבְּגָדִים כְּשֶׁמְּכַבְּסִין אוֹתָן. וְכֵן אֵין מְקַפְּלִים הַבְּגָדִים בְּשַׁבָּת כְּדֶרֶךְ שֶׁעוֹשִׂין בְּחל בַּבְּגָדִים כְּשֶׁיְּכַבְּסוּ אוֹתָן. וְאִם לֹא הָיָה לוֹ כְּלִי אַחֵר לְהַחֲלִיפוֹ מֻתָּר לְקַפְּלוֹ וּלְפָשְׁטוֹ וּלְהִתְכַּסּוֹת בּוֹ כְּדֵי שֶׁיִּתְנָאֶה בּוֹ בְּשַׁבָּת. וְהוּא שֶׁיִּהְיֶה בֶּגֶד חָדָשׁ לָבָן שֶׁהֲרֵי הוּא מִתְמַעֵךְ וּמִתְלַכְלֵךְ מִיָּד. וּכְשֶׁיְּקַפֵּל לֹא יְקַפֵּל אֶלָּא אִישׁ אֶחָד אֲבָל לְקַפֵּל בִּשְׁנַיִם אָסוּר:","הַצּוֹבֵעַ מֵאֲבוֹת מְלָאכוֹת לְפִיכָךְ אָסוּר לְאִשָּׁה לְהַעֲבִיר סְרָק עַל פָּנֶיהָ מִפְּנֵי שֶׁהִיא כְּצוֹבַעַת. וְהַתּוֹפֵר מֵאֲבוֹת מְלָאכוֹת לְפִיכָךְ אָסוּר לְמַלְּאוֹת הַכַּר וְהַכֶּסֶת הַחֲדָשִׁים בְּמוֹכִין גְּזֵרָה שֶׁמָּא יִתְפֹּר. אֲבָל מוֹכִין שֶׁנָּשְׁרוּ מִן הַכַּר אוֹ מִן הַכֶּסֶת מַחְזִירִין אוֹתָן בְּשַׁבָּת:","הַקּוֹרֵעַ מֵאֲבוֹת מְלָאכוֹת. לְפִיכָךְ מִי שֶׁנִּסְתַּבְּכוּ בְּגָדָיו בְּקוֹצִים מַפְרִישָׁן בְּצִנְעָה וּמִתְמַהְמֵהַּ כְּדֵי שֶׁלֹּא יִקְרַע. וְאִם נִקְרְעוּ אֵינוֹ חַיָּב כְּלוּם שֶׁהֲרֵי לֹא נִתְכַּוִּן. וּמֻתָּר לִלְבּשׁ בְּגָדִים חֲדָשִׁים וְאִם נִקְרְעוּ נִקְרְעוּ. פּוֹצְעִין אֶת הָאֱגוֹז בְּמַטְלִית וְאֵין חוֹשְׁשִׁין שֶׁמָּא תִּקָּרַע:","הַתּוֹקֵעַ חַיָּב מִשּׁוּם בּוֹנֶה. לְפִיכָךְ כָּל הַדְּלָתוֹת הַמְחֻבָּרוֹת לַקַּרְקַע לֹא נוֹטְלִין אוֹתָן וְלֹא מַחְזִירִין גְּזֵרָה שֶׁמָּא יִתְקַע. אֲבָל דֶּלֶת שִׁדָּה תֵּבָה וּמִגְדָּל וּשְׁאָר דַּלְתוֹת הַכֵּלִים נוֹטְלִין וְלֹא מַחְזִירִין. וְאִם נִשְׁמַט צִיר הַתַּחְתּוֹן שֶׁלָּהֶן דּוֹחֲקִין אוֹתוֹ לִמְקוֹמוֹ. וּבַמִּקְדָּשׁ מַחְזִירִין אוֹתוֹ. אֲבָל צִיר הָעֶלְיוֹן שֶׁנִּשְׁמַט אָסוּר לְהַחֲזִירוֹ בְּכָל מָקוֹם גְּזֵרָה שֶׁמָּא יִתְקַע:","אֵין גּוֹדְלִין אֶת שְׂעַר הָרֹאשׁ וְאֵין פּוֹקְסִין אוֹתוֹ מִפְּנֵי שֶׁנִּרְאֶה כְּבוֹנֶה. וְאֵין מַחְזִירִין מְנוֹרָה שֶׁל חֻלְיוֹת וְלֹא כִּסֵּא הַמְפֻצָּל וְלֹא שֻׁלְחָן הַמְפֻצָּל וְכַיּוֹצֵא בָּהֶן מִפְּנֵי שֶׁנִּרְאֶה כְּבוֹנֶה. וְאִם הֶחֱזִיר פָּטוּר שֶׁאֵין בִּנְיָן בְּכֵלִים וְאֵין סְתִירָה בְּכֵלִים. וְאִם הָיָה רָפוּי מֻתָּר לְהַחֲזִירוֹ. וְאֵין מְתַקְּנִין חֻלְיוֹת שֶׁל שִׁדְרָה שֶׁל קָטָן זוֹ בְּצַד זוֹ מִפְּנֵי שֶׁנִּרְאֶה כְּבוֹנֶה:","הָעוֹשֶׂה אֹהֶל קָבוּעַ חַיָּב מִשּׁוּם בּוֹנֶה. לְפִיכָךְ אֵין עוֹשִׂין אֹהֶל עֲרַאי לְכַתְּחִלָּה וְלֹא סוֹתְרִין אֹהֶל עֲרַאי גְּזֵרָה שֶׁמָּא יַעֲשֶׂה אוֹ יִסְתֹּר אֹהֶל קָבוּעַ. וְאִם עָשָׂה אוֹ סָתַר אֹהֶל עֲרַאי פָּטוּר. וּמֻתָּר לְהוֹסִיף עַל אֹהֶל עֲרַאי בְּשַׁבָּת. כֵּיצַד. טַלִּית שֶׁהָיְתָה פְּרוּסָה עַל הָעַמּוּדִים אוֹ עַל הַכְּתָלִים וְהָיְתָה כְּרוּכָה קֹדֶם הַשַּׁבָּת אִם נִשְׁאָר מִמֶּנָּה גַּג טֶפַח מָתוּחַ הֲרֵי זֶה מוֹתֵחַ אֶת כֻּלָּהּ בְּשַׁבָּת עַד שֶׁיַּעֲשֶׂה אֹהֶל גָּדוֹל. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","אֵין תּוֹלִין אֶת הַכִּלָּה שֶׁהֲרֵי נַעֲשֵׂית תַּחְתֶּיהָ אֹהֶל עֲרַאי. וּמֻתָּר לְהַנִּיחַ מִטָּה וְכִסֵּא וּטְרַסְקָל וְאַף עַל פִּי שֶׁיֵּעָשֶׂה תַּחְתֵּיהֶן אֹהֶל שֶׁאֵין זֶה דֶּרֶךְ עֲשִׂיַּת אֹהֶל לֹא קֶבַע וְלֹא עֲרַאי:","כָּל אֹהֶל מְשֻׁפָּע שֶׁאֵין בְּגַגּוֹ טֶפַח וְלֹא בְּפָחוֹת מִשְּׁלֹשָׁה סָמוּךְ לְגַגּוֹ רֹחַב טֶפַח הֲרֵי זֶה אֹהֶל עֲרַאי וְהָעוֹשֶׂה אוֹתוֹ לְכַתְּחִלָּה בְּשַׁבָּת פָּטוּר. טַלִּית כְּפוּלָה שֶׁהָיוּ עָלֶיהָ חוּטִין שֶׁהִיא תְּלוּיָה בָּהֶן מֵעֶרֶב שַׁבָּת מֻתָּר לִנְטוֹתָהּ וּמֻתָּר לְפָרְקָהּ וְכֵן הַפָּרֹכֶת:","כִּלַּת חֲתָנִים שֶׁאֵין בְּגַגָּהּ טֶפַח וְאֵין בְּפָחוֹת מִשְּׁלֹשָׁה סָמוּךְ לְגַגָּהּ רֹחַב טֶפַח. הוֹאִיל שֶׁהִיא מְתֻקֶּנֶת לְכָךְ מֻתָּר לִנְטוֹתָהּ וּמֻתָּר לְפָרְקָהּ וְהוּא שֶׁלֹּא תְּהֵא מְשֻׁלְשֶׁלֶת מֵעַל הַמִּטָּה טֶפַח. פְּקַק הַחַלּוֹן בִּזְמַן שֶׁהוּא מְתֻקָּן לְכָךְ אַף עַל פִּי שֶׁאֵינוֹ קָשׁוּר וְאֵינוֹ תָּלוּי מֻתָּר לִפְקֹק בּוֹ הַחַלּוֹן:","כּוֹבַע שֶׁעוֹשִׂין עַל הָרֹאשׁ וְיֵשׁ לוֹ שָׂפָה מַקֶּפֶת שֶׁהִיא עוֹשָׂה צֵל כְּמוֹ אֹהֶל עַל לְבוּשׁוֹ מֻתָּר לְלָבְשׁוֹ. וְאִם הוֹצִיא מִן הַבֶּגֶד סָבִיב לְרֹאשׁוֹ אוֹ כְּנֶגֶד פָּנָיו כְּמוֹ אֹהֶל וְהָיָה מְהֻדָּק עַל רֹאשׁוֹ וְהָיְתָה הַשָּׂפָה שֶׁהוֹצִיאָהּ קָשָׁה בְּיוֹתֵר כְּמוֹ גַּג אָסוּר מִפְּנֵי שֶׁהוּא עוֹשֶׂה אֹהֶל עֲרַאי:","הַנּוֹטֶה פָּרֹכֶת וְכַיּוֹצֵא בָּהּ צָרִיךְ לְהִזָּהֵר שֶׁלֹּא יַעֲשֶׂה אֹהֶל בְּשָׁעָה שֶׁנּוֹטֶה לְפִיכָךְ אִם הָיְתָה פָּרֹכֶת גְּדוֹלָה תּוֹלִין אוֹתָהּ שְׁנַיִם אֲבָל אֶחָד אָסוּר. וְאִם הָיְתָה כִּלָּה שֶׁיֵּשׁ לָהּ גַּג אֵין מוֹתְחִין אוֹתָהּ וַאֲפִלּוּ עֲשָׂרָה שֶׁאִי אֶפְשָׁר שֶׁלֹּא תִּגְבַּהּ מְעַט מֵעַל הָאָרֶץ וְתֵעָשֶׂה אֹהֶל עֲרַאי:","בֶּגֶד שֶׁמְּכַסֶּה בּוֹ פִּי הֶחָבִית לֹא יְכַסֶּה בּוֹ אֶת כֻּלָּהּ מִפְּנֵי שֶׁנַּעֲשָׂה אֹהֶל אֲבָל מְכַסֶּה הוּא מִקְצָת פִּיהָ. הַמְסַנֵּן בִּכְפִיפָה מִצְרִית לֹא יַגְבִּיהַּ קַרְקָעִית הַכְּפִיפָה מִן הַכְּלִי טֶפַח כְּדֵי שֶׁלֹּא יַעֲשֶׂה אֹהֶל עֲרַאי בְּשַׁבָּת:"],"Mishneh Torah, Sabbath 6":["אָסוּר לוֹמַר לְנָכְרִי לַעֲשׂוֹת לָנוּ מְלָאכָה בְּשַׁבָּת אַף עַל פִּי שֶׁאֵינוֹ מְצֻוֶּה עַל הַשַּׁבָּת. וְאַף עַל פִּי שֶׁאָמַר לוֹ מִקֹּדֶם הַשַּׁבָּת. וְאַף עַל פִּי שֶׁאֵינוֹ צָרִיךְ לְאוֹתָהּ מְלָאכָה אֶלָּא לְאַחַר הַשַּׁבָּת. וְדָבָר זֶה אָסוּר מִדִּבְרֵי סוֹפְרִים כְּדֵי שֶׁלֹּא תִּהְיֶה שַׁבָּת קַלָּה בְּעֵינֵיהֶן וְיָבוֹאוּ לַעֲשׂוֹת בְּעַצְמָן:","נָכְרִי שֶׁעָשָׂה מְלָאכָה מֵעַצְמוֹ בְּשַׁבָּת אִם בִּשְׁבִיל יִשְׂרָאֵל עָשָׂה אוֹתָהּ אָסוּר לֵהָנוֹת בְּאוֹתָהּ מְלָאכָה עַד מוֹצָאֵי שַׁבָּת וְיַמְתִּין בִּכְדֵי שֶׁתֵּעָשֶׂה. וְהוּא שֶׁלֹּא יְהֵא הַדָּבָר בְּפַרְהֶסְיָא עַד שֶׁיֵּדְעוּ בּוֹ רַבִּים שֶׁדָּבָר זֶה בִּשְׁבִיל פְּלוֹנִי הוּא נַעֲשָׂה בְּשַׁבָּת. וְאִם בִּשְׁבִיל עַצְמוֹ בִּלְבַד עָשָׂה מֻתָּר לֵהָנוֹת בָּהּ בְּשַׁבָּת:","כֵּיצַד. נָכְרִי שֶׁהִדְלִיק אֶת הַנֵּר מִשְׁתַּמֵּשׁ לְאוֹרוֹ יִשְׂרָאֵל וְאִם בִּשְׁבִיל יִשְׂרָאֵל אָסוּר. עָשָׂה נָכְרִי כֶּבֶשׁ לֵירֵד בּוֹ מִן הַסְּפִינָה יֵרֵד אַחֲרָיו יִשְׂרָאֵל וְאִם בִּשְׁבִיל יִשְׂרָאֵל אָסוּר. מִלֵּא מַיִם לְהַשְׁקוֹת בְּהֶמְתּוֹ מַשְׁקֶה אַחֲרָיו יִשְׂרָאֵל וְאִם בִּשְׁבִיל יִשְׂרָאֵל אָסוּר. לִקֵּט עֲשָׂבִים לְהַאֲכִיל לִבְהֶמְתּוֹ מַנִּיחַ יִשְׂרָאֵל בְּהֶמְתּוֹ לֶאֱכל מֵהֶן. וְהוּא שֶׁלֹּא יְהֵא אוֹתוֹ הַנָּכְרִי מַכִּיר לְאוֹתוֹ יִשְׂרָאֵל שֶׁמָּא יַרְבֶּה בִּמְלַאכְתּוֹ בִּשְׁבִילוֹ וְנִמְצָא עוֹשֶׂה בִּשְׁבִיל יִשְׂרָאֵל. וְכֵן כָּל דָּבָר שֶׁאֶפְשָׁר לְהַרְבּוֹת בּוֹ לֹא יֵהָנֶה בּוֹ בְּשַׁבָּת אֶלָּא אִם כֵּן אֵינוֹ מַכִּירוֹ:","אֲבָל דָּבָר שֶׁאֵין בּוֹ לְהַרְבּוֹת וּלְמַעֵט כְּגוֹן נֵר וְכֶבֶשׁ הוֹאִיל וְעָשָׂה בִּשְׁבִיל עַצְמוֹ נֶהֱנֶה אַחֲרָיו יִשְׂרָאֵל בְּשַׁבָּת וְאַף עַל פִּי שֶׁהוּא מַכִּירוֹ. נֵר הַדָּלוּק בִּמְסִבָּה בְּשַׁבָּת. אִם רֹב יִשְׂרָאֵל אָסוּר לְהִשְׁתַּמֵּשׁ לְאוֹרָהּ שֶׁהַמַּדְלִיק עַל דַּעַת הָרֹב מַדְלִיק. וְאִם רֹב נָכְרִים מֻתָּר לְהִשְׁתַּמֵּשׁ לְאוֹרָהּ. מֶחֱצָה לְמֶחֱצָה אָסוּר. נָפְלָה דְּלֵקָה בְּשַׁבָּת וּבָא נָכְרִי לְכַבּוֹת אֵין אוֹמְרִין לוֹ כַּבֵּה וְאַל תְּכַבֶּה מִפְּנֵי שֶׁאֵין שְׁבִיתָתוֹ עָלֵינוּ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","מֵת שֶׁעָשׂוּ לוֹ נָכְרִים אָרוֹן וְחָפְרוּ לוֹ קֶבֶר בְּשַׁבָּת אוֹ הֵבִיאוּ לוֹ חֲלִילִין לִסְפֹּד בָּהֶן. אִם בְּצִנְעָה יַמְתִּין בִּכְדֵי שֶׁיֵּעָשׂוּ לְמוֹצָאֵי שַׁבָּת וְיִקָּבֵר בּוֹ. וְאִם הָיָה הַקֶּבֶר בִּסְרַטְיָא גְּדוֹלָה וְהָאָרוֹן עַל גַּבָּיו וְכָל הָעוֹבְרִין וְהַשָּׁבִין אוֹמְרִים שֶׁזֶּה שֶׁהַנָּכְרִים עוֹשִׂין עַכְשָׁו בְּשַׁבָּת לִפְלוֹנִי הוּא. הֲרֵי זֶה לֹא יִקָּבֵר בּוֹ אוֹתוֹ יִשְׂרָאֵל עוֹלָמִית. מִפְּנֵי שֶׁהוּא בְּפַרְהֶסְיָא. וּמֻתָּר לִקְבֹּר בּוֹ יִשְׂרָאֵל אַחֵר וְהוּא שֶׁיַּמְתִּין בִּכְדֵי שֶׁיֵּעָשֶׂה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","נָכְרִי שֶׁהֵבִיא חֲלִילִין בְּשַׁבָּת לְמֵת אַף עַל פִּי שֶׁהֱבִיאָן מִצַּד הַחוֹמָה יַמְתִּין לְמוֹצָאֵי שַׁבָּת בִּכְדֵי שֶׁיָּבוֹא מִמָּקוֹם קָרוֹב וְאַחַר כָּךְ יִסְפְּדוּ בָּהֶן. שֶׁמָּא בַּלַּיְלָה הֱבִיאוּם מִמָּקוֹם אַחֵר עַד הַחוֹמָה וּבַבֹּקֶר נִכְנְסוּ בָּהֶן. וְאִם יָדַע בְּוַדַּאי שֶׁמִּמָּקוֹם פְּלוֹנִי הֱבִיאוּם בְּשַׁבָּת יַמְתִּין בִּכְדֵי שֶׁיָּבוֹאוּ מֵאוֹתוֹ מָקוֹם אַחַר הַשַּׁבָּת. וְהוּא שֶׁלֹּא יְהֵא הַדָּבָר בִּסְרַטְיָא גְּדוֹלָה כְּמוֹ שֶׁאָמַרְנוּ:","עִיר שֶׁיִּשְׂרָאֵל וְנָכְרִים דָּרִין בְּתוֹכָהּ וְהָיְתָה בָּהּ מֶרְחָץ הַמַּרְחֶצֶת בְּשַׁבָּת. אִם רֹב נָכְרִים מֻתָּר לִרְחֹץ בָּהּ לְמוֹצָאֵי שַׁבָּת מִיָּד. וְאִם רֹב יִשְׂרָאֵל יַמְתִּין בִּכְדֵי שֶׁיֵּחַמּוּ חַמִּין. שֶׁבִּשְׁבִיל הָרֹב הוּחַמּוּ. מֶחֱצָה לְמֶחֱצָה יַמְתִּין בִּכְדֵי שֶׁיֵּחַמּוּ חַמִּין. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","יִשְׂרָאֵל שֶׁאָמַר לְנָכְרִי לַעֲשׂוֹת לוֹ מְלָאכָה זוֹ בְּשַׁבָּת אַף עַל פִּי שֶׁעָבַר וּמַכִּין אוֹתוֹ מַכַּת מַרְדּוּת מֻתָּר לוֹ לֵהָנוֹת בְּאוֹתָהּ מְלָאכָה לָעֶרֶב אַחַר שֶׁיַּמְתִּין בִּכְדֵי שֶׁתֵּעָשֶׂה. וְלֹא אָסְרוּ בְּכָל מָקוֹם עַד שֶׁיַּמְתִּין בִּכְדֵי שֶׁיֵּעָשׂוּ אֶלָּא מִפְּנֵי דָּבָר זֶה. שֶׁאִם תֹּאמַר יְהֵא מֻתָּר מִיָּד שֶׁמָּא יֹאמַר לְנָכְרִי לַעֲשׂוֹת לוֹ וְיִמְצָא הַדָּבָר מוּכָן מִיָּד. וְכֵיוָן שֶׁאָסְרוּ עַד שֶׁיַּמְתִּין בִּכְדֵי שֶׁיֵּעָשׂוּ לֹא יֹאמַר לְנָכְרִי לַעֲשׂוֹת לוֹ שֶׁהֲרֵי אֵינוֹ מִשְׂתַּכֵּר כְּלוּם מִפְּנֵי שֶׁהוּא מִתְעַכֵּב לָעֶרֶב בִּכְדֵי שֶׁיֵּעָשֶׂה דָּבָר זֶה שֶׁנַּעֲשָׂה בְּשַׁבָּת:","דָּבָר שֶׁאֵינוֹ מְלָאכָה וְאֵין אָסוּר לַעֲשׂוֹתוֹ בְּשַׁבָּת אֶלָּא מִשּׁוּם שְׁבוּת מֻתָּר לְיִשְׂרָאֵל לוֹמַר לְנָכְרִי לַעֲשׂוֹתוֹ בְּשַׁבָּת. וְהוּא שֶׁיִּהְיֶה שָׁם מִקְצָת חֹלִי אוֹ יִהְיֶה צָרִיךְ לַדָּבָר צֹרֶךְ הַרְבֵּה אוֹ מִפְּנֵי מִצְוָה:","כֵּיצַד. אוֹמֵר יִשְׂרָאֵל לְנָכְרִי בְּשַׁבָּת לַעֲלוֹת בָּאִילָן אוֹ לָשׁוּט עַל פְּנֵי הַמַּיִם כְּדֵי לְהָבִיא לוֹ שׁוֹפָר. אוֹ סַכִּין לְמִילָה. אוֹ מֵבִיא לוֹ מֵחָצֵר לְחָצֵר שֶׁאֵין עֵרוּב בֵּינֵיהֶן מַיִם חַמִּין לְהַרְחִיץ בָּהֶם קָטָן וּמִצְטַעֵר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַלּוֹקֵחַ בַּיִת בְּאֶרֶץ יִשְׂרָאֵל מִן הַנָּכְרִי מֻתָּר לוֹ לוֹמַר לַנָּכְרִי לִכְתֹּב לוֹ שְׁטָר בְּשַׁבָּת. שֶׁאֲמִירָה לְנָכְרִי בְּשַׁבָּת אֲסוּרָה מִדִּבְרֵיהֶם וּמִשּׁוּם יִשּׁוּב אֶרֶץ יִשְׂרָאֵל לֹא גָּזְרוּ בְּדָבָר זֶה. וְכֵן הַלּוֹקֵחַ בַּיִת מֵהֶם בְּסוּרְיָא, שֶׁסּוּרְיָא כְּאֶרֶץ יִשְׂרָאֵל לְדָבָר זֶה:","פּוֹסֵק אָדָם עִם הַנָּכְרִי עַל הַמְּלָאכָה וְקוֹצֵץ דָּמִים וְהַנָּכְרִי עוֹשֶׂה לְעַצְמוֹ וְאַף עַל פִּי שֶׁהוּא עוֹשֶׂה בְּשַׁבָּת מֻתָּר. וְכֵן הַשּׂוֹכֵר אֶת הַנָּכְרִי לְיָמִים הַרְבֵּה מֻתָּר אַף עַל פִּי שֶׁהוּא עוֹשֶׂה בְּשַׁבָּת. כֵּיצַד. כְּגוֹן שֶׁשָּׂכַר הַנָּכְרִי לְשָׁנָה אוֹ לִשְׁתַּיִם שֶׁיִּכְתֹּב לוֹ אוֹ שֶׁיֶּאֱרֹג לוֹ. הֲרֵי זֶה כּוֹתֵב וְאוֹרֵג בְּשַׁבָּת וּמֻתָּר כְּאִלּוּ קָצַץ עִמּוֹ שֶׁיִּכְתֹּב לוֹ סֵפֶר אוֹ שֶׁיֶּאֱרֹג לוֹ בֶּגֶד שֶׁהוּא עוֹשֶׂה בְּכָל עֵת שֶׁיִּרְצֶה. וְהוּא שֶׁלֹּא יַחְשֹׁב עִמּוֹ יוֹם יוֹם:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּצִנְעָה שֶׁאֵין מַכִּירִים הַכּל שֶׁזּוֹ הַמְּלָאכָה הַנַּעֲשֵׂית בְּשַׁבָּת שֶׁל יִשְׂרָאֵל הִיא. אֲבָל אִם הָיְתָה יְדוּעָה וּגְלוּיָה וּמְפֻרְסֶמֶת אֲסוּרָה שֶׁהָרוֹאֶה אֶת הַנָּכְרִי עוֹסֵק אֵינוֹ יוֹדֵעַ שֶׁקָּצַץ וְאוֹמֵר שֶׁפְּלוֹנִי שָׂכַר הַנָּכְרִי לַעֲשׂוֹת לוֹ מְלָאכָה בְּשַׁבָּת:","לְפִיכָךְ הַפּוֹסֵק עִם הַנָּכְרִי לִבְנוֹת לוֹ חֲצֵרוֹ אוֹ כָּתְלוֹ אוֹ לִקְצֹר אֶת שָׂדֵהוּ אוֹ שֶׁשְּׂכָרוֹ שָׁנָה אוֹ שְׁתַּיִם לִבְנוֹת לוֹ חָצֵר אוֹ לִטַּע לוֹ כֶּרֶם. אִם הָיְתָה הַמְּלָאכָה בַּמְּדִינָה אוֹ בְּתוֹךְ הַתְּחוּם אָסוּר לוֹ לַהֲנִיחָן לַעֲשׂוֹת בְּשַׁבָּת מִפְּנֵי הָרוֹאִים שֶׁאֵינָם יוֹדְעִים שֶׁפָּסַק. וְאִם הָיְתָה הַמְּלָאכָה חוּץ לַתְּחוּם מֻתָּר שֶׁאֵין שָׁם יִשְׂרָאֵל שֶׁיִּרְאֶה אֶת הַפּוֹעֲלִין כְּשֶׁהֵן עוֹשִׂין בְּשַׁבָּת:","וְכֵן מֻתָּר לְאָדָם לְהַשְׂכִּיר כַּרְמוֹ אוֹ שָׂדֵהוּ לְנָכְרִי אַף עַל פִּי שֶׁהוּא זוֹרְעָן וְנוֹטְעָן בְּשַׁבָּת. שֶׁהָרוֹאֶה יוֹדֵעַ שֶׁשְּׂכוּרִין הֵן אוֹ בַּאֲרִיסוּת נָתַן לָהֶן. וְדָבָר שֶׁשֵּׁם יִשְׂרָאֵל בְּעָלָיו קָרוּי עָלָיו וְאֵין דֶּרֶךְ רֹב אַנְשֵׁי אוֹתוֹ הַמָּקוֹם לְהַשְׂכִּירוֹ אוֹ לִתְּנוֹ בַּאֲרִיסוּת אָסוּר לְהַשְׂכִּירוֹ לְנָכְרִי. מִפְּנֵי שֶׁהַנָּכְרִי עוֹשֶׂה בְּאוֹתוֹ הַמָּקוֹם מְלָאכָה בְּשַׁבָּת וְהוּא נִקְרָא עַל שֵׁם הַיִּשְׂרָאֵל בְּעָלָיו:","מֻתָּר לְהַשְׁאִיל כֵּלִים וּלְהַשְׂכִּירָן לְנָכְרִי וְאַף עַל פִּי שֶׁהוּא עוֹשֶׂה בָּהֶן מְלָאכָה בְּשַׁבָּת מִפְּנֵי שֶׁאֵין אָנוּ מְצֻוִּים עַל שְׁבִיתַת הַכֵּלִים. אֲבָל בְּהֶמְתּוֹ וְעַבְדּוֹ אָסוּר מִפְּנֵי שֶׁאָנוּ מְצֻוִּין עַל שְׁבִיתַת בְּהֵמָה וְעֶבֶד:","הַמִּשְׁתַּתֵּף עִם הַנָּכְרִי בִּמְלָאכָה אוֹ בִּסְחוֹרָה אוֹ בַּחֲנוּת. אִם הִתְנוּ בַּתְּחִלָּה שֶׁיִּהְיֶה שְׂכַר הַשַּׁבָּת לַנָּכְרִי לְבַדּוֹ אִם מְעַט אִם הַרְבֵּה וּשְׂכַר יוֹם אַחֵר כְּנֶגֶד יוֹם הַשַּׁבָּת לְיִשְׂרָאֵל לְבַדּוֹ מֻתָּר. וְאִם לֹא הִתְנוּ בַּתְּחִלָּה. כְּשֶׁיָּבוֹאוּ לַחֲלֹק נוֹטֵל הַנָּכְרִי שְׂכַר הַשַּׁבָּתוֹת כֻּלָּן לְבַדּוֹ וְהַשְּׁאָר חוֹלְקִין אוֹתוֹ. וְאֵינוֹ מוֹסִיף לוֹ כְּלוּם כְּנֶגֶד יוֹם הַשַּׁבָּת אֶלָּא אִם כֵּן הִתְנוּ בַּתְּחִלָּה. וְכֵן אִם קִבְּלוּ שָׂדֶה בְּשֻׁתָּפוּת דִּין אֶחָד הוּא:","וְאִם לֹא הִתְּנוּ וּבָאוּ לַחֲלֹק הַשָּׂכָר וְלֹא הָיָה שְׂכַר שַׁבָּת יָדוּעַ יֵרָאֶה לִי שֶׁהַנָּכְרִי נוֹטֵל לְבַדּוֹ שְׁבִיעִית הַשָּׂכָר וְהַשְּׁאָר חוֹלְקִין. הַנּוֹתֵן מָעוֹת לְנָכְרִי לְהִתְעַסֵּק בָּהֶן אַף עַל פִּי שֶׁהַנָּכְרִי נוֹשֵׂא וְנוֹתֵן בְּשַׁבָּת חוֹלֵק עִמּוֹ בַּשָּׂכָר בְּשָׁוֶה וְכֵן הוֹרוּ כָּל הַגְּאוֹנִים:","לֹא יִתֵּן אָדָם בְּעֶרֶב שַׁבָּת כֵּלִים לְאֻמָּן נָכְרִי לַעֲשׂוֹתָן אַף עַל פִּי שֶׁפָּסַק עִמּוֹ. אֶלָּא בִּכְדֵי שֶׁיֵּצֵא בָּהֶן מִבֵּיתוֹ קֹדֶם שֶׁחֲשֵׁכָה. וְכֵן לֹא יִמְכֹּר אָדָם חֲפָצָיו לְנָכְרִי וְלֹא יַשְׁאִילֶנּוּ וְלֹא יַלְוֶנּוּ וְלֹא יְמַשְׁכְּנֶנּוּ וְלֹא יִתֵּן לוֹ בְּמַתָּנָה אֶלָּא בִּכְדֵי שֶׁיֵּצֵא בְּאוֹתוֹ חֵפֶץ מִפֶּתַח בֵּיתוֹ קֹדֶם הַשַּׁבָּת. שֶׁכָּל זְמַן שֶׁהוּא בְּבֵיתוֹ אֵין אָדָם יוֹדֵעַ אֵימָתַי נָתַן לוֹ וּכְשֶׁיֵּצֵא הַנָּכְרִי מִבֵּיתוֹ בְּשַׁבָּת וְחֵפֶץ יִשְׂרָאֵל בְּיָדוֹ יֵרָאֶה כְּמִי שֶׁהִלְּוָהוּ לַנָּכְרִי אוֹ מִשְׁכְּנוֹ אוֹ פָּסַק עִמּוֹ אוֹ מָכַר לוֹ בְּשַׁבָּת:","הַנּוֹתֵן אִגֶּרֶת לְנָכְרִי לְהוֹלִיכָהּ לְעִיר אַחֶרֶת אִם קָצַץ עִמּוֹ שְׂכַר הוֹלָכָה מֻתָּר. וַאֲפִלּוּ נְתָנָהּ לוֹ עֶרֶב שַׁבָּת עִם חֲשֵׁכָה. וְהוּא שֶׁיֵּצֵא בָּהּ מִפֶּתַח בֵּיתוֹ קֹדֶם הַשַּׁבָּת. וְאִם לֹא קָצַץ אִם יֵשׁ בַּמְּדִינָה אָדָם קָבוּעַ שֶׁהוּא מְקַבֵּץ הָאִגְּרוֹת וְשׁוֹלֵחַ אוֹתָם לְכָל מְדִינָה וּמְדִינָה עִם שְׁלוּחָיו מֻתָּר לִתֵּן לַנָּכְרִי הָאִגֶּרֶת. וְהוּא שֶׁיִּהְיֶה שְׁהוּת בַּיּוֹם כְּדֵי שֶׁיַּגִּיעַ לַבַּיִת הַסָּמוּךְ לַחוֹמָה קֹדֶם הַשַּׁבָּת. שֶׁמָּא זֶה שֶׁמְּקַבֵּל הָאִגְּרוֹת וְשׁוֹלְחָן בֵּיתוֹ סָמוּךְ לַחוֹמָה הוּא. וְאִם אֵין שָׁם אָדָם קָבוּעַ לְכָךְ אֶלָּא הַנָּכְרִי שֶׁנּוֹתְנִין לוֹ הָאִגֶּרֶת הוּא שֶׁמּוֹלִיכָהּ לְעִיר אַחֶרֶת אָסוּר לִשְׁלֹחַ בְּיַד נָכְרִי הָאִגֶּרֶת לְעוֹלָם אֶלָּא אִם כֵּן קָצַץ לוֹ דָּמִים:","נָכְרִי שֶׁהֵבִיא חֲפָצָיו בְּשַׁבָּת וְהִכְנִיסָן לְבֵית יִשְׂרָאֵל מֻתָּר. וַאֲפִלּוּ אָמַר לוֹ הַנִּיחָן בְּזָוִית זוֹ הֲרֵי זֶה מֻתָּר. וּמְזַמְּנִין אֶת הַנָּכְרִי בְּשַׁבָּת וְנוֹתְנִין לְפָנָיו מְזוֹנוֹת לְאָכְלָן. וְאִם נְטָלָן וְיָצָא אֵין נִזְקָקִין לוֹ מִפְּנֵי שֶׁאֵין שְׁבִיתָתוֹ עָלֵינוּ. וְכֵן נוֹתְנִין מְזוֹנוֹת לִפְנֵי הַכֶּלֶב בֶּחָצֵר וְאִם נְטָלָן וְיָצָא אֵין נִזְקָקִין לוֹ:","מִי שֶׁהָיָה בָּא בַּדֶּרֶךְ וְקָדַשׁ עָלָיו הַיּוֹם וְהָיוּ עִמּוֹ מָעוֹת נוֹתֵן כִּיסוֹ לְנָכְרִי לְהוֹלִיכוֹ לוֹ וּלְמוֹצָאֵי שַׁבָּת לוֹקְחוֹ מִמֶּנּוּ. וְאַף עַל פִּי שֶׁלֹּא נָתַן לוֹ שָׂכָר עַל זֶה. וְאַף עַל פִּי שֶׁנְּתָנוֹ לוֹ מִשֶּׁחֲשֵׁכָה מֻתָּר מִפְּנֵי שֶׁאָדָם בָּהוּל עַל מָמוֹנוֹ וְאִי אֶפְשָׁר שֶׁיַּשְׁלִיכֶנּוּ. וְאִם לֹא תַּתִּיר לוֹ דָּבָר זֶה שֶׁאֵין אִסּוּרוֹ אֶלָּא מִדִּבְרֵי סוֹפְרִים יָבוֹא לַהֲבִיאוֹ בְּיָדוֹ וְעוֹבֵר עַל מְלָאכָה שֶׁל תּוֹרָה. בַּמֶּה דְּבָרִים אֲמוּרִים בְּכִיסוֹ אֲבָל מְצִיאָה לֹא יִתֵּן לַנָּכְרִי אֶלָּא מוֹלִיכָהּ בְּפָחוֹת פָּחוֹת מֵאַרְבַּע אַמּוֹת:","יִשְׂרָאֵל שֶׁעָשָׂה מְלָאכָה בְּשַׁבָּת אִם עָבַר וְעָשָׂה בְּזָדוֹן אָסוּר לוֹ לֵהָנוֹת בְּאוֹתָהּ מְלָאכָה לְעוֹלָם. וּשְׁאָר יִשְׂרָאֵל מֻתָּר לָהֶם לֵהָנוֹת בָּהּ לְמוֹצָאֵי שַׁבָּת מִיָּד שֶׁנֶּאֱמַר (שמות לא יד) \"וּשְׁמַרְתֶּם אֶת הַשַּׁבָּת כִּי קֹדֶשׁ הִיא\", הִיא קֹדֶשׁ וְאֵין מַעֲשֶׂיהָ קֹדֶשׁ. כֵּיצַד. יִשְׂרָאֵל שֶׁבִּשֵּׁל בְּשַׁבָּת בְּמֵזִיד. לְמוֹצָאֵי שַׁבָּת יֵאָכֵל לַאֲחֵרִים אֲבָל לוֹ לֹא יֵאָכֵל עוֹלָמִית. וְאִם בִּשֵּׁל בִּשְׁגָגָה לְמוֹצָאֵי שַׁבָּת יֹאכַל בֵּין הוּא בֵּין אֲחֵרִים מִיָּד. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","פֵּרוֹת שֶׁיָּצְאוּ חוּץ לַתְּחוּם וְחָזְרוּ. בְּשׁוֹגֵג יֵאָכְלוּ בְּשַׁבָּת שֶׁהֲרֵי לֹא נַעֲשָׂה בְּגוּפָן מַעֲשֶׂה וְלֹא נִשְׁתַּנּוּ. בְּמֵזִיד לֹא יֵאָכְלוּ עַד מוֹצָאֵי שַׁבָּת:","הַשּׂוֹכֵר אֶת הַפּוֹעֵל לִשְׁמֹר לוֹ אֶת הַפָּרָה וְאֶת הַתִּינוֹק לֹא יִתֵּן לוֹ שְׂכָרוֹ שֶׁל שַׁבָּת. לְפִיכָךְ אֵין אַחֲרָיוּת שַׁבָּת עָלָיו. וְאִם הָיָה הַשָּׂכִיר שְׂכִיר שַׁבָּת אוֹ שְׂכִיר שָׁנָה נוֹתֵן לוֹ שְׂכָרוֹ מָשְׁלָם. לְפִיכָךְ אַחֲרָיוּת שַׁבָּת עָלָיו. וְלֹא יֹאמַר לוֹ תֵּן לִי שְׂכָרִי שֶׁל שַׁבָּת אֶלָּא אוֹמֵר לוֹ תֵּן לִי שְׂכָרִי שֶׁל שָׁנָה אוֹ שֶׁל עֲשָׂרָה יָמִים:"],"Mishneh Torah, Sabbatical Year and the Jubilee 5":["פֵּרוֹת שְׁבִיעִית נִתְּנוּ לַאֲכִילָה וְלִשְׁתִיָּה וּלְסִיכָה וּלְהַדְלָקַת הַנֵּר וְלִצְבִיעָה. מִפִּי הַשְּׁמוּעָה לָמְדוּ (ויקרא כה ז) \"תִּהְיֶה\" אַף לְהַדְלָקַת נֵר וְלִצְבֹּעַ בָּהּ צֶבַע:","לַאֲכִילָה וְלִשְׁתִיָּה כֵּיצַד. לֶאֱכֹל דָּבָר שֶׁדַּרְכּוֹ לֶאֱכֹל. וְלִשְׁתּוֹת דָּבָר שֶׁדַּרְכּוֹ לִשְׁתּוֹת. כְּדִין תְּרוּמָה וּמַעֲשֵׂר שֵׁנִי:","וְלֹא יְשַׁנֶּה פֵּרוֹת מִבְּרִיָּתָן כְּדֶרֶךְ שֶׁאֵינוֹ מְשַׁנֶּה בִּתְרוּמָה וּמַעֲשֵׂר שֵׁנִי. דָּבָר שֶׁדַּרְכּוֹ לֶאֱכֹל חַי לֹא יֹאכְלֶנּוּ מְבֻשָּׁל. וְדָבָר שֶׁדַּרְכּוֹ לְהֵאָכֵל מְבֻשָּׁל אֵין אוֹכְלִין אוֹתוֹ חַי. לְפִיכָךְ אֵין שׁוֹלְקִין אָכֳלֵי בְּהֵמָה וְאֵינוֹ מְטַפֵּל לֶאֱכֹל תַּבְשִׁיל שֶׁנִּפְסַד וְהַפַּת שֶׁעִפְּשָׁה כְּדֶרֶךְ שֶׁאֵינוֹ אוֹכֵל בִּתְרוּמָה וּמַעֲשֵׂר:","וְאֵין מְבַשְּׁלִין יָרָק שֶׁל שְׁבִיעִית בְּשֶׁמֶן תְּרוּמָה שֶׁלֹּא יְבִיאֶנּוּ לִידֵי פְּסוּל. וְאִם בִּשֵּׁל מְעַט וַאֲכָלוֹ מִיָּד מֻתָּר שֶׁהֲרֵי לֹא הִנִּיחָן כְּדֵי לָבוֹא לִידֵי פְּסוּל:","פֵּרוֹת הַמְיֻחָדִין לְמַאֲכַל אָדָם אֵין מַאֲכִילִין אוֹתָן לִבְהֵמָה לְחַיָּה וּלְעוֹפוֹת. הָלְכָה הַבְּהֵמָה מֵאֵלֶיהָ לְתַחַת הַתְּאֵנָה וְאָכְלָה אֵין מְחַיְּבִין אוֹתוֹ לְהַחְזִירָהּ שֶׁנֶּאֱמַר (ויקרא כה ז) \"וְלִבְהֶמְתְּךָ וְלַחַיָּה אֲשֶׁר בְּאַרְצֶךָ תִּהְיֶה כָל תְּבוּאָתָהּ לֶאֱכֹל\":","לְסִיכָה כֵּיצַד. לָסוּךְ דָּבָר שֶׁדַּרְכּוֹ לָסוּךְ. לֹא יָסוּךְ יַיִן וְחֹמֶץ אֲבָל סָךְ הוּא אֶת הַשֶּׁמֶן. וְלֹא יְפַטֵּם אֶת הַשֶּׁמֶן. וְלֹא יָסוּךְ בַּמֶּרְחָץ אֲבָל סָךְ הוּא מִבַּחוּץ וְנִכְנָס:","שֶׁמֶן שֶׁל שְׁבִיעִית אֵין חוֹסְמִין בּוֹ תַנּוּר וְכִירַיִם. וְאֵין סָכִין בּוֹ מִנְעָל וְסַנְדָּל. וְאֵין סָכִין אוֹתוֹ בְּיָדַיִם טְמֵאוֹת. נָפַל עַל בְּשָׂרוֹ מְשַׁפְשְׁפוֹ בְּיָדַיִם טְמֵאוֹת. וְלֹא יָסוּךְ רַגְלוֹ בְּתוֹךְ הַמִּנְעָל. אֲבָל סָךְ הוּא רַגְלוֹ וְלוֹבֵשׁ הַמִּנְעָל. וְסָךְ גּוּפוֹ וּמִתְעַגֵּל עַל גַּבֵּי קַטַבְלִיָא:","לְהַדְלָקַת הַנֵּר כֵּיצַד. שֶׁמַּדְלִיק אֶת הַנֵּר בְּשֶׁמֶן שְׁבִיעִית עַצְמוֹ. מְכָרוֹ וְלָקַח בּוֹ שֶׁמֶן אַחֵר אוֹ שֶׁהֶחְלִיף שֶׁמֶן בְּשֶׁמֶן שְׁנֵיהֶם אֲסוּרִים בְּהַדְלָקָה. שֶׁאֵין מַדְלִיקִין בִּדְמֵי שְׁבִיעִית. וְלֹא יִתֵּן הַשֶּׁמֶן לְתוֹךְ הַמְּדוּרָה אֶלָּא מַדְלִיקוֹ בְּנֵר:","לִצְבִיעָה כֵּיצַד. דְּבָרִים שֶׁדַּרְכָּן לִצְבֹּעַ בָּהֶן אַף עַל פִּי שֶׁהֵן מַאַכְלֵי אָדָם צוֹבְעִין בָּהֶן לְאָדָם. אֲבָל אֵין צוֹבְעִין לִבְהֵמָה מִפֵּרוֹת שְׁבִיעִית אֲפִלּוּ מַאַכְלֵי בְּהֵמָה. שֶׁאֵין קְדֻשַּׁת שְׁבִיעִית חָלָה עַל צִבְעֵי בְּהֵמָה:","מִינֵי כִּבּוּסִים כְּגוֹן בֹּרִית וְאָהָל קְדֻשַּׁת שְׁבִיעִית חָלָה עֲלֵיהֶן וּמְכַבְּסִין בָּהֶן שֶׁנֶּאֱמַר (ויקרא כה ו) \"וְהָיְתָה שַׁבַּת הָאָרֶץ לָכֶם\" לְכָל צָרְכֵיכֶם. אֲבָל אֵין מְכַבְּסִין בְּפֵרוֹת שְׁבִיעִית וְאֵין עוֹשִׂין מֵהֶם מְלוּגְמָא שֶׁנֶּאֱמַר וְהָיְתָה שַׁבַּת הָאָרֶץ לָכֶם לְאָכְלָה וְלֹא לִמְלוּגְמָא וְלֹא לְזִלּוּף וְלֹא לְהָקִיא וְלֹא לְמִשְׁרָה וְלֹא לִכְבִיסָה:","כְּלָל גָּדוֹל אָמְרוּ בְּפֵרוֹת שְׁבִיעִית. כָּל שֶׁהוּא מְיֻחָד לְמַאֲכַל אָדָם כְּגוֹן חִטִּים תְּאֵנִים וַעֲנָבִים וְכַיּוֹצֵא בָּהֶן אֵין עוֹשִׂין מִמֶּנּוּ מְלוּגְמָא אוֹ רְטִיָּה וְכַיּוֹצֵא בּוֹ אֲפִלּוּ לְאָדָם שֶׁנֶּאֱמַר (ויקרא כה ו) \"לָכֶם לְאָכְלָה\" כָּל שֶׁהוּא מְיֻחָד לָכֶם יִהְיֶה לְאָכְלָה וְלֹא לִרְפוּאָה. וְכָל שֶׁאֵינוֹ מְיֻחָד לְמַאֲכַל אָדָם כְּגוֹן קוֹצִין וְדַרְדָּרִין הָרַכִּים עוֹשִׂין מֵהֶן מְלוּגְמָא לְאָדָם אֲבָל לֹא לִבְהֵמָה. וְכָל שֶׁאֵינוֹ מְיֻחָד לֹא לָזֶה וְלֹא לָזֶה כְּגוֹן הַסְּאָה וְהָאֵזוֹב וְהַקּוֹרָנִית הֲרֵי הוּא תָּלוּי בְּמַחֲשַׁבְתּוֹ. חָשַׁב עָלָיו לְעֵצִים הֲרֵי הוּא כְּעֵצִים. לַאֲכִילָה הֲרֵי הוּא כְּפֵרוֹת. לְמַאֲכַל אָדָם וּלְמַאֲכַל בְּהֵמָה נוֹתְנִין עָלָיו חֻמְרֵי מַאֲכַל אָדָם, שֶׁאֵין עוֹשִׂין מֵהֶן מְלוּגְמָא. וְחֻמְרֵי מַאֲכַל בְּהֵמָה שֶׁאֵין שׁוֹלְקִין אוֹתוֹ:","מֻתָּר לִמְכֹּר אָכֳלֵי אָדָם וְאָכֳלֵי בְּהֵמָה וְלִקַּח בָּהֶם אָכֳלֵי אָדָם. אֲבָל אֵין מוֹכְרִין אָכֳלֵי בְּהֵמָה לִקַּח בָּהֶם אָכֳלֵי בְּהֵמָה אַחֶרֶת. וְאֵין צָרִיךְ לוֹמַר שֶׁאֵין מוֹכְרִין אָכֳלֵי אָדָם לִקַּח בָּהֶם אָכֳלֵי בְּהֵמָה. וְאִם לָקַח בָּהֶן אוֹ הֶחְלִיף בָּהֶן אָכֳלֵי אָדָם בְּאָכֳלֵי בְּהֵמָה הֲרֵי הֵן כְּאָכֳלֵי אָדָם שֶׁאֵין עוֹשִׂין מֵהֶן מְלוּגְמָא לָאָדָם:","פֵּרוֹת שְׁבִיעִית אֵין מוֹצִיאִין אוֹתָן מֵהָאָרֶץ לְחוּצָה לָאָרֶץ וַאֲפִלּוּ לְסוּרְיָא. וְאֵין מַאֲכִילִין אוֹתָן לֹא לְעַכּוּ\"ם וְלֹא לְשָׂכִיר. וְאִם הָיָה שְׂכִיר שַׁבָּת אוֹ שְׂכִיר שָׁנָה אוֹ שְׂכִיר חֹדֶשׁ אוֹ שֶׁקָּצַץ מְזוֹנוֹתָיו עָלָיו הֲרֵי הוּא כְּאַנְשֵׁי בֵּיתוֹ וּמַאֲכִילִין אוֹתוֹ. וּמַאֲכִילִין אֶת הָאַכְסַנְיָא פֵּרוֹת שְׁבִיעִית:","אֵין בֵּית דִּין פּוֹסְקִין לְאִשָּׁה פֵּרוֹת שְׁבִיעִית. מִפְּנֵי שֶׁזֶּה כִּמְשַׁלֵּם חוֹב מִפֵּרוֹת שְׁבִיעִית. אֲבָל נִזּוֹנֶת הִיא מִשֶּׁל בַּעְלָהּ:","אֵין אוֹסְפִין פֵּרוֹת שְׁבִיעִית כְּשֶׁהֵן בֹּסֶר שֶׁנֶּאֱמַר (ויקרא כה יב) \"תֹּאכְלוּ אֶת תְּבוּאָתָהּ\" אֵינָהּ נֶאֱכֶלֶת עַד שֶׁתֵּעָשֶׂה תְּבוּאָה. אֲבָל אוֹכֵל מֵהֶן מְעַט בַּשָּׂדֶה כְּשֶׁהֵם פַּגִּין כְּדֶרֶךְ שֶׁאוֹכֵל בִּשְׁאָר שְׁנֵי שָׁבוּעַ. וְלֹא יַכְנִיס לֶאֱכֹל בְּתוֹךְ בֵּיתוֹ עַד שֶׁיַּגִּיעוּ לְעוֹנַת הַמַּעַשְׂרוֹת:","וּמֵאֵימָתַי יִהְיֶה מֻתָּר לֶאֱכֹל פֵּרוֹת הָאִילָן בַּשָּׂדֶה בַּשְּׁבִיעִית. הַפַּגִּין שֶׁל תְּאֵנִים מִשֶּׁיַּזְרִיחוּ אוֹכֵל בָּהֶן פִּתּוֹ בַּשָּׂדֶה. וְכֵן כָּל כַּיּוֹצֵא בָּהֶן. הַבֹּסֶר מִשֶּׁיּוֹצִיא מַיִם וְאוֹכְלוֹ בַּשָּׂדֶה. וְכֵן כָּל כַּיּוֹצֵא בּוֹ. הַזֵּיתִים מִשֶּׁיִּכְנְסוּ סְאָה שֶׁל זֵיתִים רְבִיעִית שֶׁמֶן פּוֹצֵעַ וְאוֹכֵל בַּשָּׂדֶה. הִכְנִיסוּ חֲצִי לוֹג כּוֹתֵשׁ וְסָךְ בַּשָּׂדֶה. הִכְנִיס שְׁלִישׁ מֻתָּר לְהַכְנִיס לְבֵיתוֹ שֶׁהֲרֵי הִגִּיעוּ לְעוֹנַת הַמַּעַשְׂרוֹת:","מֻתָּר לָקֹץ אִילָנוֹת לְעֵצִים בַּשְּׁבִיעִית קֹדֶם שֶׁיִּהְיֶה בָּהֶן פְּרִי. אֲבָל מִשֶּׁיַּתְחִיל לַעֲשׂוֹת פְּרִי לֹא יָקֹץ אוֹתוֹ שֶׁהֲרֵי מַפְסִיד הָאֹכֶל וְנֶאֱמַר (ויקרא כה ו) \"לָכֶם לְאָכְלָה\" וְלֹא לְהֶפְסֵד. וְאִם הוֹצִיא פֵּרוֹת וְהִגִּיעוּ לְעוֹנַת הַמַּעַשְׂרוֹת מֻתָּר לָקֹץ אוֹתוֹ שֶׁהֲרֵי הוֹצִיא פֵּרוֹתָיו וּבָטֵל דִּין שְׁבִיעִית מִמֶּנּוּ:","וּמֵאֵימָתַי אֵין קוֹצְצִין הָאִילָן בַּשְּׁבִיעִית. הֶחָרוּבִין מִשֶּׁיְּשַׁלְשֵׁלוּ. וְהַגְּפָנִים מִשֶּׁיִּגָּרְעוּ. וְהַזֵּיתִים מִשֶּׁיָּנֵצּוּ. וּשְׁאָר כָּל הָאִילָנוֹת מִשֶּׁיּוֹצִיאוּ בֹּסֶר. וְאֵין קוֹצְצִין אֶת הַכָּפְנִיּוֹת בַּשְּׁבִיעִית מִפְּנֵי שֶׁהוּא הֶפְסֵד פְּרִי. וְאִם אֵין דַּרְכָּן לְהֵעָשׂוֹת תְּמָרִים אֶלָּא שִׁיצִין מֻתָּר לָקֹץ אוֹתָן כָּפְנִיּוֹת:","אֵין שׂוֹרְפִין תֶּבֶן וְקַשׁ שֶׁל שְׁבִיעִית מִפְּנֵי שֶׁהוּא רָאוּי לְמַאֲכַל בְּהֵמָה. אֲבָל מַסִּיקִין בְּגֶפֶת וּבְזַגִּין שֶׁל שְׁבִיעִית:","מֶרְחָץ שֶׁהֻסְּקָה בְּתֶבֶן וּבְקַשׁ שֶׁל שְׁבִיעִית מֻתָּר לִרְחֹץ בָּהּ בְּשָׂכָר. וְאִם אָדָם חָשׁוּב הוּא אָסוּר שֶׁמָּא יַסִּיקוּ בָּהּ דְּבָרִים אֲחֵרִים בִּשְׁבִילוֹ כְּדֵי שֶׁיִּהְיֶה רֵיחָהּ נוֹדֵף. וְנִמְצְאוּ מַפְסִידִין פֵּרוֹת שְׁבִיעִית:","הַקְּלִפִּין וְהַגַּרְעִינִין שֶׁמֻּתָּרִין בִּתְרוּמָה לְזָרִים אֵין קְדֻשַּׁת שְׁבִיעִית חָלָה עֲלֵיהֶם וַהֲרֵי הֵן כְּעֵצִים אֶלָּא אִם כֵּן רְאוּיִין לִצְבִיעָה. וְהַקּוֹר קְדֻשַּׁת שְׁבִיעִית חָלָה עָלָיו:","הַצּוֹרֵר תַּבְלִין שֶׁל שְׁבִיעִית וְנוֹתֵן לְתוֹךְ הַתַּבְשִׁיל. אִם בָּטֵל טַעְמָן הֲרֵי אֵלּוּ מֻתָּרִין לְכָל דָּבָר. וְאִם נִשְׁאַר בָּהֶן טַעַם עֲדַיִן הֵם בִּקְדֻשַּׁת שְׁבִיעִית:","אֵין נוֹתְנִין תֶּבֶן וְקַשׁ שֶׁל שְׁבִיעִית לֹא לְתוֹךְ הַכַּר וְלֹא לְתוֹךְ הַטִּיט. וְאִם נָתַן הֲרֵי זֶה כִּמְבֹעָר. תַּנּוּר שֶׁהִסִּיקוּהוּ בְּתֶבֶן וּבְקַשׁ שֶׁל שְׁבִיעִית יוּצַן. וּמִשֶּׁתֵּרֵד רְבִיעָה שְׁנִיָּה בְּמוֹצָאֵי שְׁבִיעִית נֶהֱנִין וְשׂוֹרְפִין בְּתֶבֶן וּבְקַשׁ שֶׁל שְׁבִיעִית:"],"Mishneh Torah, Sacrifices Rendered Unfit 16":["כְּבָר בֵּאַרְנוּ שֶׁהַמְחַשֵּׁב בְּאַחַת מֵאַרְבַּע הָעֲבוֹדוֹת מַחֲשֶׁבֶת המָּקוֹם הַקָּרְבָּן פָּסוּל וְאֵינוֹ פִּגּוּל. וְאִם חִשֵּׁב מַחֲשֶׁבֶת הַזְּמַן הַקָּרְבָּן פִּגּוּל. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁלֹּא עֵרֵב עִם מַחֲשֶׁבֶת הַזְּמַן מַחֲשָׁבָה אַחֶרֶת. אֲבָל אִם עֵרֵב מַחֲשֶׁבֶת מָקוֹם אוֹ מַחֲשֶׁבֶת שִׁנּוּי הַשֵּׁם בְּפֶסַח וּבְחַטָּאת עִם מַחֲשֶׁבֶת הַזְּמַן הַקָּרְבָּן פָּסוּל וְאֵינוֹ פִּגּוּל. כֵּיצַד. שָׁחַט וְקִבֵּל וְהוֹלִיךְ וְזָרַק וּמַחְשַׁבְתּוֹ בְּאַרְבַּע עֲבוֹדוֹת אֵלּוּ מַחֲשֶׁבֶת הַזְּמַן. אוֹ שֶׁהָיְתָה מַחְשַׁבְתּוֹ בְּאַחַת מֵאַרְבַּעְתָּן מַחֲשֶׁבֶת הַזְּמַן וּבִשְׁאָר הָעֲבוֹדוֹת הָיְתָה מַחְשַׁבְתּוֹ נְכוֹנָה. אוֹ לֹא הָיְתָה שָׁם מַחֲשָׁבָה כְּלָל בִּשְׁאָר הָעֲבוֹדוֹת. הֲרֵי זֶה פִּגּוּל. אֲבָל אִם שָׁחַט בְּמַחְשֶׁבֶת הַזְּמַן וְקִבֵּל אוֹ הוֹלִיךְ אוֹ זָרַק בְּמַחְשֶׁבֶת הַמָּקוֹם. אוֹ שֶׁשָּׁחַט בְּמַחְשֶׁבֶת הַמָּקוֹם וְקִבֵּל אוֹ הוֹלִיךְ אוֹ זָרַק בְּמַחְשֶׁבֶת הַזְּמַן. הֲרֵי זֶה אֵינוֹ פִּגּוּל אֶלָּא פָּסוּל בִּלְבַד. וְכֵן הַפֶּסַח וְהַחַטָּאת שֶׁשְּׁחָטָן בְּמַחְשֶׁבֶת שִׁנּוּי הַשֵּׁם וְקִבֵּל וְהוֹלִיךְ בְּמַחְשֶׁבֶת הַזְּמַן. אוֹ שֶׁשְּׁחָטָן בְּמַחְשֶׁבֶת הַזְּמַן וְקִבֵּל אוֹ הוֹלִיךְ אוֹ זָרַק בְּמַחְשֶׁבֶת שִׁנּוּי הַשֵּׁם. אֵין זֶה פִּגּוּל אֶלָּא פָּסוּל. וְהוּא הַדִּין בְּעוֹפוֹת וּבִמְנָחוֹת. אֵין שָׁם פִּגּוּל אֶלָּא קָרְבָּן שֶׁנִּפְסַל בְּמַחְשֶׁבֶת הַזְּמַן וְלֹא עֵרֵב עִמָּהּ מַחֲשֶׁבֶת הַמָּקוֹם לֹא בַּתְּחִלָּה וְלֹא בְּסוֹף וְלֹא עֵרֵב עִמָּהּ מַחֲשֶׁבֶת שִׁנּוּי הַשֵּׁם בְּקָרְבָּנוֹת שֶׁנִּפְסָלִין בְּמַחְשֶׁבֶת שִׁנּוּי הַשֵּׁם:","הַמְחַשֵּׁב בְּאַחַת מֵאַרְבַּע הָעֲבוֹדוֹת אוֹ בְּכֻלָּם לֶאֱכל כְּזַיִת מִדָּבָר הָרָאוּי לַאֲכִילָה בַּחוּץ וּכְזַיִת לְמָחָר. אוֹ כְּזַיִת לְמָחָר וּכְזַיִת בַּחוּץ. אוֹ כַּחֲצִי זַיִת בַּחוּץ וְכַחֲצִי זַיִת לְמָחָר. אוֹ כַּחֲצִי זַיִת לְמָחָר וְכַחֲצִי זַיִת בַּחוּץ. הֲרֵי הַקָּרְבָּן פָּסוּל וְאֵינוֹ פִּגּוּל. וְכֵן אִם עֵרֵב הַמַּחְשָׁבָה בְּהַקְטָרָה הֲרֵי זֶה פָּסוּל וְאֵינוֹ פִּגּוּל:","חִשֵּׁב לֶאֱכל אוֹ לְהַקְטִיר כַּחֲצִי זַיִת בְּמַחְשֶׁבֶת הַמָּקוֹם וְלֶאֱכל אוֹ לְהַקְטִיר כְּזַיִת בְּמַחְשֶׁבֶת הַזְּמַן הֲרֵי זֶה פִּגּוּל. בֵּין שֶׁהִקְדִּים מַחֲשֶׁבֶת כְּזַיִת בֵּין שֶׁאִחֵר אוֹתָהּ. שֶׁאֵין חֲצִי זַיִת חָשׁוּב אֵצֶל כְּזַיִת:","חִשֵּׁב עַל חֲצִי זַיִת בְּמַחְשֶׁבֶת הַזְּמַן וְעַל חֲצִי זַיִת בְּמַחְשֶׁבֶת הַמָּקוֹם וְחָזַר וְחִשֵּׁב עַל חֲצִי זַיִת אַחֵר בְּמַחְשֶׁבֶת הַזְּמַן הֲרֵי זֶה פִּגּוּל. וְכֵן אִם חִשֵּׁב עַל חֲצִי זַיִת בְּמַחְשֶׁבֶת הַזְּמַן וְחָזַר וְחִשֵּׁב עַל כְּזַיִת חֶצְיוֹ בְּמַחְשֶׁבֶת הַזְּמַן וְחֶצְיוֹ בְּמַחְשֶׁבֶת הַמָּקוֹם הֲרֵי זֶה פִּגּוּל:","חִשֵּׁב עַל הַדָּמִים הַנִּתָּנִין לְמַטָּה לִתֵּן אוֹתָם לְמַעְלָה אוֹ עַל הַנִּתָּנִין לְמַעְלָה לְתִתָּם לְמַטָּה וְכַיּוֹצֵא בְּמַחְשָׁבוֹת אֵלּוּ שֶׁאֵינָן פּוֹסְלִין כְּמוֹ שֶׁבֵּאַרְנוּ וְעֵרֵב עִמָּהֶן מַחֲשֶׁבֶת הַזְּמַן הֲרֵי זֶה פִּגּוּל. וְאִם חִשֵּׁב עִמָּהֶן מַחֲשֶׁבֶת הַמָּקוֹם לְבַדָּהּ הֲרֵי זֶה פָּסוּל וְאֵינוֹ פִּגּוּל:","חִשֵּׁב עַל הַדָּם הַנִּתָּן לְמַעְלָה לְתִתּוֹ לְמָחָר לְמַטָּה. אוֹ עַל הַדָּם הַנִּתָּן לְמַטָּה לְתִתּוֹ לְמָחָר לְמַעְלָה. אוֹ שֶׁחִשֵּׁב עַל הַדָּם הַנִּתָּן בִּפְנִים בַּהֵיכָל לְתִתּוֹ לְמָחָר בַּמִּזְבֵּחַ הַחִיצוֹן. אוֹ שֶׁחִשֵּׁב עַל הַדָּם הַנִּתָּן בַּמִּזְבֵּחַ הַחִיצוֹן לְתִתּוֹ לְמָחָר בִּפְנִים בַּהֵיכָל. אֵינוֹ פִּגּוּל. אַף עַל פִּי שֶׁחִשֵּׁב מַחֲשֶׁבֶת הַזְּמַן הוֹאִיל וְשִׁנָּה מְקוֹם נְתִינַת הַדָּם בְּמַחֲשַׁבְתּוֹ הֲרֵי זֶה פָּסוּל וְאֵינוֹ פִּגּוּל. וּמֵאַחַר שֶׁבֵּאַרְנוּ בַּהֲלָכוֹת אֵלּוּ שֶׁהַדָּם שֶׁנִּתָּן שֶׁלֹּא בִּמְקוֹמוֹ כְּאִלּוּ נִתַּן בִּמְקוֹמוֹ לָמָּה לֹא יִהְיֶה זֶה פִּגּוּל בְּמַחְשָׁבָה זוֹ שֶׁחִשֵּׁב לִתֵּן הַדָּם שֶׁלֹּא בִּמְקוֹמוֹ לְמָחָר. מִפְּנֵי שֶׁהַדָּם הַנִּתָּן שֶׁלֹּא בִּמְקוֹמוֹ אַף עַל פִּי שֶׁהַזֶּבַח כָּשֵׁר אֵינוֹ מַתִּיר הַבָּשָׂר בַּאֲכִילָה כְּמוֹ שֶׁבֵּאַרְנוּ. וְכָל זְרִיקָה שֶׁאֵינָהּ מַתֶּרֶת הַבָּשָׂר בַּאֲכִילָה אִם חִשֵּׁב לִתְּנָהּ חוּץ לִזְמַנּוֹ לֹא פִּגֵּל. לְפִיכָךְ אִם חָזַר וְחִשֵּׁב בְּזֶבַח זֶה מַחֲשֶׁבֶת הַזְּמַן הֲרֵי זֶה פָּסוּל וְאֵינוֹ פִּגּוּל:","חִשֵּׁב מַחֲשֶׁבֶת זְמַן בִּשְׁעַת קְמִיצָה אֲבָל לֹא בִּשְׁעַת לִקּוּט הַלְּבוֹנָה. אוֹ שֶׁחִשֵּׁב מַחֲשֶׁבֶת הַזְּמַן בִּשְׁעַת לִקּוּט הַלְּבוֹנָה אֲבָל לֹא בִּשְׁעַת קְמִיצָה. הֲרֵי זוֹ פְּסוּלָה וְאֵינָהּ פִּגּוּל עַד שֶׁיְּחַשֵּׁב מַחֲשֶׁבֶת הַזְּמַן בְּכָל הַמַּתִּיר שֶׁהוּא הַקֹּמֶץ עִם הַלְּבוֹנָה. בִּשְׁעַת קְמִיצַת הַקֹּמֶץ וְלִקּוּט הַלְּבוֹנָה. אוֹ בִּשְׁעַת נְתִינַת שְׁנֵיהֶן בִּכְלִי. אוֹ בִּשְׁעַת הוֹלָכָתָן אוֹ בִּשְׁעַת זְרִיקָתָן:","חִשֵּׁב בִּשְׁעַת הַקְטָרַת הַקֹּמֶץ שֶׁיַּקְטִיר הַלְּבוֹנָה לְמָחָר אֵינָהּ פִּגּוּל שֶׁאֵין הַקְטָרָה מְפַגֶּלֶת הַקְטָרָה. וְכֵן אִם הִקְטִיר הַלְּבוֹנָה לְבַדָּהּ אוֹ הַקֹּמֶץ לְבַדּוֹ וְהוּא מְחַשֵּׁב לֶאֱכל שְׁיָרִים לְמָחָר הֲרֵי זוֹ פְּסוּלָה וְאֵינָהּ פִּגּוּל שֶׁאֵין מְפַגְּלִין בַּחֲצִי מַתִּיר. אֲבָל אִם הִקְטִיר אֶת הַקֹּמֶץ לְבַדּוֹ וְחִשֵּׁב שֶׁיַּקְטִיר לְבוֹנָה לְמָחָר וְאַחַר כָּךְ הִקְטִיר הַלְּבוֹנָה וְחִשֵּׁב שֶׁיֹּאכַל הַשְּׁיָרִים לְמָחָר הֲרֵי זֶה פִּגּוּל. שֶׁהֲרֵי פָּשְׁטָה מַחֲשֶׁבֶת זְמַן בְּכָל הַמִּנְחָה:","הִקְטִיר כְּדֵי שֻׁמְשֹׁם מִן הַקֹּמֶץ עִם הַלְּבוֹנָה וְהוּא מְחַשֵּׁב שֶׁיֹּאכַל כְּדֵי שֻׁמְשֹׁם מִן הַשְּׁיָרִים לְמָחָר. עַד שֶׁהִשְׁלִים כָּל הַקֹּמֶץ עִם הַלְּבוֹנָה בְּמַחְשֶׁבֶת הַזְּמַן. הֲרֵי זוֹ פְּסוּלָה וְאֵינָהּ פִּגּוּל. שֶׁאַף עַל פִּי שֶׁדֶּרֶךְ אֲכִילָה בְּכָךְ מְעַט מְעַט אֵין דֶּרֶךְ הַקְטָרָה בְּכָךְ אֶלָּא הֲרֵי זוֹ כְּמִנְחָה שֶׁלֹּא הֻקְטַר קֻמְצָהּ:","מִנְחַת חוֹטֵא אוֹ מִנְחַת קְנָאוֹת שֶׁהָיָה עָלֶיהָ לְבוֹנָה וְחִשֵּׁב בָּהּ מַחֲשֶׁבֶת הַזְּמַן קֹדֶם שֶׁיְּלַקֵּט הַלְּבוֹנָה הֲרֵי זוֹ פְּסוּלָה וְאֵינָהּ פִּגּוּל. וְאִם אַחַר שֶׁלִּקֵּט הַלְּבוֹנָה חִשֵּׁב עָלֶיהָ מַחֲשֶׁבֶת הַזְּמַן הֲרֵי זֶה פִּגּוּל:","שְׁיָרִים שֶׁחָסְרוּ בֵּין קְמִיצָה לְהַקְטָרָה וְהִקְטִיר הַקֹּמֶץ בְּמַחְשֶׁבֶת הַזְּמַן הֲרֵי זֶה סָפֵק אִם נִקְבְּעוּ לְפִגּוּל וַהֲרֵי הֵן פִּגּוּל. אוֹ לֹא נִקְבְּעוּ וְאֵינוֹ פִּגּוּל:"],"Mishneh Torah, Sacrificial Procedure 1":["כָּל הַקָּרְבָּנוֹת שֶׁל מִינֵי נֶפֶשׁ חַיָּה בָּאִין מֵחֲמִשָּׁה מִינִין בִּלְבַד. מִן הַבָּקָר וּמִן הַכְּבָשִׂים וּמִן הָעִזִּים וּמִן הַתּוֹרִים וּמִן בְּנֵי הַיּוֹנָה:","וְכָל הַקָּרְבָּנוֹת בֵּין שֶׁל צִבּוּר בֵּין שֶׁל יָחִיד אַרְבָּעָה מִינִין. עוֹלָה. וְחַטָּאת. וְאָשָׁם. וּשְׁלָמִים:","וְעוֹד יֵשׁ שָׁם שְׁלֹשָׁה מִינֵי קָרְבַּן יָחִיד וְהֵם הַפֶּסַח. וְהַבְּכוֹר. וְהַמַּעֲשֵׂר:","כָּל קָרְבָּנוֹת הַצִּבּוּר הֵן עוֹלָה אוֹ חַטָּאת. וְאֵין בְּקָרְבְּנוֹת הַצִּבּוּר שְׁלָמִים חוּץ מִשְּׁנֵי כְּבָשִׂים הַבָּאִים עִם לֶחֶם הַתְּנוּפָה בַּעֲצֶרֶת. וְהֵם הַנִּקְרָאִים זִבְחֵי שַׁלְמֵי צִבּוּר. וְאֵין הַצִּבּוּר מַקְרִיבִין אָשָׁם לְעוֹלָם וְלֹא עוֹף:","קָרְבְּנוֹת הַצִּבּוּר הֵם שְׁנֵי תְּמִידִין שֶׁל כָּל יוֹם. וּמוּסְפֵי שַׁבָּתוֹת וְרָאשֵׁי חֳדָשִׁים וְהַמּוֹעֲדוֹת וּשְׂעִיר חַטָּאת שֶׁל יוֹם הַכִּפּוּרִים. וְכֵן אִם שָׁגְגוּ בֵּית דִּין וְהוֹרוּ בַּעֲבוֹדָה זָרָה מֵבִיא כָּל שֵׁבֶט וְשֵׁבֶט פַּר וְשָׂעִיר. הַפָּר עוֹלָה וְהַשָּׂעִיר חַטָּאת. וְאֵלּוּ הַשְּׂעִירִים הֵם הַנִּקְרָאִים שְׂעִירֵי עֲבוֹדָה זָרָה. וְאִם שָׁגְגוּ וְהוֹרוּ בִּשְׁאָר הַמִּצְוֹת מְבִיאִין פַּר לְחַטָּאת וְהוּא הַנִּקְרָא פַּר הֶעְלֵם דָּבָר שֶׁל צִבּוּר:","קָרְבְּנוֹת הַיָּחִיד הֵם הַבְּכוֹר וְהַמַּעֲשֵׂר וְהַפֶּסַח. וְהַחֲגִיגָה וְהִיא שְׁלָמִים. וְהָרְאִיָּה וְהִיא עוֹלוֹת. וְקָרְבַּן הַגֵּר וְהוּא עוֹלָה מִן הַבְּהֵמָה. אוֹ שְׁנֵי בְּנֵי יוֹנָה אוֹ שְׁתֵּי תּוֹרִים וּשְׁנֵיהֶן עוֹלָה. אוֹ שְׁתֵּי בְּהֵמוֹת אַחַת עוֹלָה וְאַחַת שְׁלָמִים. וְהַנּוֹדֵר אוֹ הַמִּתְנַדֵּב עוֹלָה אוֹ שְׁלָמִים. וּשְׁלָמִים הַבָּאִין עִם הַלֶּחֶם הֵם הַנִּקְרָאִים תּוֹדָה. וְכֵן קָרְבְּנוֹת הַנָּזִיר וְהֵן עוֹלָה וְחַטָּאת וּשְׁלָמִים. וְקָרְבְּנוֹת מְצֹרָע וְהֵן חַטָּאת וְאָשָׁם וְעוֹלָה. וְקָרְבְּנוֹת זָבִים וְיוֹלְדוֹת וְהֵן חַטָּאת וְעוֹלָה. וְקָרְבַּן הַשּׁוֹגֵג בְּמִצְוַת לֹא תַּעֲשֶׂה שֶׁיֵּשׁ בָּהּ כָּרֵת וְהוּא חַטָּאת. וְאִם נִסְתַּפֵּק לוֹ אִם עָשָׂה אוֹ לֹא עָשָׂה אוֹתוֹ הַחוֹטֵא מֵבִיא אָשָׁם וְהוּא הַנִּקְרָא אָשָׁם תָּלוּי. וְיֵשׁ עֲבֵרוֹת שֶׁמֵּבִיא עֲלֵיהֶן אָשָׁם וְהוּא הַנִּקְרָא אָשָׁם וַדַּאי. וְכֵן אֵיל הָעוֹלָה וּפַר הַחַטָּאת שֶׁמַּקְרִיב כֹּהֵן גָּדוֹל מִשֶּׁלּוֹ בְּיוֹם הַכִּפּוּרִים הֲרֵי הֵן קָרְבַּן יָחִיד. וּפַר זֶה הוּא הַנִּקְרָא פַּר יוֹם הַכִּפּוּרִים. וְכָל אֵלּוּ הַקָּרְבָּנוֹת מְפֹרָשִׁין הֵן בַּתּוֹרָה וְכָל אֶחָד מֵהֶן יִתְבָּאֲרוּ דִּינָיו בִּמְקוֹמוֹ:","כָּל קָרְבְּנוֹת הַיָּחִיד חַיָּב בְּאַחֲרָיוּתָן וּבְאַחֲרָיוּת נִסְכֵּיהֶן חוּץ מִן הַנְּדָבָה. וְכָל קָרְבְּנוֹת הַצִּבּוּר אֵינָן חַיָּבִין בְּאַחֲרָיוּתָן וְלֹא בְּאַחֲרָיוּת נִסְכֵּיהֶן. וְאִם קָרַב הַזֶּבַח חַיָּבִין בְּאַחֲרָיוּת נִסְכֵּיהֶם. וְקָרְבַּן יָחִיד שֶׁקָּבוּעַ לוֹ זְמַן הֲרֵי הוּא כְּקָרְבַּן צִבּוּר וְאֵינוֹ חַיָּב בְּאַחֲרָיוּתוֹ:","כָּל עוֹלַת בְּהֵמָה אֵינָהּ בָּאָה אֶלָּא מִן הַזְּכָרִים בִּלְבַד. וְהִיא בָּאָה מִן הַכְּבָשִׂים וּמִן הָעִזִּים וּמִן הַבָּקָר בֵּין גְּדוֹלִים בֵּין קְטַנִּים. וּמִן הַתּוֹרִים וּבְנֵי יוֹנָה וְאֶחָד בָּהֶן הַזָּכָר וְהַנְּקֵבָה:","הַחַטָּאת בָּאָה מֵחֲמֵשֶׁת הַמִּינִים הָאֵלּוּ מִן הַזְּכָרִים וּמִן הַנְּקֵבוֹת מִן הַגְּדוֹלִים וּמִן הַקְּטַנִּים:","הָאָשָׁם אֵינוֹ בָּא אֶלָּא מִזִּכְרֵי כְּבָשִׂים בִּלְבַד. יֵשׁ אָשָׁם בָּא מִגְּדוֹלֵי מִין זֶה וְיֵשׁ אָשָׁם בָּא מִן הַקְּטַנִּים:","הַשְּׁלָמִים בָּאִים מִן הַכְּבָשִׂים וּמִן הָעִזִּים וּמִן הַבָּקָר מִזְּכָרִים וּמִנְּקֵבוֹת מִן הַגְּדוֹלִים וּמִן הַקְּטַנִּים. וְאֵין הָעוֹף בָּא שְׁלָמִים. הַקְּטַנִּים הֵם מִבֶּן שְׁמוֹנַת יָמִים עַד שָׁנָה תְּמִימָה מִיּוֹם לְיוֹם. אִם נִתְעַבְּרָה שָׁנָה נִתְעַבְּרָה לוֹ. וְהַגְּדוֹלִים בַּבָּקָר עַד שָׁלֹשׁ שָׁנִים שְׁלֵמוֹת מִיּוֹם לְיוֹם. וּבַצֹּאן עַד שְׁתֵּי שָׁנִים שְׁלֵמוֹת מִיּוֹם לְיוֹם. יוֹתֵר עַל זֶה הֲרֵי הוּא זָקֵן וְאֵין מַקְרִיבִין אוֹתוֹ:","אַף עַל פִּי שֶׁכָּל הַקָּרְבָּנוֹת כְּשֵׁרִין מִיּוֹם הַשְּׁמִינִי וָהָלְאָה אֵין מַקְרִיבִין לְכַתְּחִלָּה אֶלָּא מִיּוֹם שְׁלֹשִׁים וָהָלְאָה. חוּץ מִן הַבְּכוֹר וּמִן הַפֶּסַח וּמִן הַמַּעֲשֵׂר שֶׁאִם רָצָה לְהַקְרִיבָן בַּשְּׁמִינִי לְכַתְּחִלָּה מַקְרִיב:","שָׁעוֹת מוֹנִין לְקָדָשִׁים. וְאִם הוֹסִיפוּ שָׁעָה אַחַת אוֹ פָּחֲתוּ שָׁעָה פְּסוּלִין. כֵּיצַד. קָרְבָּן שֶׁמִּצְוָתוֹ לִהְיוֹת בֶּן שָׁנָה אִם הוֹסִיף עַל הַשָּׁנָה שָׁעָה אַחַת נִפְסַל. אֲפִלּוּ הָיָה בֶּן שָׁנָה בִּשְׁעַת שְׁחִיטָה וְהוֹסִיף עַל הַשָּׁנָה בִּשְׁעַת זְרִיקָה נִפְסַל עַד שֶׁיִּהְיֶה בֶּן שָׁנָה עַד שְׁעַת זְרִיקָה. וְכֵן בְּכָל הַזְּבָחִים:","כָּל מָקוֹם שֶׁנֶּאֱמַר בַּתּוֹרָה כֶּבֶשׂ אוֹ כַּבְשָׂה אוֹ כְּבָשִׂים הֲרֵי אֵלּוּ בְּנֵי שָׁנָה. וְכָל מָקוֹם שֶׁנֶּאֱמַר אַיִל אוֹ אֵילִים הֵם הַזְּכָרִים בְּנֵי שְׁנָתַיִם. וּמֵאֵימָתַי יִקָּרֵא אַיִל מִשֶּׁיִּכָּנֵס בְּשָׁנָה שְׁנִיָּה אֶחָד וּשְׁלֹשִׁים יוֹם. אֲבָל בְּיוֹם שְׁלֹשִׁים אֵינוֹ כָּשֵׁר לֹא לְכֶבֶשׂ וְלֹא לָאַיִל וְהוּא הַנִּקְרָא פִּלְגָּס. וְכָל מָקוֹם שֶׁנֶּאֱמַר בּוֹ עֵגֶל הֲרֵי זֶה בֶּן שָׁנָה. פַּר בֶּן שְׁתַּיִם. שְׂעִיר עִזִּים [בֶּן שָׁנָה. שָׂעִיר] בֶּן שְׁתַּיִם. כָּל שָׁנָה שְׁנִיָּה הוּא נִקְרָא שָׂעִיר:","כָּל קָרְבְּנוֹת הַצִּבּוּר זְכָרִים. וְכֵן חַטָּאוֹת שֶׁל צִבּוּר מִן הָעֵז אוֹ מִן הַבָּקָר. וְאֵין בָּהֶן מִן הַכְּבָשִׂים. וְכָל עוֹלוֹת הַצִּבּוּר מִן הַכְּבָשִׂים וּמִן הַבָּקָר. וְאֵין לָהֶן עוֹלָה מִן הָעֵז. כָּל חַטַּאת יָחִיד נְקֵבָה וְתֵאָכֵל לַכֹּהֲנִים וְאֵינָהּ בָּאָה מִן הַבָּקָר. חוּץ מִשָּׁלֹשׁ חַטָּאוֹת. חַטַּאת נָשִׂיא שֶׁהִיא עֵז וְנֶאֱכֶלֶת. וְחַטַּאת כֹּהֵן מָשִׁיחַ שֶׁהוּא פַּר וְנִשְׂרֶפֶת וְהוּא פַּר הַבָּא עַל כָּל הַמִּצְוֹת. וְהַשְּׁלִישִׁי פַּר שֶׁמֵּבִיא כֹּהֵן גָּדוֹל בְּיוֹם הַכִּפּוּרִים וְהוּא חַטָּאת וְנִשְׂרָף:","כָּל חַטָּאוֹת שֶׁל צִבּוּר נֶאֱכָלוֹת חוּץ מִשָּׂעִיר שֶׁל יוֹם הַכִּפּוּרִים שֶׁחֲבֵרוֹ מִשְׁתַּלֵּחַ. וְכֵן שְׂעִירֵי עֲבוֹדָה זָרָה וּפַר הֶעְלֵם נִשְׂרָפִין. וּפַר הַבָּא עַל כָּל הַמִּצְוֹת וּפַר הֶעְלֵם נִקְרָאִים פָּרִים הַנִּשְׂרָפִין. וּשְׂעִירֵי עֲבוֹדָה זָרָה נִקְרָאִים שְׂעִירִים הַנִּשְׂרָפִין. הָא לָמַדְתָּ שֶׁחָמֵשׁ חַטָּאוֹת הֵם הַנִּשְׂרָפוֹת. שְׁתַּיִם לַיָּחִיד וְשָׁלֹשׁ לַצִּבּוּר:","כָּל הַקָּרְבָּנוֹת הָאֵלּוּ נִקְרָאִים זְבָחִים. וְכָל הָעוֹלוֹת וְהַחַטָּאוֹת וְהָאֲשָׁמוֹת וּשְׁנֵי כַּבְשֵׂי שְׁלָמִים שֶׁל עֲצֶרֶת נִקְרָאִים קָדְשֵׁי קָדָשִׁים. אֲבָל שְׁלָמִים שֶׁל יָחִיד וְהַבְּכוֹר וְהַמַּעֲשֵׂר וְהַפֶּסַח נִקְרָאִים קָדָשִׁים קַלִּים:","הָאֵיבָרִים שֶׁשּׂוֹרְפִין אוֹתָן עַל גַּבֵּי הַמִּזְבֵּחַ מִן הַחַטָּאוֹת הַנֶּאֱכָלוֹת וּמִן הָאֲשָׁמוֹת וּמִן הַשְּׁלָמִים הֵן הַנִּקְרָאִין אֵימוּרִין. וְאֵלּוּ הֵן הָאֵימוּרִין שֶׁל שׁוֹר אוֹ שֶׁל עֵז. הַחֵלֶב אֲשֶׁר עַל הַקֶּרֶב וּבִכְלָלוֹ חֵלֶב שֶׁעַל גַּבֵּי הַקֵּבָה וּשְׁתֵּי הַכְּלָיוֹת וְחֵלֶב שֶׁעֲלֵיהֶן עִם הַחֵלֶב אֲשֶׁר עַל הַכְּסָלִים וְיוֹתֶרֶת הַכָּבֵד וְנוֹטֵל מִן הַכָּבֵד מְעַט עִם הַיּוֹתֶרֶת. וְאִם הָיָה הַקָּרְבָּן מִמִּין הַכְּבָשִׂים מוֹסִיף עַל אֵלּוּ הָאַלְיָה תְּמִימָה עִם הַחֻלְיוֹת מִן הַשִּׁדְרָה עַד מְקוֹם הַכְּלָיוֹת שֶׁנֶּאֱמַר (ויקרא ג ט) \"לְעֵמַּת הֶעָצֶה יְסִירֶנָּה\". וְכָל הָאֵימוּרִין נִשְׂרָפִין עַל מִזְבֵּחַ הַחִיצוֹן:","הָיְתָה הַבְּהֵמָה מְעֻבֶּרֶת אַף עַל פִּי שֶׁכָּלוּ חֳדָשָׁיו שֶׁל עֻבָּר וַאֲפִלּוּ נִמְצָא חַי אֵינוֹ מַעֲלֶה חֶלְבּוֹ עִם חֵלֶב אִמּוֹ אֶלָּא חֵלֶב אִמּוֹ בִּלְבַד. וַהֲרֵי הָעֻבָּר כְּאֶחָד מֵאֵיבָרֶיהָ:"],"Mishneh Torah, Sacrificial Procedure 3":["שְׁנַּיִם שֶׁרָצוּ לְהָבִיא שְׁלָמִים אוֹ עוֹלָה בְּשֻׁתָּפוּת מְבִיאִין בֵּין בְּנֵדֶר בֵּין בִּנְדָבָה. וַאֲפִלּוּ עוֹף יָבוֹא בְּשֻׁתָּפוּת:","וְאֶחָד אֲנָשִׁים וְאֶחָד נָשִׁים אוֹ עֲבָדִים מְבִיאִין כָּל הַקָּרְבָּנוֹת. אֲבָל הָעַכּוּ\"ם אֵין מְקַבְּלִין מֵהֶן אֶלָּא עוֹלוֹת בִּלְבַד שֶׁנֶּאֱמַר (ויקרא כב כה) \"וּמִיַּד בֶּן נֵכָר לֹא תַקְרִיבוּ אֶת לֶחֶם אֱלֹהֵיכֶם\". אֲפִלּוּ עוֹלַת הָעוֹף מְקַבְּלִין מִן הַנָּכְרִי אַף עַל פִּי שֶׁהוּא עוֹבֵד עֲבוֹדָה זָרָה. אֲבָל אֵין מְקַבְּלִין מֵהֶן שְׁלָמִים וְלֹא מְנָחוֹת וְלֹא חַטָּאוֹת וַאֲשָׁמוֹת. וְכֵן עוֹלוֹת שֶׁאֵינָן בָּאוֹת בְּנֵדֶר וּנְדָבָה אֵין מְקַבְּלִין אוֹתָן מִן הַנָּכְרִי כְּגוֹן עוֹלַת יוֹלֶדֶת וְכַיּוֹצֵא בָּהּ מֵעוֹלוֹת שֶׁאֵינָן בָּאוֹת מִשּׁוּם נֵדֶר וְלֹא מִשּׁוּם נְדָבָה:","נָכְרִי שֶׁהֵבִיא שְׁלָמִים מַקְרִיבִין אוֹתָן עוֹלוֹת שֶׁהָעַכּוּ\"ם לִבּוֹ לַשָּׁמַיִם. נָדַר שְׁלָמִים וּנְתָנָם לְיִשְׂרָאֵל עַל מְנָת שֶׁיִּתְכַּפֵּר בָּהֶן לְיִשְׂרָאֵל אוֹכְלִין אוֹתָן הַיִּשְׂרְאֵלִים כְּשַׁלְמֵי יִשְׂרָאֵל. וְכֵן אִם נְתָנָן לַכֹּהֵן כֹּהֵן אוֹכְלָן:","יִשְׂרָאֵל שֶׁהוּא מוּמָר לַעֲבוֹדָה זָרָה אוֹ מְחַלֵּל שַׁבָּת בְּפַרְהֶסְיָא אֵין מְקַבְּלִין מִמֶּנּוּ קָרְבָּן כְּלָל. אֲפִלּוּ הָעוֹלָה שֶׁמְּקַבְּלִין אוֹתָהּ מִן הַנָּכְרִים אֵין מְקַבְּלִין אוֹתָהּ מִן הַמּוּמָר הַזֶּה שֶׁנֶּאֱמַר (ויקרא א ב) \"אָדָם כִּי יַקְרִיב מִכֶּם\" מִפִּי הַשְּׁמוּעָה לָמְדוּ מִכֶּם וְלֹא כֻּלְּכֶם לְהוֹצִיא אֶת הַמּוּמָר. אֲבָל אִם הָיָה מוּמָר לִשְׁאָר עֲבֵרוֹת מְקַבְּלִין מִמֶּנּוּ כָּל הַקָּרְבָּנוֹת כְּדֵי שֶׁיַּחֲזֹר בִּתְשׁוּבָה. הָיָה מוּמָר לַעֲבֵרָה וְהוּא מְפֻרְסָם וְיָדוּעַ לַעֲשׂוֹתָהּ וְהֻרְגַּל בָּהּ בֵּין לְהַכְעִיס בֵּין לְתֵאָבוֹן אֵין מְקַבְּלִין מִמֶּנּוּ קָרְבָּן לְאוֹתָהּ עֲבֵרָה. כֵּיצַד. כְּגוֹן שֶׁהָיָה רָגִיל לֶאֱכל חֵלֶב בֵּין לְהַכְעִיס בֵּין לְתֵאָבוֹן וְשָׁגַג וְאָכַל חֵלֶב וְהֵבִיא חַטָּאת אֵין מְקַבְּלִין אוֹתָהּ מִמֶּנּוּ:","עוֹלוֹת הָעַכּוּ\"ם אֵין מְבִיאִין עִמָּהֶן נְסָכִים שֶׁנֶּאֱמַר (במדבר טו יג) \"כָּל הָאֶזְרָח יַעֲשֶׂה כָּכָה\". אֲבָל נִסְכֵּיהֶם קְרֵבִין מִשֶּׁל צִבּוּר שֶׁנֶּאֱמַר (במדבר טו יב) \"כָּכָה תַּעֲשׂוּ לָאֶחָד כְּמִסְפָּרָם\". וְאֵינָן טְעוּנוֹת סְמִיכָה שֶׁאֵין סְמִיכָה אֶלָּא בְּיִשְׂרָאֵל בַּאֲנָשִׁים לֹא בְּנָשִׁים:","כָּל קָרְבְּנוֹת בְּהֵמָה שֶׁיַּקְרִיב הַיָּחִיד בֵּין חוֹבָה בֵּין נְדָבָה סוֹמֵךְ עֲלֵיהֶן כְּשֶׁהֵן חַיִּין. חוּץ מִן הַבְּכוֹר וְהַמַּעֲשֵׂר וְהַפֶּסַח. שֶׁנֶּאֱמַר (ויקרא ג ב) \"וְסָמַךְ יָדוֹ עַל רֹאשׁ קָרְבָּנוֹ\". מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁכָּל קָרְבָּן בְּמַשְׁמָע חוּץ מִפֶּסַח וּבְכוֹר וּמַעֲשֵׂר:","הָעוֹף אֵינוֹ טָעוּן סְמִיכָה. וְכֵן כָּל הַמָּעוֹת שֶׁדִּינָן שֶׁיִּפְּלוּ לַתֵּבוֹת שֶׁל נְדָבָה שֶׁכְּבָר בֵּאַרְנוּ בְּהִלְכוֹת שְׁקָלִים שֶׁכֻּלָּן יָבוֹאוּ עוֹלוֹת אֵין בַּעַל אוֹתָן הַמָּעוֹת סוֹמֵךְ עַל אוֹתָהּ הָעוֹלָה וְאֵינוֹ מֵבִיא עָלֶיהָ נְסָכִים אֶלָּא נְסָכֶיהָ מִשֶּׁל צִבּוּר וְאַף עַל פִּי שֶׁהָיָה כֹּהֵן עֲבוֹדָתָהּ וְעוֹרָהּ שֶׁל אַנְשֵׁי מִשְׁמָר:","הַכּל סוֹמְכִין חוּץ מֵחֵרֵשׁ שׁוֹטֶה וְקָטָן וְעֶבֶד וְאִשָּׁה וְסוּמָא וְנָכְרִי. וְאֵין הַשָּׁלִיחַ סוֹמֵךְ שֶׁאֵין סְמִיכָה אֶלָּא בִּבְעָלִים שֶׁנֶּאֱמַר (ויקרא ג ב) \"וְסָמַךְ יָדוֹ\" לֹא יַד אִשְׁתּוֹ וְלֹא יַד עַבְדּוֹ וְלֹא שְׁלוּחוֹ:","חֲמִשָּׁה שֶׁהֵבִיאוּ זֶבַח אֶחָד כֻּלָּן סוֹמְכִין עָלָיו זֶה אַחַר זֶה. לֹא שֶׁיִּסְמְכוּ כֻּלָּן בְּבַת אַחַת. מִי שֶׁמֵּת וְהִנִּיחַ קָרְבָּנוֹ עוֹלָה אוֹ שְׁלָמִים הֲרֵי יוֹרְשׁוֹ מְבִיאוֹ וְסוֹמֵךְ עָלָיו וּמֵבִיא נְסָכָיו:","אֵין סְמִיכָה בְּקָרְבְּנוֹת הַצִּבּוּר חוּץ מִשְּׁתֵי סְמִיכוֹת. עַל שָׂעִיר הַמִּשְׁתַּלֵּחַ וְעַל פַּר הֶעְלֵם דָּבָר. וּשְׁלֹשָׁה מִן הַסַּנְהֶדְרִין סוֹמְכִין עָלָיו. וְדָבָר זֶה הֲלָכָה מִפִּי משֶׁה רַבֵּנוּ שֶׁאֵין בְּצִבּוּר אֶלָּא שְׁתֵּי סְמִיכוֹת:","אֵין סוֹמְכִין אֶלָּא בָּעֲזָרָה. סָמַךְ חוּץ לָעֲזָרָה חוֹזֵר וְסוֹמֵךְ מִבִּפְנִים. וְאִם הָיָה בַּעַל הַקָּרְבָּן עוֹמֵד בַּחוּץ וְהִכְנִיס יָדוֹ לְפָנִים וְסָמַךְ סְמִיכָתוֹ כְּשֵׁרָה. וְהוּא שֶׁיִּסְמֹךְ בְּכָל כֹּחוֹ. וְאֵין סוֹמֵךְ אֶלָּא טָהוֹר וְאִם סָמַךְ הַטָּמֵא סָמַךְ:","וּבְמָקוֹם שֶׁסּוֹמְכִין שׁוֹחֲטִין. וְתֵכֶף לִסְמִיכָה שְׁחִיטָה. וְאִם שָׁחַט בְּמָקוֹם אַחֵר אוֹ שֶׁשָּׁהָה שְׁחִיטָתוֹ כְּשֵׁרָה. וְהַסְּמִיכָה שְׁיָרֵי מִצְוָה הִיא לְפִיכָךְ אִם לֹא סָמַךְ כִּפֵּר וְאֵינָהּ מְעַכֶּבֶת וְאַף עַל פִּי כֵן מַעֲלִין עָלָיו כְּאִלּוּ לֹא כִּפֵּר:","וְצָרִיךְ הַסּוֹמֵךְ לִסְמֹךְ בְּכָל כֹּחוֹ בִּשְׁתֵּי יָדָיו עַל רֹאשׁ הַבְּהֵמָה שֶׁנֶּאֱמַר (ויקרא א ד) \"עַל רֹאשׁ הָעלָה\" לֹא עַל הַצַּוָּאר וְלֹא עַל הַצְּדָדִין. וְלֹא יִהְיֶה דָּבָר חוֹצֵץ בֵּין יָדָיו וּבֵין הַבְּהֵמָה:","וְכֵיצַד סוֹמֵךְ. אִם הָיָה הַקָּרְבָּן קֹדֶשׁ קָדָשִׁים מַעֲמִידוֹ בַּצָּפוֹן וּפָנָיו לַמַּעֲרָב וְהַסּוֹמֵךְ עוֹמֵד בַּמִּזְרָח וּפָנָיו לַמַּעֲרָב וּמַנִּיחַ שְׁתֵּי יָדָיו בֵּין שְׁתֵּי קַרְנָיו וּמִתְוַדֶּה עַל חַטָּאת עֲוֹן חַטָּאת וְעַל אָשָׁם עֲוֹן אָשָׁם. וְעַל הָעוֹלָה מִתְוַדֶּה עֲוֹן עֲשֵׂה וַעֲוֹן לֹא תַּעֲשֶׂה שֶׁנִּתַּק לַעֲשֵׂה:","כֵּיצַד מִתְוַדֶּה. אוֹמֵר חָטָאתִי עָוִיתִי פָּשַׁעְתִּי וְעָשִׂיתִי כָּךְ וְכָךְ וְחָזַרְתִּי בִּתְשׁוּבָה לְפָנֶיךָ וְזוֹ כַּפָּרָתִי. הָיָה הַקָּרְבָּן שְׁלָמִים סוֹמֵךְ בְּכָל מָקוֹם שֶׁיִּרְצֶה מִן הָעֲזָרָה בִּמְקוֹם שְׁחִיטָה. וְיֵרָאֶה לִי שֶׁאֵינוֹ מִתְוַדֶּה עַל הַשְּׁלָמִים אֲבָל אוֹמֵר דִּבְרֵי שֶׁבַח:"],"Mishneh Torah, Sales 14":["כְּבָר בֵּאַרְנוּ שֶׁהַנּוֹשִׂא וְנוֹתִן בֶּאֱמוּנָה וְאָמַר כָּךְ וְכָךְ אֲנִי מִשְׂתַּכֵּר אֵין לוֹ הוֹנָיָה. וַאֲפִלּוּ אָמַר זֶה לָקַחְתִּי בְּסֶלַע וּבְעֶשֶׂר אֲנִי מוֹכֵר מֻתָּר. אֲבָל בֵּית דִּין חַיָּבִין לִפְסֹק הַשְּׁעָרִים וּלְהַעֲמִיד שׁוֹטְרִין לְכָךְ. וְלֹא יִהְיֶה כָּל אֶחָד וְאֶחָד מִשְׂתַּכֵּר כָּל מַה שֶּׁיִּרְצֶה אֶלָּא שְׁתוּת בִּלְבַד יִפְסְקוּ לָהֶם בִּשְׂכָרָם. וְלֹא יִשְׂתַּכֵּר הַמּוֹכֵר יֶתֶר עַל שְׁתוּת:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּדְבָרִים שֶׁיֵּשׁ בָּהֶם חַיֵּי נֶפֶשׁ כְּגוֹן יֵינוֹת שְׁמָנִים וּסְלָתוֹת. אֲבָל הָעִקָּרִין כְּגוֹן הַקֹּשְׁט וְהַלְּבוֹנָה וְכַיּוֹצֵא בָּהֶן אֵין פּוֹסְקִין לָהֶם שַׁעַר אֶלָּא יִשְׂתַּכֵּר כָּל מַה שֶּׁיִּרְצֶה:","וְאֵין מִשְׂתַּכְּרִין פַּעֲמַיִם בְּבֵיצִים אֶלָּא הַתַּגָּר הָרִאשׁוֹן הוּא מוֹכְרָן בְּשָׂכָר וְהַלּוֹקֵחַ מִמֶּנּוּ מוֹכְרָן בְּקֶרֶן בִּלְבַד:","אָסוּר לַעֲשׂוֹת סְחוֹרָה בְּאֶרֶץ יִשְׂרָאֵל בִּדְבָרִים שֶׁיֵּשׁ בָּהֶן חַיֵּי נֶפֶשׁ. אֶלָּא זֶה מֵבִיא מִגָּרְנוֹ וּמוֹכֵר וְזֶה מֵבִיא מִגָּרְנוֹ וּמוֹכֵר כְּדֵי שֶׁיִּמְכְּרֶנּוּ בְּזוֹל. וּבְמָקוֹם שֶׁהַשֶּׁמֶן מְרֻבֶּה מֻתָּר לְהִשְׂתַּכֵּר בְּשֶׁמֶן:","אֵין אוֹצְרִין פֵּרוֹת שֶׁיֵּשׁ בָּהֶן חַיֵּי נֶפֶשׁ בָּאָרֶץ יִשְׂרָאֵל וְכֵן בְּכָל מָקוֹם שֶׁרֻבּוֹ יִשְׂרָאֵל שֶׁהֲרֵי מַגִּיעַ מִדָּבָר זֶה צַעַר לְיִשְׂרָאֵל. בַּמֶּה דְּבָרִים אֲמוּרִים בְּלוֹקֵחַ מִן הַשּׁוּק. אֲבָל הַמַּכְנִיס מִשֶּׁלּוֹ מֻתָּר לַעֲשׂוֹת לוֹ קַבּוֹ אוֹצָר:","מֻתָּר לֶאֱצֹר פֵּרוֹת שָׁלֹשׁ שָׁנִים עֶרֶב שְׁבִיעִית וּשְׁבִיעִית וּמוֹצָאֵי שְׁבִיעִית. וּבִשְׁנֵי בַּצֹּרֶת אֲפִלּוּ קַב חָרוּבִין לֹא יֶאֱצֹר מִפְּנֵי שֶׁמַּכְנִיס מְאֵרָה בַּשְּׁעָרִים. וְכָל הַמַּפְקִיעַ שְׁעָרִים אוֹ שֶׁאָצַר פֵּרוֹת בָּאָרֶץ אוֹ בְּמָקוֹם שֶׁרֻבּוֹ יִשְׂרָאֵל הֲרֵי זֶה כְּמַלְוֶה בְּרִבִּית:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּפֵרוֹת שֶׁיֵּשׁ בָּהֶן חַיֵּי נֶפֶשׁ. אֲבָל הַתַּבְלִין כְּגוֹן כַּמּוֹן וּפִלְפְּלִין מֻתָּר לֶאֱצֹר אוֹתָן בְּאֶרֶץ יִשְׂרָאֵל וּלְהוֹצִיא אוֹתָן מִמָּקוֹם לְמָקוֹם כִּשְׁאָר הָעִקָּרִין:","אֵין מוֹצִיאִין פֵּרוֹת שֶׁיֵּשׁ בָּהֶן חַיֵּי נֶפֶשׁ כְּגוֹן יֵינוֹת שְׁמָנִים וּסְלָתוֹת מֵאֶרֶץ יִשְׂרָאֵל לְחוּצָה לָאָרֶץ אוֹ לְסוּרְיָא. וְלֹא מֵרְשׁוּת מֶלֶךְ זֶה לִרְשׁוּת מֶלֶךְ אַחֵר בְּאֶרֶץ יִשְׂרָאֵל:","רַשָּׁאִין בְּנֵי הָעִיר לָקֹץ לָהֶם שַׁעַר לְכָל דָּבָר שֶׁיִּרְצוּ וַאֲפִלּוּ בָּשָׂר וְלֶחֶם וּלְהַתְנוֹת בֵּינֵיהֶם לְכָל מִי שֶׁיַּעֲבֹר יַעַנְשׁוּ אוֹתוֹ כָּךְ וְכָךְ:","רַשָּׁאִין אַנְשֵׁי אֻמָּנֻיּוֹת לִפְסֹק בֵּינֵיהֶם שֶׁלֹּא יַעֲשֶׂה אֶחָד בְּיוֹם שֶׁיַּעֲשֶׂה חֲבֵרוֹ וְכַיּוֹצֵא בָּזֶה וְכָל מִי שֶׁיַּעֲבֹר עַל הַתְּנַאי יַעַנְשׁוּ אוֹתוֹ כָּךְ וְכָךְ:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּמְדִינָה שֶׁאֵין בָּהּ חָכָם חָשׁוּב לְתַקֵּן מַעֲשֵׂה הַמְּדִינָה וּלְהַצְלִיחַ דַּרְכֵי יוֹשְׁבֶיהָ. אֲבָל אִם יֵשׁ בָּהּ אָדָם חָכָם חָשׁוּב אֵין הַתְּנַאי שֶׁלָּהֶן מוֹעִיל כְּלוּם וְאֵין יְכוֹלִין לַעֲנשׁ וּלְהַפְסִיד עַל מִי שֶׁלֹּא קִבֵּל הַתְּנַאי אֶלָּא אִם כֵּן הִתְנָה עִמָּהֶם וְעָשׂוּ מִדַּעַת הֶחָכָם. וְכָל מִי שֶׁהִפְסִיד לְפִי הַתְּנַאי שֶׁאֵינוֹ מִדַּעַת הֶחָכָם מְשַׁלֵּם:","כְּשֵׁם שֶׁהוֹנָיָה בְּמִקָּח וּמִמְכָּר כָּךְ יֵשׁ הוֹנָיָה בִּדְבָרִים שֶׁנֶּאֱמַר (ויקרא כה יז) \"וְלֹא תוֹנוּ אִישׁ אֶת עֲמִיתוֹ וְיָרֵאתָ מֵאֱלֹהֶיךָ אֲנִי ה'\". זֶה הוֹנָיַת דְּבָרִים:","כֵּיצַד. הָיָה בַּעַל תְּשׁוּבָה לֹא יֹאמַר לוֹ זְכֹר מַעֲשֶׂיךָ הָרִאשׁוֹנִים. וְאִם הָיָה בֶּן גֵּרִים לֹא יֹאמַר לוֹ זְכֹר מַעֲשֵׂה אֲבוֹתֶיךָ. הָיָה גֵּר וּבָא לִלְמֹד תּוֹרָה לֹא יֹאמַר לוֹ פֶּה שֶׁאָכַל נְבֵלוֹת וּטְרֵפוֹת יָבוֹא וְיִלְמֹד תּוֹרָה שֶׁנִּתְּנָה מִפִּי הַגְּבוּרָה. הָיוּ חֳלָאִים וְיִסּוּרִים בָּאִין עָלָיו אוֹ שֶׁהָיָה מְקַבֵּר אֶת בָּנָיו. לֹא יֹאמַר לוֹ כְּדֶרֶךְ שֶׁאָמְרוּ חֲבֵרָיו לְאִיּוֹב (איוב ד ו) \"הֲלֹא יִרְאָתְךָ כִּסְלָתֶךָ\" (איוב ד ז) \"זְכָר נָא מִי הוּא נָקִי אָבָד\":","הָיוּ חַמָּרִין מְבַקְּשִׁין תְּבוּאָה לֹא יֹאמַר לָהֶם לְכוּ אֵצֶל פְּלוֹנִי וְהוּא יוֹדֵעַ שֶׁלֹּא מָכַר תְּבוּאָה מֵעוֹלָם. נִשְׁאֲלָה שְׁאֵלָה עַל דְּבַר חָכְמָה לֹא יֹאמַר לְמִי שֶׁאֵינוֹ יוֹדֵעַ אוֹתָהּ חָכְמָה מַה תָּשִׁיב בְּדָבָר זֶה אוֹ מַה דַּעְתְּךָ בְּדָבָר זֶה. וְכֵן כָּל כַּיּוֹצֵא בִּדְבָרִים הַלָּלוּ:","כָּל הַמְאַנֶּה אֶת הַגֵּר בֵּין בְּמָמוֹן בֵּין בִּדְבָרִים עוֹבֵר בִּשְׁלֹשָׁה לָאוִין. שֶׁנֶּאֱמַר (שמות כב כ) \"וְגֵר לֹא תוֹנֶה\" זֶה הוֹנָיַת דְּבָרִים. (שמות כב כ) \"וְלֹא תִלְחָצֶנּוּ\" זֶה הוֹנָיַת מָמוֹן. הָא לָמַדְתָּ שֶׁכָּל הַמְּאַנֶּה אֶת הַגֵּר עוֹבֵר בִּשְׁלֹשָׁה לָאוִין. מִשּׁוּם (ויקרא כה יז) \"לֹא תוֹנוּ אִישׁ אֶת עֲמִיתוֹ\". וּמִשּׁוּם (ויקרא כה יד) \"אַל תּוֹנוּ אִישׁ אֶת אָחִיו\". וּמִשּׁוּם וְגֵר לֹא תוֹנֶה:","וְכֵן אִם לְחָצוֹ וְהוֹנָהוּ בְּמָמוֹן עוֹבֵר בִּשְׁלֹשָׁה לָאוִין. מִשּׁוּם (ויקרא כה יד) \"אַל תּוֹנוּ אִישׁ אֶת אָחִיו\". וּמִשּׁוּם (ויקרא כה יז) \"וְלֹא תוֹנוּ אִישׁ אֶת עֲמִיתוֹ\". וּמִשּׁוּם (שמות כב כ) \"וְלֹא תִלְחָצֶנּוּ\":","וּמִפְּנֵי מָה עוֹבֵר בְּגֵר עַל לָאו שֶׁל הוֹנָיַת דְּבָרִים אַף בַּהֲנָיַת מָמוֹן. וְעַל לָאו שֶׁל הוֹנָיַת מָמוֹן אַף בְּהוֹנָאַת דְּבָרִים. מִפְּנֵי שֶׁהוֹצִיא הַכָּתוּב אֶת שְׁנֵיהֶם בִּלְשׁוֹן הוֹנָיָה סְתָם. וְכָפַל לָאוִין בְּגֵר בִּשְׁנֵי הַדְּבָרִים בְּפֵרוּשׁ. לֹא תוֹנוּ וְלֹא תִלְחָץ:","גְּדוֹלָה הוֹנָיַת דְּבָרִים מֵהוֹנָיַת מָמוֹן. שֶׁזֶּה נִתָּן לְהִשָּׁבוֹן וְזֶה לֹא נִתָּן לְהִשָּׁבוֹן. וְזֶה בְּמָמוֹנוֹ וְזֶה בְּגוּפוֹ. וַהֲרֵי הוּא אוֹמֵר בְּהוֹנָיַת דְּבָרִים (ויקרא כה יז) \"וְיָרֵאתָ מֵאֱלֹהֶיךָ\" לְפִי שֶׁהַדָּבָר מָסוּר לַלֵּב. הָא לָמַדְתָּ כָּל דָּבָר שֶׁהוּא מָסוּר לַלֵּב נֶאֱמַר בּוֹ וְיָרֵאתָ מֵאֱלֹהֶיךָ. וְכָל הַצּוֹעֵק מֵהוֹנָיַת דְּבָרִים נַעֲנֶה מִיָּד שֶׁנֶּאֱמַר (ויקרא כה יז) \"כִּי אֲנִי ה'\":"],"Mishneh Torah, Sales 25":["הַמּוֹכֵר דָּבָר שֶׁיֵּשׁ לוֹ תַּשְׁמִישִׁין לֹא מָכַר אֶת הַתַּשְׁמִישִׁין אֶלָּא אִם כֵּן פֵּרֵשׁ. כֵּיצַד. מָכַר אֶת הַבַּיִת לֹא מָכַר אֶת הַיָּצִיעַ שֶׁסְּבִיבוֹת הַבַּיִת אַף עַל פִּי שֶׁהוּא פָּתוּחַ לְתוֹכוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה רֹחַב הַיָּצִיעַ אַרְבַּע אַמּוֹת אוֹ יֶתֶר. אֲבָל פָּחוֹת מִזֶּה הֲרֵי הוּא בִּכְלַל הַבַּיִת. וְכֵן הָעֲלִיָּה שֶׁעַל גַּבֵּי הַבַּיִת הַפְּתוּחָה לְתוֹכוֹ בָּאֲרֻבָּה בְּמֵעֲזִיבַת הַבַּיִת הֲרֵי הוּא בִּכְלַל הַבַּיִת:","הַמּוֹכֵר אֶת הַבַּיִת לֹא מָכַר אֶת הַחֶדֶר שֶׁלְּפָנִים מִמֶּנּוּ. אַף עַל פִּי שֶׁמֵּצֵר לוֹ מְצָרִים הַחִיצוֹנִים. וְלֹא אֶת הַגַּג בִּזְמַן שֶׁיֵּשׁ לוֹ מַעֲקֵה עֲשָׂרָה טְפָחִים וְיֵשׁ בּוֹ רֹחַב אַרְבַּע אַמּוֹת. וְלֹא אֶת הַבּוֹר הֶחָפוּר בַּקַּרְקַע וְלֹא אֶת הַדּוּת הַבָּנוּי בַּבּוֹר אַף עַל פִּי שֶׁמָּכַר לוֹ הָעֹמֶק וְהָרוּם כְּמוֹ שֶׁבֵּאַרְנוּ:","וְצָרִיךְ הַמּוֹכֵר לִקְנוֹת לוֹ דֶּרֶךְ מִן הַלּוֹקֵחַ כְּדֵי לְהִכָּנֵס בְּבוֹר זֶה אוֹ לַדּוּת שֶׁשִּׁיֵּר. שֶׁכָּל הַמּוֹכֵר בְּעַיִן יָפָה מוֹכֵר. וְאִם אָמַר לוֹ מָכַרְתִּי לְךָ הַבַּיִת חוּץ מִן הַבּוֹר אוֹ הַדּוּת אֵין צָרִיךְ לִקְנוֹת לוֹ דֶּרֶךְ. וְכֵן הַמּוֹכֵר בּוֹר אוֹ דּוּת בִּלְבַד אֵין הַלּוֹקֵחַ צָרִיךְ לִקְנוֹת לוֹ דֶּרֶךְ אֶלָּא נִכְנָס לְתוֹךְ בֵּיתוֹ שֶׁל מוֹכֵר עַד הַדּוּת וּמְמַלֵּא:","שְׁנֵי בָּתִּים זֶה לְפָנִים מִזֶּה. מָכַר שְׁנֵיהֶם לִשְׁנַיִם אוֹ נָתַן שְׁנֵיהֶם לִשְׁנַיִם אֵין לָהֶם דֶּרֶךְ זֶה עַל זֶה. וְאֵין צָרִיךְ לוֹמַר אִם נָתַן הַחִיצוֹן וּמָכַר הַפְּנִימִי. אֲבָל אִם מָכַר הַחִיצוֹן וְנָתַן הַפְּנִימִי יֵשׁ לוֹ דֶּרֶךְ שֶׁכָּל הַנּוֹתֵן בְּעַיִן יָפָה נוֹתֵן יוֹתֵר מִן הַמּוֹכֵר:","הַמּוֹכֵר אֶת הַבַּיִת מָכַר אֶת הַתַּנּוּר וְאֶת הַכִּירַיִם וְאֶת מַלְבְּנוֹת הַפְּתָחִים הַמְחֻבָּרִין בְּטִיט וְאֶת הַדֶּלֶת וְאֶת הַנֶּגֶר וְאֶת הַמַּנְעוּל אֲבָל לֹא הַמַּפְתֵּחַ. וּמָכַר אֶת הַמַּכְתֶּשֶׁת הַקְּבוּעָה אֲבָל לֹא אֶת הַמִּטַלְטֶּלֶת. וּמָכַר אֶת הָאִיצְטְרוֹבִיל אֲבָל לֹא אֶת הַכְּלִי שֶׁהַקֶּמַח יוֹרֵד לְתוֹכוֹ שֶׁהוּא כְּמוֹ כְּפִיפָה שֶׁל עֵץ. וְלֹא מָכַר אֶת מַלְבְּנוֹת כִּרְעֵי הַמִּטָּה וְלֹא אֶת מַלְבְּנוֹת הַחַלּוֹנוֹת אַף עַל פִּי שֶׁהֵן מְחֻבָּרִין בְּטִיט מִפְּנֵי שֶׁהֵן לְנוֹי. וּבִזְמַן שֶׁאָמַר הוּא וְכָל מַה שֶּׁבְּתוֹכוֹ הֲרֵי כֻּלָּן מְכוּרִין:","הַמּוֹכֵר אֶת הֶחָצֵר מָכַר בּוֹרוֹת שִׁיחִין וּמְעָרוֹת שֶׁבְּתוֹכָהּ. וְכָל הַבָּתִּים הַחִיצוֹנִים וְהַפְּנִימִים וּבָתִּים שֶׁיֵּשׁ בָּהֶן הַחל וְהַחֲנֻיּוֹת הַפְּתוּחוֹת לְתוֹכָהּ. אֲבָל שֶׁאֵינָן פְּתוּחוֹת לְתוֹכָהּ אֵינָם נִמְכָּרִים עִמָּהּ. הָיוּ פְּתוּחוֹת לְכָאן וּלְכָאן אִם רֹב תַּשְׁמִישָׁן לְתוֹכָהּ נִמְכָּרוֹת עִמָּהּ וְאִם לָאו אֵינָן נִמְכָּרוֹת עִמָּהּ. וְלֹא מָכַר אֶת הַמִּטַּלְטְלִין שֶׁבְּתוֹכָהּ. וּבַזְּמַן שֶׁאָמַר הִיא וְכָל מַה שֶּׁבְּתוֹכָהּ הֲרֵי כֻּלָּם מְכוּרִין. בֵּין כָּךְ וּבֵין כָּךְ לֹא מָכַר אֶת הַמֶּרְחָץ וְלֹא בֵּית הַבַּד שֶׁבְּתוֹכָהּ:","הַמּוֹכֵר אֶת בֵּית הַבַּד מָכַר אֶת הָאֶבֶן הַגְּדוֹלָה הַבְּנוּיָה בָּאָרֶץ שֶׁטּוֹחֲנִים עָלֶיהָ זֵיתִים. וְאֶת הַכְּלֻנְסָאוֹת שֶׁל אֶרֶז שֶׁסּוֹמְכִין בָּהֶן בְּעֵת טְחִינַת הַזֵּיתִים. וְאֶת הַיְקָבִים וְאֶת הַכֵּלִים שֶׁנּוֹתְנִין בָּהֶן אֶת הַזֵּיתִים הַכְּתוּשִׁין וְהֵם הַמְפָרְכוֹת. אֲבָל לֹא מָכַר אֶת הָרֵחָיִם הָעֶלְיוֹנָה. וּבִזְמַן שֶׁאָמַר הוּא וְכָל מַה שֶּׁבְּתוֹכוֹ הֲרֵי כֻּלָּן מְכוּרִין. בֵּין כָּךְ וּבֵין כָּךְ לֹא מָכַר אֶת הַכּוֹבְשִׁין שֶׁמְּכַבְּשִׁין בָּהֶן הַזֵּיתִים וְלֹא אֶת הַגַּלְגַּל וְלֹא אֶת הַקּוֹרָה וְלֹא אֶת הַשַּׂקִּין וְלֹא אֶת הַמַּרְצוּפִין:","אָמַר לוֹ בֵּית הַבַּד וְכָל תַּשְׁמִישָׁיו אֲנִי מוֹכֵר לְךָ כֻּלָּן מְכוּרִין. הָיוּ חוּצָה לָהּ חֲנֻיּוֹת שֶׁשּׁוֹטְחִים בָּהֶן הַזֵּיתִים אוֹ הַשֻּׁמְשְׁמִין. אִם מֵצֵר לוֹ מְצָרִים הַחִיצוֹנִים שֶׁלָּהֶן קָנָה הַכּל. וְאִם לָאו לֹא קָנָה אֶלָּא מַה שֶּׁבְּתוֹכָהּ:","המוֹכֵר אֶת הַמֶּרְחָץ מָכַר אֶת בֵּית הַנְּסָרִים שֶׁיּוֹשְׁבִין עֲלֵיהֶן כְּשֶׁהֵן עֲרֻמִּים. וְאֶת בֵּית הַיְקָמִים שֶׁנּוֹטְלִין בָּהֶן הַמַּיִם. וְאֶת בֵּית הַסַּפְסָלִין שֶׁיּוֹשְׁבִין עֲלֵיהֶן בַּחֲצַר הַמֶּרְחָץ כְּשֶׁהֵן לְבוּשִׁים. וְאֶת בֵּית הַוִּילָאוֹת שֶׁמִּסְתַּפְּגִין בָּהֶן. אֲבָל לֹא מָכַר אֶת הַנְּסָרִים עַצְמָן וְאֶת הַיְּקָמִים עַצְמָן וְלֹא אֶת הַסַּפְסָלִין עַצְמָן וְלֹא אֶת בֵּית הַוִּילָאוֹת עַצְמָן. וּבִזְמַן שֶׁאָמַר לוֹ הוּא וְכָל מַה שֶּׁבְּתוֹכוֹ הֲרֵי כֻּלָּן מְכוּרִין. בֵּין כָּךְ וּבֵין כָּךְ לֹא מָכַר הַבְּרֵכוֹת הַמְסַפְּקוֹת לוֹ מַיִם בֵּין בִּימוֹת הַחַמָּה בֵּין בִּימוֹת הַגְּשָׁמִים. וְלֹא בֵּית כִּנּוּס הָעֵצִים. וְאִם אָמַר לוֹ מֶרְחָץ וְכָל תַּשְׁמִישָׁיו אֲנִי מוֹכֵר לְךָ הֲרֵי הֵן כֻּלָּן מְכוּרִין אַף עַל פִּי שֶׁהֵן חוּצָה לוֹ:"],"Mishneh Torah, Sales 9":["הַמּוֹכֵר לַהֶקְדֵּשׁ וְאָמַר לוֹ הַגִּזְבָּר בְּכַמָּה אַתָּה מוֹכֵר חֵפֶץ זֶה וְאָמַר בַּעֲשָׂרָה אֲפִלּוּ הָיָה שָׁוֶה מֵאָה כֵּיוָן שֶׁאָמַר בַּעֲשָׂרָה אֵינוֹ [יָכוֹל] לַחְזֹר בּוֹ. שֶׁאֲמִירָה לְגָבוֹהַּ כִּמְסִירָה לְהֶדְיוֹט:","הַגִּזְבָּר שֶׁקָּנָה לַהֶקְדֵּשׁ אוֹ שֶׁמָּכַר יָדוֹ עַל הָעֶלְיוֹנָה. כֵּיצַד. נָתַן דָּמִים שֶׁל הֶקְדֵּשׁ אַף עַל פִּי שֶׁלֹּא מָשַׁךְ הַפֵּרוֹת אִם הוּקְרוּ קָנָה כְּדִין תּוֹרָה. וְאִם הוּזְלוּ הַפֵּרוֹת חוֹזֵר שֶׁהֲרֵי לֹא מָשַׁךְ. וְלֹא יְהֵא כֹּחַ הֶדְיוֹט חָמוּר מִכֹּחַ הַהֶקְדֵּשׁ. וְכֵן אִם מָכַר חֵפֶץ שֶׁל הֶקְדֵּשׁ וּמְשָׁכוֹ הַלּוֹקֵחַ וְלֹא נָתַן דָּמִים וְהוּזַל הַחֵפֶץ קָנָה. שֶׁלֹּא יְהֵא כֹּחַ הֶדְיוֹט חָמוּר מִכֹּחַ הֶקְדֵּשׁ. וְאִם הוּקַר הַחֵפֶץ חוֹזֵר בּוֹ שֶׁהֲרֵי לֹא לָקַח הַגִּזְבָּר דָּמִים. וְהַהֶקְדֵּשׁ אֵינוֹ נִקְנֶה אֶלָּא בְּכֶסֶף שֶׁנֶּאֱמַר וְנָתַן הַכֶּסֶף וְקָם לוֹ. וְאֵין הַגִּזְבָּר חַיָּב לְקַבֵּל מִי שֶׁפָּרַע:","נִכְסֵי יְתוֹמִים הֲרֵי הֵן כְּהֶקְדֵּשׁ. כֵּיצַד. יְתוֹמִים שֶׁמָּכְרוּ פֵּרוֹת וְנִמְשְׁכוּ מֵהֶן הַפֵּרוֹת וַעֲדַיִן לֹא לָקְחוּ הַדָּמִים וְהוּקְרוּ הַפֵּרוֹת חוֹזְרִין בָּהֶן. שֶׁאֵין נִכְסֵי יְתוֹמִים נִקְנִין אֶלָּא בְּכֶסֶף כְּהֶקְדֵּשׁ. הוּזְלוּ הַפֵּרוֹת לֹא יִהְיֶה כֹּחַ הֶדְיוֹט יוֹתֵר חָמוּר מִכֹּחָן:","וְכֵן אִם לָקְחוּ הַדָּמִים וַעֲדַיִן לֹא נִמְשְׁכוּ פֵּרוֹתֵיהֶן וְהוּקְרוּ. חוֹזְרִין כִּשְׁאָר הַהֶדְיוֹטוֹת. אֲבָל אִם הוּזְלוּ הַפֵּרוֹת וְרָצוּ הַלָּקוֹחוֹת לַחְזֹר בָּהֶן. חוֹזְרִין וּמְקַבְּלִין מִי שֶׁפָּרַע כְּדִינָם עִם שְׁאָר הָעָם. שֶׁאִם נְחַיֵּב אוֹתָם לִקַּח הַפֵּרוֹת כְּדִין תּוֹרָה הֲרֵי זוֹ רָעָה לַיְתוֹמִים. שֶׁאִם יִהְיֶה דִּינָם כָּךְ כְּשֶׁיִּצְטָרְכוּ לִמְכֹּר לֹא יִמְצְאוּ מִי יִתֵּן לָהֶם דָּמִים:","וְכֵן יְתוֹמִים שֶׁלָּקְחוּ פֵּרוֹת וּמָשְׁכוּ הַפֵּרוֹת וְלֹא נָתְנוּ הַדָּמִים וְהוּקְרוּ לֹא יִהְיֶה כֹּחַ הֶדְיוֹט גָּדוֹל מִכֹּחָן. וְאִם הוּזְלוּ הַפֵּרוֹת אֵינָן חוֹזְרִין. שֶׁזּוֹ רָעָה לָהֶם כְּשֶׁיִּצְטָרְכוּ לִקְנוֹת פֵּרוֹת לֹא יִמְצְאוּ מִי שֶׁיִּמְכֹּר לָהֶם:","נָתְנוּ הַדָּמִים וְלֹא מָשְׁכוּ הַפֵּרוֹת וְהֻזְּלוּ הַפֵּרוֹת חוֹזְרִין. לֹא יִהְיֶה כֹּחַ הֶדְיוֹט גָּדוֹל מִכֹּחָן. הוּקְרוּ אִם רָצוּ הַמּוֹכְרִים לַחְזֹר בָּהֶן חוֹזְרִין וּמְקַבְּלִין מִי שֶׁפָּרַע. שֶׁאִם יִהְיֶה דִּינָם שֶׁיִּקְנוּ בִּנְתִינַת הַמָּעוֹת יֹאמַר לָהֶם הַמּוֹכֵר נִשְׂרְפוּ הַפֵּרוֹת שֶׁלְּקַחְתֶּם אוֹ אָבְדוּ בְּאֹנֶס וּכְבָר נַעֲשׂוּ בִּרְשׁוּתְכֶם מִשְּׁעַת נְתִינַת הַמָּעוֹת:","בְּאַרְבָּעָה פְּרָקִים בַּשָּׁנָה הֶעֱמִידוּ דִּבְרֵיהֶם עַל דִּין תּוֹרָה בְּבָשָׂר מִפְּנֵי שֶׁהָעָם כֻּלָּן צְרִיכִין לְבָשָׂר. וְאֵלּוּ הֵן. עֶרֶב יוֹם טוֹב הָאַחֲרוֹן שֶׁל חַג. וְעֶרֶב יוֹם טוֹב הָרִאשׁוֹן שֶׁל פֶּסַח. וְעֶרֶב הָעֲצֶרֶת. וְעֶרֶב רֹאשׁ הַשָּׁנָה. כֵּיצַד. הָיָה לַטַּבָּח שׁוֹר אֲפִלּוּ שָׁוֶה מֵאָה דִּינָרִין וְלָקַח דִּינָר אֶחָד מִן הַלּוֹקֵחַ כְּדֵי לִתֵּן לוֹ בָּשָׂר כְּשֶׁיִּשְׁחֹט וְלֹא נִתְקַבְּצוּ לוֹ כָּל דְּמֵי הַשּׁוֹר אֵינוֹ יָכוֹל לַחְזֹר בּוֹ. אֶלָּא מַשְׁחִיטִין אֶת הַטַּבָּח בַּעַל כָּרְחוֹ. וְכוֹפִין אוֹתוֹ לִשְׁחֹט וְלִתֵּן הַבָּשָׂר לַלּוֹקֵחַ. לְפִיכָךְ אִם מֵת הַשּׁוֹר מֵת לַלּוֹקֵחַ:"],"Mishneh Torah, Sanctification of the New Month 2":["אֵין כָּשֵׁר לְעֵדוּת הַחֹדֶשׁ אֶלָּא שְׁנֵי אֲנָשִׁים כְּשֵׁרִים הָרְאוּיִין לְהָעִיד בְּכָל דָּבָר וְדָבָר. אֲבָל נָשִׁים וַעֲבָדִים הֲרֵי הֵן כִּשְׁאָר פְּסוּלֵי עֵדוּת וְאֵין מְעִידִין. אָב וּבְנוֹ שֶׁרָאוּ אֶת הַיָּרֵחַ יֵלְכוּ לְבֵית דִּין לְהָעִיד. לֹא מִפְּנֵי שֶׁעֵדוּת הַחֹדֶשׁ כְּשֵׁרָה בִּקְרוֹבִים אֶלָּא שֶׁאִם יִמָּצֵא אֶחָד מֵהֶן פָּסוּל מִפְּנֵי שֶׁהוּא גַּזְלָן וְכַיּוֹצֵא בּוֹ מִשְּׁאָר הַפַּסְלָנוּת יִצְטָרֵף הַשֵּׁנִי עִם אַחֵר וְיָעִידוּ. וְכָל הַפָּסוּל לְעֵדוּת מִדִּבְרֵי סוֹפְרִים אַף עַל פִּי שֶׁהוּא כָּשֵׁר מִן הַתּוֹרָה פָּסוּל לְעֵדוּת הַחֹדֶשׁ:","דִּין תּוֹרָה שֶׁאֵין מְדַקְדְּקִין בְּעֵדוּת הַחֹדֶשׁ. שֶׁאֲפִלּוּ קִדְּשׁוּ אֶת הַחֹדֶשׁ עַל פִּי עֵדִים וְנִמְצְאוּ זוֹמְמִין בְּעֵדוּת זוֹ הֲרֵי זֶה מְקֻדָּשׁ. לְפִיכָךְ הָיוּ בָּרִאשׁוֹנָה מְקַבְּלִין עֵדוּת הַחֹדֶשׁ מִכָּל אָדָם מִיִּשְׂרָאֵל שֶׁכָּל יִשְׂרָאֵל בְּחֶזְקַת כַּשְׁרוּת עַד שֶׁיִּוָּדַע לְךָ שֶׁזֶּה פָּסוּל. מִשֶּׁקִּלְקְלוּ הַבַּיְתוֹסִים וְהָיוּ שׂוֹכְרִין אֲנָשִׁים לְהָעִיד שֶׁרָאוּ וְהֵם לֹא רָאוּ הִתְקִינוּ שֶׁלֹּא יְקַבְּלוּ בֵּית דִּין עֵדוּת הַחֹדֶשׁ אֶלָּא מֵעֵדִים שֶׁמַּכִּירִין בֵּית דִּין אוֹתָן שֶׁהֵם כְּשֵׁרִים וְשֶׁיִּהְיוּ דּוֹרְשִׁין וְחוֹקְרִים בָּעֵדוּת:","לְפִיכָךְ אִם לֹא יִהְיוּ בֵּית דִּין יוֹדְעִים אֶת הָעֵדִים שֶׁרָאוּ אֶת הַיָּרֵחַ מְשַׁלְּחִין אַנְשֵׁי הָעִיר שֶׁנִּרְאָה בָּהּ עִם הָעֵדִים שֶׁרָאוּ עֵדִים אֲחֵרִים שֶׁמְּזַכִּין אוֹתָן לְבֵית דִּין וּמוֹדִיעִין אוֹתָן שֶׁאֵלּוּ כְּשֵׁרִים הֵם וְאַחַר כָּךְ מְקַבְּלִין מֵהֶם:","בֵּית דִּין מְחַשְּׁבִין בַּדְּרָכִים שֶׁהָאִיצְטַגְנִינִין מְחַשְּׁבִין בָּהֶם וְיוֹדְעִין הַלְּבָנָה כְּשֶׁתֵּרָאֶה בְּחֹדֶשׁ זֶה אִם תִּהְיֶה בִּצְפוֹן הַשֶּׁמֶשׁ אוֹ בִּדְרוֹמָהּ וְאִם תִּהְיֶה רְחָבָה אוֹ קְצָרָה וּלְהֵיכָן יִהְיוּ רָאשֵׁי קַרְנֶיהָ נוֹטִין. וּכְשֶׁיָּבוֹאוּ הָעֵדִים לְהָעִיד בּוֹדְקִין אוֹתָם כֵּיצַד רְאִיתֶם אוֹתָהּ בְּצָפוֹן אוֹ בְּדָרוֹם. לְהֵיכָן הָיוּ קַרְנֶיהָ נוֹטוֹת. כַּמָּה הָיְתָה גְּבוֹהָה בִּרְאִיַּת עֵינֵיכֶם וְכַמָּה הָיְתָה רְחָבָה. אִם נִמְצְאוּ דִּבְרֵיהֶם מְכֻוָּנִין לְמַה שֶּׁנּוֹדַע בַּחֶשְׁבּוֹן מְקַבְּלִין אוֹתָם וְאִם לֹא נִמְצְאוּ דִּבְרֵיהֶם מְכֻוָּנִין אֵין מְקַבְּלִין אוֹתָם:","אָמְרוּ הָעֵדִים רְאִינוּהוּ בַּמַּיִם אוֹ בֶּעָבִים אוֹ בַּעֲשָׁשִׁית. אוֹ שֶׁרָאוּ מִקְצָתוֹ בָּרָקִיעַ וּמִקְצָתוֹ בֶּעָבִים אוֹ בַּמַּיִם אוֹ בַּעֲשָׁשִׁית אֵין זוֹ רְאִיָּה וְאֵין מְקַדְּשִׁין עַל רְאִיָּה זֹאת. אָמַר אֶחָד רְאִיתִיו גָּבוֹהַּ בְּעֵינַי כְּמוֹ שְׁתֵּי קוֹמוֹת וְאָמַר הַשֵּׁנִי כְּמוֹ שָׁלֹשׁ קוֹמוֹת הָיָה גָּבוֹהַּ מִצְטָרְפִין. אָמַר הָאֶחָד כְּמוֹ שָׁלֹשׁ קוֹמוֹת וְהַשֵּׁנִי אוֹמֵר כְּמוֹ חָמֵשׁ אֵין מִצְטָרְפִין. וּמִצְטָרֵף אֶחָד מֵהֶם עִם שֵׁנִי שֶׁיָּעִיד כְּמוֹתוֹ אוֹ יִהְיֶה בֵּינֵיהֶן קוֹמָה אַחַת:","אָמְרוּ רְאִינוּהוּ בְּלֹא כַּוָּנָה וְכֵיוָן שֶׁהִתְבּוֹנַנְנוּ בּוֹ וְנִתְכַּוַּנְנוּ לִרְאוֹתוֹ לְהָעִיד שׁוּב לֹא רְאִינוּהוּ אֵין זוֹ עֵדוּת וְאֵין מְקַדְּשִׁין עָלֶיהָ. שֶׁמָּא עָבִים נִתְקַשְּׁרוּ וְנִרְאוּ כַּלְּבָנָה וְכָלוּ וְהָלְכוּ לָהֶם. אָמְרוּ עֵדִים רְאִינוּהוּ בְּיוֹם תִּשְׁעָה וְעֶשְׂרִים שַׁחֲרִית בַּמִּזְרָח קֹדֶם שֶׁתַּעֲלֶה הַשֶּׁמֶשׁ וּרְאִינוּהוּ עַרְבִית בַּמַּעֲרָב בְּלֵיל שְׁלֹשִׁים הֲרֵי אֵלּוּ נֶאֱמָנִים וּמְקַדְּשִׁין עַל רְאִיָּה זוֹ שֶׁהֲרֵי רָאוּהוּ בִּזְמַנּוֹ. אֲבָל הָרְאִיָּה שֶׁאָמְרוּ שֶׁרָאוּהוּ בְּשַׁחֲרִית אֵין נִזְקָקִין לָהּ שֶׁאֵין אָנוּ אַחְרָאִין לִרְאִיַּת שַׁחֲרִית וּבְיָדוּעַ שֶׁהֶעָבִים הֵם שֶׁנִּתְקַשְּׁרוּ וְנִרְאָה לָהֶם כִּלְבָנָה. וְכֵן אִם רָאוּהוּ בִּזְמַנּוֹ וּבְלֵיל עִבּוּרוֹ לֹא נִרְאָה הֲרֵי אֵלּוּ נֶאֱמָנִין שֶׁאֵין אָנוּ אַחְרָאִין אֶלָּא לִרְאִיַּת לֵיל שְׁלֹשִׁים בִּלְבַד:","כֵּיצַד מְקַבְּלִין עֵדוּת הַחֹדֶשׁ. כָּל מִי שֶׁרָאוּי לְהָעִיד שֶׁרָאָה אֶת הַיָּרֵחַ בָּא לְבֵית דִּין. וּבֵית דִּין מַכְנִיסִים אוֹתָן כֻּלָּן לְמָקוֹם אֶחָד וְעוֹשִׂין לָהֶן סְעֻדּוֹת גְּדוֹלוֹת כְּדֵי שֶׁיִּהְיוּ הָעָם רְגִילִין לָבוֹא. וְזוּג שֶׁבָּא רִאשׁוֹן בּוֹדְקִין אוֹתָן רִאשׁוֹן בַּבְּדִיקוֹת שֶׁאָמַרְנוּ. מַכְנִיסִין אֶת הַגָּדוֹל וְשׁוֹאֲלִין אוֹתוֹ. נִמְצְאוּ דְּבָרָיו מְכֻוָּנִים לַחֶשְׁבּוֹן מַכְנִיסִים אֶת חֲבֵרוֹ. נִמְצְאוּ דִּבְרֵיהֶם מְכֻוָּנִין עֵדוּתָן קַיֶּמֶת. וּשְׁאָר כָּל הַזּוּגוֹת שׁוֹאֲלִין אוֹתָם רָאשֵׁי דְּבָרִים. לֹא שֶׁצְּרִיכִים לָהֶם אֶלָּא כְּדֵי שֶׁלֹּא יֵצְאוּ בְּפַחֵי נֶפֶשׁ, כְּדֵי שֶׁיִּהְיוּ רְגִילִין לָבוֹא:","וְאַחַר כָּךְ אַחַר שֶׁתִּתְקַיֵּם הָעֵדוּת רֹאשׁ בֵּית דִּין אוֹמֵר מְקֻדָּשׁ וְכָל הָעָם עוֹנִים אַחֲרָיו מְקֻדָּשׁ מְקֻדָּשׁ. וְאֵין מְקַדְּשִׁין אֶת הַחֹדֶשׁ אֶלָּא בִּשְׁלֹשָׁה. וְאֵין מְחַשְּׁבִין אֶלָּא בִּשְׁלֹשָׁה. וְאֵין מְקַדְּשִׁין אֶלָּא חֹדֶשׁ שֶׁנִּרְאֶה בִּזְמַנּוֹ. וְאֵין מְקַדְּשִׁין אֶלָּא בַּיּוֹם וְאִם קִדְּשׁוּהוּ בַּלַּיְלָה אֵינוֹ מְקֻדָּשׁ. ואֲפִלּוּ רָאוּהוּ בֵּית דִּין וְכָל יִשְׂרָאֵל וְלֹא אָמְרוּ בֵּית דִּין מְקֻדָּשׁ עַד שֶׁחָשְׁכָה לֵיל אֶחָד וּשְׁלֹשִׁים. אוֹ שֶׁנֶּחְקְרוּ הָעֵדִים וְלֹא הִסְפִּיקוּ בֵּית דִּין לוֹמַר מְקֻדָּשׁ עַד שֶׁחָשְׁכָה לֵיל אֶחָד וּשְׁלֹשִׁים. אֵין מְקַדְּשִׁין אוֹתוֹ וְיִהְיֶה הַחֹדֶשׁ מְעֻבָּר וְלֹא יִהְיֶה רֹאשׁ חֹדֶשׁ אֶלָּא יוֹם אֶחָד וּשְׁלֹשִׁים אַף עַל פִּי שֶׁנִּרְאֵית בְּלֵיל שְׁלֹשִׁים. שֶׁאֵין הָרְאִיָּה קוֹבַעַת אֶלָּא בֵּית דִּין שֶׁאָמְרוּ מְקֻדָּשׁ הֵם שֶׁקּוֹבְעִין:","רָאוּהוּ בֵּית דִּין עַצְמָן בְּסוֹף יוֹם תִּשְׁעָה וְעֶשְׂרִים. אִם עֲדַיִן לֹא יָצָא כּוֹכַב לֵיל שְׁלֹשִׁים. בֵּית דִּין אוֹמְרִים מְקֻדָּשׁ שֶׁעֲדַיִן יוֹם הוּא. וְאִם רָאוּהוּ בְּלֵיל שְׁלֹשִׁים אַחַר שֶׁיָּצְאוּ שְׁנֵי כּוֹכָבִים. לְמָחָר מוֹשִׁיבִין שְׁנֵי דַּיָּנִין אֵצֶל אֶחָד מֵהֶם וְיָעִידוּ הַשְּׁנַיִם בִּפְנֵי הַשְּׁלֹשָׁה וִיקַדְּשׁוּהוּ הַשְּׁלֹשָׁה:","בֵּית דִּין שֶׁקִּדְּשׁוּ אֶת הַחֹדֶשׁ בֵּין שׁוֹגְגִין בֵּין מֻטְעִין בֵּין אֲנוּסִים הֲרֵי זֶה מְקֻדָּשׁ וְחַיָּבִין הַכּל לְתַקֵּן הַמּוֹעֲדוֹת עַל הַיּוֹם שֶׁקִּדְּשׁוּ בּוֹ. אַף עַל פִּי שֶׁזֶּה יוֹדֵעַ שֶׁטָּעוּ חַיָּב לִסְמֹךְ עֲלֵיהֶם שֶׁאֵין הַדָּבָר מָסוּר אֶלָּא לָהֶם וּמִי שֶׁצִּוָּה לִשְׁמֹר הַמּוֹעֲדוֹת הוּא צִוָּה לִסְמֹךְ עֲלֵיהֶם שֶׁנֶּאֱמַר אֲשֶׁר תִּקְרְאוּ אֹתָם וְגוֹ':"],"Mishneh Torah, Second Tithes and Fourth Year's Fruit 1":["אַחַר שֶׁמַּפְרִישִׁין מַעֲשֵׂר רִאשׁוֹן בְּכָל שָׁנָה מַפְרִישִׁין מַעֲשֵׂר שֵׁנִי שֶׁנֶּאֱמַר (דברים יד כב) \"עַשֵּׂר תְּעַשֵּׂר אֵת כָּל תְּבוּאַת זַרְעֶךָ\". וּבְשָׁנָה שְׁלִישִׁית וְשִׁשִּׁית מַפְרִישִׁין מַעֲשַׂר עָנִי חֵלֶף מַעֲשֵׂר שֵׁנִי כְּמוֹ שֶׁבֵּאַרְנוּ:","בְּאֶחָד בְּתִשְׁרֵי הוּא רֹאשׁ הַשָּׁנָה לְמַעֲשַׂר תְּבוּאוֹת וְקִטְנִיּוֹת וִירָקוֹת. וְכָל מָקוֹם שֶׁנֶּאֱמַר רֹאשׁ הַשָּׁנָה הוּא אֶחָד בְּתִשְׁרֵי. וּבְט\"ו בִּשְׁבָט הוּא רֹאשׁ הַשָּׁנָה לְמַעֲשַׂר הָאִילָנוֹת. כֵּיצַד. תְּבוּאָה וְקִטְנִיּוֹת שֶׁהִגִּיעוּ לְעוֹנַת הַמַּעַשְׂרוֹת לִפְנֵי רֹאשׁ הַשָּׁנָה שֶׁל שְׁלִישִׁית אַף עַל פִּי שֶׁנִּגְמְרוּ וְנֶאֶסְפוּ בַּשְּׁלִישִׁית מַפְרִישִׁין מֵהֶן מַעֲשֵׂר שֵׁנִי. וְאִם לֹא בָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת אֶלָּא לְאַחַר רֹאשׁ הַשָּׁנָה שֶׁל שְׁלִישִׁית מַפְרִישִׁין מֵהֶן מַעֲשַׂר עָנִי. וְכֵן פֵּרוֹת הָאִילָן שֶׁבָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת קֹדֶם ט\"ו בִּשְׁבָט שֶׁל שְׁלִישִׁית אַף עַל פִּי שֶׁנִּגְמְרוּ וְנֶאֶסְפוּ אַחַר כֵּן בְּסוֹף שָׁנָה שְׁלִישִׁית מִתְעַשְּׂרִין לְשֶׁעָבַר וּמַפְרִישִׁין מֵהֶן מַעֲשֵׂר שֵׁנִי. וְכֵן אִם בָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת קֹדֶם ט\"ו בִּשְׁבָט שֶׁל רְבִיעִית אַף עַל פִּי שֶׁנִּגְמְרוּ וְנֶאֶסְפוּ בִּרְבִיעִית מַפְרִישִׁין מֵהֶן מַעֲשֵׂר עָנִי. וְאִם בָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת אַחַר ט\"ו בִּשְׁבָט מִתְעַשְּׂרִין לְהַבָּא:","וְהֶחָרוּבִין אַף עַל פִּי שֶׁחָנְטוּ פֵּרוֹתֵיהֶן קֹדֶם ט\"ו בִּשְׁבָט מִתְעַשְּׂרִין לְהַבָּא. הוֹאִיל וּמִתְעַשְּׂרוֹת מִדִּבְרֵי סוֹפְרִים. יֵרָאֶה לִי שֶׁאֵין הַדְּבָרִים אֲמוּרִין אֶלָּא בְּחָרוּבֵי צַלְמוֹנָה וְכַיּוֹצֵא בָּהֶן שֶׁאֵין רְאוּיִין לְמַאֲכַל רֹב הָאָדָם. וְהֵן הֵן שֶׁמִּתְעַשְּׂרוֹת מִדִּבְרֵי סוֹפְרִים. אֲבָל שְׁאָר הֶחָרוּבִין יֵרָאֶה לִי שֶׁהֵן כִּשְׁאָר פֵּרוֹת הָאִילָן:","הַיָּרָק בִּשְׁעַת לְקִיטָתוֹ עִשּׂוּרוֹ. כֵּיצַד. אִם נִלְקַט בְּיוֹם רֹאשׁ הַשָּׁנָה שֶׁל שְׁלִישִׁית אַף עַל פִּי שֶׁבָּא לְעוֹנַת הַמַּעַשְׂרוֹת וְנִגְמַר בַּשְּׁנִיָּה מַפְרִישִׁין מִמֶּנּוּ מַעֲשַׂר עָנִי. וְאִם נִלְקַט בָּרְבִיעִית מַעֲשֵׂר שֵׁנִי:","וְכֵן הָאֶתְרוֹג בִּלְבַד מִשְּׁאָר פֵּרוֹת הָאִילָן הֲרֵי הוּא כְּיָרָק וְהוֹלְכִין אַחַר לְקִיטָתוֹ בֵּין לְמַעֲשֵׂר בֵּין לִשְׁבִיעִית. כֵּיצַד. אִם נִלְקַט בַּשְּׁלִישִׁית אַחַר ט\"ו בִּשְׁבָט מַפְרִישִׁין מִמֶּנּוּ מַעֲשַׂר עָנִי אַף עַל פִּי שֶׁנִּגְמְרָה בַּשְּׁנִיָּה. וְכֵן אִם נִלְקַט בָּרְבִיעִית קֹדֶם ט\"ו בִּשְׁבָט מַפְרִישִׁין מִמֶּנּוּ מַעֲשַׂר עָנִי. נִלְקַט בָּרְבִיעִית אַחַר ט\"ו בִּשְׁבָט מַפְרִישִׁין מִמֶּנּוּ מַעֲשֵׂר שֵׁנִי:","וְאַף עַל פִּי שֶׁהוֹלְכִין אַחַר לְקִיטָתוֹ אֶתְרוֹג בַּת שִׁשִּׁית שֶׁנִּכְנְסָה לַשְּׁבִיעִית אֲפִלּוּ הָיְתָה כְּזַיִת וְנַעֲשֵׂית כְּכִכָּר חַיֶּבֶת בְּמַעַשְׂרוֹת:","הָאֶבְיוֹנוֹת שֶׁל צָלָף נוֹתְנִין עֲלֵיהֶן חֻמְרֵי אִילָן וְחֻמְרֵי זְרָעִים. שֶׁאִם הָיוּ מִשָּׁנָה שְׁנִיָּה שֶׁנִּכְנְסָה לַשְּׁלִישִׁית וְנִלְקְטוּ קֹדֶם ט\"ו בִּשְׁבָט מַפְרִישִׁין מַעֲשֵׂר רִאשׁוֹן וְאַחַר כָּךְ מַפְרִישׁ מַעֲשֵׂר אַחֵר וּפוֹדֵהוּ. וְאַחַר שֶׁפּוֹדֵהוּ נוֹתְנוֹ לָעֲנִיִּים וְאוֹכֵל פִּדְיוֹנוֹ בְּתוֹרַת מַעֲשֵׂר שֵׁנִי. וְנִמְצָא כְּמוֹ שֶׁהִפְרִישׁ מַעֲשֵׂר שֵׁנִי וּמַעֲשַׂר עָנִי:","הָאֹרֶז וְהַדֹּחַן וְהַפְּרָגִין וְהַשֻּׁמְשְׁמִין אַף עַל פִּי שֶׁהִשְׁרִישׁוּ קֹדֶם רֹאשׁ הַשָּׁנָה אֵין הוֹלְכִין בָּהֶן אֶלָּא אַחַר גְּמַר הַפְּרִי וּמִתְעַשְּׂרִין לְהַבָּא. וְכֵן פּוֹל הַמִּצְרִי אַף עַל פִּי שֶׁמִּקְצָתוֹ הִשְׁרִישׁ לִפְנֵי רֹאשׁ הַשָּׁנָה וּמִקְצָתוֹ לְאַחֲרָיו צוֹבֵר גָּרְנוֹ לְתוֹכוֹ וְתוֹרֵם וּמְעַשֵּׂר מִן הַכּל כְּאֶחָד שֶׁהַכּל הוֹלֵךְ אַחַר גְּמַר הַפְּרִי:","הַבְּצָלִים הַסָּרִיסִים שֶׁמָּנַע מֵהֶם מַיִם שְׁלֹשִׁים יוֹם לִפְנֵי רֹאשׁ הַשָּׁנָה. וְשֶׁל בַּעַל שֶׁמָּנַע מֵהֶם שָׁלֹשׁ עוֹנוֹת לִפְנֵי רֹאשׁ הַשָּׁנָה. מִתְעַשְּׂרִין לְשֶׁעָבַר. מָנַע מֵהֶם פָּחוֹת מִכָּאן אַף עַל פִּי שֶׁהִתְחִילוּ לִיבַשׁ קֹדֶם רֹאשׁ הַשָּׁנָה מִתְעַשְּׂרִין לְהַבָּא:","פּוֹל הַמִּצְרִי שֶׁהֵבִיא שְׁלִישׁ לִפְנֵי רֹאשׁ הַשָּׁנָה אִם זְרָעוֹ לְזֶרַע מִתְעַשֵּׂר לְשֶׁעָבַר. זְרָעוֹ לְיָרָק מִתְעַשֵּׂר לְהַבָּא. זַרְעוֹ לְזֶרַע וּלְיָרָק אוֹ שֶׁזְּרָעוֹ לְזֶרַע וְחִשֵּׁב עָלָיו לְיָרָק מְעַשֵּׂר מִזַּרְעוֹ עַל יְרָקוֹ וּמִירָקוֹ עַל זַרְעוֹ. לֹא הֵבִיא שְׁלִישׁ לִפְנֵי רֹאשׁ הַשָּׁנָה אִם זְרָעוֹ לְזֶרַע זַרְעוֹ מִתְעַשֵּׂר לְשֶׁעָבַר וִירָקוֹ בִּשְׁעַת לְקִיטָתוֹ עִשּׂוּרוֹ. וְהוּא שֶׁלִּקֵּט מִמֶּנּוּ לִפְנֵי רֹאשׁ הַשָּׁנָה. אֲבָל אִם לִקֵּט מִמֶּנּוּ אַחַר רֹאשׁ הַשָּׁנָה בֵּין יְרָקוֹ בֵּין זַרְעוֹ מִתְעַשֵּׂר לְהַבָּא. זְרָעוֹ לְזֶרַע וְחִשֵּׁב עָלָיו לְיָרָק הוֹלְכִין אַחַר מַחֲשַׁבְתּוֹ. זְרָעוֹ לְיָרָק וְחִשֵּׁב עָלָיו לְזָרַע אֵין מַחֲשֶׁבֶת זֶרַע חָלָה עָלָיו אֶלָּא אִם כֵּן מָנַע מִמֶּנּוּ שָׁלֹשׁ אֲרָיוֹת. וְהוּא שֶׁהֵבִיא שְׁלִישׁ לִפְנֵי רֹאשׁ הַשָּׁנָה אֲבָל אִם לֹא הֵבִיא שְׁלִישׁ אֶלָּא לְאַחֲרָיו אַף עַל פִּי שֶׁלֹּא נִמְנַע מִלֶּאֱרוֹת מִמֶּנּוּ שָׁלֹשׁ אֲרָיוֹת. זַרְעוֹ לְזֶרַע וְעָשָׂה כֻּלּוֹ קַצָּצִין גְּמוּרִים לִפְנֵי רֹאשׁ הַשָּׁנָה זַרְעוֹ מִתְעַשֵּׂר לְשֶׁעָבַר. וִירָקוֹ בִּשְׁעַת לְקִיטָתוֹ. מִקְצָתוֹ עָשָׂה קַצָּצִין גְּמוּרִין וּמִקְצָתוֹ לֹא עָשָׂה. זֶה שֶׁאָמְרוּ צוֹבֵר גָּרְנוֹ לְתוֹכוֹ וְנִמְצָא מְעַשֵּׂר מִזַּרְעוֹ עַל יְרָקוֹ וּמִירָקוֹ עַל זַרְעוֹ:","פֵּרוֹת שָׁנָה שְׁנִיָּה שֶׁנִּתְעָרְבוּ בְּפֵרוֹת שְׁלִישִׁית. אוֹ שֶׁל שְׁלִישִׁית בִּרְבִיעִית. הוֹלְכִין אַחַר הָרֹב. מֶחֱצָה לְמֶחֱצָה מַפְרִישׁ מַעֲשֵׂר שֵׁנִי מִן הַכּל. אֲבָל לֹא מַעֲשַׂר עָנִי שֶׁמַּעֲשֵׂר שֵׁנִי חָמוּר שֶׁהֲרֵי הוּא קֹדֶשׁ וּמַעֲשַׂר עָנִי חֹל. וְכֵן פֵּרוֹת שֶׁהֵן סָפֵק אִם פֵּרוֹת שְׁנִיָּה הֵם אוֹ פֵּרוֹת שְׁלִישִׁית מַפְרִישׁ מֵהֶן מַעֲשֵׂר שֵׁנִי:","כָּל הַפְּטוּר מִמַּעֲשֵׂר רִאשׁוֹן פָּטוּר מִן הַשֵּׁנִי וּמִן הֶעָנִי. וְכָל שֶׁחַיָּב בְּרִאשׁוֹן חַיָּב בִּשְׁנֵיהֶם. וְכָל הַתּוֹרֵם מוֹצִיא מַעֲשֵׂר. וְכָל שֶׁאֵינוֹ תּוֹרֵם אֵינוֹ מוֹצִיא מַעֲשֵׂר זֶה. כָּל מִי שֶׁאִם תָּרַם תְּרוּמָתוֹ תְּרוּמָה כָּךְ אִם עִשֵּׂר מַעֲשֵׂר זֶה הֲרֵי הוּא מַעֲשֵׂר. וְכָל מִי שֶׁאֵין תְּרוּמָתוֹ תְּרוּמָה כָּךְ אִם הוֹצִיא מַעֲשֵׂר זֶה אֵינוֹ מַעֲשֵׂר:","פֵּרוֹת שֶׁהוֹצִיא מֵהֶן מַעֲשֵׂר רִאשׁוֹן קֹדֶם שֶׁיִּקָּבְעוּ לַמַּעֲשֵׂר הֲרֵי זֶה אוֹכֵל מֵהֶן עַרְאַי קֹדֶם שֶׁיּוֹצִיא מַעֲשֵׂר שֵׁנִי. שֶׁאֵין הָרִאשׁוֹן קוֹבֵעַ לַשֵּׁנִי. אֲבָל מִשֶּׁנִּקְבְּעוּ לְמַעֲשֵׂר אַף עַל פִּי שֶׁהוֹצִיא אֶת הָרִאשׁוֹן אָסוּר לֶאֱכל מֵהֶן עַרְאַי עַד שֶׁיּוֹצִיא אֶת הַשֵּׁנִי אוֹ אֶת מַעֲשַׂר עָנִי:","מַעֲשֵׂר שֵׁנִי הוֹאִיל וְטָעוּן הֲבָאַת מָקוֹם אֵין מְבִיאִין אוֹתוֹ מִחוּצָה לָאָרֶץ כִּבְכוֹר בְּהֵמָה. לְפִיכָךְ לֹא חִיְּבוּ לְהַפְרִישׁ מַעֲשֵׂר שֵׁנִי בְּסוּרְיָא. וְיֵרָאֶה לִי שֶׁמַּעֲשֵׂר שֵׁנִי שֶׁמַּפְרִישִׁים בְּאֶרֶץ שִׁנְעָר וּבְמִצְרַיִם פּוֹדִין אוֹתוֹ וּמְבִיאִין דָּמָיו לִירוּשָׁלַיִם. וְכֵן יֵרָאֶה לִי שֶׁלֹּא חִיְּבוּ מְקוֹמוֹת אֵלּוּ בְּמַעֲשֵׂר שֵׁנִי אֶלָּא כְּדֵי לִקְבֹּעַ מַעֲשֵׂר עָנִי כְּדֵי שֶׁיִּהְיוּ עֲנִיֵּי יִשְׂרָאֵל סוֹמְכִים עֲלֵיהֶם:"],"Mishneh Torah, Service on the Day of Atonement 2":["כָּל מַעֲשֵׂה הַתְּמִידִין וְהַמּוּסָפִין שֶׁל יוֹם זֶה כֹּהֵן גָּדוֹל עוֹשֶׂה אוֹתָן וְהוּא לָבוּשׁ בְּבִגְדֵי זָהָב. וַעֲבוֹדוֹת הַמְיֻחָדוֹת לְיוֹם זֶה בְּבִגְדֵי לָבָן. וַעֲבוֹדָה הַמְיֻחֶדֶת לְיוֹם זֶה הִיא מַעֲשֵׂה הַפָּר שֶׁל כֹּהֵן גָּדוֹל. וּשְׁנֵי הַשְּׂעִירִים שֶׁאֶחָד מֵהֶן שָׂעִיר הַמִּשְׁתַּלֵּחַ. וְהַקְטָרַת הַקְּטֹרֶת בְּקֹדֶשׁ הַקָּדָשִׁים. כָּל אֵלּוּ בְּבִגְדֵי לָבָן הֵם נַעֲשִׂים:","כָּל עֵת שֶׁיְּשַׁנֶּה הַבְּגָדִים וְיִפְשֹׁט בְּגָדִים וְלוֹבֵשׁ בְּגָדִים אֲחֵרִים טָעוּן טְבִילָה. שֶׁנֶּאֱמַר (ויקרא טז כג) \"וּפָשַׁט אֶת בִּגְדֵי הַבָּד\" (ויקרא טז כד) \"וְרָחַץ אֶת בְּשָׂרוֹ בַמַּיִם בְּמָקוֹם קָדוֹשׁ וְלָבַשׁ אֶת בְּגָדָיו\". וְחָמֵשׁ טְבִילוֹת וַעֲשָׂרָה קִדּוּשִׁין טוֹבֵל כֹּהֵן גָּדוֹל וּמְקַדֵּשׁ בּוֹ בַּיּוֹם. כֵּיצַד. בַּתְּחִלָּה פּוֹשֵׁט בִּגְדֵי חֹל שֶׁעָלָיו וְטוֹבֵל וְעוֹלֶה וּמִסְתַּפֵּג וְלוֹבֵשׁ בִּגְדֵי זָהָב וּמְקַדֵּשׁ יָדָיו וְרַגְלָיו. וְשׁוֹחֵט אֶת הַתָּמִיד וּמַקְטִיר קְטֹרֶת שֶׁל שַׁחַר שֶׁל כָּל יוֹם וּמֵיטִיב אֶת הַנֵּרוֹת וּמַקְטִיר אֵיבְרֵי הַתָּמִיד עִם הַחֲבִיתִין וְהַנְּסָכִים וּמַקְרִיב הַפָּר וְשִׁבְעָה כְּבָשִׂים שֶׁל מוּסַף הַיּוֹם. וְאַחַר כָּךְ מְקַדֵּשׁ יָדָיו וְרַגְלָיו וּפוֹשֵׁט בִּגְדֵי הַזָּהָב וְטוֹבֵל וְעוֹלֶה וּמִסְתַּפֵּג וְלוֹבֵשׁ בִּגְדֵי לָבָן. וּמְקַדֵּשׁ יָדָיו וְרַגְלָיו וְעוֹבֵד עֲבוֹדַת הַיּוֹם כָּל הַוִּדּוּיִּים עִם הַהַגְרָלָה וּזְרִיקַת הַדָּמִים בִּפְנִים וְהַקְטָרַת הַקְּטֹרֶת בְּקֹדֶשׁ הַקָּדָשִׁים. וּמוֹסֵר הַשָּׂעִיר לַמְשַׁלְּחוֹ לַעֲזָאזֵל. וּמוֹצִיא אֵימוּרֵי הַפָּר וְהַשָּׂעִיר הַנִּשְׂרָפִים וּמוֹסֵר שְׁאֵרָן לִשְׂרֵפָה. וְאַחַר כָּךְ מְקַדֵּשׁ יָדָיו וְרַגְלָיו וּפוֹשֵׁט בִּגְדֵי לָבָן וְטוֹבֵל וְעוֹלֶה וּמִסְתַּפֵּג. וְלוֹבֵשׁ בִּגְדֵי זָהָב וּמְקַדֵּשׁ יָדָיו וְרַגְלָיו. וּמַקְרִיב שְׂעִיר חַטָּאת שֶׁל מוּסָף הַיּוֹם וְאֵילוֹ וְאֵיל הָעָם. וְהֵם עוֹלוֹת. וּמַקְטִיר אֵימוּרֵי פַּר וְשָׂעִיר הַנִּשְׂרָפִין. וּמַקְרִיב תָּמִיד שֶׁל בֵּין הָעַרְבַּיִם. וְאַחַר כָּךְ מְקַדֵּשׁ יָדָיו וְרַגְלָיו וּפוֹשֵׁט בִּגְדֵי זָהָב. וְטוֹבֵל וְעוֹלֶה וּמִסְתַּפֵּג וְלוֹבֵשׁ בִּגְדֵי לָבָן. וּמְקַדֵּשׁ יָדָיו וְרַגְלָיו. וְנִכְנָס לְקֹדֶשׁ הַקָּדָשִׁים. וּמוֹצִיא מִשָּׁם אֶת הַכַּף וְאֶת הַמַּחְתָּה. וְאַחַר כָּךְ מְקַדֵּשׁ יָדָיו וְרַגְלָיו וּפוֹשֵׁט בִּגְדֵי לָבָן. וְטוֹבֵל וְעוֹלֶה וּמִסְתַּפֵּג. וְלוֹבֵשׁ בִּגְדֵי זָהָב וּמְקַדֵּשׁ יָדָיו וְרַגְלָיו. וּמַקְטִיר קְטֹרֶת שֶׁל בֵּין הָעַרְבַּיִם שֶׁל כָּל יוֹם וּמֵיטִיב אֶת הַנֵּרוֹת בֵּין הָעַרְבַּיִם. וּמְקַדֵּשׁ יָדָיו וְרַגְלָיו. וּפוֹשֵׁט בִּגְדֵי זָהָב וְלוֹבֵשׁ בִּגְדֵי חֹל וְיוֹצֵא:","כָּל הַטְּבִילוֹת הָאֵלּוּ וְהַקִּדּוּשִׁין כֻּלָּן בַּמִּקְדָּשׁ שֶׁנֶּאֱמַר (ויקרא טז כד) \"וְרָחַץ אֶת בְּשָׂרוֹ בַמַּיִם בְּמָקוֹם קָדוֹשׁ\". חוּץ מִטְּבִילָה רִאשׁוֹנָה שֶׁהוּא רַשַּׁאי לִטְבּל אוֹתָהּ בְּחֹל שֶׁאֵינָהּ אֶלָּא לְהוֹסִיף כַּוָּנָתוֹ. שֶׁאִם יִזְכֹּר טֻמְאָה יְשָׁנָה שֶׁבְּיָדוֹ יִפְרשׁ מִמֶּנָּה בִּטְבִילָה זוֹ לִשְׁמָהּ. וְכָל כֹּהֵן שֶׁלֹּא טָבַל בֵּין בְּגָדִים לִבְגָדִים אוֹ שֶׁלֹּא קִדֵּשׁ בֵּין בֶּגֶד לְבֶגֶד וּבֵין עֲבוֹדָה לַעֲבוֹדָה וְעָבַד. עֲבוֹדָתוֹ כְּשֵׁרָה:","הָיָה כֹּהֵן גָּדוֹל זָקֵן אוֹ חוֹלֶה מְלַבְּנִין עֲשָׁשִׁיּוֹת שֶׁל בַּרְזֶל בְּאֵשׁ מִבָּעֶרֶב וּלְמָחָר מְטִילִין אוֹתָן בְּמַיִם כְּדֵי לְהָפִיג צִנָּתָן שֶׁאֵין שְׁבוּת בַּמִּקְדָּשׁ. אוֹ מְעָרְבִין מַיִם חַמִּין בְּמֵי הַמִּקְוֶה עַד שֶׁתָּפִיג צִנָּתָן:","בְּכָל יוֹם כֹּהֵן גָּדוֹל מְקַדֵּשׁ יָדָיו וְרַגְלָיו מִן הַכִּיּוֹר כִּשְׁאָר הַכֹּהֲנִים וְהַיּוֹם מְקַדֵּשׁ מִקִּיתוֹן שֶׁל זָהָב מִשּׁוּם כְּבוֹדוֹ. בְּכָל יוֹם הַכֹּהֲנִים עוֹלִים בְּמִזְרָחוֹ שֶׁל כֶּבֶשׁ וְיוֹרְדִין בְּמַעֲרָבוֹ וְהַיּוֹם עוֹלִים בָּאֶמְצַע וְיוֹרְדִין בָּאֶמְצַע לִפְנֵי כֹּהֵן גָּדוֹל כְּדֵי לְהַדְּרוֹ. בְּכָל יוֹם מִי שֶׁזָּכָה בַּמַּחְתָּה חוֹתֶה בְּמַחְתָּה שֶׁל כֶּסֶף וּמְעָרֶה הָאֵשׁ לְמַחְתָּה שֶׁל זָהָב וְהַיּוֹם חוֹתֶה כֹּהֵן גָּדוֹל בְּמַחְתָּה שֶׁל זָהָב וּבָהּ נִכְנָס לַהֵיכָל. שֶׁלֹּא לְיַגְּעוֹ בְּתוֹסֶפֶת עֲבוֹדָה. וְכֵן מַחְתָּה שֶׁל כָּל יוֹם מַחְזֶקֶת אַרְבָּעָה קַבִּין וְשֶׁל הַיּוֹם שְׁלֹשָׁה קַבִּין וּבְכָל יוֹם הָיְתָה כְּבֵדָה וְהַיּוֹם קַלָּה. וּבְכָל יוֹם יָדָהּ קְצָרָה וְהַיּוֹם אֲרֻכָּה כְּדֵי לְהָקֵל עַל כֹּהֵן גָּדוֹל שֶׁלֹּא יִיגַע. בְּכָל יוֹם וְיוֹם הָיוּ עַל הַמִּזְבֵּחַ שָׁלֹשׁ מַעֲרָכוֹת שֶׁל אֵשׁ וְהַיּוֹם הָיוּ שָׁם אַרְבַּע. מוֹסִיפִין מַעֲרָכָה כְּדֵי לְהַדֵּר הַמִּזְבֵּחַ וּלְעַטְּרוֹ:","זֶה שֶׁנֶּאֱמַר בַּתּוֹרָה (ויקרא טז יז) \"וְכִפֶּר בַּעֲדוֹ וּבְעַד בֵּיתוֹ וּבְעַד כָּל קְהַל יִשְׂרָאֵל\". מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזֶּה וִדּוּי דְּבָרִים. נִמְצֵאתָ לָמֵד שֶׁהוּא מִתְוַדֶּה בְּיוֹם זֶה שְׁלֹשָׁה וִדּוּיִים. אֶחָד עַל יְדֵי עַצְמוֹ תְּחִלָּה. וִדּוּי שֵׁנִי עַל יְדֵי עַצְמוֹ עִם שְׁאָר הַכֹּהֲנִים. וּשְׁנֵיהֶם עַל פַּר הַחַטָּאת אֲשֶׁר לוֹ. וְהַוִּדּוּי שְׁלִישִׁי עַל יְדֵי כָּל יִשְׂרָאֵל עַל שָׂעִיר הַמִּשְׁתַּלֵּחַ. וּמַזְכִּיר אֶת הַשֵּׁם בְּכָל וִדּוּי מֵהֶן שָׁלֹשׁ פְּעָמִים. כֵּיצַד הוּא אוֹמֵר. אָנָּא הַשֵּׁם חָטָאתִי עָוִיתִי וּפָשַׁעְתִּי לְפָנֶיךָ אָנָּא הַשֵּׁם כַּפֵּר נָא לַחֲטָאִים וְלָעֲווֹנוֹת וְלַפְּשָׁעִים שֶׁחָטָאתִי וְשֶׁעָוִיתִי וְשֶׁפָּשַׁעְתִּי וְכוּ' שֶׁנֶּאֱמַר (ויקרא טז ל) \"כִּי בַיּוֹם הַזֶּה יְכַפֵּר עֲלֵיכֶם לְטַהֵר אֶתְכֶם מִכּל חַטֹּאתֵיכֶם לִפְנֵי ה' תִּטְהָרוּ\". הֲרֵי שָׁלֹשׁ פְּעָמִים הִזְכִּיר אֶת הַשֵּׁם. וְכֵן בְּכָל וִדּוּי מֵהֶן. וּכְשֶׁהוּא נוֹתֵן אֶת הַגּוֹרָל עַל שְׂעִיר הַחַטָּאת אוֹמֵר לַהַשֵּׁם חַטָּאת. נִמְצָא מַזְכִּיר אֶת הַשֵּׁם בַּיּוֹם זֶה עֶשֶׂר פְּעָמִים. וּבְכֻלָּם הוּא מַזְכִּיר כִּכְתָבוֹ שֶׁהוּא הַשֵּׁם הַמְפֹרָשׁ. בָּרִאשׁוֹנָה הָיָה מַגְבִּיהַּ אֶת קוֹלוֹ בַּשֵּׁם. כֵּיוָן שֶׁרַבּוּ פְּרוּצִין חָזְרוּ לְאָמְרוֹ בְּקוֹל נָמוּךְ וּמַבְלִיעוֹ בִּנְעִימוּת עַד שֶׁלֹּא יַכִּירוּ בּוֹ אֲפִלּוּ חֲבֵרָיו הַכֹּהֲנִים:","כָּל הַכֹּהֲנִים וְהָעָם הָעוֹמְדִים בָּעֲזָרָה כְּשֶׁהֵם שׁוֹמְעִים אֶת הַשֵּׁם הַמְפֹרָשׁ יוֹצֵא מִפִּי כֹּהֵן גָּדוֹל בִּקְדֻשָּׁה וּבְטָהֳרָה. הָיוּ כּוֹרְעִים וּמִשְׁתַּחֲוִים וְנוֹפְלִים עַל פְּנֵיהֶם וְאוֹמְרִים בָּרוּךְ שֵׁם כָּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֵד שֶׁנֶּאֱמַר (דברים לב ג) \"כִּי שֵׁם ה' אֶקְרָא הָבוּ גֹּדֶל לֵאלֹהֵינוּ\". וּבִשְׁלֹשֶׁת הַוִּדּוּיִּים הָיָה מִתְכַּוֵּן לִגְמֹר אֶת הַשֵּׁם כְּנֶגֶד הַמְבָרְכִין וְאוֹמֵר לָהֶן תִּטְהָרוּ. וְכָל הַיּוֹם כָּשֵׁר לְוִדּוּי יוֹם הַכִּפּוּרִים וּלְוִדּוּי הַפָּרִים הַנִּשְׂרָפִים:"],"Mishneh Torah, Shofar, Sukkah and Lulav 5":["הַסְכָךְ שֶׁל סֻכָּה אֵינוֹ כָּשֵׁר מִכָּל דָּבָר. אֵין מְסַכְּכִין אֶלָּא בְּדָבָר שֶׁגִּדּוּלוֹ מִן הָאָרֶץ שֶׁנֶּעֱקַר מִן הָאָרֶץ וְאֵינוֹ מְקַבֵּל טֻמְאָה וְאֵין רֵיחוֹ רַע וְאֵינוֹ נוֹשֵׁר וְאֵינוֹ נוֹבֵל תָּמִיד:","סִכֵּךְ בְּדָבָר שֶׁאֵין גִּדּוּלָיו מִן הָאָרֶץ אוֹ בִּמְחֻבָּר לָאָרֶץ אוֹ בְּדָבָר שֶׁמְּקַבֵּל טֻמְאָה פְּסוּלָה. אֲבָל אִם עָבַר וְסִכֵּךְ בְּדָבָר הַנּוֹבֵל וְנוֹשֵׁר אוֹ בְּדָבָר שֶׁרֵיחוֹ רַע כְּשֵׁרָה. שֶׁלֹּא אָמְרוּ אֵין מְסַכְּכִין בְּאֵלּוּ אֶלָּא כְּדֵי שֶׁלֹּא יַנִּיחַ הַסֻּכָּה וְיֵצֵא. וְצָרִיךְ לְהִזָּהֵר שֶׁלֹּא יִהְיוּ הוּצִין וְעָלִין שֶׁל סְכָךְ יוֹרְדִין לְתוֹךְ עֲשָׂרָה טְפָחִים כְּדֵי שֶׁלֹּא יָצֵר לוֹ בִּישִׁיבָתוֹ. סִכְּכָהּ בְּמִינֵי מַתָּכוֹת אוֹ בַּעֲצָמוֹת וְעוֹרוֹת פְּסוּלָה מִפְּנֵי שֶׁאֵינָן גִּדּוּלֵי קַרְקַע. הִדְלָה עָלֶיהָ גְּפָנִים וְכַיּוֹצֵא בָּהֶן עַד שֶׁנַּעֲשׂוּ סֻכָּה פְּסוּלָה שֶׁהֲרֵי לֹא נֶעֶקְרוּ. סִכְּכָהּ בִּכְלֵי עֵץ וּבְמַחֲצָלוֹת הָעֲשׂוּיוֹת לִשְׁכִיבָה וְכַיּוֹצֵא בָּהֶן פְּסוּלָה מִפְּנֵי שֶׁהֵן מְקַבְּלִין טֻמְאָה. וְכֵן אִם סִכְּכָהּ בְּשִׁבְרֵי כֵּלִים וּבְלִיּוֹתֵיהֶן פְּסוּלָה הוֹאִיל וְהָיוּ מְקַבְּלִין טֻמְאָה שֶׁמָּא יְסַכֵּךְ בִּשְׁבָרִים שֶׁעֲדַיִן לֹא טָהֲרוּ:","סִכְּכָהּ בָּאֳכָלִין פְּסוּלָה מִפְּנֵי שֶׁהֵן מְקַבְּלִין טֻמְאָה. סוֹכֵי תְּאֵנִים וּבָהֶן תְּאֵנִים. פַּרְכִּילֵי עֲנָבִים וּבָהֶם עֲנָבִים. מִכְבָּדוֹת וּבָהֶם תְּמָרִים. וְכֵן כָּל כַּיּוֹצֵא בָּהֶן. רוֹאִין אִם פְּסלֶת מְרֻבָּה עַל הָאֳכָלִין מְסַכְּכִין בָּהֶן וְאִם לָאו אֵין מְסַכְּכִין בָּהֶן. סִכֵּךְ בִּירָקוֹת שֶׁאִם יִבשׁוּ יִבּלוּ וְלֹא יִשָּׁאֵר בָּהֶן מַמָּשׁ אַף עַל פִּי שֶׁהֵן עַתָּה לַחִים הֲרֵי מְקוֹמָן נֶחְשָׁב כְּאִלּוּ הוּא אֲוִיר וּכְאִלּוּ אֵינָם:","סִכְּכָהּ בְּפִשְׁתֵּי הָעֵץ שֶׁלֹּא דַּק אוֹתָן וְלֹא נִפְּצָן כְּשֵׁרָה שֶׁעֲדַיִן עֵץ הוּא. וְאִם דַּק וְנִפֵּץ אוֹתָן אֵין מְסַכְּכִין בּוֹ מִפְּנֵי שֶׁנִּשְׁתַּנֵּית צוּרָתוֹ וּכְאִלּוּ אֵינָן מִגִּדּוּלֵי קַרְקַע. מְסַכְּכִין בַּחֲבָלִים שֶׁל סִיב וְשֶׁל חֲלָף וְכַיּוֹצֵא בָּהֶן שֶׁהֲרֵי צוּרָתָן עוֹמֵד וְאֵין הַחֲבָלִים כֵּלִים:","סִכְּכָהּ בְּחִצִּים בִּזְכָרִים כְּשֵׁרָה בִּנְקֵבוֹת פְּסוּלָה אַף עַל פִּי שֶׁהוּא עָשׂוּי לְהִתְמַלְּאוֹת בְּבַרְזֶל בֵּית קִבּוּל הוּא וּמְקַבֵּל טֻמְאָה כְּכָל כְּלִי קִבּוּל:","מַחְצֶלֶת קָנִים אוֹ מַחְצֶלֶת גֶּמִי אוֹ חֲלָף. קְטַנָּה סְתָמָה לִשְׁכִיבָה לְפִיכָךְ אֵין מְסַכְּכִין בָּהּ אֶלָּא אִם כֵּן עָשָׂה אוֹתָהּ לְסִכּוּךְ. גְּדוֹלָה סְתָמָה לְסִכּוּךְ לְפִיכָךְ מְסַכְּכִין בָּהּ אֶלָּא אִם כֵּן עָשָׂה אוֹתָהּ לִשְׁכִיבָה. וְאִם יֵשׁ לָהּ קִיר אֲפִלּוּ גְּדוֹלָה אֵין מְסַכְּכִין בָּהּ שֶׁהֲרֵי הִיא כִּכְלִי קִבּוּל. וַאֲפִלּוּ נִטַּל הַקִּיר שֶׁלָּהּ אֵין מְסַכְּכִין בָּהּ מִפְּנֵי שֶׁהִיא כְּשִׁבְרֵי כֵּלִים:","נְסָרִים שֶׁאֵין בְּרָחְבָּן אַרְבָּעָה טְפָחִים מְסַכְּכִין בָּהֶן אַף עַל פִּי שֶׁהֵן מְשֻׁפִּין. וְאִם יֵשׁ בְּרָחְבָּן אַרְבָּעָה אֵין מְסַכְּכִין בָּהֶן וְאַף עַל פִּי שֶׁאֵינָם מְשֻׁפִּין גְּזֵרָה שֶׁמָּא יֵשֵׁב תַּחַת הַתִּקְרָה וִידַמֶּה שֶׁהִיא כְּסֻכָּה. נָתַן עָלֶיהָ נֶסֶר אֶחָד שֶׁיֵּשׁ בְּרָחְבּוֹ אַרְבָּעָה טְפָחִים כְּשֵׁרָה וְאֵין יְשֵׁנִין תַּחְתָּיו וְהַיָּשֵׁן תַּחְתָּיו לֹא יָצָא יְדֵי חוֹבָתוֹ. הָיוּ נְסָרִין שֶׁיֵּשׁ בְּרָחְבָּן אַרְבָּעָה וְאֵין בְּעָבְיָן אַרְבָּעָה וַהֲפָכָן בְּצִדֵּיהֶן שֶׁאֵין בָּהֶן אַרְבָּעָה וְסִכֵּךְ בָּהֶן הֲרֵי זוֹ פְּסוּלָה. שֶׁהֲרֵי הַנֶּסֶר פָּסוּל בֵּין שֶׁסִּכֵּךְ בְּרָחְבּוֹ בֵּין שֶׁסִּכֵּךְ בְּעָבְיוֹ:","תִּקְרָה שֶׁאֵין עָלֶיהָ מַעֲזִיבָה שֶׁהִיא הַטִּיט וְהָאֲבָנִים אֶלָּא נְסָרִין תְּקוּעִין בִּלְבַד הֲרֵי זוֹ פְּסוּלָה שֶׁהֲרֵי לֹא נַעֲשׂוּ לְשֵׁם סֻכָּה אֶלָּא לְשֵׁם בַּיִת. לְפִיכָךְ אִם פִּקְפֵּק הַנְּסָרִים וְהֵנִיד הַמַּסְמְרִים לְשֵׁם סֻכָּה הֲרֵי זוֹ כְּשֵׁרָה. וּבִלְבַד שֶׁלֹּא יִהְיֶה בְּכָל נֶסֶר וְנֶסֶר אַרְבָּעָה טְפָחִים. וְכֵן אִם נָטַל אֶחָד מִבֵּינְתַיִם וְהִנִּיחַ בִּמְקוֹמוֹ סְכָךְ כָּשֵׁר לְשֵׁם סֻכָּה הֲרֵי זוֹ כְּשֵׁרָה:","סֻכָּה שֶׁנַּעֲשֵׂית כְּהִלְכָתָהּ מִכָּל מָקוֹם כְּשֵׁרָה אַף עַל פִּי שֶׁלֹּא נַעֲשֵׂית לְשֵׁם מִצְוָה. וְהוּא שֶׁתִּהְיֶה עֲשׂוּיָה לְצֵל כְּגוֹן סֻכַּת עַכּוּ\"ם וְסֻכַּת בְּהֵמָה וְכָל כַּיּוֹצֵא בָּהֶן. אֲבָל סֻכָּה שֶׁנַּעֲשֵׂית מֵאֵלֶיהָ פְּסוּלָה לְפִי שֶׁלֹּא נַעֲשֵׂית לְצֵל. וְכֵן הַחוֹטֵט בְּגָדִישׁ וְעָשָׂהוּ סֻכָּה אֵינָהּ סֻכָּה שֶׁהֲרֵי לֹא עִמֵּר גָּדִישׁ זֶה לְצֵל. לְפִיכָךְ אִם עָשָׂה בַּתְּחִלָּה חֲלַל טֶפַח בְּמֶשֶׁךְ שִׁבְעָה לְשֵׁם סֻכָּה וְחָטַט בָּהּ אַחֲרֵי כֵן וְהִשְׁלִימָהּ לַעֲשָׂרָה כְּשֵׁרָה שֶׁהֲרֵי נַעֲשָׂה סְכָךְ שֶׁלָּהּ לְצֵל:","חֲבִילֵי קַשׁ וַחֲבִילֵי עֵצִים וַחֲבִילֵי זְרָדִין אֵין מְסַכְּכִין בָּהֶן גְּזֵרָה שֶׁמָּא יַעֲשֶׂה אוֹתָן חֲבִילוֹת עַל גַּגּוֹ כְּדֵי לְיַבְּשָׁן וְיִמָּלֵךְ וְיֵשֵׁב תַּחְתֵּיהֶן לְשֵׁם סֻכָּה וְהוּא מִתְּחִלָּה לֹא עָשָׂה סְכָךְ זֶה לְצֵל וְנִמְצֵאת כְּסֻכָּה שֶׁנַּעֲשֵׂית מֵאֵלֶיהָ. וְאִם הִתִּירָם כְּשֵׁרוֹת. וְאֵין חֲבִילָה פְּחוּתָה מֵעֶשְׂרִים וַחֲמִשָּׁה בַּדִּים:","חֲבִילוֹת קְטַנּוֹת שֶׁאָגְדוּ אוֹתָן לְמִנְיָן מְסַכְּכִין בָּהֶן. וְכֵן הַחוֹתֵךְ רֹאשׁ הַדֶּקֶל וְהַחֲרָיוֹת אֲגֻדּוֹת בּוֹ מְסַכְּכִין בּוֹ שֶׁאֶגֶד בִּידֵי שָׁמַיִם אֵינוֹ כַּחֲבִילָה. וַאֲפִלּוּ קָשַׁר רָאשֵׁי הַחֲרָיוֹת כֻּלָּן מִצַּד הָאֶחָד שֶׁנִּמְצְאוּ בַּחֲבִילָה אַחַת אֶחָד מִשְּׁנֵי רָאשִׁים בִּידֵי שָׁמַיִם וְאֶחָד בִּידֵי אָדָם מְסַכְּכִין בָּהּ שֶׁהָאוֹגֵד עֵץ אֶחָד אֵינוֹ חֲבִילָה וְזוֹ כְּעֵץ אֶחָד הִיא שֶׁהֲרֵי אֲגוּדָה בִּידֵי שָׁמַיִם. וְכֵן כָּל אֶגֶד שֶׁאֵינוֹ עָשׂוּי לְטַלְטְלוֹ אֵינוֹ אֶגֶד:","הָעוֹשֶׂה סֻכָּתוֹ תַּחַת הָאִילָן כְּאִלּוּ עֲשָׂאָהּ בְּתוֹךְ הַבַּיִת. הִדְלָה עָלֶיהָ עָלֵי הָאִילָנוֹת וּבַדֵּיהֶן וְסִכֵּךְ עַל גַּבָּן וְאַחַר כָּךְ קָצְצָן. אִם הָיָה הַסִּכּוּךְ הַרְבֵּה מֵהֶן כְּשֵׁרָה. וְאִם לֹא הָיָה הַסִּכּוּךְ שֶׁהָיָה מִתְּחִלָּתוֹ כָּשֵׁר הַרְבֵּה מֵהֶן צָרִיךְ לְנַעֲנֵעַ אוֹתָן אַחַר קְצִיצָתָן כְּדֵי שֶׁתִּהְיֶה עֲשׂוּיָה לְשֵׁם סֻכָּה:","עֵרֵב דָּבָר שֶׁמְּסַכְּכִין בּוֹ בְּדָבָר שֶׁאֵין מְסַכְּכִין בּוֹ וְסִכֵּךְ בִּשְׁנֵיהֶם אַף עַל פִּי שֶׁהַכָּשֵׁר יָתֵר עַל הַפָּסוּל פְּסוּלָה. סִכֵּךְ בָּזֶה לְעַצְמוֹ וּבָזֶה לְעַצְמוֹ זֶה בְּצַד זֶה. אִם יֵשׁ בַּסְּכָךְ פָּסוּל שְׁלֹשָׁה טְפָחִים בְּמָקוֹם אֶחָד בֵּין בָּאֶמְצַע בֵּין מִן הַצַּד הֲרֵי זוֹ פְּסוּלָה:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּסֻכָּה קְטַנָּה אֲבָל בְּסֻכָּה גְּדוֹלָה סְכָךְ פָּסוּל בָּאֶמְצַע פּוֹסְלָהּ בְּאַרְבָּעָה טְפָחִים. פָּחוֹת מִכֵּן כְּשֵׁרָה. וּמִן הַצַּד פּוֹסֵל בְּאַרְבַּע אַמּוֹת וּפָחוֹת מִכֵּן כְּשֵׁרָה. כֵּיצַד. בַּיִת שֶׁנִּפְחַת בְּאֶמְצָעוֹ וְסִכֵּךְ עַל מְקוֹם הַפְּחָת. וְכֵן חָצֵר הַמֻּקֶּפֶת אַכְסַדְרָה שֶׁסִּכֵּךְ עָלֶיהָ. וְכֵן סֻכָּה גְּדוֹלָה שֶׁהִקִּיפוּהָ בְּדָבָר שֶׁאֵין מְסַכְּכִין בּוֹ בְּצַד הַדְּפָנוֹת מִלְּמַעְלָה. אִם יֵשׁ מִשְּׂפַת הַסְּכָךְ הַכָּשֵׁר וְלַכֹּתֶל אַרְבַּע אַמּוֹת פְּסוּלָה. פָּחוֹת מִכֵּן רוֹאִין כְּאִלּוּ הַכֹּתֶל נֶעֱקַם וְיֵחָשֵׁב זֶה הַסְּכָךְ הַפָּסוּל מִגּוּף הַכֹּתֶל וּכְשֵׁרָה. וְדָבָר זֶה הֲלָכָה לְמשֶׁה מִסִּינַי:","וְאֵי זוֹ הִיא סֻכָּה קְטַנָּה כָּל שֶׁאֵין בָּהּ אֶלָּא שִׁבְעָה טְפָחִים עַל שִׁבְעָה טְפָחִים. וּגְדוֹלָה כָּל שֶׁיִּשָּׁאֵר בָּהּ יֶתֶר עַל סְכָךְ הַפָּסוּל שִׁבְעָה טְפָחִים עַל שִׁבְעָה טְפָחִים סְכָךְ כָּשֵׁר:","סִכֵּךְ בְּדָבָר פָּסוּל וְדָבָר כָּשֵׁר זֶה בְּצַד זֶה וְאֵין בְּמָקוֹם אֶחָד מִסְּכָךְ הַפָּסוּל רֹחַב שְׁלֹשָׁה טְפָחִים אֶלָּא פָּחוֹת. אִם הָיָה כָּל הַסְּכָךְ הַכָּשֵׁר יוֹתֵר עַל כָּל הַסְּכָךְ הַפָּסוּל כָּשֵׁר. וְאִם הָיָה זֶה כְּמוֹ זֶה בְּצִמְצוּם אַף עַל פִּי שֶׁאֵין בְּמָקוֹם אֶחָד שְׁלֹשָׁה הֲרֵי זוֹ פְּסוּלָה מִפְּנֵי שֶׁסְּכָךְ פָּסוּל כְּפָרוּץ הוּא נֶחְשָׁב:","פָּרַשׂ עָלֶיהָ בֶּגֶד מִלְּמַעְלָה אוֹ שֶׁפָּרַשׂ תַּחְתֶּיהָ מִפְּנֵי הַנֶּשֶׁר פְּסוּלָה. פְּרָשׂוֹ כְּדֵי לְנָאוֹתָהּ כְּשֵׁרָה. וְכֵן אִם סִכְּכָהּ כְּהִלְכָתָהּ וְעִטְּרָהּ בְּמִינֵי פֵּרוֹת וּבְמִינֵי מְגָדִים וְכֵלִים שֶׁתְּלוּיִין בֵּין בִּכְתָלֶיהָ בֵּין בַּסְּכָךְ כְּדֵי לְנָאוֹתָהּ כְּשֵׁרָה:","נוֹיֵי סֻכָּה אֵין מְמַעֲטִין בְּגָבְהָהּ אֲבָל מְמַעֲטִין בְּרָחְבָּהּ. הָיוּ נוֹיֵי הַסֻּכָּה מֻפְלָגִין מִגַּגָּהּ אַרְבָּעָה טְפָחִים אוֹ יֶתֶר פְּסוּלָה. שֶׁנִּמְצָא הַיּוֹשֵׁב שָׁם כְּאִלּוּ אֵינוֹ תַּחַת הַסְּכָךְ אֶלָּא תַּחַת הַנּוֹיִים שֶׁהֵן אֳכָלִין וְכֵלִים שֶׁאֵין מְסַכְּכִין בָּהֶן:","סְכָךְ שֶׁהָיוּ בּוֹ חַלּוֹנוֹת חַלּוֹנוֹת שֶׁהָאֲוִיר נִרְאֶה מֵהֶן. אִם יֵשׁ בְּכָל הָאֲוִיר כְּכָל מָקוֹם הַמְסֻכָּךְ הֲרֵי זוֹ פְּסוּלָה מִפְּנֵי שֶׁחַמָּתָהּ תִּהְיֶה מְרֻבָּה מִצִּלָּתָהּ. וְכָל שֶׁהַחַמָּה מְרֻבָּה עַל הַצֵּל אֵינוֹ סְכָךְ. וְאִם הָיָה הַסְּכָךְ רַב עַל הָאֲוִיר כְּשֵׁרָה:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁלֹּא הָיָה בְּמָקוֹם אֶחָד אֲוִיר שְׁלֹשָׁה טְפָחִים. אֲבָל אִם הָיָה אֲוִיר שְׁלֹשָׁה טְפָחִים בֵּין בָּאֶמְצַע בֵּין מִן הַצַּד הֲרֵי זוֹ פְּסוּלָה עַד שֶׁיְּמַעֲטֶנּוּ מִשְּׁלֹשָׁה. מִעֲטוֹ בְּדָבָר הַפָּסוּל כְּגוֹן כָּרִים וּכְסָתוֹת. אִם סֻכָּה גְּדוֹלָה הִיא כְּשֵׁרָה. וְאִם בְּסֻכָּה קְטַנָּה פְּסוּלָה עַד שֶׁיְּמַעֲטֶנּוּ בְּדָבָר שֶׁמְּסַכְּכִין בּוֹ. הָיָה רֹב הַסִּכּוּךְ צִלָּתוֹ מְרֻבֶּה מֵחֲמָתוֹ וּמִעוּטוֹ חֲמָתוֹ מְרֻבֶּה מִצִּלָּתוֹ הוֹאִיל וְצִלַּת הַכּל מְרֻבָּה מֵחֲמַת הַכּל כְּשֵׁרָה:","דֶּרֶךְ הַסִּכּוּךְ לִהְיוֹת קַל כְּדֵי שֶׁיֵּרָאוּ מִמֶּנּוּ הַכּוֹכָבִים הַגְּדוֹלִים. הָיְתָה מְעֻבָּה כְּמִין בַּיִת אַף עַל פִּי שֶׁאֵין הַכּוֹכָבִים נִרְאִין מִתּוֹכָהּ כְּשֵׁרָה. הָיָה הַסִּכּוּךְ מְדֻבְלָל וְהוּא הַסִּכּוּךְ שֶׁיִּהְיֶה מִקְצָתוֹ לְמַעְלָה וּמִקְצָתוֹ לְמַטָּה כָּשֵׁר. וּבִלְבַד שֶׁלֹּא יִהְיֶה בֵּין הָעוֹלֶה וְהַיּוֹרֵד שְׁלֹשָׁה טְפָחִים. וְאִם הָיָה בְּרֹחַב זֶה הָעוֹלֶה טֶפַח אוֹ יֶתֶר אַף עַל פִּי שֶׁהוּא גָּבוֹהַּ יֶתֶר מִשְּׁלֹשָׁה טְפָחִים רוֹאִין אוֹתוֹ כְּאִלּוּ יָרַד לְמַטָּה וְנָגַע בִּשְׂפַת זֶה הַיּוֹרֵד. וְהוּא שֶׁיִּהְיֶה מְכֻוָּן כְּנֶגֶד שְׂפַת הַיּוֹרֵד:","הָעוֹשֶׂה סֻכָּה עַל גַּבֵּי סֻכָּה. הַתַּחְתּוֹנָה פְּסוּלָה כְּמִי שֶׁעָשָׂה סֻכָּה בְּתוֹךְ הַבַּיִת וְהָעֶלְיוֹנָה כְּשֵׁרָה בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁהַתַּחְתּוֹנָה פְּסוּלָה בְּשֶׁהָיָה גֹּבַהּ חֲלַל הָעֶלְיוֹנָה עֲשָׂרָה טְפָחִים אוֹ יֶתֶר וְהָיָה גַּג הַתַּחְתּוֹנָה יָכוֹל לְקַבֵּל כָּרִים וּכְסָתוֹת שֶׁל עֶלְיוֹנָה אֲפִלּוּ עַל יְדֵי הַדְּחָק. אֲבָל אִם אֵין גָּבְהָהּ שֶׁל עֶלְיוֹנָה עֲשָׂרָה אוֹ שֶׁלֹּא הָיְתָה הַתַּחְתּוֹנָה יְכוֹלָה לְקַבֵּל כָּרִים וּכְסָתוֹת שֶׁל עֶלְיוֹנָה אֲפִלּוּ עַל יְדֵי הַדְּחָק (אַף) הַתַּחְתּוֹנָה כְּשֵׁרָה וְהוּא שֶׁלֹּא יִהְיֶה גֹּבַהּ שְׁתֵּיהֶן יֶתֶר עַל עֶשְׂרִים אַמָּה שֶׁהַתַּחְתּוֹנָה בַּסְּכָךְ הָעֶלְיוֹנָה הִיא נִתֶּרֶת:","מִטָּה שֶׁבְּתוֹךְ הַסֻּכָּה אִם גְּבוֹהָה עֲשָׂרָה טְפָחִים. הַיּוֹשֵׁב תַּחְתֶּיהָ לֹא יָצָא יְדֵי חוֹבָתוֹ. מִפְּנֵי שֶׁהִיא כְּסֻכָּה בְּתוֹךְ סֻכָּה. וְכֵן כִּלָּה שֶׁיֵּשׁ לָהּ גַּג אֲפִלּוּ טֶפַח אִם גְּבוֹהָה עֲשָׂרָה טְפָחִים אֵין יְשֵׁנִין בָּהּ בַּסֻּכָּה. וְכֵן הַמַּעֲמִיד אַרְבָּעָה עַמּוּדִים וּפָרַשׂ סָדִין עֲלֵיהֶן אִם גְּבוֹהִין עֲשָׂרָה הֲרֵי זוֹ כְּסֻכָּה בְּתוֹךְ סֻכָּה:","אֲבָל שְׁנֵי עַמּוּדִים שֶׁפָּרַשׂ עֲלֵיהֶן סָדִין וְכֵן כִּלָּה שֶׁאֵין בְּגַגָּהּ טֶפַח אֲפִלּוּ גְּבוֹהִין כָּל שֶׁהֵן מֻתָּר לִישֹׁן תַּחְתֵּיהֶם בְּסֻכָּה. שֶׁאֵינָן כְּסֻכָּה בְּתוֹךְ סֻכָּה מִפְּנֵי שֶׁאֵין לָהּ גַּג:","סֻכָּה שְׁאוּלָה כְּשֵׁרָה וְכֵן הַגְּזוּלָה כְּשֵׁרָה. כֵּיצַד. אִם תָּקַף עַל חֲבֵרוֹ וְהוֹצִיאוֹ מִסֻּכָּתוֹ וּגְזָלָהּ וְיָשַׁב בָּהּ יָצָא שֶׁאֵין הַקַּרְקַע נִגְזֶלֶת. וְאִם גָּזַל עֵצִים וְעָשָׂה מֵהֶן סֻכָּה יָצָא. שֶׁתַּקָּנַת חֲכָמִים הִיא שֶׁאֵין לְבַעַל הָעֵצִים אֶלָּא דְּמֵי עֵצִים בִּלְבַד. וַאֲפִלּוּ גָּזַל נְסָרִים וְהִנִּיחָן וְלֹא חִבְּרָן וְלֹא שָׁנָה בָּהֶן כְּלוּם יָצָא. הָעוֹשֶׂה סֻכָּתוֹ בִּרְשׁוּת הָרַבִּים הֲרֵי זוֹ כְּשֵׁרָה:"],"Mishneh Torah, Slaves 9":["יִשְׂרָאֵל שֶׁבָּא עַל שִׁפְחָה כְּנַעֲנִית אַף עַל פִּי שֶׁהִיא שִׁפְחָתוֹ הֲרֵי זֶה הַוָּלָד כְּנַעֲנִי לְכָל דָּבָר וְנִמְכָּר וְנִקְנֶה וּמִשְׁתַּמְּשִׁים בּוֹ לְעוֹלָם כִּשְׁאָר הָעֲבָדִים:","אֶחָד הַקּוֹנֶה עֶבֶד כְּנַעֲנִי מִיִּשְׂרָאֵל אוֹ מִן גֵּר תּוֹשָׁב אוֹ מִן עַכּוּ\"ם שֶׁהוּא כָּבוּשׁ תַּחַת יָדֵינוּ אוֹ מֵאֶחָד מִשְּׁאָר הָאֻמּוֹת יֵשׁ לוֹ לִמְכֹּר אֶת עַצְמוֹ לְיִשְׂרָאֵל לְעֶבֶד וַהֲרֵי הוּא עֶבֶד כְּנַעֲנִי לְכָל דָּבָר. וְכֵן מוֹכֵר בָּנָיו וּבְנוֹתָיו שֶׁנֶּאֱמַר (ויקרא כה מה) \"מֵהֶם תִּקְנוּ וּמִמִּשְׁפַּחְתָּם אֲשֶׁר עִמָּכֶם אֲשֶׁר הוֹלִידוּ בְּאַרְצְכֶם\". וְכָל אֶחָד מֵאֵלּוּ הֲרֵי הוּא כְּעֶבֶד כְּנַעֲנִי לְכָל דָּבָר:","אֶחָד מִן הָאֻמּוֹת שֶׁבָּא עַל שִׁפְחָה כְּנַעֲנִית שֶׁלָּנוּ הֲרֵי הַבֵּן עֶבֶד כְּנַעֲנִי שֶׁנֶּאֱמַר אֲשֶׁר הוֹלִידוּ בְּאַרְצְכֶם. אֲבָל הָעֶבֶד שֶׁלָּנוּ שֶׁבָּא עַל אַחַת מִן הָאֻמּוֹת אֵין הַבֵּן עֶבֶד שֶׁנֶּאֱמַר אֲשֶׁר הוֹלִידוּ בְּאַרְצְכֶם וְעֶבֶד אֵין לוֹ יַחַס:","מֶלֶךְ עַכּוּ\"ם שֶׁעָשָׂה מִלְחָמָה וְהֵבִיא שִׁבְיָה וּמְכָרָהּ. וְכֵן אִם הִרְשָׁה לְכָל מִי שֶׁיִּרְצֶה שֶׁיֵּלֵךְ וְיִגְנֹב מֵאֻמָּה שֶׁהִיא עוֹשָׂה עִמּוֹ מִלְחָמָה שֶׁיָּבִיא וְיִמְכֹּר לְעַצְמוֹ. וְכֵן אִם הָיוּ דִּינָיו שֶׁכָּל מִי שֶׁלֹּא יִתֵּן הַמַּס יִמְכֹּר. אוֹ מִי שֶׁעָשָׂה כָּךְ וְכָךְ אוֹ לֹא יַעֲשֶׂה יִמְכֹּר. הֲרֵי דִּינָיו דִּין וְעֶבֶד הַנִּלְקָח בְּדִינִין אֵלּוּ הֲרֵי הוּא כְּעֶבֶד כְּנַעֲנִי לְכָל דָּבָר:","עַכּוּ\"ם שֶׁקָּנָה עַכּוּ\"ם לְעַבְדוּת לֹא קָנָה גּוּפוֹ וְאֵין לוֹ בּוֹ אֶלָּא מַעֲשֵׂה יָדָיו. אַף עַל פִּי כֵן אִם מְכָרוֹ לְיִשְׂרָאֵל הֲרֵי גּוּפוֹ קָנוּי לְיִשְׂרָאֵל:","הָאִשָּׁה קוֹנָה שְׁפָחוֹת וְאֵינָהּ קוֹנָה עֲבָדִים אֲפִלּוּ קְטַנִּים מִפְּנֵי הַחֲשָׁד וְאִם קָנְתָה אוֹתָם הֲרֵי זוֹ קָנְתָה גּוּפָם כְּאִישׁ. וְיֵרָאֶה לִי שֶׁאֵינָהּ אֲסוּרָה לִקְנוֹת אֶלָּא עֶבֶד בֶּן תֵּשַׁע שָׁנִים וּמִתֵּשַׁע וּלְמַעְלָה. וְכֵן אָסוּר לְאָדָם לְשַׁחְרֵר עֶבֶד כְּנַעֲנִי. וְכָל הַמְשַׁחְרְרוֹ עוֹבֵר בַּעֲשֵׂה שֶׁנֶּאֱמַר (ויקרא כה מו) \"לְעלָם בָּהֶם תַּעֲבֹדוּ\". וְאִם שִׁחְרְרוֹ מְשֻׁחְרָר כְּמוֹ שֶׁבֵּאַרְנוּ. וְכוֹפִין אוֹתוֹ לִכְתֹּב גֵּט שִׁחְרוּר בְּכָל הַדְּרָכִים שֶׁבֵּאַרְנוּ. וּמֻתָּר לְשַׁחְרְרוֹ לִדְבַר מִצְוָה אֲפִלּוּ לְמִצְוָה שֶׁל דִּבְרֵיהֶם כְּגוֹן שֶׁלֹּא הָיוּ עֲשָׂרָה בְּבֵית הַכְּנֶסֶת הֲרֵי זֶה מְשַׁחְרֵר עַבְדּוֹ וּמַשְׁלִים בּוֹ הַמִּנְיָן. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְכֵן שִׁפְחָה שֶׁנּוֹהֲגִין בָּהּ הָעָם מִנְהַג הֶפְקֵר וַהֲרֵי הִיא מִכְשׁוֹל לַחוֹטְאִים כּוֹפִין אֶת רַבָּה וּמְשַׁחְרְרָהּ כְּדֵי שֶׁתִּנָּשֵׂא וְיָסוּר הַמִּכְשׁוֹל. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","יָכוֹל הָרַב לוֹמַר לְעַבְדּוֹ כְּנַעֲנִי עָשָׂה עִמִּי וְאֵינִי זָנְךָ אֶלָּא יֵלֵךְ וְיִשְׁאַל עַל הַפְּתָחִים וְיִתְפַּרְנֵס מִן הַצְּדָקָה שֶׁיִּשְׂרָאֵל מְצֻוִּין לְהַחֲיוֹת הָעֲבָדִים שֶׁבֵּינֵיהֶם. בַּמֶּה דְּבָרִים אֲמוּרִים בַּעֲבָדָיו שֶׁאֵין בֵּית דִּין נִזְקָקִין לִגְדוֹלִים לִשְׁמֹר מָמוֹנָם וְאִם לֹא יַאֲכִיל לַעֲבָדָיו וְיַשְׁקֵם כָּרָאוּי הֵם יִבְרְחוּ אוֹ יָמוּתוּ וְאָדָם חָס עַל מָמוֹן עַצְמוֹ יֶתֶר מִכָּל אָדָם. אֲבָל עֲבָדִים שֶׁהִכְנִיסָה לוֹ אִשְׁתּוֹ בְּתוֹרַת נִכְסֵי מְלוֹג חַיָּב בִּמְזוֹנוֹתֵיהֶן שֶׁעַל מְנָת כֵּן הִכְנִיס אוֹתָם שֶׁאִם לֹא יָזוּן אוֹתָם יָמוּתוּ וְיִבְרְחוּ וַהֲרֵי אֵינוֹ חַיָּב בְּאַחֲרָיוּתָן:","מֻתָּר לַעֲבֹד בְּעֶבֶד כְּנַעֲנִי בְּפָרֶךְ. וְאַף עַל פִּי שֶׁהַדִּין כָּךְ מִדַּת חֲסִידוּת וְדַרְכֵי חָכְמָה שֶׁיִּהְיֶה אָדָם רַחְמָן וְרוֹדֵף צֶדֶק וְלֹא יַכְבִּיד עֵלּוֹ עַל עַבְדּוֹ וְלֹא יָצֵר לוֹ וְיַאֲכִילֵהוּ וְיַשְׁקֵהוּ מִכָּל מַאֲכָל וּמִכָּל מִשְׁתֶּה. חֲכָמִים הָרִאשׁוֹנִים הָיוּ נוֹתְנִין לָעֶבֶד מִכָּל תַּבְשִׁיל וְתַבְשִׁיל שֶׁהָיוּ אוֹכְלִין. וּמַקְדִּימִין מְזוֹן הַבְּהֵמוֹת וְהָעֲבָדִים לִסְעוּדַת עַצְמָן. הֲרֵי הוּא אוֹמֵר (תהילים קכג ב) \"כְעֵינֵי עֲבָדִים אֶל יַד אֲדוֹנֵיהֶם כְּעֵינֵי שִׁפְחָה אֶל יַד גְּבִרְתָּהּ\". וְכֵן לֹא יְבַזֵּהוּ בַּיָּד וְלֹא בִּדְבָרִים. לְעַבְדוּת מְסָרָן הַכָּתוּב לֹא לְבוּשָׁה. וְלֹא יַרְבֶּה עָלָיו צְעָקָה וְכַעַס אֶלָּא יְדַבֵּר עִמּוֹ בְּנַחַת וְיִשְׁמַע טַעֲנוֹתָיו. וְכֵן מְפֹרָשׁ בְּדַרְכֵי אִיּוֹב הַטּוֹבִים שֶׁהִשְׁתַּבֵּחַ בָּהֶן (איוב לא יג) \"אִם אֶמְאַס מִשְׁפַּט עַבְדִּי וַאֲמָתִי בְּרִבָם עִמָּדִי\" (איוב לא טו) \"הֲלֹא בַבֶּטֶן עשֵֹׁנִי עָשָׂהוּ וַיְכֻנֶנּוּ בָּרֶחֶם אֶחָד\". וְאֵין הָאַכְזָרִיּוּת וְהָעַזּוּת מְצוּיָה אֶלָּא בְּעַכּוּ\"ם עוֹבְדֵי עֲבוֹדָה זָרָה אֲבָל זַרְעוֹ שֶׁל אַבְרָהָם אָבִינוּ וְהֵם יִשְׂרָאֵל שֶׁהִשְׁפִּיעַ לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא טוֹבַת הַתּוֹרָה וְצִוָּה אוֹתָם בְּחֻקִּים וּמִשְׁפָּטִים צַדִּיקִים רַחְמָנִים הֵם עַל הַכּל. וְכֵן בְּמִדּוֹתָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶּׁצִּוָּנוּ לְהִדָּמוֹת בָּהֶם הוּא אוֹמֵר (תהילים קמה ט) \"וְרַחֲמָיו עַל כָּל מַעֲשָׂיו\". וְכָל הַמְרַחֵם מְרַחֲמִין עָלָיו שֶׁנֶּאֱמַר (דברים יג יח) \"וְנָתַן לְךָ רַחֲמִים וְרִחַמְךָ וְהִרְבֶּךָ\":"],"Mishneh Torah, Tefillin, Mezuzah and the Torah Scroll 7":["מִצְוַת עֲשֵׂה עַל כָּל אִישׁ וְאִישׁ מִיִּשְׂרָאֵל לִכְתֹּב סֵפֶר תּוֹרָה לְעַצְמוֹ שֶׁנֶּאֱמַר (דברים לא יט) ״וְעַתָּה כִּתְבוּ לָכֶם אֶת הַשִּׁירָה״. כְּלוֹמַר כִּתְבוּ לָכֶם תּוֹרָה שֶׁיֵּשׁ בָּהּ שִׁירָה זוֹ, לְפִי שֶׁאֵין כּוֹתְבִין אֶת הַתּוֹרָה פָּרָשִׁיּוֹת פָּרָשִׁיּוֹת. וְאַף עַל פִּי שֶׁהִנִּיחוּ לוֹ אֲבוֹתָיו סֵפֶר תּוֹרָה מִצְוָה לִכְתֹּב מִשֶּׁלּוֹ. ואִם כְּתָבוֹ בְּיָדוֹ הֲרֵי הוּא כְּאִלּוּ קִבְּלָהּ מֵהַר סִינַי. וְאִם אֵינוֹ יוֹדֵעַ לִכְתֹּב אֲחֵרִים כּוֹתְבִין לוֹ. וְכָל הַמַּגִּיהַּ סֵפֶר תּוֹרָה וַאֲפִלּוּ אוֹת אַחַת הֲרֵי הוּא כְּאִלּוּ כְּתָבוֹ כֻּלּוֹ:","וְהַמֶּלֶךְ מִצְוָה עָלָיו לִכְתֹּב סֵפֶר תּוֹרָה אֶחָד לְעַצְמוֹ לְשֵׁם הַמֶּלֶךְ יָתֵר עַל סֵפֶר שֶׁיִּהְיֶה לוֹ כְּשֶׁהוּא הֶדְיוֹט שֶׁנֶּאֱמַר (דברים יז יח) ״וְהָיָה כְשִׁבְתּוֹ עַל כִּסֵּא מַמְלַכְתּוֹ וְכָתַב לוֹ״ וְגוֹ׳‎. וּמַגִּיהִין אוֹתוֹ מִסֵּפֶר הָעֲזָרָה עַל פִּי בֵּית דִּין הַגָּדוֹל. זֶה שֶׁהָיָה לוֹ כְּשֶׁהוּא הֶדְיוֹט מַנִּיחוֹ בְּבֵית גְּנָזָיו. וְזֶה שֶׁכָּתַב אוֹ שֶׁנִּכְתַּב לוֹ אַחַר שֶׁמָּלַךְ יִהְיֶה עִמּוֹ תָּמִיד. וְאִם יָצָא לַמִּלְחָמָה סֵפֶר תּוֹרָה עִמּוֹ. נִכְנָס וְהוּא עִמּוֹ. יוֹשֵׁב בַּדִּין וְהוּא עִמּוֹ. מֵסֵב וְהוּא כְּנֶגְדּוֹ שֶׁנֶּאֱמַר (דברים יז יט) ״וְהָיְתָה עִמּוֹ וְקָרָא בוֹ כָּל יְמֵי חַיָּיו״:","לֹא הָיָה לוֹ סֵפֶר תּוֹרָה קֹדֶם שֶׁיִּמְלֹךְ צָרִיךְ לִכְתֹּב לוֹ אַחַר שֶׁמָּלַךְ שְׁנֵי סִפְרֵי תּוֹרָה. אֶחָד מַנִּיחוֹ בְּבֵית גְּנָזָיו. וְהַשֵּׁנִי יִהְיֶה עִמּוֹ תָּמִיד לֹא יָסוּר מֵעִמּוֹ אֶלָּא בַּלַּיְלָה בִּלְבַד וּכְשֶׁיִּכָּנֵס לְבֵית הַמֶּרְחָץ אוֹ לְבֵית הַכִּסֵּא אוֹ לִישֹׁן עַל מִטָּתוֹ:","סֵפֶר תּוֹרָה שֶׁכְּתָבוֹ בְּלֹא שִׂרְטוּט אוֹ שֶׁכְּתָבוֹ מִקְצָתוֹ עַל הַגְּוִיל וּמִקְצָתוֹ עַל הַקְּלָף פָּסוּל אֶלָּא אוֹ כֻּלּוֹ עַל הַגְּוִיל אוֹ כֻּלּוֹ עַל הַקְּלָף. וְכֵיצַד כּוֹתְבִין סֵפֶר תּוֹרָה. כּוֹתֵב כְּתִיבָה מְתֻקֶּנֶת נָאָה בְּיוֹתֵר. יַנִּיחַ בֵּין כָּל תֵּבָה וְתֵבָה כִּמְלֹא אוֹת קְטַנָּה וּבֵין אוֹת לְאוֹת כִּמְלֹא חוּט הַשַּׂעֲרָה וּבֵין כָּל שִׁיטָה וְשִׁיטָה כִּמְלֹא שִׁיטָה. וְאֹרֶךְ כָּל שִׁיטָה וְשִׁיטָה שְׁלֹשִׁים אוֹתִיּוֹת כְּדֵי לִכְתֹּב לְמִשְׁפְּחוֹתֵיכֶם לְמִשְׁפְּחוֹתֵיכֶם לְמִשְׁפְּחוֹתֵיכֶם תְּלָתָא זִמְנֵי. וְזֶה הוּא רֹחַב כָּל דַּף וְדַף. וְלֹא תְּהֵא שִׁיטָה קְצָרָה מִזֶּה כְּדֵי שֶׁלֹּא יְהֵא הַדַּף כְּאִגֶּרֶת. וְלֹא אָרְכָּהּ יוֹתֵר עַל זֶה כְּדֵי שֶׁלֹּא יְהוּ עֵינָיו מְשׁוֹטְטוֹת בַּכְּתָב:","לֹא יְמַעֵט הַכְּתָב מִפְּנֵי הָרֶוַח שֶׁבֵּין פָּרָשָׁה לְפָרָשָׁה. נִזְדַּמְּנָה לוֹ תֵּבָה בַּת חָמֵשׁ אוֹתִיּוֹת לֹא יִכְתֹּב שְׁתַּיִם בְּתוֹךְ הַדַּף וְשָׁלֹשׁ חוּץ לַדַּף אֶלָּא כּוֹתֵב שָׁלֹשׁ בְּתוֹךְ הַדַּף וּשְׁתַּיִם חוּץ לַדַּף. לֹא נִשְׁאַר מִן הַשִּׁיטָה כְּדֵי לִכְתֹּב שָׁלֹשׁ אוֹתִיּוֹת מֵנִיחַ הַמָּקוֹם פָּנוּי וּמַתְחִיל מִתְּחִלַּת הַשִּׁיטָה:","נִזְדַּמְּנָה לוֹ תֵּבָה בַּת שְׁתֵּי אוֹתִיּוֹת לֹא יִזְרְקֶנָּה בֵּין הַדַּפִּין אֶלָּא יַחֲזִיר לִתְחִלַּת הַשִּׁיטָה. נִזְדַּמְּנָה לוֹ בְּתוֹךְ הַשִּׁיטָה תֵּבָה בַּת עֶשֶׂר אוֹתִיּוֹת אוֹ פָּחוֹת אוֹ יָתֵר וְלֹא נִשְׁאַר מִן הַשִּׁיטָה כְּדֵי לִכְתֹּב אֶת כֻּלָּהּ בְּתוֹךְ הַדַּף אִם יָכוֹל לִכְתֹּב חֶצְיָהּ בְּתוֹךְ הַדַּף וְחֶצְיָהּ חוּץ לַדַּף כּוֹתֵב וְאִם לָאו מֵנִיחַ הַמָּקוֹם פָּנוּי וּמַתְחִיל מִתְּחִלַּת הַשִּׁיטָה:","וּמֵנִיחַ בֵּין כָּל חֻמָּשׁ וְחֻמָּשׁ אַרְבַּע שִׁיטִין פְּנוּיוֹת בְּלֹא כְּתִיבָה לֹא פָּחוֹת וְלֹא יָתֵר. וְיַתְחִיל הַחֻמָּשׁ מִתְּחִלַּת שִׁיטָה חֲמִישִׁית. וּכְשֶׁיִּגְמֹר אֶת הַתּוֹרָה צָרִיךְ שֶׁיִּגְמֹר בְּאֶמְצַע שִׁיטָה שֶׁבְּסוֹף הַדַּף. וְאִם נִשְׁאַר מִן הַדַּף שִׁיטִין הַרְבֵּה מְקַצֵּר וְעוֹלֶה וּמַתְחִיל מִתְּחִלַּת הַשִּׁיטָה שֶׁבְּסוֹף הַדַּף וְלֹא יִגְמֹר אֶת הַשִּׁיטָה. וּמִתְכַּוֵּן עַד שֶׁיִּהְיֶה (דברים לד יב) ״לְעֵינֵי כָּל יִשְׂרָאֵל״ בְּאֶמְצַע שִׁיטָה שֶׁבְּסוֹף הַדַּף:","וְיִזָּהֵר בָּאוֹתִיּוֹת הַגְּדוֹלוֹת וּבָאוֹתִיּוֹת הַקְּטַנּוֹת וּבָאוֹתִיּוֹת הַנְּקֻדּוֹת וְאוֹתִיּוֹת הַמְשֻׁנּוֹת כְּגוֹן הַפֵּאִי״ן הַלְּפוּפוֹת וְהָאוֹתִיּוֹת הָעֲקֻמּוֹת כְּמוֹ שֶׁהֶעְתִּיקוּ הַסּוֹפְרִים אִישׁ מִפִּי אִישׁ. וְיִזָּהֵר בַּתָּגִין וּבְמִנְיָנָן. יֵשׁ אוֹת שֶׁיֵּשׁ עָלֶיהָ תָּג אֶחָד וְיֵשׁ אוֹת שֶׁיֵּשׁ עָלֶיהָ שִׁבְעָה. וְכָל הַתָּגִין כְּצוּרַת זַיִנִּי״ן הֵן דַּקִּין כְּחוּט הַשַּׂעֲרָה:","כָּל הַדְּבָרִים הָאֵלּוּ לֹא נֶאֶמְרוּ אֶלָּא לְמִצְוָה מִן הַמֻּבְחָר. וְאִם שִׁנָּה בְּתִקּוּן זֶה אוֹ שֶׁלֹּא דִּקְדֵּק בַּתָּגִין וְכָתַב כָּל הָאוֹתִיּוֹת כְּתִקּוּנָן אוֹ שֶׁקֵּרֵב אֶת הַשִּׁיטִין אוֹ הִרְחִיקָן אוֹ הֶאֱרִיכָן אוֹ קִצְּרָן הוֹאִיל וְלֹא הִדְבִּיקָן אוֹת בְּאוֹת וְלֹא חִסֵּר וְלֹא הוֹתִיר וְלֹא הִפְסִיד צוּרַת אוֹת אַחַת וְלֹא שִׁנָּה בִּפְתוּחוֹת וּסְתוּמוֹת הֲרֵי זֶה סֵפֶר כָּשֵׁר:","יֵשׁ דְּבָרִים אֲחֵרִים שֶׁלֹּא נֶאֶמְרוּ בַּגְּמָרָא וְנָהֲגוּ בָּהֶם הַסּוֹפְרִים וְקַבָּלָה הוּא בְּיָדָם אִישׁ מִפִּי אִישׁ. וְהֵן שֶׁיִּהְיוּ מִנְיַן הַשִּׁיטִין שֶׁבְּכָל דַּף וְדַף לֹא פָּחוֹת מִשְּׁמוֹנָה וְאַרְבָּעִים וְלֹא יָתֵר עַל שִׁשִּׁים. וְשֶׁיִּהְיֶה הָרֶוַח שֶׁבֵּין פָּרָשָׁה לְפָרָשָׁה כְּמוֹ תֵּשַׁע אוֹתִיּוֹת אֲשֶׁר אֲשֶׁר אֲשֶׁר. וְשֶׁיִּהְיֶה בְּרֹאשׁ הַשִּׁיטִין לְמַעְלָה מִשִּׁירַת הַיָּם (שמות יד כח לא) ״הַבָּאִים. בַיַּבָּשָׁה. הַשֵּׁם. מֵת. בְּמִצְרַיִם״. חָמֵשׁ שִׁיטִין. וּלְמַטָּה מִן הַשִּׁירָה חָמֵשׁ שִׁיטִין תְּחִלַּת כָּל שִׁיטָה מֵהֶן כָּךְ. (שמות טו כ כג) ״וַתִּקַּח. אַחֲרֶיהָ. סוּס. וַיֵּצְאוּ. וַיָּבֹאוּ״. וְיִהְיֶה בְּרָאשֵׁי הַשִּׁיטִין לְמַעְלָה מִשִּׁירַת הַאֲזִינוּ. (דברים לא כט ל) ״וְאָעִידָה. אַחֲרֵי. הַדֶּרֶךְ. בְּאַחֲרִית. לְהַכְעִיסוֹ. קְהַל״. שֵׁשׁ שִׁיטִין. וּלְמַטָּה מִמֶּנָּה חָמֵשׁ שִׁיטִין (דברים לב מד מז) ״וַיָּבֹא. לְדַבֵּר. אֲשֶׁר. הַזֹּאת. אֲשֶׁר״:","וְכָל הַדְּבָרִים הָאֵלּוּ לְמִצְוָה מִן הַמֻּבְחָר וְאִם שִׁנָּה לֹא פָּסַל. אֲבָל אִם כָּתַב הַמָּלֵא חָסֵר אוֹ הֶחָסֵר מָלֵא. אוֹ שֶׁכָּתַב מִלָּה שֶׁהִיא קְרִי וְכָתַב כִּקְרִיאָתָהּ כְּגוֹן שֶׁכָּתַב יִשְׁכָּבֶנָּה בִּמְקוֹם יִשְׁגָּלֶנָּה וּבַטְּחֹרִים בְּמָקוֹם וּבַעֲפלִים וְכַיּוֹצֵא בָּהֵן. אוֹ שֶׁכָּתַב פָּרָשָׁה פְּתוּחָה סְתוּמָה אוֹ סְתוּמָה פְּתוּחָה. אוֹ שֶׁכָּתַב הַשִּׁירָה כִּשְׁאָר הַכְּתָב. אוֹ שֶׁכָּתַב פָּרָשָׁה אַחַת כְּשִׁירָה הֲרֵי זֶה פָּסוּל וְאֵין בּוֹ קְדֻשַּׁת סֵפֶר תּוֹרָה כְּלָל אֶלָּא כְּחֻמָּשׁ מִן הַחֻמָּשִׁין שֶׁמְּלַמְּדִין בָּהּ הַתִּינוֹקוֹת:","סֵפֶר תּוֹרָה שֶׁאֵינוֹ מֻגָּהּ אָסוּר לִשְׁהוֹתוֹ יוֹתֵר עַל שְׁלֹשִׁים יוֹם אֶלָּא יְתַקֵּן אוֹ יִגָּנֵז. סֵפֶר תּוֹרָה שֶׁיֵּשׁ בּוֹ שָׁלֹשׁ טָעֵיּוֹת בְּכָל דַּף וְדַף יְתַקֵּן וְאִם הָיוּ אַרְבַּע יִגָּנֵז. וְאִם הָיָה רֹב הַסֵּפֶר מֻגָּהּ וְהַשְּׁאָר יֵשׁ בּוֹ אַרְבַּע טָעֻיּוֹת בְּכָל דַּף וְנִשְׁאָר אֲפִלּוּ דַּף אֶחָד מֵאוֹתוֹ הַשְּׁאָר הַמְשֻׁבָּשׁ בְּלֹא אַרְבַּע טָעֵיּוֹת הֲרֵי זֶה יְתַקֵּן:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁכָּתַב הַמָּלֵא חָסֵר שֶׁנִּמְצָא תּוֹלֶה הָאוֹתִיּוֹת שֶׁשָּׁכַח בֵּינֵי הַשִּׁיטוֹת. אֲבָל אִם כָּתַב הֶחָסֵר מָלֵא אֲפִלּוּ יֵשׁ בְּכָל דַּף וְדַף כַּמָּה טָעֵיּוֹת הֲרֵי זֶה מְתַקֵּן מִפְּנֵי שֶׁהוּא גּוֹרֵד וְאֵינוֹ תּוֹלֶה:","מֻתָּר לִכְתֹּב הַתּוֹרָה כָּל חֻמָּשׁ וְחֻמָּשׁ בִּפְנֵי עַצְמוֹ וְאֵין בָּהֶן קְדֻשַּׁת סֵפֶר תּוֹרָה. אֲבָל לֹא יִכְתֹּב מְגִלָּה בִּפְנֵי עַצְמָהּ שֶׁיִּהְיֶה בָּהּ פָּרָשִׁיּוֹת. וְאֵין כּוֹתְבִין מְגִלָּה לְתִינוֹק לְהִתְלַמֵּד בָּהּ. וְאִם דַּעְתּוֹ לְהַשְׁלִים עָלֶיהָ חֻמָּשׁ מֻתָּר. כָּתַב מְגִלָּה שָׁלֹשׁ שָׁלֹשׁ תֵּבוֹת בְּשִׁיטָה אַחַת מֻתָּר:","מֻתָּר לְדַבֵּק תּוֹרָה נְבִיאִים וּכְתוּבִים בְּכֶרֶךְ אֶחָד. וּמַנִּיחַ בְּכָל חֻמָּשׁ וְחֻמָּשׁ אַרְבַּע שִׁיטִין. וּבֵין כָּל נָבִיא וְנָבִיא שָׁלֹשׁ שִׁיטִין. וּבֵין כָּל נָבִיא וְנָבִיא מִשְּׁנֵים עָשָׂר שָׁלֹשׁ שִׁיטִין שֶׁאִם בָּא לַחְתֹּךְ חוֹתֵךְ. וְסִדּוּרָן שֶׁל נְבִיאִים כָּךְ הוּא. יְהוֹשֻׁעַ. שׁוֹפְטִים. שְׁמוּאֵל. מְלָכִים. יִרְמְיָה. יְחֶזְקֵאל. יְשַׁעְיָה. תְּרֵי עָשָׂר. וְסֵדֶר הַכְּתוּבִים. רוּת. וּתְהִלִּים. וְאִיּוֹב. וּמִשְׁלֵי. וְקֹהֶלֶת. וְשִׁיר הַשִּׁירִים. וְקִינוֹת. וְדָנִיֵּאל. וּמְגִלָּה. וְעֶזְרָא. וְדִבְרֵי הַיָּמִים:","כָּל כִּתְבֵי הַקֹּדֶשׁ אֵין כּוֹתְבִין אוֹתָן אֶלָּא בְּשִׂרְטוּט אֲפִלּוּ כְּתָבָן עַל הַנְּיָר. וּמֻתָּר לִכְתֹּב שָׁלֹשׁ תֵּבוֹת בְּלֹא שִׂרְטוּט. יוֹתֵר עַל זֶה אָסוּר. כֶּרֶךְ זֶה שֶׁיֵּשׁ בּוֹ תּוֹרָה נְבִיאִים וּכְתוּבִים אֵין קְדֻשָּׁתוֹ כִּקְדֻשַּׁת סֵפֶר תּוֹרָה אֶלָּא כְּחֻמָּשׁ מִן הַחֻמָּשִׁים. דִּין הַיָּתֵר כְּדִין הֶחָסֵר:"],"Mishneh Torah, Testimony 18":["מִי שֶׁהֵעִיד בְּשֶׁקֶר וְנוֹדַע בְּעֵדִים שֶׁהֵעִיד בְּשֶׁקֶר זֶהוּ שֶׁנִּקְרָא עֵד זוֹמֵם. וּמִצְוַת עֲשֵׂה לַעֲשׂוֹת לוֹ כְּמָה שֶׁרָצָה לַעֲשׂוֹת בְּעֵדוּתוֹ לַחֲבֵרוֹ. אִם בַּעֲבֵרָה שֶׁחַיָּבִין עָלֶיהָ סְקִילָה הֵעִידוּ וְהוּזְמוּ נִסְקָלִין כֻּלָּן. וְאִם בִּשְׂרֵפָה נִשְׂרָפִין וְכֵן שְׁאָר הַמִּיתוֹת. וְאִם הֵעִידוּ בְּמַלְקוֹת לוֹקֶה כָּל אֶחָד מֵהֶן כִּשְׁאָר מְחֻיְּבֵי מַלְקוֹת. וְאוֹמְדִין כֹּחוֹ וּמַלְקִין אוֹתוֹ. וְאִם הֵעִידוּ לְחַיְּבוֹ מָמוֹן מְשַׁלְּשִׁין הַמָּמוֹן בֵּינֵיהֶן לְפִי מִנְיַן הָעֵדִים. כָּל אֶחָד וְאֶחָד יִתֵּן חֵלֶק הַמַּגִּיעַ לוֹ. וְאֵין לוֹקִין בִּמְקוֹם תַּשְׁלוּמִין:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּעֵדִים שֶׁהוּזְמוּ. אֲבָל שְׁתֵּי כִּתּוֹת הַמַּכְחִישׁוֹת זוֹ אֶת זוֹ וְאֵין כָּאן עֵדוּת אֵין עוֹנְשִׁין אֶת אַחַת מֵהֶן. לְפִי שֶׁאֵין אָנוּ יוֹדְעִים מִי הִיא הַכַּת הַשַּׁקְרָנִית. וּמַה בֵּין הַכְחָשָׁה לַהֲזָמָה. הַהַכְחָשָׁה בָּעֵדוּת עַצְמָהּ זֹאת אוֹמֶרֶת הָיָה הַדָּבָר הַזֶּה וְזֹאת אוֹמֶרֶת לֹא הָיָה הַדָּבָר הַזֶּה אוֹ יָבוֹא מִכְּלַל דְּבָרֶיהָ שֶׁלֹּא הָיָה. וְהַהֲזָמָה בָּעֵדִים עַצְמָן וְאֵלּוּ הָעֵדִים שֶׁהֱזִימוּם אֵינָן יוֹדְעִים אִם נִהְיָה הַדָּבָר אוֹ לֹא הָיָה. כֵּיצַד. עֵדִים שֶׁבָּאוּ וְאָמְרוּ רָאִינוּ זֶה שֶׁהָרַג אֶת הַנֶּפֶשׁ אוֹ לָוָה מָנֶה מִפְּלוֹנִי בְּיוֹם פְּלוֹנִי בְּמָקוֹם פְּלוֹנִי. וְאַחַר שֶׁהֵעִידוּ וְנִבְדְּקוּ בָּאוּ שְׁנַיִם אֲחֵרִים וְאָמְרוּ בְּיוֹם זֶה וּבְמָקוֹם זֶה הָיִינוּ עִמָּכֶם וְעִם אֵלּוּ כָּל הַיּוֹם. וְלֹא הָיוּ דְּבָרִים מֵעוֹלָם לֹא זֶה הָרַג אֶת זֶה וְלֹא זֶה הִלְוָה אֶת זֶה הֲרֵי זוֹ הַכְחָשָׁה. וְכֵן אִם אָמְרוּ לָהֶם הֵיאַךְ אַתֶּם מְעִידִים כָּךְ וְזֶה הַהוֹרֵג אוֹ הַנֶּהֱרָג אוֹ הַלּוֶֹה אוֹ הַמַּלְוֶה הָיָה עִמָּנוּ בְּיוֹם זֶה בִּמְדִינָה אַחֶרֶת. הֲרֵי זוֹ עֵדוּת מֻכְחֶשֶׁת שֶׁזֶּה כְּמִי שֶׁאָמַר לֹא הָרַג זֶה אֶת זֶה וְלֹא זֶה הִלְוָה אֶת זֶה שֶׁהֲרֵי עִמָּנוּ הָיוּ וְלֹא נִהְיָה דָּבָר זֶה. וְכֵן כָּל כַּיּוֹצֵא בִּדְבָרִים אֵלּוּ. אֲבָל אִם אָמְרוּ לָהֶם אָנוּ אֵין אָנוּ יוֹדְעִים אִם זֶה הָרַג זֶה בְּיוֹם זֶה בִּירוּשָׁלַיִם כְּמוֹ שֶׁאַתֶּם אוֹמְרִין אוֹ לֹא הֲרָגוֹ. וְאָנוּ מְעִידִים שֶׁאַתֶּם עַצְמְכֶם הֱיִיתֶם עִמָּנוּ בְּיוֹם זֶה בְּבָבֶל. הֲרֵי אֵלּוּ זוֹמְמִים וְנֶהֱרָגִין אוֹ מְשַׁלְּמִין. הוֹאִיל וְהָעֵדִים שֶׁהֱזִימוּם לֹא הִשְׁגִּיחוּ עַל עַצְמָהּ שֶׁל עֵדוּת כְּלָל אִם אֱמֶת הָיָה אוֹ שֶׁקֶר:","וְזֶה שֶׁהֶאֱמִינָה תּוֹרָה עֵדוּת הָאַחֲרוֹנִים עַל הָעֵדִים הָרִאשׁוֹנִים גְּזֵרַת הַכָּתוּב הִיא. אֲפִלּוּ הָיוּ הָעֵדִים הָרִאשׁוֹנִים מֵאָה וּבָאוּ שְׁנַיִם וֶהֱזִימוּם וְאָמְרוּ לָהֶם אָנוּ מְעִידִים שֶׁאַתֶּם הַמֵּאָה כֻּלְּכֶם עִמָּנוּ הֱיִיתֶם בְּיוֹם פְּלוֹנִי בְּמָקוֹם פְּלוֹנִי הֲרֵי אֵלּוּ נֶעֱנָשִׁין עַל פִּיהֶם. שֶׁהַשְּׁנַיִם כְּמֵאָה וּמֵאָה כִּשְׁנַיִם. וְכֵן בִּשְׁתֵּי כִּתֵּי עֵדִים הַמַּכְחִישׁוֹת זוֹ אֶת זוֹ אֵין הוֹלְכִין אַחַר הָרֹב אֶלָּא דּוֹחִין אֶת שְׁתֵּיהֶן:","עֵדִים זוֹמְמִין אֵינָן צְרִיכִין הַתְרָאָה. וְעֵדִים שֶׁהֻכְחֲשׁוּ וּלְבַסּוֹף הוּזַמּוּ הֲרֵי אֵלּוּ נֶהֱרָגִין אוֹ לוֹקִין אוֹ מְשַׁלְּמִין מִפְּנֵי שֶׁהַכְחָשָׁה תְּחִלַּת הֲזָמָה הִיא אֶלָּא שֶׁעֲדַיִן לֹא נִגְמְרָה:","אֵין מְזִימִין אֶת הָעֵדִים אֶלָּא בִּפְנֵיהֶם. וּמַכְחִישִׁין אֶת הָעֵדִים שֶׁלֹּא בִּפְנֵיהֶם. וְעֵדִים שֶׁהוּזַמּוּ שֶׁלֹּא בִּפְנֵיהֶן הֲרֵי הֻכְחֲשׁוּ. לְפִיכָךְ אִם מֵתוּ הָעֵדִים שֶׁהֱזִימוּם קֹדֶם שֶׁיָּזִימוּ אוֹתָם בִּפְנֵיהֶם אֵין כָּאן עֵדוּת שֶׁהֲרֵי הִכְחִישׁוּ זֶה אֶת זֶה:","עֵדֵי נְפָשׁוֹת שֶׁהֻכְחֲשׁוּ וְלֹא הוּזַמּוּ אֲפִלּוּ בָּא הַנֶּהֱרָג בְּרַגְלָיו אֵינָם לוֹקִין. מִפְּנֵי שֶׁהוּא לָאו שֶׁנִּתָּן לְאַזְהָרַת מִיתַת בֵּית דִּין וְאֵין לוֹקִין עָלָיו. אֲבָל בֵּית דִּין מַכִּין אוֹתָן מַכַּת מַרְדּוּת כְּפִי מַה שֶּׁיִּרְאוּ:","עֵדִים זוֹמְמִים צְרִיכִין הַכְרָזָה. וְהֵיאַךְ הִיא הַהַכְרָזָה שֶׁלָּהֶן. כּוֹתְבִין וְשׁוֹלְחִין בְּכָל עִיר וְעִיר פְּלוֹנִי וּפְלוֹנִי הֵעִידוּ בְּכָךְ וְכָךְ וְהוּזַמּוּ וַהֲרַגְנוּם. אוֹ לָקוּ בְּפָנֵינוּ אוֹ עָנַשְׁנוּ אוֹתָן כָּךְ וְכָךְ דִּינָרִין. שֶׁנֶּאֱמַר (דברים יט כ) \"וְהַנִּשְׁאָרִים יִשְׁמְעוּ וְיִרָאוּ\":","חִיּוּב הָעֵדִים זוֹמְמִים לְשַׁלֵּם בְּמָקוֹם שֶׁחַיָּבִין לְשַׁלֵּם קְנָס הוּא וּלְפִיכָךְ אֵין מְשַׁלְּמִין עַל פִּי עַצְמָן. כֵּיצַד. הֲרֵי שֶׁהֵעִידוּ וְנֶחְקְרָה עֵדוּתָן בְּבֵית דִּין וְאַחַר כָּךְ אָמְרוּ שְׁנֵיהֶם עֵדוּת שֶׁקֶר הֵעַדְנוּ וְאֵין לָזֶה אֵצֶל זֶה כְּלוּם. אוֹ שֶׁאָמַרְנוּ הֵעַדְנוּ עַל זֶה בְּכָךְ וְכָךְ וְהוּזַמְנוּ אֵין מְשַׁלְּמִין עַל פִּיהֶן. אֲבָל אִם אָמְרוּ הֵעַדְנוּ עַל זֶה וְהוּזַמְנוּ בְּבֵית דִּינוֹ שֶׁל פְּלוֹנִי וְנִתְחַיַּבְנוּ לִתֵּן לוֹ כָּךְ וְכָךְ הֲרֵי אֵלּוּ מְשַׁלְּמִין שֶׁזּוֹ הוֹדָאָה בְּמָמוֹן שֶׁנִּגְמַר דִּינוֹ לִתְּנוֹ. וְאִם אָמַר הָאֶחָד כָּךְ מְשַׁלֵּם חֶלְקוֹ:"],"Mishneh Torah, Testimony 9":["עֲשָׂרָה מִינֵי פַּסְלוּת הֵם כָּל מִי שֶׁנִּמְצָא בּוֹ אֶחָד מֵהֶן הֲרֵי הוּא פָּסוּל לְעֵדוּת. וְאֵלּוּ הֵן. הַנָּשִׁים. וְהָעֲבָדִים. וְהַקְּטַנִּים. וְהַשּׁוֹטִים. וְהַחֵרְשִׁים. וְהַסּוּמִים. וְהָרְשָׁעִים. וְהַבְּזוּיִין. וְהַקְּרוֹבִין. וְהַנּוֹגְעִין בְּעֵדוּתָן. הֲרֵי אֵלּוּ עֲשָׂרָה:","נָשִׁים פְּסוּלוֹת לְעֵדוּת מִן הַתּוֹרָה שֶׁנֶּאֱמַר (דברים יז ו) \"עַל פִּי שְׁנַיִם עֵדִים\" לָשׁוֹן זָכָר וְלֹא לָשׁוֹן נְקֵבָה:","וְכֵן הַטֻּמְטוּם וְהָאַנְדְּרוֹגִינוּס פְּסוּלִין מִפְּנֵי שֶׁהֵן סָפֵק אִשָּׁה. וְכָל מִי שֶׁהוּא סָפֵק כָּשֵׁר סָפֵק פָּסוּל הֲרֵי הוּא פָּסוּל שֶׁאֵין הָעֵד בָּא אֶלָּא לְהוֹצִיא מָמוֹן עַל פִּיו אוֹ לְחַיֵּב עַל פִּיו וְאֵין מוֹצִיאִין מָמוֹן מִסָּפֵק וְאֵין עוֹנְשִׁין מִסָּפֵק דִּין תּוֹרָה:","הָעֲבָדִים פְּסוּלִין לְעֵדוּת מִן הַתּוֹרָה. שֶׁנֶּאֱמַר (דברים יט יט) \"וַעֲשִׂיתֶם לוֹ כַּאֲשֶׁר זָמַם לַעֲשׂוֹת לְאָחִיו\" מִכְּלָל שֶׁאָחִיו כָּמוֹהוּ מָה אָחִיו בֶּן בְּרִית אַף הָעֵד בֶּן בְּרִית קַל וָחֹמֶר לְעַכּוּ\"ם אִם עֲבָדִים שֶׁהֵן בְּמִקְצָת מִצְוֹת פְּסוּלִין הָעַכּוּ\"ם לֹא כָּל שֶׁכֵּן:","מִי שֶׁחֶצְיוֹ עֶבֶד וְחֶצְיוֹ בֶּן חוֹרִין פָּסוּל:","כָּל מִי שֶׁנִּשְׁתַּחְרֵר וַהֲרֵי הוּא מְחֻסָּר גֵּט שִׁחְרוּר. פָּסוּל עַד שֶׁיַּגִּיעַ גֵּט לְיָדוֹ וְיֵעָשֶׂה מִכְּלַל בְּנֵי בְּרִית וְאַחַר כָּךְ יָעִיד:","הַקְּטַנִּים פְּסוּלִין לְעֵדוּת מִן הַתּוֹרָה שֶׁנֶּאֱמַר בְּעֵדִים (דברים יט יז) \"וְעָמְדוּ שְׁנֵי הָאֲנָשִׁים\" אֲנָשִׁים וְלֹא קְטַנִּים. אֲפִלּוּ הָיָה הַקָּטָן נָבוֹן וְחָכָם הֲרֵי הוּא פָּסוּל עַד שֶׁיָּבִיא שְׁתֵּי שְׂעָרוֹת אַחַר שְׁלֹשׁ עֶשְׂרֵה שָׁנָה גְּמוּרוֹת. וְאִם הִגִּיעַ לְעֶשְׂרִים שָׁנָה וְלֹא הֵבִיא שְׁתֵּי שְׂעָרוֹת וְנוֹלַד בּוֹ סִימָן מִסִּימָנֵי סֵרוּס הֲרֵי זֶה סָרִיס וְיָעִיד. וְאִם לֹא נוֹלַד בּוֹ לֹא יָעִיד עַד רֹב שְׁנוֹתָיו כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת אִישׁוּת:","קָטָן שֶׁהִגִּיעַ לִכְלַל שְׁנוֹתָיו שֶׁנִּרְאוּ בּוֹ סִימָנֵי בַּגְרוּת מִלְּמַעְלָה אֵינוֹ צָרִיךְ בְּדִיקָה. וְאִם לָאו אֵין מְקַבְּלִין עֵדוּתוֹ עַד שֶׁיִּבָּדֵק. וּבֶן שְׁלֹשׁ עֶשְׂרֵה שָׁנָה וְיוֹם אֶחָד שֶׁהֵבִיא שְׁתֵּי שְׂעָרוֹת וְאֵינוֹ יוֹדֵעַ בְּטִיב מַשָּׂא וּמַתָּן אֵין עֵדוּתוֹ עֵדוּת בְּקַרְקָעוֹת מִפְּנֵי שֶׁאֵינוֹ מְדַקְדֵּק בִּדְבָרִים שֶׁהֲרֵי אֵינוֹ יוֹדֵעַ. אֲבָל בְּעֵדוּת מִטַּלְטְלִין מְקַבְּלִין עֵדוּתוֹ הוֹאִיל וְהוּא גָּדוֹל:","הַשּׁוֹטֶה פָּסוּל לְעֵדוּת מִן הַתּוֹרָה לְפִי שֶׁאֵינוֹ בֶּן מִצְוֹת. וְלֹא שׁוֹטֶה שֶׁהוּא מְהַלֵּךְ עָרֹם וּמְשַׁבֵּר כֵּלִים וְזוֹרֵק אֲבָנִים בִּלְבַד. אֶלָּא כָּל מִי שֶׁנִּטְרְפָה דַּעְתּוֹ וְנִמְצֵאת דַּעְתּוֹ מְשֻׁבֶּשֶׁת תָּמִיד בְּדָבָר מִן הַדְּבָרִים אַף עַל פִּי שֶׁהוּא מְדַבֵּר וְשׁוֹאֵל כָּעִנְיָן בִּשְׁאָר דְּבָרִים הֲרֵי זֶה פָּסוּל וּבִכְלַל שׁוֹטִים יֵחָשֵׁב. הַנִּכְפֶּה בְּעֵת כְּפִיָּתוֹ פָּסוּל וּבְעֵת שֶׁהוּא בָּרִיא כָּשֵׁר. וְאֶחָד הַנִּכְפֶּה מִזְּמַן לִזְמַן אוֹ הַנִּכְפֶּה תָּמִיד בְּלֹא עֵת קָבוּעַ. וְהוּא שֶׁלֹּא תִּהְיֶה דַּעְתּוֹ מְשֻׁבֶּשֶׁת תָּמִיד שֶׁהֲרֵי יֵשׁ שָׁם נִכְפִּים שֶׁגַּם בְּעֵת בְּרִיאוּתָם דַּעְתָּם מִטָּרֶפֶת עֲלֵיהֶם. וְצָרִיךְ לְהִתְיַשֵּׁב בְּעֵדוּת הַנִּכְפִּין הַרְבֵּה:","הַפְּתָאִים בְּיוֹתֵר שֶׁאֵין מַכִּירִין דְּבָרִים שֶׁסּוֹתְרִין זֶה אֶת זֶה וְלֹא יָבִינוּ עִנְיְנֵי הַדָּבָר כְּדֶרֶךְ שֶׁמְּבִינִין שְׁאָר עַם הָאָרֶץ. וְכֵן הַמְבֹהָלִים וְהַנֶּחְפָּזִים בְּדַעְתָּם וְהַמִּשְׁתַּגְּעִים בְּיוֹתֵר הֲרֵי אֵלּוּ בִּכְלַל הַשּׁוֹטִים. וְדָבָר זֶה לְפִי (מַה) שֶּׁיִּרְאֶה הַדַּיָּן שֶׁאִי אֶפְשָׁר לְכַוֵּן הַדַּעַת בִּכְתָב:","הַחֵרֵשׁ כְּשׁוֹטֶה שֶׁאֵין דַּעְתּוֹ נְכוֹנָה וְאֵינוֹ בֶּן מִצְוֹת. וְאֶחָד חֵרֵשׁ מְדַבֵּר וְאֵינוֹ שׁוֹמֵעַ אוֹ שׁוֹמֵעַ וְאֵינוֹ מְדַבֵּר. אַף עַל פִּי שֶׁרְאִיָּתוֹ רְאִיָּה מְעֻלָּה וְדַעְתּוֹ נְכוֹנָה צָרִיךְ לְהָעִיד בְּבֵית דִּין בְּפִיו. אוֹ שֶׁיִּהְיֶה רָאוּי לְהָעִיד בְּפִיו. וְיִהְיֶה רָאוּי לִשְׁמֹעַ הַדַּיָּנִים וְהָאִיּוּם שֶׁמְּאַיְּמִין עָלָיו. וְכֵן אִם נִשְׁתַּתֵּק אַף עַל פִּי שֶׁנִּבְדַּק בְּדֶרֶךְ שֶׁבּוֹדְקִין לְעִנְיַן גִּטִּין וְנִמְצֵאת עֵדוּתוֹ מְכֻוֶּנֶת וְהֵעִיד בְּפָנֵינוּ בִּכְתַב יָדוֹ אֵינָהּ עֵדוּת כְּלָל. חוּץ מֵעֵדוּת אִשָּׁה לְפִי שֶׁבְּעִגּוּנָהּ הֵקֵלּוּ:","הַסּוּמִים אַף עַל פִּי שֶׁמַּכִּירִין הַקּוֹל וְיָדְעוּ הָאֲנָשִׁים הֲרֵי אֵלּוּ פְּסוּלִין מִן הַתּוֹרָה. שֶׁנֶּאֱמַר (ויקרא ה א) \"וְהוּא עֵד אוֹ רָאָה\" מִי שֶׁהוּא רָאוּי לִרְאוֹת הוּא שֶׁמֵּעִיד. וְהַסּוּמָא בְּאַחַת מֵעֵינָיו כָּשֵׁר לְהָעִיד:"],"Mishneh Torah, The Order of Prayer 4":["נסח הודוי","אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ תָּבוֹא לְפָנֶיךָ תְּפִלָּתֵנוּ וְאַל תִּתְעַלַּם מִתְּחִנָּתֵנוּ שֶׁאֵין אָנוּ עַזֵּי פָנִים וּקְשֵׁי עֹרֶף שֶׁנֹּאמַר לְפָנֶיךָ צַדִּיקִים אֲנַחְנוּ וְלֹא חָטָאנוּ אֲבָל אֲנַחְנוּ וַאֲבוֹתֵינוּ אָשַׁמְנוּ בָּגַדְנוּ גָּזַלְנוּ דִּבַּרְנוּ דֹּפִי הֶעֱוִינוּ וְהִרְשַׁעְנוּ זַדְנוּ חָמַסְנוּ כוּ׳‎. עַד כִּי אֱמֶת עָשִׂיתָ וַאֲנַחְנוּ הִרְשָׁעְנוּ. מַה נֹּאמַר לְפָנֶיךָ יְיָ׳‎ אֱלֹהֵינוּ יוֹשֵׁב מָרוֹם וּמַה נְּסַפֵּר לְפָנֶיךָ שׁוֹכֵן שְׁחָקִים הֲלֹא הַנִּסְתָּרוֹת וְהַנִּגְלוֹת אַתָּה יוֹדֵעַ. אַתָּה יוֹדֵעַ רָזֵי עוֹלָם וְתַעֲלוּמוֹת סִתְרֵי כָּל חָי אַתָּה חוֹפֵשׂ כָּל חַדְרֵי בָטֶן וּבוֹחֵן כְּלָיוֹת וָלֵב אֵין כָּל דָּבָר נֶעְלָם מִמֶּךָּ וְאֵין נִסְתָּר מִנֶּגֶד עֵינֶיךָ. וּבְכֵן יְהִי רָצוֹן מִלְּפָנֶיךָ יְיָ׳‎ אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ שֶׁתִּמְחל לָנוּ עַל כָּל חַטֹּאתֵינוּ וּתְכַפֶּר לָנוּ עַל כָּל עֲוֹנוֹתֵינוּ וְתִסְלַח לָנוּ עַל כָּל פְּשָׁעֵינוּ. עַל חֵטְא שֶׁחָטָאנוּ לְפָנֶיךָ בְּאֹנֶס וְעַל חֵטְא שֶׁחָטָאנוּ לְפָנֶיךָ בִּבְלִי דָעַת. עַל חֵטְא שֶׁחָטָאנוּ לְפָנֶיךָ בְּגָלוּי וְעַל חֵטְא שֶׁחָטָאנוּ לְפָנֶיךָ בְּדַעַת וּבְמִרְמָה. עַל חֵטְא שֶׁחָטָאנוּ לְפָנֶיךָ בְּהַרְהוֹר הַלֵּב וְעַל חֵטְא שֶׁחָטָאנוּ לְפָנֶיךָ בְּוִדּוּי פֶּה. עַל חֵטְא שֶׁחָטָאנוּ לְפָנֶיךָ בְּזָדוֹן וְעַל חֵטְא שֶׁחָטָאנוּ לְפָנֶיךָ בְּחֹזֶק יָד. עַל חֵטְא שֶׁחָטָאנוּ לְפָנֶיךָ בְּטֻמְאַת שְׂפָתָיִם וְעַל חֵטְא שֶׁחָטָאנוּ לְפָנֶיךָ בְּיֵצֶר הָרָע. עַל חֵטְא שֶׁחָטָאנוּ לְפָנֶיךָ בְּיוֹדְעִים וְעַל חֵטְא שֶׁחָטָאנוּ לְפָנֶיךָ בְּלֹא יוֹדְעִים. עַל חֵטְא שֶׁחָטָאנוּ לְפָנֶיךָ בְכַחַשׁ וּבְכָזָב וְעַל חֵטְא שֶׁחָטָאנוּ לְפָנֶיךָ בְּלָשׁוֹן הָרָע. עַל חֵטְא שֶׁחָטָאנוּ לְפָנֶיךָ בְּמַרְאִית הָעַיִן וְעַל חֵטְא שֶׁחָטָאנוּ לְפָנֶיךָ בְּנֶשֶׁךְ וּבְמַרְבִּית. עַל חֵטְא שֶׁחָטָאנוּ לְפָנֶיךָ בְּשִׂיחַ שִׂפְתוֹתֵינוּ וְעַל חֵטְא שֶׁחָטָאנוּ לְפָנֶיךָ בְּעֵינַיִם רָמוֹת. עַל חֵטְא שֶׁחָטָאנוּ לְפָנֶיךָ בְּפִתְחוֹן פֶּה וְעַל חֵטְא שֶׁחָטָאנוּ לְפָנֶיךָ בְּצַעֲדֵי רַגְלַיִם. עַל חֵטְא שֶׁחָטָאנוּ לְפָנֶיךָ בִּקְפִיצַת יָד וְעַל חֵטְא שֶׁחָטָאנוּ לְפָנֶיךָ בְּרָצוֹן וּבְדַעַת. עַל חֵטְא שֶׁחָטָאנוּ לְפָנֶיךָ בִּשְׁגָגָה וְעַל חֵטְא שֶׁחָטָאנוּ לְפָנֶיךָ בְּתִמְהוֹן לֵבָב. עַל חֲטָאִים שֶׁאָנוּ חַיָּבִין עֲלֵיהֶם חַטָּאת. עַל חֲטָאִים שֶׁאָנוּ חַיָּבִין עֲלֵיהֶם עוֹלָה. (עַל חֲטָאִים שֶׁאָנוּ חַיָּבִין עֲלֵיהֶם קָרְבָּן). עַל חֲטָאִים שֶׁאָנוּ חַיָּבִין עֲלֵיהֶם אָשָׁם וַדַּאי. עַל חֲטָאִים שֶׁאָנוּ חַיָּבִין עֲלֵיהֶם אָשָׁם תָּלוּי. עַל חֲטָאִים שֶׁאָנוּ חַיָּבִין עֲלֵיהֶם קָרְבָּן עוֹלֶה וְיוֹרֵד. עַל חֲטָאִים שֶׁאָנוּ חַיָּבִין עֲלֵיהֶם עֲשֵׂה. עַל חֲטָאִים שֶׁאָנוּ חַיָּבִין עֲלֵיהֶם לֹא תַעֲשֶׂה) שֶׁנִּתְּקוּ לַעֲשֵׂה. עַל חֲטָאִים שֶׁאָנוּ חַיָּבִין עֲלֵיהֶם מִיתָה בִּידֵי שָׁמַיִם. עַל חֲטָאִים שֶׁאָנוּ חַיָּבִין עֲלֵיהֶם כָּרֵת. עַל חֲטָאִים שֶׁאָנוּ חַיָּבִין עֲלֵיהֶם מַלְקוֹת. עַל חֲטָאִים שֶׁאָנוּ חַיָּבִין עֲלֵיהֶם אַרְבַּע מִיתוֹת בֵּית דִּין סְקִילָה שְׂרֵפָה הֶרֶג וְחֶנֶק. עַל הַגְּלוּיִים לָנוּ וְעַל שֶׁאֵינָן גְּלוּיִים לָנוּ הַגְּלוּיִים לָנוּ כְּבָר אֲמַרְנוּם לְפָנֶיךָ יְיָ׳‎ אֱלֹהֵינוּ וְשֶׁאֵינָם גְּלוּיִים לָנוּ כָּל חֲטָאֵינוּ אַתָּה יוֹדֵעַ כָּל הַנִּסְתָּרוֹת כַּכָּתוּב הַנִּסְתָּרוֹת לַיְיָ׳‎ אֱלֹהֵינוּ וְהַנִּגְלֹת לָנוּ וּלְבָנֵינוּ עַד עוֹלָם וְכוּ׳‎. כִּי אַתָּה סָלְחָן לְיִשְׂרָאֵל מִן הָעוֹלָם וּמָחֳלָן לְשִׁבְטֵי יְשׁוּרוּן וּמִבַּלְעָדֶיךָ אֵין לָנוּ מֶלֶךְ מוֹחֵל וְסוֹלֵחַ. אֱלֹהַי עַד שֶׁלֹּא נוֹצַרְתִּי אֵינִי כְדַאי וְעַכְשָׁיו שֶׁנּוֹצַרְתִּי כְּאִלּוּ לֹא נוֹצַרְתִּי עָפָר אֲנִי בְּחַיָּי קַל וָחֹמֶר בְּמִיתָתִי הֲרֵי אֲנִי לְפָנֶיךָ יְיָ׳‎ אֱלֹהַי כִּכְלִי מָלֵא בוּשָׁה וּכְלִמָּה יְהִי רָצוֹן מִלְּפָנֶיךָ שֶׁלֹּא אֶחֱטָא עוֹד וּמַה שֶּׁחָטָאתִי מְחֵה בְּרַחֲמֶיךָ הָרַבִּים אֲבָל לֹא עַל יְדֵי יִסּוּרִין. יִהְיוּ לְרָצוֹן אִמְרֵי פִי וְהֶגְיוֹן לִבִּי לְפָנֶיךָ יְיָ׳‎ צוּרִי וְגוֹאֲלִי.","כַּסֵּדֶר הַזֶּה מִתְוַדֶּה בְּעַרְבִית שַׁחֲרִית וּמוּסָף וּמִנְחָה בֵּין יָחִיד בֵּין שְׁלִיחַ צִבּוּר. אֶלָּא שֶׁהַיָּחִיד אוֹמֵר וִדּוּי זֶה אַחַר תְּפִלָּתוֹ אַחַר שֶׁגּוֹמֵר שִׂים שָׁלוֹם קֹדֶם שֶׁיַּפְסִיעַ שָׁלֹשׁ פְּסִיעוֹת וּשְׁלִיחַ צִבּוּר אוֹמְרוֹ בְּתוֹךְ בְּרָכָה אֶמְצָעִית קֹדֶם שֶׁיֹּאמַר אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ מְחל לַעֲוֹנוֹתֵינוּ מִתְוַדֶּה וִדּוּי כַּסֵּדֶר הַזֶּה וְאַחַר כָּךְ אוֹמֵר מְחל לַעֲוֹנוֹתֵינוּ בְּיוֹם צוֹם הַכִּפּוּרִים:","בִּנְעִילָה מִתְוַדֶּה כַּסֵּדֶר הַזֶּה. מַה נֹּאמַר לְפָנֶיךָ יוֹשֵׁב מָרוֹם כוּ׳‎ כִּי עֲוֹנוֹתֵינוּ רַבּוּ מִלִּמְנוֹת כוּ׳‎ מָה אָנוּ מֶה חַיֵּינוּ מֶה חַסְדֵּנוּ מַה צִּדְקֵנוּ מַה מַּעֲשֵׂינוּ מַה נֹּאמַר לְפָנֶיךָ יְיָ׳‎ אֱלֹהֵינוּ הֲלֹא כָּל הַגִּבּוֹרִים כְּאַיִן לְפָנֶיךָ וְאַנְשֵׁי הַשֵּׁם כְּלֹא הָיוּ וַחֲכָמִים כִּבְלִי מַדָּע וּנְבוֹנִים כִּבְלִי הַשְׂכֵּל כִּי כָּל מַעֲשֵׂינוּ תֹּהוּ וִימֵי חַיֵּינוּ הֶבֶל לְפָנֶיךָ כַּכָּתוּב וּמוֹתַר הָאָדָם מִן הַבְּהֵמָה אָיִן כִּי הַכּל הָבֶל. אֲבָל אַתָּה הִבְדַּלְתָּ אֱנוֹשׁ מֵרֹאשׁ וַתַּכִּירֵהוּ לַעֲמֹד לְפָנֶיךָ כִּי מִי יֹאמַר לְךָ מַה תַּעֲשֶׂה וְאִם יִצְדַּק מַה יִתֶּן לָךְ וַתִּתֶּן לָנוּ יְיָ׳‎ אֱלֹהֵינוּ אֶת יוֹם הַכִּפּוּרִים הַזֶּה קֵץ מְחִילָה לְכָל חַטֹּאתֵינוּ לְמַעַן נֶחְדַּל מֵעשֶׁק יָדֵינוּ וְנָשׁוּב לַעֲשׂוֹת חֻקֵּי רְצוֹנֶךָ בְּלֵב שָׁלֵם כַּדָּבָר שֶׁנֶּאֱמַר דִּרְשׁוּ יְיָ׳‎ בְּהִמָּצְאוֹ קְרָאֻהוּ בִּהְיוֹתוֹ קָרוֹב יַעֲזֹב רָשָׁע דַּרְכּוֹ וְאִישׁ אָוֶן מַחְשְׁבֹתָיו וְיָשֹׁב אֶל יְיָ׳‎ וִירַחֲמֵהוּ וְאֶל אֱלֹהֵינוּ כִּי יַרְבֶּה לִסְלוֹחַ. וְאַתָּה אֱלוֹהַּ סְלִיחוֹת טוֹב וּמֵטִיב חַנּוּן וְרַחוּם אֶרֶךְ אַפַּיִם וְרַב חֶסֶד מַרְבֶּה לְהֵיטִיב רוֹצֶה בִּתְשׁוּבָתָן שֶׁל רְשָׁעִים וְאֵין אַתָּה חָפֵץ בְּמִיתָתָן כַּכָּתוּב חַי אָנִי נְאֻם יְיָ׳‎ אִם אֶחְפֹּץ בְּמוֹת הָרָשָׁע כִּי אִם בְּשׁוּב רָשָׁע מִדַּרְכּוֹ וְחָיָה שׁוּבוּ שׁוּבוּ מִדַּרְכֵיכֶם הָרָעִים וְלָמָּה תָמוּתוּ בֵּית יִשְׂרָאֵל. הֲשִׁיבֵנוּ וְקַבְּלֵנוּ וּמְחל לָנוּ וּסְלַח כְּגֹדֶל חַסְדְּךָ. יִהְיוּ לְרָצוֹן אִמְרֵי פִי וְהֶגְיוֹן לִבִּי לְפָנֶיךָ יְיָ׳‎ כוּ׳‎. עשֶֹׁה שָׁלוֹם וְכוּ׳‎:"],"Mishneh Torah, The Sanhedrin and the Penalties within Their Jurisdiction 19":["כָּל לֹא תַּעֲשֶׂה שֶׁיֵּשׁ בּוֹ כָּרֵת וְאֵין בּוֹ מִיתַת בֵּית דִּין שֶׁלּוֹקִין עֲלֵיהֶן אֶחָד וְעֶשְׂרִים וְאֵלּוּ הֵן. א) הַבָּא עַל אֲחוֹתוֹ. ב) הַבָּא עַל אֲחוֹת אָבִיו. ג) הַבָּא עַל אֲחוֹת אִמּוֹ. ד) הַבָּא עַל אֲחוֹת אִשְׁתּוֹ. ה) הַבָּא עַל אֵשֶׁת אָחִיו. ו) הַבָּא עַל אֵשֶׁת אֲחִי אָבִיו. ז) הַבָּא עַל הַנִּדָּה. ח) הָאוֹכֵל חֵלֶב. ט) הָאוֹכֵל דָּם. י) הָאוֹכֵל חָמֵץ בְּפֶסַח. יא) הָאוֹכֵל בְּיוֹם הַכִּפּוּרִים. יב) הָעוֹשֶׂה מְלָאכָה בְּיוֹם הַכִּפּוּרִים. יג) הָאוֹכֵל הַנּוֹתָר. יד) הָאוֹכֵל פִּגּוּל. טו) הַטָּמֵא שֶׁאָכַל בְּשַׂר קֹדֶשׁ. טז) הַטָּמֵא שֶׁנִּכְנַס לָעֲזָרָה. יז) הַשּׁוֹחֵט קָדָשִׁים בַּחוּץ. יח) הַמַּעֲלֶה קָדָשִׁים בַּחוּץ. יט) הַמְפַטֵּם אֶת הַשֶּׁמֶן. כ) הַסָּךְ בְּשֶׁמֶן הַמִּשְׁחָה. כא) הַמְפַטֵּם אֶת הַקְּטֹרֶת:","כָּל מְחֻיָּבִין מִיתָה בִּידֵי שָׁמַיִם שֶׁהֵן בְּלֹא תַּעֲשֶׂה וְיֵשׁ בָּהֶן מַעֲשֶׂה שֶׁלּוֹקִין עֲלֵיהֶן שְׁמוֹנָה עָשָׂר וְאֵלּוּ הֵן. א) זָר שֶׁאָכַל תְּרוּמָה גְּדוֹלָה בֵּין טְהוֹרָה בֵּין טְמֵאָה. ב) זָר שֶׁאָכַל תְּרוּמַת מַעֲשֵׂר. ג) זָר שֶׁאָכַל בִּכּוּרִים אַחַר שֶׁנִּכְנְסוּ לִירוּשָׁלַיִם. ד) זָר שֶׁאָכַל חַלָּה. ה) הָאוֹכֵל טֶבֶל שֶׁלֹּא הוּרַם מִמֶּנּוּ תְּרוּמָה גְּדוֹלָה וּתְרוּמַת מַעֲשֵׂר. ו) הָאוֹכֵל עִסָּה שֶׁלֹּא הוּרְמָה חַלָּתָהּ. ז) כֹּהֵן טָמֵא שֶׁאָכַל תְּרוּמָה טְהוֹרָה. ח) כֹּהֵן שֶׁנִּכְנַס לְקֹדֶשׁ הַקָּדָשִׁים שֶׁלֹּא לַעֲבוֹדָה. ט) כֹּהֵן שֶׁיָּצָא מִן הַמִּקְדָּשׁ בִּשְׁעַת עֲבוֹדָה. י) לֵוִי שֶׁעָבַד בַּעֲבוֹדַת כֹּהֲנִים. יא) זָר שֶׁשִּׁמֵּשׁ בַּמִּקְדָּשׁ. יב) מְחֻסַּר בְּגָדִים הֲרֵי הוּא כְּזָר וְלוֹקֶה אִם עָבַד. יג) כֹּהֵן טָמֵא שֶׁשִּׁמֵּשׁ. יד) שְׁתוּי יַיִן שֶׁשִּׁמֵּשׁ. טו) טְבוּל יוֹם שֶׁשִּׁמֵּשׁ. טז) מְחֻסַּר כִּפּוּרִים שֶׁשִּׁמֵּשׁ. יז) פְּרוּעַ רֹאשׁ שֶׁשִּׁמֵּשׁ. יח) קְרוּעַ בְּגָדִים שֶׁשִּׁמֵּשׁ:","אֲבָל הַמְשַׁמֵּשׁ בְּלֹא קִדּוּשׁ יָדַיִם וְרַגְלַיִם אַף עַל פִּי שֶׁהוּא חַיָּב מִיתָה אֵינוֹ לוֹקֶה מִפְּנֵי שֶׁהִיא מִצְוַת עֲשֵׂה. וְכֵן נָבִיא שֶׁכָּבַשׁ נְבוּאָתוֹ. אוֹ שֶׁעָבַר עַל דִּבְרֵי עַצְמוֹ. וְהָעוֹבֵר עַל דִּבְרֵי נָבִיא. אַף עַל פִּי שֶׁשְּׁלָשְׁתָּן בְּמִיתָה אֵינוֹ לוֹקֶה. שֶׁהֵן בָּאִין מִכְּלַל עֲשֵׂה שֶׁנֶּאֱמַר (דברים יח טו) \"אֵלָיו תִּשְׁמָעוּן\" וְלָאו הַבָּא מִכְּלַל עֲשֵׂה הֲרֵי הוּא כַּעֲשֵׂה וְאֵין לוֹקִין עָלָיו:","כָּל לֹא תַּעֲשֶׂה שֶׁבַּתּוֹרָה שֶׁאֵין בָּהֶן לֹא כָּרֵת וְלֹא מִיתַת בֵּית דִּין שֶׁלּוֹקִין עֲלֵיהֶן קס\"ח וְאֵלּוּ הֵן. א) הָעוֹשֶׂה אֱלִיל. ב) הָעוֹשֶׂה אֱלִיל לְנוֹי. ג) הַפּוֹנֶה אֶל אֱלִילִים בְּאֶחָד מִן הַמַּעֲשִׂים. ד) הַמֵּקִים מַצֵּבָה. ה) הַנּוֹטֵעַ אִילָן בַּמִּקְדָּשׁ. ו) הַנּוֹתֵן אֶבֶן מַשְׂכִּית. ז) הַנּוֹדֵר בְּשֵׁם עֲבוֹדָה זָרָה. ח) הַנִּשְׁבָּע בִּשְׁמָהּ. ט) הַנֶּהֱנֶה בָּהּ. י) הַבּוֹנֶה עִיר הַנִּדַּחַת. יא) הַנֶּהֱנֶה מִמֶּנָּה. יב) הָעוֹשֶׂה כְּחֻקּוֹת הָעַכּוּ\"ם. יג) הַקּוֹסֵם. יד) הַמְעוֹנֵן. טו) הַמְנַחֵשׁ. טז) הַחוֹבֵר. יז) הַדּוֹרֵשׁ אֶל הַמֵּתִים. יח) הַמּוֹחֵק שֵׁם וְכַיּוֹצֵא בּוֹ כְּגוֹן הוֹרֵס אֶבֶן מִן הַמִּזְבֵּחַ אוֹ שׂוֹרֵף עֵץ מִן הַמִּקְדָּשׁ. יט) הַמְכַבֶּה אֵשׁ מִן הַמִּזְבֵּחַ. כ) הָעוֹלֶה עָלָיו בְּמַעֲלוֹת. כא) הַנִּכְנָס לַעֲזָרָה בִּבְגָדִים טְמֵאִים. כב) זָב וְכַיּוֹצֵא בּוֹ שֶׁנִּכְנַס לְהַר הַבַּיִת. כג) הַמֵּסִיר בַּדֵּי אָרוֹן. כד) הַמֵּזִיחַ חשֶׁן מֵעַל הָאֵפוֹד. כה) הַקּוֹרֵעַ פִּי הַמְּעִיל. כו) הַמַּקְרִיב עַל מִזְבַּח הַזָּהָב. כז) כֹּהֵן שֶׁנִּכְנַס לַהֵיכָל שֶׁלֹּא בִּשְׁעַת הָעֲבוֹדָה. כח) בַּעַל מוּם שֶׁנִּכְנַס לְשָׁם. כט) שָׁתוּי שֶׁנִּכְנַס לְשָׁם. ל) בַּעַל מוּם שֶׁשִּׁמֵּשׁ. לא) עָרֵל שֶׁשִּׁמֵּשׁ. לב) כֹּהֵן שֶׁעָבַד בַּעֲבוֹדַת הַלְוִיִּם. לג) כֹּהֵן שֶׁנִּכְנַס לַמִּקְדָּשׁ פְּרוּעַ רֹאשׁ. לד) כֹּהֵן שֶׁנִּכְנַס לַמִּקְדָּשׁ קְרוּעַ בְּגָדִים. לה) הַמַּקְדִּישׁ בַּעֲלֵי מוּמִין. לו) הַשּׁוֹחֲטָן. לז) הַזּוֹרֵק דְּמֵיהֶן. לח) הַמַּקְטִיר אֵימוּרֵיהֶן. לט) הַמַּקְרִיב קָרְבְּנוֹת עַכּוּ\"ם בַּעֲלֵי מוּמִין. מ) הַמַּטִּיל מוּם בְּקָדָשִׁים בִּזְמַן הַמִּקְדָּשׁ. מא) הָעוֹבֵד בְּקָדָשִׁים. מב) הַגּוֹזֵז אוֹתָן. מג) הַמַּקְטִיר שְׂאוֹר אוֹ דְּבַשׁ. מד) הָעוֹשֶׂה שְׁיָרֵי מְנָחוֹת מֵחָמֵץ. מה) הַמַּקְרִיב בְּלֹא מֶלַח. מו) הַמַּקְרִיב אֶתְנָן אוֹ מְחִיר כֶּלֶב. מז) הַנּוֹתֵן שֶׁמֶן עַל מִנְחַת חוֹטֵא. מח) הַנּוֹתֵן עָלֶיהָ לְבוֹנָה. מט) הַנּוֹתֵן שֶׁמֶן בְּקָרְבַּן סוֹטָה. נ) הַנּוֹתֵן עָלָיו לְבוֹנָה. נא) הַמַּבְדִּיל בְּחַטַּאת הָעוֹף. נב) הַמֵּימֵר בְּקָדְשֵׁי מִזְבֵּחַ. נג) הָאוֹכֵל בְּשַׂר קֹדֶשׁ שֶׁנִּטְמָא. נד) הָאוֹכֵל מִפְּסוּלֵי הַמֻּקְדָּשִׁין. נה) כֹּהֵן שֶׁאָכַל בְּשַׂר קָדְשֵׁי קָדָשִׁים חוּץ לָעֲזָרָה. נו) זָר שֶׁאָכַל בְּשַׂר קָדְשֵׁי קָדָשִׁים אַחַר מַתַּן דָּמִים. נז) זָר שֶׁאָכַל בְּשַׂר בְּכוֹר. נח) כֹּהֶנֶת שֶׁנִּשֵּׂאת לְזָר שֶׁאוֹכֶלֶת חָזֶה וְשׁוֹק אֲפִלּוּ לְאַחַר מִיתַת בַּעְלָהּ. נט) חֲלָלָה שֶׁאָכְלָה תְּרוּמָה. ס) הָאוֹכֵל קָדָשִׁים קַלִּים חוּץ לִירוּשָׁלַיִם. סא) הָאוֹכֵל קָדָשִׁים קַלִּים קֹדֶם זְרִיקַת דָּמִים. סב) הָאוֹכֵל בְּכוֹר חוּץ לִירוּשָׁלַיִם. סג) הָאוֹכֵל מַעֲשֵׂר שֵׁנִי אַחַר שֶׁרָאָה פְּנֵי הַבַּיִת חוּץ לִירוּשָׁלַיִם. סד) כֹּהֵן שֶׁאָכַל בִּכּוּרִים מִשֶּׁנִּכְנְסוּ לִירוּשָׁלַיִם קֹדֶם הַנָּחָה בָּעֲזָרָה. סה) כֹּהֵן שֶׁאָכַל בִּכּוּרִים חוּץ לִירוּשָׁלַיִם אַחַר שֶׁהִנִּיחוּ בָּעֲזָרָה. סו) הָאוֹכֵל מַעֲשֵׂר שֵׁנִי שֶׁנִּטְמָא בִּירוּשָׁלַיִם קֹדֶם שֶׁיִּפָּדֶה. סז) טָמֵא שֶׁאָכַל מַעֲשֵׂר שֵׁנִי הַטָּהוֹר בִּירוּשָׁלַיִם. סח) הָאוֹכֵל מַעֲשֵׂר שֵׁנִי בַּאֲנִינוּת וְכֵן כָּל הַקָּדָשִׁים. סט) עָרֵל שֶׁאָכַל בְּשַׂר קֹדֶשׁ אוֹ תְּרוּמוֹת. ע) הָאוֹכֵל מִמִּנְחַת כֹּהֵן וְכֵן מִכָּל דָּבָר שֶׁהוּא כָּלִיל לְאִשִּׁים. עא) הָאוֹכֵל מִבְּשַׂר חַטָּאוֹת הַנִּשְׂרָפוֹת וְכֵן מִכָּל הַטָּעוּן שְׂרֵפָה. עב) הַשּׁוֹחֵט פֶּסַח עַל הֶחָמֵץ. עג) הַשּׁוֹבֵר בּוֹ עֶצֶם בֵּין בְּרִאשׁוֹן בֵּין בְּשֵׁנִי. עד) הַמּוֹצִיא מִבְּשָׂרוֹ חוּץ לַחֲבוּרָתוֹ. עה) הָאוֹכֵל מִבְּשָׂרוֹ חוּץ מֵחֲבוּרָתוֹ. עו) הָאוֹכֵל מִבְּשָׂרוֹ נָא אוֹ מְבֻשָּׁל. עז) הַנֶּהֱנֶה מִן הַהֶקְדֵּשׁ בְּמֵזִיד. עח) הָאוֹכֵל טֶבֶל שֶׁעֲדַיִן לֹא הֻפְרַשׁ מִמֶּנּוּ מַעֲשֵׂר אֲפִלּוּ מַעֲשַׂר עָנִי אַף עַל פִּי שֶׁהוּרְמוּ תְּרוּמוֹתָיו. עט) הָאוֹכֵל מִבְּשַׂר נֶפֶשׁ חַיָּה שֶׁנִּגְמַר דִּינָהּ לִסְקִילָה אַף עַל פִּי שֶׁנִּשְׁחֲטָה. פ) הָאוֹכֵל בְּהֵמָה טְמֵאָה. פא) הָאוֹכֵל עוֹף טָמֵא. פב) הָאוֹכֵל דָּג טָמֵא. פג) הָאוֹכֵל שֶׁרֶץ הָעוֹף. פד) הָאוֹכֵל שֶׁרֶץ הָאָרֶץ. פה) הָאוֹכֵל שֶׁרֶץ הַמַּיִם. פו) הָאוֹכֵל רֶמֶשׂ הָאֲדָמָה אַף עַל פִּי שֶׁאֵינוֹ רָבֶה. פז) הָאוֹכֵל תּוֹלָעִים שֶׁבַּפֵּרוֹת אַחַר שֶׁפֵּרְשׁוּ. פח) הָאוֹכֵל נְבֵלָה. פט) הָאוֹכֵל טְרֵפָה. צ) הָאוֹכֵל אֵבֶר מִן הַחַי. צא) הָאוֹכֵל גִּיד הַנָּשֶׁה. צב) הָאוֹכֵל בָּשָׂר בְּחָלָב. צג) הַמְבַשֵּׁל בָּשָׂר בְּחָלָב. צד) הָאוֹכֵל מִתְּבוּאָה חֲדָשָׁה קֹדֶם הֲבָאַת הָעֹמֶר. [הַמַּקְרִיב מִנְחָה מִתְּבוּאָה חֲדָשָׁה קֹדֶם הֲבָאַת שְׁתֵּי הַלֶּחֶם]. צה) הָאוֹכֵל עָרְלָה. צו) הָאוֹכֵל כִּלְאֵי הַכֶּרֶם. צז) הָאוֹכֵל תַּעֲרֹבֶת חָמֵץ בְּפֶסַח. צח) הָאוֹכֵל חָמֵץ אַחַר חֲצוֹת. צט) הַמְקַיֵּם חָמֵץ בִּרְשׁוּתוֹ וּכְגוֹן שֶׁחִמֵּץ עִסָּתוֹ. ק) הַשּׁוֹתֶה יֵין נֶסֶךְ. קא) נָזִיר שֶׁאָכַל מִגֶּפֶן הַיַּיִן. קב) נָזִיר שֶׁגִּלֵּחַ. קג) נָזִיר שֶׁנִּטְמָא לְמֵת. קד) הַמְגַלֵּחַ אֶת הַנֶּתֶק. קה) הַחוֹתֵךְ סִימָנֵי צָרַעַת אוֹ שֶׁכְּוָאָן בְּאֵשׁ. קו) הָעוֹבֵד בְּנַחַל שֶׁנִּתְעָרְפָה בּוֹ הָעֶגְלָה. קז) הַזּוֹרֵעַ אֶרֶץ יִשְׂרָאֵל בִּשְׁבִיעִית. קח) הַזּוֹמֵר אֶת הָאִילָן בִּשְׁבִיעִית. קט) הַקּוֹצֵר סְפִיחַ בְּלֹא שִׁנּוּי. קי) הַבּוֹצֵר בְּלֹא שִׁנּוּי. קיא) הַזּוֹרֵעַ בִּשְׁנַת הַיּוֹבֵל. קיב) הַקּוֹצֵר בָּהּ בְּלֹא שִׁנּוּי. קיג) הַבּוֹצֵר בָּהּ בְּלֹא שִׁנּוּי. קיד) הַמְכַלֶּה פְּאַת שָׂדֶה וְלֹא נְתָנָהּ לֶעָנִי. קטו) הַמְעוֹלֵל כַּרְמוֹ וְלֹא נְתָנָהּ לֶעָנִי. קטז) הַמְלַקֵּט לֶקֶט וְלֹא נְתָנוֹ לֶעָנִי. קיז) פָּרַט כַּרְמוֹ וְלֹא נְתָנוֹ לֶעָנִי. קיח) הַלּוֹקֵחַ עֹמֶר הַשִּׁכְחָה וְלֹא נְתָנוֹ לֶעָנִי. קיט) הַלּוֹקֵחַ אֵם עַל בָּנִים וְלֹא שִׁלֵּחַ הָאֵם. קכ) הַזּוֹרֵעַ כִּלְאַיִם בָּאָרֶץ בִּזְרָעִים. קכא) הַזּוֹרֵעַ כִּלְאֵי הַכֶּרֶם בָּאָרֶץ. קכב) הַמַּרְכִּיב אִילָנוֹת כִּלְאַיִם בְּכָל מָקוֹם. קכג) הַמַּרְבִּיעַ בְּהֵמָה כִּלְאַיִם בְּכָל מָקוֹם. קכד) הַמַּנְהִיג בְּכִלְאַיִם בְּכָל מָקוֹם. קכה) הַחוֹסֵם בְּהֵמָה בְּעֵת מְלָאכָה בְּכָל מָקוֹם. קכו) הַשּׁוֹחֵט אוֹתוֹ וְאֶת בְּנוֹ בְּכָל מָקוֹם. קכז) הַמְמַשְׁכֵּן חֲבֵרוֹ בְּיָדוֹ וְלֹא הֶחְזִיר לוֹ הָעֲבוֹט. קכח) הַחוֹבֵל אַלְמָנָה וְלֹא הֶחְזִיר הַמַּשְׁכּוֹן. קכט) הַחוֹבֵל כֵּלִים שֶׁעוֹשִׂין בָּהֶן אֹכֶל נֶפֶשׁ. קל) עֵד זוֹמֵם שֶׁאֵין בּוֹ תַּשְׁלוּמִין. קלא) הַמַּכֶּה חֲבֵרוֹ הַכָּאָה שֶׁאֵין בָּהּ שְׁוֵה פְּרוּטָה. קלב) בֶּן סוֹרֵר וּמוֹרֶה בְּעֵדוּת רִאשׁוֹנָה. קלג) הַמּוֹצִיא שֵׁם רַע שֶׁנִּמְצָא דְּבָרוֹ שֶׁקֶר. קלד) הַמְקַלֵּל אֶת חֲבֵרוֹ בְּשֵׁם. קלה) הַנִּשְׁבָּע לַשֶּׁקֶר. קלו) הַנִּשְׁבָּע לַשָּׁוְא. קלז) הַמְחַלֵּל נִדְרוֹ. קלח) הַיּוֹצֵא חוּץ לַתְּחוּם בְּשַׁבָּת. קלט) הָעוֹשֶׂה מְלָאכָה בְּיוֹם טוֹב. קמ) הַמַּקִּיף פְּאַת הָרֹאשׁ. קמא) הַמַּקִּיף פְּאַת זָקָן. קמב) הַשּׂוֹרֵט עַל מֵת. קמג) הַקּוֹרֵחַ רֹאשׁוֹ עַל הַמֵּת. קמד) הַכּוֹתֵב כְּתֹבֶת קַעֲקַע. קמה) הַלּוֹבֵשׁ שַׁעַטְנֵז. קמו) הַקּוֹצֵץ אִילָנֵי מַאֲכָל דֶּרֶךְ הַשְׁחָתָה. קמז) אִישׁ שֶׁלָּבַשׁ מַלְבּוּשׁ אִשָּׁה. קמח) אִשָּׁה שֶׁלָּבְשָׁה מַלְבּוּשׁ אִישׁ. קמט) כֹּהֵן שֶׁנִּטְמָא לְמֵת. קנ) כֹּהֵן שֶׁקִּדֵּשׁ אִשָּׁה זוֹנָה וּבְעָלָהּ. קנא) כֹּהֵן שֶׁקִּדֵּשׁ גְּרוּשָׁה וּבְעָלָהּ. קנב) כֹּהֵן שֶׁקִּדֵּשׁ חֲלָלָה וּבְעָלָהּ. קנג) כֹּהֵן גָּדוֹל שֶׁבָּעַל אַלְמָנָה אַף עַל פִּי שֶׁלֹּא קִדְּשָׁהּ. קנד) הַמַּחֲזִיר גְּרוּשָׁתוֹ אַחַר שֶׁנִּתְקַדְּשָׁה. קנה) הַנּוֹשֵׂא זְקוּקָה לְיָבָם. קנו) הַבָּא עַל הַקְּדֵשָׁה. קנז) מַמְזֵר שֶׁנָּשָׂא בַּת יִשְׂרָאֵל וּבָעַל. קנח) פְּצוּעַ דַּכָּא שֶׁנָּשָׂא בַּת יִשְׂרָאֵל וּבָעַל. קנט) הַמְסָרֵס אִישׁ וְכֵן שְׁאָר זִכְרֵי בְּהֵמָה חַיָּה וְעוֹף. קס) אוֹנֵס שֶׁגֵּרֵשׁ אֲנוּסָתוֹ וְלֹא הֶחְזִירָהּ. קסא) הַמּוֹצִיא שֵׁם רַע שֶׁגֵּרֵשׁ אִשְׁתּוֹ וְלֹא הֶחֱזִירָהּ. קסב) הַקָּרֵב אֶל הָעֲרָיוֹת בְּדֶרֶךְ מִדַּרְכֵי הַזְּנוּת אַף עַל פִּי שֶׁלֹּא גִּלָּה עֶרְוָה וְזֶהוּ הֶחָשׁוּד עַל הָעֲרָיוֹת. קסג) הַמִּתְחַתֵּן בְּעַכּוּ\"ם. קסד) גֵּר עַמּוֹנִי שֶׁנָּשָׂא בַּת יִשְׂרָאֵל וּבָעַל. קסה) גֵּר מוֹאָבִי שֶׁנָּשָׂא בַּת יִשְׂרָאֵל וּבָעַל. קסו) מֶלֶךְ שֶׁהִרְבָּה נָשִׁים. קסז) מֶלֶךְ שֶׁהִרְבָּה סוּסִים. קסח) מֶלֶךְ שֶׁהִרְבָּה כֶּסֶף וְזָהָב: נִמְצְאוּ כָּל הַלּוֹקִים ר\"ז וְסִימָן לָהֶם יִלְקוּ זֵדִים:"],"Mishneh Torah, The Sanhedrin and the Penalties within Their Jurisdiction 6":["כָּל דַּיָּן שֶׁדָּן דִּינֵי מָמוֹנוֹת וְטָעָה אִם טָעָה בַּדְּבָרִים הַגְּלוּיִים וְהַיְדוּעִים כְּגוֹן דִּינִין הַמְפֹרָשִׁין בַּמִּשְׁנָה אוֹ בַּגְּמָרָא חוֹזֵר הַדִּין וּמַחְזִירִין הַדָּבָר כְּשֶׁהָיָה וְדָנִין בּוֹ כַּהֲלָכָה. וְאִם אִי אֶפְשָׁר לְהַחְזִיר כְּגוֹן שֶׁהָלַךְ זֶה שֶׁנָּטַל הַמָּמוֹן שֶׁלֹּא כַּדִּין לִמְדִינַת הַיָּם אוֹ שֶׁהָיָה אַלָּם אוֹ שֶׁטִּמֵּא דָּבָר טָהוֹר אוֹ שֶׁהוֹרָה בִּכְשֵׁרָה שֶׁהִיא טְרֵפָה וְהֶאֱכִילָהּ לַכְּלָבִים וְכַיּוֹצֵא בָּזֶה הֲרֵי זֶה פָּטוּר מִלְּשַׁלֵּם. אַף עַל פִּי שֶׁגָּרַם לְהַזִּיק לֹא נִתְכַּוֵּן לְהַזִּיק:","טָעָה בְּשִׁקּוּל הַדַּעַת כְּגוֹן דָּבָר שֶׁהוּא מַחְלֹקֶת תַּנָּאִים אוֹ אָמוֹרָאִים וְלֹא נִפְסְקָה הֲלָכָה כְּאֶחָד מֵהֶן בְּפֵרוּשׁ וְעָשָׂה כְּאֶחָד מֵהֶן וְלֹא יָדַע שֶׁכְּבָר פָּשַׁט הַמַּעֲשֶׂה בְּכָל הָעוֹלָם כְּדִבְרֵי הָאַחֵר. אִם הָיָה זֶה דַּיָּן מֻמְחֶה וְנָטַל רְשׁוּת מֵרֹאשׁ גָּלוּת. אוֹ שֶׁלֹּא הָיָה נוֹטֵל רְשׁוּת אֲבָל קִבְּלוּ אוֹתוֹ בַּעֲלֵי דִּינִין עֲלֵיהֶן. הוֹאִיל וְהוּא מֻמְחֶה חוֹזֵר הַדִּין. וְאִם אִי אֶפְשָׁר לְהַחְזִיר פָּטוּר מִלְּשַׁלֵּם. אֶחָד הַנּוֹטֵל רְשׁוּת מֵרֹאשׁ גָּלוּת אוֹ הַנּוֹטֵל רְשׁוּת מִבֵּית דִּין שֶׁל יִשְׂרָאֵל בְּאֶרֶץ יִשְׂרָאֵל אֲבָל לֹא בְּחוּצָה לָאָרֶץ כְּמוֹ שֶׁבֵּאַרְנוּ:","הָיָה הַטּוֹעֶה מֻמְחֶה וְלֹא נָטַל רְשׁוּת וְלֹא קִבְּלוּ אוֹתוֹ בַּעֲלֵי דִּינִין עֲלֵיהֶן. אוֹ שֶׁלֹּא הָיָה מֻמְחֶה אֲבָל קִבְּלוּ אוֹתוֹ בַּעֲלֵי דִּינִין עֲלֵיהֶן לָדוּן לָהֶן כַּדִּין וְטָעָה בְּשִׁקּוּל הַדַּעַת. אִם נָשָׂא וְנָתַן בַּיַּד מַה שֶּׁעָשָׂה עָשׂוּי וִישַׁלֵּם מִבֵּיתוֹ. אִם לֹא נָשָׂא וְנָתַן בַּיָּד יַחְזֹר הַדִּין. וְאִם אִי אֶפְשָׁר לְהַחְזִיר יְשַׁלֵּם מִבֵּיתוֹ:","אֲבָל מִי שֶׁאֵינוֹ מֻמְחֶה וְלֹא קִבְּלוּ אוֹתוֹ בַּעֲלֵי דִּינִין אַף עַל פִּי שֶׁנָּטַל רְשׁוּת הֲרֵי זֶה בִּכְלַל בַּעֲלֵי זְרוֹעַ וְאֵינוֹ בִּכְלַל הַדַּיָּנִין. לְפִיכָךְ אֵין דִּינָיו דִּין בֵּין טָעָה בֵּין לֹא טָעָה וְכָל אֶחָד מִבַּעֲלֵי דִּינִין אִם רָצָה חוֹזֵר וְדָן בִּפְנֵי בֵּית דִּין. וְאִם טָעָה וְנָשָׂא וְנָתַן בַּיָּד חַיָּב לְשַׁלֵּם מִבֵּיתוֹ וְחוֹזֵר וְלוֹקֵחַ מִבַּעַל דִּין זֶה שֶׁנָּתַן לוֹ שֶׁלֹּא כַּהֲלָכָה. וְאִם אֵין לוֹ לְהַחְזִיר אוֹ שֶׁטִּמֵּא אוֹ שֶׁהֶאֱכִיל דָּבָר הַמֻּתָּר לַכְּלָבִים יְשַׁלֵּם כְּדִין כָּל גּוֹרֵם לְהַזִּיק שֶׁזֶּה מִתְכַּוֵּן לְהַזִּיק הוּא:","דַּיָּן שֶׁטָּעָה וְחִיֵּב שְׁבוּעָה לְמִי שֶׁאֵינוֹ חַיָּב בָּהּ וְעָשָׂה זֶה פְּשָׁרָה עִם בַּעַל דִּינוֹ כְּדֵי שֶׁלֹּא יִשָּׁבַע וְאַחַר כָּךְ יָדַע שֶׁאֵינוֹ בֶּן שְׁבוּעָה. אַף עַל פִּי שֶׁקָּנוּ מִיָּדוֹ עַל הַפְּשָׁרָה אֵינָהּ כְּלוּם שֶׁלֹּא קִבֵּל עָלָיו לִתֵּן לוֹ אוֹ לִמְחל לוֹ אֶלָּא כְּדֵי שֶׁיִּפָּטֵר מִשְּׁבוּעָה שֶׁחִיְּבוֹ בָּהּ הַטּוֹעֶה וְכָל קִנְיָן בְּטָעוּת חוֹזֵר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","שְׁנַיִם שֶׁנִּתְעַצְּמוּ בַּדִּין אֶחָד אוֹמֵר נָדוּן כָּאן וְאֶחָד אוֹמֵר נַעֲלֶה לְבֵית דִּין הַגָּדוֹל שֶׁמָּא יִטְעוּ אֵלּוּ הַדַּיָּנִין וְיוֹצִיאוּ מָמוֹן שֶׁלֹּא כַּדִּין כּוֹפִין אוֹתוֹ וְדָן בְּעִירוֹ. וְאִם אָמַר כִּתְבוּ וּתְנוּ לִי מֵאֵי זֶה טַעַם דַּנְתּוּנִי שֶׁמָּא טְעִיתֶם כּוֹתְבִים וְנוֹתְנִין לוֹ וְאַחַר כָּךְ מוֹצִיאִין מִמֶּנּוּ. וְאִם הֻצְרַךְ לִשְׁאל דָּבָר מִבֵּית דִּין הַגָּדוֹל שֶׁבִּירוּשָׁלַיִם כּוֹתְבִים וְשׁוֹלְחִין וְשׁוֹאֲלִין וְדָנִין לָהֶם בְּעִירָם כְּפִי מַה שֶּׁיָּבוֹא בִּכְתַב בֵּית דִּין הַגָּדוֹל:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּשְׁאָר הַדִּינִין שֶׁזֶּה טוֹעֵן וְזֶה טוֹעֵן אוֹ כְּשֶׁאָמַר הַמַּלְוֶה נָדוּן כָּאן וְהַלּוֶֹה אוֹמֵר נֵלֵךְ לְבֵית דִּין הַגָּדוֹל. אֲבָל אִם אָמַר הַמַּלְוֶה נֵלֵךְ לְבֵית דִּין הַגָּדוֹל כּוֹפִין אֶת הַלּוֶֹה וְעוֹלֶה עִמּוֹ שֶׁנֶּאֱמַר (משלי כב ז) \"עֶבֶד לוֶֹה לְאִישׁ מַלְוֶה\". וְכֵן אִם טָעַן זֶה שֶׁהִזִּיקוֹ אוֹ גְּזָלוֹ וְרָצָה הַטּוֹעֵן לַעֲלוֹת כּוֹפִין בֵּית דִּין שֶׁבְּעִירוֹ אֶת הַנִּטְעָן לַעֲלוֹת עִמּוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁיִּהְיוּ שָׁם עֵדִים אוֹ רְאָיָה לַנִּגְזָל אוֹ לַנִּזָּק אוֹ לַמַּלְוֶה. אֲבָל טַעֲנָה רֵקָנִית אֵין מְחַיְּבִין אֶת הַנִּטְעָן לָצֵאת כְּלָל אֶלָּא נִשְׁבָּע בִּמְקוֹמוֹ וְנִפְטָר:","וְכֵן הַדִּין בַּזְּמַן הַזֶּה שֶׁאֵין שָׁם בֵּית דִּין גָּדוֹל אֲבָל יֵשׁ מְקוֹמוֹת שֶׁיֵּשׁ בָּהֶן חֲכָמִים גְּדוֹלִים מֻמְחִין לָרַבִּים וּמְקוֹמוֹת שֶׁיֵּשׁ בָּהֶן תַּלְמִידִים שֶׁאֵינָן כְּמוֹתָן. אִם אָמַר הַמַּלְוֶה נֵלֵךְ לְמָקוֹם פְּלוֹנִי שֶׁבְּאֶרֶץ פְּלוֹנִית לִפְלוֹנִי וּפְלוֹנִי הַגָּדוֹל וְנָדוּן לְפָנָיו בְּדִין זֶה. שֶׁכּוֹפִין אֶת הַלּוֶֹה וְהוֹלֵךְ עִמּוֹ. וְכֵן הָיוּ מַעֲשִׂים בְּכָל יוֹם בִּסְפָרַד:"],"Mishneh Torah, Theft 9":["כָּל הַגּוֹנֵב נֶפֶשׁ אָדָם עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (שמות כ יג) (דברים ה טז) \"לֹא תִגְנֹב\". פָּסוּק זֶה הָאָמוּר בַּעֲשֶׂרֶת הַדְּבָרִים הִיא אַזְהָרָה לְגוֹנֵב נְפָשׁוֹת. וְכֵן הַמּוֹכְרוֹ עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁזֶּה בִּכְלַל (ויקרא כה מב) \"לֹא יִמָּכְרוּ מִמְכֶּרֶת עָבֶד\". וְאֵין לוֹקִין עַל שְׁנֵי לָאוִין אֵלּוּ מִפְּנֵי שֶׁהוּא לָאו שֶׁנִּתָּן לְאַזְהָרַת מִיתַת בֵּית דִּין שֶׁנֶּאֱמַר (דברים כד ז) \"כִּי יִמָּצֵא אִישׁ גֹּנֵב נֶפֶשׁ מֵאֶחָיו\" וְגוֹ' וּמִיתָתוֹ בְּחֶנֶק:","אֵין הַגַּנָּב חַיָּב מִיתַת חֶנֶק עַד שֶׁיִּגְנֹב אֶת הַיִּשְׂרָאֵל וְיַכְנִיסֵנוּ לִרְשׁוּתוֹ וְיִשְׁתַּמֵּשׁ בּוֹ וְיִמְכְּרֶנּוּ לַאֲחֵרִים שֶׁנֶּאֱמַר (דברים כד ז) \"וְהִתְעַמֶּר בּוֹ וּמְכָרוֹ\". וַאֲפִלּוּ לֹא נִשְׁתַּמֵּשׁ בּוֹ אֶלָּא בְּפָחוֹת מִשְּׁוֵה פְּרוּטָה כְּגוֹן שֶׁנִּשְׁעַן עָלָיו אוֹ נִסְמַךְ בּוֹ אַף עַל פִּי שֶׁהַנִּגְנָב יָשֵׁן הֲרֵי זֶה נִשְׁתַּמֵּשׁ בּוֹ:","גְּנָבוֹ וְנִשְׁתַּמֵּשׁ בּוֹ וּמְכָרוֹ וַעֲדַיִן הַגָּנוּב בִּרְשׁוּת עַצְמוֹ וְלֹא הִכְנִיסוֹ הַגַּנָּב לִרְשׁוּתוֹ פָּטוּר. גְּנָבוֹ וְהוֹצִיאוֹ לִרְשׁוּתוֹ וְנִשְׁתַּמֵּשׁ בּוֹ וְלֹא מְכָרוֹ אוֹ מְכָרוֹ קֹדֶם שֶׁנִּשְׁתַּמֵּשׁ בּוֹ אוֹ נִשְׁתַּמֵּשׁ בּוֹ וּמְכָרוֹ לְאֶחָד מִקְּרוֹבָיו שֶׁל גָּנוּב כְּגוֹן שֶׁמְּכָרוֹ לְאָבִיו אוֹ לְאָחִיו הֲרֵי זֶה פָּטוּר שֶׁנֶּאֱמַר (דברים כד ז) \"גֹּנֵב נֶפֶשׁ מֵאֶחָיו\" עַד שֶׁיַּבְדִּילֶנּוּ מֵאֶחָיו וּמִקְּרוֹבָיו בַּמְּכִירָה. וְכֵן אִם גְּנָבוֹ וְהוּא יָשֵׁן וְנִשְׁתַּמֵּשׁ בּוֹ כְּשֶׁהוּא יָשֵׁן וּמְכָרוֹ וַעֲדַיִן הוּא יָשֵׁן הֲרֵי זֶה פָּטוּר:","וְכֵן אִם גָּנַב אִשָּׁה וּמְכָרָהּ לְעֻבָּרֶיהָ בִּלְבַד כְּגוֹן שֶׁהִתְנָה עַל הַלּוֹקֵחַ שֶׁזּוֹ הַשִּׁפְחָה לִי וְאֵין לְךָ אֶלָּא הַוְּלָדוֹת הֲרֵי זֶה פָּטוּר:","הַגּוֹנֵב אֶת בְּנוֹ אוֹ אֶת אָחִיו הַקָּטָן וְכֵן הָאַפּוֹטְרוֹפִּין שֶׁגָּנְבוּ אֶת הַיְתוֹמִים שֶׁהֵן סְמוּכִין אֶצְלָם וּבַעַל הַבַּיִת שֶׁגָּנַב אֶחָד מִבְּנֵי בֵּיתוֹ הַסְּמוּכִין עַל שֻׁלְחָנוֹ וּמְלַמֵּד תִּינוֹקוֹת שֶׁגָּנַב אֶחָד מִן הַקְּטַנִּים הַלּוֹמְדִים אֶצְלוֹ. אַף עַל פִּי שֶׁנִּשְׁתַּמֵּשׁ בּוֹ וּמְכָרוֹ פָּטוּר שֶׁנֶּאֱמַר (שמות כא טז) \"וְנִמְצָא בְיָדוֹ\" פְּרָט לְאֵלּוּ שֶׁהֵן מְצוּיִין בְּיָדָם:","אֶחָד הַגּוֹנֵב אֶת הַגָּדוֹל אוֹ הַגּוֹנֵב אֶת הַקָּטָן בֶּן יוֹמוֹ שֶׁכָּלוּ לוֹ חֳדָשָׁיו בֵּין זָכָר בֵּין נְקֵבָה בֵּין שֶׁהָיָה הַגַּנָּב אִישׁ אוֹ אִשָּׁה הֲרֵי אֵלּוּ נֶהֱרָגִין שֶׁנֶּאֱמַר (דברים כד ז) \"גֹּנֵב נֶפֶשׁ\" מִכָּל מָקוֹם. וְאֶחָד הַגּוֹנֵב אֶת יִשְׂרָאֵל אוֹ שֶׁגָּנַב גֵּר אוֹ עֶבֶד מְשֻׁחְרָר שֶׁנֶּאֱמַר (דברים כד ז) \"נֶפֶשׁ מֵאֶחָיו\" וְאֵלּוּ בִּכְלַל אַחֵינוּ הֵן בְּתוֹרָה וּבְמִצְוֹת. אֲבָל הַגּוֹנֵב אֶת הָעֶבֶד אוֹ מִי שֶׁחֶצְיוֹ עֶבֶד וְחֶצְיוֹ בֶּן חוֹרִין פָּטוּר:","הַבָּא בַּמַּחְתֶּרֶת בֵּין בַּיּוֹם בֵּין בַּלַּיְלָה אֵין לוֹ דָּמִים אֶלָּא אִם הֲרָגוֹ בַּעַל הַבַּיִת אוֹ שְׁאָר הָאָדָם פְּטוּרִין. וּרְשׁוּת יֵשׁ לַכּל לְהָרְגוֹ בֵּין בְּחל בֵּין בְּשַׁבָּת בְּכָל מִיתָה שֶׁיְּכוֹלִין לַהֲמִיתוֹ שֶׁנֶּאֱמַר (שמות כב א) \"אֵין לוֹ דָּמִים\":","וְאֶחָד הַבָּא בַּמַּחְתֶּרֶת אוֹ גַּנָּב שֶׁנִּמְצָא בְּתוֹךְ גַּגּוֹ שֶׁל אָדָם אוֹ בְּתוֹךְ חֲצֵרוֹ אוֹ בְּתוֹךְ קַרְפִּיפוֹ בֵּין בַּיּוֹם בֵּין בַּלַּיְלָה. וְלָמָּה נֶאֱמַר (שמות כב א) \"מַחְתֶּרֶת\" לְפִי שֶׁדֶּרֶךְ רֹב הַגַּנָּבִים לָבוֹא בַּמַּחְתֶּרֶת בַּלַּיְלָה:","וּמִפְּנֵי מָה הִתִּירָה תּוֹרָה דָּמוֹ שֶׁל גָּנַב אַף עַל פִּי שֶׁבָּא עַל עִסְקֵי מָמוֹן. לְפִי שֶׁחֶזְקָתוֹ שֶׁאִם עָמַד בַּעַל הַבַּיִת לְפָנָיו וּמְנָעוֹ יַהַרְגֵנוּ וְנִמְצָא זֶה הַנִּכְנָס לְבֵית חֲבֵרוֹ לִגְנֹב כְּרוֹדֵף אַחַר חֲבֵרוֹ לְהָרְגוֹ. וּלְפִיכָךְ יַהֲרֹג בֵּין שֶׁהָיָה גָּדוֹל בֵּין שֶׁהָיָה קָטָן בֵּין זָכָר בֵּין נְקֵבָה:","הָיָה הַדָּבָר בָּרוּר לְבַעַל הַבַּיִת שֶׁזֶּה הַגַּנָּב הַבָּא עָלָיו אֵינוֹ הוֹרְגוֹ וְלֹא בָּא אֶלָּא עַל עִסְקֵי מָמוֹן אָסוּר לְהָרְגוֹ וְאִם הֲרָגוֹ הֲרֵי זֶה הוֹרֵג נֶפֶשׁ. שֶׁנֶּאֱמַר (שמות כב ב) \"אִם זָרְחָה הַשֶּׁמֶשׁ עָלָיו\" אִם בָּרוּר לְךָ הַדָּבָר כַּשֶׁמֶשׁ שֶׁיֵּשׁ לוֹ שָׁלוֹם עִמְּךָ אֶל תַּהַרְגֵהוּ. לְפִיכָךְ אָב הַבָּא בַּמַּחְתֶּרֶת עַל בְּנוֹ אֵינוֹ נֶהֱרָג שֶׁוַּדַּאי שֶׁאֵינוֹ הוֹרְגוֹ. אֲבָל הַבֵּן הַבָּא עַל אָבִיו נֶהֱרָג:","וְכֵן הַגַּנָּב שֶׁגָּנַב וְיָצָא. אוֹ שֶׁלֹּא גָּנַב וּמְצָאוֹ יוֹצֵא מִן הַמַּחְתֶּרֶת הוֹאִיל וּפָנָה עֹרֶף וְאֵינוֹ רוֹדֵף יֵשׁ לוֹ דָּמִים. וְכֵן אִם הִקִּיפוּהוּ בְּנֵי אָדָם אוֹ עֵדִים אַף עַל פִּי שֶׁעֲדַיִן הוּא בִּרְשׁוּת זֶה שֶׁבָּא עָלָיו אֵינוֹ נֶהֱרָג. וְאֵין צָרִיךְ לוֹמַר אִם בָּא לְבֵית דִּין שֶׁאֵינוֹ נֶהֱרָג:","וְכֵן הַבָּא בַּמַּחְתֶּרֶת לְתוֹךְ גִּנָּתוֹ אוֹ לְתוֹךְ שָׂדֵהוּ אוֹ לְתוֹךְ הַדִּיר וְהַסַּהַר יֵשׁ לוֹ דָּמִים. שֶׁחֶזְקָתוֹ שֶׁבָּא עַל הַמָּמוֹן בִּלְבַד לְפִי שֶׁאֵין רֹב הַבְּעָלִים מְצוּיִים בִּמְקוֹמוֹת אֵלּוּ:","כָּל גַּנָּב שֶׁיֵּשׁ לוֹ דָּמִים אִם נָפַל עָלָיו גַּל בְּשַׁבָּת מְפַקְּחִים עָלָיו. וְאִם שָׁבַר כֵּלִים בְּבִיאָתוֹ חַיָּב בְּתַשְׁלוּמִין. אֲבָל מִי שֶׁאֵין לוֹ דָּמִים שֶׁשָּׁבַר כֵּלִים בְּבִיאָתוֹ פָּטוּר כְּמוֹ שֶׁבֵּאַרְנוּ: סְלִיקוּ לְהוּ הִלְכוֹת גְּנֵבָה בְּסַ\"ד"],"Mishneh Torah, Those Who Defile Bed or Seat 13":["כֹּהֵן שֶׁטִּהֵר כֵּלָיו לְגַת זוֹ וְהִנִּיחָן לַגַּת הַבָּאָה הֲרֵי אֵלּוּ בְּחֶזְקָתָן. שֶׁאֵין עַמֵּי הָאָרֶץ נוֹגְעִין בְּכֵלִים שֶׁל כֹּהֵן זֶה שֶׁהֵן בְּתוֹךְ גִּתּוֹ מִפְּנֵי שֶׁהוּא אוֹכֵל טָהֳרוֹת. אֲבָל שֶׁל יִשְׂרָאֵל טְמֵאוֹת עַד שֶׁיֹּאמַר בְּלִבִּי הָיָה לִשְׁמֹר עַם הָאָרֶץ שֶׁיִּכָּנֵס לַגַּת שֶׁלֹּא יִגַּע בְּכֵלִים:","הָרוֹצֶה לַעֲשׂוֹת יֵינוֹ בְּטָהֳרָה בְּאֻמָּנִין עַמֵּי הָאָרֶץ הֲרֵי זֶה מַטְבִּיל אֶת הַבּוֹצְרִים. וְכֵן אִם הָיָה עוֹשֶׂה שֶׁמֶן מַטְבִּיל אֶת הַבַּדָּדִין. וְצָרִיךְ לַעֲמֹד עַל הָאֻמָּנִים עַד שֶׁיִּטְבְּלוּ בְּפָנָיו שֶׁהֲרֵי אֵינָן יוֹדְעִים הִלְכוֹת טְבִילָה וַחֲצִיצָה. יָצְאוּ חוּץ לְפֶתַח בֵּית הַבַּד וְנִפְנוּ אֲחוֹרֵי הַגָּדֵר וְחָזְרוּ הֲרֵי אֵלּוּ בְּטָהֳרָתָן. עַד כַּמָּה יַרְחִיקוּ וְהֵם טְהוֹרִין עַד כְּדֵי שֶׁלֹּא יִסָּתְרוּ מֵעֵינָיו. אֲבָל אִם נִסְתְּרוּ מֵעֵינָיו חָזְרוּ לְטֻמְאָתָם עַד שֶׁיַּטְבִּילֵם פַּעַם אַחֶרֶת וְיַעֲרִיב שִׁמְשָׁן:","הַבַּדָּדִין וְהַבּוֹצְרִים שֶׁנִּמְצֵאת טֻמְאָה לִפְנֵיהֶן נֶאֱמָנִין לוֹמַר לֹא נָגַעְנוּ. וְכֵן בְּתִינוֹקוֹת שֶׁלָּהֶם:","הַמְטַהֵר אֶת הַבַּדָּדִין וְהִכְנִיסָן לְבֵית הַבַּד וְנָעַל עֲלֵיהֶן. אִם הָיוּ שָׁם כֵּלִים שֶׁנִּטְמְאוּ בְּמִדְרָס הֲרֵי בֵּית הַבַּד כֻּלּוֹ טָמֵא שֶׁמָּא נָגְעוּ בְּאוֹתָן הַכֵּלִים. וַאֲפִלּוּ רָאָה אוֹתָם מִקֹּדֶם נִזְהָרִין מֵאוֹתָם הַכֵּלִים מִפְּנֵי טֻמְאָתָן הֲרֵי בֵּית הַבַּד טָמֵא שֶׁמָּא הֵסִיטוּ וְהֵן מְדַמִּין שֶׁאֵין הַמֵּסִיט טָמֵא שֶׁאֵין עַמֵּי הָאָרֶץ בְּקִיאִין בְּטֻמְאַת הֶסֵּט:","הָיוּ חַמָּרָיו וּפוֹעֲלָיו טוֹעֲנִין טָהֳרוֹת וְעוֹבְרִין לְפָנָיו אַף עַל פִּי שֶׁהִפְלִיגוּ יוֹתֵר מִמִּיל הֲרֵי אֵלּוּ טְהוֹרוֹת מִפְּנֵי שֶׁהֵן בְּחֶזְקַת שֶׁהוּא שׁוֹמְרָן וְהֵן מְפַחֲדִין לִגַּע וְאוֹמְרִים עַכְשָׁו יָבוֹא שֶׁהֲרֵי הוּא יָבוֹא אַחֲרֵינוּ. אֲבָל אִם אָמַר לָהֶם צְאוּ וַאֲנִי אָבוֹא אַחֲרֵיכֶם כֵּיוָן שֶׁנִּתְכַּסּוּ מֵעֵינָיו הֲרֵי הֵן טְמֵאוֹת:","חָבֵר שֶׁהָיָה לָבוּשׁ בְּחָלוּק וְעָטוּף בְּטַלִּית וּמְהַלֵּךְ וְאָמַר בְּלִבִּי הָיָה לִשְׁמֹר אֶת הֶחָלוּק וְהָיִיתִי נִזְהָר בּוֹ וְהִסַּחְתִּי דַּעְתִּי מִן הַטַּלִּית. הֲרֵי הֶחָלוּק בְּטָהֳרָתוֹ וְהַטַּלִּית טְמֵאָה שֶׁמָּא נָגַע בָּהּ עַם הָאָרֶץ. הָיָה סַל עַל כְּתֵפוֹ וּמַגְרֵפָה בְּתוֹךְ הַסַּל וְאָמַר בְּלִבִּי הָיָה לִשְׁמֹר אֶת הַסַּל וְלִשְׁמֹר אֶת הַמַּגְרֵפָה מִדָּבָר הַמְטַמְּאָהּ אֲבָל לֹא מִדָּבָר הַפּוֹסְלָהּ הַסַּל טָהוֹר וְהַמַּגְרֵפָה טְמֵאָה. וְכָל תְּרוּמָה שֶׁבַּסַּל פְּסוּלָה מִפְּנֵי הַמַּגְרֵפָה טְמֵאָה שֶׁפּוֹסֶלֶת הָאֳכָלִין שֶׁבַּסַּל. הָיָה מִשְׁתַּמֵּשׁ מִן הֶחָבִית בְּטָהֳרָה בְּחֶזְקַת שֶׁהִיא חֻלִּין וְאַחַר כָּךְ נִמְצֵאת תְּרוּמָה אַף עַל פִּי שֶׁהִיא טְהוֹרָה הֲרֵי הִיא אֲסוּרָה בַּאֲכִילָה שֶׁמָּא נָגַע בָּהּ טְבוּל יוֹם שֶׁהוּא פּוֹסֵל בִּתְרוּמָה וְטָהוֹר בְּחֻלִּין כְּמוֹ שֶׁיִּתְבָּאֵר. וְאֵינוֹ דּוֹמֶה מְשַׁמֵּר תְּרוּמָה לִמְשַׁמֵּר חֻלִּין. וְאִם אָמַר בְּלִבִּי הָיָה לְשָׁמְרוֹ אֲפִלּוּ מִדָּבָר הַפּוֹסְלָהּ הֲרֵי זוֹ מֻתֶּרֶת בַּאֲכִילָה. נִתְחַלְּפוּ לוֹ כֵּלִים שֶׁל שַׁבָּת בְּכֵלִים שֶׁל חֹל וּלְבָשָׁן נִטְמְאוּ. שֶׁאֵינוֹ מְשַׁמֵּר כֵּלִים שֶׁל חֹל כְּכֵלִים שֶׁל שַׁבָּת. מַעֲשֶׂה בִּשְׁתֵּי נָשִׁים חֲבֵרוֹת שֶׁנִּתְחַלְּפוּ לָהֶן כְּלֵיהֶן בְּבֵית הַמֶּרְחָץ וּבָא מַעֲשֶׂה לִפְנֵי חֲכָמִים וְטִמְּאוּ הַכּל. אֲפִלּוּ נָפְלָה מַעֲפַרְתָּהּ מִמֶּנָּה וְאָמְרָה לְחָבֵר תְּנָה לִי וּנְתָנָהּ לָהּ נִטְמֵאת גְּזֵרָה שֶׁמָּא יִתְּנֶנָּה לָהּ עַם הָאָרֶץ אוֹ שֶׁלֹּא יִהְיֶה הֶחָבֵר מְשַׁמְּרָהּ שֶׁאֵין אָדָם מְשַׁמֵּר כֵּלִים שֶׁאֵינָן שֶׁלּוֹ כְּכֵלָיו אֶלָּא אִם כֵּן הוֹדִיעַ שֶׁסָּמַךְ עָלָיו:","חָבֵר שֶׁמֵּת וְהִנִּיחַ טָהֳרוֹת הֲרֵי אֵלּוּ טְהוֹרוֹת. הִנִּיחַ כֵּלִים הֲרֵי הֵן טְמֵאִים שֶׁאֲנִי אוֹמֵר שֶׁמָּא נִטְמְאוּ וְהִזָּה עֲלֵיהֶם בַּשְּׁלִישִׁי וְלֹא הִזָּה עֲלֵיהֶן בַּשְּׁבִיעִי. אוֹ שֶׁמָּא הִזָּה עֲלֵיהֶם בַּשְּׁבִיעִי וַעֲדַיִן לֹא הִטְבִּיל. אוֹ שֶׁמָּא לֹא הִזָּה עֲלֵיהֶן בַּשְּׁבִיעִי כָּל עִקָּר:","מִי שֶׁאָמַר לוֹ עֵד אֶחָד נִטְמְאוּ טָהֳרוֹתֶיךָ וְהַלָּה שׁוֹתֵק הֲרֵי זֶה נֶאֱמָן וַהֲרֵי הֵן טְמֵאוֹת. וְאִם הִכְחִישׁוֹ וְאָמַר לֹא נִטְמְאוּ הֲרֵי הֵן בְּחֶזְקָתָן עַד שֶׁיָּעִידוּ שְׁנַיִם. הָיָה עוֹשֶׂה עִמּוֹ בְּטָהֳרוֹת אוֹ בִּזְבָחִים וּלְאַחַר זְמַן מְצָאוֹ וְאָמַר לוֹ בְּשָׁעָה שֶׁפָּגַע בּוֹ טָהֳרוֹת שֶׁעָשִׂיתִי עִמְּךָ נִטְמְאוּ וּזְבָחִים שֶׁעָשִׂיתִי עִמְּךָ נִתְפַּגְּלוּ הֲרֵי זֶה נֶאֱמָן. אֲבָל אִם פָּגַע בּוֹ וְלֹא אָמַר לוֹ כְּלוּם וְאַחַר כָּךְ פָּגַע בּוֹ פַּעַם שְׁנִיָּה וְאָמַר לוֹ אֵינוֹ נֶאֱמָן אֶלָּא הֲרֵי זְבָחָיו בְּחֶזְקַת כַּשְׁרוּת וְטָהֳרוֹתָיו בְּחֶזְקַת טָהֳרָה: בְּרִיךְ רַחֲמָנָא דְּסַיְּעָן"],"Mishneh Torah, Tithes 12":["הַלוֹקֵחַ פֵּרוֹת מִמִּי שֶׁאֵינוֹ נֶאֱמָן עַל הַמַּעַשְׂרוֹת וְשָׁכַח לְעַשְּׂרָן וְנִכְנְסָה שַׁבָּת אוֹ יוֹם טוֹב שֶׁאֵינוֹ יָכוֹל לְעַשֵּׂר הֲרֵי זֶה שׁוֹאֲלוֹ. וְאִם אָמַר לוֹ מְעֻשָּׂרִין הֵן אוֹכֵל עַל פִּיו בְּשַׁבָּת. וְכֵן אִם אָמַר לוֹ אֶחָד שֶׁאֵינוֹ נֶאֱמָן מְעֻשָּׂרִין הֵן אוֹכֵל עַל פִּיו בְּאוֹתָהּ שַׁבָּת. וַאֲפִלּוּ הָיוּ לוֹ פֵּרוֹת אֲחֵרוֹת מְתֻקָּנִין מֵאוֹתוֹ הַמִּין מִפְּנֵי שֶׁאֵימַת שַׁבָּת עַל עַמֵּי הָאָרֶץ וְאֵינוֹ עוֹבֵר בָּהּ עֲבֵרָה:","אַף עַל פִּי שֶׁהוּא אוֹכֵל עַל פִּיו בְּשַׁבָּת הֲרֵי זֶה לֹא יֹאכַל מֵאוֹתָן הַפֵּרוֹת לְמוֹצָאֵי שַׁבָּת עַד שֶׁיְּעַשֵּׂר דְּמַאי עַל הַכּל עַל שֶׁאָכַל בְּשַׁבָּת וְעַל הַנִּשְׁאָר שֶׁלֹּא הֵקֵלּוּ וְהֶאֱמִינוּהוּ אֶלָּא לְצֹרֶךְ אוֹתָהּ שַׁבָּת. הָיְתָה שַׁבָּת וְיוֹם טוֹב סָמוּךְ לָהּ וּשְׁאָלוֹ בְּאֶחָד מֵהֶן אוֹכֵל אַף בַּשֵּׁנִי. מִפְּנֵי שֶׁלֹּא נִרְאֶה לְעַשֵּׂר בֵּינְתַיִם. וְכֵן בִּשְׁנֵי יָמִים טוֹבִים שֶׁל גָּלֻיּוֹת:","הַנִּשְׁבָּע עַל חֲבֵרוֹ שֶׁיֹּאכַל עִמּוֹ בְּשַׁבָּת וְהוּא אֵינוֹ מַאֲמִינוֹ עַל הַמַּעַשְׂרוֹת שׁוֹאֵל וְאוֹכֵל עַל פִּיו בַּשַּׁבָּת הָרִאשׁוֹנָה בִּלְבַד. אֲבָל בְּשַׁבָּת שְׁנִיָּה אַף עַל פִּי שֶׁנָּדַר מִמֶּנּוּ הֲנָאָה אִם לֹא יֹאכַל אֶצְלוֹ לֹא יֹאכַל עַד שֶׁיְּעַשֵּׂר דְּמַאי:","מִי שֶׁאֵינוֹ נֶאֱמָן שֶׁרְאִינוּהוּ שֶׁהִפְרִישׁ תְּרוּמַת מַעֲשֵׂר מִפֵּרוֹתָיו שֶׁהֵן דְּמַאי וּרְאִינוּהוּ שֶׁחָזְרָה וְנָפְלָה בְּפָנֵינוּ בֵּין לְמָקוֹם אַחֵר בֵּין לִמְקוֹמָהּ וְחָזַר וְאָמַר הִפְרַשְׁתִּיהָ נֶאֱמָן אֲפִלּוּ בְּחל וְאוֹכֵל עַל פִּיו. כְּשֵׁם שֶׁאֵימַת שַׁבָּת עַל עַמֵּי הָאָרֶץ כָּךְ אֵימַת דִּמּוּעַ עֲלֵיהֶם וְאֵינָן חֲשׁוּדִין לְהַאֲכִיל אֶת הַמְדֻמָּע:","מִי שֶׁאֵינוֹ נֶאֱמָן שֶׁרְאִינוּהוּ שֶׁהִפְרִישׁ מַעֲשֵׂר רִאשׁוֹן מִפֵּרוֹת אֵלּוּ וְאָמַר שֶׁהִפְרִישׁ מֵהֶן מַעֲשֵׂר שֵׁנִי נֶאֱמָן. הִפְרִישׁ מַעֲשֵׂר שֵׁנִי בְּפָנֵינוּ וְאָמַר שֶׁהִפְרִישׁ מַעֲשֵׂר רִאשׁוֹן אֵינוֹ נֶאֱמָן שֶׁהַשֵּׁנִי שֶׁלּוֹ. וְהַנֶּאֱמָן עַל הַשֵּׁנִי אֵינוֹ נֶאֱמָן עַל הָרִאשׁוֹן. וְהַנֶּאֱמָן עַל הָרִאשׁוֹן נֶאֱמָן עַל הַשֵּׁנִי. לְפִיכָךְ מִי שֶׁאֵינוֹ נֶאֱמָן שֶׁהוֹצִיא פֵּרוֹת מִבֵּיתוֹ וְאָמַר אֵלּוּ מַעֲשֵׂר רִאשׁוֹן נֶאֱמָן. וְאֵין מַפְרִישִׁין מֵהֶן תְּרוּמוֹת וּמַעַשְׂרוֹת. וְאִם אָמַר אֵלּוּ מַעֲשֵׂר שֵׁנִי אֵינוֹ נֶאֱמָן וַהֲרֵי הֵן דְּמַאי וּמַפְרִישִׁין מֵהֶן תְּרוּמַת מַעֲשֵׂר. וְיֵרָאֶה לִי שֶׁהוּא פּוֹדֶה אֶת כֻּלָּם:","הָאוֹמֵר לְמִי שֶׁאֵינוֹ נֶאֱמָן עַל הַמַּעַשְׂרוֹת קַח לִי מִמִּי שֶׁהוּא מְעַשֵּׂר וְהָלַךְ וְלָקַח וְהֵבִיא לוֹ אֵינוֹ נֶאֱמָן. וְאִם אָמַר לוֹ קַח לִי מֵאִישׁ פְּלוֹנִי הֲרֵי זֶה נֶאֱמָן לוֹמַר מִמֶּנּוּ לָקַחְתִּי שֶׁהֲרֵי מִתְיָרֵא שֶׁמָּא יִשְׁאָלֶנּוּ. הָלַךְ לִקַּח לוֹ מֵאוֹתוֹ פְּלוֹנִי וְאָמַר לוֹ מְצָאתִיו וְלָקַחְתִּי לְךָ מֵאַחֵר שֶׁהוּא נֶאֱמָן אֵינוֹ נֶאֱמָן:","הַנִּכְנָס לְעִיר וְאֵינוֹ מַכִּיר אָדָם שָׁם וְאָמַר מִי כָּאן נֶאֱמָן מִי כָּאן מְעַשֵּׂר וְאָמַר לוֹ אֶחָד אֲנִי. אֵינוֹ נֶאֱמָן. אָמַר לוֹ אִישׁ פְּלוֹנִי הֲרֵי זֶה נֶאֱמָן. וְלוֹקֵחַ מֵאוֹתוֹ פְּלוֹנִי אַף עַל פִּי שֶׁאֵינוֹ מַכִּירוֹ וְהוֹלֵךְ וְאוֹכֵל עַל פִּיו. הָלַךְ וְלָקַח מִמֶּנּוּ וְשָׁאַל לוֹ מִי כָּאן מוֹכֵר יַיִן יָשָׁן אָמַר לוֹ זֶה שֶׁשְּׁלָחֲךָ אֶצְלִי אַף עַל פִּי שֶׁהֵן כְּגוֹמְלִין זֶה אֶת זֶה הֲרֵי אֵלּוּ נֶאֱמָנִין:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּזְמַן שֶׁאֵינוֹ מַכִּיר אָדָם שָׁם. אֲבָל אִם מַכִּיר אָדָם שָׁם לֹא יִקַּח אֶלָּא מִן הַמֻּמְחֶה. וְאִם שָׁהָה שָׁם שְׁלֹשִׁים יוֹם אַף עַל פִּי שֶׁאֵינוֹ מַכִּיר אָדָם שָׁם לֹא יִקַּח אֶלָּא מִן הַמֻּמְחֶה:","וְלֹא הִתִּירוּ דְּבָרִים אֵלּוּ אֶלָּא בִּתְרוּמוֹת וּמַעַשְׂרוֹת. אֲבָל לְעִנְיַן פֵּרוֹת שְׁבִיעִית אוֹ לְעִנְיַן טָהֳרוֹת לֹא יִקַּח אֶלָּא מִן הַמֻּמְחֶה:","הַחַמָּרִין שֶׁנִּכְנְסוּ לָעִיר וְאָמַר אֶחָד מֵהֶן פֵּרוֹת אֵלּוּ אֵינָם מְתֻקָּנִים וּפֵרוֹת חֲבֵרִי מְתֻקָּנִין אֵינוֹ נֶאֱמָן שֶׁמָּא קְנוּנְיָא עָשׂוּ בֵּינֵיהֶן:","הַמּוֹכֵר פֵּרוֹת בְּסוּרְיָא וְאָמַר מִשֶּׁל אֶרֶץ יִשְׂרָאֵל הֵם חַיָּב הַלּוֹקֵחַ לְעַשֵּׂר. מְעֻשָּׂרִין הֵן נֶאֱמָן שֶׁהַפֶּה שֶׁאָסַר הוּא הַפֶּה שֶׁהִתִּיר. מִשֶּׁלִּי הֵן חַיָּב לְעַשֵּׂר. מְעֻשָּׂרִין הֵן נֶאֱמָן שֶׁהַפֶּה שֶׁאָסַר הוּא הַפֶּה שֶׁהִתִּיר. וְאִם יָדוּעַ שֶׁיֵּשׁ לוֹ קַרְקַע בְּסוּרְיָא וְהָיָה רֹב מִמְכָּרוֹ מִשָּׂדֵהוּ חַיָּב הַלּוֹקֵחַ מִמֶּנּוּ לְעַשֵּׂר. שֶׁחֶזְקָתוֹ שֶׁמִּשָּׂדֵהוּ הֱבִיאָם:","עֲנִיִּים שֶׁאָמְרוּ פֵּרוֹת אֵלּוּ שֶׁל לֶקֶט שִׁכְחָה וּפֵאָה הֲרֵי אֵלּוּ נֶאֱמָנִין כָּל זְמַן הַגֳּרָנוֹת שֶׁהַלֶּקֶט וְהַשִּׁכְחָה וְהַפֵּאָה מְצוּיִים. וְהוּא שֶׁיִּהְיֶה קָרוֹב מִן הַגֹּרֶן כְּדֵי שֶׁיֵּצֵא וְיָבוֹא בּוֹ בַּיּוֹם. וְאִם אָמְרוּ שֶׁל מַעֲשַׂר עָנִי הֵם הֲרֵי אֵלּוּ נֶאֱמָנִין כָּל הַשָּׁנָה כֻּלָּהּ. וְאֵינָן נֶאֱמָנִין אֶלָּא עַל דָּבָר שֶׁדֶּרֶךְ בְּנֵי אָדָם לִתְּנוֹ:","כֵּיצַד. חִטִּים אֵלּוּ לֶקֶט שִׁכְחָה וּפֵאָה הֵם הֲרֵי אֵלּוּ נֶאֱמָנִים. קֶמַח זֶה שֶׁל לֶקֶט שִׁכְחָה וּפֵאָה הוּא אֵינָם נֶאֱמָנִין. וְאֵין צָרִיךְ לוֹמַר שֶׁאֵין נֶאֱמָנִין עַל הַפַּת לוֹמַר מִמַּתְּנוֹת עֲנִיִּים הוּא אֶלָּא מִתְעַשְּׂרִין דְּמַאי:","נֶאֱמָנִין עַל הַשְּׂעוֹרָה שֶׁל אֹרֶז וְאֵין נֶאֱמָנִין עָלָיו בֵּין חַי בֵּין מְבֻשָּׁל. נֶאֱמָנִין עַל הַפּוֹל וְאֵין נֶאֱמָנִין עַל הַגְּרִיסִין בֵּין חַיִּין בֵּין מְבֻשָּׁלִין. נֶאֱמָנִין עַל הַשֶּׁמֶן לוֹמַר שֶׁל מַעֲשַׂר עָנִי הוּא וְאֵין נֶאֱמָנִין לוֹמַר שֶׁל זֵיתֵי נִקּוּף הֵם. נֶאֱמָנִין עַל הַיָּרָק חַי וְלֹא מְבֻשָּׁל אֶלָּא אִם כֵּן הָיָה דָּבָר מֻעָט. שֶׁכֵּן דֶּרֶךְ בַּעֲלֵי בָּתִּים לִתֵּן מְעַט יָרָק מְבֻשָּׁל מִקְּדֵרָתוֹ לְעָנִי. וּמִתּוֹךְ שֶׁיָּכוֹל לוֹמַר הַבַּעַל הַבַּיִת נְתָנוֹ לִי יָכוֹל לוֹמַר אֲנִי בִּשַּׁלְתִּיו מִמַּתְּנוֹתַי:","וְכֵן בֶּן לֵוִי שֶׁאָמַר פֵּרוֹת אֵלּוּ מִמַּעֲשֵׂר רִאשׁוֹן שֶׁנִּטְּלָה תְּרוּמָתוֹ הֵם הֲרֵי זֶה נֶאֱמָן לְעוֹלָם עַל תְּרוּמַת מַעֲשֵׂר כְּשֵׁם שֶׁיִּשְׂרָאֵל נֶאֱמָן עַל תְּרוּמָה גְּדוֹלָה. אֲבָל אֵינוֹ נֶאֱמָן עָלָיו לְפָטְרוֹ מִמַּעֲשֵׂר שֵׁנִי:","אֵין כָּל הַדְּבָרִים הָאֵלּוּ אֲמוּרִין אֶלָּא בְּעַם הָאָרֶץ שֶׁאֵינוֹ לֹא חָשׁוּד וְלֹא נֶאֱמָן. אֲבָל מִי שֶׁהוּא חָשׁוּד לִמְכֹּר תְּרוּמָה לְשֵׁם חֻלִּין אָסוּר לִקַּח מִמֶּנּוּ כְּלָל דָּבָר שֶׁיֵּשׁ בּוֹ זִקַּת תְּרוּמָה וּמַעֲשֵׂר אֲפִלּוּ קִרְבֵי דָּגִים מִפְּנֵי שֶׁנּוֹתְנִין בָּהֶם שֶׁמֶן. וְאֵין אָסוּר אֶלָּא כָּל שֶׁלְּפָנָיו. אֲבָל אֲצָרוֹ מֻתָּר לִקַּח מִמֶּנּוּ מִפְּנֵי שֶׁהוּא מִתְיָרֵא לְעָרֵב תְּרוּמָה בְּאוֹצָרוֹ שֶׁמָּא יִוָּדַע הַדָּבָר וְיַפְסִיד הַכּל. וְכֵן הֶחָשׁוּד לְמַעֲשֵׂר שֵׁנִי לְמָכְרָן לְשֵׁם חֻלִּין אֵין לוֹקְחִין מִמֶּנּוּ דָּבָר שֶׁיֵּשׁ עָלָיו זִקַּת מַעֲשֵׂר. וְכָל זֶה קְנָס מִדִּבְרֵיהֶם:","חָשׁוּד שֶׁהֵעִיד עַל שֶׁל אֲחֵרִים נֶאֱמָן. חֲזָקָה אֵין אָדָם חוֹטֵא וְלֹא לוֹ. וְאֵין צָרִיךְ לוֹמַר עַם הָאָרֶץ. לְפִיכָךְ עַם הָאָרֶץ שֶׁאָמַר זֶה טֶבֶל וְזֶה תְּרוּמָה זֶה וַדַּאי וְזֶה דְּמַאי אֲפִלּוּ בְּשֶׁלּוֹ נֶאֱמָן. אָמַר אֵלּוּ פֵּרוֹת מְתֻקָּנִין בְּשֶׁל אֲחֵרִים נֶאֱמָן וְהוּא שֶׁלֹּא יֵרָאוּ כְּעוֹשֶׂה קְנוּנְיָא כְּמוֹ שֶׁבֵּאַרְנוּ:","הַמּוֹכֵר פֵּרוֹת לַחֲבֵרוֹ וְאַחַר שֶׁיָּצְאוּ מִתַּחַת יָדוֹ אָמַר לַלּוֹקֵחַ פֵּרוֹת שֶׁמָּכַרְתִּי לְךָ טְבָלִים הֵן. הַבָּשָׂר בְּשַׂר בְּכוֹר הָיָה. הַיַּיִן יֵין נֶסֶךְ. שׁוּרַת הַדִּין שֶׁאֵינוֹ נֶאֱמָן אֲפִלּוּ הָיָה הַמּוֹכֵר חָבֵר וְהַזָּרִיז מַחֲמִיר עַל עַצְמוֹ. וְאִם הֶאֱמִינוֹ הֲרֵי זֶה מְשֻׁבָּח אֲפִלּוּ הָיָה הַמּוֹכֵר עַם הָאָרֶץ:"],"Mishneh Torah, Torah Study 2":["מוֹשִׁיבִין מְלַמְּדֵי תִּינוֹקוֹת בְּכָל מְדִינָה וּמְדִינָה וּבְכָל פֶּלֶךְ וּפֶלֶךְ וּבְכָל עִיר וָעִיר. וְכָל עִיר שֶׁאֵין בָּהּ תִּינוֹקוֹת שֶׁל בֵּית רַבָּן מַחְרִימִין אֶת אַנְשֵׁי הָעִיר עַד שֶׁמּוֹשִׁיבִין מְלַמְּדֵי תִּינוֹקוֹת. וְאִם לֹא הוֹשִׁיבוּ מַחְרִימִין אֶת הָעִיר. שֶׁאֵין הָעוֹלָם מִתְקַיֵּם אֶלָּא בְּהֶבֶל פִּיהֶם שֶׁל תִּינוֹקוֹת שֶׁל בֵּית רַבָּן:","מַכְנִיסִין אֶת הַתִּינוֹקוֹת לְהִתְלַמֵּד כְּבֶן שֵׁשׁ כְּבֶן שֶׁבַע לְפִי כֹּחַ הַבֵּן וּבִנְיַן גּוּפוֹ. וּפָחוֹת מִבֶּן שֵׁשׁ אֵין מַכְנִיסִים אוֹתוֹ. וּמַכֶּה אוֹתָן הַמְלַמֵּד לְהַטִּיל עֲלֵיהֶם אֵימָה. וְאֵינוֹ מַכֶּה אוֹתָם מַכַּת אוֹיֵב מַכַּת אַכְזָרִי. לְפִיכָךְ לֹא יַכֶּה אוֹתָם בְּשׁוֹטִים וְלֹא בְּמַקְלוֹת אֶלָּא בִּרְצוּעָה קְטַנָּה. וְיוֹשֵׁב וּמְלַמְּדָן כָּל הַיּוֹם כֻּלּוֹ וּמִקְצָת מִן הַלַּיְלָה כְּדֵי לְחַנְּכָן לִלְמֹד בַּיּוֹם וּבַלַּיְלָה. וְלֹא יִבָּטְלוּ הַתִּינוֹקוֹת כְּלָל חוּץ מֵעַרְבֵי שַׁבָּתוֹת וְיָמִים טוֹבִים בְּסוֹף הַיָּמִים וּבְיָמִים טוֹבִים. אֲבָל בְּשַׁבָּת אֵין קוֹרִין בַּתְּחִלָּה אֲבָל שׁוֹנִין בָּרִאשׁוֹן. וְאֵין מְבַטְּלִין הַתִּינוֹקוֹת וַאֲפִלּוּ לְבִנְיַן בֵּית הַמִּקְדָּשׁ:","מְלַמֵּד הַתִּינוֹקוֹת שֶׁהוּא מֵנִיחַ הַתִּינוֹקוֹת וְיוֹצֵא אוֹ שֶׁהוּא עוֹשֶׂה מְלָאכָה אַחֶרֶת עִמָּהֶן אוֹ שֶׁהוּא מִתְרַשֵּׁל בְּלִמּוּדָן הֲרֵי זֶה בִּכְלַל (ירמיה מח י) \"אָרוּר עוֹשֶׂה מְלֶאכֶת ה' רְמִיָּה\". לְפִיכָךְ אֵין רָאוּי לְהוֹשִׁיב מְלַמֵּד אֶלָּא בַּעַל יִרְאָה מָהִיר לִקְרוֹת וּלְדַקְדֵּק:","וּמִי שֶׁאֵין לוֹ אִשָּׁה לֹא יְלַמֵּד תִּינוֹקוֹת מִפְּנֵי אִמּוֹתֵיהֶם הַבָּאוֹת אֵצֶל בְּנֵיהֶם. וְכָל אִשָּׁה לֹא תְּלַמֵּד תִּינוֹקוֹת מִפְּנֵי אֲבוֹתֵיהֶם שֶׁהֵם בָּאִים אֵצֶל הַבָּנִים:","עֶשְׂרִים וַחֲמִשָּׁה תִּינוֹקוֹת לְמֵדִים אֵצֶל מְלַמֵּד אֶחָד. הָיוּ יוֹתֵר עַל עֶשְׂרִים וַחֲמִשָּׁה עַד אַרְבָּעִים מוֹשִׁיבִין עִמּוֹ אַחֵר לְסַיְּעוֹ בְּלִמּוּדָם. הָיוּ יוֹתֵר עַל אַרְבָּעִים מַעֲמִידִין לָהֶם שְׁנֵי מְלַמְּדֵי תִּינוֹקוֹת:","מוֹלִיכִין אֶת הַקָּטָן מִמְּלַמֵּד לִמְלַמֵּד אַחֵר שֶׁהוּא מָהִיר מִמֶּנּוּ בֵּין בְּמִקְרָא בֵּין בְּדִקְדּוּק. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיוּ שְׁנֵיהֶם בְּעִיר אַחַת וְלֹא הָיָה הַנָּהָר מַפְסִיק בֵּינֵיהֶם. אֲבָל מֵעִיר לְעִיר אוֹ מִצַּד הַנָּהָר לְצִדּוֹ אֲפִלּוּ בְּאוֹתָהּ הָעִיר אֵין מוֹלִיכִין אֶת הַקָּטָן אֶלָּא אִם כֵּן הָיָה בִּנְיָן בָּרִיא עַל גַּבֵּי הַנָּהָר בִּנְיָן שֶׁאֵינוֹ רָאוּי לִפּל בִּמְהֵרָה:","אֶחָד מִבְּנֵי מָבוֹי שֶׁבִּקֵּשׁ לְהֵעָשׂוֹת מְלַמֵּד, אֲפִלּוּ אֶחָד מִבְּנֵי הֶחָצֵר, אֵין יְכוֹלִין שְׁכֵנָיו לִמְחוֹת בְּיָדוֹ. וְכֵן מְלַמֵּד תִּינוֹקוֹת שֶׁבָּא חֲבֵרוֹ וּפָתַח בַּיִת לְלַמֵּד תִּינוֹקוֹת בְּצִדּוֹ כְּדֵי שֶׁיָּבוֹאוּ תִּינוֹקוֹת אֲחֵרִים לוֹ אוֹ כְּדֵי שֶׁיָּבוֹאוּ מִתִּינוֹקוֹת שֶׁל זֶה אֵצֶל זֶה, אֵינוֹ יָכוֹל לִמְחוֹת בְּיָדוֹ, שֶׁנֶּאֱמַר (ישעיה מב כא) \"ה' חָפֵץ לְמַעַן צִדְקוֹ יַגְדִּיל תּוֹרָה וְיַאְדִּיר\":"],"Mishneh Torah, Transmission of the Oral Law 15":["וְלָמָּה עָשָׂה רַבֵּנוּ הַקָּדוֹשׁ כָּךְ, וְלֹא הִנִּיחַ הַדָּבָר כְּמוֹת שֶׁהָיָה – לְפִי שֶׁרָאָה שֶׁהַתַּלְמִידִים מִתְמַעֲטִים וְהוֹלְכִים, וְהַצָּרוֹת מִתְחַדְּשׁוֹת וּבָאוֹת, וּמַמְלֶכֶת הָרִשְׁעָה פּוֹשֶׁטֶת בָּעוֹלָם וּמִתְגַּבֶּרֶת, וְיִשְׂרָאֵל מִתְגַּלְגְּלִים וְהוֹלְכִים לַקְּצָווֹת: חִבַּר חִבּוּר אֶחָד לִהְיוֹת בְּיַד כֻּלָּם, כְּדֵי שֶׁיִּלְמְדוּהוּ בִּמְהֵרָה וְלֹא יִשָּׁכַח; וְיָשַׁב כָּל יָמָיו הוּא וּבֵית דִּינוֹ, וְלִמַּד הַמִּשְׁנָה בָּרַבִּים."],"Mishneh Torah, Transmission of the Oral Law 26":["וְכֵן יִתְבָּאַר מֵהֶם הַמִּנְהָגוֹת וְהַתַּקָּנוֹת שֶׁהִתְקִינוּ אוֹ שֶׁנָּהֲגוּ בְּכָל דּוֹר וָדוֹר, כְּמוֹ שֶׁרָאוּ בֵּית דִּין שֶׁלְּאוֹתוֹ הַדּוֹר, לְפִי שֶׁאָסוּר לָסוּר מֵהֶם, שֶׁנֶּאֱמָר \"לֹא תָסוּר, מִכָּל הַדָּבָר אֲשֶׁר־יַגִּידוּ לְךָ – יָמִין וּשְׂמֹאל\" (ראה דברים יז, יא)."],"Mishneh Torah, Transmission of the Oral Law 37":["וּשְׁאֵלוֹת רַבּוֹת שׁוֹאֲלִין אַנְשֵׁי כָּל עִיר וְעִיר לְכָל גָּאוֹן שֶׁיִּהְיֶה בִּימֵיהֶם לְפָרַשׁ לָהֶם דְּבָרִים קָשִׁים שֶׁבַּתַּלְמוּד, וְהֶם מְשִׁיבִים לָהֶם כְּפִי חָכְמָתָם; וְאוֹתָן הַשּׁוֹאֲלִין מְקַבְּצִין הַתְּשׁוּבוֹת, וְעוֹשִׂין מֵהֶן סְפָרִים לְהָבִין מֵהֶם."],"Mishneh Torah, Transmission of the Oral Law 7":["בֵּית דִּינוֹ שֶׁלְּעֶזְרָא, הֶם הַנִּקְרָאִין אַנְשֵׁי כְּנֶסֶת הַגְּדוֹלָה. וְהֶם חַגַּי זְכַרְיָה וּמַלְאָכִי, וְדָנִיֵּאל חֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה, וּנְחֶמְיָה בֶּן חֲכַלְיָה, וּמָרְדֳּכַי, וּזְרֻבָּבֶל; וְהַרְבֵּה חֲכָמִים עִמָּהֶם, תַּשְׁלוּם מֵאָה וְעֶשְׂרִים זְקֵנִים. הָאַחֲרוֹן מֵהֶם הוּא שִׁמְעוֹן הַצַּדִּיק, וְהוּא הָיָה מִכְּלַל הַמֵּאָה וְעֶשְׂרִים, וְקִבַּל תּוֹרָה שֶׁבְּעַל פֶּה מִכֻּלָּן; וְהוּא הָיָה כּוֹהֵן גָּדוֹל, אַחַר עֶזְרָא."],"Mishneh Torah, Vessels 10":["מַסְמְרוֹת שֶׁמַּחֲזִיקִין בָּהֶן הַתִּקְרָה הָעֲשׂוּיִין לִתְקֹעַ אוֹתוֹ בְּעֵצִים אֵינָן מְקַבְּלִין טֻמְאָה. וְכֵן הַמַּסְמְרוֹת שֶׁתּוֹקְעִין אוֹתָן בַּכְּתָלִים לִתְלוֹת בָּהֶן. וְאִם הִתְקִינוֹ לִהְיוֹת כְּלִי בִּפְנֵי עַצְמוֹ מְקַבֵּל טֻמְאָה. כֵּיצַד. מַסְמֵר שֶׁהִתְקִינוֹ לִהְיוֹת פּוֹתֵחַ וְנוֹעֵל בָּהּ אוֹ לְהוֹצִיא אֶת הַפְּתִילָה אוֹ שֶׁנְּתָנוֹ בְּרֵחַיִם שֶׁל יָד אוֹ שֶׁל חֲמוֹר הֲרֵי זֶה מְקַבֵּל טֻמְאָה. הִתְקִינוֹ לִפְתֹּחַ בּוֹ אֶת הֶחָבִית טָהוֹר עַד שֶׁיִּצְרְפֶנּוּ:","מַסְמֵר הֶעָשׂוּי כְּסִימָן לִשְׁמִירַת הַפֶּתַח אֵינוֹ מְקַבֵּל טֻמְאָה. וְכֵן מַסְמֵר שֶׁל שֻׁלְחָנִי שֶׁתּוֹלֶה בּוֹ הַמֹּאזְנַיִם וְהַכִּיס טָהוֹר. וְכֵן תְּלוֹיֵי הַמִּגְרָדוֹת טְהוֹרוֹת. אַף עַל פִּי שֶׁמַּסְמְרִין אֵלּוּ מְשֻׁנִּין בְּצוּרָתָן מִשְּׁאָר מַסְמְרוֹת הַתְּקִיעָה:","מַסְמֵר הַגָּרָע וְהוּא הַכְּלִי שֶׁמַּקִּיזִין מְקַבֵּל טֻמְאָה. וּמַסְמֵר שֶׁל אֶבֶן הַשָּׁעוֹת טָהוֹר:","מַסְמֵר הַגַּרְדִּי וְהוּא הַמַּסְמֵר הָאָרֹךְ כְּעֵין שִׁפּוּד שֶׁמַּכְנִיס בּוֹ הָאוֹרֵג שְׁפוֹפֶרֶת הַקָּנֶה אוֹ הָעֵץ וְלוֹפֵף עָלֶיהָ חוּטִים מְקַבֵּל טֻמְאָה:","אֵלּוּ כְּלֵי מַתָּכוֹת הַמִּתְטַמְּאוֹת בָּעֲגָלָה. הָעל שֶׁל מַתֶּכֶת. וְהַקַּטְרָב. וְהַכְּנָפַיִם הַמְקַבְּלוֹת אֶת הָרְצוּעוֹת. וּבַרְזֶל שֶׁתַּחַת צַוְּארֵי הַבְּהֵמָה. וְהַסּוֹמֵךְ. וְהַמַּחְגֵּר. וְהַתַּמְחֻיּוֹת. וְהַעִנְבּוֹל. וְהַצְּנִירָה. וּמַסְמֵר הַמְחַבֵּר אֶת כֻּלָּם. וְאֵלּוּ טְהוֹרִים בָּעֲגָלָה. הָעל שֶׁל עֵץ הַמְצֻפֶּה. וּכְנָפַיִם הָעֲשׂוּיִין לְנוֹי. וְהַשְּׁפוֹפָרוֹת הַמַּשְׁמִיעוֹת אֶת הַקּוֹל. וְהָאֲבָר שֶׁבְּצַד צַוְּארֵי בְּהֵמָה. וְהַסּוֹבֵב שֶׁל גַּלְגַּל. וְהַטַּסִּין וְהַצִּפּוּיִין. וּשְׁאָר כָּל הַמַּסְמְרוֹת שֶׁבָּהּ טְהוֹרִין:","עַקְרָב בֵּית הַבַּד מְקַבֵּל טֻמְאָה. אָרוֹן שֶׁל גָּרוֹסוֹת אַף עַל פִּי שֶׁהוּא טָהוֹר אִם הָיְתָה תַּחְתָּיו עֲגָלָה שֶׁל מַתֶּכֶת הֲרֵי זוֹ מְקַבֶּלֶת טֻמְאָה:","רֵחַיִם שֶׁל פִּלְפְּלִין מְקַבֶּלֶת טֻמְאָה מִשּׁוּם שְׁלֹשָׁה כֵּלִים מִשּׁוּם כְּלִי מַתָּכוֹת וּמִשּׁוּם כְּלִי קִבּוּל וּמִשּׁוּם כְּבָרָה:","הַדֶּלֶת שֶׁל מַתֶּכֶת שֶׁבְּמִגְדָּל שֶׁל בַּעֲלֵי בָּתִּים אֵינָהּ מְקַבֶּלֶת טֻמְאָה. וְשֶׁל רוֹפְאִים מְקַבֶּלֶת טֻמְאָה מִפְּנֵי שֶׁמַּנִּיחִים בָּהּ אֶת הָאִסְפְּלָנִית וְתוֹלֶה בָּהּ אֶת הַמִּסְפָּרַיִם:","טַסִּין שֶׁל מַתֶּכֶת שֶׁמְּנַעֲרִין בָּהֶן אֶת הַקְּדֵרָה מְקַבְּלִין טֻמְאָה. וְהַקְּבוּעִין בַּכִּירָה טְהוֹרִין:","הַמֶּלְקָחַיִם שֶׁמְּמָעֵךְ בָּהֶן אֶת הַפְּתִילָה מְקַבְּלִין טֻמְאָה. וְהַצִּנּוֹרוֹת שֶׁתּוֹפְסוֹת אֶת הָרֵחַיִם מִלְּמַעְלָה אֵינָן מְקַבְּלוֹת טֻמְאָה. מִפְּנֵי שֶׁאֵינָן עֲשׂוּיוֹת אֶלָּא לְחַזֵּק:","קְלוֹסְטְרָא שֶׁנּוֹעֲלִין בָּהּ הַדְּלָתוֹת אִם הָיְתָה שֶׁל מַתֶּכֶת מִתְטַמְּאָה. הָיְתָה שֶׁל עֵץ וּמְצֻפָּה מַתֶּכֶת טָהוֹר:","הַפִּין וְהַפּוּרְנָא טְמֵאִים:","פִּיקָה שֶׁל מַתֶּכֶת טְהוֹרָה לְפִי שֶׁהִיא מְשַׁמֶּשֶׁת אֶת הָעֵץ:","הַכּוּשׁ וְהַפִּימָא וְהַמַּקֵּל וְסִמְפּוֹנְיָא וְחָלִיל שֶׁל מַתֶּכֶת מְקַבְּלִין טֻמְאָה. הָיוּ שֶׁל עֵץ וּמְצֻפִּין מַתֶּכֶת טָהוֹר. חוּץ מִן הַסִּמְפּוֹנְיָא שֶׁאִם הָיָה בָּהּ בֵּית קִבּוּל כְּנָפַיִם אַף עַל פִּי שֶׁהִיא מְצֻפָּה טְמֵאָה:","הַחֲצוֹצֶרֶת שֶׁמְּפֻצֶּלֶת חֻלְיוֹת חֻלְיוֹת. אִם אֵין יוֹדֵעַ לְהַחְזִירָהּ אֶלָּא אֻמָּן הֲרֵי זוֹ מְקַבֶּלֶת טֻמְאָה כְּשֶׁהִיא מְחֻבֶּרֶת. וְאִם יְכוֹלִין הַכּל לְפָרְקָהּ וּלְהַחֲזִירָהּ אֵינָהּ מְקַבֶּלֶת טֻמְאָה:","הַקָּצֶה שֶׁמַּנִּיחִין הַפֶּה עָלָיו בִּשְׁעַת תְּקִיעָה מְקַבֵּל טֻמְאָה בִּפְנֵי עַצְמוֹ. וְהַקָּצֶה הָאַחֵר הָרָחָב אֵינוֹ מְקַבֵּל טֻמְאָה בִּפְנֵי עַצְמוֹ. וּבִשְׁעַת חִבּוּר הַכּל טָמֵא. כַּיּוֹצֵא בּוֹ קְנֵי מְנוֹרָה בִּפְנֵי עַצְמָן אֵינָן מְקַבְּלִין טֻמְאָה מִפְּנֵי שֶׁיֵּשׁ לָהֶן שֵׁם לְוַוי. הַפֶּרַח שֶׁלָּהּ וְהַבָּסִיס מִתְטַמְּאִין בִּפְנֵי עַצְמָן וּבִשְׁעַת חִבּוּר הַכּל טָמֵא:","קוֹרַת הַחִצִּים שֶׁהִיא הַמַּטָּרָה שֶׁיֵּשׁ בָּהּ לְשׁוֹנוֹת שֶׁל מַתֶּכֶת מְקַבֶּלֶת טֻמְאָה. וְשֶׁמַּנִּיחִים אוֹתָהּ בְּרַגְלֵי הָאֲסוּרִים טְהוֹרָה. וְהַקּוֹלָר מְקַבֵּל טֻמְאָה. מְגֵרָה שֶׁעָשָׂה שִׁנֶּיהָ לְחוֹר הַדֶּלֶת אַף עַל פִּי שֶׁמִּשְׁתַּמֵּשׁ בָּהּ אֵינָהּ מְקַבֶּלֶת טֻמְאָה. וְאִם מִשֶּׁנִּטְמֵאת עֲשָׂאָהּ לְחוֹר הַדֶּלֶת הֲרֵי זוֹ בְּטֻמְאָתָהּ עַד שֶׁיִּקְבָּעֶנָּה בְּמַסְמֵר. הֲפָכָהּ בֵּין מִלְּמַעְלָה בֵּין מִלְּמַטָּה בֵּין מִן הַצְּדָדִים טְהוֹרָה:"],"Mishneh Torah, Vessels 21":["הַחוּטִין הַיּוֹצְאִין מִן הָאָרִיג וְשֶׁבִּתְחִלַּת הַיְרִיעָה וְשֶׁבְּסוֹפָהּ וְהֵן הַנִּקְרָאִין נִימִין כַּמָּה שִׁעוּרָן. שֶׁל סָדִין וְשֶׁל סוּדָרִין וְשֶׁל צָעִיף וְשֶׁל פִּלְיוֹן שֶׁל רֹאשׁ שֵׁשׁ אֶצְבָּעוֹת. וְשֶׁל חָלוּק שֶׁהוּא קָרוּעַ מִתְּחִלָּתוֹ וְעַד סוֹפוֹ וְאַחַר שֶׁלּוֹבְשִׁין אוֹתוֹ מְקַבְּצִין אוֹתוֹ בְּלוּלָאוֹת שִׁעוּר חוּטָיו עֶשֶׂר אֶצְבָּעוֹת. הַסָּגִיס וְהָרְדִיד וְהַטַּלִּית שָׁלֹשׁ אֶצְבָּעוֹת. וְכָל הַיֶּתֶר עַל הַשִּׁעוּרִין הָאֵלּוּ הַנּוֹגֵעַ בּוֹ טָהוֹר אַף עַל פִּי שֶׁהַבֶּגֶד טָמֵא בְּמִדְרָס אוֹ בִּשְׁאָר טֻמְאוֹת. וְאֵין צָרִיךְ לוֹמַר שֶׁאִם נָגְעָה טֻמְאָה בַּיֶּתֶר שֶׁהַבֶּגֶד טָהוֹר:","נִימֵי הַכִּפָּה שֶׁל רֹאשׁ. וְהַמַּסְוֶה שֶׁמַּנִּיחִין הָעַרְבִיִּים עַל פְּנֵיהֶם. וְהַקִּלְקָלִין הַשְּׁזוּרִין מִן הַשֵּׂעָר. וְהַפֻּנְדָּא שֶׁלּוֹבֵשׁ הָאָדָם עַל בְּשָׂרוֹ. וְהַשִּׂמְלָה וְהַפַּרְגּוֹד שֶׁמַּנִּיחִין עַל הַפְּתָחִים כְּמוֹ פָּרֹכֶת. נִימֵיהֶן כָּל שֶׁהֵן:","מִשְׁקלֶת שֶׁנִּטְמֵאת הֲרֵי שְׁנֵים עָשָׂר טֶפַח מִן הַחוּט שֶׁלָּהּ חִבּוּר לָהּ. וְכָל הַנּוֹגֵעַ בְּחוּץ לִשְׁנֵים עָשָׂר טֶפַח טָהוֹר. וּמִשְׁקלֶת שֶׁל חָרָשִׁים שְׁמוֹנָה עָשָׂר טֶפַח. וְשֶׁל בַּנָּאִין חֲמִשִּׁים אַמָּה. וְהַיֶּתֶר עַל מִדּוֹת אֵלּוּ אַף עַל פִּי שֶׁהוּא רוֹצֶה בְּקִיּוּמוֹ טָהוֹר:","מִשְׁקוֹלוֹת שֶׁל סַיָּדִין וְשֶׁל צַיָּרִין אֲפִלּוּ אֲרֻכִּין כָּל שֶׁהֵן טְמֵאִין:","חוּט מֹאזְנַיִם שֶׁל זֶהָבִים. שֶׁל פֶּלֶס. וְשֶׁל שׁוֹקְלֵי אַרְגָּמָן טוֹב שֶׁאוֹחֵז הַשּׁוֹקֵל בּוֹ וְתוֹלֶה הַמֹּאזְנַיִם מִיָּדוֹ שָׁלֹשׁ אֶצְבָּעוֹת. קָנֶה שֶׁלָּהּ וְחוּטֶיהָ כָּל שֶׁהֵן. חוּטֵי מֹאזְנַיִם שֶׁל מוֹכְרֵי עֲשָׁשִׁיּוֹת שֶׁל מַתָּכוֹת וְכַיּוֹצֵא בָּהֶן שְׁלֹשָׁה טְפָחִים. קָנֶה שֶׁלָּהּ וְחוּטֶיהָ שְׁנֵים עָשָׂר טְפָחִים. חוּט מֹאזְנַיִם שֶׁל חֶנְוָנִים וְשֶׁל בַּעֲלֵי בָּתִּים טֶפַח. קְנֵה הַמֹּאזְנַיִם וְחוּטֶיהָ שִׁשָּׁה טְפָחִים. חוּט מֹאזְנַיִם שֶׁל צַמָּרִים וְשֶׁל שׁוֹקְלֵי זְכוּכִית טְפָחַיִם. קְנֵה מֹאזְנַיִם וְחוּטֶיהָ תִּשְׁעָה טְפָחִים. וְהַיֶּתֶר עַל הַשִּׁעוּרִין אֵלּוּ אֵינָן חִבּוּר:","הַחֶבֶל שֶׁמְּסָרְגִין הַמִּטּוֹת מֵאֵימָתַי הוּא חִבּוּר לַטֻּמְאָה מִשֶּׁיְּסָרֵג בּוֹ שְׁלֹשָׁה בָּתִּים. וְהַנּוֹגֵעַ בַּחֶבֶל מִן הַקֶּשֶׁר וּלְפָנִים טָמֵא מִן הַקֶּשֶׁר וְלַחוּץ עַד שָׁלֹשׁ אֶצְבָּעוֹת טָמֵא מִפְּנֵי שֶׁהֵן צְרָכָיו שֶׁל קֶשֶׁר הֲרֵי הֵן מִכְּלַל הַמִּטָּה. וְחוּץ לְשָׁלֹשׁ אֶצְבָּעוֹת טָהוֹר שֶׁאֵינוֹ לְצֹרֶךְ הַכְּלִי שֶׁאֲפִלּוּ פְּסָקוֹ אֵין הַקֶּשֶׁר נִתָּר:","חֶבֶל הַיּוֹצֵא מִן הַמִּטָּה שֶׁהִיא טְמֵאָה עַד סוֹף אַרְבָּעָה טְפָחִים הַנּוֹגֵעַ בּוֹ טָהוֹר שֶׁאֵינוֹ מִצָּרְכֵי הַמִּטָּה לְפִי שֶׁאֵינוֹ רָאוּי לִכְלוּם. מִתְּחִלַּת חֲמִשָּׁה וְעַד סוֹף עֲשָׂרָה טָמֵא מִפְּנֵי שֶׁתּוֹלִין בּוֹ אֶת הַמִּטּוֹת. מֵעֲשָׂרָה וְלַחוּץ טָהוֹר מִפְּנֵי שֶׁהוּא יֶתֶר עַל צֹרֶךְ הַמִּטָּה:","אַבְנֵט שֶׁל אָרִיג שֶׁמַּקִּיפִין אוֹתוֹ עַל הַמִּטָּה כְּדֵי לְקַבֵּץ אֵיבָרֶיהָ וְהוּא הַנִּקְרָא מִזְרָן שֶׁמִּקְצָתוֹ יוֹצְאָה מִן הַמִּטָּה עַד עֲשָׂרָה טְפָחִים הֲרֵי הוּא מִצָּרְכֵי הַמִּטָּה. יֶתֶר עַל כֵּן אֵינוֹ מִצָּרְכֵי הַמִּטָּה. וּמִזְרָן שֶׁבָּלָה אִם נִשְׁאַר מִמֶּנּוּ שִׁבְעָה טְפָחִים כְּדֵי לַעֲשׂוֹת מִמֶּנּוּ חֶבֶק לַחֲמוֹר הֲרֵי זֶה מְקַבֵּל טֻמְאָה:","מִטָּה שֶׁהָיְתָה טְמֵאָה מִדְרָס וּמִזְרָן יוֹצֵא מִמֶּנָּה עַד עֲשָׂרָה טְפָחִים הֲרֵי הוּא אַב טֻמְאָה כַּמִּטָּה עַצְמָהּ וְהַכּל מִדְרָס. מֵעֲשָׂרָה וְלַחוּץ הֲרֵי הוּא כְּמַגַּע מִדְרָס. דָּרַס הַזָּב עַל הַמִּזְרָן הַיּוֹצֵא מֵעֲשָׂרָה וּלְפָנִים הֲרֵי הַמִּטָּה כֻּלָּהּ מִדְרָס. מֵעֲשָׂרָה וְלַחוּץ טְהוֹרָה. בַּמֶּה דְּבָרִים אֲמוּרִים לְמִדְרָס. אֲבָל לִשְׁאָר טֻמְאוֹת אֲפִלּוּ מֵאָה אַמָּה כֻּלּוֹ חִבּוּר. כֵּיצַד. מִזְרָן שֶׁהוּא כָּרוּךְ עַל הַמִּטָּה וְהִכְנִיס קְצָתוֹ לְאֹהֶל הַמֵּת אוֹ שֶׁנָּגַע שֶׁרֶץ בִּקְצָתוֹ אוֹ שֶׁנָּפְלוּ מַשְׁקִין טְמֵאִין עַל מִקְצָתוֹ נִטְמֵאת הַמִּטָּה וַאֲפִלּוּ הָיָה הַקָּצֶה שֶׁנִּטְמָא יוֹצֵא מִן הַמִּטָּה מֵאָה אַמָּה:","מִטָּה הַטְּמֵאָה מִדְרָס וְכָרַךְ לָהּ מִזְרָן הַכּל טָמֵא מִדְרָס. הִפְרִישׁוֹ הַמִּטָּה מִדְרָס כְּשֶׁהָיְתָה וְהַמִּזְרָן מַגַּע מִדְרָס. הָיְתָה טְמֵאָה טֻמְאַת שִׁבְעָה וְכָרַךְ לָהּ מִזְרָן כֻּלָּהּ טְמֵאָה טֻמְאַת שִׁבְעָה. הִפְרִישׁוֹ הִיא טְמֵאָה כְּשֶׁהָיְתָה וְהַמִּזְרָן טָמֵא טֻמְאַת עֶרֶב. הָיְתָה טְמֵאָה טֻמְאַת עֶרֶב וְכָרַךְ לָהּ מִזְרָן הַכּל טָמֵא טֻמְאַת עֶרֶב. הִפְרִישׁוֹ הִיא טְמֵאָה טֻמְאַת עֶרֶב וְהַמִּזְרָן טָהוֹר:","מִטָּה שֶׁכָּרַךְ עָלֶיהָ מִזְרָן וְנָגַע בָּהֶן הַמֵּת הַכּל טָמֵא טֻמְאַת שִׁבְעָה. פֵּרְשׁוּ טָמֵא טֻמְאַת שִׁבְעָה. נָגַע בָּהּ שֶׁרֶץ וְכַיּוֹצֵא בָּהֶן טְמֵאִין טֻמְאַת עֶרֶב. פֵּרְשׁוּ טְמֵאִין טֻמְאַת עֶרֶב:","כֶּרַע שֶׁהָיְתָה טְמֵאָה מִדְרָס וְחִבְּרָהּ לְמִטָּה הַמִּטָּה כֻּלָּהּ מִדְרָס. פֵּרְשָׁה הַכֶּרַע טְמֵאָה מִדְרָס כְּשֶׁהָיְתָה וְהַמִּטָּה מַגַּע מִדְרָס. וְכֵן אִם הָיְתָה הַכֶּרַע טְמֵאָה טֻמְאַת שִׁבְעָה וְחִבְּרָהּ לְמִטָּה הַמִּטָּה כֻּלָּהּ טְמֵאָה שִׁבְעָה כְּאִלּוּ נָגַע הַמֵּת בְּכֶרַע שֶׁלָּהּ. וְאִם הִזָּה עַל הַמִּטָּה טִהֲרָה וְהַכֶּרַע בִּכְלָלָהּ. וְאִם פֵּרְשָׁה קֹדֶם הַזָּיָה הַכֶּרַע טְמֵאָה טֻמְאַת שִׁבְעָה כְּשֶׁהָיְתָה וְהַמִּטָּה טְמֵאָה טֻמְאַת עֶרֶב. הָיָה הַכֶּרַע טְמֵאָה טֻמְאַת עֶרֶב וְחִבְּרָהּ לַמִּטָּה הַכּל טָמֵא טֻמְאַת עֶרֶב. פֵּרְשָׁה הִיא טְמֵאָה טֻמְאַת עֶרֶב וְהַמִּטָּה טְהוֹרָה שֶׁאֵין הַטָּמֵא טֻמְאַת עֶרֶב מִן הַמֵּת מְטַמֵּא לֹא אָדָם וְלֹא כֵּלִים מִפְּנֵי שֶׁהוּא וָלָד כְּמוֹ שֶׁבֵּאַרְנוּ. וְכֵן הַדִּין בְּשֵׁן שֶׁל מַעְדֵּר שֶׁנִּטְמָא בְּמֵת וְאַחַר כָּךְ חִבְּרוֹ לַמַּעְדֵּר:"],"Mishneh Torah, Vessels 7":["כְּלֵי עוֹר מֵאֵימָתַי מְקַבְּלִין טֻמְאָה. הַתּוּרְמָל וְכַיּוֹצֵא בּוֹ מִשֶּׁיַּחְסֹם שִׂפְתוֹתָיו וְיִכְרֹת הַקּוֹפִין הַקְּטַנִּים הַיּוֹצְאִין עַל גַּבֵּי הָעוֹר וְיַעֲשֶׂה קִיחוֹתָיו. סְקוּרְטִיָה מִשֶּׁיַּחְסֹם וְיִכְרֹת וְיַעֲשֶׂה צִיצָתָהּ. קַטַבוּלְיָה מִשֶּׁיַּחְסֹם וְיִכְרֹת. הַכַּר וְהַכֶּסֶת שֶׁל עוֹר מִשֶּׁיַּחְסֹם שִׂפְתוֹתֵיהֶן וְיִכְרֹת הַקּוֹפִין הַיּוֹצְאִין. וְכֵן כָּל כַּיּוֹצֵא בָּהֶן. הַתְּפִלִּין מִשֶּׁיִּגְמֹר הַקְּצִיצָה אַף עַל פִּי שֶׁהוּא עָתִיד לָתֵת בָּהּ אֶת הָרְצוּעָה מְקַבֶּלֶת טֻמְאָה. עוֹר הָעֲרִיסָה שֶׁהוּא עָתִיד לַעֲשׂוֹת לוֹ טַבּוּר עַד שֶׁיַּעֲשֶׂנּוּ לוֹ. הַסַּנְדָּל מִשֶּׁיַּקְמִיעַ. הַמִּנְעָל מִשֶׁיִּגּוֹב [עַל] הָאִמּוּם. וְאִם עָתִיד לכַרְכֵּם וּלְשַׂרְטֵט עַד שֶׁיִּכַרְכֵּם וִישַׂרְטֵט:","עוֹר שֶׁאֵין עָלָיו צוּרַת כְּלִי אֵינוֹ מְקַבֵּל טֻמְאָה. לְפִיכָךְ כַּף שֶׁל עוֹר שֶׁקּוֹשְׁרִין לוֹקְטֵי קוֹצִים עַל כַּפּוֹתֵיהֶן כְּדֵי שֶׁלֹּא יַכֵּם קוֹץ אֵינוֹ מְקַבֵּל טֻמְאָה מִפְּנֵי שֶׁהוּא עוֹר פָּשׁוּט וְאֵין עָלָיו צוּרַת כְּלִי. וְכֵן הָעוֹר שֶׁמְּלַקְּטִין בּוֹ גְּלָלֵי הַבָּקָר וְעוֹר שֶׁחוֹסְמִין בּוֹ פִּי הַבְּהֵמָה וְעוֹר שֶׁמּוֹשִׁיבִין בּוֹ הַדְּבוֹרִים בְּשָׁעָה שֶׁלּוֹקְחִין הַדְּבַשׁ וְעוֹר שֶׁמְּנִיפִין בּוֹ אֶת הָרוּחַ מִפְּנֵי הַחֹם טְהוֹרִין וְאֵין מְקַבְּלִין טֻמְאָה:","כָּל בֵּית הָאֶצְבָּעוֹת שֶׁל עוֹר טְהוֹרוֹת חוּץ מִשֶּׁל קַיָיצִין מִפְּנֵי שֶׁהִיא מְקַבֶּלֶת אֶת הָאוֹג טְמֵאָה. נִקְרְעָה אִם אֵינָהּ מְקַבֶּלֶת אֶת רֹב הָאוֹג טְהוֹרָה:","הָאַבְנֵט שֶׁל עוֹרוֹת וְעוֹרוֹת שֶׁתּוֹפְרִין הַקִּטְּעִים עַל אַרְכֻּבּוֹתֵיהֶן כְּדֵי שֶׁיִּתְגַּלְגְּלוּ בָּהֶן עַל הַקַּרְקַע מְקַבְּלִין טֻמְאָה שֶׁהֲרֵי צוּרַת כְּלִי עֲלֵיהֶן. וְכֵן הָעוֹרוֹת הָעֲשׂוּיוֹת כְּעֵין טַבָּעוֹת שֶׁמַּכְנִיסִין אוֹתָן הָאֻמָּנִין בִּזְרוֹעוֹתֵיהֶן כְּדֵי לְהַגְבִּיהַּ בִּגְדֵיהֶן מֵעֲלֵיהֶן בִּשְׁעַת מְלָאכָה מִתְטַמְּאִין כִּשְׁאָר כְּלֵי עוֹר הַפְּשׁוּטִים:","עוֹר שֶׁתּוֹפְרִין מִמֶּנּוּ כִּסּוּי לְיָד וְלִזְרוֹעַ שֶׁל זוֹרְעֵי גִּנּוֹת וְשֶׁל הוֹלְכֵי דְּרָכִים וְשֶׁל עוֹשֵׂי פִּשְׁתָּן מְקַבְּלִין טֻמְאָה. וְאִם הָיָה שֶׁל צַבָּעִים וְשֶׁל נַפָּחִים אֵינוֹ מְקַבֵּל טֻמְאָה. זֶה הַכְּלָל כָּל הֶעָשׂוּי לְקַבָּלָה כְּדֵי שֶׁלֹּא יַכֵּהוּ קוֹץ וּכְדֵי שֶׁיֹּאחַז יָפֶה יָפֶה מְקַבֵּל טֻמְאָה. וְהֶעָשׂוּי מִפְּנֵי הַזֵּעָה כְּדֵי שֶׁלֹּא יִפָּסֵד הַדָּבָר שֶׁמִּתְעַסֵּק בּוֹ בְּזֵעַת יָדוֹ אֵינוֹ מְקַבֵּל טֻמְאָה:","כַּמָּה שִׁעוּר הַנֶּקֶב שֶׁיִּנָּקֵב כְּלִי הָעוֹר וְיִטְהַר. הַחֵמֶת מִשֶּׁתִּנָּקֵב כְּמוֹצִיא פְּקָעִיּוֹת שֶׁל שְׁתִי. וְאִם אֵינָהּ יְכוֹלָה לְקַבֵּל שֶׁל שְׁתִי הוֹאִיל וּמְקַבֶּלֶת שֶׁל עֵרֶב מְקַבֶּלֶת טֻמְאָה עַד שֶׁתִּנָּקֵב רֻבָּהּ:","הַתֻּרְמִיל שֶׁנִּפְחַת הַכִּיס שֶׁבְּתוֹכוֹ עֲדַיִן הַתֻּרְמִיל מְקַבֵּל טֻמְאָה וְאֵינוֹ חִבּוּר לוֹ:","הַחֵמֶת שֶׁהַבֵּצִים שֶׁלָּהּ מְקַבְּלוֹת עִמָּהּ וְנִפְחֲתוּ טְהוֹרוֹת שֶׁאֵינָן מְקַבְּלוֹת כְּדַרְכָּן:","כְּלִי עוֹר שֶׁיֵּשׁ לוֹ לוּלָאוֹת וּשְׁנָצוֹת כְּגוֹן סַנְדָּל עִמְקִי וְכִיס שֶׁל שְׁנָצוֹת אַף עַל פִּי שֶׁכְּשֶׁהֵן מֻתָּרִין אֵין עֲלֵיהֶן צוּרַת כְּלִי הֲרֵי אֵלּוּ מְקַבְּלִין טֻמְאָה כְּשֶׁהֵן מֻתָּרִין הוֹאִיל וְהַהֶדְיוֹט יָכוֹל בִּמְהֵרָה לְהַכְנִיס הַשְּׁנָצוֹת בַּלּוּלָאוֹת וְיַחְזֹר כְּלִי קִבּוּל כְּשֶׁהָיָה. וְכֵן אִם נִטְמְאוּ וְהֵסִיר הַשְּׁנָצוֹת מֵהֶן וְנִפְסְדָה צוּרָתָן הֲרֵי הֵן טְהוֹרִין אַף עַל פִּי שֶׁאֶפְשָׁר לְהַחְזִירָן שֶׁלֹּא בְּאֻמָּן:","כִּיס שֶׁל שְׁנָצוֹת שֶׁנִּטְּלוּ שְׁנָצָיו עֲדַיִן הוּא מְקַבֵּל טֻמְאָה שֶׁהֲרֵי הוּא מְקַבֵּל. נִפְשַׁט וְחָזַר עוֹר פָּשׁוּט טָהוֹר. טָלָה עָלָיו אֶת הַמַּטְלֵת מִלְּמַטָּה מְקַבֶּלֶת טֻמְאָה אַף עַל פִּי שֶׁהוּא פָּשׁוּט שֶׁהֲרֵי יֵשׁ עָלָיו צוּרַת כְּלִי:","עוֹר שֶׁכָּרַךְ בּוֹ אֶת הַקָּמֵעַ מְקַבֵּל טֻמְאָה. פְּשָׁטוֹ טָהוֹר. חָזַר וְכָרַךְ בּוֹ מְקַבֵּל טֻמְאָה. מִתְטַמֵּא וּמִתְטַהֵר אֲפִלּוּ עֶשֶׂר פְּעָמִים בְּיוֹם. וְעוֹר שֶׁכָּתַב עָלָיו אֶת הַקָּמֵעַ טָהוֹר. וְאִם כָּרַת מִמֶּנּוּ וְעָשָׂה חֻלְיָא לְתַכְשִׁיט מְקַבֵּל טֻמְאָה:","הַתְּפִלָּה שֶׁל רֹאשׁ אַרְבָּעָה כֵּלִים הִיא. הֲרֵי שֶׁנִּטְמֵאת בְּמֵת וְהִתִּיר קְצִיצָה הָרִאשׁוֹנָה וְתִקְּנָהּ הֲרֵי הִיא אַב טֻמְאָה כְּשֶׁהָיְתָה. וְכֵן אִם הִתִּיר הַשְּׁנִיָּה וְתִקְּנָהּ. וְאִם הִתִּיר אַף הַשְּׁלִישִׁית וְתִקְּנָהּ וְהִתִּיר אַף הָרְבִיעִית וְתִקְּנָהּ נַעֲשֵׂית כֻּלָּהּ רִאשׁוֹן לְטֻמְאָה. שֶׁהֲרֵי הִתִּיר כָּל אַחַת וְאַחַת וְחָזַר וְתִקְּנָם כֻּלָּם וּכְאִלּוּ זוֹ תְּפִלִּין אַחֲרוֹנוֹת שֶׁנָּגְעוּ בָּרִאשׁוֹנוֹת. חָזַר וְהִתִּיר אֶת הָרִאשׁוֹנָה פַּעַם שְׁנִיָּה וְתִקְּנָהּ הֲרֵי הִיא רִאשׁוֹן כְּשֶׁהָיְתָה. וְכֵן אִם הִתִּיר אֶת הַשְּׁנִיָּה וְאֶת הַשְּׁלִישִׁית. חָזַר וְהִתִּיר אַף הָרְבִיעִית וְתִקְּנָהּ הֲרֵי כֻּלָּהּ טְהוֹרָה שֶׁאֵין הָרִאשׁוֹן מְטַמֵּא כֵּלִים מִפְּנֵי שֶׁהוּא וָלָד כְּמוֹ שֶׁבֵּאַרְנוּ. וְכֵן סַנְדָּל שֶׁהוּא טְמֵא מִדְרָס וְנִפְסְקָה אַחַת מֵאָזְנָיו וְתִקְּנָהּ טָמֵא מִדְרָס. נִפְסְקָה שְׁנִיָּה וְתִקְּנָהּ הֲרֵי הוּא טָהוֹר מִן הַמִּדְרָס שֶׁהֲרֵי נַעֲשׂוּ לוֹ אָזְנַיִם חֲדָשׁוֹת אֲבָל טְמֵא מַגַּע מִדְרָס. לֹא הִסְפִּיק לְתַקֵּן אֶת הָרִאשׁוֹנָה עַד שֶׁנִּפְסְקָה הַשְּׁנִיָּה אוֹ שֶׁנִּפְסַק עֲקֵבוֹ אוֹ נִטַּל חָטְמוֹ אוֹ נֶחְלַק לִשְׁנַיִם טָהוֹר:","מִנְעָל שֶׁנִּפְחַת אִם אֵינוֹ מְקַבֵּל רֹב הָרֶגֶל טָהוֹר:","תְּפִלָּה שֶׁנִּטְמֵאת מֵאֵימָתַי טָהֳרָתָהּ. שֶׁל יָד מִשֶּׁיַּתִּיר אוֹתָהּ מִשָּׁלֹשׁ רוּחוֹת. וְשֶׁל רֹאשׁ מִשֶּׁיַּתִּיר מִשָּׁלֹשׁ רוּחוֹת וּבֵין קְצִיצָה לַחֲבֵרְתָהּ:","הַכַּדּוּר וְהָאִמּוּם וְהַקָּמֵע וְהַתְּפִלִּין שֶׁנִּקְרְעוּ אַחַר שֶׁנִּטְמְאוּ הַנּוֹגֵעַ בָּהֶן טָמֵא וּבְמַה שֶּׁבְּתוֹכָן טָהוֹר. הָאִכּוּף שֶׁנִּקְרַע הַנּוֹגֵעַ בְּמַה שֶּׁבְּתוֹכוֹ טָמֵא מִפְּנֵי שֶׁהַתֶּפֶר מְחַבְּרוֹ וְנַעֲשָׂה כֻּלּוֹ כְּגוּף אֶחָד:"],"Mishneh Torah, Vessels of the Sanctuary and Those Who Serve Therein 9":["כֵּיצַד מַעֲשֵׂה הַצִּיץ. עוֹשֶׂה טַס שֶׁל זָהָב רֹחַב שְׁתֵּי אֶצְבָּעוֹת וּמַקִּיף מֵאֹזֶן לְאֹזֶן וְכוֹתֵב עָלָיו שֵׁנִי שִׁיטִין קֹדֶשׁ לַה' קֹדֶשׁ מִלְּמַטָּה לַה' מִלְמַעְלָה. וְאִם כְּתָבוֹ בְּשִׁיטָה אַחַת כָּשֵׁר. וּפְעָמִים כְּתָבוּהוּ בְּשִׁיטָה אַחַת:","וְהָאוֹתִיּוֹת בּוֹלְטוֹת בְּפָנָיו. [כֵּיצַד]. חוֹפֵר אֶת הָאוֹתִיּוֹת מֵאַחֲרָיו וְהוּא מְדֻבָּק עַל הַשַּׁעֲוָה עַד שֶׁבּוֹלֵט. וְהוּא נָקוּב בִּשְׁתֵּי קְצוֹתָיו. וּפְתִיל תְּכֵלֶת לְמַטָּה מִמֶּנּוּ נִכְנָס מִנֶּקֶב לְנֶקֶב כְּדֵי שֶׁיִּהְיֶה נִקְשָׁר בִּפְתִיל כְּנֶגֶד הָעֹרֶף:","הַמְּעִיל כֻּלּוֹ תְּכֵלֶת. וְחוּטָיו כְּפוּלִין שְׁנֵים עָשָׂר וּפִיו אָרוּג בִּתְחִלַּת אֲרִיגָתוֹ. וְאֵין לוֹ בֵּית יָד אֶלָּא נֶחְלָק לִשְׁתֵּי כְּנָפַיִם מִסּוֹף הַגָּרוֹן עַד לְמַטָּה כְּדֶרֶךְ כָּל הַמְּעִילִים וְאֵינוֹ מְחֻבָּר אֶלָּא כְּנֶגֶד כָּל הַגָּרוֹן בִּלְבַד. וְהַקּוֹרֵעַ פִּי הַמְּעִיל לוֹקֶה שֶׁנֶּאֱמַר (שמות כח לב) (שמות לט כג) \"לֹא יִקָּרֵעַ\". וְהוּא הַדִּין לְכָל בִּגְדֵי כְּהֻנָּה שֶׁהַקּוֹרְעָן דֶּרֶךְ הַשְׁחָתָה לוֹקֶה:","וּמֵבִיא תְּכֵלֶת וְאַרְגָּמָן וְתוֹלַעַת שָׁנִי כָּל מִין מִשְּׁלָשְׁתָּן שָׁזוּר שְׁמוֹנָה לְפִי שֶׁנֶּאֱמַר בְּשׁוּלָיו (שמות לט כד) \"מָשְׁזָר\". נִמְצְאוּ חוּטֵי הַשּׁוּלַיִם אַרְבָּעָה וְעֶשְׂרִים. וְעוֹשֶׂה אוֹתָן כְּמִין רִמּוֹנִים שֶׁלֹּא פָּתְחוּ פִּיהֶן וְתוֹלֶה אוֹתָן בַּמְּעִיל. וּמֵבִיא שְׁנַיִם וְשִׁבְעִים זוּגִים וּבָהֶם שְׁנַיִם וְשִׁבְעִים עִנְבּוֹלִים הַכּל זָהָב וְתוֹלֶה בּוֹ שִׁשָּׁה וּשְׁלֹשִׁים בְּשׁוּלֵי כָּנָף זֶה וְשִׁשָּׁה וּשְׁלֹשִׁים בְּשׁוּלֵי כָּנָף זֶה. וְהַזּוּג עִם הָעִנְבּוֹל הַתָּלוּי בֵּין שְׁנֵיהֶם כְּאֶחָד נִקְרָא פַּעֲמוֹן עַד שֶׁיִּהְיוּ שׁוּלָיו מִשְּׁנֵי צְדָדָיו (שמות לט כו) \"פַּעֲמוֹן וְרִמּוֹן פַּעֲמוֹן וְרִמּוֹן\":","הַזָּהָב שֶׁבַּאֲרִיגַת הָאֵפוֹד וְהַחשֶׁן הָאָמוּר בַּתּוֹרָה כָּכָה הוּא מַעֲשֵׂהוּ. לוֹקֵחַ חוּט אֶחָד זָהָב טָהוֹר וְנוֹתְנוֹ עִם שִׁשָּׁה חוּטִין שֶׁל תְּכֵלֶת וְכוֹפֵל הַשִּׁבְעָה חוּטִין כְּאַחַת. וְכֵן הוּא עוֹשֶׂה חוּט זָהָב עִם שִׁשָּׁה שֶׁל אַרְגָּמָן וְחוּט אֶחָד עִם שִׁשָּׁה שֶׁל תּוֹלַעַת שָׁנִי. וְחוּט אֶחָד עִם שִׁשָּׁה שֶׁל פִּשְׁתִּים. נִמְצְאוּ אַרְבָּעָה חוּטֵי זָהָב וְנִמְצְאוּ כָּל הַחוּטִים שְׁמוֹנָה וְעֶשְׂרִים שֶׁנֶּאֱמַר (שמות לט ג) \"וַיְרַקְּעוּ אֶת פַּחֵי הַזָּהָב\" וְגוֹמֵר (שמות לט ג) \"לַעֲשׂוֹת בְּתוֹךְ הַתְּכֵלֶת וּבְתוֹךְ הָאַרְגָּמָן וּבְתוֹךְ תּוֹלַעַת הַשָּׁנִי וּבְתוֹךְ הַשֵּׁשׁ\" מְלַמֵּד שֶׁחוּט הַזָּהָב כָּפוּל בְּתוֹכָן:","כֵּיצַד מַעֲשֵׂה הַחשֶׁן. אוֹרֵג בֶּגֶד מַעֲשֵׂה חשֵׁב מִן הַזָּהָב וְהַתְּכֵלֶת וְהָאַרְגָּמָן וְתוֹלַעַת הַשָּׁנִי וְהַשֵּׁשׁ עַל שְׁמֹנָה וְעֶשְׂרִים חוּטִין כְּמוֹ שֶׁבֵּאַרְנוּ אָרְכּוֹ אַמָּה וְרָחְבּוֹ זֶרֶת וְכוֹפְלוֹ לִשְׁנַיִם. נִמְצָא זֶרֶת עַל זֶרֶת מְרֻבָּע. וְקוֹבֵעַ בּוֹ אַרְבָּעָה טוּרִים שֶׁל אֶבֶן הַמְפֹרָשִׁים בַּתּוֹרָה כָּל אֶבֶן מֵהֶן מְרֻבָּע וּמְשֻׁקָּע בְּבַיִת שֶׁל זָהָב שֶׁמַּקִּיפוֹ מִלְּמַטָּה וּמֵאַרְבַּע רוּחוֹתָיו:","וּמְפַתֵּחַ עַל הָאֲבָנִים שְׁמוֹת הַשְּׁבָטִים כְּתוֹלְדוֹתָם וְנִמְצָא כּוֹתֵב עַל הָאֹדֶם רְאוּבֵן וְעַל יָשְׁפֵה בִּנְיָמִין. וְכוֹתֵב בַּתְּחִלָּה לְמַעְלָה מֵרְאוּבֵן אַבְרָהָם יִצְחָק וְיַעֲקֹב וְכוֹתֵב לְמַטָּה מִבִּנְיָמִין שִׁבְטֵי יָהּ כְּדֵי שֶׁיִּהְיוּ כָּל הָאוֹתִיּוֹת מְצוּיוֹת שָׁם:","וְעוֹשֶׂה עַל אַרְבַּע זָוִיּוֹת שֶׁל חשֶׁן אַרְבַּע טַבְּעוֹת זָהָב. וְנוֹתֵן בִּשְׁתֵּי הַטַּבָּעוֹת שֶׁל מַעְלָה שֶׁהַחשֶׁן נִתְלֶה בָּהֶן שְׁתֵּי עֲבוֹתוֹת הַזָּהָב. וְהֵם הַנִּקְרָאִים שַׁרְשְׁרוֹת. וְנוֹתֵן בִּשְׁתֵּי טַבָּעוֹת שֶׁל מַטָּה שֶׁהֵן כְּנֶגֶד הַדָּדִים שְׁנֵי פְּתִילֵי תְּכֵלֶת:","הָאֵפוֹד רָחְבּוֹ כְּרֹחַב גַּבּוֹ שֶׁל אָדָם מִכָּתֵף לְכָתֵף. וְאָרְכּוֹ מִכְּנֶגֶד אַצִּילֵי הַיָּדַיִם מֵאֲחוֹרָיו עַד הָרַגְלַיִם. וְיֵשׁ לוֹ כְּמוֹ שְׁתֵּי יָדוֹת יוֹצְאוֹת מִמֶּנּוּ בָּאָרִיג לְכָאן וּלְכָאן שֶׁחוֹגְרִין אוֹתוֹ בָּהֶם וְהֵם הַנִּקְרָאִין חֵשֶׁב הָאֵפוֹד. וְהַכּל אָרוּג זָהָב תְּכֵלֶת וְאַרְגָּמָן וְתוֹלַעַת שָׁנִי וְשֵׁשׁ עַל שְׁמוֹנָה וְעֶשְׂרִים חוּטִין כְּמַעֲשֵׂה הַחשֶׁן. וְתוֹפֵר עָלָיו שְׁתֵּי כְּתֵפוֹת כְּדֵי שֶׁיִּהְיוּ עַל כִּתְפוֹת הַכֹּהֵן. וְקוֹבֵעַ עַל כָּל כָּתֵף וְכָתֵף אֶבֶן שֹׁהַם מְרֻבָּע מֻשְׁקָע בְּבַיִת שֶׁל זָהָב. וּמְפַתֵּחַ עַל שְׁתֵּי הָאֲבָנִים שְׁמוֹת הַשְּׁבָטִים. שִׁשָּׁה עַל אֶבֶן זוֹ וְשִׁשָּׁה עַל אֶבֶן זוֹ כְּתוֹלְדוֹתָם. וְכוֹתְבִין שֵׁם יוֹסֵף יְהוֹסֵף. וְנִמְצְאוּ כ\"ה אוֹת בְּאֶבֶן זוֹ וְכ\"ה אוֹת בְּאֶבֶן זוֹ. וְכָךְ הָיוּ כְּתוּבִין: וְהָאֶבֶן שֶׁכָּתוּב בָּהּ רְאוּבֵן עַל כְּתֵפוֹ הַיְמָנִית. וְהָאֶבֶן שֶׁכָּתוּב בָּהּ שִׁמְעוֹן עַל כְּתֵפוֹ הַשְּׂמָאלִית. וְעוֹשֶׂה בְּכָל כָּתֵף שְׁתֵּי טַבָּעוֹת אַחַת מִלְּמַעְלָה בְּרֹאשׁ הַכָּתֵף וְאַחַת מִלְּמַטָּה לַכָּתֵף לְמַעְלָה מִן הַחֵשֶׁב. וְנוֹתֵן שְׁתֵּי עֲבוֹתוֹת זָהָב בִּשְׁתֵּי טַבָּעוֹת שֶׁלְּמַעְלָה וְהֵם הַנִּקְרָאִים שַׁרְשְׁרוֹת:","וְאַחַר כָּךְ מַכְנִיס קְצוֹת הָעֲבוֹתוֹת שֶׁל חשֶׁן בַּטַּבָּעוֹת שֶׁל מַעְלָה בְּכִתְפוֹת הָאֵפוֹד. וּמַכְנִיס שְׁנֵי פְּתִילֵי הַתְּכֵלֶת שֶׁבְּשׁוּלֵי הַחשֶׁן בִּשְׁתֵּי הַטַּבָּעוֹת שֶׁל מַעְלָה מֵחֵשֶׁב הָאֵפוֹד. וּמוֹרִידִין אֶת הַשַּׁרְשְׁרוֹת שֶׁבְּטַבְּעוֹת כִּתְפוֹת הָאֵפוֹד עַד טַבְּעוֹת הַחשֶׁן הָעֶלְיוֹנוֹת כְּדֵי שֶׁיִּדָּבְקוּ זֶה בָּזֶה (שמות כח כח) (שמות לט כא) \"וְלֹא יִזַּח הַחשֶׁן מֵעַל הָאֵפוֹד\". וְכָל הַמֵּזִיחַ חשֶׁן מֵעַל הָאֵפוֹד וּמְפָרֵק חִבּוּרָן דֶּרֶךְ קִלְקוּל לוֹקֶה:","נִמְצָא כְּשֶׁלּוֹבֵשׁ הָאֵפוֹד עִם הַחשֶׁן יִהְיֶה הַחשֶׁן עַל לִבּוֹ בְּשָׁוֶה וְהָאֵפוֹד מֵאַחֲרָיו וְחֵשֶׁב הָאֵפוֹד קָשׁוּר עַל לִבּוֹ תַּחַת הַחשֶׁן. וּשְׁתֵּי כִּתְפוֹת הָאֵפוֹד עַל שְׁתֵּי כְּתֵפָיו. וּשְׁתֵּי עֲבוֹתוֹת זָהָב יוֹרְדוֹת מֵעַל כְּתֵפָיו מִכָּאן וּמִכָּאן מִכִּתְפוֹת הָאֵפוֹד עַד טַבְּעוֹת הַחשֶׁן. וּשְׁנֵי חוּטֵי תְּכֵלֶת מְרֻכָּסִין מִתַּחַת אַצִּילֵי יָדָיו. מִשְּׁתֵּי טַבְּעוֹת הַחשֶׁן הַתַּחְתּוֹנוֹת עַד שְׁתֵּי טַבְּעוֹת כִּתְפוֹת הָאֵפוֹד הַתַּחְתּוֹנוֹת שֶׁהֵם לְמַעְלָה מִן הַחֵשֶׁב:"],"Mishneh Torah, Vows 5":["רְאוּבֵן שֶׁאָמַר לְשִׁמְעוֹן הֲרֵינִי עָלֶיךָ חֵרֶם אוֹ הֲרֵי אַתָּה אָסוּר בַּהֲנָיָתִי נֶאֱסַר עַל שִׁמְעוֹן שֶׁיֵּהָנֶה בִּרְאוּבֵן. וְאִם עָבַר וְנֶהֱנָה אֵינוֹ לוֹקֶה שֶׁהֲרֵי לֹא אָמַר שִׁמְעוֹן כְּלוּם. וּמֻתָּר לִרְאוּבֵן לֵהָנוֹת בְּשִׁמְעוֹן שֶׁהֲרֵי לֹא אָסַר עַצְמוֹ בַּהֲנָיָתוֹ:","אָמַר לְשִׁמְעוֹן הֲרֵי אַתָּה עָלַי חֵרֶם אוֹ הֲרֵינִי אָסוּר בַּהֲנָיָתְךָ הֲרֵי נֶאֱסַר רְאוּבֵן מִלֵּהָנוֹת בְּשִׁמְעוֹן וְאִם נֶהֱנָה לוֹקֶה שֶׁהֲרֵי חִלֵּל דְּבָרוֹ וְשִׁמְעוֹן מֻתָּר בַּהֲנָיַת רְאוּבֵן. אָמַר לוֹ הֲרֵינִי עָלֶיךָ חֵרֶם וְאַתָּה עָלַי אוֹ הֲרֵינִי אָסוּר בַּהֲנָיָתְךָ וְאַתָּה אָסוּר בַּהֲנָיָתִי שְׁנֵיהֶם אֲסוּרִין זֶה בָּזֶה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","רְאוּבֵן שֶׁאָמַר לְשִׁמְעוֹן הֲרֵי פֵּרוֹת פְּלוֹנִי אֲסוּרִין עָלֶיךָ. אוֹ הֲרֵי אַתָּה אָסוּר בַּהֲנָיַת פְּלוֹנִי אֵין זֶה כְּלוּם. שֶׁאֵין אָדָם אוֹסֵר חֲבֵרוֹ בְּדָבָר שֶׁאֵינוֹ שֶׁלּוֹ אֶלָּא אִם כֵּן עָנָה שִׁמְעוֹן אָמֵן כְּמוֹ שֶׁבֵּאַרְנוּ:","הָאוֹמֵר לַחֲבֵרוֹ כִּכָּרִי זוֹ אֲסוּרָה עָלֶיךָ אַף עַל פִּי שֶׁנְּתָנָהּ לוֹ בְּמַתָּנָה הֲרֵי זוֹ אֲסוּרָה עָלָיו. מֵת וְנָפְלָה לוֹ בִּירֻשָּׁה אוֹ שֶׁנְּתָנָהּ לוֹ אַחֵר בְּמַתָּנָה הֲרֵי זוֹ מֻתֶּרֶת שֶׁלֹּא אָמַר לוֹ אֶלָּא כִּכָּרִי וַהֲרֵי אֵינָהּ עַתָּה שֶׁלּוֹ:","אָמַר לוֹ פֵּרוֹת אֵלּוּ אֲסוּרִין עָלֶיךָ וְלֹא אָמַר לוֹ פֵּרוֹתַי. אַף עַל פִּי שֶׁמְּכָרָן אוֹ שֶׁמֵּת וְנָפְלוּ לְאַחֵר הֲרֵי אֵלּוּ אֲסוּרִין עָלָיו. שֶׁהָאוֹסֵר דָּבָר שֶׁהוּא שֶׁלּוֹ עַל חֲבֵרוֹ אַף עַל פִּי שֶׁיָּצָא מֵרְשׁוּתוֹ הֲרֵי הוּא בְּאִסּוּרוֹ עוֹמֵד. אֶלָּא אִם כֵּן אָמַר נְכָסַי אוֹ בֵּיתִי אוֹ פֵּרוֹתַי וְכַיּוֹצֵא בִּלְשׁוֹנוֹת אֵלּוּ שֶׁהֲרֵי לֹא אֲסָרָן אֶלָּא כָּל זְמַן שֶׁהֵן בִּרְשׁוּתוֹ:","הָאוֹמֵר לִבְנוֹ הֲרֵי אַתְּ אָסוּר בַּהֲנָיָתִי. אוֹ שֶׁנִּשְׁבַּע שֶׁלֹּא יֵהָנֶה בּוֹ. אִם מֵת יִירָשֶׁנּוּ. שֶׁזֶּה כְּאוֹמֵר נְכָסַי עָלֶיךָ אֲסוּרִין. אָסַר עָלָיו הֲנָיָתוֹ וּפֵרֵשׁ בֵּין בְּחַיַּי בֵּין בְּמוֹתִי אִם מֵת לֹא יִירָשֶׁנּוּ. שֶׁזֶּה כְּמִי שֶׁאָמַר לוֹ נְכָסִים אֵלּוּ אֲסוּרִין עָלֶיךָ:","אָסַר בְּנוֹ בַּהֲנָיָתוֹ וְאָמַר אִם יִהְיֶה בֶּן בְּנִי זֶה תַּלְמִיד חָכָם יִקְנֶה בְּנִי זֶה נְכָסַי כְּדֵי לְהַקְנוֹתָן לִבְנוֹ הֲרֵי זֶה מֻתָּר. וְיִהְיֶה הַבֵּן אָסוּר בְּנִכְסֵי הָאָב וּבֶן הַבֵּן מֻתָּר בָּהֶן אִם יִהְיֶה תַּלְמִיד חָכָם כְּמוֹ שֶׁהִתְנָה:","זֶה הַבֵּן הָאָסוּר בִּירֻשַּׁת אָבִיו אִם נָתַן יְרֻשַּׁת אָבִיו לְאֶחָיו אוֹ לְבָנָיו הֲרֵי זֶה מֻתָּר. וְכֵן אִם פְּרָעָם בְּחוֹבוֹ אוֹ בִּכְתֻבַּת אִשְׁתּוֹ. וְצָרִיךְ לְהוֹדִיעָן שֶׁאֵלּוּ נִכְסֵי אָבִי שֶׁאֲסָרָן עָלַי. שֶׁהַנִּשְׁבָּע שֶׁלֹּא יֵהָנֶה בּוֹ חֲבֵרוֹ מֻתָּר לוֹ לִפְרֹעַ אֶת חוֹבוֹ כְּמוֹ שֶׁיִּתְבָּאֵר:","מִי שֶׁנֶּאֱסַר עָלָיו מִין מִמִּינֵי מַאֲכָל בֵּין בְּנֵדֶר בֵּין בִּשְׁבוּעָה וְנִתְבַּשֵּׁל עִם מִינִים אֲחֵרִים אוֹ נִתְעָרֵב עִמָּהֶן הֲרֵי זֶה מֻתָּר בַּמִּינִים הַמֻּתָּרִים אַף עַל פִּי שֶׁיֵּשׁ בָּהֶן טַעַם הַמִּין הָאָסוּר. וְאִם נֶאֱסַר בְּפֵרוֹת אֵלּוּ וְנִתְעָרְבוּ בַּאֲחֵרִים אִם יֵשׁ בָּהֶן טַעַם דָּבָר הָאָסוּר אֲסוּרִין וְאִם לָאו מֻתָּרִין:","כֵּיצַד. נֶאֱסַר בְּבָשָׂר אוֹ בְּיַיִן הֲרֵי זֶה מֻתָּר לֶאֱכל מָרָק וִירָקוֹת שֶׁנִּתְבַּשְּׁלוּ עִם הַבָּשָׂר וְעִם הַיַּיִן אַף עַל פִּי שֶׁיֵּשׁ בָּהֶן טַעַם הַבָּשָׂר אוֹ טַעַם הַיַּיִן. וְאֵינוֹ אָסוּר אֶלָּא בַּאֲכִילַת בָּשָׂר בִּפְנֵי עַצְמוֹ אוֹ לִשְׁתּוֹת יַיִן בִּפְנֵי עַצְמוֹ:","נֶאֱסַר בְּבָשָׂר זֶה אוֹ בְּיַיִן זֶה וְנִתְבַּשֵּׁל עִם הַיָּרָק. אִם יֵשׁ בַּיְרָקוֹת טַעַם בָּשָׂר אוֹ טַעַם הַיַּיִן אֲסוּרִין וְאִם לָאו מֻתָּרִין. שֶׁזֶּה הַבָּשָׂר וְזֶה הַיַּיִן נַעֲשָׂה כְּמוֹ בְּשַׂר נְבֵלוֹת וּשְׁקָצִים וְכַיּוֹצֵא בָּהֶן. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. לְפִיכָךְ הָאוֹמֵר בָּשָׂר זֶה אָסוּר עָלַי הֲרֵי זֶה אָסוּר בּוֹ וּבַמָּרָק שֶׁבּוֹ וּבַתַּבְלִין שֶׁבּוֹ:","נִתְעָרֵב יַיִן זֶה שֶׁאֲסָרוֹ עַל עַצְמוֹ בְּיַיִן אַחֵר אֲפִלּוּ טִפָּה בְּחָבִית נֶאֱסַר הַכּל. מִפְּנֵי שֶׁיֵּשׁ לוֹ לְהִשָּׁאֵל עַל נִדְרוֹ נַעֲשָׂה כְּדָבָר שֶׁיֵּשׁ לוֹ מַתִּירִין שֶׁאֵינוֹ בָּטֵל בְּמִינוֹ כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת מַאֲכָלוֹת אֲסוּרוֹת:","הָאוֹמֵר פֵּרוֹת הָאֵלּוּ קָרְבָּן עָלַי אוֹ קָרְבָּן הֵן לְפִי. אוֹ קָרְבָּן הֵן עַל פִּי. הֲרֵי זֶה אָסוּר בְּחִלּוּפֵיהֶן וּבְגִדּוּלֵיהֶם. וְאֵין צָרִיךְ לוֹמַר בַּמַּשְׁקִין הַיּוֹצְאִין מֵהֶן:","נָדַר אוֹ נִשְׁבַּע שֶׁאֵינִי אוֹכֵל אוֹתָם אוֹ שֶׁאֵינִי טוֹעֵם אוֹתָם. אִם הָיָה דָּבָר שֶׁזַּרְעוֹ כָּלֶה כְּשֶׁיִּזָּרַע כְּגוֹן חִטָּה וּשְׂעוֹרָה הֲרֵי זֶה מֻתָּר בְּחִלּוּפֵיהֶן וּבְגִדּוּלֵיהֶן. וְאִם הָיָה הַדָּבָר שֶׁאֵין זַרְעוֹ כָּלֶה בָּאָרֶץ כְּשֶׁיִּזָּרַע כְּגוֹן בְּצָלִים וְשׁוּמִין אֲפִלּוּ גִּדּוּלֵי גִּדּוּלִין אֲסוּרִין. וּבֵין כָּךְ וּבֵין כָּךְ מַשְׁקִין הַיּוֹצְאִין מֵהֶן סָפֵק. לְפִיכָךְ אִם שָׁתָה מֵהֶן אֵינוֹ לוֹקֶה:","וְכֵן הָאוֹמֵר לְאִשְׁתּוֹ מַעֲשֵׂה יָדַיִךְ עָלַי קָרְבָּן אוֹ קָרְבָּן הֵן לְפִי אוֹ קָרְבָּן הֵן עַל פִּי. אָסוּר בְּחִלּוּפֵיהֶן וּבְגִדּוּלֵיהֶן. שֶׁאֵינִי טוֹעֵם שֶׁאֵינִי אוֹכֵל אִם הָיוּ פֵּרוֹת מַעֲשֵׂה יָדֶיהָ דָּבָר שֶׁזַּרְעוֹ כָּלֶה מֻתָּר בְּחִלּוּפֵיהֶן וּבְגִדּוּלֵיהֶן. וְאִם הָיָה דָּבָר שֶׁאֵין זַרְעוֹ כָּלֶה אֲפִלּוּ גִּדּוּלֵי גִּדּוּלִין אֲסוּרִין. וְלָמָּה לֹא יִבָּטֵל הָעִקָּר הָאָסוּר בַּגִּדּוּלִין שֶׁרַבּוּ עָלָיו. שֶׁהֲרֵי הֵן דָּבָר שֶׁיֵּשׁ לוֹ מַתִּירִין שֶׁאֵינוֹ בָּטֵל בְּרֹב כְּמוֹ שֶׁבֵּאַרְנוּ:","הָאוֹסֵר פֵּרוֹתָיו עַל חֲבֵרוֹ בֵּין בְּנֵדֶר בֵּין בִּשְׁבוּעָה הֲרֵי גִּדּוּלֵיהֶן וְחִלּוּפֵיהֶן סָפֵק. לְפִיכָךְ חֲבֵרוֹ אָסוּר בְּגִדּוּלֵי פֵּרוֹת אֵלּוּ וּבְחִלּוּפֵיהֶן. וְאִם עָבַר וְנֶהֱנָה נֶהֱנָה:"]} as Record<string, string[]>;
